@dataclass
class ExperimentDesign:
    """
    Pre-evidence classification of hypothesis claims.
    Generated by MetacognitiveReasoningEngine.design_critical_experiment()
    BEFORE gather_evidence() runs.

    critical_claims:
        If ANY of these are False in the evidence → immediate falsification
        (or score penalty if coverage guard is active).
        Popperian hard kill — no amount of supportive evidence overrides this.

    supportive_claims:
        If False → score penalty only. Does not falsify.

    unknown_claims:
        Not directly verifiable in the SymbolGraph.
        Ignored in scoring but counted in coverage_score.
        Active Learning (_resolve_unknown_claims) may reclassify some
        of these into supportive_claims if their symbols are found.

    hypothesis_hash:
        MD5 of hypothesis text. Used to cache this design across iterations
        when the hypothesis text hasn't changed substantially.
    """

    critical_claims: List[str]
    supportive_claims: List[str]
    unknown_claims: List[str]
    hypothesis_hash: str = ""


@dataclass
class ScoredHypothesis:
    """
    Complete evaluation result for one hypothesis in compete_hypotheses().

    coverage_score:
        Fraction of total claims that were structurally verifiable.
        coverage = (critical + supportive) / (critical + supportive + unknown).
        Low coverage means the obj_score is based on sparse evidence —
        a high score with low coverage is an availability bias artifact.

    epistemic_uncertainty:
        Bayesian-inspired uncertainty estimate combining coverage,
        prediction failures, and score ambiguity.
        0.0 = high confidence | 1.0 = high uncertainty.
        Used to gate peer review (only when uncertainty > threshold).

    falsified:
        True if is_falsified() triggered a hard kill.
        Note: with coverage guard enabled, falsification is suppressed
        when coverage_score < min_coverage_for_falsification and
        a penalty is applied instead.

    falsification_reason:
        Human-readable explanation from is_falsified().
        Also used for downgrade penalties (coverage guard case).
    """

    text: str
    score: float
    llm_conf: float
    obj_score: float
    evidence: "StaticEvidence"
    design: "ExperimentDesign"
    falsified: bool
    falsification_reason: Optional[str]
    scope: Optional[str] = None
    predictions_verified: int = 0
    predictions_total: int = 0
    coverage_score: float = 0.0
    epistemic_uncertainty: float = 0.0


@dataclass
class PeerReviewResult:
    """
    Result of MetacognitiveReasoningEngine.peer_review_hypothesis().

    verdict:
        APPROVE  — no significant structural flaws found
        REJECT   — critical contradiction found; runner-up promoted if available
        QUALIFY  — hypothesis holds with caveats; critiques added to synthesis

    is_external:
        True only when peer_review_model is set and differs from
        cot_model_level3. False for internal devil's advocate.
        Affects confidence language in the dialectical synthesis.
    """

    verdict: str  # "APPROVE" | "REJECT" | "QUALIFY"
    critiques: List[str]
    reviewer_model: str
    is_external: bool = False


@dataclass
class CompetitionRecord:
    """
    Post-competition record for metacognitive debriefing.
    PROJECT LEVEL (H5 temporal hierarchy).

    Stored per project_id in MetacognitiveReasoningEngine._performance_history.
    Used by _get_adaptive_strategy() to adapt future competitions.

    All fields are derived from deterministic SymbolGraph data —
    no LLM self-evaluation. The graph evaluates the LLM, not the reverse.

    score_trajectory:
        obj_score per iteration (NOT combined score — llm_conf excluded
        because it is self-reported by the LLM and unreliable as a
        convergence signal).
    """

    timestamp: float
    n_hypotheses_initial: int
    n_falsified: int
    primary_falsification_type: str  # "call_relations" | "symbols" | "none"
    final_score: float
    coverage_score: float
    iterations_used: int
    stagnated: bool
    score_trajectory: List[float]  # obj_score per iteration only
    call_relation_failures: int
    symbol_failures: int
    low_coverage_count: int


class UseCase(str, Enum):
    """
    Use case categories for intent classification.

    Each member has a short internal key (value) and a human-readable label.
    The internal key is used for LOD profiles and logic; the label is used
    for logging and prompts.
    """

    ARCHITECTURE = "A"
    PLANNING = "B"
    PROGRAMMING = "C"
    REFACTORING = "D"
    SCAFFOLDING = "E"

    @property
    def label(self) -> str:
        """Human-readable label for the use case."""
        return {
            "A": "Architecture/Design",
            "B": "Planning/Roadmap",
            "C": "General Programming",
            "D": "Refactoring/Impact Analysis",
            "E": "Scaffolding/Boilerplate",
        }[self.value]


def qualify_symbol_name(
    name: str, parent_symbol: str, file_path: Optional[str] = None
) -> str:
    """
    Unique-within-project identity for a symbol.

    - Class-scoped symbols: 'ClassName.method'
    - Module-level functions: 'module.function' (derived from file_path)
    - Fallback: bare name when neither parent nor file_path is available

    This is the central fix for the docstring / call-graph collision bug:
    same-named methods in different classes, and same-named functions in
    different files, are now stored under distinct qualified ids so they
    never stomp on or fuse with each other.
    """
    if parent_symbol:
        return f"{parent_symbol}.{name}"
    if file_path:
        module = os.path.splitext(os.path.basename(file_path))[0]
        if module and module != name:
            return f"{module}.{name}"
    return name


def qualify_symbol(sym: "CodeSymbol") -> str:
    """
    Convenience wrapper: qualify a CodeSymbol using ALL the identity
    fields the indexing side already uses (name, parent_symbol, file_path).
    Prefer this over calling qualify_symbol_name(sym.name, sym.parent_symbol)
    directly — the two-arg form silently drops file_path, which only matters
    for module-level functions with a detected file path, but is exactly the
    inconsistency that caused them to go unmatched in several lookups.
    """
    return qualify_symbol_name(sym.name, sym.parent_symbol, sym.file_path)


def _get_cross_encoder(
    model_name: str = "Qwen/Qwen3-Reranker-0.6B",
) -> Optional[Any]:
    """Return the CrossEncoder singleton, loading it once. Thread‑safe."""
    global _CROSS_ENCODER
    if _CROSS_ENCODER is None:
        with _CROSS_ENCODER_LOCK:
            if _CROSS_ENCODER is None:
                try:
                    from sentence_transformers import CrossEncoder

                    _CROSS_ENCODER = CrossEncoder(model_name)
                except Exception:
                    return None
    return _CROSS_ENCODER


class ContentType(str, Enum):
    """Classification of a code block's role in the conversation."""

    BASE_CODE = "base_code"  # Existing code provided by the user
    PROPOSED_CHANGE = "proposed_change"  # Suggested modification (diff or snippet)
    COMMITTED_CHANGE = "committed_change"  # Accepted / applied change
    GENERAL = "general"  # Plain conversation text
    TOOL_CALL = "tool_call"  # Structured tool / function call payload
    ERROR = "error"  # Traceback or error message


class CodeSymbol(BaseModel):
    """A single function, method, or class extracted from source code."""

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Symbol identity
    # ═══════════════════════════════════════════════════════════════════════════

    name: str
    kind: str  # "function", "class", or "method"
    signature: str

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Location in source
    # ═══════════════════════════════════════════════════════════════════════════

    file_path: Optional[str] = None
    line_start: Optional[int] = None
    line_end: Optional[int] = None

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Relationships & context
    # ═══════════════════════════════════════════════════════════════════════════

    parent_block_hash: str = ""  # Hash of the CodeBlock that owns this symbol
    parent_symbol: str = ""  # Enclosing class name, or "" for top-level
    language: str = "unknown"

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Additional metadata (calls, docstring)
    # ═══════════════════════════════════════════════════════════════════════════

    calls: List[str] = Field(default_factory=list)  # Bare names called by this symbol
    docstring: str = ""


class CodeBlock(BaseModel):
    """A chunk of code managed by the context system.

    Every code block carries a content hash for deduplication, an importance
    score that decays over time, and a list of ``CodeSymbol`` entries
    extracted from its content.  The importance score is recalculated
    whenever ``_update_importance()`` is called.
    """

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Core content & identity
    # ═══════════════════════════════════════════════════════════════════════════

    content: str
    content_type: ContentType
    hash: str = ""

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Location & timing
    # ═══════════════════════════════════════════════════════════════════════════

    file_path: Optional[str] = None
    line_range: Optional[Tuple[int, int]] = None
    timestamp: float = Field(default_factory=time.time)

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. State flags
    # ═══════════════════════════════════════════════════════════════════════════

    is_active: bool = True
    generated_by_assistant: bool = False
    pinned: bool = False
    obsolete: bool = False
    is_raw: bool = False

    # REMOVED: potentially_affected: bool = False

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Importance & recency
    # ═══════════════════════════════════════════════════════════════════════════

    importance_score: float = 1.0
    mention_count: int = 1
    last_mentioned: float = Field(default_factory=time.time)
    last_mentioned_msg_idx: Optional[int] = None

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Extracted symbols & summary
    # ═══════════════════════════════════════════════════════════════════════════

    block_summary: str = ""
    symbols: List[CodeSymbol] = Field(default_factory=list)
    _cached_token_count: int = 0

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Methods
    # ═══════════════════════════════════════════════════════════════════════════

    def __init__(self, **data):
        super().__init__(**data)
        if not self.hash:
            self.hash = hashlib.md5(self.content.encode()).hexdigest()[:16]
        self._update_importance()

    def _update_importance(self):
        """Recalculate the importance score from content type, keywords,
        mention frequency, recency, and obsolete status."""
        base_score = {
            ContentType.BASE_CODE: 8.0,
            ContentType.ERROR: 7.0,
            ContentType.COMMITTED_CHANGE: 6.0,
            ContentType.PROPOSED_CHANGE: 5.0,
            ContentType.TOOL_CALL: 3.0,
            ContentType.GENERAL: 2.0,
        }.get(self.content_type, 2.0)
        keyword_boost = (
            2.0
            if re.search(
                r"\b(fix|bug|security|critical|important|todo)\b", self.content, re.I
            )
            else 0.0
        )
        if self.generated_by_assistant:
            base_score *= 0.8
        mention_boost = min(self.mention_count / 5, 3.0)
        recency_factor = 0.5 ** ((time.time() - self.last_mentioned) / 3600)
        penalty = 1.0
        if self.obsolete:
            penalty = 0.1
            self.is_active = False
        self.importance_score = (
            (base_score + keyword_boost) * mention_boost * recency_factor * penalty
        )


class Edge(BaseModel):
    """A directed relationship between two symbols in the call graph.

    The source (``src``) is always a qualified symbol id
    (``ClassName.method`` or ``module.function``).  The destination
    (``dst``) is a bare name — resolving it to a concrete class would
    require type inference, which is outside the scope of a static pass.
    Downstream components handle this by fanning out to every qualified
    symbol that shares the bare callee name.
    """

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Source & destination (identity)
    # ═══════════════════════════════════════════════════════════════════════════

    src: str
    dst: str

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Edge type & weight
    # ═══════════════════════════════════════════════════════════════════════════

    type: str
    weight: float = 1.0  # Base importance of this edge type
    confidence: float = 1.0  # 1.0 = confirmed, < 1.0 = inferred / provisional

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Methods
    # ═══════════════════════════════════════════════════════════════════════════

    def effective_weight(self) -> float:
        """Effective weight used in activation propagation (PPR)."""
        return self.weight * self.confidence


# ---------------------------------------------------------------------------
# Activation Graph — query‑conditioned node activation
# ---------------------------------------------------------------------------
class ActivationState(BaseModel):
    """Snapshot of a single node's activation during PPR propagation."""

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Node identity
    # ═══════════════════════════════════════════════════════════════════════════

    node_id: str

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Activation score
    # ═══════════════════════════════════════════════════════════════════════════

    score: float

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Propagation metadata
    # ═══════════════════════════════════════════════════════════════════════════

    depth: int
    source: str


class SymbolIndex:
    """Central index that stores every known symbol under a **qualified id**
    (``ClassName.method`` or ``module.function``) so that methods with the
    same bare name in different classes never collide.

    Provides:
    * Block‑hash lookup by qualified id, with bare‑name fallback that
      returns **all** matching symbols (inclusive, not last‑writer‑wins).
    * Typed call edges (``calls``, ``data_flow``, …) between symbols.
    * Per‑symbol metadata: signature, docstring, kind, file path, line span.
    * PageRank centrality over the qualified call graph.

    Use ``get_all_names()`` for coarse text matching, ``get_all_qualified_names()``
    when every distinct symbol must be visible (inventories, hashes, centrality).
    """

    MAX_ENTRIES = 10_000

    def __init__(self) -> None:
        # Primary storage, indexed by (project_id, qualified_id).
        self._name_to_blocks: Dict[Tuple[str, str], Set[str]] = defaultdict(set)
        self._stats: Counter = Counter()
        self._symbol_meta: Dict[Tuple[str, str], Dict[str, Any]] = {}
        # Reverse index: (project_id, bare_name) -> {qualified_id, ...}.
        # Lets every bare‑name‑based consumer (query‑word matching,
        # /expand <bare>, traceback frame names, ...) resolve to the full
        # set of real symbols that share that name, instead of silently
        # picking whichever was indexed last.
        self._bare_index: Dict[Tuple[str, str], Set[str]] = defaultdict(set)

        # Legacy call relationships, kept for compatibility with
        # find_entry_points() and any external consumer of get_callers().
        # Destinations remain bare (the callee's identity is generally not
        # resolvable without type inference); values are now caller qualified
        # ids instead of caller bare names.
        self._callee_to_callers: Dict[Tuple[str, str], Set[str]] = defaultdict(set)

        # Typed edges (v7+).  Sources are qualified ids (we always know
        # which symbol we are walking); destinations stay bare, best-effort
        # (see class docstring + qualify_symbol_name()).
        self._edges_out: Dict[str, List[Edge]] = defaultdict(list)
        self._edges_in: Dict[str, List[Edge]] = defaultdict(list)

        # Centrality cache (v8), now keyed by qualified id.
        self._centrality_cache: Dict[str, Dict[str, float]] = {}

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Symbol registration & removal (qualified id + bare index)
    # ═══════════════════════════════════════════════════════════════════════════

    def add(self, symbol: "CodeSymbol", block_hash: str, project_id: str) -> None:
        """Register *symbol* in the index, keyed by its qualified id.
        Updates the bare‑name reverse index and call‑relationship storage."""
        qid = qualify_symbol_name(symbol.name, symbol.parent_symbol, symbol.file_path)
        key = (project_id, qid)
        self._name_to_blocks[key].add(block_hash)
        self._stats[key] += 1
        self._bare_index[(project_id, symbol.name)].add(qid)

        prev = self._symbol_meta.get(key)
        self._symbol_meta[key] = {
            "name": symbol.name,
            "signature": symbol.signature,
            "docstring": symbol.docstring
            or (prev.get("docstring", "") if prev else ""),
            "file_path": symbol.file_path,
            "language": symbol.language,
            "kind": symbol.kind,
            "parent_symbol": symbol.parent_symbol
            or (prev.get("parent_symbol", "") if prev else ""),
            "line_start": symbol.line_start,
            "cfg_skeleton": "",  # Lazy CFG skeleton (populated by ensure_cfg_batch)
            "cfg_body_hash": "",  # Hash of the source body that generated cfg_skeleton
        }

        for callee in symbol.calls:
            callee_key = (project_id, callee)
            self._callee_to_callers[callee_key].add(qid)
        self._evict_if_needed()

    def remove(self, symbol: "CodeSymbol", block_hash: str, project_id: str) -> None:
        """Remove *symbol* from the index.  If the block hash was the last
        reference to that qualified id, the entry is fully deleted from all
        internal structures."""
        qid = qualify_symbol_name(symbol.name, symbol.parent_symbol, symbol.file_path)
        key = (project_id, qid)
        s = self._name_to_blocks.get(key)
        if s:
            s.discard(block_hash)
            if not s:
                del self._name_to_blocks[key]
                self._stats.pop(key, None)
                self._symbol_meta.pop(key, None)
                bare_key = (project_id, symbol.name)
                bare_set = self._bare_index.get(bare_key)
                if bare_set:
                    bare_set.discard(qid)
                    if not bare_set:
                        del self._bare_index[bare_key]

    def remove_all_for_block(
        self, block_hash: str, symbols: List["CodeSymbol"], project_id: str
    ) -> None:
        """Remove every symbol belonging to *block_hash* and their edges."""
        for sym in symbols:
            self.remove(sym, block_hash, project_id)
            qid = qualify_symbol_name(sym.name, sym.parent_symbol, sym.file_path)
            self.remove_edges_for_symbol(qid, project_id)

    def _evict_if_needed(self) -> None:
        """
        Drop the least‑frequently‑added entry when the index exceeds
        ``MAX_ENTRIES``, keeping memory bounded.
        """
        while len(self._name_to_blocks) > self.MAX_ENTRIES:
            # Get the least common entry (by add count)
            least_common = self._stats.most_common()[-1][0]
            project_id, qid = least_common

            # --- 1. Remove all edges (in/out) that reference this symbol ---
            self.remove_edges_for_symbol(qid, project_id)

            # --- 2. Remove the symbol entry itself ---
            meta = self._symbol_meta.get(least_common, {})
            bare = meta.get("name", qid)
            bare_key = (project_id, bare)
            bare_set = self._bare_index.get(bare_key)
            if bare_set:
                bare_set.discard(qid)
                if not bare_set:
                    del self._bare_index[bare_key]

            del self._name_to_blocks[least_common]
            self._stats.pop(least_common, None)
            self._symbol_meta.pop(least_common, None)

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Name & symbol resolution (qualified, bare, and cross-reference)
    # ═══════════════════════════════════════════════════════════════════════════

    def find_blocks(self, name_or_qid: str, project_id: str) -> Set[str]:
        """Block hashes for a symbol.  Exact qualified-id match first; if
        not found, falls back to a bare‑name lookup that UNIONS all blocks
        of every symbol sharing that bare name (e.g. every __init__ of every
        class), instead of returning just one."""
        exact = self._name_to_blocks.get((project_id, name_or_qid))
        if exact is not None:
            return exact
        qids = self._bare_index.get((project_id, name_or_qid))
        if not qids:
            return set()
        result: Set[str] = set()
        for qid in qids:
            result |= self._name_to_blocks.get((project_id, qid), set())
        return result

    def get_all_names(self, project_id: str) -> Set[str]:
        """Bare names indexed in this project (deduplicated).  Use for
        coarse text/query matching, where the caller doesn't know — and
        doesn't need to know — which concrete class a name belongs to."""
        return {bare for (pid, bare) in self._bare_index if pid == project_id}

    def get_all_qualified_names(self, project_id: str) -> Set[str]:
        """Every distinct symbol identity in the project (one entry per real
        occurrence, e.g. each class's __init__ separately).  Use instead of
        get_all_names() where every real symbol must be visible —
        inventories, skeleton hash, centrality."""
        return {qid for (pid, qid) in self._symbol_meta if pid == project_id}

    def get_qualified_names_for(self, bare_name: str, project_id: str) -> Set[str]:
        """All qualified ids that share this bare name (e.g. every class's
        __init__).  If nothing is indexed under that bare name, returns
        {bare_name} as-is — defensive, and also makes passing an ALREADY-
        qualified id through here (not found as bare) a correct no-op,
        returning it unchanged."""
        qids = self._bare_index.get((project_id, bare_name))
        return set(qids) if qids else {bare_name}

    def get_symbol_meta(
        self, name_or_qid: str, project_id: str
    ) -> Optional[Dict[str, Any]]:
        """Full metadata dict for a symbol (signature, docstring, kind, …),
        or ``None`` if not found."""
        return self._resolve_meta(name_or_qid, project_id)

    def get_parent_symbol(self, name_or_qid: str, project_id: str) -> str:
        """Enclosing class name for a symbol, or ``""`` if it is top-level
        or the symbol is not found."""
        meta = self._resolve_meta(name_or_qid, project_id)
        return meta.get("parent_symbol", "") if meta else ""

    def get_class_members(self, class_name: str, project_id: str) -> List[str]:
        """Qualified ids of every member of `class_name`, ordered by
        source order (line_start) then by id.  Unlike before, this now
        returns ALL members correctly even when other classes in the project
        have methods sharing the same bare names."""
        members = []
        for (pid, qid), meta in self._symbol_meta.items():
            if pid == project_id and meta.get("parent_symbol") == class_name:
                members.append(qid)

        def _line_start(qid: str) -> int:
            meta = self._symbol_meta.get((project_id, qid), {})
            val = meta.get("line_start")
            return val if val is not None else 999999

        return sorted(members, key=lambda q: (_line_start(q), q))

    def get_classes(self, project_id: str) -> Set[str]:
        """Return every class name that has at least one indexed member,
        plus every symbol whose kind is ``"class"``."""
        classes = set()
        for (pid, qid), meta in self._symbol_meta.items():
            if pid != project_id:
                continue
            if meta.get("kind") == "class":
                classes.add(meta.get("name", qid))
            parent = meta.get("parent_symbol")
            if parent:
                classes.add(parent)
        return classes

    def get_signature(self, name_or_qid: str, project_id: str) -> Optional[str]:
        """Signature string for a symbol, or ``None``."""
        meta = self._resolve_meta(name_or_qid, project_id)
        return meta.get("signature") if meta else None

    def get_docstring(self, name_or_qid: str, project_id: str) -> str:
        """One-line docstring for a symbol, or ``""``."""
        meta = self._resolve_meta(name_or_qid, project_id)
        return meta.get("docstring", "") if meta else ""

    def update_cfg(
        self, qid: str, project_id: str, cfg_skeleton: str, body_hash: str
    ) -> None:
        """
        Store a symbol's control-flow skeleton and the body_hash it was derived
        from. Unlike update_docstring, this ONLY updates an exact qualified-id
        match — never a bare-name fallback. A CFG skeleton is specific to one
        concrete function body; applying it to "every symbol sharing this bare
        name" (as update_docstring does for resilience) would silently show the
        wrong control flow for a same-named method in a different class.
        """
        key = (project_id, qid)
        if key in self._symbol_meta:
            self._symbol_meta[key]["cfg_skeleton"] = cfg_skeleton
            self._symbol_meta[key]["cfg_body_hash"] = body_hash

    def get_cfg(self, qid: str, project_id: str) -> Optional[str]:
        """Return the cached CFG skeleton for an exact qualified id, or None.
        No bare-name fallback — see update_cfg()."""
        meta = self._symbol_meta.get((project_id, qid))
        if meta:
            return meta.get("cfg_skeleton")
        return None

    def get_file_for_symbol(self, name_or_qid: str, project_id: str) -> Optional[str]:
        """File path for a symbol, or ``None``."""
        meta = self._resolve_meta(name_or_qid, project_id)
        return meta.get("file_path") if meta else None

    def update_docstring(
        self, name_or_qid: str, project_id: str, docstring: str
    ) -> None:
        """Update a symbol's docstring.  An exact qid match updates only that
        one occurrence — every new call site (background docstring
        generation, batch generation) now passes a qualified id and gets
        this precise behaviour.  A bare‑name call (legacy compatibility)
        updates every symbol sharing that name, which is safer than the old
        silent-overwrite-of-one but is still an approximation — prefer
        passing the qualified id when you have it."""
        key = (project_id, name_or_qid)
        if key in self._symbol_meta:
            self._symbol_meta[key]["docstring"] = docstring
            return
        qids = self._bare_index.get((project_id, name_or_qid))
        if qids:
            for qid in qids:
                meta = self._symbol_meta.get((project_id, qid))
                if meta is not None:
                    meta["docstring"] = docstring

    def _resolve_meta(
        self, name_or_qid: str, project_id: str
    ) -> Optional[Dict[str, Any]]:
        """Exact qualified-id match first; if missing, a deterministic
        choice among all symbols sharing that bare name.  Anyone who already
        knows the qualified id (e.g. anything iterating
        get_all_qualified_names(), or holding a CodeSymbol with its own
        parent_symbol) should pass the qid directly for an unambiguous
        answer.  Anyone with only a bare name (regex matches,
        /expand <bare> typed by the user, ...) gets a single representative
        entry — better than nothing, but inherently ambiguous when several
        classes share that method name."""
        key = (project_id, name_or_qid)
        meta = self._symbol_meta.get(key)
        if meta is not None:
            return meta
        qids = self._bare_index.get((project_id, name_or_qid))
        if not qids:
            return None
        chosen = sorted(qids)[0]
        return self._symbol_meta.get((project_id, chosen))

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Call relationships (legacy)
    # ═══════════════════════════════════════════════════════════════════════════

    def get_callers(self, callee_name: str, project_id: str) -> Set[str]:
        """Qualified caller ids for a callee name (necessarily bare)."""
        return self._callee_to_callers.get((project_id, callee_name), set())

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Typed edges (v7+)
    # ═══════════════════════════════════════════════════════════════════════════

    def add_edge(self, edge: "Edge", project_id: str) -> None:
        """Register a typed edge.  `edge.src` is expected to be the
        qualified id of the symbol whose body contains the call (the caller
        must qualify it themselves with qualify_symbol_name() before
        building the Edge — SymbolIndex has no way to know a symbol's
        parent_symbol from a bare string alone).  `edge.dst` stays whatever
        the extractor produced (best-effort, normally bare)."""
        src_key = f"{project_id}:{edge.src}"
        dst_key = f"{project_id}:{edge.dst}"
        existing = self._edges_out.get(src_key, [])
        for e in existing:
            if e.dst == edge.dst and e.type == edge.type:
                return
        self._edges_out[src_key].append(edge)
        self._edges_in[dst_key].append(edge)

    def remove_edges_for_symbol(self, symbol_id: str, project_id: str) -> None:
        """Remove edges where `symbol_id` (qualified id for a class‑scoped
        symbol, bare name for a module‑level one) is source or destination."""
        src_key = f"{project_id}:{symbol_id}"
        for edge in self._edges_out.pop(src_key, []):
            dst_key = f"{project_id}:{edge.dst}"
            self._edges_in[dst_key] = [
                e for e in self._edges_in.get(dst_key, []) if e.src != symbol_id
            ]
        dst_key = f"{project_id}:{symbol_id}"
        for edge in self._edges_in.pop(dst_key, []):
            src_key_in = f"{project_id}:{edge.src}"
            self._edges_out[src_key_in] = [
                e for e in self._edges_out.get(src_key_in, []) if e.dst != symbol_id
            ]

    def get_edges_out(self, symbol_id: str, project_id: str) -> List["Edge"]:
        """Outgoing edges.  Pass a method's qualified id for precisely its
        own calls; a module‑level function's bare name works as-is."""
        return self._edges_out.get(f"{project_id}:{symbol_id}", [])

    def get_edges_in(self, callee_name: str, project_id: str) -> List["Edge"]:
        """Incoming edges for a callee name (necessarily bare, best-effort).
        May include callers from an unrelated symbol that shares that bare
        name — there is no general way to know which class's method a call
        `obj.method()` actually resolves to without type inference; this is
        the inherent and documented limitation."""
        return self._edges_in.get(f"{project_id}:{callee_name}", [])

    def get_all_edges_out(self, project_id: str) -> Dict[str, List["Edge"]]:
        prefix = f"{project_id}:"
        return {
            key[len(prefix) :]: edges
            for key, edges in self._edges_out.items()
            if key.startswith(prefix)
        }

    def get_all_edges_in(self, project_id: str) -> Dict[str, List["Edge"]]:
        prefix = f"{project_id}:"
        inverted: Dict[str, List["Edge"]] = defaultdict(list)
        for key, edges in self._edges_out.items():
            if not key.startswith(prefix):
                continue
            for e in edges:
                inverted[e.dst].append(
                    Edge(
                        src=e.dst,
                        dst=e.src,
                        type=e.type,
                        weight=e.weight,
                        confidence=e.confidence,
                    )
                )
        return dict(inverted)

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Centrality (PageRank)
    # ═══════════════════════════════════════════════════════════════════════════

    def precompute_centrality(
        self,
        project_id: str,
        alpha: float = 0.85,
        max_steps: int = 30,
        tolerance: float = 1e-7,
    ) -> Dict[str, float]:
        """PageRank over QUALIFIED symbol identities, so e.g. fifteen
        __init__ with the same name are fifteen separate nodes instead of
        one node whose edges were silently fused.

        Each edge's destination (best-effort, normally bare) is resolved
        against every qualified node sharing that bare name — if a name is
        ambiguous (multiple classes with a method of that same name), the
        contribution is split among all candidates instead of being silently
        lost."""
        names = list(self.get_all_qualified_names(project_id))
        n = len(names)
        if n == 0:
            return {}
        if n == 1:
            scores = {names[0]: 1.0}
            self._store_centrality(project_id, scores)
            return scores

        idx = {name: i for i, name in enumerate(names)}

        bare_to_indices: Dict[str, List[int]] = {}
        for (pid, bare), qids in self._bare_index.items():
            if pid != project_id:
                continue
            indices = [idx[q] for q in qids if q in idx]
            if indices:
                bare_to_indices[bare] = indices

        out_links: list = [[] for _ in range(n)]
        for name in names:
            i = idx[name]
            for edge in self._edges_out.get(f"{project_id}:{name}", []):
                if edge.dst in idx:
                    out_links[i].append(idx[edge.dst])
                else:
                    for j in bare_to_indices.get(edge.dst, []):
                        out_links[i].append(j)

        rank = [1.0 / n] * n
        base = (1.0 - alpha) / n
        dangling_nodes = [i for i in range(n) if not out_links[i]]

        for _ in range(max_steps):
            new_rank = [base] * n
            dangling_sum = sum(rank[i] for i in dangling_nodes)
            if dangling_sum:
                share = alpha * dangling_sum / n
                for k in range(n):
                    new_rank[k] += share
            for i in range(n):
                links = out_links[i]
                if not links:
                    continue
                contrib = alpha * rank[i] / len(links)
                for j in links:
                    new_rank[j] += contrib
            delta = sum(abs(new_rank[k] - rank[k]) for k in range(n))
            rank = new_rank
            if delta < tolerance:
                break

        max_r = max(rank) if rank else 1.0
        if max_r <= 0:
            scores = {name: 0.0 for name in names}
        else:
            scores = {names[k]: rank[k] / max_r for k in range(n)}

        self._store_centrality(project_id, scores)
        return scores

    def get_hub_symbols(
        self, project_id: str, centrality: Dict[str, float], top_n: int
    ) -> List[Tuple[str, float]]:
        """Top‑N symbols by centrality, sorted by descending score.
        Falls back to the cached scores from the last
        ``precompute_centrality()`` call if *centrality* is empty."""
        if not centrality:
            centrality = getattr(self, "_centrality_cache", {}).get(project_id, {})
        if not centrality or top_n <= 0:
            return []
        ranked = sorted(centrality.items(), key=lambda kv: (-kv[1], kv[0]))
        return ranked[:top_n]

    def _store_centrality(self, project_id: str, scores: Dict[str, float]) -> None:
        """Cache centrality scores for cheap re-reads by ``get_hub_symbols()``."""
        self._centrality_cache[project_id] = scores

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Skeleton & signature hashes
    # ═══════════════════════════════════════════════════════════════════════════

    def compute_signature_hash(self, project_id: str) -> str:
        """Stable hash of all symbol signatures (not bodies).  Changes only
        when symbols are added/removed/renamed or a signature changes."""
        qids = sorted(self.get_all_qualified_names(project_id))
        if not qids:
            return ""
        parts = []
        for qid in qids:
            meta = self._symbol_meta.get((project_id, qid), {})
            name = meta.get("name", qid)
            sig = meta.get("signature") or name
            parent = meta.get("parent_symbol", "")
            parts.append(f"{parent}\x1f{name}\x1f{sig}")
        blob = "\x1e".join(parts)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()[:16]

    def compute_skeleton_hash(self, project_id: str) -> str:
        """Stable hash of the skeleton tier (signatures + docstrings)."""
        qids = sorted(self.get_all_qualified_names(project_id))
        if not qids:
            return ""
        parts = []
        for qid in qids:
            meta = self._symbol_meta.get((project_id, qid), {})
            name = meta.get("name", qid)
            sig = meta.get("signature") or name
            parent = meta.get("parent_symbol", "")
            doc = meta.get("docstring", "")
            parts.append(f"{parent}\x1f{name}\x1f{sig}\x1f{doc}")
        blob = "\x1e".join(parts)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()[:16]

    def compute_structure_hash(self, project_id: str) -> str:
        """
        Hash of symbol signatures and structure only, excluding docstrings.
        Used for KV‑cache and slot persistence stability.

        This hash changes only when the symbol set or signatures change,
        not when docstrings are added/updated. This keeps the Block A
        prefix hash stable across the docstring-fill-in period, preventing
        spurious KV-cache misses and slot-restore failures.

        Args:
            project_id (str): The project identifier.

        Returns:
            str: A 16-character hex hash, or empty string if no symbols exist.
        """
        qids = sorted(self.get_all_qualified_names(project_id))
        if not qids:
            return ""
        parts = []
        for qid in qids:
            meta = self._symbol_meta.get((project_id, qid), {})
            name = meta.get("name", qid)
            sig = meta.get("signature") or name
            parent = meta.get("parent_symbol", "")
            # Include only structure: parent, name, signature.
            # Docstrings are excluded deliberately.
            parts.append(f"{parent}\x1f{name}\x1f{sig}")
        blob = "\x1e".join(parts)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()[:16]

    # ═══════════════════════════════════════════════════════════════════════════
    # 7. Project lifecycle & cleanup
    # ═══════════════════════════════════════════════════════════════════════════

    def clear_project(self, project_id: str) -> None:
        """Remove every symbol, edge, and metadata entry for *project_id*."""
        keys_to_remove = [key for key in self._name_to_blocks if key[0] == project_id]
        for key in keys_to_remove:
            del self._name_to_blocks[key]
            self._stats.pop(key, None)

        bare_keys = [key for key in self._bare_index if key[0] == project_id]
        for key in bare_keys:
            del self._bare_index[key]

        inv_keys = [key for key in self._callee_to_callers if key[0] == project_id]
        for key in inv_keys:
            del self._callee_to_callers[key]

        prefix = f"{project_id}:"
        for k in list(self._edges_out.keys()):
            if k.startswith(prefix):
                del self._edges_out[k]
        for k in list(self._edges_in.keys()):
            if k.startswith(prefix):
                del self._edges_in[k]

        self._centrality_cache.pop(project_id, None)

        meta_keys = [key for key in self._symbol_meta if key[0] == project_id]
        for key in meta_keys:
            del self._symbol_meta[key]

    def clear(self) -> None:
        """Drop all in‑memory data for all projects."""
        self._name_to_blocks.clear()
        self._bare_index.clear()
        self._callee_to_callers.clear()
        self._stats.clear()
        self._edges_out.clear()
        self._edges_in.clear()
        self._centrality_cache.clear()
        self._symbol_meta.clear()

    # ── Internal helpers (iteration) ─────────────────────────────────────

    def _iter_names(self, project_id: str):
        return iter(self.get_all_qualified_names(project_id))

    def _iter_out_edges(self, project_id: str, name: str):
        key = f"{project_id}:{name}"
        for edge in self._edges_out.get(key, []):
            yield edge.dst

    def _symbol_line_start(self, name_or_qid: str, project_id: str) -> int:
        meta = self._resolve_meta(name_or_qid, project_id)
        if meta is None:
            return 999999
        val = meta.get("line_start")
        return val if val is not None else 999999


class ConversationState(BaseModel):
    """
    Persistent conversation state for a single project.
    """

    model_config = {"arbitrary_types_allowed": True}

    # -- Active code blocks --------------------------------------------------
    active_blocks: Dict[str, "CodeBlock"] = Field(default_factory=dict)
    recent_changes: List["CodeBlock"] = Field(default_factory=list)
    committed_changes: List["CodeBlock"] = Field(default_factory=list)

    # -- Conversation counters ----------------------------------------------
    message_count: int = 0
    last_cot_level: int = 0

    # -- Feedback and suggestions -------------------------------------------
    feedback_history: List["AppliedChangeFeedback"] = Field(default_factory=list)
    last_compression_timestamp: float = 0.0
    last_suggestion_timestamp: float = 0.0
    last_cleanup_suggestion_msg_idx: int = 0

    # -- Call graph state ---------------------------------------------------
    has_any_calls: bool = False

    # -- Conversation summaries ---------------------------------------------
    conversation_summaries: List[Dict[str, Any]] = Field(default_factory=list)
    summarized_turn_hwm: int = 0

    # -- History compression tracker ----------------------------------------
    history_blocked_age: Dict[str, int] = Field(default_factory=dict)

    # -- KV slot persistence ------------------------------------------------
    pending_slot_resave: bool = False

    # -- WindowManager instrumentation (persistent metrics) ------------------
    wm_fired: bool = False
    wm_msgs_evicted: int = 0
    wm_turns_evicted: int = 0
    wm_summary_ok: bool = False
    wm_emergency_cap: bool = False
    wm_batch_too_small: bool = False
    wm_no_slot: bool = False
    wm_degradation_guard: bool = False

    # -- tokens freed by window manager compression --------------------
    wm_tokens_freed: int = 0

    # -- Hub‑Bodies Tier tracker --------------------------------------------
    hub_tier_last_modified: Dict[str, int] = Field(default_factory=dict)
    hub_tier_body_hashes: Dict[str, str] = Field(default_factory=dict)
    hub_tier_query_heat: Dict[str, float] = Field(default_factory=dict)
    hub_tier_qids_persisted: List[str] = Field(default_factory=list)

    # -- Persistent compression stubs ---------------------------------------
    compressed_user_messages: Dict[str, str] = Field(default_factory=dict)

    def reset_wm_metrics(self) -> None:
        """Reset all WindowManager instrumentation flags at the start of each turn."""
        self.wm_fired = False
        self.wm_msgs_evicted = 0
        self.wm_turns_evicted = 0
        self.wm_summary_ok = False
        self.wm_emergency_cap = False
        self.wm_batch_too_small = False
        self.wm_no_slot = False
        self.wm_degradation_guard = False
        self.wm_tokens_freed = 0


class ConversationStateManager:
    """
    Centralized manager for persistent conversation state.

    Parallel to ProjectStateManager (volatile per-project state):
    ConversationStateManager handles PERSISTENT state across sessions,
    backed by SQLite through StateStore's write queue.

    Responsibilities:
      - LRU cache of ConversationState per project_id.
      - Load from DB (_load_from_db) with CodeBlock reconstruction and docstring restoration.
      - Async save (_save_to_db) with 2-second debounce.
      - SymbolIndex rebuild after cold load.
      - LRU eviction when max_cached_projects is exceeded.

    Delegated to StateStore:
      - SQLite write queue       → StateStore._db_enqueue()
      - DDL table creation       → StateStore.init_db()
      - Per-project locks        → StateStore.get_project_lock()
      - Edges/path views/docstrings/CFG persistence → StateStore
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the manager with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._f = filter_ref
        self._cache: OrderedDict[str, ConversationState] = OrderedDict()
        self._dirty: Set[str] = set()
        self._last_saved: Dict[str, float] = {}

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Public API
    # ═══════════════════════════════════════════════════════════════════════

    def get(self, project_id: str) -> ConversationState:
        """
        Return the ConversationState for the given project.

        Loads from DB if not cached; creates a fresh empty state if not in DB either.

        Replaces: StateStore.get_state(project_id)
        """
        if project_id in self._cache:
            self._cache.move_to_end(project_id)
            return self._cache[project_id]

        state = self._load_from_db(project_id)
        if state is None:
            state = ConversationState()

        self._cache[project_id] = state
        self._cache.move_to_end(project_id)
        self._evict_lru()

        if state.active_blocks:
            self._rebuild_symbol_index(state, project_id)

        return state

    def set(self, project_id: str, state: ConversationState) -> None:
        """
        Update the state in cache and mark it as dirty (pending save).

        Replaces: StateStore.set_state(project_id, state)

        Invariant: In existing code, set() is always preceded by get() for the
        same project_id in the same turn, so the project is already in cache.
        If future code adds a set() without a prior get(), call _evict_lru() here.
        """
        self._cache[project_id] = state
        self._cache.move_to_end(project_id)
        self.mark_dirty(project_id)

    def mark_dirty(self, project_id: str) -> None:
        """Mark the state for a project as modified (pending save)."""
        self._dirty.add(project_id)

    async def save_if_dirty(self, project_id: str) -> None:
        """
        Persist the state if dirty and at least 2 seconds have passed since last save.
        """
        if project_id not in self._dirty:
            return
        now = time.time()
        if now - self._last_saved.get(project_id, 0.0) < 2.0:
            return

        self._dirty.discard(project_id)

        state = self._cache.get(project_id)
        if state is None:
            return

        try:
            await self._save_to_db_async(project_id, state)
            self._last_saved[project_id] = now
        except Exception as e:
            import traceback

            self._f._log_debug(
                f"ConversationStateManager.save_if_dirty: failed for "
                f"'{project_id}': {e}\n{traceback.format_exc()}"
            )
            self._dirty.add(project_id)

    def clear_project(self, project_id: str) -> None:
        """Remove the cached state for a project (LRU eviction or project switch)."""
        self._cache.pop(project_id, None)
        self._dirty.discard(project_id)
        self._last_saved.pop(project_id, None)

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Load from SQLite
    # ═══════════════════════════════════════════════════════════════════════

    def _load_from_db(self, project_id: str) -> Optional[ConversationState]:
        """
        Load ConversationState from SQLite.

        FIX Bug 6: los code_contents se cargan en una sola query batch en lugar
        de una query por bloque (N+1). Con 50 bloques activos el original hacía
        51 queries síncronas bloqueando el event loop; ahora son siempre 2.

        FIX Regresión: hash_to_block_keys mapea cada hash a una LISTA de block
        keys. El dict original (hash → un key) sobreescribía el primer bloque
        cuando dos bloques compartían contenido idéntico, dejando uno sin
        contenido restaurado.
        """
        try:
            with _db_global_lock:
                cur = self._f._db_conn.execute(
                    "SELECT state_json FROM conversation_state WHERE project_id = ?",
                    (project_id,),
                )
                row = cur.fetchone()
        except Exception as e:
            self._f._log_debug(
                f"ConversationStateManager._load_from_db: DB read error "
                f"for '{project_id}': {e}"
            )
            return None

        if not row:
            return None

        try:
            data = json.loads(row[0])
        except Exception as e:
            self._f._log_debug(
                f"ConversationStateManager._load_from_db: invalid JSON: {e}"
            )
            return None

        # ── Validate active_blocks ─────────────────────────────────────────
        raw_active = data.get("active_blocks")
        if raw_active is None:
            self._f._log_debug(
                f"⚠️  CORRUPT STATE: 'active_blocks' missing for "
                f"'{project_id}'. Resetting. "
                f"If this persists, delete: {self._f.valves.state_db_path}"
            )
            raw_active = {}
        elif not isinstance(raw_active, dict):
            self._f._log_debug(
                f"⚠️  CORRUPT STATE: 'active_blocks' is "
                f"{type(raw_active).__name__} for '{project_id}'. Resetting."
            )
            raw_active = {}

        # ── FIX Bug 6: batch fetch de code_contents ─────────────────────────
        # Recopilar hash → lista de block_keys que lo referencian.
        # Un dict hash → un solo key sobreescribiría el primero cuando dos
        # bloques tienen contenido idéntico (mismo hash); ambos quedarían sin
        # contenido restaurado excepto el último que se procesara.
        hash_to_block_keys: Dict[str, List[str]] = {}
        for k, v in raw_active.items():
            content_field = v.get("content", "")
            if content_field.startswith("@@hash:"):
                content_hash = content_field[7:]
                hash_to_block_keys.setdefault(content_hash, []).append(k)

        content_lookup: Dict[str, str] = {}
        if hash_to_block_keys:
            try:
                placeholders = ",".join("?" * len(hash_to_block_keys))
                with _db_global_lock:
                    cur2 = self._f._db_conn.execute(
                        f"SELECT hash, content FROM code_contents "
                        f"WHERE hash IN ({placeholders})",
                        list(hash_to_block_keys.keys()),
                    )
                    rows2 = cur2.fetchall()
                content_lookup = {r[0]: r[1] for r in rows2}
            except Exception as e:
                self._f._log_debug(
                    f"ConversationStateManager._load_from_db: "
                    f"batch content fetch failed: {e}"
                )

        # Aplicar el resultado del batch a todos los block_keys que referencian
        # ese hash (puede ser más de uno si dos bloques tienen contenido idéntico).
        for content_hash, block_keys in hash_to_block_keys.items():
            resolved = content_lookup.get(
                content_hash,
                f"[Content not found for hash {content_hash}]",
            )
            for block_key in block_keys:
                raw_active[block_key]["content"] = resolved

        # ── Rebuild active_blocks ──────────────────────────────────────────
        active: Dict[str, CodeBlock] = {}
        for k, v in raw_active.items():
            try:
                v["content_type"] = (
                    ContentType(v["content_type"])
                    if "content_type" in v
                    else ContentType.GENERAL
                )
                blk = CodeBlock(**v)
                if blk.last_mentioned_msg_idx is None:
                    blk.last_mentioned_msg_idx = data.get("message_count", 0)
                active[k] = blk
            except Exception:
                self._f._log_debug(f"Skipping corrupted block {k} in state DB")

        # ── Rebuild recent and committed lists ─────────────────────────────
        recent: List[CodeBlock] = []
        for b in data.get("recent_changes", []):
            try:
                b["content_type"] = (
                    ContentType(b["content_type"])
                    if "content_type" in b
                    else ContentType.GENERAL
                )
                recent.append(CodeBlock(**b))
            except Exception:
                pass

        committed: List[CodeBlock] = []
        for b in data.get("committed_changes", []):
            try:
                b["content_type"] = (
                    ContentType(b["content_type"])
                    if "content_type" in b
                    else ContentType.GENERAL
                )
                committed.append(CodeBlock(**b))
            except Exception:
                pass

        feedback: List[AppliedChangeFeedback] = []
        for fb in data.get("feedback_history", []):
            try:
                feedback.append(AppliedChangeFeedback(**fb))
            except Exception:
                self._f._log_debug(f"Skipping corrupt feedback entry in '{project_id}'")

        # ── Recalculate token counts ───────────────────────────────────────
        for blk in list(active.values()) + recent + committed:
            if self._f.tokenizer:
                blk._cached_token_count = len(self._f.tokenizer.encode(blk.content))
            else:
                blk._cached_token_count = len(blk.content) // 4

        # ── Restore docstrings from symbol_docstrings table ───────────────
        try:
            with _db_global_lock:
                cur = self._f._db_conn.execute(
                    "SELECT symbol_name, docstring FROM symbol_docstrings "
                    "WHERE project_id = ?",
                    (project_id,),
                )
                rows = cur.fetchall()
            if rows:
                doc_map = {row[0]: row[1] for row in rows}
                for block in active.values():
                    if block.obsolete:
                        continue
                    for sym in block.symbols:
                        if sym.docstring:
                            continue
                        qid = qualify_symbol_name(
                            sym.name, sym.parent_symbol, sym.file_path
                        )
                        doc = doc_map.get(qid) or doc_map.get(sym.name)
                        if doc:
                            sym.docstring = doc
                            self._f._symbol_index.update_docstring(qid, project_id, doc)
        except Exception as e:
            self._f._log_debug(f"_load_from_db: docstring restore failed: {e}")

        # ── Build and return ConversationState ─────────────────────────────
        return ConversationState(
            active_blocks=active,
            recent_changes=recent,
            committed_changes=committed,
            feedback_history=feedback,
            message_count=data.get("message_count", 0),
            last_compression_timestamp=data.get("last_compression_timestamp", 0.0),
            last_suggestion_timestamp=data.get("last_suggestion_timestamp", 0.0),
            has_any_calls=data.get("has_any_calls", False),
            last_cleanup_suggestion_msg_idx=data.get(
                "last_cleanup_suggestion_msg_idx", 0
            ),
            last_cot_level=data.get("last_cot_level", 0),
            conversation_summaries=data.get("conversation_summaries", []),
            summarized_turn_hwm=data.get("summarized_turn_hwm", 0),
            history_blocked_age=data.get("history_blocked_age", {}),
            wm_fired=data.get("wm_fired", data.get("_wm_fired", False)),
            wm_msgs_evicted=data.get(
                "wm_msgs_evicted", data.get("_wm_msgs_evicted", 0)
            ),
            wm_turns_evicted=data.get(
                "wm_turns_evicted", data.get("_wm_turns_evicted", 0)
            ),
            wm_summary_ok=data.get("wm_summary_ok", data.get("_wm_summary_ok", False)),
            wm_emergency_cap=data.get(
                "wm_emergency_cap", data.get("_wm_emergency_cap", False)
            ),
            wm_batch_too_small=data.get(
                "wm_batch_too_small", data.get("_wm_batch_too_small", False)
            ),
            wm_no_slot=data.get("wm_no_slot", data.get("_wm_no_slot", False)),
            wm_degradation_guard=data.get(
                "wm_degradation_guard",
                data.get("_wm_degradation_guard", False),
            ),
            pending_slot_resave=data.get(
                "pending_slot_resave",
                data.get("_pending_slot_resave", False),
            ),
            hub_tier_last_modified=data.get("hub_tier_last_modified", {}),
            hub_tier_body_hashes=data.get("hub_tier_body_hashes", {}),
            hub_tier_query_heat=data.get("hub_tier_query_heat", {}),
            hub_tier_qids_persisted=data.get("hub_tier_qids_persisted", []),
        )

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Save to SQLite
    # ═══════════════════════════════════════════════════════════════════════

    async def _save_to_db_async(
        self, project_id: str, state: ConversationState
    ) -> None:
        """Acquire the project lock and persist the state."""
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            await self._save_to_db(project_id, state)

    async def _save_to_db(self, project_id: str, state: ConversationState) -> None:
        """
        Serialize ConversationState and persist to SQLite.

        Migrated from StateStore._save_state_to_db().
        Differences:
          - Reads attributes (state.recent_changes) instead of dict keys.
          - Persists summarized_turn_hwm, history_blocked_age, and all wm_* fields.
          - Persists hub_tier_* tracker fields for cross‑restart stability.
          - The @@hash trick for code_contents remains unchanged.
        """
        # ── Serialize active_blocks, externalizing content ─────────────────
        active_blocks_meta: Dict[str, Any] = {}
        for k, v in state.active_blocks.items():
            d = v.dict()
            d["content_type"] = v.content_type.value
            content_hash = v.hash
            await self._f._state_store._db_enqueue(
                lambda ch=content_hash, ct=v.content: self._f._db_conn.execute(
                    "INSERT OR IGNORE INTO code_contents "
                    "(hash, content, created_at) VALUES (?, ?, ?)",
                    (ch, ct, time.time()),
                )
            )
            d["content"] = f"@@hash:{content_hash}"
            active_blocks_meta[k] = d

        serializable = {
            "active_blocks": active_blocks_meta,
            "recent_changes": [b.dict() for b in state.recent_changes],
            "committed_changes": [b.dict() for b in state.committed_changes],
            "feedback_history": [fb.dict() for fb in state.feedback_history],
            "message_count": state.message_count,
            "last_compression_timestamp": state.last_compression_timestamp,
            "last_suggestion_timestamp": state.last_suggestion_timestamp,
            "last_cleanup_suggestion_msg_idx": (state.last_cleanup_suggestion_msg_idx),
            "has_any_calls": state.has_any_calls,
            "last_cot_level": state.last_cot_level,
            "conversation_summaries": state.conversation_summaries,
            "summarized_turn_hwm": state.summarized_turn_hwm,
            "history_blocked_age": state.history_blocked_age,
            "wm_fired": state.wm_fired,
            "wm_msgs_evicted": state.wm_msgs_evicted,
            "wm_turns_evicted": state.wm_turns_evicted,
            "wm_summary_ok": state.wm_summary_ok,
            "wm_emergency_cap": state.wm_emergency_cap,
            "wm_batch_too_small": state.wm_batch_too_small,
            "wm_no_slot": state.wm_no_slot,
            "wm_degradation_guard": state.wm_degradation_guard,
            "pending_slot_resave": state.pending_slot_resave,
            # ── Hub‑Bodies Tier tracker (cross‑restart) ──
            "hub_tier_last_modified": state.hub_tier_last_modified,
            "hub_tier_body_hashes": state.hub_tier_body_hashes,
            "hub_tier_query_heat": state.hub_tier_query_heat,
            "hub_tier_qids_persisted": state.hub_tier_qids_persisted,
        }

        def _write() -> None:
            self._f._db_conn.execute(
                "REPLACE INTO conversation_state "
                "(project_id, state_json, updated_at) VALUES (?, ?, ?)",
                (project_id, json.dumps(serializable), time.time()),
            )
            self._f._db_conn.commit()

        await self._f._state_store._db_enqueue(_write)

    # ═══════════════════════════════════════════════════════════════════════
    # 4. SymbolIndex rebuild after cold load
    # ═══════════════════════════════════════════════════════════════════════

    def _rebuild_symbol_index(self, state: ConversationState, project_id: str) -> None:
        """
        Rebuild SymbolIndex from active blocks.

        Migrated from StateStore._rebuild_symbol_index().
        No logic changes; only attribute access (state.active_blocks).

        Invariant: The index for project_id must be empty before calling this
        to avoid duplicates. get() guarantees this because it is only called
        on a cache miss (cold load), when the index for that project has not
        been populated yet. If called elsewhere, call clear_project() first.
        """
        for block in state.active_blocks.values():
            if block.obsolete:
                continue
            for sym in block.symbols:
                self._f._symbol_index.add(sym, block.hash, project_id)
                caller_qid = qualify_symbol_name(
                    sym.name, sym.parent_symbol, sym.file_path
                )
                for callee in sym.calls:
                    edge = Edge(
                        src=caller_qid,
                        dst=callee,
                        type="calls",
                        weight=EDGE_WEIGHTS["calls"],
                    )
                    self._f._symbol_index.add_edge(edge, project_id)

    # ═══════════════════════════════════════════════════════════════════════
    # 5. LRU eviction
    # ═══════════════════════════════════════════════════════════════════════

    def _evict_lru(self) -> None:
        """
        Evict the least recently used projects when max_cached_projects is exceeded.
        """
        max_cached = self._f.valves.max_cached_projects
        while len(self._cache) > max_cached:
            oldest_pid, oldest_state = next(iter(self._cache.items()))

            if oldest_pid in self._dirty:
                try:
                    # Fire-and-forget: submit al thread pool sin esperar resultado.
                    # El thread pool tiene sus propios workers y procesará el write
                    # en background sin bloquear el event loop.
                    self._f._db_executor.submit(
                        self._f._state_store._db_conn_write_sync,
                        oldest_pid,
                        oldest_state,
                    )
                    self._f._log_debug(
                        f"ConversationStateManager: flush dispatched (non-blocking) "
                        f"for '{oldest_pid}' before LRU eviction"
                    )
                except Exception as e:
                    self._f._log_debug(
                        f"ConversationStateManager: flush dispatch failed for "
                        f"'{oldest_pid}': {e} — state may be lost"
                    )

            self._f._symbol_index.clear_project(oldest_pid)
            self._f._path_index.clear_project(oldest_pid)
            self._f._pager.clear_project(oldest_pid)
            self._f._project_state_manager.clear_project(oldest_pid)
            self.clear_project(oldest_pid)
            self._f._log_debug(
                f"ConversationStateManager: evicted LRU project '{oldest_pid}'"
            )


class ActivationGraph:
    """Personalised PageRank (PPR) engine for the symbol call graph.

    Seeds are set from user-query terms, tracebacks, and recent history.
    ``propagate()`` runs the PPR power iteration over the directed edges
    stored in ``SymbolIndex``, spreading activation to related symbols.
    The resulting scores determine the LOD tiers in Block B.
    """

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Constants & initialization
    # ═══════════════════════════════════════════════════════════════════════════

    DECAY_BASE: float = 0.7

    def __init__(self):
        self._activations: Dict[str, ActivationState] = {}

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Seed activation
    # ═══════════════════════════════════════════════════════════════════════════

    def seed(self, node_ids: List[str], initial_score: float = 1.0):
        """Insert activation seeds.  Called once before ``propagate()``."""
        for nid in node_ids:
            self._activations[nid] = ActivationState(
                node_id=nid,
                score=initial_score,
                depth=0,
                source="seed",
            )

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. PPR propagation
    # ═══════════════════════════════════════════════════════════════════════════

    def propagate(
        self,
        edges_out: Dict[str, List[Edge]],
        max_steps: int = 20,
        min_score: float = 0.05,
        alpha: float = 0.85,
        tolerance: float = 1e-6,
    ):
        """
        Run the PPR power iteration until convergence or ``max_steps``.

        Seeds keep their original high score (they are not overwritten by the
        converged PPR score). Propagated nodes receive the PPR score as usual.
        """
        if not self._activations:
            return
        seed_total = sum(
            s.score for s in self._activations.values() if s.source == "seed"
        )
        if seed_total == 0:
            return
        personalization: Dict[str, float] = {
            nid: s.score / seed_total
            for nid, s in self._activations.items()
            if s.source == "seed"
        }
        out_weight_total: Dict[str, float] = {}
        for src, edges in edges_out.items():
            total_w = sum(e.effective_weight() for e in edges)
            out_weight_total[src] = total_w if total_w > 0 else 1.0
        r: Dict[str, float] = dict(personalization)
        for iteration in range(max_steps):
            r_new: Dict[str, float] = {}
            for node, score in personalization.items():
                r_new[node] = (1.0 - alpha) * score
            for src, edges in edges_out.items():
                src_score = r.get(src, 0.0)
                if src_score < min_score:
                    continue
                out_w = out_weight_total.get(src, 1.0)
                for edge in edges:
                    contribution = alpha * src_score * edge.effective_weight() / out_w
                    r_new[edge.dst] = r_new.get(edge.dst, 0.0) + contribution
            all_keys = set(r.keys()) | set(r_new.keys())
            delta = sum(abs(r_new.get(k, 0.0) - r.get(k, 0.0)) for k in all_keys)
            r = r_new
            if delta < tolerance:
                break

        # Update activations: seeds keep their original score, propagated nodes get the PPR score
        for node_id, score in r.items():
            if score < min_score:
                continue
            existing = self._activations.get(node_id)
            # Seeds keep their initial high score — PPR only lowers propagated neighbors
            final_score = (
                max(score, existing.score)
                if (existing and existing.source == "seed")
                else score
            )
            self._activations[node_id] = ActivationState(
                node_id=node_id,
                score=final_score,
                depth=existing.depth if existing else 99,
                source=existing.source if existing else "propagation",
            )

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Query methods
    # ═══════════════════════════════════════════════════════════════════════════

    def get_score(self, node_id: str) -> float:
        """Return the final activation score of a node (0.0 if not activated)."""
        state = self._activations.get(node_id)
        return state.score if state else 0.0

    def get_activated_nodes(self, threshold: float = 0.1) -> Dict[str, float]:
        """Return {node_id: score} for nodes whose score >= threshold."""
        return {
            nid: s.score for nid, s in self._activations.items() if s.score >= threshold
        }

    def get_seed_nodes(self) -> List[str]:
        """
        Return node_ids that were seeded directly (source == 'seed'), as
        opposed to nodes that only received score via PPR propagation. Used
        by the case-D (refactor) caller pull-in: only the literal seeds —
        the symbols the user is actually asking about — should gain forced
        caller visibility, not every propagated neighbor.
        """
        return [nid for nid, s in self._activations.items() if s.source == "seed"]

    def aggregate_path_score(self, symbol_list: List[str]) -> float:
        """Mean activation score of a list of symbols (ignoring inactive ones)."""
        scores = [self.get_score(s) for s in symbol_list]
        active = [s for s in scores if s > 0]
        if not active:
            return 0.0
        return sum(active) / len(active)


# ---------------------------------------------------------------------------
# Query model and SubgraphExtractor skeleton
# ---------------------------------------------------------------------------
class SubgraphExtractor:
    """Extract a connected subgraph induced by activated nodes.

    Takes an ``ActivationGraph`` and the full edge set, then returns
    the subset of nodes that are activated (above threshold) and the
    edges among them.  Optionally expands the subgraph by one hop along
    high-confidence ``calls`` edges.
    """

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Initialization
    # ═══════════════════════════════════════════════════════════════════════════

    def __init__(self, activation_threshold: float = 0.1, expand_hops: int = 1):
        self.activation_threshold = activation_threshold
        self.expand_hops = expand_hops

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Extraction
    # ═══════════════════════════════════════════════════════════════════════════

    def extract(
        self,
        activation: ActivationGraph,
        edges_out: Dict[str, List[Edge]],
        edges_in: Dict[str, List[Edge]],
    ) -> Tuple[Set[str], List[Edge]]:
        """Return (activated_nodes, edges_among_them) after optional expansion."""
        activated = activation.get_activated_nodes(self.activation_threshold)
        included_nodes: Set[str] = set(activated.keys())
        if self.expand_hops > 0:
            expansion_candidates = []
            for node_id in list(included_nodes):
                for edge in edges_out.get(node_id, []):
                    if (
                        edge.dst not in included_nodes
                        and edge.effective_weight() >= 0.8
                        and edge.type == "calls"
                    ):
                        expansion_candidates.append(edge.dst)
            included_nodes.update(expansion_candidates)
        included_edges: List[Edge] = []
        for node_id in included_nodes:
            for edge in edges_out.get(node_id, []):
                if edge.dst in included_nodes:
                    included_edges.append(edge)
        return included_nodes, included_edges


# ---------------------------------------------------------------------------
# CodePathView — a cached projection of an activated subgraph
# ---------------------------------------------------------------------------
class CodePathView(BaseModel):
    """A cached snapshot of an activated subgraph, used for speculative
    prefetch and path tracking.  Holds the induced nodes (with scores),
    edges, and structural hashes so staleness can be detected cheaply."""

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Core identity & structural hashes
    # ═══════════════════════════════════════════════════════════════════════════

    path_id: str
    entry_point: str
    seed_nodes: List[str]

    structural_hash: str = ""  # Hash of block content for induced nodes
    call_graph_hash: str = ""  # Hash of call relationships among them

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Induced subgraph data
    # ═══════════════════════════════════════════════════════════════════════════

    induced_nodes: Dict[str, float]  # node_id → activation score
    induced_edges: List[Edge]
    activation_score: float

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Business metadata (LLM-generated labels)
    # ═══════════════════════════════════════════════════════════════════════════

    business_label: str = ""
    summary: str = ""
    label_confidence: float = 0.0

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Timestamp
    # ═══════════════════════════════════════════════════════════════════════════

    last_built: float = Field(default_factory=time.time)

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Methods
    # ═══════════════════════════════════════════════════════════════════════════

    def is_stale(self, current_structural: str, current_call_graph: str) -> bool:
        """True if the code or call graph has changed since this view was built."""
        return (
            self.structural_hash != current_structural
            or self.call_graph_hash != current_call_graph
        )

    def top_symbols(self, n: int = 10) -> List[str]:
        """Return the *n* symbols with the highest activation score in this view."""
        return sorted(
            self.induced_nodes.keys(),
            key=lambda s: self.induced_nodes[s],
            reverse=True,
        )[:n]


# ---------------------------------------------------------------------------
# StaticEvidence – deterministic proof from the SymbolGraph
# ---------------------------------------------------------------------------
class StaticEvidence(BaseModel):
    """Deterministic evidence gathered from the SymbolGraph to validate a
    hypothesis during scientific Chain‑of‑Thought reasoning.

    All fields are derived without an LLM call — they come directly from the
    SymbolIndex, active blocks, and path index.  ``objective_score`` is the
    fraction of verifiable claims that hold true."""

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Symbol evidence & call relations
    # ═══════════════════════════════════════════════════════════════════════════

    symbols_found: Dict[str, bool]  # Is each mentioned symbol in the index?
    call_relations_valid: Dict[str, bool]  # Are claimed call edges actually present?

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Recent changes & entry points
    # ═══════════════════════════════════════════════════════════════════════════

    recent_changes: List[str]  # Mentioned symbols changed in the last hour
    entry_points_mentioned: List[str]  # Entry points referenced in the hypothesis

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Path memberships & data flow
    # ═══════════════════════════════════════════════════════════════════════════

    path_memberships: Dict[str, List[str]]  # Path views each symbol belongs to
    data_flow_upstream: Dict[str, List[str]] = Field(default_factory=dict)

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Objective score
    # ═══════════════════════════════════════════════════════════════════════════

    objective_score: float  # Fraction of verifiable claims that hold


# ---------------------------------------------------------------------------
# PathIndex — index of CodePathViews
# ---------------------------------------------------------------------------
class PathIndex:
    """Lightweight in‑memory index of ``CodePathView`` objects, organised by
    project and symbol.  Used for speculative prefetch, staleness detection,
    and entry‑point discovery.
    """

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Initialization
    # ═══════════════════════════════════════════════════════════════════════════

    def __init__(self):
        self._views: Dict[str, CodePathView] = {}
        self._symbol_to_views: Dict[str, Set[str]] = defaultdict(set)

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. View management (add, remove, get)
    # ═══════════════════════════════════════════════════════════════════════════

    def add(self, view: CodePathView, project_id: str):
        """Register a view and cross‑reference all its induced symbols."""
        key = f"{project_id}:{view.path_id}"
        self._views[key] = view
        for sym_name in view.induced_nodes:
            self._symbol_to_views[f"{project_id}:{sym_name}"].add(view.path_id)

    def remove(self, path_id: str, project_id: str):
        """Remove a view and its symbol cross‑references."""
        key = f"{project_id}:{path_id}"
        view = self._views.pop(key, None)
        if view:
            for sym_name in view.induced_nodes:
                sym_key = f"{project_id}:{sym_name}"
                self._symbol_to_views[sym_key].discard(path_id)

    def get(self, path_id: str, project_id: str) -> Optional[CodePathView]:
        """Return a single view by path_id, or None."""
        return self._views.get(f"{project_id}:{path_id}")

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Project-level queries & cleanup
    # ═══════════════════════════════════════════════════════════════════════════

    def get_all(self, project_id: str) -> List[CodePathView]:
        """All views for a project (order undefined)."""
        prefix = f"{project_id}:"
        return [v for k, v in self._views.items() if k.startswith(prefix)]

    def clear_project(self, project_id: str):
        """Drop every view and cross‑reference for a project."""
        prefix = f"{project_id}:"
        keys = [k for k in self._views if k.startswith(prefix)]
        for k in keys:
            del self._views[k]
        sym_keys = [k for k in self._symbol_to_views if k.startswith(prefix)]
        for k in sym_keys:
            del self._symbol_to_views[k]

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Symbol-level queries
    # ═══════════════════════════════════════════════════════════════════════════

    def mark_stale_for_symbol(self, symbol_name: str, project_id: str) -> List[str]:
        """Return path_ids that reference a given symbol (to invalidate them later)."""
        key = f"{project_id}:{symbol_name}"
        return list(self._symbol_to_views.get(key, set()))

    def find_entry_points(
        self, symbol_index: "SymbolIndex", project_id: str
    ) -> Set[str]:
        """Symbols with no known caller — used as activation seeds when a
        query matches nothing in the index.  Operates on QUALIFIED ids so
        that, for example, a class's only method that is called exclusively
        from outside is not confused with another class's same-named method
        that DOES have registered callers."""
        all_qids = symbol_index.get_all_qualified_names(project_id)
        result = set()
        for qid in all_qids:
            meta = symbol_index.get_symbol_meta(qid, project_id) or {}
            bare = meta.get("name", qid.rsplit(".", 1)[-1])
            if not symbol_index.get_callers(bare, project_id):
                result.add(qid)
        return result


# ---------------------------------------------------------------------------
# AppliedChangeFeedback
# ---------------------------------------------------------------------------
class AppliedChangeFeedback(BaseModel):
    """Feedback record for a change that was applied (or rejected) by the user.

    Kept in the conversation state so the system can learn from past changes
    and surface context in Block A when ``inject_feedback_context`` is enabled.
    """

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Change identity & description
    # ═══════════════════════════════════════════════════════════════════════════

    change_hash: str
    change_description: str

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Location
    # ═══════════════════════════════════════════════════════════════════════════

    file_path: Optional[str] = None

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Status & metadata (original order: timestamp, success, user_comment, resolved)
    # ═══════════════════════════════════════════════════════════════════════════

    timestamp: float = Field(default_factory=time.time)
    success: bool = True
    user_comment: str = ""
    resolved: bool = False


# ═══════════════════════════════════════════════════════════════════════════
# CLASSES — Module level, before class Filter
# ═══════════════════════════════════════════════════════════════════════════


class HubSymbolIndex:
    """
    Build the architecture map for Block A: a compact class→members outline,
    plus, for the hub symbols (top-N by call-graph centrality), a
    bidirectional view of who calls them and whom they call.
    """

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Public API
    # ═══════════════════════════════════════════════════════════════════════════

    def get_hub_names(self, centrality: dict, top_n: int) -> list:
        """Return symbol ids sorted by descending centrality, capped at *top_n*.
        Ties are broken alphabetically for deterministic, cache-stable output."""
        if not centrality or top_n <= 0:
            return []
        ranked = sorted(centrality.items(), key=lambda kv: (-kv[1], kv[0]))
        return [name for name, _ in ranked[:top_n]]

    def is_hub(self, symbol_name: str, centrality: dict, top_n: int) -> bool:
        """True if *symbol_name* would appear in Block A for the given *top_n*."""
        return symbol_name in set(self.get_hub_names(centrality, top_n))

    @staticmethod
    def build(
        symbol_index: "SymbolIndex",
        centrality: dict,
        project_id: str,
        top_n: int = 30,
        valves=None,
        mode: str = "hubs_only",
    ) -> str:
        """
        Build the hub-symbol section of Block A for the given project.

        Supported modes:
            hubs_only      — compact list of hub signatures with callers/callees
            expanded_hubs  — hub signatures plus inline body excerpts
            full_graph     — all symbols in the project, no centrality filter
            class_outline  — class hierarchy without method bodies

        Returns "" when:
            - The symbol index is empty.
            - Centrality is not yet computed and mode requires it (hubs_only,
              expanded_hubs). A log entry is emitted so operators know why
              Block A is empty on the first turn.
            - mode is unrecognised. A warning is logged so misconfigured valves
              are immediately visible without tracing the full assembly pipeline.

        FIX Bug 53: removed the automatic fallback from hubs_only/expanded_hubs
        to class_outline when centrality is empty. That fallback was a behaviour
        change: users on first session or with empty projects would see unexpected
        content in Block A, and the block-A cache (keyed on structure hash, not
        mode) could store a class_outline entry for a hubs_only key, producing
        an inconsistent cache on the next turn when centrality becomes available.

        Steps:
            1.  Validate inputs; return "" on empty index.
            2.  Check centrality availability for mode that requires it.
            3.  Dispatch to the appropriate builder by mode.
            4.  Log warning and return "" for unrecognised modes.
        """
        # -- Step 1: validate inputs --
        all_qids = symbol_index.get_all_qualified_names(project_id)
        if not all_qids:
            return ""

        # -- Step 2: centrality availability check --
        if not centrality and mode in ("hubs_only", "expanded_hubs"):
            import logging

            logging.getLogger(__name__).debug(
                "HubSymbolIndex.build: centrality not yet computed for "
                "'%s' (mode='%s'). Returning empty hub tier. "
                "Will populate after first PPR pass.",
                project_id,
                mode,
            )
            return ""

        # -- Step 3: dispatch --
        if mode == "hubs_only":
            hub_qids = HubSymbolIndex.get_hub_names(centrality, top_n)
            if not hub_qids:
                return ""
            return HubSymbolIndex._build_hub_section(
                hub_qids=hub_qids,
                centrality=centrality,
                symbol_index=symbol_index,
                project_id=project_id,
                enable_callees=True,
            )

        if mode == "expanded_hubs":
            return HubSymbolIndex._build_expanded_hubs_section(
                symbol_index=symbol_index,
                centrality=centrality,
                project_id=project_id,
                top_n=top_n,
                valves=valves,
            )

        if mode == "full_graph":
            return HubSymbolIndex._build_full_graph_section(
                symbol_index=symbol_index,
                project_id=project_id,
                valves=valves,
            )

        if mode == "class_outline":
            return HubSymbolIndex._build_class_outline(
                symbol_index=symbol_index,
                project_id=project_id,
                valves=valves,
            )

        # -- Step 4: unrecognised mode --
        import logging

        logging.getLogger(__name__).warning(
            "HubSymbolIndex.build: unrecognised mode '%s' for project '%s'. "
            "Valid modes: hubs_only, expanded_hubs, full_graph, class_outline. "
            "Returning empty hub tier.",
            mode,
            project_id,
        )
        return ""

    def _build_expanded_hubs_section(
        self, symbol_index, centrality, project_id, top_n, valves=None
    ) -> str:
        """
        Top-N hubs (rendered exactly as in hubs_only) PLUS a sub-section
        listing every direct neighbor (caller or callee) of any hub that is
        not itself a hub — one hop beyond the hub set without the full
        O(all symbols) cost.

        Neighbors are a flat qid list grouped by hub (NOT full
        _format_symbol_line entries — that would recursively pull in THEIR
        neighbors and balloon token cost, blowing the ~2k-5k budget).
        Truncated by expanded_hubs_max_tokens with an explicit notice.
        """
        enable_callees = getattr(valves, "enable_hub_callees", True) if valves else True
        hub_qids = self.get_hub_names(centrality, top_n)
        if not hub_qids:
            logger.debug("Expanded hubs: no hubs found, returning empty.")
            return ""

        hub_section = self._build_hub_section(
            hub_qids, centrality, symbol_index, project_id, enable_callees
        )

        hub_set = set(hub_qids)
        neighbor_lines = []
        for qid in hub_qids:
            callers = self._safe_callers(qid, project_id, symbol_index) - hub_set
            callees = self._safe_callees(qid, project_id, symbol_index) - hub_set
            extra = sorted(callers | callees)
            if extra:
                neighbor_lines.append(f"- `{qid}` neighbors: {', '.join(extra)}")

        if not neighbor_lines:
            logger.debug("Expanded hubs: no neighbor lines to add.")
            return hub_section

        budget_chars = self.valves_expanded_hubs_budget_chars(valves)
        kept_lines = []
        total = 0
        omitted = 0
        for idx, line in enumerate(neighbor_lines):
            total += len(line)
            if budget_chars and total > budget_chars:
                omitted = len(neighbor_lines) - idx
                kept_lines.append(
                    f"_(Neighbor list truncated to fit budget — "
                    f"{omitted} hub(s) omitted)_"
                )
                break
            kept_lines.append(line)

        logger.debug(
            f"Expanded hubs: {len(hub_qids)} hubs, {len(neighbor_lines)} neighbor entries total, "
            f"{len(kept_lines) - (1 if omitted else 0)} shown, {omitted} omitted due to budget."
        )

        neighbor_section = (
            "### Direct neighbors of hub symbols (depth 1, non-hub only)\n"
            + "\n".join(kept_lines)
        )
        return hub_section + "\n\n" + neighbor_section

    @staticmethod
    def valves_expanded_hubs_budget_chars(valves) -> int:
        """expanded_hubs_max_tokens → char budget (4 chars/token heuristic).
        Returns 0 (no limit) if valves is None or the field is absent."""
        if valves is None:
            return 0
        tok = getattr(valves, "expanded_hubs_max_tokens", 0)
        return tok * 4 if tok > 0 else 0

    def _build_full_graph_section(self, symbol_index, project_id, valves=None) -> str:
        """
        Every qualified symbol in the project, alphabetically sorted, each with
        its direct callers/callees (no centrality score — in full_graph every
        symbol is shown regardless of rank, so a score column is misleading
        noise).

        Alphabetical order (not centrality order) is deliberate: centrality
        ties at 0.0 for every leaf symbol, so centrality-based ordering is not
        stable across rebuilds and would cause spurious Block A cache misses
        from pure reordering. Alphabetical order is stable as long as the
        symbol set is unchanged — exactly what Block A's code_state_hash key
        already tracks.

        Hard-truncates at full_graph_max_tokens with an explicit notice. Never
        falls back to a different mode — truncation is the only degradation path.
        """
        all_qids = sorted(symbol_index.get_all_qualified_names(project_id))
        if not all_qids:
            logger.debug("Full graph: no symbols found, returning empty.")
            return ""

        max_tokens = (
            getattr(valves, "full_graph_max_tokens", 20000) if valves else 20000
        )
        budget_chars = max_tokens * 4 if max_tokens > 0 else None

        # Defense in depth: a manual override of full_graph bypasses the
        # auto-mode symbol-count ceiling entirely. Cap the candidate list
        # itself (not just the rendered text) so an oversized manually-forced
        # project never allocates per-symbol caller/callee sets it will
        # immediately discard via truncation. ~4 chars/token, ~80 chars/line
        # average for a symbol-with-edges line ⇒ budget_chars // 80 is a safe
        # upper bound on how many lines could possibly fit regardless of
        # actual edge density.
        if budget_chars is not None:
            max_renderable_lines = max(10, budget_chars // 80)
            if len(all_qids) > max_renderable_lines:
                original_count = len(all_qids)
                all_qids = all_qids[:max_renderable_lines]
                logger.debug(
                    f"Full graph: capped candidate list from {original_count} to "
                    f"{max_renderable_lines} (budget {max_tokens} tokens)"
                )

        logger.debug(
            f"Full graph: rendering {len(all_qids)} symbols, budget {max_tokens} tokens."
        )

        lines = [
            f"## Full Call Graph (all {len(all_qids)} symbols, direct edges only)",
            "_Every indexed symbol with its direct callers/callees. "
            "Use `/expand <name>` for full bodies._",
            "",
        ]
        total_chars = sum(len(l) for l in lines)

        truncated = False
        for idx, qid in enumerate(all_qids):
            line = self._format_symbol_line_no_score(qid, project_id, symbol_index)
            if budget_chars is not None and total_chars + len(line) > budget_chars:
                remaining = len(all_qids) - idx
                lines.append(
                    f"\n_(Truncated to fit {max_tokens}-token budget — "
                    f"{remaining} symbol(s) omitted. Consider expanded_hubs "
                    f"or raising full_graph_max_tokens.)_"
                )
                truncated = True
                logger.debug(
                    f"Full graph truncated: kept {idx} symbols out of {len(all_qids)}, "
                    f"omitted {remaining} due to budget {max_tokens} tokens."
                )
                break
            lines.append(line)
            total_chars += len(line)

        if not truncated:
            logger.debug(
                f"Full graph: successfully rendered all {len(all_qids)} symbols."
            )

        return "\n".join(lines)

    def _format_symbol_line_no_score(self, qid, project_id, symbol_index) -> str:
        """
        Same as _format_symbol_line but without the centrality score column.
        full_graph forces callees on: showing the bidirectional edge set is the
        whole point of this mode.

        Caller attribution caveat: get_edges_in() resolves by bare name —
        a method shared across multiple classes (every __init__, etc.) shows
        the union of callers of ANY same-named method, not specifically this
        occurrence. Lines affected by this are marked '(ambiguous: shared name)'
        so the model — and a human reading the dump — doesn't treat the
        caller list as precise for those symbols.

        All callers and callees are shown in full, without truncation.
        """
        bare_name = qid.rsplit(".", 1)[-1]
        is_ambiguous_name = (
            len(symbol_index.get_qualified_names_for(bare_name, project_id)) > 1
        )

        callers = self._safe_callers(qid, project_id, symbol_index)
        callees = self._safe_callees(qid, project_id, symbol_index)

        parts = [f"- `{qid}`"]

        if callers:
            tag = " (ambiguous: shared name)" if is_ambiguous_name else ""
            parts.append(f"\n  ← used by{tag}: {', '.join(sorted(callers))}")

        if callees:
            parts.append(f"\n  → calls: {', '.join(sorted(callees))}")

        return "".join(parts)

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Class / function outline (Architecture Map)
    # ═══════════════════════════════════════════════════════════════════════════

    def _build_class_outline(self, symbol_index, project_id, valves=None) -> str:
        """Render the ``## Code Architecture Map`` section: one line per class
        listing its methods, plus module-level functions if any.  Respects
        ``architecture_map_max_tokens`` for the overall section budget.
        """
        if valves is not None and not getattr(valves, "enable_architecture_map", True):
            return ""
        max_tokens = (
            getattr(valves, "architecture_map_max_tokens", 3000) if valves else 3000
        )

        classes = sorted(symbol_index.get_classes(project_id))
        if not classes:
            return ""

        lines = [
            "## Code Architecture Map",
            "_Class → methods. See the hub section below for call relationships "
            "of the most central symbols. Use `/expand <name>` or "
            "`/expand Class.method` for full bodies._",
            "",
        ]
        total_chars = sum(len(l) for l in lines)
        budget_chars = max_tokens * 4 if max_tokens > 0 else None
        truncated = False

        for class_name in classes:
            member_qids = symbol_index.get_class_members(class_name, project_id)
            if not member_qids:
                continue
            bare_members = []
            for qid in member_qids:
                meta = symbol_index.get_symbol_meta(qid, project_id) or {}
                bare_members.append(meta.get("name", qid.rsplit(".", 1)[-1]))
            line = (
                f"- **{class_name}** ({len(bare_members)} methods): "
                f"{', '.join(bare_members)}"
            )
            if budget_chars is not None and total_chars + len(line) > budget_chars:
                lines.append(
                    f"_(Outline truncated to fit budget — {len(classes)} classes total)_"
                )
                truncated = True
                break
            lines.append(line)
            total_chars += len(line)

        if not truncated:
            top_level = sorted(
                qid
                for qid in symbol_index.get_all_qualified_names(project_id)
                if "." not in qid
                and (symbol_index.get_symbol_meta(qid, project_id) or {}).get("kind")
                == "function"
            )
            if top_level:
                line = f"- **(module-level functions)**: {', '.join(top_level)}"
                if budget_chars is None or total_chars + len(line) <= budget_chars:
                    lines.append(line)

        if len(lines) <= 3:
            return ""
        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Hub symbols with bidirectional call graph
    # ═══════════════════════════════════════════════════════════════════════════

    def _build_hub_section(
        self, hub_qids, centrality, symbol_index, project_id, enable_callees=True
    ) -> str:
        """Render the ``## Code Symbol Index`` section listing each hub symbol
        with its centrality score, incoming callers, and (when
        *enable_callees* is True) outgoing callees."""
        by_file: dict = {}
        for qid in hub_qids:
            file_path = self._file_for(qid, project_id, symbol_index)
            by_file.setdefault(file_path, []).append(qid)

        lines = [
            f"## Code Symbol Index — Hub Symbols (top {len(hub_qids)} by call-graph centrality)",
            "> Remaining symbols are available via LOD activation. "
            "Use /expand <name> for any symbol's full body.",
            "",
        ]

        if len(by_file) == 1 and None in by_file:
            for qid in sorted(hub_qids, key=lambda q: -centrality.get(q, 0)):
                lines.append(
                    self._format_symbol_line(
                        qid, centrality, symbol_index, project_id, enable_callees
                    )
                )
        else:
            for file_path in sorted(by_file.keys(), key=lambda fp: (fp is None, fp)):
                if file_path is None:
                    continue
                lines.append(f"### {file_path}")
                for qid in sorted(
                    by_file[file_path], key=lambda q: -centrality.get(q, 0)
                ):
                    lines.append(
                        self._format_symbol_line(
                            qid, centrality, symbol_index, project_id, enable_callees
                        )
                    )
                lines.append("")

        lines.append(
            "To see any symbol's full body, mention it in your message "
            "or use /expand <name>."
        )
        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Private helpers
    # ═══════════════════════════════════════════════════════════════════════════

    def _file_for(self, qid, project_id, symbol_index):
        """Resolve a symbol's file path from the SymbolIndex, or None."""
        return symbol_index.get_file_for_symbol(qid, project_id)

    def _safe_callers(self, qid, project_id, symbol_index) -> set:
        """Callers of `qid`, looked up by its BARE name — edge destinations
        are best-effort bare strings (see SymbolIndex docstring), so this is
        the only reliable lookup direction, with the known limitation that a
        very common bare name (e.g. __init__) will show callers from any
        method of that same name, not only this one."""
        meta = symbol_index.get_symbol_meta(qid, project_id) or {}
        bare = meta.get("name", qid.rsplit(".", 1)[-1])
        fn = getattr(symbol_index, "get_edges_in", None)
        if not callable(fn):
            return set()
        try:
            edges = fn(bare, project_id)
            return {e.src for e in edges}
        except Exception:
            return set()

    def _safe_callees(self, qid, project_id, symbol_index) -> set:
        """Callees of `qid`, looked up by its qualified id — precise, since
        edge sources are always the exact symbol in whose body the call was
        found."""
        fn = getattr(symbol_index, "get_edges_out", None)
        if not callable(fn):
            return set()
        try:
            edges = fn(qid, project_id)
            return {e.dst for e in edges}
        except Exception:
            return set()

    @staticmethod
    def _format_symbol_line(
        qid: str,
        centrality: dict,
        symbol_index: "SymbolIndex",
        project_id: str,
        enable_callees: bool = True,
    ) -> str:
        """
        Format a single symbol line for the hub tier.

        Renders: signature, centrality score, file location, and optionally
        the top callers and callees.

        When get_signature() returns None (stale index entry, dangling edge, or
        symbol removed since last centrality computation), falls back to the
        bare qualified id rather than producing the literal string "None" in the
        hub section.

        Steps:
            1.  Resolve signature with bare-qid fallback.
            2.  Format centrality score.
            3.  Append file location if available.
            4.  Append callers and callees when enabled.
        """
        # -- Step 1: resolve signature --
        signature = (
            symbol_index.get_signature(qid, project_id)
            or qid.rsplit(".", 1)[-1]  # bare name as last resort
        )

        cent_score = centrality.get(qid, 0.0)

        # -- Step 2: format score --
        line = f"- `{signature}` _(hub: {cent_score:.2f})_"

        # -- Step 3: file location --
        file_path = HubSymbolIndex._file_for(qid, project_id, symbol_index)
        if file_path:
            line += f" · `{file_path}`"

        # -- Step 4: callers and callees --
        if enable_callees:
            callers = HubSymbolIndex._safe_callers(qid, project_id, symbol_index)
            callees = HubSymbolIndex._safe_callees(qid, project_id, symbol_index)

            if callers:
                caller_sigs = []
                for c in sorted(callers)[:3]:
                    sig = (
                        symbol_index.get_signature(c, project_id)
                        or c.rsplit(".", 1)[-1]
                    )
                    caller_sigs.append(f"`{sig}`")
                line += f"\n  ← {', '.join(caller_sigs)}"

            if callees:
                callee_sigs = []
                for c in sorted(callees)[:3]:
                    sig = (
                        symbol_index.get_signature(c, project_id)
                        or c.rsplit(".", 1)[-1]
                    )
                    callee_sigs.append(f"`{sig}`")
                line += f"\n  → {', '.join(callee_sigs)}"

        return line


class ContextPager:
    """
    Manages CodeBlock lifecycle between active_blocks (RAM) and ChromaDB (paged).

    This class handles soft-eviction of code blocks to ChromaDB when they are
    no longer relevant, and page-in of blocks that become relevant again.
    It uses a CrossEncoder + LLM cascade to make eviction decisions.
    """

    # ------------------------------------------------------------------
    # Region: Initialization & State Management
    # ------------------------------------------------------------------

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the ContextPager with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance.
        """
        self._f = filter_ref
        # project_id -> set of block hashes currently paged out.
        self._paged_hashes: dict = {}

    def is_paged(self, block_hash: str, project_id: str) -> bool:
        """
        Check if a block hash is currently paged out for a project.

        Args:
            block_hash: The hash of the code block.
            project_id: The project identifier.

        Returns:
            True if the block is paged out, False otherwise.
        """
        return block_hash in self._paged_hashes.get(project_id, set())

    def clear_project(self, project_id: str) -> None:
        """
        Drop the in-memory paged registry for a project.

        Called on project switch to avoid stale references.

        Args:
            project_id: The project identifier.
        """
        self._paged_hashes.pop(project_id, None)

    # ------------------------------------------------------------------
    # Region: Eviction & Page-Out
    # ------------------------------------------------------------------

    def get_eviction_candidates(
        self,
        state: ConversationState,
        project_id: str,
        activation_scores: dict,
        paging_threshold: int,
        min_activation: float,
    ) -> list:
        """
        Return block hashes eligible for page-out based on activation scores.

        Criteria:
            - Active block count exceeds paging_threshold.
            - Block activation score is below min_activation.
            - Block is not pinned, not obsolete, and not in the hub tier.

        Args:
            state: The current conversation state.
            project_id: Current project identifier.
            activation_scores: Dict mapping qualified symbol ids to activation scores.
            paging_threshold: Active block count above which paging starts.
            min_activation: Minimum activation score to keep a block in RAM.

        Returns:
            A list of block hashes eligible for page-out, sorted by coldest first.
        """
        active = state.active_blocks
        if len(active) <= paging_threshold:
            return []

        # ------------------------------------------------------------------
        # Step 1: Get hub tier qids to protect them from paging.
        # ------------------------------------------------------------------
        psm = self._f._project_state_manager
        tier_qids = set(psm.get_hub_tier_qids(project_id))
        if not tier_qids:
            tier_qids = set(state.hub_tier_qids_persisted)

        candidates = []

        # ------------------------------------------------------------------
        # Step 2: Evaluate each block for eviction.
        # ------------------------------------------------------------------
        for h, block in active.items():
            if block.pinned or block.obsolete:
                continue

            if self._f.valves.hub_bodies_tier_protect_from_paging:
                if any(qualify_symbol(s) in tier_qids for s in block.symbols):
                    continue

            # Block-level activation is the max of its symbols' scores.
            if block.symbols:
                block_activation = max(
                    (
                        activation_scores.get(qualify_symbol(s), 0.0)
                        for s in block.symbols
                    ),
                    default=0.0,
                )
            else:
                block_activation = 0.0

            if block_activation < min_activation:
                candidates.append((h, block_activation, block.importance_score))

        # ------------------------------------------------------------------
        # Step 3: Sort by coldest first (activation then importance).
        # ------------------------------------------------------------------
        candidates.sort(key=lambda t: (t[1], t[2]))
        n_to_page = len(active) - paging_threshold
        selected = [h for h, _, _ in candidates[:n_to_page]]

        return selected

    async def page_out_block(
        self,
        block: "CodeBlock",
        project_id: str,
        state: dict,
        symbol_index: "SymbolIndex",
        chroma_collection,
        embedder,
    ) -> bool:
        """
        Soft-evict a code block to ChromaDB with semantic relevance filtering.

        Uses a cascade: heuristic reinforcement, CrossEncoder, and LLM fallback.
        The full block content (up to 32768 tokens) is stored in ChromaDB as
        the authoritative source for page_in_block reconstruction.

        Args:
            block: The block to page out.
            project_id: Current project identifier.
            state: Conversation state.
            symbol_index: SymbolIndex instance.
            chroma_collection: ChromaDB collection for cold storage.
            embedder: Embedder instance.

        Returns:
            True if the block was paged out, False if kept.
        """
        if chroma_collection is None or embedder is None:
            return False

        current_query = self._f._project_state_manager.get_last_user_query(project_id)

        should_page_out = True
        h_weight = self._f.valves.heuristic_reinforcement_weight

        # ── Step 1: Heuristic reinforcement — boost keep for important blocks ──
        if block.importance_score > 5.0 or block.pinned:
            keep_boost = 0.2 * h_weight
        else:
            keep_boost = 0.0

        # ── Step 2: CrossEncoder evaluation ───────────────────────────────────
        if current_query and self._f._cross_encoder is not None:
            content_snippet = block.content[:1500]
            pairs = [
                (
                    current_query[:500],
                    f"This code block is relevant to the current query and should be kept:\n{content_snippet}",
                ),
                (
                    current_query[:500],
                    f"This code block is not relevant to the current query and can be paged out:\n{content_snippet}",
                ),
            ]
            scores = await self._f._commands._predict_cross_encoder(pairs)

            if scores is not None and len(scores) >= 2:
                scores_reinforced = list(scores)
                scores_reinforced[0] += keep_boost

                diff = scores_reinforced[0] - scores_reinforced[1]
                CE_CONFIDENCE_THRESHOLD = self._f.valves.paging_ce_threshold
                LLM_FALLBACK_THRESHOLD = self._f.valves.paging_llm_threshold

                if diff >= CE_CONFIDENCE_THRESHOLD:
                    should_page_out = scores_reinforced[1] > scores_reinforced[0]
                    self._f._log_debug(
                        f"page_out_block: CE confident (diff={diff:.2f}) → "
                        f"{'page out' if should_page_out else 'keep'} for {block.hash[:8]}"
                    )
                elif diff < LLM_FALLBACK_THRESHOLD:
                    self._f._log_debug(
                        f"page_out_block: CE uncertain (diff={diff:.2f} < {LLM_FALLBACK_THRESHOLD:.2f}), "
                        f"using LLM for {block.hash[:8]}"
                    )
                    should_page_out = await self._page_out_block_with_llm(
                        block, current_query, scores_reinforced, project_id
                    )
                else:
                    should_page_out = not (block.importance_score > 5.0 or block.pinned)
                    self._f._log_debug(
                        f"page_out_block: middle zone, heuristic: "
                        f"{'page out' if should_page_out else 'keep'} for {block.hash[:8]}"
                    )

        # ── Step 3: Execute page-out if decided ───────────────────────────────
        if should_page_out:
            entry_id = f"{project_id}_paged_{block.hash}"
            symbol_names = ",".join(s.name for s in block.symbols)

            # Truncate to embedder token limit — this is stored as the
            # authoritative document in ChromaDB for lossless page_in.
            safe_text = block.content
            if hasattr(self._f, "_tokens"):
                safe_text = self._f._tokens.truncate_text_to_tokens(
                    block.content, 32768
                )

            metadata = {
                "project_id": project_id,
                "is_paged_block": True,
                "block_hash": block.hash,
                "file_path": block.file_path or "",
                "content_type": block.content_type.value,
                "importance_score": block.importance_score,
                "paged_at": time.time(),
                "symbol_names": symbol_names,
            }

            # Offload embedding + upsert to background — safe_text is the
            # document (not a 2000-char excerpt) so page_in can reconstruct fully.
            asyncio.create_task(
                self._page_out_async(
                    entry_id=entry_id,
                    safe_text=safe_text,
                    metadata=metadata,
                    embedder=embedder,
                    chroma_collection=chroma_collection,
                )
            )

            self._paged_hashes.setdefault(project_id, set()).add(block.hash)
            return True

        return False

    async def _page_out_async(
        self,
        entry_id: str,
        safe_text: str,
        metadata: dict,
        embedder,
        chroma_collection,
    ) -> None:
        """
        Background task for embedding and upserting a paged block.

        safe_text is stored as both the embedding source and the ChromaDB
        document, making it the authoritative source for page_in_block
        reconstruction. The previous design stored only a 2000-char excerpt
        as the document, making lossless reconstruction impossible.

        Args:
            entry_id: Unique ID for the ChromaDB entry.
            safe_text: Full block content (truncated to embedder token limit).
            metadata: Metadata to store with the embedding.
            embedder: Embedder instance.
            chroma_collection: ChromaDB collection.
        """
        async with self._f._chroma_semaphore:
            try:
                embedding = await anyio.to_thread.run_sync(
                    lambda: embedder.encode(safe_text).tolist()
                )
                await anyio.to_thread.run_sync(
                    lambda: chroma_collection.upsert(
                        ids=[entry_id],
                        embeddings=[embedding],
                        documents=[safe_text],  # full content — was excerpt[:2000]
                        metadatas=[metadata],
                    )
                )
            except Exception:
                # Best effort; paged_hashes already tracks the eviction.
                # If this fails, page_in_block will return None for this block.
                pass

    # ------------------------------------------------------------------
    # Region: LLM Fallback for Paging Decision
    # ------------------------------------------------------------------

    async def _page_out_block_with_llm(
        self,
        block: "CodeBlock",
        query: str,
        ce_scores: List[float],
        project_id: str,
    ) -> bool:
        """
        LLM fallback for paging decision when the CrossEncoder diff falls
        below paging_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer. Default on failure is False (keep) to
        avoid discarding potentially relevant blocks.

        Args:
            block: The block being considered for paging.
            query: Current user query (truncated to 400 chars).
            ce_scores: [keep_score, pageout_score] from the CrossEncoder.
            project_id: Current project identifier, used for slot restoration.

        Returns:
            bool: True if the block should be paged out, False to keep it.
        """
        prompt = (
            f"CrossEncoder scores — keep: {ce_scores[0]:.2f}, "
            f"page_out: {ce_scores[1]:.2f}\n\n"
            f"Code block (snippet):\n{block.content[:500]}\n\n"
            f"Current query:\n{query[:400]}\n\n"
            f"Is this block needed to answer the query? "
            f"When uncertain, prefer keeping it.\n\n"
            f'Output only the JSON object, e.g. {{"page_out": false}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a memory manager. "
                "Output ONLY a valid JSON object with a single boolean field 'page_out'. "
                "When uncertain, output false (keep the block). "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="paging_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            self._f._log_debug(
                f"_page_out_block_with_llm: empty response, keeping block {block.hash[:8]}"
            )
            return False

        try:
            data = json.loads(response)
            result = bool(data.get("page_out", False))
            self._f._log_debug(
                f"_page_out_block_with_llm: "
                f"{'page out' if result else 'keep'} for block {block.hash[:8]}"
            )
            return result
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_page_out_block_with_llm: JSON parse error — "
                f"response: {response[:200]!r}, keeping block {block.hash[:8]}"
            )
            return False

    # ------------------------------------------------------------------
    # Region: Purge Old Versions
    # ------------------------------------------------------------------

    async def purge_old_versions(
        self,
        project_id: str,
        state: dict,
        symbol_index: "SymbolIndex",
        chroma_collection,
        embedder,
        max_versions_per_file: int = 3,
        stop_event: asyncio.Event = None,
    ) -> int:
        """
        Move code versions beyond the N most recent per file to cold storage.

        Uses the same cascade as page_out_block for each old version.

        Args:
            project_id: Current project identifier.
            state: Conversation state.
            symbol_index: SymbolIndex instance.
            chroma_collection: ChromaDB collection for cold storage.
            embedder: Embedder instance.
            max_versions_per_file: Number of recent versions per file to keep.
            stop_event: If set, stops processing gracefully.

        Returns:
            int: The number of blocks purged.
        """
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            from collections import defaultdict

            if stop_event and stop_event.is_set():
                return 0

            # ------------------------------------------------------------------
            # Step 1: Group blocks by file path.
            # ------------------------------------------------------------------
            by_file = defaultdict(list)
            for h, block in state.active_blocks.items():
                if block.file_path and not block.pinned and not block.obsolete:
                    by_file[block.file_path].append((h, block))

            purged = 0
            current_query = self._f._project_state_manager.get_last_user_query(
                project_id
            )
            h_weight = self._f.valves.heuristic_reinforcement_weight

            # ------------------------------------------------------------------
            # Step 2: Process each file's versions.
            # ------------------------------------------------------------------
            for file_path, versions in by_file.items():
                if stop_event and stop_event.is_set():
                    self._f._log_debug(
                        f"purge_old_versions: stopped after {purged} purged blocks"
                    )
                    break

                if len(versions) <= max_versions_per_file:
                    continue

                versions.sort(key=lambda x: x[1].timestamp, reverse=True)
                to_purge = versions[max_versions_per_file:]

                for h, block in to_purge:
                    should_purge = True

                    # ------------------------------------------------------------------
                    # Heuristic reinforcement: keep if important.
                    # ------------------------------------------------------------------
                    keep_boost = 0.2 * h_weight if block.importance_score > 5.0 else 0.0

                    # ------------------------------------------------------------------
                    # CrossEncoder evaluation.
                    # ------------------------------------------------------------------
                    if current_query and self._f._cross_encoder is not None:
                        content_snippet = block.content[:1500]
                        pairs = [
                            (
                                current_query[:500],
                                f"This old version is still relevant and should be kept:\n{content_snippet}",
                            ),
                            (
                                current_query[:500],
                                f"This old version is obsolete and can be purged:\n{content_snippet}",
                            ),
                        ]
                        scores = await self._f._commands._predict_cross_encoder(pairs)

                        if scores is not None and len(scores) >= 2:
                            scores_reinforced = list(scores)
                            scores_reinforced[0] += keep_boost

                            diff = scores_reinforced[0] - scores_reinforced[1]
                            CE_CONFIDENCE_THRESHOLD = self._f.valves.purge_ce_threshold
                            LLM_FALLBACK_THRESHOLD = self._f.valves.purge_llm_threshold

                            if diff >= CE_CONFIDENCE_THRESHOLD:
                                should_purge = (
                                    scores_reinforced[1] > scores_reinforced[0]
                                )
                                self._f._log_debug(
                                    f"purge_old_versions: CE confident (diff={diff:.2f}) → "
                                    f"{'purge' if should_purge else 'keep'} for {block.hash[:8]}"
                                )
                            elif diff < LLM_FALLBACK_THRESHOLD:
                                self._f._log_debug(
                                    f"purge_old_versions: CE uncertain (diff={diff:.2f} < {LLM_FALLBACK_THRESHOLD:.2f}), "
                                    f"using LLM for {block.hash[:8]}"
                                )
                                should_purge = await self._purge_old_version_with_llm(
                                    block, current_query, scores_reinforced, project_id
                                )
                            else:
                                should_purge = not (
                                    block.importance_score > 5.0 or block.pinned
                                )
                                self._f._log_debug(
                                    f"purge_old_versions: middle zone, heuristic: "
                                    f"{'purge' if should_purge else 'keep'} for {block.hash[:8]}"
                                )

                    # ------------------------------------------------------------------
                    # Execute purge if decided.
                    # ------------------------------------------------------------------
                    if should_purge:
                        if (
                            self._f.valves.enable_block_paging
                            and chroma_collection is not None
                        ):
                            paged = await self.page_out_block(
                                block=block,
                                project_id=project_id,
                                state=state,
                                symbol_index=symbol_index,
                                chroma_collection=chroma_collection,
                                embedder=embedder,
                            )
                            if paged:
                                del state.active_blocks[h]
                                purged += 1
                                continue

                        # Fallback: remove from active blocks without paging.
                        if h in state.active_blocks:
                            del state.active_blocks[h]
                            purged += 1

            if purged > 0:
                self._f._log_debug(
                    f"Purged {purged} old code version(s) across {len(by_file)} file(s)"
                )
            return purged

    async def _purge_old_version_with_llm(
        self,
        block: "CodeBlock",
        query: str,
        ce_scores: List[float],
        project_id: str,
    ) -> bool:
        """
        LLM fallback for purge decision when the CrossEncoder diff falls
        below purge_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer. Default on failure is False (keep) to
        avoid discarding potentially valuable context.

        Args:
            block: The block to evaluate.
            query: Current user query (truncated to 500 chars).
            ce_scores: [keep_score, purge_score] from the CrossEncoder.
            project_id: Current project identifier, used for slot restoration.

        Returns:
            bool: True if the block should be purged, False to keep it.
        """
        prompt = (
            f"CrossEncoder scores — keep: {ce_scores[0]:.2f}, "
            f"purge: {ce_scores[1]:.2f}\n\n"
            f"Old version (snippet):\n{block.content[:500]}\n\n"
            f"Current query:\n{query[:500]}\n\n"
            f"Is this old version still valuable for context, "
            f"or can it be safely purged? "
            f"Consider whether it is likely to be referenced again.\n\n"
            f'Output only the JSON object, e.g. {{"purge": false}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a memory manager. "
                "Output ONLY a valid JSON object with a single boolean field 'purge'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="purge_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            self._f._log_debug(
                f"_purge_old_version_with_llm: empty response, "
                f"keeping block {block.hash[:8]}"
            )
            return False

        try:
            data = json.loads(response)
            result = bool(data.get("purge", False))
            self._f._log_debug(
                f"_purge_old_version_with_llm: "
                f"{'purge' if result else 'keep'} for block {block.hash[:8]}"
            )
            return result
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_purge_old_version_with_llm: JSON parse error — "
                f"response: {response[:200]!r}, keeping block {block.hash[:8]}"
            )
            return False

    # ------------------------------------------------------------------
    # Region: Page-In
    # ------------------------------------------------------------------

    async def page_in_block(
        self,
        block_hash: str,
        project_id: str,
        chroma_collection,
        db_conn=None,
    ) -> "Optional[CodeBlock]":
        """
        Retrieve a soft-evicted block from ChromaDB for use in the current turn only.
        Does NOT restore the block to active_blocks.

        ChromaDB is always consulted when the block is absent from the in-memory
        registry. This handles the post-restart case where _paged_hashes was reset
        but the block persists in ChromaDB. When found via this fallback path, the
        block_hash is re-registered in _paged_hashes so that subsequent is_paged()
        calls return correctly for the remainder of the session.

        db_conn is accepted for API compatibility but is unused; ChromaDB is the
        single authoritative source for paged block content.
        """
        if chroma_collection is None:
            return None

        entry_id = f"{project_id}_paged_{block_hash}"

        # -- Step 1: log registry miss for diagnostics --
        # The absence from _paged_hashes does not abort the lookup; it may
        # simply indicate a post-restart access.
        if not self.is_paged(block_hash, project_id):
            self._f._log_debug(
                f"page_in_block: {block_hash[:8]} not in paged registry, "
                f"attempting ChromaDB lookup (possible post-restart access)"
            )

        # -- Step 2: fetch full content and metadata from ChromaDB --
        meta = None
        content = ""
        try:
            result = await anyio.to_thread.run_sync(
                lambda: chroma_collection.get(
                    ids=[entry_id], include=["metadatas", "documents"]
                )
            )
            if result and result.get("ids"):
                meta = result["metadatas"][0]
                content = result["documents"][0] if result.get("documents") else ""
        except Exception as e:
            self._f._log_debug(
                f"page_in_block: ChromaDB fetch failed for {block_hash[:8]}: {e}"
            )
            return None

        if not content:
            return None

        # -- Step 3: re-register in paged_hashes --
        # Ensures is_paged() returns True for the remainder of this session
        # without requiring another ChromaDB round-trip.
        self._paged_hashes.setdefault(project_id, set()).add(block_hash)

        # -- Step 4: extract metadata fields with safe defaults --
        file_path = meta.get("file_path") if meta else None
        ctype_str = (
            meta.get("content_type", ContentType.GENERAL.value)
            if meta
            else ContentType.GENERAL.value
        )
        importance = meta.get("importance_score", 1.0) if meta else 1.0

        try:
            ctype = ContentType(ctype_str)
        except Exception:
            ctype = ContentType.GENERAL

        # -- Step 5: re-extract symbols from the restored content --
        symbols = []
        try:
            symbols = await SignatureExtractor.extract_async(content, file_path)
        except Exception:
            pass

        # -- Step 6: reconstruct and return the CodeBlock --
        block = CodeBlock(
            content=content,
            content_type=ctype,
            file_path=file_path,
            hash=block_hash,
            symbols=symbols,
            importance_score=importance,
        )
        for s in block.symbols:
            s.parent_block_hash = block_hash

        return block


class RaptorCodeIndex:
    """
    Hierarchical clustering of code symbols (RAPTOR adapted for code).

    Builds two levels:
    - L1: clusters raw symbols (functions/classes) by semantic + graph proximity.
    - L2: clusters L1 cluster summaries into broader subsystems.

    Provides retrieval of the most relevant cluster summaries for a query,
    with L2 summaries prioritised (broader context first).
    """

    _N_LANDMARKS: int = 8

    # ------------------------------------------------------------------
    # Region: Initialization
    # ------------------------------------------------------------------

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the RAPTOR index with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance.
        """
        self._f = filter_ref

    # ------------------------------------------------------------------
    # Region: Public API – Rebuild and Retrieve
    # ------------------------------------------------------------------

    async def rebuild(
        self,
        project_id: str,
        symbol_index: "SymbolIndex",
        edges_out: dict,
        n_clusters: int,
        summary_model: str,
        summary_max_tokens: int,
        chroma_collection,
        llm_caller,
        embedder,
        graph_weight: float = 0.5,
        stop_event: Optional[asyncio.Event] = None,
    ) -> None:
        """
        Full rebuild: build L1 (symbol clusters) and, if enough L1 clusters
        exist, L2 (clusters of L1 summaries). Uses upsert over stable ids —
        a failed rebuild leaves the prior set intact. After a successful
        build, prunes stale higher-numbered cluster ids.

        Args:
            project_id: Current project identifier.
            symbol_index: The SymbolIndex instance.
            edges_out: Call graph edges (outgoing).
            n_clusters: Number of clusters per level.
            summary_model: Model to use for cluster summaries.
            summary_max_tokens: Maximum tokens for each summary.
            chroma_collection: ChromaDB collection.
            llm_caller: Async function to call the LLM.
            embedder: Embedder instance.
            graph_weight: Weight for graph distance in clustering.
            stop_event: Optional event to signal early termination.
        """
        if stop_event and stop_event.is_set():
            return

        names = []
        try:
            names = list(symbol_index.get_all_names(project_id))
        except Exception:
            return
        if len(names) < max(2 * n_clusters, 4):
            return

        # ------------------------------------------------------------------
        # Build L1 from symbols.
        # ------------------------------------------------------------------
        n_l1 = await self.build_layer(
            project_id=project_id,
            level=1,
            symbol_index=symbol_index,
            edges_out=edges_out,
            n_clusters=n_clusters,
            summary_model=summary_model,
            summary_max_tokens=summary_max_tokens,
            chroma_collection=chroma_collection,
            llm_caller=llm_caller,
            embedder=embedder,
            graph_weight=graph_weight,
            stop_event=stop_event,
        )

        if stop_event and stop_event.is_set():
            return

        # ------------------------------------------------------------------
        # Build L2 from L1 summaries if enough L1 clusters exist.
        # ------------------------------------------------------------------
        if n_l1 >= 4:
            await self.build_layer(
                project_id=project_id,
                level=2,
                symbol_index=symbol_index,
                edges_out=edges_out,
                n_clusters=max(2, n_l1 // 3),
                summary_model=summary_model,
                summary_max_tokens=summary_max_tokens,
                chroma_collection=chroma_collection,
                llm_caller=llm_caller,
                embedder=embedder,
                graph_weight=graph_weight,
                stop_event=stop_event,
            )

        # ------------------------------------------------------------------
        # Prune stale cluster ids.
        # ------------------------------------------------------------------
        await self._prune_stale_clusters(
            project_id=project_id,
            level=1,
            kept_count=n_l1,
            chroma_collection=chroma_collection,
        )
        if n_l1 >= 4:
            await self._prune_stale_clusters(
                project_id=project_id,
                level=2,
                kept_count=max(2, n_l1 // 3),
                chroma_collection=chroma_collection,
            )

    # ------------------------------------------------------------------
    # Region: Public API – Rebuild and Retrieve
    # ------------------------------------------------------------------

    async def build_layer(
        self,
        project_id: str,
        level: int,
        symbol_index: "SymbolIndex",
        edges_out: dict,
        n_clusters: int,
        summary_model: str,
        summary_max_tokens: int,
        chroma_collection,
        llm_caller,
        embedder,
        graph_weight: float = 0.5,
        stop_event: Optional[asyncio.Event] = None,
    ) -> int:
        """
        Build one RAPTOR layer by clustering symbols (level 1) or prior-level
        summaries (level > 1), generating a natural-language summary per cluster,
        and storing the results in ChromaDB.

        Returns the number of clusters stored, or 0 when the layer is skipped
        (empty project, insufficient items to cluster, stop_event set).

        n_clusters is capped to len(names) before clustering. Without this cap,
        KMeans raises ValueError when the project has fewer symbols than the
        configured cluster count, which kills the background RAPTOR task
        permanently for that session.

        Steps:
            1.  Collect names for this level (symbols at L1, summary texts at L>1).
            2.  Cap n_clusters to len(names); exit when fewer than 2 items remain.
            3.  Compute embeddings with stop_event checks between batches.
            4.  Build graph-feature matrix from edge adjacency.
            5.  Cluster with KMeans using combined embedding + graph distance.
            6.  For each cluster: summarise members and store in ChromaDB.
            7.  Prune stale clusters from prior builds at this level.
            8.  Return cluster count.
        """
        if stop_event and stop_event.is_set():
            return 0

        # -- Step 1: collect names --
        if level == 1:
            names: List[str] = list(symbol_index.get_all_qualified_names(project_id))
            member_texts: List[str] = [
                (symbol_index.get_signature(n, project_id) or n)
                + (
                    f": {symbol_index.get_docstring(n, project_id)}"
                    if symbol_index.get_docstring(n, project_id)
                    else ""
                )
                for n in names
            ]
        else:
            prev_summaries = await self._load_level_summaries(
                project_id, level - 1, chroma_collection
            )
            if not prev_summaries:
                return 0
            names = [
                s.get("id", f"L{level-1}_c{i}") for i, s in enumerate(prev_summaries)
            ]
            member_texts = [s.get("text", "") for s in prev_summaries]

        if not names:
            self._f._log_debug(
                f"RAPTOR build_layer: no items for project '{project_id}' "
                f"level {level}, skipping"
            )
            return 0

        # -- Step 2: cap n_clusters --
        original_n = n_clusters
        n_clusters = min(n_clusters, len(names))
        if n_clusters != original_n:
            self._f._log_debug(
                f"RAPTOR build_layer: capped n_clusters {original_n}→{n_clusters} "
                f"(only {len(names)} item(s) available)"
            )

        if n_clusters < 2:
            self._f._log_debug(
                f"RAPTOR build_layer: {len(names)} item(s) — fewer than 2 required "
                f"for clustering, skipping level {level}"
            )
            return 0

        if stop_event and stop_event.is_set():
            return 0

        # -- Step 3: compute embeddings --
        try:
            embeddings = await anyio.to_thread.run_sync(
                lambda: embedder.encode(member_texts, show_progress_bar=False)
            )
        except Exception as e:
            self._f._log_debug(
                f"RAPTOR build_layer: embedding failed for level {level}: {e}"
            )
            return 0

        if stop_event and stop_event.is_set():
            return 0

        # -- Step 4: build graph features --
        try:
            graph_features = self._build_graph_features(names, edges_out)
        except Exception:
            graph_features = None

        # -- Step 5: cluster --
        try:
            import numpy as np
            from sklearn.cluster import KMeans
            from sklearn.preprocessing import normalize

            emb_matrix = np.array(embeddings, dtype=np.float32)
            emb_norm = normalize(emb_matrix)

            if graph_features is not None and graph_weight > 0.0:
                gf_norm = normalize(np.array(graph_features, dtype=np.float32))
                combined = (1.0 - graph_weight) * emb_norm + graph_weight * gf_norm
            else:
                combined = emb_norm

            km = KMeans(n_clusters=n_clusters, n_init=10, random_state=42)
            labels = km.fit_predict(combined)

        except Exception as e:
            self._f._log_debug(
                f"RAPTOR build_layer: clustering failed level {level}: "
                f"{type(e).__name__}: {e}"
            )
            return 0

        # -- Step 6: summarise and store --
        stored = 0
        clusters: Dict[int, List[int]] = {}
        for idx, label in enumerate(labels):
            clusters.setdefault(int(label), []).append(idx)

        for cluster_id, member_indices in clusters.items():
            if stop_event and stop_event.is_set():
                break

            cluster_texts = [member_texts[i] for i in member_indices]
            cluster_names = [names[i] for i in member_indices]

            try:
                summary = await self._summarise_cluster(
                    cluster_texts, level, summary_model, summary_max_tokens, llm_caller
                )
            except Exception as e:
                self._f._log_debug(
                    f"RAPTOR build_layer: summarise failed for cluster "
                    f"{cluster_id} level {level}: {e}"
                )
                continue

            ok = await self._store_summary(
                project_id,
                level,
                cluster_id,
                summary,
                cluster_names,
                chroma_collection,
                embedder,
            )
            if ok:
                stored += 1

        # -- Step 7: prune stale clusters --
        if stored > 0:
            await self._prune_stale_clusters(
                project_id, level, stored, chroma_collection
            )

        self._f._log_debug(
            f"RAPTOR build_layer: level {level} complete — "
            f"{stored}/{n_clusters} cluster(s) stored for '{project_id}'"
        )
        return stored

    async def retrieve(
        self,
        query: str,
        project_id: str,
        top_k: int,
        embedder,
        chroma_collection,
    ) -> list:
        """
        Retrieve the top_k most relevant RAPTOR cluster summaries for a query.

        Queries all built RAPTOR levels and merges results by distance before
        returning the top_k summaries as plain strings. Returns [] on any
        infrastructure error or when the index is empty.

        ChromaDB query() returns nested lists even when empty:
            {"documents": [[]], "distances": [[]]}
        Accessing [0] on an empty inner list raises IndexError. Every result
        field is therefore guarded with (field or [[]])[0] before use.

        Steps:
            1.  Embed the query; return [] on failure.
            2.  For each RAPTOR level up to raptor_max_levels: query ChromaDB,
                guard against empty/missing result fields, collect (doc, dist) pairs.
            3.  Sort all collected results by distance and return the top_k docs.
        """
        if not chroma_collection:
            return []

        # -- Step 1: embed query --
        try:
            query_emb = await anyio.to_thread.run_sync(
                lambda: embedder.encode([query], show_progress_bar=False)[0].tolist()
            )
        except Exception as e:
            self._f._log_debug(f"RAPTOR retrieve: embedding failed: {e}")
            return []

        # -- Step 2: query each level --
        max_levels = getattr(self._f.valves, "raptor_max_levels", 3)
        all_results: List[Tuple[str, float]] = []

        for level in range(1, max_levels + 1):
            try:
                raw = await anyio.to_thread.run_sync(
                    lambda lvl=level: chroma_collection.query(
                        query_embeddings=[query_emb],
                        n_results=top_k,
                        where={
                            "$and": [
                                {"project_id": {"$eq": project_id}},
                                {"raptor_level": {"$eq": lvl}},
                            ]
                        },
                        include=["documents", "distances"],
                    )
                )
            except Exception as e:
                self._f._log_debug(
                    f"RAPTOR retrieve: ChromaDB query failed level {level}: "
                    f"{type(e).__name__}: {e}"
                )
                continue

            # Guard against empty/missing result fields before indexing.
            docs = (raw.get("documents") or [[]])[0]
            distances = (raw.get("distances") or [[]])[0]

            if not docs:
                continue

            for doc, dist in zip(docs, distances):
                if doc and isinstance(doc, str):
                    all_results.append((doc, float(dist)))

        if not all_results:
            return []

        # -- Step 3: merge and return top_k --
        all_results.sort(key=lambda x: x[1])
        return [doc for doc, _ in all_results[:top_k]]

    # ------------------------------------------------------------------
    # Region: Graph & Distance Helpers (for clustering)
    # ------------------------------------------------------------------

    def _build_adjacency(self, edges_out: dict) -> dict:
        """
        Build an undirected adjacency dict from the directed call graph.

        Args:
            edges_out: {src_name: [Edge(dst=..., type=...), ...]}

        Returns:
            {name: set(neighbour_names)} undirected.
        """
        adj: dict = {}
        for src, edge_list in edges_out.items():
            adj.setdefault(src, set())
            for edge in edge_list:
                dst = getattr(edge, "dst", None) or getattr(edge, "target", None)
                if dst is None:
                    continue
                adj[src].add(dst)
                adj.setdefault(dst, set()).add(src)
        return adj

    def _bfs_from(self, start: str, adj: dict, max_depth: int = 3) -> dict:
        """
        BFS from `start` up to `max_depth` hops.

        Args:
            start: Starting node.
            adj: Undirected adjacency dict.
            max_depth: Maximum depth to traverse.

        Returns:
            {name: depth} for all reachable nodes within max_depth.
        """
        from collections import deque

        visited = {start: 0}
        queue = deque([(start, 0)])
        while queue:
            node, depth = queue.popleft()
            if depth >= max_depth:
                continue
            for nb in adj.get(node, ()):
                if nb not in visited:
                    visited[nb] = depth + 1
                    queue.append((nb, depth + 1))
        return visited

    def _graph_distance(
        self,
        sym_a: str,
        sym_b: str,
        adj: dict,
        max_depth: int = 3,
    ) -> float:
        """
        Normalised call-graph distance in [0, 1].

        0.0 = same symbol or direct call.
        1.0 = unreachable within max_depth.

        Args:
            sym_a: First symbol.
            sym_b: Second symbol.
            adj: Undirected adjacency dict.
            max_depth: Maximum depth to consider.

        Returns:
            Normalised distance.
        """
        if sym_a == sym_b:
            return 0.0

        from collections import deque

        visited = {sym_a}
        queue = deque([(sym_a, 0)])
        while queue:
            node, depth = queue.popleft()
            if depth >= max_depth:
                continue
            for nb in adj.get(node, ()):
                if nb == sym_b:
                    return (depth + 1) / (max_depth + 1)
                if nb not in visited:
                    visited.add(nb)
                    queue.append((nb, depth + 1))
        return 1.0

    def _combined_distance(
        self,
        emb_a,
        emb_b,
        sym_a: str,
        sym_b: str,
        edges_out: dict,
        graph_weight: float,
    ) -> float:
        """
        Combined clustering metric (used for validation).

        combined = (1 - graph_weight) * cosine_distance + graph_weight * graph_distance
        Lower = more similar.

        Args:
            emb_a: Embedding of symbol A.
            emb_b: Embedding of symbol B.
            sym_a: Name of symbol A.
            sym_b: Name of symbol B.
            edges_out: Call graph edges.
            graph_weight: Weight for graph distance.

        Returns:
            Combined distance.
        """
        import numpy as np

        a = np.asarray(emb_a, dtype=np.float32)
        b = np.asarray(emb_b, dtype=np.float32)
        cosine_dist = 1.0 - float(
            np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b) + 1e-8)
        )
        adj = self._build_adjacency(edges_out)
        graph_dist = self._graph_distance(sym_a, sym_b, adj, max_depth=3)
        return (1.0 - graph_weight) * cosine_dist + graph_weight * graph_dist

    def _build_graph_features(self, names: list, edges_out: dict):
        """
        Build a graph-position feature matrix.

        For each symbol, its (inverse) BFS distance to each of N landmark hub symbols.
        Landmarks are the symbols with the highest out+in degree.

        Args:
            names: List of symbol names.
            edges_out: Call graph edges.

        Returns:
            (len(names) x N_LANDMARKS) float32 matrix.
        """
        import numpy as np

        if not names:
            return np.zeros((0, self._N_LANDMARKS), dtype=np.float32)

        # ------------------------------------------------------------------
        # Degree (out + in) for landmark selection.
        # ------------------------------------------------------------------
        out_deg = {n: len(edges_out.get(n, [])) for n in names}
        in_deg = {n: 0 for n in names}
        for src, elist in edges_out.items():
            for e in elist:
                tgt = getattr(e, "dst", None) or getattr(e, "target", None)
                if tgt in in_deg:
                    in_deg[tgt] += 1
        degree = {n: out_deg.get(n, 0) + in_deg.get(n, 0) for n in names}

        landmarks = sorted(names, key=lambda n: -degree[n])[: self._N_LANDMARKS]
        while len(landmarks) < self._N_LANDMARKS and landmarks:
            landmarks.append(landmarks[-1])

        # ------------------------------------------------------------------
        # Build adjacency once for all BFS calls.
        # ------------------------------------------------------------------
        adj = self._build_adjacency(edges_out)

        # ------------------------------------------------------------------
        # Per-landmark BFS -> closeness features.
        # ------------------------------------------------------------------
        feats = np.zeros((len(names), self._N_LANDMARKS), dtype=np.float32)
        max_depth = 3
        for j, lm in enumerate(landmarks):
            bfs_result = self._bfs_from(lm, adj, max_depth=max_depth)
            for i, n in enumerate(names):
                if n in bfs_result:
                    d = bfs_result[n]
                    feats[i, j] = 1.0 - (d / (max_depth + 1))
        return feats

    # ------------------------------------------------------------------
    # Region: Summary Generation & Storage (LLM + ChromaDB)
    # ------------------------------------------------------------------

    async def _summarise_cluster(
        self,
        member_texts: list,
        level: int,
        summary_model: str,
        summary_max_tokens: int,
        llm_caller,
    ) -> str:
        """
        Generate an LLM summary describing the cluster's shared responsibility.

        Args:
            member_texts: List of member texts (signatures or summaries).
            level: Cluster level (1 or 2).
            summary_model: Model to use.
            summary_max_tokens: Maximum tokens for the summary.
            llm_caller: Async LLM caller function.

        Returns:
            The generated summary string, or empty string on failure.
        """
        if not member_texts:
            return ""

        listing = "\n".join(f"- {t}" for t in member_texts[:30])

        # ------------------------------------------------------------------
        # Build level-specific prompt.
        # ------------------------------------------------------------------
        if level == 1:
            prompt = (
                f"These {len(member_texts)} functions/classes are closely "
                f"related in a codebase:\n{listing}\n\n"
                f"In 2-3 sentences, describe the subsystem they form and its "
                f"single responsibility. Be specific and concise."
            )
        else:
            prompt = (
                f"These {len(member_texts)} subsystem summaries belong to one "
                f"larger module:\n{listing}\n\n"
                f"In 2-3 sentences, describe the module's overall purpose."
            )

        # ------------------------------------------------------------------
        # Call the LLM.
        # ------------------------------------------------------------------
        try:
            return (
                await llm_caller(
                    prompt,
                    system_prompt="You are a code summarisation assistant. Output only the summary.",
                    model_override=summary_model,
                    max_tokens=summary_max_tokens,
                    temperature=0.2,
                )
            ).strip()
        except Exception:
            return ""

    async def _store_summary(
        self,
        project_id: str,
        level: int,
        cluster_id: int,
        summary: str,
        member_names: list,
        chroma_collection,
        embedder,
    ) -> bool:
        """
        Upsert one cluster summary into ChromaDB.

        Args:
            project_id: Current project identifier.
            level: Cluster level (1 or 2).
            cluster_id: Cluster identifier.
            summary: Summary text.
            member_names: Names of members in the cluster.
            chroma_collection: ChromaDB collection.
            embedder: Embedder instance.

        Returns:
            True if stored successfully, False otherwise.
        """
        entry_id = f"{project_id}_raptor_L{level}_C{cluster_id}"
        metadata = {
            "project_id": project_id,
            "is_raptor_summary": True,
            "raptor_level": level,
            "level_tag": f"L{level}",
            "cluster_id": int(cluster_id),
            "member_count": len(member_names),
            "member_names": ",".join(member_names[:50]),
            "created_at": time.time(),
        }

        # ------------------------------------------------------------------
        # Embed and upsert using the shared ChromaDB semaphore.
        # ------------------------------------------------------------------
        try:
            async with self._f._chroma_semaphore:
                emb = await anyio.to_thread.run_sync(
                    lambda: embedder.encode(summary).tolist()
                )
                await anyio.to_thread.run_sync(
                    lambda: chroma_collection.upsert(
                        ids=[entry_id],
                        embeddings=[emb],
                        documents=[summary],
                        metadatas=[metadata],
                    )
                )
            return True
        except Exception:
            return False

    async def _load_level_summaries(
        self, project_id: str, level: int, chroma_collection
    ) -> list:
        """
        Read back stored summaries for a given level.

        Args:
            project_id: Current project identifier.
            level: Cluster level (1 or 2).
            chroma_collection: ChromaDB collection.

        Returns:
            List of {"id": str, "text": str} for the level.
        """
        try:
            res = await anyio.to_thread.run_sync(
                lambda: chroma_collection.get(
                    where={
                        "$and": [
                            {"project_id": project_id},
                            {"is_raptor_summary": True},
                            {"level_tag": f"L{level}"},
                        ]
                    },
                    include=["documents"],
                )
            )
        except Exception:
            return []
        ids = res.get("ids") or []
        docs = res.get("documents") or []
        return [{"id": i, "text": d} for i, d in zip(ids, docs)]

    async def _prune_stale_clusters(
        self,
        project_id: str,
        level: int,
        kept_count: int,
        chroma_collection,
    ) -> None:
        """
        Remove cluster ids >= kept_count for the given level.

        Called after a successful build so the prior set stays intact on failure.

        Args:
            project_id: Current project identifier.
            level: Cluster level (1 or 2).
            kept_count: Number of clusters to keep.
            chroma_collection: ChromaDB collection.
        """
        if chroma_collection is None:
            return

        # ------------------------------------------------------------------
        # Read all current ids for this level.
        # ------------------------------------------------------------------
        try:
            res = await anyio.to_thread.run_sync(
                lambda: chroma_collection.get(
                    where={
                        "$and": [
                            {"project_id": project_id},
                            {"is_raptor_summary": True},
                            {"level_tag": f"L{level}"},
                        ]
                    },
                    include=["ids"],
                )
            )
            current_ids = res.get("ids") or []
        except Exception:
            return

        # ------------------------------------------------------------------
        # Identify stale clusters (id >= kept_count).
        # ------------------------------------------------------------------
        stale = []
        for id_ in current_ids:
            parts = id_.split("_C")
            if len(parts) == 2:
                try:
                    cid = int(parts[1])
                    if cid >= kept_count:
                        stale.append(id_)
                except ValueError:
                    pass

        # ------------------------------------------------------------------
        # Delete stale clusters.
        # ------------------------------------------------------------------
        if stale:
            try:
                await anyio.to_thread.run_sync(
                    lambda: chroma_collection.delete(ids=stale)
                )
            except Exception:
                pass

    # ------------------------------------------------------------------
    # Region: Utilities
    # ------------------------------------------------------------------

    @staticmethod
    def _safe(fn, *args, default=None):
        """
        Call fn(*args), returning default on any exception.

        Args:
            fn: Function to call.
            *args: Arguments to pass.
            default: Default value to return on exception.

        Returns:
            The function result, or default on exception.
        """
        try:
            result = fn(*args)
            return result if result is not None else default
        except Exception:
            return default


class ContextBuilder:
    """
    Builds Block A + Block B, owns KV slot lifecycle, and provides skeleton
    and inventory utilities for the system prompt.

    Block A is the static, KV‑cache‑anchoring part (hub symbols, architecture
    map, guidelines, feedback context).  Block B is the dynamic, per‑query
    part (LOD‑activated code, LTM, use‑case‑tuned policies).

    Also handles:
    * Skeleton tier (stable signatures) inside Block A.
    * Scaffolding / skeleton responses for intent queries.
    * Chain‑of‑Thought (CoT) expand resolution.
    * Slot persistence (save / restore of KV cache state).
    * Use case classification with cascade (Heuristic → CE → LLM).
    * LOD-3 semantic relevance filtering with cascade.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """Initialize the ContextBuilder with a reference to the parent Filter."""
        self._f = filter_ref

        # Fast-path trigger for inventory / structural queries.
        self._LIST_INTENTS = re.compile(
            r"\b(?:dame\s+la\s+)?lista\s*(?:de\s+)?(?:clases|funciones)|"
            r"lístame|listame|enumera|inventario|"
            r"todas las (clases|funciones)|qué (clases|funciones)|"
            r"estructura del código|overview|list all|all (classes|functions)|"
            r"muestra las clases|show classes|list classes",
            re.IGNORECASE,
        )
        # Fast-path for skeleton/scaffolding queries.
        self._SKELETON_INTENTS = re.compile(
            r"\b(esqueleto|skeleton|stubs?|scaffold(ing)?|"
            r"(solo|sólo)\s+firmas|signatures?\s+only|"
            r"plantilla\s+de\s+(clases|c[oó]digo))\b"
            r"|estructura[^.\n]{0,40}(completar|rellenar|esqueleto|stub)",
            re.IGNORECASE,
        )
        # Filtered skeleton: "esqueleto de ClassName" / "skeleton of FuncName".
        self._SKELETON_SYMBOL_RE = re.compile(
            r"\b(?:esqueleto|skeleton|stub|scaffolding?)\s+"
            r"(?:de|of|para|for)?\s*`?(?P<sym>[A-Za-z_]\w*)`?",
            re.IGNORECASE,
        )

        # ── LOD policy per use case ──
        self.LOD_PROFILES: Dict[str, dict] = {
            "A": {
                "lod1_mult": 1.0,
                "lod2_mult": 1.4,
                "lod3_mult": 2.5,
                "activation_direction": "both",
            },
            "B": {
                "lod1_mult": 1.0,
                "lod2_mult": 1.0,
                "lod3_mult": 1.2,
                "activation_direction": "callees",
            },
            "C": {
                "lod1_mult": 1.0,
                "lod2_mult": 1.0,
                "lod3_mult": 1.0,
                "activation_direction": "callees",
            },
            "D": {
                "lod1_mult": 1.0,
                "lod2_mult": 1.0,
                "lod3_mult": 1.0,
                "activation_direction": "callers",
            },
            "E": {
                "lod1_mult": 1.0,
                "lod2_mult": 2.0,
                "lod3_mult": 4.0,
                "activation_direction": "callees",
            },
        }
        # Use-case detection. Refactor (D) is tested BEFORE architecture (A).
        self._UC_COMMAND_RE = re.compile(
            r"^\s*/(arch|plan|code|refactor|scaffold)\b", re.IGNORECASE
        )
        self._UC_SCAFFOLD_RE = re.compile(
            r"\b(esqueleto|skeleton|stubs?|scaffold(?:ing)?|solo\s+firmas|"
            r"signatures?\s+only|boilerplate|plantilla\s+de\s+(?:clase|c[oó]digo))\b",
            re.IGNORECASE,
        )
        self._UC_REFACTOR_RE = re.compile(
            r"\brefactor\w*|"
            r"\brenombr\w*|\brename\w*|"
            r"extrae\s+la\s+(?:validaci[oó]n|l[oó]gica)|"
            r"extrae\s+(?:el\s+)?(?:m[eé]todo|funci[oó]n)|"
            r"extract\s+(?:a\s+)?(?:method|function)|"
            r"mueve\s+\w+\s+a|move\s+\w+\s+to|\binline\b|deduplic\w*|"
            r"reorganiz\w*|restructur\w*|"
            r"split\s+(?:this|the|el|la)\b|"
            r"an[aá]lisis\s+de\s+impacto|"
            r"nueva\s+estructura|"
            r"demasiado\s+larg[oa]|"
            r"limpiar\s+(?:el\s+)?(?:m[eé]todo|c[oó]digo)|"
            r"separar\s+responsabilidades",
            re.IGNORECASE,
        )
        self._UC_ARCH_RE = re.compile(
            r"\b(arquitectura|architecture|dise[ñn]o|design|"
            r"c[oó]mo\s+(?:estructurar|organizar|dividir)|"
            r"qu[eé]\s+(?:clases|m[oó]dulos|componentes)\s+"
            r"(?:necesito|crear|a[ñn]adir)|"
            r"abstract\s+(?:base\s+)?class|interface\s+design|"
            r"propuesta\s+de\s+dise[ñn]o|API\s+surface)\b",
            re.IGNORECASE,
        )
        self._UC_PLAN_RE = re.compile(
            r"\b(plan\s+de\s+(?:implementaci[oó]n|cambios)|implementation\s+plan|"
            r"pasos\s+para|steps\s+to|roadmap|"
            r"c[oó]mo\s+implementar|how\s+to\s+implement)\b",
            re.IGNORECASE,
        )

    # ======================================================================
    # B4 – warmup stub
    # ======================================================================

    async def _warmup_tier_prefill(self, project_id: str) -> None:
        """
        Phase‑2 placeholder: pre‑warms the stable tier prefix into the KV slot
        immediately after silent ingestion, so the next inlet finds it hot.
        Currently a no‑op; full implementation deferred to Phase 2 (KV‑slot
        prediction).
        """
        pass

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Block A – static, KV‑cache‑anchoring content
    # ═══════════════════════════════════════════════════════════════════════

    async def build_block_a(
        self,
        project_id: str,
        is_code_session: bool,
        is_continuation: bool,
    ) -> str:
        """
        Build Block A: stable, KV-cache-anchoring content.

        Returns "" when not a code session.
        """
        if not is_code_session:
            return ""

        # --- 1. Resolve per-project state ---
        psm = self._f._project_state_manager
        # pstate_raw is kept for keys that have no typed accessor:
        # skeleton_render_mode, last_static_prefix_hash, hub_tier_qids_persisted.
        pstate_raw = psm.get_pstate(project_id)

        # -- E4: prune ghost hub qids -------------------------------------
        hub_qids: List[str] = pstate_raw.get("hub_tier_qids_persisted", [])
        if hub_qids:
            current_qids: Set[str] = set(
                self._f._symbol_index.get_all_qualified_names(project_id)
            )
            hub_set = set(hub_qids)
            ghost_qids = hub_set - current_qids
            if ghost_qids:
                deletion_ratio = len(ghost_qids) / max(len(hub_set), 1)
                if deletion_ratio > 0.30:
                    pruned = list(hub_set & current_qids)
                    self._f._log_debug(
                        f"Hub tier: pruned {len(ghost_qids)} ghost qids "
                        f"({deletion_ratio:.0%} deleted after large code "
                        f"change). Remaining: {len(pruned)}"
                    )
                    pstate_raw["hub_tier_qids_persisted"] = pruned

        # --- 2. Compute structure-only hash (stable across docstring enrichment) ---
        structure_hash = self._f._symbol_index.compute_structure_hash(project_id)
        if not structure_hash:
            structure_hash = hashlib.md5("no_symbols".encode()).hexdigest()[:16]
        psm.set_structure_hash_for_cache(project_id, structure_hash)

        # --- 3. Resolved call graph mode ---
        mode = psm.get_resolved_call_graph_mode(project_id) or "hubs_only"

        # --- 4. Build cache key using structure hash (not the rendered text) ---
        cache_key = f"{structure_hash}__{mode}"
        cached_text = psm.get_block_a_cached(project_id)
        stored_key = psm.get_block_a_cache_key(project_id)

        if stored_key and stored_key == cache_key and cached_text is not None:
            # --- 4a. Cache hit: same code + same mode ---
            return cached_text

        # --- 4b. Cache miss or continuation freeze ---
        if is_continuation and cached_text is not None:
            # Continuation: freeze Block A to prevent KV cache misses.
            self._f._log_debug("Block A: frozen for AutoContinue (KV cache stability)")
            return cached_text

        # --- 5. Build the static block ---
        parts: List[str] = []

        # 5.1 Base instructions (completely static)
        if is_code_session and self._f.valves.enable_confidence_scoring:
            parts.append(self._f.valves.confidence_prompt.strip())

        if is_code_session and self._f.valves.enable_code_awareness:
            checklist = (
                "## Code review checklist (apply when reviewing or fixing code):\n"
                "1. Execute mentally with 3 different inputs including edge cases.\n"
                "2. Identify every assumption and verify each one.\n"
                "3. Test every regex or string match against 5 counter-examples.\n"
                "4. Test collections with empty, single-element, and large inputs.\n"
                "5. Consider the worst-case scenario.\n"
                "6. Reason step by step, then provide the corrected code."
            )
            parts.append(checklist)

            critical_guidelines = (
                "## Critical reasoning guidelines\n"
                "- Before diagnosing a bug, verify if the observed behavior matches the "
                "expected behavior defined in the specification or codebase. "
                "Do not confuse expected behavior with a bug.\n"
                "- When you propose a fix, explicitly explain **why** the change resolves "
                "the root cause and how it prevents the issue from recurring.\n"
                "- When you propose a change (refactor, addition), explain **why** "
                "the change is needed: what problem it solves, what benefits it brings, "
                "and any trade-offs involved.\n"
                "- Avoid magic numbers; define named constants with meaningful names "
                "and derive them from a single source of truth whenever possible."
            )
            parts.append(critical_guidelines)

        # 5.2 Symbol index (depth depends on call_graph_context_mode)
        symbol_section_rendered = False
        if is_code_session and self._f.valves.enable_code_awareness:
            state = self._f._conversation_state_manager.get(project_id)
            if state and state.active_blocks:
                centrality = psm.get_node_centrality(project_id)
                resolved_mode = (
                    psm.get_resolved_call_graph_mode(project_id) or "hubs_only"
                )
                self._f._log_debug(
                    f"Building Block A symbol section with mode='{resolved_mode}' "
                    f"(project={project_id})"
                )
                symbol_section = self._f._hub_index.build(
                    symbol_index=self._f._symbol_index,
                    centrality=centrality,
                    project_id=project_id,
                    top_n=self._f.valves.symbol_index_max_in_block_a,
                    valves=self._f.valves,
                    mode=resolved_mode,
                )
                if symbol_section:
                    parts.append(symbol_section)
                    symbol_section_rendered = True

        # 5.3 Skeleton tier
        skeleton_rendered_this_turn = False
        if is_code_session and self._f.valves.enable_code_awareness:
            skeleton_tier = self._build_skeleton_tier(project_id)
            if skeleton_tier:
                parts.append(skeleton_tier)
                skeleton_rendered_this_turn = True

        # 5.4 Feedback context
        if (
            is_code_session
            and self._f.valves.enable_feedback_tracking
            and self._f.valves.inject_feedback_context
        ):
            feedback_ctx = self._f._enrichment.get_feedback_context(project_id)
            if feedback_ctx:
                parts.append(feedback_ctx)

        static_block = "\n\n".join(p for p in parts if p.strip())

        # --- 6. Store in cache with the mode-aware key (using structure hash) ---
        psm.set_block_a_cache_key(project_id, cache_key)
        psm.set_block_a_cached(project_id, static_block)

        # --- 7. Record whether skeleton was actually rendered this turn ---
        psm.set_skeleton_rendered_this_turn(project_id, skeleton_rendered_this_turn)
        pstate_raw["skeleton_render_mode"] = mode

        # --- 8. Detect and log prefix changes (KV cache miss) ---
        new_prefix_hash = structure_hash
        last_hash = pstate_raw.get("last_static_prefix_hash")
        if last_hash and last_hash != new_prefix_hash:
            self._f._log_debug(
                f"KV CACHE MISS detected: static block changed "
                f"({last_hash} -> {new_prefix_hash}). "
                f"llama.cpp will do a full prefill on this request."
            )
        elif not last_hash:
            self._f._log_debug(
                f"KV Cache: first request for project, "
                f"static prefix established ({new_prefix_hash})."
            )
        else:
            self._f._log_debug(
                f"KV Cache: static prefix stable ({new_prefix_hash}). "
                f"llama.cpp will reuse KV states for Block A."
            )
        pstate_raw["last_static_prefix_hash"] = new_prefix_hash

        tokens = (
            len(self._f.tokenizer.encode(static_block))
            if self._f.tokenizer
            else len(static_block) // 4
        )
        self._f._log_debug(f"Static Context Block: ~{tokens} tokens")

        return static_block

    def invalidate_block_a_cache(
        self, project_id: str, reason: str = "", recompute_centrality: bool = False
    ) -> None:
        """
        Force Block A rebuild on the next request, optionally refreshing
        centrality scores.
        """
        psm = self._f._project_state_manager
        psm.set_block_a_cache_key(project_id, None)
        psm.set_block_a_cached(project_id, None)

        raw = psm.get_pstate(project_id)
        raw["skeleton_tier_cache_key"] = None
        raw["skeleton_tier_cached"] = None

        if recompute_centrality:
            try:
                psm.set_node_centrality(
                    project_id,
                    self._f._symbol_index.precompute_centrality(project_id),
                )
            except Exception as e:
                self._f._log_debug(f"Centrality recomputation failed: {e}")

        if reason:
            self._f._log_debug(f"Block A + skeleton cache invalidated ({reason})")

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Skeleton tier (stable signatures inside Block A)
    # ═══════════════════════════════════════════════════════════════════════

    def _build_skeleton_tier(self, project_id: str) -> str:
        """
        Render the project skeleton (signatures only) as a STABLE context
        tier, cached by structure_hash so body edits and docstring additions
        do not invalidate it. Returns "" when disabled, empty, or over budget.
        """
        psm = self._f._project_state_manager

        if not self._f.valves.enable_skeleton_tier:
            psm.set_skeleton_tier_qids(project_id, [])
            return ""

        pstate = psm.get_pstate(project_id)

        structure_hash = self._f._symbol_index.compute_structure_hash(project_id)
        if not structure_hash:
            psm.set_skeleton_tier_qids(project_id, [])
            return ""

        cached_hash = pstate.get("skeleton_tier_cache_key")
        cached_tier = pstate.get("skeleton_tier_cached")
        if cached_hash and cached_hash == structure_hash and cached_tier is not None:
            rendered_qids = sorted(
                self._f._symbol_index.get_all_qualified_names(project_id)
            )
            psm.set_skeleton_tier_qids(project_id, rendered_qids)
            return cached_tier

        skel = self._format_skeleton(project_id)
        if not skel:
            pstate["skeleton_tier_cache_key"] = structure_hash
            pstate["skeleton_tier_cached"] = ""
            psm.set_skeleton_tier_qids(project_id, [])
            return ""

        budget = self._f.valves.skeleton_tier_max_tokens
        if budget > 0:
            tok = self._f._tokens.estimate_code_tokens(skel)
            if tok > budget:
                self._f._log_debug(
                    f"Skeleton tier skipped: {tok} tokens > budget "
                    f"{budget}. Block B keeps signatures inline."
                )
                pstate["skeleton_tier_cache_key"] = structure_hash
                pstate["skeleton_tier_cached"] = ""
                psm.set_skeleton_tier_qids(project_id, [])  # FIX Bug 4
                return ""

        tier = (
            "## Project Skeleton (stable — signatures only)\n"
            "_Contracts for the whole project. Bodies are shown on demand "
            "below or via `/expand <name>`._\n\n"
            f"{skel}"
        )

        pstate["skeleton_tier_cache_key"] = structure_hash
        pstate["skeleton_tier_cached"] = tier

        rendered_qids = sorted(
            self._f._symbol_index.get_all_qualified_names(project_id)
        )
        psm.set_skeleton_tier_qids(project_id, rendered_qids)

        self._f._log_debug(
            f"Skeleton tier rendered (structure_hash={structure_hash}, "
            f"~{self._f._tokens.estimate_code_tokens(tier)} tokens, "
            f"{len(rendered_qids)} qids registered)"
        )

        return tier

    def _build_hub_bodies_tier(self, project_id: str) -> Tuple[str, str, List[str]]:
        """
        Build the Hub‑Bodies Tier: full bodies of top‑N hubs by centrality,
        ordered by stability (last_modified_turn), truncated by budget.
        """
        if not self._f.valves.enable_hub_bodies_tier:
            return "", "", []

        psm = self._f._project_state_manager
        centrality = psm.get_node_centrality(project_id)
        if not centrality:
            return "", "", []

        state = self._f._conversation_state_manager.get(project_id)
        current_turn = state.message_count

        hub_seeds_this_turn = psm.get_hub_tier_seeds_this_turn(project_id)
        if hub_seeds_this_turn:
            prev_seeds = psm.get_hub_tier_prev_seeds(project_id)
        else:
            prev_seeds = list(
                psm.get_pstate(project_id).get("hub_tier_qids_persisted", [])
            )

        last_mod = state.hub_tier_last_modified
        body_hashes = state.hub_tier_body_hashes
        heat = state.hub_tier_query_heat

        ranked = self._f._symbol_index.get_hub_symbols(
            project_id, centrality, self._f.valves.hub_bodies_tier_top_n
        )
        floor = self._f.valves.hub_bodies_tier_min_centrality
        candidates = [qid for qid, c in ranked if (floor <= 0 or c >= floor)]

        resolved = {}
        for qid in candidates:
            body, lang = self._resolve_hub_body(qid, project_id, state)
            if not body:
                continue
            max_body = self._f.valves.hub_bodies_tier_max_body_tokens
            if max_body > 0 and self._f._tokens.estimate_code_tokens(body) > max_body:
                self._f._log_debug(f"Hub tier: skipping {qid} (body > {max_body} tok)")
                continue
            bh = hashlib.md5(body.encode()).hexdigest()[:16]
            if body_hashes.get(qid) != bh:
                last_mod[qid] = current_turn
            body_hashes[qid] = bh
            resolved[qid] = (body, bh, lang)

        if not resolved:
            return "", "", []

        alpha = 0.3
        for qid in candidates:
            was_seed = 1.0 if qid in prev_seeds else 0.0
            heat[qid] = alpha * was_seed + (1 - alpha) * heat.get(qid, 0.0)

        ordered = sorted(
            resolved,
            key=lambda q: (
                last_mod.get(q, current_turn),
                -heat.get(q, 0.0),
                q,
            ),
        )

        budget = self._f.valves.hub_bodies_tier_max_tokens
        if (
            self._f.valves.enable_multi_phase_response
            or self._f.valves.force_multi_phase_response
        ):
            budget = min(budget, 6000)
            self._f._log_debug(f"Hub tier: budget capped to 6000 (multi‑phase active)")

        lines = [
            "## Core Implementation (hub symbols — stable, cached)",
            "_Full bodies of the most central symbols, ordered from most to least stable. "
            "They rarely change and are anchored here for KV cache reuse._",
            "",
        ]
        total = self._f._tokens.estimate_code_tokens("\n".join(lines))
        kept = []
        excluded_by_cap = []

        for qid in ordered:
            body, bh, lang = resolved[qid]
            meta = self._f._symbol_index.get_symbol_meta(qid, project_id) or {}
            doc = meta.get("docstring", "")
            doc_line = f"_{doc}_\n" if doc else ""

            kept_set = set(kept)
            body_with_xrefs = self._inject_tier_xrefs(body, qid, kept_set | set([qid]))

            chunk = f"### `{qid}`\n{doc_line}```{lang}\n{body_with_xrefs}\n```\n"
            tok = self._f._tokens.estimate_code_tokens(chunk)
            if budget > 0 and total + tok > budget:
                excluded_by_cap.extend(ordered[ordered.index(qid) :])
                break
            lines.append(chunk)
            kept.append(qid)
            total += tok

        if excluded_by_cap:
            self._f._log_debug(
                f"Hub tier: {len(excluded_by_cap)} hub(s) excluded by budget cap "
                f"→ will be served via LoD: {excluded_by_cap}"
            )

        if not kept:
            return "", "", []

        tier_text = "\n".join(lines)

        config_prefix = (
            f"n={self._f.valves.hub_bodies_tier_top_n}|"
            f"floor={self._f.valves.hub_bodies_tier_min_centrality}"
        )
        tier_hash = hashlib.md5(
            f"{config_prefix}|"
            + "|".join(f"{q}:{resolved[q][1]}" for q in kept).encode()
        ).hexdigest()[:16]

        live = set(candidates)
        for d in (last_mod, body_hashes, heat):
            for stale in [k for k in list(d.keys()) if k not in live]:
                del d[stale]

        state.hub_tier_qids_persisted = kept
        self._f._conversation_state_manager.set(project_id, state)

        previous_tier_hash = psm.get_pstate(project_id).get("last_tier_hash")
        if previous_tier_hash and previous_tier_hash != tier_hash:
            self._f._log_debug(
                f"⚠️ TIER CACHE MISS: tier_hash changed "
                f"({previous_tier_hash} → {tier_hash}). "
                f"Hub bodies will be re-prefilled."
            )
        elif not previous_tier_hash:
            self._f._log_debug(f"TIER CACHE: first tier built ({tier_hash})")
        else:
            self._f._log_debug(f"✓ TIER CACHE HIT: tier_hash stable ({tier_hash})")

        psm.set_hub_tier_prev_seeds(project_id, hub_seeds_this_turn or prev_seeds)

        return tier_text, tier_hash, kept

    def _resolve_hub_body(
        self, qid: str, project_id: str, state: "ConversationState"
    ) -> Tuple[str, str]:
        """
        Deterministically resolve the full body of a symbol.

        Returns (body, language). Returns ('', 'python') if not found.
        """
        candidates = []
        for bh in self._f._symbol_index.find_blocks(qid, project_id):
            block = state.active_blocks.get(bh)
            if block and not block.obsolete:
                body = CodeBlockManager.extract_symbol_body(block, qid)
                if body:
                    candidates.append((block.timestamp, body, block))
        if not candidates:
            return "", "python"
        candidates.sort(key=lambda x: x[0], reverse=True)
        _, body, block = candidates[0]
        lang = block.symbols[0].language if block.symbols else "python"
        return body, lang

    def _inject_tier_xrefs(self, body: str, qid: str, kept_set: Set[str]) -> str:
        """Add inline comments where this symbol calls another hub in the tier."""
        lines = body.split("\n")
        result = []
        for line in lines:
            result.append(line)
            for other_qid in kept_set:
                if other_qid == qid:
                    continue
                bare = other_qid.rsplit(".", 1)[-1]
                if (
                    f"{bare}(" in line
                    or f"self.{bare}(" in line
                    or f"->{bare}(" in line
                ):
                    result.append(f"    # ↑ see `{other_qid}` in this tier")
                    break
        return "\n".join(result)

    def _build_hub_recency_pointers(
        self,
        project_id: str,
        current_block_b_qids: Set[str],
    ) -> str:
        """
        Build the recency pointer section for Block B.

        E6: includes a one‑line signature preview for symbols NOT in Block B.
        Symbols that ARE in Block B are marked as active this turn.
        """
        if not self._f.valves.hub_bodies_tier_recency_pointers:
            return ""

        prev_seeds = self._f._project_state_manager.get_hub_tier_prev_seeds(project_id)
        if not prev_seeds:
            return ""

        in_ctx = [q for q in prev_seeds if q in current_block_b_qids]
        out_of_ctx = [q for q in prev_seeds if q not in current_block_b_qids]

        lines = ["**Recently Active Symbols** (recency pointers):"]

        for qid in in_ctx:
            lines.append(f"  · `{qid}`  ← active this turn (full body in Block B)")

        for qid in out_of_ctx[:3]:
            meta = self._f._symbol_index.get_symbol_meta(qid, project_id) or {}
            sig = meta.get("signature", qid)
            lines.append(f"  · `{sig}`  # signature preview (not in Block B this turn)")

        if len(out_of_ctx) > 3:
            lines.append(
                f"  · … and {len(out_of_ctx) - 3} more (not in context this turn)"
            )

        return "\n".join(lines) if len(lines) > 1 else ""

    @staticmethod
    def _build_instruction_tail(use_case: str = "C") -> str:
        """M2: instruction tail adapted to the active use case."""
        tails = {
            "A": "_[Architecture mode: focus on contracts, interfaces, and invariants. "
            "Reasoning guidelines from system above apply.]_",
            "D": "_[Refactor mode: identify all callers before proposing changes. "
            "Code review checklist from system above applies.]_",
            "E": "_[Scaffold mode: signatures only, no implementation. "
            "Guidelines from system above apply.]_",
        }
        default = (
            "_[Reasoning mode: code review checklist + critical reasoning "
            "guidelines from system above apply to this response]_"
        )
        return tails.get(use_case, default)

    def _is_skeleton_tier_active(self, project_id: str) -> bool:
        """True only if the skeleton tier was actually rendered into Block A THIS turn."""
        if not self._f.valves.enable_skeleton_tier:
            return False
        return self._f._project_state_manager.get_skeleton_rendered_this_turn(
            project_id
        )

    # ═══════════════════════════════════════════════════════════════════════
    # 2.1 — Project skeleton rendering (signatures only)
    # ═══════════════════════════════════════════════════════════════════════

    def _format_skeleton(self, project_id: str) -> str:
        """Render the project skeleton: signatures of all indexed symbols."""
        symbol_index = self._f._symbol_index
        qids = sorted(symbol_index.get_all_qualified_names(project_id))
        if not qids:
            return ""

        lines: List[str] = []
        include_docstrings = self._f.valves.skeleton_include_docstrings

        classes = sorted(symbol_index.get_classes(project_id))
        if classes:
            lines.append("## Classes")
            for cls_name in classes:
                members = symbol_index.get_class_members(cls_name, project_id)
                if not members:
                    continue
                lines.append(f"class {cls_name}:")
                for member_qid in members:
                    meta = symbol_index.get_symbol_meta(member_qid, project_id) or {}
                    sig = meta.get("signature", member_qid)
                    if include_docstrings:
                        docstring = meta.get("docstring", "")
                        if docstring:
                            first_line = docstring.split("\n")[0]
                            lines.append(f"    {sig}  # {first_line}")
                        else:
                            lines.append(f"    {sig}")
                    else:
                        lines.append(f"    {sig}")

        module_funcs = [
            qid
            for qid in qids
            if "." not in qid
            and (symbol_index.get_symbol_meta(qid, project_id) or {}).get("kind")
            == "function"
        ]
        if module_funcs:
            if lines:
                lines.append("")
            lines.append("## Module-level functions")
            for qid in module_funcs:
                meta = symbol_index.get_symbol_meta(qid, project_id) or {}
                sig = meta.get("signature", qid)
                if include_docstrings:
                    docstring = meta.get("docstring", "")
                    if docstring:
                        first_line = docstring.split("\n")[0]
                        lines.append(f"- `{sig}`  # {first_line}")
                    else:
                        lines.append(f"- `{sig}`")
                else:
                    lines.append(f"- `{sig}`")

        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════
    # 2.2 — Filtered skeleton for a single symbol
    # ═══════════════════════════════════════════════════════════════════════

    async def _format_skeleton_for_symbol(
        self, symbol_name: str, project_id: str, query: str
    ) -> str:
        """Render a filtered skeleton for a single symbol and its direct neighbors."""
        symbol_index = self._f._symbol_index
        qids = symbol_index.get_qualified_names_for(symbol_name, project_id)
        if not qids:
            return ""

        target_qid = sorted(qids)[0]
        meta = symbol_index.get_symbol_meta(target_qid, project_id) or {}
        sig = meta.get("signature", target_qid)
        doc = meta.get("docstring", "")

        lines = [
            f"## Skeleton for `{target_qid}`",
            f"```\n{sig}\n```",
        ]
        if doc and self._f.valves.skeleton_include_docstrings:
            lines.append(f"# {doc.split(chr(10))[0]}")

        bare = meta.get("name", target_qid.rsplit(".", 1)[-1])
        callers = set()
        for edge in symbol_index.get_edges_in(bare, project_id):
            callers.add(edge.src)
        if callers:
            lines.append("\n### Callers")
            for c in sorted(callers)[:10]:
                cm = symbol_index.get_symbol_meta(c, project_id) or {}
                csig = cm.get("signature", c)
                lines.append(f"- `{csig}`")

        callees = set()
        for edge in symbol_index.get_edges_out(target_qid, project_id):
            callees.add(edge.dst)
        if callees:
            lines.append("\n### Callees")
            for c in sorted(callees)[:10]:
                q = symbol_index.get_qualified_names_for(c, project_id)
                if q:
                    qid = sorted(q)[0]
                    cm = symbol_index.get_symbol_meta(qid, project_id) or {}
                    csig = cm.get("signature", c)
                else:
                    csig = c
                lines.append(f"- `{csig}`")

        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════
    # 2.3 — Full symbol inventory
    # ═══════════════════════════════════════════════════════════════════════

    async def _format_full_symbol_inventory(
        self, all_qids: List[str], project_id: str
    ) -> str:
        """Render a complete inventory of all symbols in the project."""
        if not all_qids:
            return ""

        symbol_index = self._f._symbol_index
        lines = ["## Code Inventory (all symbols)"]

        classes = sorted(symbol_index.get_classes(project_id))
        if classes:
            lines.append("\n### Classes")
            for cls in classes:
                members = symbol_index.get_class_members(cls, project_id)
                if not members:
                    continue
                lines.append(f"- **{cls}** ({len(members)} methods)")
                for m in members[:20]:
                    meta = symbol_index.get_symbol_meta(m, project_id) or {}
                    sig = meta.get("signature", m)
                    lines.append(f"    - `{sig}`")
                if len(members) > 20:
                    lines.append(f"    - ... and {len(members)-20} more")

        module_funcs = [
            qid
            for qid in all_qids
            if "." not in qid
            and (symbol_index.get_symbol_meta(qid, project_id) or {}).get("kind")
            == "function"
        ]
        if module_funcs:
            lines.append("\n### Module‑level functions")
            for qid in module_funcs[:50]:
                meta = symbol_index.get_symbol_meta(qid, project_id) or {}
                sig = meta.get("signature", qid)
                lines.append(f"- `{sig}`")
            if len(module_funcs) > 50:
                lines.append(f"- ... and {len(module_funcs)-50} more")

        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════
    # 2.4 — Skeleton for CoT (architecture reasoning context)
    # ═══════════════════════════════════════════════════════════════════════

    async def _get_skeleton_for_cot(self, project_id: str, query: str) -> str:
        """Retrieve the project skeleton (signatures only) for use as CoT context."""
        return self._format_skeleton(project_id)

    # ═══════════════════════════════════════════════════════════════════════
    # 2.5 — Resolve /expand hints in CoT output
    # ═══════════════════════════════════════════════════════════════════════

    async def _resolve_cot_expands(self, reasoning_text: str, project_id: str) -> str:
        """Replace `/expand <symbol>` placeholders with actual symbol bodies."""
        if not self._f.valves.enable_cot_expand_resolution:
            return reasoning_text

        pattern = re.compile(r"/expand\s+([A-Za-z_][\w.]*)")
        max_expands = self._f.valves.cot_expand_max_symbols
        max_tokens = self._f.valves.cot_expand_max_tokens

        matches = pattern.findall(reasoning_text)
        if not matches:
            return reasoning_text

        symbols = list(dict.fromkeys(matches))[:max_expands]
        expanded = reasoning_text
        total_chars_added = 0

        for sym in symbols:
            qids = self._f._symbol_index.get_qualified_names_for(sym, project_id)
            if not qids:
                continue
            qid = sorted(qids)[0]

            block_hashes = self._f._symbol_index.find_blocks(qid, project_id)
            if not block_hashes:
                continue
            state = self._f._conversation_state_manager.get(project_id)
            block = None
            for bh in block_hashes:
                blk = state.active_blocks.get(bh)
                if blk and not blk.obsolete:
                    block = blk
                    break
            if block is None:
                continue

            body = CodeBlockManager.extract_symbol_body(block, qid)
            if not body:
                continue

            if max_tokens > 0:
                est_tokens = self._f._tokens.estimate_code_tokens(body)
                if total_chars_added + est_tokens * 4 > max_tokens * 4:
                    truncated = (
                        body[: (max_tokens * 4 - total_chars_added)]
                        + "\n# ... [truncated]"
                    )
                    body = truncated
                    expanded = expanded.replace(
                        f"/expand {sym}", f"```\n{body}\n```", 1
                    )
                    break

            replacement = f"```\n{body}\n```"
            expanded = expanded.replace(f"/expand {sym}", replacement, 1)
            total_chars_added += len(body)

        return expanded

    # ═══════════════════════════════════════════════════════════════════════
    # 2.6 — Docstring provider
    # ═══════════════════════════════════════════════════════════════════════

    def _make_docstring_provider(self, project_id: str):
        """Return f(symbol_name, parent_class='') -> one-line docstring or ''."""
        if not self._f.valves.skeleton_include_docstrings:
            return lambda _name, _parent="": ""

        def _provider(symbol_name: str, parent_class: str = "") -> str:
            qid = qualify_symbol_name(symbol_name, parent_class)
            return self._f._symbol_index.get_docstring(qid, project_id) or ""

        return _provider

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Use case classification (cascade: Heuristic → CE → LLM)
    # ═══════════════════════════════════════════════════════════════════════

    def get_effective_context_budget(self, project_id: str) -> int:
        """
        Tokens available for history + user message after Block A + Block B.
        """
        window = self._f.valves.context_window_tokens
        used = self._f._project_state_manager.get_last_system_tokens(project_id)

        reserve = self._f.valves.response_reserve_tokens
        budget = max(0, window - used - reserve)

        self._f._log_debug(
            f"get_effective_context_budget: window={window}, used_system={used}, "
            f"reserve={reserve} → {budget} tokens available for history + user message"
        )
        return budget

    async def classify_use_case(
        self, query: str, intent_vector: dict, project_id: str
    ) -> Tuple[str, dict, str]:
        """
        Classify the query into one of five use cases using a cascade.

        Cascade:
        1. Heuristic reinforcement: command prefix (/arch, /plan, etc.) overrides all.
        2. Regex-based explicit detection (fast).
        3. CrossEncoder scores the use case against definitions.
        4. If confident (diff >= CE_THRESHOLD), use CrossEncoder result.
        5. If extremely uncertain (diff < LLM_THRESHOLD), call LLM with CE context.
        6. Middle zone: use intent_vector fallback (original heuristic).

        Restores KV slot after any LLM call.

        Returns:
            Tuple[str, dict, str]: (use_case_key, lod_profile, human_label)
        """
        q = query or ""

        # ── Fast path: explicit command prefix ──
        if self._f.valves.lod_intent_explicit_override:
            m = self._UC_COMMAND_RE.match(q)
            if m:
                case_key = {
                    "arch": UseCase.ARCHITECTURE,
                    "plan": UseCase.PLANNING,
                    "code": UseCase.PROGRAMMING,
                    "refactor": UseCase.REFACTORING,
                    "scaffold": UseCase.SCAFFOLDING,
                }[m.group(1).lower()]
                case = case_key.value
                self._f._log_debug(
                    f"classify_use_case: detected '{case_key.label}' "
                    f"via explicit command '/{m.group(1)}'"
                )
                return case, dict(self.LOD_PROFILES[case]), case_key.label

        # ── Regex-based explicit detection ──
        if self._UC_SCAFFOLD_RE.search(q):
            case = UseCase.SCAFFOLDING
            self._f._log_debug(f"classify_use_case: detected '{case.label}' via regex")
            return case.value, dict(self.LOD_PROFILES[case.value]), case.label
        if self._UC_REFACTOR_RE.search(q):
            case = UseCase.REFACTORING
            self._f._log_debug(f"classify_use_case: detected '{case.label}' via regex")
            return case.value, dict(self.LOD_PROFILES[case.value]), case.label
        if self._UC_ARCH_RE.search(q):
            case = UseCase.ARCHITECTURE
            self._f._log_debug(f"classify_use_case: detected '{case.label}' via regex")
            return case.value, dict(self.LOD_PROFILES[case.value]), case.label
        if self._UC_PLAN_RE.search(q):
            case = UseCase.PLANNING
            self._f._log_debug(f"classify_use_case: detected '{case.label}' via regex")
            return case.value, dict(self.LOD_PROFILES[case.value]), case.label

        # ── CrossEncoder ──
        if (
            self._f._cross_encoder is not None
            and self._f.valves.enable_cot_llm_detection
        ):
            stripped = self._f._commands._extract_text_for_classification(q)
            query_short = stripped[:500] if stripped else q[:500]
            pairs = [
                (
                    query_short,
                    "The user is asking about architecture, design, or high-level structure.",
                ),
                (
                    query_short,
                    "The user is planning or creating a roadmap, steps, or implementation plan.",
                ),
                (
                    query_short,
                    "The user is programming, writing code, or asking about general programming.",
                ),
                (
                    query_short,
                    "The user is refactoring or analyzing impact of changes.",
                ),
                (
                    query_short,
                    "The user is scaffolding, creating stubs, or asking for boilerplate code.",
                ),
            ]
            scores = await self._f._commands._predict_cross_encoder(pairs)

            if scores is not None and len(scores) >= 5:
                # ── Heuristic reinforcement ──
                scores_reinforced = list(scores)
                h_weight = self._f.valves.heuristic_reinforcement_weight
                if intent_vector.get("debug", 0) > 0.3:
                    scores_reinforced[3] += h_weight * 0.2  # refactor
                if intent_vector.get("explain", 0) > 0.4:
                    scores_reinforced[0] += h_weight * 0.2  # architecture
                if intent_vector.get("modify", 0) > 0.4:
                    scores_reinforced[2] += h_weight * 0.1  # programming

                max_score = max(scores_reinforced)
                second_max = (
                    sorted(scores_reinforced, reverse=True)[1]
                    if len(scores_reinforced) > 1
                    else 0
                )
                diff = max_score - second_max

                CE_CONFIDENCE_THRESHOLD = self._f.valves.use_case_ce_threshold
                LLM_FALLBACK_THRESHOLD = self._f.valves.use_case_llm_threshold

                if diff >= CE_CONFIDENCE_THRESHOLD:
                    best_idx = int(np.argmax(scores_reinforced))
                    case_keys = ["A", "B", "C", "D", "E"]
                    case_key = case_keys[best_idx]
                    case = UseCase(case_key)
                    self._f._log_debug(
                        f"classify_use_case: CE confident (diff={diff:.2f}) → '{case.label}'"
                    )
                    return case.value, dict(self.LOD_PROFILES[case.value]), case.label

                elif diff < LLM_FALLBACK_THRESHOLD:
                    self._f._log_debug(
                        f"classify_use_case: CE uncertain (diff={diff:.2f} < {LLM_FALLBACK_THRESHOLD:.2f}), "
                        "using LLM"
                    )
                    return await self._classify_use_case_with_llm(
                        q, scores_reinforced, project_id
                    )
                # else: middle zone → fall through to heuristic

        # ── Fallback: intent_vector-based heuristic ──
        iv = intent_vector or {}
        refactor_w = iv.get("refactor", 0.0)
        debug_w = iv.get("debug", 0.0)
        modify_w = iv.get("modify", 0.0)
        explain_w = iv.get("explain", 0.0)

        if refactor_w >= 0.30 and refactor_w >= max(debug_w, modify_w, explain_w):
            case = UseCase.REFACTORING
            self._f._log_debug(
                f"classify_use_case: fallback to '{case.label}' via intent_vector (refactor={refactor_w:.2f})"
            )
            return case.value, dict(self.LOD_PROFILES[case.value]), case.label

        if explain_w >= 0.5 and explain_w > modify_w:
            case = UseCase.ARCHITECTURE
            self._f._log_debug(
                f"classify_use_case: fallback to '{case.label}' via intent_vector (explain={explain_w:.2f})"
            )
            return case.value, dict(self.LOD_PROFILES[case.value]), case.label

        case = UseCase.PROGRAMMING
        self._f._log_debug(f"classify_use_case: default '{case.label}'")
        return case.value, dict(self.LOD_PROFILES[case.value]), case.label

    async def _classify_use_case_with_llm(
        self,
        query: str,
        ce_scores: List[float],
        project_id: str,
    ) -> Tuple[str, dict, str]:
        """
        LLM fallback for use case classification when the CrossEncoder diff
        falls below use_case_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer. Default on unknown response is 'C'
        (Programming) — the most common use case.

        Args:
            query: The user's message (truncated to 500 chars).
            ce_scores: List of 5 CE scores [Architecture, Planning, Programming,
                       Refactoring, Scaffolding].
            project_id: Current project identifier, used for slot restoration.

        Returns:
            Tuple[str, dict, str]: (use_case_key, lod_profile, human_label)
        """
        ce_block = (
            f"CrossEncoder scores — "
            f"Architecture: {ce_scores[0]:.2f}, "
            f"Planning: {ce_scores[1]:.2f}, "
            f"Programming: {ce_scores[2]:.2f}, "
            f"Refactoring: {ce_scores[3]:.2f}, "
            f"Scaffolding: {ce_scores[4]:.2f}\n\n"
        )

        prompt = (
            f"{ce_block}"
            f"User question:\n{query[:500]}\n\n"
            f"Choose the most appropriate use case:\n"
            f"  Architecture — design, structure, high-level system decisions\n"
            f"  Planning     — roadmap, steps, implementation plan\n"
            f"  Programming  — general coding, writing code, debugging\n"
            f"  Refactoring  — restructuring, impact analysis, code changes\n"
            f"  Scaffolding  — stubs, boilerplate, skeleton code\n\n"
            f'Output only the JSON object, e.g. {{"use_case": "Programming"}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a use case classifier. "
                "Output ONLY a valid JSON object with a single string field 'use_case' "
                "whose value is one of: Architecture, Planning, Programming, "
                "Refactoring, Scaffolding. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="use_case_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        # Restore the KV slot after any auxiliary LLM call.
        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        # Map the string value to the internal use case key.
        _label_map = {
            "architecture": "A",
            "planning": "B",
            "programming": "C",
            "refactoring": "D",
            "scaffolding": "E",
        }

        case_key = "C"  # default: Programming
        if response:
            try:
                data = json.loads(response)
                raw = str(data.get("use_case", "")).strip().lower()
                case_key = _label_map.get(raw, "C")
                if case_key == "C" and raw not in _label_map:
                    self._f._log_debug(
                        f"_classify_use_case_with_llm: unknown value {raw!r}, "
                        f"defaulting to Programming"
                    )
                else:
                    self._f._log_debug(
                        f"_classify_use_case_with_llm: LLM decided {raw!r} → {case_key!r}"
                    )
            except (json.JSONDecodeError, Exception):
                self._f._log_debug(
                    f"_classify_use_case_with_llm: JSON parse error — "
                    f"response: {response[:200]!r}, defaulting to Programming"
                )

        case = UseCase(case_key)
        return case.value, dict(self.LOD_PROFILES[case.value]), case.label

    # ═══════════════════════════════════════════════════════════════════════
    # 4. Call graph mode resolution (cascade: Heuristic → CE → LLM)
    # ═══════════════════════════════════════════════════════════════════════

    async def _resolve_call_graph_mode(
        self,
        query: str,
        intent_vector: dict,
        project_id: str,
    ) -> str:
        """
        Resolve the effective call-graph depth for Block A using a cascade.

        Uses heuristic reinforcement, CrossEncoder, and LLM fallback to decide
        between 'hubs_only', 'expanded_hubs', and 'full_graph'.

        Args:
            query: User query.
            intent_vector: Intent classification probabilities.
            project_id: Current project identifier.

        Returns:
            'hubs_only', 'expanded_hubs', or 'full_graph'.
        """
        # ------------------------------------------------------------------
        # Step 1: Manual override via valve.
        # ------------------------------------------------------------------
        valve = self._f.valves.call_graph_context_mode
        if valve != "auto":
            self._f._log_debug(f"_resolve_call_graph_mode: valve override → '{valve}'")
            return valve

        # ------------------------------------------------------------------
        # Step 2: Determine use case from intent_vector.
        # ------------------------------------------------------------------
        use_case = "C"  # Default: Programming.
        if intent_vector:
            if intent_vector.get("refactor", 0.0) >= 0.30:
                use_case = "D"
            elif intent_vector.get("explain", 0.0) >= 0.5:
                use_case = "A"

        # ------------------------------------------------------------------
        # Step 3: Calculate token availability.
        # ------------------------------------------------------------------
        total_symbols = len(self._f._symbol_index.get_all_qualified_names(project_id))
        free_tokens = self.get_effective_context_budget(project_id)

        def _full_graph_allowed() -> bool:
            symbol_ok = (
                total_symbols
                <= self._f.valves.call_graph_auto_full_graph_symbol_ceiling
            )
            fg_floor = int(
                self._f.valves.context_window_tokens
                * self._f.valves.full_graph_min_free_token_ratio
            )
            return symbol_ok and (free_tokens >= fg_floor)

        def _expanded_hubs_allowed() -> bool:
            symbol_ok = (
                total_symbols
                <= self._f.valves.call_graph_auto_expanded_hubs_symbol_ceiling
            )
            eh_floor = int(
                self._f.valves.context_window_tokens
                * self._f.valves.expanded_hubs_min_free_token_ratio
            )
            return symbol_ok and (free_tokens >= eh_floor)

        # ------------------------------------------------------------------
        # Step 4: CrossEncoder for mode resolution.
        # ------------------------------------------------------------------
        if (
            self._f._cross_encoder is not None
            and self._f.valves.enable_cot_llm_detection
        ):
            stripped = self._f._commands._extract_text_for_classification(query)
            query_short = stripped[:500] if stripped else query[:500]
            pairs = [
                (
                    query_short,
                    "The user only needs the top hub symbols, no full call graph.",
                ),
                (
                    query_short,
                    "The user needs the top hub symbols plus their direct callers/callees.",
                ),
                (query_short, "The user needs the full call graph with all symbols."),
            ]
            scores = await self._f._commands._predict_cross_encoder(pairs)

            if scores is not None and len(scores) >= 3:
                # Apply heuristic reinforcement.
                h_weight = self._f.valves.heuristic_reinforcement_weight
                scores_reinforced = list(scores)

                if use_case == "A":
                    scores_reinforced[2] += (
                        h_weight * 0.3
                    )  # full_graph for architecture.
                elif use_case == "D":
                    scores_reinforced[1] += (
                        h_weight * 0.3
                    )  # expanded_hubs for refactor.

                if intent_vector.get("debug", 0) > 0.3:
                    scores_reinforced[1] += h_weight * 0.2

                max_score = max(scores_reinforced)
                second_max = (
                    sorted(scores_reinforced, reverse=True)[1]
                    if len(scores_reinforced) > 1
                    else 0
                )
                diff = max_score - second_max

                CE_CONFIDENCE_THRESHOLD = self._f.valves.graph_mode_ce_threshold
                LLM_FALLBACK_THRESHOLD = self._f.valves.graph_mode_llm_threshold

                if diff >= CE_CONFIDENCE_THRESHOLD:
                    best_idx = int(np.argmax(scores_reinforced))
                    modes = ["hubs_only", "expanded_hubs", "full_graph"]
                    resolved_mode = modes[best_idx]
                    self._f._log_debug(
                        f"_resolve_call_graph_mode: CE confident (diff={diff:.2f}) → '{resolved_mode}'"
                    )
                    return resolved_mode

                elif diff < LLM_FALLBACK_THRESHOLD:
                    self._f._log_debug(
                        f"_resolve_call_graph_mode: CE uncertain (diff={diff:.2f} < {LLM_FALLBACK_THRESHOLD:.2f}), "
                        "using LLM fallback"
                    )
                    # ------------------------------------------------------------------
                    # LLM fallback for mode resolution.
                    # ------------------------------------------------------------------
                    ce_summary = "\n".join(
                        [
                            f"- Hubs only: {scores_reinforced[0]:.2f}",
                            f"- Expanded hubs: {scores_reinforced[1]:.2f}",
                            f"- Full graph: {scores_reinforced[2]:.2f}",
                        ]
                    )
                    prompt = f"""
The CrossEncoder is uncertain. Scores:
{ce_summary}

User query:
{query[:500]}

Choose the call graph depth.
Options:
- hubs_only: only top hub symbols
- expanded_hubs: hubs + direct callers/callees
- full_graph: all symbols

Output only the option name.
"""
                    llm_response = await self._f._llm_orchestrator.call_llm(
                        prompt=prompt,
                        system_prompt="You are a context planner. Output only 'hubs_only', 'expanded_hubs', or 'full_graph'.",
                        model_override=self._f.valves.summarization_model,
                        max_tokens=10,
                        temperature=0.0,
                        label="graph_mode_llm",
                    )
                    if llm_response:
                        llm_mode = llm_response.strip().lower()
                        if llm_mode in ("hubs_only", "expanded_hubs", "full_graph"):
                            self._f._log_debug(
                                f"_resolve_call_graph_mode: LLM decided '{llm_mode}'"
                            )
                            return llm_mode

                # Middle zone: fall through to heuristic.

        # ------------------------------------------------------------------
        # Step 5: Heuristic fallback.
        # ------------------------------------------------------------------
        if use_case == "A":
            if _full_graph_allowed():
                return "full_graph"
            if _expanded_hubs_allowed():
                return "expanded_hubs"
            return "hubs_only"

        if use_case == "D":
            if _expanded_hubs_allowed():
                return "expanded_hubs"
            return "hubs_only"

        return "hubs_only"

    # ------------------------------------------------------------------
    # Region: Call Graph Mode Resolution with Hysteresis
    # ------------------------------------------------------------------

    async def prepare_call_graph_mode(
        self, project_id: str, query: str, intent_vector: dict
    ) -> str:
        """
        Resolve and apply the call-graph mode for this turn before Block A is built.

        Implements hysteresis: upgrades are applied immediately; downgrades are
        deferred by call_graph_mode_downgrade_after_turns.

        Args:
            project_id: Current project identifier.
            query: The user query string.
            intent_vector: Intent classification probabilities.

        Returns:
            The resolved call-graph mode string ('hubs_only', 'expanded_hubs',
            or 'full_graph').
        """
        psm = self._f._project_state_manager
        pstate = psm.get_pstate(project_id)

        # ------------------------------------------------------------------
        # Step 1: Global scope detection forces full_graph.
        # ------------------------------------------------------------------
        if hasattr(
            self._f, "_seed_inferencer"
        ) and self._f._seed_inferencer.is_global_scope(query):
            psm.set_resolved_call_graph_mode(project_id, "full_graph")
            psm.set_force_multi_phase_this_turn(project_id, True)
            pstate["graph_mode_downgrade_streak"] = 0
            self._f._log_debug(
                "prepare_call_graph_mode: global scope detected -> "
                "full_graph forced + multi-phase activated this turn."
            )
            return "full_graph"

        # ------------------------------------------------------------------
        # Step 2: Resolve the raw mode using the cascade.
        # ------------------------------------------------------------------
        raw_resolved_mode = await self._resolve_call_graph_mode(
            query, intent_vector, project_id
        )

        # ------------------------------------------------------------------
        # Step 3: Hysteresis - defer downgrades to avoid KV-cache thrash.
        # ------------------------------------------------------------------
        _MODE_RANK = {"hubs_only": 0, "expanded_hubs": 1, "full_graph": 2}

        previous_mode = psm.get_resolved_call_graph_mode(project_id)
        streak = pstate.get("graph_mode_downgrade_streak", 0)

        if previous_mode is None or _MODE_RANK.get(
            raw_resolved_mode, 0
        ) >= _MODE_RANK.get(previous_mode, 0):
            # Upgrade or first time: apply immediately.
            resolved_graph_mode = raw_resolved_mode
            pstate["graph_mode_downgrade_streak"] = 0
        else:
            # Downgrade: defer until streak reaches threshold.
            streak += 1
            pstate["graph_mode_downgrade_streak"] = streak
            if streak >= self._f.valves.call_graph_mode_downgrade_after_turns:
                resolved_graph_mode = raw_resolved_mode
                pstate["graph_mode_downgrade_streak"] = 0
            else:
                resolved_graph_mode = previous_mode
                self._f._log_debug(
                    f"Call graph mode: downgrade to {raw_resolved_mode} "
                    f"deferred ({streak}/"
                    f"{self._f.valves.call_graph_mode_downgrade_after_turns}"
                    f" turns) - keeping {previous_mode} to avoid "
                    f"KV-cache thrash"
                )

        # ------------------------------------------------------------------
        # Step 4: Store and log the resolved mode if changed.
        # ------------------------------------------------------------------
        if previous_mode != resolved_graph_mode:
            self._f._log_debug(
                f"Call graph mode: {previous_mode or '(none)'} -> "
                f"{resolved_graph_mode} (resolved before Block A "
                f"build this turn)"
            )
            psm.set_resolved_call_graph_mode(project_id, resolved_graph_mode)

        return resolved_graph_mode

    # ═══════════════════════════════════════════════════════════════════════
    # 5. Block B — dynamic, per‑query LOD‑activated context
    # ═══════════════════════════════════════════════════════════════════════

    def _render_symbol_body_only(self, qid: str, project_id: str) -> str:
        """Render a symbol's body without the signature header.

        Used when the signature is already present in Block A (skeleton tier).
        """
        state = self._f._conversation_state_manager.get(project_id)
        block_hashes = self._f._symbol_index.find_blocks(qid, project_id)
        for bh in block_hashes:
            block = state.active_blocks.get(bh)
            if block and not block.obsolete:
                body = CodeBlockManager.extract_symbol_body(block, qid)
                if body:
                    return f"# {qid} — body\n{body}\n"
        return ""

    # ------------------------------------------------------------------
    # Region: Block B — Dynamic, per‑query LOD‑activated context
    # ------------------------------------------------------------------

    async def build_block_b(
        self,
        project_id: str,
        query: str,
        messages: list,
        slot_free: bool,
        intent_vector: dict,
        is_continuation: bool,
    ) -> str:
        """
        Build Block B: dynamic per-query content with SWA-aware ordering.

        Steps:
            1.  Early exit when path analysis is disabled.
            2.  Fast paths: empty state, skeleton-symbol intent, skeleton intent,
                inventory queries.
            3.  Use case classification and semantic seed inference.
            4.  Build ActivationGraph via PPR; abort if no nodes activate.
            5.  Adjust LOD thresholds by intent vector and use-case profile.
            6.  Case D: pull direct callers into Block B at LOD-1.
            7.  Resolve call-graph mode from pstate.
            8.  Compute token budget for Block B assembly.
            9.  LOD-2 hysteresis: build lod2_qids and lod3_qids from pre-bump
                activation scores; persist lod2_active_qids_prev.
            10. Retrieve skeleton tier qids to avoid signature duplication.
            11. Define _lod_tier closure (captures lod2_qids/lod3_qids by name).
                Sort activated nodes by descending tier then descending score.
            12. Centrality LOD bump: adjust per-node activation scores, then
                rebuild lod2_qids and lod3_qids from bumped scores preserving
                LOD-2 hysteresis (Bug 12 fix), and re-sort.
            13. Batch LOD-2 docstring pre-resolution.
                lod3_qids excluded (Bug 14 fix): full-body nodes receive body
                injection in Step 15, making a separate docstring pass redundant.
            14. Batch LOD-2.5 CFG pre-resolution.
                lod3_qids excluded (Bug 14 fix): same reason as Step 13.
            15. Render each activated node at its effective LOD tier:
                  LOD-1 → signature line
                  LOD-2 → signature + docstring (+ optional CFG skeleton)
                  LOD-3 → full code body with overflow / compression /
                           semantic relevance filter
            16. Prepend RAPTOR cluster summaries to the LOD-2 section.
            17. SWA-aware assembly of rendered sections.
            18. Append hub recency pointers.
            19. Append use-case instruction tail.
            20. Fallback to full active_code_context when nothing rendered.
            21. Append summary line.
            22. Record LOD-level map for adaptive threshold tuning.
            23. Store injected qids for docstring prioritisation.
        """
        psm = self._f._project_state_manager

        # ── Step 1: early exit ────────────────────────────────────────────────
        if not self._f.valves.enable_path_analysis:
            active_ctx = self._f._activation.get_active_code_context(project_id, query)
            return active_ctx if active_ctx else ""

        state = self._f._conversation_state_manager.get(project_id)
        if not state or not state.active_blocks:
            return ""

        # ── Step 2: fast paths ────────────────────────────────────────────────
        if self._f.valves.enable_skeleton_intent:
            _sym_match = self._SKELETON_SYMBOL_RE.search(query)
            if _sym_match:
                _sym_name = _sym_match.group("sym")
                _all = self._f._symbol_index.get_all_names(project_id)
                if _sym_name in _all:
                    skel = await self._format_skeleton_for_symbol(
                        _sym_name, project_id, query
                    )
                    if skel:
                        return skel

        if self._f.valves.enable_skeleton_intent and self._SKELETON_INTENTS.search(
            query
        ):
            skel = self._format_skeleton(project_id)
            if skel:
                return skel

        if self._LIST_INTENTS.search(query):
            all_qids = self._f._symbol_index.get_all_qualified_names(project_id)
            if all_qids:
                return await self._format_full_symbol_inventory(all_qids, project_id)

        # ── Step 3: use case classification and seed inference ────────────────
        active_use_case, use_case_profile, _ = await self.classify_use_case(
            query, intent_vector, project_id
        )

        inferred_seeds: Dict[str, float] = {}
        if self._f.valves.seed_inference_mode != "off":
            inferred_seeds = await self._f._seed_inferencer.infer_seeds(
                query=query,
                project_id=project_id,
                intent_vector=intent_vector,
                use_case=active_use_case,
                slot_free=slot_free,
            )

        # ── Step 4: build ActivationGraph ────────────────────────────────────
        ag = await self._f._activation.build_activation_graph(
            query,
            project_id,
            messages=messages,
            inferred_seeds=inferred_seeds,
        )
        activated = ag.get_activated_nodes(
            threshold=self._f.valves.path_activation_threshold
        )
        if not activated:
            self._f._log_debug(
                "build_block_b: no activated nodes, falling back to full context"
            )
            return self._f._activation.get_active_code_context(project_id, query)

        if self._f.valves.debug and hasattr(self._f, "_write_counter"):
            if self._f._write_counter % 50 == 0:
                self._f._log_debug(self._f._activation._ppr_cache.stats)

        # ── Step 5: adjust LOD thresholds by intent ───────────────────────────
        debug_weight = intent_vector.get("debug", 0.2)
        modify_weight = intent_vector.get("modify", 0.3)
        refactor_weight = intent_vector.get("refactor", 0.1)

        lod3 = self._f.valves.lod3_threshold
        lod2 = self._f.valves.lod2_threshold
        lod1 = self._f.valves.lod1_threshold

        if self._f.valves.enable_lod_by_intent:
            lod1 *= use_case_profile.get("lod1_mult", 1.0)
            lod2 *= use_case_profile.get("lod2_mult", 1.0)
            lod3 *= use_case_profile.get("lod3_mult", 1.0)
        else:
            if debug_weight + modify_weight > 0.6:
                scale = 0.7
            elif refactor_weight > 0.4:
                scale = 0.0
            else:
                scale = 1.0
            lod3 *= scale
            lod2 *= scale
            lod1 *= scale

        # ── Step 6: Case D – pull in direct callers ───────────────────────────
        if (
            self._f.valves.enable_lod_by_intent
            and active_use_case == "D"
            and self._f.valves.lod_intent_refactor_callers_max != 0
        ):
            max_callers = self._f.valves.lod_intent_refactor_callers_max
            pulled = 0
            for seed_qid in ag.get_seed_nodes():
                meta = self._f._symbol_index.get_symbol_meta(seed_qid, project_id) or {}
                bare = meta.get("name", seed_qid.rsplit(".", 1)[-1])
                for edge in self._f._symbol_index.get_edges_in(bare, project_id):
                    if max_callers > 0 and pulled >= max_callers:
                        break
                    caller_qid = edge.src
                    if activated.get(caller_qid, 0.0) < lod1:
                        activated[caller_qid] = max(
                            activated.get(caller_qid, 0.0), lod1
                        )
                        pulled += 1
                if max_callers > 0 and pulled >= max_callers:
                    break
            if pulled:
                self._f._log_debug(
                    f"Case D: pulled {pulled} direct caller(s) into Block B "
                    f"at LOD-1 (impact analysis)"
                )

        # ── Step 7: resolve call-graph mode ──────────────────────────────────
        resolved_graph_mode = psm.get_resolved_call_graph_mode(project_id)
        if resolved_graph_mode is None:
            resolved_graph_mode = await self.prepare_call_graph_mode(
                project_id, query, intent_vector
            )

        # ── Step 8: token budget ──────────────────────────────────────────────
        total_tokens = 0
        budget = self._f.valves.active_context_max_tokens or 32000

        if (
            self._f.valves.auto_budget_context_for_parts
            and (
                self._f.valves.enable_multi_phase_response
                or self._f.valves.force_multi_phase_response
            )
            and self._f.valves.context_window_tokens > 0
        ):
            _SYSTEM_OVERHEAD = 2000
            _available_for_context = (
                self._f.valves.context_window_tokens
                - self._f.valves.multi_phase_effective_max_tokens
                - _SYSTEM_OVERHEAD
            )
            budget = min(budget, max(8000, _available_for_context))

        tier_qids: Set[str] = set(psm.get_hub_tier_qids(project_id))
        injected_symbols: Set[str] = set(tier_qids)

        # ── Step 9: LOD-2 hysteresis ──────────────────────────────────────────
        lod2_entry = self._f.valves.lod2_threshold
        lod2_exit = lod2_entry * self._f.valves.lod2_exit_ratio
        currently_lod2: Set[str] = set(psm.get_lod2_active_qids_prev(project_id))

        lod2_qids: Set[str] = set()
        lod3_qids: Set[str] = set()

        for qid, score in activated.items():
            if score >= lod3:
                lod3_qids.add(qid)
            if qid in currently_lod2:
                if score >= lod2_exit:
                    lod2_qids.add(qid)
            else:
                if score >= lod2_entry:
                    lod2_qids.add(qid)

        psm.set_lod2_active_qids_prev(project_id, list(lod2_qids))

        # ── Step 10: retrieve skeleton tier qids ─────────────────────────────
        skeleton_qids: Set[str] = set(psm.get_skeleton_tier_qids(project_id))

        # ── Step 11: closure + stable ordering ───────────────────────────────
        # The closure captures lod2_qids and lod3_qids by name (not by value).
        # Rebinding those names in Step 12 is automatically visible here
        # without redefining the closure.
        def _lod_tier(qid: str) -> int:
            if qid in lod3_qids:
                return 3
            if qid in lod2_qids:
                return 2
            return 1

        sorted_nodes: List[str] = sorted(
            activated.keys(),
            key=lambda q: (-_lod_tier(q), -activated.get(q, 0.0), q),
        )

        # ── Step 12: centrality LOD bump ──────────────────────────────────────
        # After adjusting per-node scores, lod2_qids and lod3_qids are rebuilt
        # from the bumped scores so that Steps 13-15 and the _lod_tier closure
        # classify every node at its correct effective tier (Bug 12).
        #
        # FIX Bug 12 + Regresión: the rebuild preserves LOD-2 hysteresis by
        # checking currently_lod2 and lod2_exit, exactly as Step 9 does.
        # Without this, nodes retained via hysteresis (score between lod2_exit
        # and lod2_entry, no centrality bump applied) were incorrectly expelled
        # from lod2_qids after the rebuild, disappearing from the context
        # silently even though their score hadn't changed.
        activated_scores: Dict[str, float] = dict(activated)
        if self._f.valves.enable_centrality_lod_bump:
            centrality = psm.get_node_centrality(project_id)
            threshold = self._f.valves.centrality_lod_bump_threshold
            adjusted: List[Tuple[str, float]] = []
            for qid in sorted_nodes:
                cent = centrality.get(qid, 0.0)
                if cent >= threshold:
                    effective = min(
                        1.0,
                        activated.get(qid, 0.0)
                        + cent * self._f.valves.centrality_lod_bump_weight,
                    )
                    adjusted.append((qid, effective))
                else:
                    adjusted.append((qid, activated.get(qid, 0.0)))
            activated_scores = dict(adjusted)

            # Rebuild tier sets from bumped scores, preserving LOD-2 hysteresis.
            lod2_qids = set()
            lod3_qids = set()
            for qid, score in activated_scores.items():
                if score >= lod3:
                    lod3_qids.add(qid)
                if qid in currently_lod2:
                    if score >= lod2_exit:
                        lod2_qids.add(qid)
                else:
                    if score >= lod2_entry:
                        lod2_qids.add(qid)

            sorted_nodes = sorted(
                activated_scores.keys(),
                key=lambda q: (-_lod_tier(q), -activated_scores.get(q, 0.0), q),
            )

        # ── Step 13: batch LOD-2 docstring pre-resolution ─────────────────────
        # FIX Bug 14: lod3_qids excluded. Full-body nodes receive body injection
        # in Step 15, making a separate docstring LLM call redundant — the
        # docstring would be generated and then immediately discarded.
        if self._f.valves.enable_auto_docstrings:
            lod2_only_candidates = [
                qid
                for qid in (lod2_qids - lod3_qids)
                if not skeleton_qids or qid not in skeleton_qids
            ]
            if lod2_only_candidates:
                missing: List[str] = []
                for qid in lod2_only_candidates:
                    has_doc = False
                    for bh in self._f._symbol_index.find_blocks(qid, project_id):
                        blk = state.active_blocks.get(bh)
                        if blk and any(
                            qualify_symbol_name(s.name, s.parent_symbol) == qid
                            and s.docstring
                            for s in blk.symbols
                        ):
                            has_doc = True
                            break
                    if not has_doc:
                        missing.append(qid)
                if missing:
                    await self._f._enrichment.ensure_docstrings_batch(
                        missing, project_id
                    )

        # ── Step 14: batch LOD-2.5 CFG pre-resolution ────────────────────────
        # FIX Bug 14: lod3_qids excluded for the same reason as Step 13.
        if self._f.valves.enable_cfg_skeletons and (
            active_use_case == "D"
            or intent_vector.get("debug", 0.0)
            >= self._f.valves.cfg_skeleton_debug_intent_threshold
        ):
            cfg_candidates = [
                qid
                for qid in (lod2_qids - lod3_qids)
                if not skeleton_qids or qid not in skeleton_qids
            ]
            self._f._log_debug(
                f"CFG gate TRIGGERED: use_case={active_use_case}, "
                f"debug_intent={intent_vector.get('debug', 0.0):.2f}, "
                f"candidates={cfg_candidates}"
            )
            if cfg_candidates:
                await self._f._enrichment.ensure_cfg_batch(cfg_candidates, project_id)
        else:
            self._f._log_debug(
                f"CFG gate NOT triggered: use_case={active_use_case}, "
                f"debug_intent={intent_vector.get('debug', 0.0):.2f}, "
                f"enable_cfg_skeletons={self._f.valves.enable_cfg_skeletons}"
            )

        # ── Step 15: render LOD tiers ─────────────────────────────────────────
        _lod1_parts: List[str] = []
        _lod2_parts: List[str] = []
        _lod3_parts: List[str] = []

        for qid in sorted_nodes:
            if total_tokens >= budget:
                break
            if qid in injected_symbols:
                continue

            # -- Skeleton tier handling --
            if qid in skeleton_qids:
                if _lod_tier(qid) == 2:
                    self._f._log_debug(
                        f"Block B: skipping LOD-2 for {qid} (in skeleton tier)"
                    )
                    continue
                if _lod_tier(qid) == 3:
                    body_only = self._render_symbol_body_only(qid, project_id)
                    if body_only:
                        tok = self._f._tokens.estimate_code_tokens(body_only)
                        if total_tokens + tok <= budget:
                            _lod3_parts.append(body_only)
                            total_tokens += tok
                            injected_symbols.add(qid)
                    continue

            block_hashes = self._f._symbol_index.find_blocks(qid, project_id)
            for bh in block_hashes:
                block = state.active_blocks.get(bh)

                if block is None and self._f._pager is not None:
                    if self._f._pager.is_paged(bh, project_id):
                        block = await self._f._pager.page_in_block(
                            block_hash=bh,
                            project_id=project_id,
                            chroma_collection=self._f.memory_collection,
                            db_conn=self._f._db_conn,
                        )

                if not block or block.obsolete:
                    continue

                score = activated_scores.get(qid, 0.0)
                tier = _lod_tier(qid)

                # -- LOD-1: signature only --
                if tier == 1:
                    sig = next(
                        (
                            s.signature
                            for s in block.symbols
                            if qualify_symbol(s) == qid
                        ),
                        qid,
                    )
                    tok = len(sig) // 4 + 2
                    if total_tokens + tok > budget:
                        break
                    loc = f" ({block.file_path})" if block.file_path else ""
                    _lod1_parts.append(f"- `{sig}`{loc} _(score: {score:.2f})_")
                    total_tokens += tok
                    injected_symbols.add(qid)

                # -- LOD-2: signature + docstring + optional CFG --
                elif tier == 2:
                    sig = next(
                        (
                            s.signature
                            for s in block.symbols
                            if qualify_symbol(s) == qid
                        ),
                        qid,
                    )
                    docstring = next(
                        (
                            s.docstring
                            for s in block.symbols
                            if qualify_symbol(s) == qid and s.docstring
                        ),
                        "",
                    )

                    cfg_skeleton = ""
                    if self._f.valves.enable_cfg_skeletons and (
                        active_use_case == "D"
                        or intent_vector.get("debug", 0.0)
                        >= self._f.valves.cfg_skeleton_debug_intent_threshold
                    ):
                        cfg_skeleton = (
                            self._f._symbol_index.get_cfg(qid, project_id) or ""
                        )

                    if cfg_skeleton:
                        self._f._log_debug(f"CFG injected for '{qid}' (LOD-2)")
                        text = f"`{sig}`"
                        if docstring:
                            text += f": {docstring}"
                        text += f"\n```python\n{cfg_skeleton}\n```"
                    else:
                        text = f"- `{sig}`: {docstring}" if docstring else f"- `{sig}`"

                    tok = self._f._tokens.estimate_code_tokens(text)
                    if total_tokens + tok > budget:
                        break
                    loc = f" ({block.file_path})" if block.file_path else ""
                    _lod2_parts.append(f"{text}{loc} _(score: {score:.2f})_")
                    total_tokens += tok
                    injected_symbols.add(qid)

                # -- LOD-3: full body --
                else:
                    if self._f.valves.enable_semantic_lod3_filter and slot_free:
                        include_block = await self._evaluate_lod3_block_relevance(
                            block=block,
                            qid=qid,
                            query=query,
                            project_id=project_id,
                        )
                        if not include_block:
                            self._f._log_debug(
                                f"Block B: skipping LOD-3 for {qid} "
                                f"(low semantic relevance)"
                            )
                            continue

                    content_to_inject = CodeBlockManager.extract_symbol_body(block, qid)
                    tok = self._f._tokens.estimate_code_tokens(content_to_inject)

                    _is_oversized = (
                        self._f.valves.max_code_block_tokens > 0
                        and tok > self._f.valves.max_code_block_tokens
                    )

                    if (
                        _is_oversized
                        and self._f.valves.code_block_overflow_action == "warn"
                    ):
                        content_to_inject = self._f.valves.code_block_warn_message
                        tok = self._f._tokens.estimate_code_tokens(content_to_inject)

                    elif (
                        _is_oversized
                        and self._f.valves.code_block_overflow_action == "summarize"
                    ):
                        if block.block_summary:
                            content_to_inject = (
                                f"[Summary of {tok}-token block]\n"
                                f"{block.block_summary}"
                            )
                        else:
                            content_to_inject = (
                                self._f._tokens.truncate_text_to_tokens(
                                    content_to_inject,
                                    self._f.valves.max_code_block_tokens,
                                )
                                + "\n# ... [truncated — use /expand for full body]"
                            )
                        tok = self._f._tokens.estimate_code_tokens(content_to_inject)

                    elif (
                        _is_oversized
                        and self._f.valves.code_block_overflow_action == "truncate"
                    ):
                        content_to_inject = (
                            self._f._tokens.truncate_text_to_tokens(
                                content_to_inject,
                                self._f.valves.max_code_block_tokens,
                            )
                            + "\n# ... [truncated — use /expand for full body]"
                        )
                        tok = self._f._tokens.estimate_code_tokens(content_to_inject)

                    if (
                        slot_free
                        and self._f.valves.enable_code_compression
                        and self._f._llmlingua_compressor
                        and tok > self._f.valves.code_compression_min_tokens
                    ):
                        content_to_inject = (
                            await self._f._history_compressor.compress_code_block(
                                content_to_inject,
                                language=(
                                    block.symbols[0].language
                                    if block.symbols
                                    else "unknown"
                                ),
                                rate=self._f.valves.code_compression_rate,
                                query=query,
                            )
                        )
                        tok = self._f._tokens.estimate_code_tokens(content_to_inject)

                    if total_tokens + tok > budget:
                        break
                    loc = f" ({block.file_path})" if block.file_path else ""
                    _lod3_parts.append(
                        f"### `{qid}`{loc} [activation: {score:.2f}]\n"
                        f"```\n{content_to_inject}\n```\n"
                    )
                    total_tokens += tok
                    injected_symbols.add(qid)

                break  # one block per qid is sufficient

        # ── Step 16: RAPTOR cluster summaries ────────────────────────────────
        if self._f.valves.enable_raptor and getattr(self._f, "_raptor", None):
            try:
                raptor_hits = await self._f._raptor.retrieve(
                    query=query,
                    project_id=project_id,
                    top_k=3,
                    embedder=self._f.embedder,
                    chroma_collection=self._f.memory_collection,
                )
            except Exception:
                raptor_hits = []
            if raptor_hits:
                raptor_section = (
                    "### Related subsystems (RAPTOR)\n"
                    + "\n".join(f"- {h}" for h in raptor_hits)
                    + "\n\n"
                )
                _lod2_parts.insert(0, raptor_section)

        # ── Step 17: SWA-aware assembly ───────────────────────────────────────
        suppress_sigs = (
            self._f.valves.skeleton_tier_suppresses_block_b_signatures
            and active_use_case != "D"
            and self._is_skeleton_tier_active(project_id)
        )

        ordered: List[str] = ["## Code Context (activation-based LOD)\n"]
        if _lod1_parts and not suppress_sigs:
            ordered.append(
                "\n**Signatures** (low activation):\n" + "\n".join(_lod1_parts)
            )
        if _lod2_parts:
            ordered.append(
                "\n**Signatures + docstrings** (medium activation):\n"
                + "\n".join(_lod2_parts)
            )
        if _lod3_parts:
            ordered.append(
                "\n### Directly relevant code (high activation)\n"
                + "\n".join(_lod3_parts)
            )

        # ── Step 18: recency pointers ─────────────────────────────────────────
        _ptr = self._build_hub_recency_pointers(project_id, set(injected_symbols))
        if _ptr:
            ordered.append(_ptr)

        # ── Step 19: instruction tail ─────────────────────────────────────────
        ordered.append(self._build_instruction_tail(active_use_case))

        # ── Step 20: fallback to full context ────────────────────────────────
        if len(ordered) <= 1:
            if suppress_sigs:
                self._f._log_debug(
                    "build_block_b: skeleton tier active and suppress_sigs=True, "
                    "skipping fallback to avoid duplication"
                )
                return ""
            return self._f._activation.get_active_code_context(project_id, query)

        # ── Step 21: summary line ─────────────────────────────────────────────
        ordered.append(
            f"\n_(Context: {len(injected_symbols)} symbols, "
            f"~{total_tokens} tokens, "
            f"{len(activated)} nodes activated)_\n"
        )

        # ── Step 22: LOD tracking for adaptive threshold tuning ───────────────
        if self._f.valves.enable_lod_adaptive:
            lod_map: Dict[str, int] = {}
            for qid, score in activated.items():
                if score < lod1:
                    lod_map[qid] = 0
                elif score < lod2:
                    lod_map[qid] = 1
                elif score < lod3:
                    lod_map[qid] = 2
                else:
                    lod_map[qid] = 3
            psm.set_last_lod_levels(project_id, lod_map)

        # ── Step 23: store injected qids for docstring prioritisation ─────────
        psm.set_block_b_qids_this_turn(project_id, list(injected_symbols))

        return "\n".join(ordered)

    # ═══════════════════════════════════════════════════════════════════════
    # 6. LOD-3 semantic relevance filtering (cascade: Heuristic → CE → LLM)
    # ═══════════════════════════════════════════════════════════════════════

    async def _evaluate_lod3_block_relevance(
        self,
        block: "CodeBlock",
        qid: str,
        query: str,
        project_id: str,
    ) -> bool:
        """
        Evaluate if a block is semantically relevant enough to include in LOD-3.

        Uses a cascade:
        1. Heuristic reinforcement (symbol mentions in query → boost)
        2. CrossEncoder for relevance scoring
        3. LLM (only when extremely uncertain, diff < LLM_THRESHOLD)
        4. Conservative default (include) when CE fails or in middle zone

        Restores KV slot after any LLM call.

        Args:
            block (CodeBlock): The block to evaluate.
            qid (str): The qualified symbol id.
            query (str): The user query.
            project_id (str): Current project identifier.

        Returns:
            bool: True if the block should be included, False otherwise.
        """
        if self._f._cross_encoder is None:
            return True

        content_snippet = block.content[:1500]
        query_snippet = query[:500]

        pairs = [
            (
                query_snippet,
                f"This code block is highly relevant to the user's question:\n{content_snippet}",
            ),
            (
                query_snippet,
                f"This code block is not relevant to the user's question:\n{content_snippet}",
            ),
        ]
        scores = await self._f._commands._predict_cross_encoder(pairs)

        if scores is None or len(scores) < 2:
            return True

        # ── Heuristic reinforcement ──
        content_lower = content_snippet.lower()
        query_words = set(query.lower().split())
        boost = 0.0
        for word in query_words:
            if len(word) > 3 and word in content_lower:
                boost += 0.05
        scores_reinforced = list(scores)
        scores_reinforced[0] += min(boost, 0.3)

        diff = scores_reinforced[0] - scores_reinforced[1]
        CE_CONFIDENCE_THRESHOLD = self._f.valves.lod3_relevance_ce_threshold
        LLM_FALLBACK_THRESHOLD = self._f.valves.lod3_relevance_llm_threshold

        if diff >= CE_CONFIDENCE_THRESHOLD:
            result = scores_reinforced[0] > scores_reinforced[1]
            self._f._log_debug(
                f"_evaluate_lod3_block_relevance: CE confident (diff={diff:.2f}) → {result} for {qid}"
            )
            return result

        elif diff < LLM_FALLBACK_THRESHOLD:
            self._f._log_debug(
                f"_evaluate_lod3_block_relevance: CE uncertain (diff={diff:.2f} < {LLM_FALLBACK_THRESHOLD:.2f}), "
                f"using LLM for {qid}"
            )
            return await self._evaluate_lod3_block_relevance_with_llm(
                block, qid, query, scores_reinforced, project_id
            )

        # Middle zone: keep by default (conservative)
        return True

    async def _evaluate_lod3_block_relevance_with_llm(
        self,
        block: "CodeBlock",
        qid: str,
        query: str,
        ce_scores: List[float],
        project_id: str,
    ) -> bool:
        """
        Use the LLM to decide if a block is relevant enough for LOD-3.

        Restores KV slot after the call.
        """
        snippet = block.content[:800]
        ce_summary = f"""
The CrossEncoder provides the following scores:
- Relevant: {ce_scores[0]:.2f}
- Not relevant: {ce_scores[1]:.2f}
"""

        prompt = f"""
{ce_summary}

Now, independently analyze if the following code block is relevant to the user's question.

User question:
{query[:500]}

Code block (snippet):
{snippet}

Decide if this code block contains information that is directly useful for answering the user's question.

Output only "YES" or "NO".
"""
        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt="You are a relevance evaluator. Output only 'YES' or 'NO'.",
            model_override=self._f.valves.summarization_model,
            max_tokens=5,
            temperature=0.0,
            label="lod3_relevance_llm",
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if response and response.strip().upper() == "YES":
            self._f._log_debug(
                f"_evaluate_lod3_block_relevance_with_llm: LLM decided YES for {qid}"
            )
            return True
        elif response and response.strip().upper() == "NO":
            self._f._log_debug(
                f"_evaluate_lod3_block_relevance_with_llm: LLM decided NO for {qid}"
            )
            return False

        self._f._log_debug(
            f"_evaluate_lod3_block_relevance_with_llm: LLM failed, including {qid} (conservative)"
        )
        return True

    # ═══════════════════════════════════════════════════════════════════════
    # 7. Slot cleanup helper
    # ═══════════════════════════════════════════════════════════════════════

    async def _cleanup_old_slot_files(self, project_id: str, keep: str) -> None:
        """Delete stale slot files, keeping only the current one."""
        slot_dir = self._f.valves.slot_save_path.rstrip("/")
        if not os.path.isdir(slot_dir):
            return
        project_slug = re.sub(r"[^a-zA-Z0-9_-]", "_", project_id)[:20]
        prefix = f"slot{self._f.valves.slot_id}_{project_slug}_"
        try:
            for fname in os.listdir(slot_dir):
                if fname.startswith(prefix) and fname != keep:
                    os.remove(os.path.join(slot_dir, fname))
                    self._f._log_debug(f"Removed obsolete slot file: {fname}")
        except Exception as e:
            self._f._log_debug(f"Slot cleanup error: {e}")


# ---------------------------------------------------------------------------
# SignatureExtractor – tree‑sitter based symbol and call extraction
# ---------------------------------------------------------------------------
class SignatureExtractor:
    """
    Extracts ``CodeSymbol`` lists and call relationships from source code
    using tree‑sitter for precise, qualified results.

    Each returned symbol carries a **qualified identity** (``ClassName.method``
    or ``module.function``) via its ``parent_symbol`` field, so downstream
    indexing never confuses same‑named methods from different classes.

    When tree‑sitter is unavailable or the language cannot be detected, an
    empty list is returned and a warning is logged — no unqualified fallback
    data is ever produced.

    Docstrings are extracted statically for Python via the ``ast`` module;
    for other languages (or when the source lacks a docstring), they are
    filled in later by the LLM‑driven ``ensure_docstrings_batch`` path.

    Caching:
        Results are cached with a 1-hour TTL to avoid re-parsing the same
        code block multiple times within a session. The cache stores raw
        symbols (before parent enrichment) and returns deep copies to
        prevent mutation of cached entries.
    """

    MAX_PARSE_SIZE_BYTES = 5_000_000
    _LANG_MAP: Dict[str, str] = {
        "py": "python",
        "js": "javascript",
        "mjs": "javascript",
        "jsx": "tsx",
        "ts": "tsx",
        "tsx": "tsx",
        "go": "go",
        "rs": "rust",
        "java": "java",
        "c": "c",
        "cpp": "cpp",
        "h": "cpp",
        "hpp": "cpp",
    }

    _parser_cache: Dict[str, Any] = {}
    _parser_cache_lock = threading.Lock()

    # ── extraction cache ──────────────────────────────────────────────
    _extraction_cache: Dict[str, Tuple[List["CodeSymbol"], float]] = {}
    _EXTRACTION_CACHE_MAXSIZE: int = 128
    _EXTRACTION_CACHE_TTL: int = 3600  # 1 hour
    _EXTRACTION_CACHE_LOCK = threading.Lock()

    @staticmethod
    def _cache_key(code: str, file_path: Optional[str], language: Optional[str]) -> str:
        """
        Generate a deterministic cache key for a code extraction request.
        """
        h = hashlib.md5(code.encode()).hexdigest()[:16]
        return f"{h}|{file_path or ''}|{language or ''}"

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Language detection
    # ═══════════════════════════════════════════════════════════════════════════

    @staticmethod
    def _guess_language(file_path: Optional[str], code: str) -> str:
        """
        Heuristically determine the programming language of a code block.

        Resolution order (first match wins):
        1. tree-sitter extension detection if *file_path* is provided.
        2. Extension‑to‑language map (``_LANG_MAP``).
        3. Source‑code heuristics: Python keywords (def, class, import, from, async def)
           or JavaScript 'function' keyword.
        4. (NEW) Use tree-sitter to detect the language from the content itself
           by attempting to parse with each known language and checking if the
           parse tree has meaningful nodes (not just ERROR nodes).
        5. Fallback to "unknown" — callers will skip tree-sitter extraction.
        """
        # 1. Try extension-based detection using tree-sitter (if file_path is given)
        if file_path and HAS_TREE_SITTER:
            try:
                return detect_language_from_extension(
                    file_path.rsplit(".", 1)[-1].lower()
                )
            except Exception:
                pass

        # 2. Fallback to the internal extension map (without tree-sitter)
        if file_path:
            ext = file_path.rsplit(".", 1)[-1].lower()
            return SignatureExtractor._LANG_MAP.get(ext, "unknown")

        # 3. Simple heuristics for common languages (no extension)
        if re.search(r"\b(?:def|class|import|from|async def)\s+\w+", code):
            return "python"
        if re.search(r"\bfunction\s+\w+\s*\(", code):
            return "javascript"

        # 4. NEW: Use tree-sitter to detect language from content
        #    This handles code pasted without a file extension.
        if HAS_TREE_SITTER:
            try:
                from tree_sitter import Parser as TSParser
                from tree_sitter_language_pack import get_language

                # List of languages to try, ordered by commonality
                languages_to_try = [
                    "python",
                    "javascript",
                    "tsx",  # TypeScript/JSX
                    "go",
                    "rust",
                    "java",
                    "cpp",
                    "c",
                    "ruby",
                    "php",
                    "c_sharp",
                    "swift",
                    "kotlin",
                    "typescript",  # plain TS (if tsx doesn't match)
                ]

                # A heuristic: if the code has a shebang, try that first
                if code.startswith("#!"):
                    shebang_line = code.split("\n")[0]
                    if "python" in shebang_line:
                        return "python"
                    if "node" in shebang_line or "js" in shebang_line:
                        return "javascript"

                # Try each language; if the parse tree has at least one
                # non‑ERROR node (i.e., it parsed something meaningful),
                # consider it a match.
                for lang in languages_to_try:
                    try:
                        lang_obj = get_language(lang)
                        parser = TSParser(lang_obj)
                        tree = parser.parse(code.encode())
                        root = tree.root_node
                        # If the root has at least one child that is not an ERROR node,
                        # and the tree is not entirely empty, it's likely a good match.
                        if root.children:
                            # Count non‑ERROR nodes
                            valid_nodes = [
                                n for n in root.children if n.type != "ERROR"
                            ]
                            if valid_nodes:
                                return lang
                    except Exception:
                        # Parser error, language mismatch, or missing grammar
                        continue

                # If no language gave a good parse, try one more pass with
                # a more permissive check: if the root type is not "ERROR"
                # and it has at least one child, consider it valid.
                for lang in languages_to_try:
                    try:
                        lang_obj = get_language(lang)
                        parser = TSParser(lang_obj)
                        tree = parser.parse(code.encode())
                        root = tree.root_node
                        if root.type != "ERROR" and root.children:
                            # It parsed without a top‑level ERROR node;
                            # good enough to assume this language.
                            return lang
                    except Exception:
                        continue

            except Exception:
                # If tree-sitter language detection fails, fall back to "unknown"
                pass

        # 5. Fallback: unknown language
        return "unknown"

    @staticmethod
    def _infer_code_language(code_snippet: str) -> str:
        """Simple heuristic language detection for a code snippet."""
        if re.search(r"\bdef\s+\w+\s*\(", code_snippet):
            return "python"
        if re.search(r"\bfunction\s+\w+\s*\(", code_snippet):
            return "javascript"
        return "unknown"

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Main extraction entry point (with caching)
    # ═══════════════════════════════════════════════════════════════════════════

    @staticmethod
    async def extract_async(
        code: str,
        file_path: Optional[str] = None,
        language: Optional[str] = None,
    ) -> List["CodeSymbol"]:
        """
        Extract CodeSymbol objects from source code using tree-sitter (preferred)
        with an ast fallback for Python.

        Results are cached by (code, file_path, language) hash. The cache always
        returns a fresh shallow copy of the stored symbol list so that callers
        mutating symbol fields (docstring, calls, cfg_skeleton) cannot corrupt
        the cached entry. Without this copy, a second call with the same code
        receives symbols that already have docstrings populated by a prior caller,
        silencing the "missing docstring" detection in EnrichmentTasks.

        Steps:
            1.  Guard: code too large or empty → return [].
            2.  Build cache key; return a shallow copy on cache hit.
            3.  Guess language when not explicitly provided.
            4.  Parse via tree-sitter; fall back to AST for Python.
            5.  Enrich with parent info.
            6.  Store a shallow copy in the cache; return a fresh copy to caller.
        """
        if not code or not code.strip():
            return []

        if (
            len(code.encode("utf-8", errors="replace"))
            > SignatureExtractor.MAX_PARSE_SIZE_BYTES
        ):
            return []

        # -- Step 2: cache lookup — return a fresh copy --
        cache_key = SignatureExtractor._cache_key(code, file_path, language)
        cached = SignatureExtractor._extraction_cache.get(cache_key)
        if cached is not None:
            # Shallow copy each symbol so callers cannot mutate cached state.
            return [sym.copy() for sym in cached]

        # -- Step 3: resolve language --
        lang = language or SignatureExtractor._guess_language(file_path, code)

        # -- Step 4: parse --
        symbols: List["CodeSymbol"] = []
        try:
            code_bytes = code.encode("utf-8", errors="replace")
            tree, used_lang = await anyio.to_thread.run_sync(
                lambda: SignatureExtractor._parse_sync(code_bytes, lang)
            )
            if tree is not None:
                symbols = SignatureExtractor._extract_symbols_from_tree(
                    tree, used_lang, code, file_path
                )
                if symbols:
                    calls_map = SignatureExtractor._extract_calls_from_tree(
                        tree, used_lang, code
                    )
                    for sym in symbols:
                        sym.calls = calls_map.get(sym.name, [])
        except Exception:
            pass

        if not symbols and lang == "python":
            try:
                symbols = SignatureExtractor._extract_symbols_from_ast(code, file_path)
                if symbols:
                    calls_map = SignatureExtractor._extract_calls_from_ast(code)
                    for sym in symbols:
                        sym.calls = calls_map.get(sym.name, [])
                    SignatureExtractor._extract_docstrings_python(code, symbols)
            except Exception:
                pass

        # -- Step 5: enrich --
        if symbols:
            symbols = SignatureExtractor.enrich_symbols_with_parent_info(symbols, code)

        # -- Step 6: store a copy in cache, return a fresh copy to caller --
        if symbols:
            stored = [sym.copy() for sym in symbols]
            SignatureExtractor._extraction_cache[cache_key] = stored
            # Enforce cache size limit
            while (
                len(SignatureExtractor._extraction_cache)
                > SignatureExtractor._EXTRACTION_CACHE_MAXSIZE
            ):
                SignatureExtractor._extraction_cache.pop(
                    next(iter(SignatureExtractor._extraction_cache))
                )

        return [sym.copy() for sym in symbols]

    @staticmethod
    def _extract_symbols_from_ast(
        code: str, file_path: Optional[str]
    ) -> List["CodeSymbol"]:
        """
        Extract function, method, and class symbols from Python source code using AST.

        This method parses the code with `ast.parse()`, walks the tree, and creates
        a `CodeSymbol` for each `FunctionDef`, `AsyncFunctionDef`, and `ClassDef`.
        It also resolves the parent class for methods.

        Args:
            code (str): The Python source code.
            file_path (Optional[str]): The file path (stored in each symbol).

        Returns:
            List[CodeSymbol]: A list of symbols with correct line ranges.
        """
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return []

        symbols = []

        # Pre‑build a mapping from class names to their body nodes for quick lookup
        class_bodies = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                class_bodies[node.name] = node

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                name = node.name
                # Determine if this function is a method (inside a class)
                parent_class = ""
                kind = "function"
                for parent in ast.walk(tree):
                    if isinstance(parent, ast.ClassDef) and node in parent.body:
                        parent_class = parent.name
                        kind = "method"
                        break
                # Build signature string (first line of the function definition)
                signature = ast.unparse(node).split("\n")[0][:200]
                line_start = node.lineno
                line_end = node.end_lineno or node.lineno
                symbols.append(
                    CodeSymbol(
                        name=name,
                        kind=kind,
                        signature=signature,
                        file_path=file_path,
                        line_start=line_start,
                        line_end=line_end,
                        language="python",
                        parent_symbol=parent_class,
                    )
                )

            elif isinstance(node, ast.ClassDef):
                name = node.name
                signature = f"class {name}: ..."
                line_start = node.lineno
                line_end = node.end_lineno or node.lineno
                symbols.append(
                    CodeSymbol(
                        name=name,
                        kind="class",
                        signature=signature,
                        file_path=file_path,
                        line_start=line_start,
                        line_end=line_end,
                        language="python",
                        parent_symbol="",
                    )
                )

        return symbols

    @staticmethod
    def _extract_calls_from_ast(code: str) -> Dict[str, List[str]]:
        """
        Extract call relationships from Python source code using AST.

        For each `Call` node, it determines the callee name and the enclosing
        function/method (caller). The caller is qualified with its parent class
        if it is a method. The result is a dict mapping caller qualified name
        to a list of callee bare names.

        Args:
            code (str): The Python source code.

        Returns:
            Dict[str, List[str]]: {caller_qualified_id: [callee_name, ...]}
        """
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return {}

        from collections import defaultdict

        call_map = defaultdict(set)

        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue

            # Resolve callee name
            callee = None
            if isinstance(node.func, ast.Name):
                callee = node.func.id
            elif isinstance(node.func, ast.Attribute):
                callee = node.func.attr

            if not callee:
                continue

            # Find the enclosing function/method that contains this call
            caller_name = None
            parent_class = ""
            for parent in ast.walk(tree):
                if (
                    isinstance(parent, (ast.FunctionDef, ast.AsyncFunctionDef))
                    and node in parent.body
                ):
                    caller_name = parent.name
                    # Check if this function is a method (inside a class)
                    for cls_node in ast.walk(tree):
                        if (
                            isinstance(cls_node, ast.ClassDef)
                            and parent in cls_node.body
                        ):
                            parent_class = cls_node.name
                            break
                    break

            if not caller_name:
                continue

            # Qualify caller name with its parent class (if any)
            caller_qid = qualify_symbol_name(caller_name, parent_class)
            call_map[caller_qid].add(callee)

        return {k: list(v) for k, v in call_map.items()}

    @staticmethod
    def _parse_sync(
        code_bytes: bytes,
        lang: str,
    ) -> Tuple[Optional[Any], str]:
        """
        Parse source bytes with tree-sitter and return (tree, lang_used).

        Parser instances are stored in thread-local storage so each worker
        thread in the anyio thread pool has its own dedicated parser. Sharing
        a single parser instance across threads is unsafe: tree-sitter's C
        library modifies internal parser state during parse() and is not
        re-entrant. Concurrent calls on the same instance produce corrupted
        trees or segfaults under load.

        Returns (None, lang) when:
            - the requested language is not in _LANG_MAP
            - the tree-sitter language grammar cannot be loaded
            - parsing raises an unexpected exception

        Steps:
            1.  Resolve language string and look up grammar in _LANG_MAP.
            2.  Get or create a per-thread parser for this language.
            3.  Parse and return the tree.
        """
        import threading

        # -- Step 1: resolve language --
        effective_lang = lang.lower().strip()
        lang_grammar = SignatureExtractor._LANG_MAP.get(effective_lang)
        if lang_grammar is None:
            return None, effective_lang

        # -- Step 2: get or create per-thread parser --
        thread_local = getattr(SignatureExtractor, "_thread_local", None)
        if thread_local is None:
            # Lazy initialisation for environments that import the class before
            # the attribute is declared (e.g. during module reload).
            SignatureExtractor._thread_local = threading.local()
            thread_local = SignatureExtractor._thread_local

        if not hasattr(thread_local, "parsers"):
            thread_local.parsers = {}

        parser = thread_local.parsers.get(effective_lang)
        if parser is None:
            try:
                from tree_sitter import Parser

                p = Parser()
                p.set_language(lang_grammar)
                thread_local.parsers[effective_lang] = p
                parser = p
            except Exception as e:
                return None, effective_lang

        # -- Step 3: parse --
        try:
            tree = parser.parse(code_bytes)
            return tree, effective_lang
        except Exception:
            # Discard the potentially corrupt parser instance for this thread
            # so the next call creates a fresh one.
            thread_local.parsers.pop(effective_lang, None)
            return None, effective_lang

    @staticmethod
    def enrich_symbols_with_parent_info(
        symbols: List["CodeSymbol"], full_code: str
    ) -> List["CodeSymbol"]:
        """Assign parent_symbol using AST line-range mapping.
        For symbols that come from the generic extractor (line_start=None),
        the line number is recovered by scanning the source code for the
        definition (def / class / async def) before matching.
        """
        import ast as ast_module

        # ── 1. Recover missing line numbers by scanning the source ──────
        lines = full_code.split("\n")
        for sym in symbols:
            if sym.line_start is not None:
                continue
            # Build a regex that matches the definition of this symbol
            if sym.kind in ("function", "method"):
                pattern = re.compile(
                    r"^\s*(?:async\s+)?def\s+" + re.escape(sym.name) + r"\b"
                )
            elif sym.kind == "class":
                pattern = re.compile(r"^\s*class\s+" + re.escape(sym.name) + r"\b")
            else:
                continue
            for i, line in enumerate(lines, start=1):
                if pattern.search(line):
                    sym.line_start = i
                    break

        # ── 2. Build the AST class‑line mapping using DFS (not BFS) ──
        try:
            tree = ast_module.parse(full_code)
        except SyntaxError:
            return symbols

        line_to_class: Dict[int, str] = {}

        def _visit(node, current_class: str) -> None:
            """Recursive DFS: current_class is the nearest enclosing class name
            (or "" at module level). Local functions nested inside a method keep
            the method's enclosing class — matching the heuristic tree-sitter
            already uses elsewhere in this file."""
            for child in ast_module.iter_child_nodes(node):
                if isinstance(child, ast_module.ClassDef):
                    end_lineno = getattr(child, "end_lineno", child.lineno)
                    for lineno in range(child.lineno, end_lineno + 1):
                        line_to_class[lineno] = current_class
                    _visit(child, child.name)
                elif isinstance(
                    child, (ast_module.FunctionDef, ast_module.AsyncFunctionDef)
                ):
                    end_lineno = getattr(child, "end_lineno", child.lineno)
                    for lineno in range(child.lineno, end_lineno + 1):
                        line_to_class[lineno] = current_class
                    _visit(child, current_class)
                else:
                    _visit(child, current_class)

        _visit(tree, "")

        # ── 3. Assign parent_symbol where possible ─────────────────────
        assigned = 0
        for sym in symbols:
            if sym.parent_symbol:
                continue  # tree-sitter already resolved this correctly — keep it
            if sym.line_start and sym.line_start in line_to_class:
                parent = line_to_class[sym.line_start]
                if parent and parent != sym.name:
                    sym.parent_symbol = parent
                    if sym.kind == "function":
                        sym.kind = "method"
                    assigned += 1

        return symbols

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Symbol extraction from tree-sitter
    # ═══════════════════════════════════════════════════════════════════════════

    @staticmethod
    def _extract_symbols_from_tree(
        tree, lang: str, code: str, file_path: Optional[str]
    ) -> List["CodeSymbol"]:
        """
        Extract symbols using tree-sitter-language-pack's built-in queries.

        Args:
            tree: The tree-sitter parse tree (unused, kept for signature compatibility).
            lang: The programming language.
            code: The source code.
            file_path: Optional file path.

        Returns:
            List[CodeSymbol]: Extracted symbols with line ranges.
        """
        if not HAS_TREE_SITTER:
            return []

        try:
            from tree_sitter_language_pack import process, ProcessConfig

            config = ProcessConfig()
            config.language = lang
            # Enable symbol extraction in the config
            # (The exact property name may vary; check the library docs)
            config.extract_symbols = True
            result = process(code, config)

            symbols = []
            if hasattr(result, "symbols"):
                for sym in result.symbols:
                    # Convert to CodeSymbol
                    # Assuming sym has: name, kind, signature, line_start, line_end, parent
                    code_sym = CodeSymbol(
                        name=sym.name,
                        kind=sym.kind,  # 'function', 'class', 'method'
                        signature=sym.signature or sym.name,
                        file_path=file_path,
                        line_start=sym.line_start + 1,  # if 0-indexed
                        line_end=sym.line_end + 1,
                        language=lang,
                        parent_symbol=sym.parent or "",
                    )
                    symbols.append(code_sym)
            return symbols
        except Exception as e:
            logger.warning(f"tree-sitter symbol extraction via process() failed: {e}")
            return []

    @staticmethod
    def _extract_calls_from_tree(tree, lang: str, code: str) -> Dict[str, List[str]]:
        """
        Extract call relationships using tree-sitter-language-pack's built-in queries.

        Returns:
            Dict[str, List[str]]: {caller_qualified_id: [callee_name, ...]}
        """
        if not HAS_TREE_SITTER:
            return {}

        try:
            from tree_sitter_language_pack import process, ProcessConfig

            config = ProcessConfig()
            config.language = lang
            config.extract_calls = True
            result = process(code, config)

            call_map: Dict[str, Set[str]] = defaultdict(set)
            if hasattr(result, "calls"):
                for call in result.calls:
                    # call should have: caller, callee, line
                    # caller can be qualified (Class.method) or bare
                    if call.caller:
                        call_map[call.caller].add(call.callee)
            return {k: list(v) for k, v in call_map.items()}
        except Exception as e:
            logger.warning(f"tree-sitter call extraction via process() failed: {e}")
            return {}

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Call extraction from tree-sitter
    # ═══════════════════════════════════════════════════════════════════════════

    @staticmethod
    def _extract_docstrings_python(code: str, symbols: List["CodeSymbol"]) -> None:
        """
        Extract docstrings from Python source code using AST with class context awareness.
        Uses a DFS visitor that tracks the current class name, so docstrings are keyed by qualified name
        (ClassName.method) to avoid collisions. Also handles line-wrapped docstrings by joining lines
        until sentence punctuation is found.
        """
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return

        doc_map: Dict[str, str] = {}

        def _first_complete_line(docstring: str) -> str:
            """Return the first complete sentence from a docstring, joining wrapped lines."""
            raw_lines = [l.strip() for l in docstring.strip().splitlines()]
            result = ""
            for line in raw_lines:
                if not line:
                    break
                result = (result + " " + line).strip() if result else line
                if result and result[-1] in ".!?:":
                    break
            return result[:200]

        def _visit(node: ast.AST, class_name: str) -> None:
            """DFS visitor that carries the current class name."""
            for child in ast.iter_child_nodes(node):
                if isinstance(child, ast.ClassDef):
                    _visit(child, child.name)
                elif isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    ds = ast.get_docstring(child)
                    if ds:
                        first = _first_complete_line(ds)
                        if first:
                            key = (
                                f"{class_name}.{child.name}"
                                if class_name
                                else child.name
                            )
                            # First definition wins (preserve the most representative one)
                            if key not in doc_map:
                                doc_map[key] = first
                    # Continue visiting nested functions (e.g., inside methods)
                    _visit(child, class_name)
                else:
                    _visit(child, class_name)

        _visit(tree, "")

        # Assign docstrings to symbols, preferring qualified key
        for sym in symbols:
            if sym.docstring:
                continue
            qid = qualify_symbol_name(sym.name, sym.parent_symbol)
            doc = doc_map.get(qid) or doc_map.get(sym.name)
            if doc:
                sym.docstring = doc


class ControlFlowExtractor:
    """
    Extracts a compressed control-flow skeleton for a single function or
    method, deterministically and without any LLM call.

    For a function body, this:
      1. Replaces straight-line statement runs with `...` (same spirit as
         ContextBuilder._skeletonize_node), but PRESERVES control structures
         (if/elif/else, try/except/finally, for, while) and the calls that
         sit directly inside them.
      2. Annotates branches with a deterministic role comment when a
         heuristic matches confidently (error path, fallback path, fast
         path). Branches that match nothing are left unannotated.
      3. Computes a body_hash from the exact source snippet
         [line_start, line_end] so the skeleton can be invalidated
         independently of sibling symbols in the same block and
         independently of the function's signature.

    Python only — see module-level discussion for why runtime
    instrumentation and bytecode introspection are not viable here
    (CodeAware never executes user-pasted code; many snippets are not even
    importable).
    """

    MAX_PARSE_SIZE_BYTES = SignatureExtractor.MAX_PARSE_SIZE_BYTES

    _CACHE_HIT_RE = re.compile(r"\b(cache|cached|memo)\w*\b", re.IGNORECASE)

    _CONTROL_LINE_RE = re.compile(
        r"^(\s*)(if\b|elif\b|else:|try:|except\b.*:|finally:|for\b|while\b|async for\b)"
    )

    # ═══════════════════════════════════════════════════════════════════
    # 1. Public entry point
    # ═══════════════════════════════════════════════════════════════════

    @staticmethod
    def extract_for_symbol(
        block_content: str,
        symbol: "CodeSymbol",
        max_lines: int = 40,
    ) -> Optional[Tuple[str, str]]:
        """
        Build the control-flow skeleton for one symbol.

        Returns (cfg_skeleton, body_hash), or None if:
          - the symbol isn't a function/method, or has no line_start/line_end;
          - the snippet exceeds max_lines (very long functions don't produce
            a "compressed" skeleton — they produce another wall of text);
          - the snippet doesn't parse as valid Python after dedent;
          - the function body has no control-flow nodes worth preserving.
        """
        if symbol.kind not in ("function", "method"):
            logger.debug(
                f"[CFG] SKIP: symbol kind is {symbol.kind}, not function/method"
            )
            return None
        if not symbol.line_start or not symbol.line_end:
            logger.debug(f"[CFG] SKIP: no line_start/line_end for {symbol.name}")
            return None
        if symbol.line_end - symbol.line_start > max_lines:
            logger.debug(
                f"[CFG] SKIP: line_count={symbol.line_end - symbol.line_start} > max_lines={max_lines}"
            )
            return None
        if len(block_content.encode()) > ControlFlowExtractor.MAX_PARSE_SIZE_BYTES:
            logger.debug(f"[CFG] SKIP: block_content exceeds MAX_PARSE_SIZE_BYTES")
            return None

        lines = block_content.split("\n")
        start_idx = max(0, symbol.line_start - 1)
        end_idx = min(len(lines), symbol.line_end)
        snippet = "\n".join(lines[start_idx:end_idx])

        if not snippet.strip():
            logger.debug(
                f"[CFG] SKIP: snippet is empty or whitespace only for {symbol.name}"
            )
            return None

        body_hash = hashlib.md5(snippet.encode()).hexdigest()[:16]

        # A method snippet sliced out of a class body starts indented
        # (e.g. "    def foo(...):"); dedent before parsing.
        dedented = textwrap.dedent(snippet)
        try:
            tree = ast.parse(dedented)
        except SyntaxError as e:
            logger.debug(f"[CFG] PARSE ERROR: {symbol.name} – {e}")
            return None

        func_node = next(
            (
                n
                for n in tree.body
                if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
            ),
            None,
        )
        if func_node is None:
            logger.debug(
                f"[CFG] SKIP: no FunctionDef/AsyncFunctionDef node found for {symbol.name}"
            )
            return None

        if not ControlFlowExtractor._has_control_flow(func_node):
            logger.debug(
                f"[CFG] SKIP: no control-flow (if/try/for/while) in body of {symbol.name}"
            )
            return None  # nothing to compress — LOD2 docstring already suffices

        role_queue: List[Optional[str]] = []
        func_node.body = ControlFlowExtractor._compress_stmt_list(
            func_node.body, role_queue
        )
        ast.fix_missing_locations(func_node)

        try:
            skeleton = ast.unparse(func_node)
        except Exception as e:
            logger.debug(f"[CFG] SKIP: ast.unparse failed for {symbol.name} – {e}")
            return None

        skeleton = ControlFlowExtractor._inject_role_comments(skeleton, role_queue)
        logger.debug(
            f"[CFG] SUCCESS: CFG generated for {symbol.name} (body_hash={body_hash})"
        )
        return skeleton, body_hash

    # ═══════════════════════════════════════════════════════════════════
    # 2. Control-flow detection
    # ═══════════════════════════════════════════════════════════════════

    @staticmethod
    def _has_control_flow(func_node: "ast.AST") -> bool:
        """True if the function body contains at least one branch worth
        preserving. A straight-line function gets no CFG tier."""
        for node in ast.walk(func_node):
            if node is func_node:
                continue
            if isinstance(node, (ast.If, ast.Try, ast.For, ast.While, ast.AsyncFor)):
                logger.debug(
                    f"[CFG] _has_control_flow: found control-flow node "
                    f"'{type(node).__name__}' in function"
                )
                return True
        logger.debug(
            "[CFG] _has_control_flow: no control-flow nodes found (straight-line function)"
        )
        return False

    # ═══════════════════════════════════════════════════════════════════
    # 3. Body compression (recursive AST rewrite)
    # ═══════════════════════════════════════════════════════════════════

    @staticmethod
    def _compress_stmt_list(
        stmts: List["ast.stmt"], role_queue: List[Optional[str]]
    ) -> List["ast.stmt"]:
        """
        Compress a list of statements by collapsing straight‑line runs into `...`,
        while preserving control‑flow statements (if, try, for, while) and
        call statements that appear as direct expressions.

        The `role_queue` is appended to during traversal in the same order that
        control‑keyword lines will appear in the final text output, enabling
        correct role comment injection after unparse().

        Returns a new list of AST statements with the same structure but with
        all non‑control bodies replaced by `...` or call placeholders.
        """
        out: List[ast.stmt] = []
        straight_run: List[ast.stmt] = []
        total_stmts = len(stmts)
        control_count = 0
        call_count = 0
        terminal_count = 0

        logger.debug(f"[CFG] _compress_stmt_list: processing {total_stmts} statements")

        def _flush_run() -> None:
            if straight_run:
                logger.debug(
                    f"[CFG] _compress_stmt_list: flushing straight-run of "
                    f"{len(straight_run)} statements"
                )
                out.append(ControlFlowExtractor._placeholder_for(straight_run))
                straight_run.clear()

        for stmt in stmts:
            if isinstance(stmt, ast.If):
                _flush_run()
                control_count += 1
                logger.debug("[CFG] _compress_stmt_list: found If statement")
                out.append(ControlFlowExtractor._compress_if(stmt, role_queue))
            elif isinstance(stmt, ast.Try):
                _flush_run()
                control_count += 1
                logger.debug("[CFG] _compress_stmt_list: found Try statement")
                out.append(ControlFlowExtractor._compress_try(stmt, role_queue))
            elif isinstance(stmt, (ast.For, ast.AsyncFor, ast.While)):
                _flush_run()
                control_count += 1
                logger.debug("[CFG] _compress_stmt_list: found Loop statement")
                out.append(ControlFlowExtractor._compress_loop(stmt, role_queue))
            elif isinstance(stmt, (ast.Return, ast.Raise)):
                _flush_run()
                terminal_count += 1
                logger.debug(
                    "[CFG] _compress_stmt_list: found terminal statement (return/raise)"
                )
                out.append(stmt)  # terminal — keep verbatim
            elif ControlFlowExtractor._is_call_statement(stmt):
                _flush_run()
                call_count += 1
                logger.debug("[CFG] _compress_stmt_list: found call statement")
                out.append(ControlFlowExtractor._call_placeholder(stmt))
            else:
                straight_run.append(stmt)
        _flush_run()

        logger.debug(
            f"[CFG] _compress_stmt_list: completed - "
            f"{len(out)} output statements, "
            f"{control_count} control structures, "
            f"{call_count} calls, "
            f"{terminal_count} terminals"
        )

        return out or [ast.Expr(value=ast.Constant(value=Ellipsis))]

    @staticmethod
    def _compress_if(node: "ast.If", role_queue: List[Optional[str]]) -> "ast.If":
        """
        Compress an `if` statement:
          - The `if` line itself gets a role from `_classify_if_role`.
          - The body is compressed recursively.
          - `elif` chains are preserved as nested `if` nodes.
          - Plain `else` blocks are compressed without role annotation.
        """
        logger.debug(
            f"[CFG] _compress_if: compressing If node "
            f"(has_orelse={bool(node.orelse)}, "
            f"body_len={len(node.body)})"
        )

        role_queue.append(ControlFlowExtractor._classify_if_role(node))
        new_body = ControlFlowExtractor._compress_stmt_list(node.body, role_queue)

        new_orelse: List[ast.stmt] = []
        if node.orelse:
            if len(node.orelse) == 1 and isinstance(node.orelse[0], ast.If):
                # elif chain — recurse; the nested call appends its own role.
                logger.debug(
                    "[CFG] _compress_if: elif chain detected (single If in orelse)"
                )
                new_orelse = [
                    ControlFlowExtractor._compress_if(node.orelse[0], role_queue)
                ]
            else:
                logger.debug(
                    f"[CFG] _compress_if: plain else block "
                    f"(orelse length {len(node.orelse)})"
                )
                role_queue.append(None)  # plain `else:` — never guess
                new_orelse = ControlFlowExtractor._compress_stmt_list(
                    node.orelse, role_queue
                )

        new_node = ast.If(test=node.test, body=new_body, orelse=new_orelse)
        ast.copy_location(new_node, node)
        logger.debug(
            f"[CFG] _compress_if: completed - "
            f"body={len(new_body)} stmts, "
            f"orelse={len(new_orelse)} stmts"
        )
        return new_node

    @staticmethod
    def _compress_try(node: "ast.Try", role_queue: List[Optional[str]]) -> "ast.Try":
        """
        Compress a `try` statement:
          - The `try:` line gets no role (queue None).
          - Each `except` handler gets a role from `_classify_except_role`.
          - `else:` and `finally:` blocks are compressed without role annotation.
        """
        logger.debug(
            f"[CFG] _compress_try: compressing Try node - "
            f"{len(node.handlers)} handlers, "
            f"has_orelse={bool(node.orelse)}, "
            f"has_finalbody={bool(node.finalbody)}"
        )

        role_queue.append(None)  # the `try:` line itself never gets a role
        new_body = ControlFlowExtractor._compress_stmt_list(node.body, role_queue)

        new_handlers: List[ast.ExceptHandler] = []
        for i, handler in enumerate(node.handlers):
            logger.debug(f"[CFG] _compress_try: processing handler {i+1}")
            role_queue.append(ControlFlowExtractor._classify_except_role(handler))
            new_handler_body = ControlFlowExtractor._compress_stmt_list(
                handler.body, role_queue
            )
            new_handler = ast.ExceptHandler(
                type=handler.type, name=handler.name, body=new_handler_body
            )
            ast.copy_location(new_handler, handler)
            new_handlers.append(new_handler)

        new_orelse: List[ast.stmt] = []
        if node.orelse:
            logger.debug("[CFG] _compress_try: processing else block")
            new_orelse = ControlFlowExtractor._compress_stmt_list(
                node.orelse, role_queue
            )

        new_finalbody: List[ast.stmt] = []
        if node.finalbody:
            logger.debug("[CFG] _compress_try: processing finally block")
            role_queue.append(None)
            new_finalbody = ControlFlowExtractor._compress_stmt_list(
                node.finalbody, role_queue
            )

        new_node = ast.Try(
            body=new_body,
            handlers=new_handlers,
            orelse=new_orelse,
            finalbody=new_finalbody,
        )
        ast.copy_location(new_node, node)
        logger.debug(
            f"[CFG] _compress_try: completed - "
            f"body={len(new_body)} stmts, "
            f"{len(new_handlers)} handlers, "
            f"orelse={len(new_orelse)} stmts, "
            f"finalbody={len(new_finalbody)} stmts"
        )
        return new_node

    @staticmethod
    def _compress_loop(node, role_queue: List[Optional[str]]):
        """
        Compress a `for`, `async for`, or `while` loop:
          - The loop header line gets no role (queue None).
          - The body is compressed recursively.
          - An `else:` clause on the loop (if present) is compressed without role.
        """
        loop_type = type(node).__name__
        logger.debug(
            f"[CFG] _compress_loop: compressing {loop_type} node "
            f"(has_orelse={bool(node.orelse)})"
        )

        role_queue.append(None)  # loops never get an automatic role in v1
        new_body = ControlFlowExtractor._compress_stmt_list(node.body, role_queue)
        new_orelse = (
            ControlFlowExtractor._compress_stmt_list(node.orelse, role_queue)
            if node.orelse
            else []
        )
        cls = type(node)
        kwargs = dict(body=new_body, orelse=new_orelse)
        if hasattr(node, "target"):
            kwargs["target"] = node.target
            kwargs["iter"] = node.iter
        if hasattr(node, "test"):
            kwargs["test"] = node.test
        new_node = cls(**kwargs)
        ast.copy_location(new_node, node)

        logger.debug(
            f"[CFG] _compress_loop: completed {loop_type} - "
            f"body={len(new_body)} stmts, "
            f"orelse={len(new_orelse)} stmts"
        )
        return new_node

    # ═══════════════════════════════════════════════════════════════════
    # 4. Call & straight-run placeholders
    # ═══════════════════════════════════════════════════════════════════

    @staticmethod
    def _is_call_statement(stmt: "ast.stmt") -> bool:
        """Return True if `stmt` is an expression statement or assignment
        whose right‑hand side is a function call."""
        is_call = False
        if isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Call):
            is_call = True
        elif isinstance(stmt, ast.Assign) and isinstance(stmt.value, ast.Call):
            is_call = True

        if is_call:
            logger.debug("[CFG] _is_call_statement: detected call statement")
        else:
            logger.debug("[CFG] _is_call_statement: not a call statement")
        return is_call

    @staticmethod
    def _call_placeholder(stmt: "ast.stmt") -> "ast.stmt":
        """Keep the call's name, drop its arguments to `...` — the point is
        showing WHICH call happens in WHICH branch, not its exact inputs
        (that's LOD3 detail)."""
        call_node = stmt.value
        has_args = bool(call_node.args or call_node.keywords)

        logger.debug(
            f"[CFG] _call_placeholder: creating placeholder for call to "
            f"'{ast.unparse(call_node.func)[:50]}' "
            f"(has_args={has_args})"
        )

        new_call = ast.Call(
            func=call_node.func,
            args=[ast.Constant(value=Ellipsis)] if has_args else [],
            keywords=[],
        )
        ast.copy_location(new_call, call_node)
        if isinstance(stmt, ast.Assign):
            new_stmt = ast.Assign(targets=stmt.targets, value=new_call)
        else:
            new_stmt = ast.Expr(value=new_call)
        ast.copy_location(new_stmt, stmt)
        return new_stmt

    @staticmethod
    def _placeholder_for(straight_run: List["ast.stmt"]) -> "ast.stmt":
        """Collapse a run of non-control statements into a single `...`."""
        logger.debug(
            f"[CFG] _placeholder_for: collapsing straight-run of "
            f"{len(straight_run)} statements to '...'"
        )
        placeholder = ast.Expr(value=ast.Constant(value=Ellipsis))
        ast.copy_location(placeholder, straight_run[0])
        return placeholder

    # ═══════════════════════════════════════════════════════════════════
    # 5. Role comment injection (post-unparse text pass)
    # ═══════════════════════════════════════════════════════════════════

    @staticmethod
    def _inject_role_comments(
        skeleton_text: str,
        role_queue: List[Optional[str]],
    ) -> str:
        """
        Replace cache-hit placeholder tokens in skeleton_text with role-label
        comments drawn from role_queue.

        role_queue is consumed left-to-right: each regex match pops one entry.
        If skeleton_text contains more matches than role_queue has entries (e.g.
        because ast.unparse produced a symbol name that incidentally matches the
        pattern), the excess matches are replaced with an empty comment rather
        than raising IndexError.

        Steps:
            1.  Build a mutable copy of role_queue so the original is not modified.
            2.  Define a replacement callback that pops from the copy, or returns
                an empty comment on underflow.
            3.  Apply the substitution and return.
        """
        if not skeleton_text:
            return skeleton_text

        # -- Step 1: mutable copy --
        queue: List[Optional[str]] = list(role_queue)

        # -- Step 2: replacement callback with underflow guard --
        def _replace(m: "re.Match") -> str:
            if not queue:
                # More matches than expected — inject a neutral placeholder
                # rather than crashing.
                return "# ..."
            role = queue.pop(0)
            if role:
                return f"# [{role}]"
            return "# ..."

        # -- Step 3: substitute --
        try:
            result = ControlFlowExtractor._CACHE_HIT_RE.sub(_replace, skeleton_text)
        except Exception:
            result = skeleton_text

        return result

    @staticmethod
    def _classify_if_role(if_node: "ast.If") -> Optional[str]:
        """'fast path' if the test mentions cache/memo AND the body returns
        directly. Any other `if` is left unlabeled — we never guess."""
        if not hasattr(ast, "unparse"):
            logger.debug("[CFG] _classify_if_role: ast.unparse not available")
            return None

        test_src = ast.unparse(if_node.test)
        body_has_return = any(isinstance(s, ast.Return) for s in if_node.body)

        logger.debug(
            f"[CFG] _classify_if_role: test='{test_src[:80]}', "
            f"body_has_return={body_has_return}"
        )

        if body_has_return and ControlFlowExtractor._CACHE_HIT_RE.search(test_src):
            logger.debug(
                f"[CFG] _classify_if_role: MATCH fast path (test mentions cache/memo)"
            )
            return "fast path"
        else:
            if not body_has_return:
                logger.debug(
                    "[CFG] _classify_if_role: no fast path (body does not return directly)"
                )
            elif not ControlFlowExtractor._CACHE_HIT_RE.search(test_src):
                logger.debug(
                    "[CFG] _classify_if_role: no fast path (test does not mention cache/memo)"
                )
        return None

    @staticmethod
    def _classify_except_role(handler: "ast.ExceptHandler") -> str:
        """'fallback path' if the handler returns an alternative value without
        re-raising; 'error path' in any other case (includes re-raise, log +
        pass, etc.). Unlike _classify_if_role, an except ALWAYS receives a role
        — there is no real ambiguity about whether an except is error handling."""
        has_raise = any(isinstance(s, ast.Raise) for s in handler.body)
        has_return_value = any(
            isinstance(s, ast.Return) and s.value is not None for s in handler.body
        )

        logger.debug(
            f"[CFG] _classify_except_role: has_raise={has_raise}, "
            f"has_return_value={has_return_value}"
        )

        if has_return_value and not has_raise:
            logger.debug("[CFG] _classify_except_role: MATCH fallback path")
            return "fallback path"
        else:
            logger.debug("[CFG] _classify_except_role: MATCH error path")
            return "error path"


class ReentrantAsyncLock:
    """Reentrant asyncio lock with optional timeout to prevent deadlocks."""

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Initialization
    # ═══════════════════════════════════════════════════════════════════════════

    def __init__(self, default_timeout: float = 60.0) -> None:
        """*default_timeout* applies to every ``acquire()`` call that doesn't
        specify its own timeout."""
        self._lock = asyncio.Lock()
        self._owner: Optional[asyncio.Task] = None
        self._count = 0
        self._default_timeout = default_timeout

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Core synchronization methods
    # ═══════════════════════════════════════════════════════════════════════════

    async def acquire(self, timeout: Optional[float] = None) -> None:
        """Acquire the lock, reentrantly if already held by the current task.
        *timeout* overrides the instance default."""
        task = asyncio.current_task()
        if self._owner is task:
            self._count += 1
            return
        effective_timeout = timeout if timeout is not None else self._default_timeout
        if effective_timeout is not None:
            await asyncio.wait_for(self._lock.acquire(), timeout=effective_timeout)
        else:
            await self._lock.acquire()
        self._owner = task
        self._count = 1

    def release(self) -> None:
        """Release the lock once.  Raises ``RuntimeError`` if the current
        task does not own the lock."""
        task = asyncio.current_task()
        if self._owner is not task:
            raise RuntimeError("Lock not owned by current task")
        self._count -= 1
        if self._count == 0:
            self._owner = None
            self._lock.release()

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Async context manager support
    # ═══════════════════════════════════════════════════════════════════════════

    async def __aenter__(self):
        """Async context manager entry."""
        await self.acquire()
        return self

    async def __aexit__(self, *args) -> None:
        """Async context manager exit."""
        self.release()


class StateStore:
    """
    SQLite database infrastructure for the CodeAware filter.

    This class manages:
      - DDL (table creation, indexes)
      - Serialized write queue (prevents "database is locked" errors)
      - Per-project async locks
      - Persistence of symbol edges, path views, docstrings, CFG skeletons
      - Database checkpoints (WAL)
      - Purge of orphaned rows

    It does NOT manage conversation state (→ ConversationStateManager).
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the state store with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Database lifecycle (DDL, connection, worker)
    # ═══════════════════════════════════════════════════════════════════════
    def init_db(self) -> None:
        """
        Create all necessary tables and indexes (idempotent).

        Called once during Filter initialization. In addition to creating the
        schema, this method tunes SQLite's runtime behaviour to minimise
        contention:
          - `busy_timeout` – tells SQLite to wait up to `llm_per_call_timeout`
            seconds before giving up on a locked database.
          - `synchronous = NORMAL` – reduces the number of `fsync()` calls,
            increasing throughput under write-heavy workloads without compromising
            crash safety, because WAL already guarantees durability.

        This method also creates the `acquire_write` table used by the OpenWebUI
        framework's SQLite-based locking mechanism. The "no such table: acquire_write"
        error is resolved by creating this table with the appropriate schema.

        Returns:
            None. The database connection is stored as `self._f._db_conn`.
        """
        db_path = self._f.valves.state_db_path
        os.makedirs(os.path.dirname(db_path), exist_ok=True)

        # ------------------------------------------------------------------
        # REGION 1 — Connect and set busy_timeout
        # ------------------------------------------------------------------
        self._f._db_conn = sqlite3.connect(db_path, check_same_thread=False)
        self._f._db_conn.execute(
            f"PRAGMA busy_timeout = {self._f.valves.llm_per_call_timeout * 1000}"
        )

        # ------------------------------------------------------------------
        # REGION 2 — Reduce fsync pressure to lower lock contention
        # ------------------------------------------------------------------
        # 'NORMAL' syncs at critical moments (e.g., WAL checkpoint) but not
        # on every transaction commit. This is safe with WAL and dramatically
        # reduces the chance of "database is locked" under concurrent writes.
        self._f._db_conn.execute("PRAGMA synchronous = NORMAL")

        # ------------------------------------------------------------------
        # REGION 3 — Create all tables and indexes (idempotent)
        # ------------------------------------------------------------------

        # --- Framework lock table (required to avoid "no such table: acquire_write") ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS acquire_write (
                key TEXT PRIMARY KEY,
                owner TEXT,
                acquired_at REAL
            )
        """)

        # --- Main conversation state table ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS conversation_state (
                project_id TEXT PRIMARY KEY,
                state_json TEXT NOT NULL,
                updated_at REAL NOT NULL
            )
        """)

        # --- Code content storage (externalized from state JSON) ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS code_contents (
                hash TEXT PRIMARY KEY,
                content TEXT NOT NULL,
                created_at REAL NOT NULL
            )
        """)

        # --- Enable WAL mode for better concurrency ---
        self._f._db_conn.execute("PRAGMA journal_mode=WAL")

        # --- Block change summaries (for change tracking) ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS block_change_summaries (
                block_hash TEXT PRIMARY KEY,
                summary TEXT NOT NULL,
                created_at REAL NOT NULL
            )
        """)

        # --- Code path views (cached subgraph projections) ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS code_path_views (
                path_id             TEXT NOT NULL,
                project_id          TEXT NOT NULL,
                entry_point         TEXT NOT NULL,
                seed_nodes_json     TEXT NOT NULL DEFAULT '[]',
                induced_nodes_json  TEXT NOT NULL DEFAULT '{}',
                induced_edges_json  TEXT NOT NULL DEFAULT '[]',
                activation_score    REAL NOT NULL DEFAULT 0.0,
                business_label      TEXT NOT NULL DEFAULT '',
                summary             TEXT NOT NULL DEFAULT '',
                label_confidence    REAL NOT NULL DEFAULT 0.0,
                structural_hash     TEXT NOT NULL DEFAULT '',
                call_graph_hash     TEXT NOT NULL DEFAULT '',
                last_built          REAL NOT NULL,
                PRIMARY KEY (path_id, project_id)
            )
        """)
        self._f._db_conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_cpv_project "
            "ON code_path_views(project_id)"
        )

        # --- Symbol edges (call graph, data flow, etc.) ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS symbol_edges (
                project_id  TEXT NOT NULL,
                src         TEXT NOT NULL,
                dst         TEXT NOT NULL,
                type        TEXT NOT NULL,
                weight      REAL NOT NULL DEFAULT 1.0,
                confidence  REAL NOT NULL DEFAULT 1.0,
                PRIMARY KEY (project_id, src, dst, type)
            )
        """)
        self._f._db_conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_edges_project_src "
            "ON symbol_edges(project_id, src)"
        )

        # --- RAPTOR clusters (hierarchical summarization) ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS raptor_clusters (
                cluster_id      TEXT PRIMARY KEY,
                project_id      TEXT NOT NULL,
                level           INTEGER NOT NULL,
                member_ids_json TEXT NOT NULL,
                summary         TEXT NOT NULL,
                centroid_json   TEXT,
                created_at      REAL NOT NULL
            )
        """)
        self._f._db_conn.execute(
            "CREATE INDEX IF NOT EXISTS idx_raptor_project_level "
            "ON raptor_clusters(project_id, level)"
        )

        # --- Edges metadata (for invalidation detection) ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS symbol_edges_meta (
                project_id      TEXT PRIMARY KEY,
                code_state_hash TEXT NOT NULL,
                edge_count      INTEGER NOT NULL DEFAULT 0,
                saved_at        REAL NOT NULL
            )
        """)

        # --- Symbol docstrings (persisted cache) ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS symbol_docstrings (
                project_id  TEXT NOT NULL,
                symbol_name TEXT NOT NULL,
                docstring   TEXT NOT NULL,
                updated_at  REAL NOT NULL,
                PRIMARY KEY (project_id, symbol_name)
            )
        """)

        # --- Control-flow skeletons (CFG) cache ---
        self._f._db_conn.execute("""
            CREATE TABLE IF NOT EXISTS symbol_cfg (
                project_id   TEXT NOT NULL,
                symbol_name  TEXT NOT NULL,
                cfg_skeleton TEXT NOT NULL,
                body_hash    TEXT NOT NULL,
                updated_at   REAL NOT NULL,
                PRIMARY KEY (project_id, symbol_name)
            )
        """)

        self._f._db_conn.commit()

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Database write queue (serialised, non-blocking writes)
    # ═══════════════════════════════════════════════════════════════════════

    async def _db_enqueue(
        self,
        fn,
        args: tuple = (),
        kwargs: Optional[dict] = None,
    ) -> None:
        """
        Enqueue a synchronous database write for the background DB worker.

        Uses asyncio.wait_for around queue.put() to implement backpressure:
        if the queue is full (DB worker can't keep up), callers block for up
        to db_enqueue_timeout seconds before the write is dropped with a
        warning. This prevents unbounded memory growth when SQLite is slow
        (WAL checkpoint running, disk saturation) at the cost of occasionally
        dropping non-critical writes.

        Critical writes (e.g. from drain_writes paths) should use wait=True
        with a longer timeout. Background writes (metrics, optional caches)
        should tolerate occasional drops.

        The queue must be initialised with a maxsize. If the queue was created
        without one (pre-fix), this method re-creates it with the configured
        maxsize on first call — a one-time migration compatible with existing
        code that creates the queue in __init__.

        Steps:
            1.  Ensure the queue has a maxsize (migrate if necessary).
            2.  Attempt to put with timeout.
            3.  Log and drop on timeout rather than blocking indefinitely.
        """
        if kwargs is None:
            kwargs = {}

        # -- Step 1: migrate unbounded queue if necessary --
        current_queue = self._f._db_write_queue
        if current_queue.maxsize == 0:
            max_q = getattr(self._f.valves, "db_write_queue_maxsize", 500)
            new_q: asyncio.Queue = asyncio.Queue(maxsize=max_q)
            # Drain pending items from the old unbounded queue into the new one
            while not current_queue.empty():
                try:
                    item = current_queue.get_nowait()
                    try:
                        new_q.put_nowait(item)
                    except asyncio.QueueFull:
                        break  # new queue already at capacity; drop oldest items
                except asyncio.QueueEmpty:
                    break
            self._f._db_write_queue = new_q
            current_queue = new_q
            self._f._log_debug(
                f"StateStore._db_enqueue: migrated to bounded queue "
                f"(maxsize={max_q})"
            )

        # -- Step 2: attempt put with timeout --
        timeout = getattr(self._f.valves, "db_enqueue_timeout", 10.0)
        try:
            await asyncio.wait_for(
                current_queue.put((fn, args, kwargs)),
                timeout=timeout,
            )
        except asyncio.TimeoutError:
            # -- Step 3: log and drop --
            qsize = current_queue.qsize()
            self._f._log_debug(
                f"StateStore._db_enqueue: queue full after {timeout}s "
                f"(size={qsize}/{current_queue.maxsize}), dropping write. "
                f"DB worker may be stalled. Check disk I/O and WAL size."
            )

    async def db_worker(self) -> None:
        """Database write worker with automatic restart on failure."""
        while True:
            try:
                await self._db_worker_loop()
            except asyncio.CancelledError:
                self._f._log_debug("DB worker cancelled — shutting down.")
                break
            except Exception as e:
                self._f._log_debug(f"DB worker crashed: {e} — restarting in 2s")
                await asyncio.sleep(2)

    async def drain_writes(self, timeout: float = 5.0) -> None:
        """
        Blocks until all pending items in _db_write_queue have been processed
        (task_done called by the worker).

        Called at the start of each inlet to ensure that docstring writes from
        the previous turn finish BEFORE inlet_preprocess() starts reading from
        SQLite. Eliminates reader/writer overlap on _db_conn.

        Args:
            timeout: maximum seconds to wait. If timeout elapses, logs and
                     continues (soft degradation, no exception).
        """
        try:
            await asyncio.wait_for(self._f._db_write_queue.join(), timeout=timeout)
        except asyncio.TimeoutError:
            self._f._log_debug(
                f"drain_writes: timeout {timeout}s; "
                "writes still in progress, continuing (soft degradation)"
            )

    async def _db_read(self, fn, *args, **kwargs):
        """
        Serialized read with the writer worker.

        While all access to _db_conn goes through _db_global_lock,
        two threads cannot touch the connection simultaneously, and
        "database is locked" disappears as a race condition.

        The lock is acquired INSIDE the thread (run_sync), not crossing
        an await, to avoid blocking the event loop.

        Usage:
            row = await self._f._state_store._db_read(
                lambda: self._f._db_conn.execute(sql, params).fetchone()
            )
        """

        def _run():
            with _db_global_lock:
                return fn(*args, **kwargs)

        return await anyio.to_thread.run_sync(_run)

    async def _db_worker_loop(self) -> None:
        """
        Single run of the DB write loop. Exits on CancelledError.
        """
        while True:
            try:
                job = await asyncio.wait_for(self._f._db_write_queue.get(), timeout=1.0)
            except asyncio.TimeoutError:
                continue
            except asyncio.CancelledError:
                raise

            func, args, kwargs = job

            def _run_batch(fn=func, a=args, kw=kwargs):
                with _db_global_lock:
                    fn(*a, **kw)

            try:
                for attempt in range(5):
                    try:
                        await anyio.to_thread.run_sync(_run_batch)
                        break  # success
                    except sqlite3.OperationalError as e:
                        if "locked" in str(e).lower() and attempt < 4:
                            backoff = 0.1 * (2**attempt)
                            self._f._log_debug(
                                f"DB worker: locked (attempt {attempt+1}/5), "
                                f"retrying in {backoff:.1f}s"
                            )
                            await asyncio.sleep(backoff)
                        else:
                            self._f._log_debug(
                                f"DB worker: job dropped after {attempt+1} attempts: {e}"
                            )
                            break
                    except Exception as e:
                        self._f._log_debug(
                            f"DB worker: unexpected error, dropping job: "
                            f"{type(e).__name__}: {e}"
                        )
                        break
            finally:
                self._f._db_write_queue.task_done()

    def _db_conn_write_sync(self, project_id: str, state: ConversationState) -> None:
        """
        Synchronous write of ConversationState to SQLite (used by LRU eviction).

        This method bypasses the async queue and writes directly to the DB.
        It is only intended for emergency flushes during eviction to avoid data loss.

        Args:
            project_id: The project identifier.
            state: The ConversationState to persist.
        """
        # Serialize the state (logic mirrored from _save_to_db)
        active_blocks_meta = {}
        for k, v in state.active_blocks.items():
            d = v.dict()
            d["content_type"] = v.content_type.value
            content_hash = v.hash
            # Insert content if not present (synchronous)
            self._f._db_conn.execute(
                "INSERT OR IGNORE INTO code_contents (hash, content, created_at) VALUES (?, ?, ?)",
                (content_hash, v.content, time.time()),
            )
            d["content"] = f"@@hash:{content_hash}"
            active_blocks_meta[k] = d

        serializable = {
            "active_blocks": active_blocks_meta,
            "recent_changes": [b.dict() for b in state.recent_changes],
            "committed_changes": [b.dict() for b in state.committed_changes],
            "feedback_history": [fb.dict() for fb in state.feedback_history],
            "message_count": state.message_count,
            "last_compression_timestamp": state.last_compression_timestamp,
            "last_suggestion_timestamp": state.last_suggestion_timestamp,
            "last_cleanup_suggestion_msg_idx": state.last_cleanup_suggestion_msg_idx,
            "has_any_calls": state.has_any_calls,
            "last_cot_level": state.last_cot_level,
            "conversation_summaries": state.conversation_summaries,
            "summarized_turn_hwm": state.summarized_turn_hwm,
            "history_blocked_age": state.history_blocked_age,
            "wm_fired": state.wm_fired,
            "wm_msgs_evicted": state.wm_msgs_evicted,
            "wm_turns_evicted": state.wm_turns_evicted,
            "wm_summary_ok": state.wm_summary_ok,
            "wm_emergency_cap": state.wm_emergency_cap,
            "wm_batch_too_small": state.wm_batch_too_small,
            "wm_no_slot": state.wm_no_slot,
            "wm_degradation_guard": state.wm_degradation_guard,
            "pending_slot_resave": state.pending_slot_resave,
        }

        self._f._db_conn.execute(
            "REPLACE INTO conversation_state (project_id, state_json, updated_at) VALUES (?, ?, ?)",
            (project_id, json.dumps(serializable), time.time()),
        )
        self._f._db_conn.commit()

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Maintenance (checkpoints)
    # ═══════════════════════════════════════════════════════════════════════

    async def run_db_checkpoints(self) -> None:
        """
        Periodically flush the SQLite WAL (Write-Ahead Log) to the main database
        file to prevent unbounded WAL growth.

        Uses PASSIVE checkpoint mode which frames checkpoint as best-effort:
        it checkpoints as many WAL frames as possible without waiting for active
        readers to finish. This is appropriate for a server process with
        continuous concurrent reads.

        FULL and TRUNCATE modes block until all readers complete, which in this
        system means holding _db_global_lock for potentially seconds while LTM
        retrieval, edge loading, and state reads are in progress — effectively
        serialising all writes behind the checkpoint.

        Checkpoints are skipped when the WAL is below wal_checkpoint_min_frames
        to avoid unnecessary I/O on idle projects.

        Steps:
            1.  Check WAL size; skip if below threshold.
            2.  Run PASSIVE checkpoint via the write thread.
            3.  Log frames checkpointed and frames remaining.
            4.  Sleep until next checkpoint interval.
        """
        interval = getattr(self._f.valves, "db_checkpoint_interval_seconds", 30.0)
        min_frames = getattr(self._f.valves, "wal_checkpoint_min_frames", 100)

        while True:
            await asyncio.sleep(interval)

            try:
                # -- Step 1: check WAL frame count --
                def _wal_size() -> int:
                    with _db_global_lock:
                        row = self._f._db_conn.execute(
                            "PRAGMA wal_checkpoint(PASSIVE)"
                        ).fetchone()
                        # row: (busy, log, checkpointed)
                        # Return log (total frames in WAL)
                        return row[1] if row else 0

                wal_frames = await anyio.to_thread.run_sync(_wal_size)

                if wal_frames < min_frames:
                    self._f._log_debug(
                        f"run_db_checkpoints: WAL has {wal_frames} frames "
                        f"(< {min_frames}), skipping"
                    )
                    continue

                # -- Steps 2-3: PASSIVE checkpoint already ran above;
                #    re-run for logging of result --
                def _checkpoint() -> Tuple[int, int, int]:
                    with _db_global_lock:
                        row = self._f._db_conn.execute(
                            "PRAGMA wal_checkpoint(PASSIVE)"
                        ).fetchone()
                        return tuple(row) if row else (0, 0, 0)

                busy, log_frames, ckpt_frames = await anyio.to_thread.run_sync(
                    _checkpoint
                )

                self._f._log_debug(
                    f"run_db_checkpoints: PASSIVE checkpoint complete — "
                    f"log={log_frames} frames, checkpointed={ckpt_frames}, "
                    f"busy_readers={busy}"
                )

                if busy > 0:
                    self._f._log_debug(
                        f"run_db_checkpoints: {busy} active reader(s) prevented "
                        f"full checkpoint; {log_frames - ckpt_frames} frames remain in WAL"
                    )

            except asyncio.CancelledError:
                raise
            except Exception as e:
                self._f._log_debug(
                    f"run_db_checkpoints: failed: {type(e).__name__}: {e}"
                )

    # ═══════════════════════════════════════════════════════════════════════
    # 4. Edge persistence
    # ═══════════════════════════════════════════════════════════════════════

    async def save_symbol_edges_to_db(self, project_id: str) -> int:
        """
        Persist typed edges from the SymbolIndex to SQLite.

        Saves alongside the current code_state_hash for invalidation detection.
        Returns the number of edges saved.

        Args:
            project_id: The current project identifier.

        Returns:
            int: Number of edges persisted.
        """
        if not self._f.valves.enable_edge_persistence:
            return 0

        edges_out = self._f._symbol_index.get_all_edges_out(project_id)
        if not edges_out:
            return 0

        code_hash = self._f._activation.compute_code_state_hash(project_id)
        if not code_hash:
            return 0

        total_edges = sum(len(edges) for edges in edges_out.values())

        def _write():
            self._f._db_conn.execute(
                "DELETE FROM symbol_edges WHERE project_id = ?", (project_id,)
            )
            for src, edges in edges_out.items():
                for edge in edges:
                    self._f._db_conn.execute(
                        "INSERT OR REPLACE INTO symbol_edges "
                        "(project_id, src, dst, type, weight, confidence) "
                        "VALUES (?,?,?,?,?,?)",
                        (
                            project_id,
                            edge.src,
                            edge.dst,
                            edge.type,
                            edge.weight,
                            edge.confidence,
                        ),
                    )
            self._f._db_conn.execute(
                "INSERT OR REPLACE INTO symbol_edges_meta "
                "(project_id, code_state_hash, edge_count, saved_at) "
                "VALUES (?,?,?,?)",
                (project_id, code_hash, total_edges, time.time()),
            )
            self._f._db_conn.commit()

        await self._db_enqueue(_write)
        self._f._log_debug(
            f"Edge persistence: saved {total_edges} edges (code_hash={code_hash})"
        )
        return total_edges

    async def load_symbol_edges_from_db(self, project_id: str) -> int:
        """
        Restore typed edges from SQLite into the SymbolIndex.

        Restoration is skipped only when the in-memory edge count already matches
        the count recorded in symbol_edges_meta, indicating a complete set is
        present. A partial in-memory set (e.g. only 'calls' edges rebuilt by
        _rebuild_symbol_index on cold load) does not prevent restoration.

        add_edge is idempotent, so edges that already exist in memory are safely
        re-added without creating duplicates.

        Returns the number of edges restored, or 0 if restoration was skipped or
        the saved metadata is stale relative to the current code state.
        """
        if not self._f.valves.enable_edge_persistence:
            return 0

        # -- Step 1: validate code state hash --
        current_code_hash = self._f._activation.compute_code_state_hash(project_id)
        if not current_code_hash:
            return 0

        # -- Step 2: read saved metadata --
        meta_row = await self._db_read(
            lambda: self._f._db_conn.execute(
                "SELECT code_state_hash, edge_count FROM symbol_edges_meta "
                "WHERE project_id = ?",
                (project_id,),
            ).fetchone()
        )

        if not meta_row:
            self._f._log_debug("Edge persistence: no saved edges for this project")
            return 0

        saved_hash, saved_count = meta_row
        if saved_hash != current_code_hash:
            self._f._log_debug(
                f"Edge persistence: stale edges detected "
                f"(saved={saved_hash}, current={current_code_hash}). "
                f"Edges will be rebuilt when code is processed."
            )
            return 0

        # -- Step 3: compare in-memory count against saved count --
        # _rebuild_symbol_index populates only 'calls' edges on cold load,
        # so in_memory_count < saved_count signals an incomplete restore.
        existing = self._f._symbol_index.get_all_edges_out(project_id)
        in_memory_count = sum(len(edges) for edges in existing.values())
        if in_memory_count >= saved_count:
            self._f._log_debug(
                f"Edge persistence: in-memory count ({in_memory_count}) matches "
                f"saved count ({saved_count}), skipping reload"
            )
            return 0

        # -- Step 4: fetch and register all saved edges --
        rows = await self._db_read(
            lambda: self._f._db_conn.execute(
                "SELECT src, dst, type, weight, confidence "
                "FROM symbol_edges WHERE project_id = ?",
                (project_id,),
            ).fetchall()
        )

        count = 0
        for src, dst, etype, weight, confidence in rows:
            edge = Edge(
                src=src,
                dst=dst,
                type=etype,
                weight=weight,
                confidence=confidence,
            )
            self._f._symbol_index.add_edge(edge, project_id)
            count += 1

        self._f._log_debug(
            f"✓ Edge persistence: restored {count} edges "
            f"(code_hash={current_code_hash})"
        )
        return count

    # ═══════════════════════════════════════════════════════════════════════
    # 5. Path view persistence
    # ═══════════════════════════════════════════════════════════════════════

    async def save_path_views_to_db(self, project_id: str, views: list) -> None:
        """
        Persist CodePathViews to SQLite, replacing any existing views for the project.

        Args:
            project_id: The current project identifier.
            views: List of CodePathView objects to persist.
        """

        def _write():
            self._f._db_conn.execute(
                "DELETE FROM code_path_views WHERE project_id = ?", (project_id,)
            )
            for v in views:
                self._f._db_conn.execute(
                    "INSERT INTO code_path_views VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (
                        v.path_id,
                        project_id,
                        v.entry_point,
                        json.dumps(v.seed_nodes),
                        json.dumps(v.induced_nodes),
                        json.dumps([e.dict() for e in v.induced_edges]),
                        v.activation_score,
                        v.business_label,
                        v.summary,
                        v.label_confidence,
                        v.structural_hash,
                        v.call_graph_hash,
                        v.last_built,
                    ),
                )
            self._f._db_conn.commit()

        await self._db_enqueue(_write)

    async def load_path_views_from_db(self, project_id: str) -> list:
        """
        Load CodePathViews from SQLite for a project.

        Args:
            project_id: The current project identifier.

        Returns:
            list: List of CodePathView objects (may be empty).
        """
        rows = await self._db_read(
            lambda: self._f._db_conn.execute(
                "SELECT path_id, entry_point, seed_nodes_json, induced_nodes_json, "
                "induced_edges_json, activation_score, business_label, summary, "
                "label_confidence, structural_hash, call_graph_hash, last_built "
                "FROM code_path_views WHERE project_id = ?",
                (project_id,),
            ).fetchall()
        )
        views = []
        for row in rows:
            try:
                induced_edges = [Edge(**e) for e in json.loads(row[4])]
                views.append(
                    CodePathView(
                        path_id=row[0],
                        entry_point=row[1],
                        seed_nodes=json.loads(row[2]),
                        induced_nodes=json.loads(row[3]),
                        induced_edges=induced_edges,
                        activation_score=row[5],
                        business_label=row[6],
                        summary=row[7],
                        label_confidence=row[8],
                        structural_hash=row[9],
                        call_graph_hash=row[10],
                        last_built=row[11],
                    )
                )
            except Exception as e:
                self._f._log_debug(f"Skipping corrupt CodePathView: {e}")
        return views

    # ═══════════════════════════════════════════════════════════════════════
    # 6. Orphan data cleanup
    # ═══════════════════════════════════════════════════════════════════════

    async def purge_orphaned_data(self, project_id: str) -> int:
        """
        Remove rows from code_contents, symbol_docstrings, and symbol_cfg
        that no longer correspond to active blocks or symbols.

        Returns the total number of rows deleted.

        Args:
            project_id: The current project identifier.

        Returns:
            int: Total number of rows purged.
        """
        state = self._f._conversation_state_manager.get(project_id)
        if (
            not state.active_blocks
            and not self._f._symbol_index.get_all_qualified_names(project_id)
        ):
            return 0

        active_qids = self._f._symbol_index.get_all_qualified_names(project_id)
        active_hashes = set(state.active_blocks.keys())

        total_deleted = 0

        def _purge():
            nonlocal total_deleted
            conn = self._f._db_conn

            if active_hashes:
                placeholders = ",".join("?" * len(active_hashes))
                cursor = conn.execute(
                    f"DELETE FROM code_contents WHERE hash NOT IN ({placeholders})",
                    tuple(active_hashes),
                )
                total_deleted += cursor.rowcount

            if active_qids:
                placeholders = ",".join("?" * len(active_qids))
                cursor = conn.execute(
                    f"DELETE FROM symbol_docstrings WHERE project_id = ? "
                    f"AND symbol_name NOT IN ({placeholders})",
                    (project_id,) + tuple(active_qids),
                )
                total_deleted += cursor.rowcount

                cursor = conn.execute(
                    f"DELETE FROM symbol_cfg WHERE project_id = ? "
                    f"AND symbol_name NOT IN ({placeholders})",
                    (project_id,) + tuple(active_qids),
                )
                total_deleted += cursor.rowcount

            conn.commit()

        await self._db_enqueue(_purge)
        if total_deleted > 0:
            self._f._log_debug(f"Purged {total_deleted} orphaned rows from DB")
        return total_deleted

    # ═══════════════════════════════════════════════════════════════════════
    # 7. Per‑project locks (reentrant async locks)
    # ═══════════════════════════════════════════════════════════════════════

    async def get_project_lock(self, project_id: str) -> ReentrantAsyncLock:
        """
        Return (or create) the reentrant async lock for the given project.

        Args:
            project_id: The project identifier.

        Returns:
            ReentrantAsyncLock: The lock instance.
        """
        async with self._f._lock_lock:
            if project_id not in self._f._project_locks:
                self._f._project_locks[project_id] = ReentrantAsyncLock()
            return self._f._project_locks[project_id]


class LongTermMemory:
    """Manages long‑term conversational and code memory using ChromaDB.

    Provides:
    * Storage and retrieval of user/assistant messages indexed by project
      and enriched with code symbols, file paths, and content type.
    * A response cache that avoids redundant LLM calls when semantically
      similar queries are repeated under the same code state.
    * Duplicate question detection using cosine similarity and optional
      CrossEncoder reranking.
    * Time‑bounded expiration of old memories.

    Docs 10–13 backported:
        M1 – strip <details> reasoning before embedding.
        M2 – skip partial multi‑phase assistant responses.
        C1 – apply similarity threshold on raw score, not decayed.
        C2 – deduplicate fragments by document ID.
        C3 – purge_project.
        C4 – validate embedding model dimension on startup.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """Initialize with a reference to the parent Filter."""
        self._f = filter_ref
        self._retrieval_disabled_reason: Optional[str] = None

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Initialization
    # ═══════════════════════════════════════════════════════════════════════════

    def init(self) -> None:
        """Initialise ChromaDB, embedder, and response cache collection."""
        os.makedirs(self._f.valves.long_term_memory_dir, exist_ok=True)
        self._f.embedder = _shared_get_embedder()
        self._f._log_debug("Embedder: using Qwen/Qwen3-Embedding-0.6B")

        self._f.chroma_client = _shared_get_chroma_client(
            self._f.valves.long_term_memory_dir
        )
        self._f._log_debug("ChromaDB: using shared singleton")

        if self._f.chroma_client is None:
            self._f._log_debug("ChromaDB not available")
            return

        # --- Memory collection (LTM) ---
        self._f.memory_collection = self._f.chroma_client.get_or_create_collection(
            name="conversation_memory", metadata={"hnsw:space": "cosine"}
        )
        self._f._log_debug(
            f"LTM collection ready – vector size = "
            f"{self._f.memory_collection.metadata.get('dimension', '?')}"
        )

        # --- Response cache collection with recovery ---
        cache_name = f"response_cache_{self._f.valves.project_id or 'default'}"
        try:
            self._f._response_cache_collection = (
                self._f.chroma_client.get_or_create_collection(
                    name=cache_name,
                    metadata={"hnsw:space": "cosine"},
                )
            )
            self._f._log_debug(f"Response cache collection '{cache_name}' ready")
        except Exception as e:
            self._f._log_debug(
                f"Failed to get/create cache collection '{cache_name}': {e}"
            )
            try:
                self._f.chroma_client.delete_collection(cache_name)
                self._f._log_debug(f"Deleted corrupted collection '{cache_name}'")
            except Exception:
                pass
            try:
                self._f._response_cache_collection = (
                    self._f.chroma_client.create_collection(
                        name=cache_name,
                        metadata={"hnsw:space": "cosine"},
                    )
                )
                self._f._log_debug(f"Recreated cache collection '{cache_name}'")
            except Exception as e2:
                self._f._log_debug(f"Could not recreate cache collection: {e2}")
                self._f._response_cache_collection = None

        # Validate embedding model fingerprint against stored collection metadata.
        # Must run after memory_collection is ready. Disables LTM retrieval if
        # the stored model fingerprint doesn't match the current embedder.
        if self._f.memory_collection is not None:
            self._validate_embedding_model()

        self._f._log_debug("LTM ready")

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Response cache & duplicate detection
    # ═══════════════════════════════════════════════════════════════════════════

    async def find_cached_response(
        self, query: str, context_hash: str, state: dict
    ) -> Optional[dict]:
        """Search the response cache for a semantically similar query.

        Returns a dict with ``response``, ``query``, and ``timestamp`` on a
        hit, or ``None`` if no valid cached entry is found.  Stale entries
        (code state changed or TTL expired) are deleted on the fly.
        """
        # ── Early exit: cache disabled or collection missing ──────────
        if not self._f.valves.enable_response_cache or not HAS_SENTENCE:
            return None
        col = getattr(self._f, "_response_cache_collection", None)
        if col is None:
            return None

        # ── Embed query ───────────────────────────────────────────────
        query_vec = await anyio.to_thread.run_sync(
            lambda: self._f.embedder.encode([query], convert_to_numpy=True)[0].tolist()
        )

        # ── Retrieve nearest neighbour ─────────────────────────────────
        results = await anyio.to_thread.run_sync(
            lambda: col.query(
                query_embeddings=[query_vec],
                n_results=1,
                where={"project_id": self._f.valves.project_id},
                include=["documents", "metadatas", "distances"],
            )
        )
        if not results or not results["ids"] or not results["ids"][0]:
            return None

        # ── Validate similarity ────────────────────────────────────────
        dist = results["distances"][0][0]
        similarity = 1.0 - (dist / 2.0)
        if similarity < self._f.valves.response_cache_similarity_threshold:
            return None

        # ── Check staleness: code state hash ───────────────────────────
        meta = results["metadatas"][0][0]
        stored_code_state = meta.get("code_state_hash", "")
        if (
            stored_code_state
            and stored_code_state
            != self._f._activation.compute_code_state_hash(self._f.valves.project_id)
        ):
            await anyio.to_thread.run_sync(
                lambda: col.delete(ids=[results["ids"][0][0]])
            )
            return None

        # ── Check staleness: TTL ───────────────────────────────────────
        ttl = self._f.valves.response_cache_ttl_hours * 3600
        ts = meta.get("timestamp", 0)
        if ttl > 0 and time.time() - ts > ttl:
            await anyio.to_thread.run_sync(
                lambda: col.delete(ids=[results["ids"][0][0]])
            )
            return None

        doc = results["documents"][0][0]
        return {"response": doc, "query": meta.get("query", ""), "timestamp": ts}

    async def find_duplicate_question(
        self, query: str, project_id: str
    ) -> Optional[dict]:
        """
        Detect near‑duplicate user questions using a cascade.

        Cascade:
        1. Cosine similarity (fast, initial filtering).
        2. CrossEncoder (semantic) scores the similarity.
        3. If confident (diff >= CE_THRESHOLD), use CrossEncoder decision.
        4. If extremely uncertain (diff < LLM_THRESHOLD), call LLM with CE context.
        5. Middle zone: fallback to cosine similarity only.

        Restores KV slot after any LLM call.

        Args:
            query (str): The user's current question.
            project_id (str): Current project identifier.

        Returns:
            Optional[dict]: {'sim': float, 'doc': str} if a duplicate is found, else None.
        """
        # ── REGION 1: Prerequisites check ──
        if not HAS_SENTENCE or not HAS_CHROMA or self._f.memory_collection is None:
            return None
        if not query or len(query.strip()) < 15:
            return None

        try:
            # ── REGION 2: Embed the query ──
            q_emb = await anyio.to_thread.run_sync(
                lambda: self._f.embedder.encode(query[:8000]).tolist()
            )
            now = time.time()

            # ── REGION 3: Build time‑filtered ChromaDB query ──
            where = {
                "$and": [
                    {"project_id": {"$eq": project_id}},
                    {"role": {"$eq": "user"}},
                    {
                        "timestamp": {
                            "$gt": time.time()
                            - self._f.valves.duplicate_question_lookback_hours * 3600
                        }
                    },
                ]
            }

            # ── REGION 4: Query ChromaDB ──
            results = await anyio.to_thread.run_sync(
                lambda: self._f.memory_collection.query(
                    query_embeddings=[q_emb],
                    n_results=self._f.valves.duplicate_question_lookback,
                    where=where,
                    include=["documents", "metadatas", "distances"],
                )
            )
            if not results or not results["ids"] or not results["ids"][0]:
                return None

            # ── REGION 5: Evaluate candidates ──
            best_candidate = None
            best_sim = 0.0
            for i, doc in enumerate(results["documents"][0]):
                dist = results["distances"][0][i]
                sim = 1.0 - (dist / 2.0)
                if sim >= self._f.valves.duplicate_question_threshold and doc != query:
                    # ── CrossEncoder for semantic similarity ──
                    pairs = [(query[:500], doc[:500])]
                    ce_scores = await self._f._commands._predict_cross_encoder(pairs)

                    if ce_scores is None or len(ce_scores) < 1:
                        # CE unavailable: use cosine similarity only
                        best_candidate = (sim, doc, None)
                        break

                    ce_score = ce_scores[0]
                    # Normalize to [0,1] roughly
                    ce_prob = 1.0 / (1.0 + math.exp(-ce_score))

                    CE_CONFIDENCE_THRESHOLD = self._f.valves.duplicate_ce_threshold
                    LLM_FALLBACK_THRESHOLD = self._f.valves.duplicate_llm_threshold

                    # ── Confidence check ──
                    if ce_prob >= 0.85 and (ce_prob - 0.5) > CE_CONFIDENCE_THRESHOLD:
                        # Confident duplicate
                        best_candidate = (sim, doc, ce_score)
                        break
                    elif ce_prob < 0.6 and (0.5 - ce_prob) > CE_CONFIDENCE_THRESHOLD:
                        # Confident not duplicate
                        continue
                    elif abs(ce_prob - 0.5) < LLM_FALLBACK_THRESHOLD:
                        # ── Extremely uncertain → LLM ──
                        is_duplicate = await self._find_duplicate_with_llm(
                            query, doc, ce_score, project_id
                        )
                        if is_duplicate:
                            best_candidate = (sim, doc, ce_score)
                            break
                        else:
                            continue
                    else:
                        # ── Middle zone: use cosine similarity threshold ──
                        if sim >= self._f.valves.duplicate_question_threshold:
                            best_candidate = (sim, doc, None)
                            break

            # ── REGION 6: Return result ──
            if best_candidate:
                sim, doc, ce = best_candidate
                log_msg = f"Duplicate question found (cosine={sim:.3f}"
                if ce is not None:
                    log_msg += f", crossencoder={ce:.3f}"
                log_msg += ")"
                self._f._log_debug(log_msg)
                return {"sim": sim, "doc": doc}

        except Exception as e:
            self._f._log_debug(f"Error in duplicate question detection: {e}")
        return None

    async def _find_duplicate_with_llm(
        self,
        query: str,
        candidate: str,
        ce_score: float,
        project_id: str,
    ) -> bool:
        """
        LLM fallback for duplicate question detection when the CrossEncoder
        diff falls below duplicate_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer. Default on failure is False (not duplicate)
        to avoid suppressing valid questions.

        Args:
            query: The user's current question (truncated to 500 chars).
            candidate: The candidate question from LTM (truncated to 500 chars).
            ce_score: CrossEncoder logit score (higher = more similar).
            project_id: Current project identifier, used for slot restoration.

        Returns:
            bool: True if the questions are duplicates, False otherwise.
        """
        prompt = (
            f"CrossEncoder score: {ce_score:.2f} (higher = more similar).\n\n"
            f"Question A:\n{query[:500]}\n\n"
            f"Question B:\n{candidate[:500]}\n\n"
            f"Are these questions asking the same thing?\n"
            f'Output only the JSON object, e.g. {{"is_duplicate": false}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a duplicate question detector. "
                "Output ONLY a valid JSON object with a single boolean field 'is_duplicate'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="duplicate_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return False

        try:
            data = json.loads(response)
            return bool(data.get("is_duplicate", False))
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_find_duplicate_with_llm: JSON parse error — "
                f"response: {response[:200]!r}"
            )
            return False

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Query helpers (parsing, symbol extraction, expansion)
    # ═══════════════════════════════════════════════════════════════════════════

    def _parse_forced_symbol_query(self, query: str) -> Tuple[Optional[str], str]:
        """Extract forced symbol from query (?symbol:Name). Returns (symbol, cleaned_query)."""
        if not self._f.valves.ltm_symbol_force_mode_enabled:
            return None, query
        match = re.match(r"\?symbol:(\S+)", query)
        if match:
            symbol = match.group(1)
            cleaned = query[match.end() :].strip()
            return symbol, cleaned if cleaned else symbol
        return None, query

    def _extract_query_symbols(self, query: str, project_id: str) -> Set[str]:
        """Return symbol names from the query that exist in the SymbolIndex."""
        if not query or not project_id:
            return set()
        words = set(re.findall(r"\b\w+\b", query))
        project_symbols = self._f._symbol_index.get_all_names(project_id)
        return words.intersection(project_symbols)

    def _is_symbol_indexable(self, symbol: "CodeSymbol") -> bool:
        """True if this symbol should be indexed in LTM metadata."""
        if symbol.kind not in ("function", "class", "method"):
            return False
        if len(symbol.name) < 3:
            return False
        blacklist = getattr(self._f, "_SYMBOL_BLACKLIST", set())
        if symbol.name in blacklist:
            return False
        return True

    async def _expand_query_for_retrieval(
        self,
        query: str,
        use_case_label: str = "General Programming",
        is_continuation: bool = False,
    ) -> List[str]:
        """
        Generate alternative search queries for LTM retrieval.

        Modified (B1): strips <details> and filters reasoning lines.
        Modified (AC-A): uses is_continuation to skip expansion.
        """
        if not self._f.valves.enable_multi_query_retrieval:
            return [query]
        if is_continuation:
            return [query]
        if len(query.strip()) < 15:
            return [query]

        prompt = (
            f"User question: {query[:300]}\n\n"
            f"Generate {self._f.valves.multi_query_variants} alternative search queries.\n"
            "Output ONLY the queries, one per line, numbered 1 to N.\n"
            "Do not include any other text.\n\n"
            "1. "
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a search query reformulator. Your ONLY task is to output search queries. "
                "Never include analysis, reasoning, explanations, or meta-commentary. "
                "Output must be in the exact format: numbered queries, one per line. "
                "No other text is allowed."
            ),
            model_override=self._f.valves.llm_model,
            max_tokens=0,
            temperature=0.4,
            label="multi_query_expand",
        )

        self._f._log_debug(f"Multi-query raw response: {response}")

        # ── B1: strip <details> reasoning blocks ──────────────────────────
        raw_response = re.sub(
            r"<details[^>]*>.*?</details>",
            "",
            response or "",
            flags=re.DOTALL | re.IGNORECASE,
        )

        # ── B1: line-level filter ──────────────────────────────────────────
        _REASONING_LINE_PREFIXES = (
            "thinking process",
            "let me ",
            "i will ",
            "to answer",
            "step ",
            "note:",
            "reasoning:",
            "my approach",
            "first,",
            "here are",
            "i need to",
            "the user",
        )

        queries = [query]
        pattern = re.compile(r"^\s*(?:\d+\.\s*|[-*]\s*)?(.+)$")
        for line in raw_response.strip().split("\n"):
            line = line.strip()
            if not line:
                continue
            match = pattern.match(line)
            if not match:
                continue
            cleaned = match.group(1).strip()
            if not cleaned:
                continue
            lower = cleaned.lower()
            if any(lower.startswith(p) for p in _REASONING_LINE_PREFIXES):
                continue
            if len(cleaned) > 5:
                queries.append(cleaned)

        queries = queries[: self._f.valves.multi_query_variants + 1]
        self._f._log_debug(f"Multi-query expansion: {len(queries)} queries")
        return queries

    async def _rerank_results(
        self, query: str, documents: List[str], top_k: int
    ) -> List[str]:
        """Rerank documents using CrossEncoder and return top_k results."""
        if not self._f.valves.enable_reranking:
            return documents[:top_k]
        pairs = [(query, doc) for doc in documents]
        scores = await self._f._commands._predict_cross_encoder(pairs)
        if scores is None:
            self._f._log_debug(
                "_rerank_results: CrossEncoder not loaded, skipping reranking."
            )
            return documents[:top_k]
        scored = list(zip(documents, scores))
        scored.sort(key=lambda x: x[1], reverse=True)
        return [doc for doc, _ in scored[:top_k]]

    async def _build_retrieval_context(
        self,
        content: str,
        project_id: str,
        role: str,
        code_symbols: List[str],
        file_paths: List[str],
        content_type: str,
    ) -> str:
        """Build a short prefix that enriches a ChromaDB document for better
        retrieval.  Two modes are supported via ``contextual_retrieval_mode``:

        * ``"metadata"`` — fast, concatenates structured fields (project,
          files, symbols, type, excerpt).
        * ``"llm"`` — asks the LLM for a one‑sentence description of the
          content (slower, but captures nuance better).
        """
        if not self._f.valves.enable_contextual_retrieval:
            return ""

        # ── LLM mode ────────────────────────────────────────────────────
        if self._f.valves.contextual_retrieval_mode == "llm":
            return await self._build_retrieval_context_llm(content, project_id)

        # ── Metadata mode ───────────────────────────────────────────────
        parts: List[str] = [f"Project: {project_id}"]
        if file_paths:
            parts.append(f"Files: {', '.join(file_paths[:3])}")
        if code_symbols:
            parts.append(f"Functions: {', '.join(code_symbols[:6])}")
        if content_type and content_type != "general":
            parts.append(f"Type: {content_type}")
        role_label = "User question" if role == "user" else "Assistant response"
        parts.append(f"Role: {role_label}")
        excerpt = content[:120].replace("\n", " ").strip()
        if len(content) > 120:
            excerpt += "..."
        parts.append(f"Excerpt: {excerpt}")
        context_line = " | ".join(parts)
        return f"[{context_line}]\n\n"

    async def _build_retrieval_context_llm(self, content: str, project_id: str) -> str:
        """
        Use the LLM to generate a one-sentence contextual description of
        *content* for improved long-term memory retrieval.

        The prompt constrains output to 10-20 words, so no max_tokens ceiling
        is needed — the model terminates naturally. enable_thinking=False avoids
        reasoning overhead on a deterministic single-sentence task.
        """
        prompt = (
            "In one sentence (10-20 words), describe what the following "
            "code/conversation excerpt is about, for search retrieval:\n\n"
            f"{content[:400]}"
        )
        context = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "Output only one descriptive sentence. "
                "Be specific about functions, files, or errors mentioned."
            ),
            model_override=self._f.valves.llm_model,
            max_tokens=0,
            temperature=0.2,
            label="retrieval_context_llm",
            enable_thinking=False,
        )
        if context and context.strip():
            return f"[Context: {context.strip()}]\n\n"
        return ""

    async def _retrieve_by_symbol(
        self, symbol: str, cleaned_query: str, project_id: str
    ) -> List[Dict[str, Any]]:
        """Retrieve memories filtered by a specific code symbol."""
        now = time.time()
        where = {
            "$and": [
                {"project_id": {"$eq": project_id}},
                {"code_symbols": {"$contains": f",{symbol},"}},
            ]
        }

        # ── FIX 11: Expiration filter with OR for summaries ──
        # Apply the same OR logic here so that summaries are not excluded.
        if self._f.valves.long_term_memory_expiration_days > 0:
            where["$and"].append(
                {
                    "$or": [
                        {"expires_at": {"$gt": now}},
                        {"is_session_summary": {"$eq": True}},
                        {"is_turn_summary": {"$eq": True}},
                        {"is_raptor_summary": {"$eq": True}},
                        {"is_hierarchical_summary": {"$eq": True}},
                    ]
                }
            )

        q_emb = await anyio.to_thread.run_sync(
            lambda: self._f.embedder.encode(cleaned_query[:1000]).tolist()
        )
        results = await anyio.to_thread.run_sync(
            lambda: self._f.memory_collection.query(
                query_embeddings=[q_emb],
                n_results=self._f.valves.long_term_memory_top_k * 2,
                where=where,
                include=["documents", "metadatas", "distances"],
            )
        )
        docs_with_meta = []
        if results and results["documents"]:
            for i, doc in enumerate(results["documents"][0]):
                meta = results["metadatas"][0][i]
                sim = 1.0 - (results["distances"][0][i] / 2.0)
                ts = meta.get("timestamp")
                if ts is not None and ts < 1000000000:
                    ts = None
                if self._f.valves.ltm_time_decay_hours > 0 and ts is not None:
                    age_hours = (now - ts) / 3600
                    sim *= 0.5 ** (age_hours / self._f.valves.ltm_time_decay_hours)
                if sim >= self._f.valves.long_term_memory_similarity_threshold:
                    docs_with_meta.append((doc, sim, ts, meta))
        docs_with_meta.sort(key=lambda x: x[1], reverse=True)
        docs_with_meta = docs_with_meta[: self._f.valves.long_term_memory_top_k]
        if not docs_with_meta and self._f.valves.ltm_symbol_force_fallback_to_semantic:
            return await self.retrieve_memories_unified(cleaned_query, project_id)
        return [{"doc": doc, "timestamp": ts} for doc, _, ts, _ in docs_with_meta]

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Main retrieval methods
    # ═══════════════════════════════════════════════════════════════════════════

    async def retrieve_memories_unified(
        self,
        query: str,
        project_id: str,
        use_case_label: str = "General Programming",
        slot_free: bool = True,
        is_continuation: bool = False,
    ) -> list:
        """
        Retrieve relevant memories from LTM using multiple complementary paths,
        then merge and deduplicate results.

        Retrieval paths (all executed concurrently where possible):
            A.  Symbol-based: extract named symbols from the query and fetch
                entries that mention those symbols.
            B.  Semantic: embed the (optionally expanded) query and perform
                nearest-neighbour search in ChromaDB.
            C.  Historical messages: retrieve recent conversation turns whose
                content overlaps with the query.

        Results from all paths are merged into a single ranked list.
        Deduplication is performed on entry_id before ranking so that a memory
        retrieved by both path A and path B counts only once.

        ChromaDB raises InvalidArgumentException when n_results exceeds the
        number of stored documents. All ChromaDB calls are wrapped in try/except
        and use a safe_n_results helper that caps the request count to the actual
        collection size.

        Steps:
            1.  Resolve effective retrieval parameters from valves.
            2.  Parse forced-symbol override if present in query.
            3.  Expand query for semantic retrieval.
            4.  Run path A: symbol-based retrieval.
            5.  Run path B: semantic retrieval with n_results cap.
            6.  Run path C: historical message retrieval.
            7.  Merge all results, deduplicate by entry_id, sort by score.
            8.  Rerank with cross-encoder if available.
            9.  Return top-k memories.
        """
        if not self._f.memory_collection:
            return []

        top_k = getattr(self._f.valves, "ltm_top_k", 5)
        max_memories = getattr(self._f.valves, "ltm_max_memories", 10)

        # -- Step 1: resolve parameters --
        enable_symbol = getattr(self._f.valves, "ltm_enable_symbol_retrieval", True)
        enable_semantic = getattr(self._f.valves, "ltm_enable_semantic_retrieval", True)
        enable_history = getattr(self._f.valves, "ltm_enable_history_retrieval", True)

        # -- Step 2: forced-symbol override --
        forced_symbol, clean_query = self._parse_forced_symbol_query(query)
        effective_query = clean_query if clean_query.strip() else query

        # -- Step 3: expand query for semantic retrieval --
        expanded_queries: List[str] = [effective_query]
        if enable_semantic and not is_continuation:
            try:
                expanded_queries = await self._expand_query_for_retrieval(
                    effective_query,
                    use_case_label=use_case_label,
                    is_continuation=is_continuation,
                ) or [effective_query]
            except Exception as e:
                self._f._log_debug(
                    f"retrieve_memories_unified: query expansion failed: {e}"
                )

        # Helper: cap n_results to avoid ChromaDB InvalidArgumentException.
        async def _safe_query_chroma(
            query_texts: List[str],
            where: dict,
            n_results: int,
            include: List[str],
        ) -> Optional[dict]:
            if not query_texts or not any(q.strip() for q in query_texts):
                return None
            try:
                # Cap n_results to actual collection count for this filter.
                count_result = await anyio.to_thread.run_sync(
                    lambda: self._f.memory_collection.count()
                )
                safe_n = max(1, min(n_results, count_result))
                return await anyio.to_thread.run_sync(
                    lambda: self._f.memory_collection.query(
                        query_texts=query_texts,
                        where=where,
                        n_results=safe_n,
                        include=include,
                    )
                )
            except Exception as e:
                self._f._log_debug(
                    f"retrieve_memories_unified: ChromaDB query failed: "
                    f"{type(e).__name__}: {e}"
                )
                return None

        # Accumulate all hits keyed by entry_id to deduplicate across paths.
        seen_ids: Set[str] = set()
        all_hits: List[Dict[str, Any]] = []

        def _add_hit(entry_id: str, doc: str, meta: dict, score: float) -> None:
            if entry_id in seen_ids:
                return
            seen_ids.add(entry_id)
            all_hits.append(
                {
                    "entry_id": entry_id,
                    "content": doc,
                    "metadata": meta,
                    "score": score,
                }
            )

        # -- Step 4: path A — symbol-based retrieval --
        if enable_symbol:
            symbols_to_fetch: Set[str] = set()
            if forced_symbol:
                symbols_to_fetch.add(forced_symbol)
            else:
                symbols_to_fetch = self._extract_query_symbols(
                    effective_query, project_id
                )

            for sym in list(symbols_to_fetch)[:5]:
                try:
                    sym_hits = await self._retrieve_by_symbol(
                        sym, effective_query, project_id
                    )
                    for hit in sym_hits:
                        _add_hit(
                            hit.get("entry_id", hit.get("id", sym)),
                            hit.get("content", ""),
                            hit.get("metadata", {}),
                            hit.get("score", 0.7),
                        )
                except Exception as e:
                    self._f._log_debug(
                        f"retrieve_memories_unified: symbol path failed "
                        f"for '{sym}': {e}"
                    )

        # -- Step 5: path B — semantic retrieval --
        if enable_semantic:
            where_filter = {
                "$and": [
                    {"project_id": {"$eq": project_id}},
                    {"type": {"$ne": "raptor_summary"}},
                ]
            }
            raw = await _safe_query_chroma(
                query_texts=expanded_queries[:3],
                where=where_filter,
                n_results=top_k * 2,
                include=["documents", "metadatas", "distances", "ids"],
            )
            if raw:
                docs = (raw.get("documents") or [[]])[0]
                metas = (raw.get("metadatas") or [[]])[0]
                distances = (raw.get("distances") or [[]])[0]
                ids = (raw.get("ids") or [[]])[0]
                for doc, meta, dist, eid in zip(docs, metas, distances, ids):
                    score = max(0.0, 1.0 - float(dist))
                    _add_hit(eid, doc or "", meta or {}, score)

        # -- Step 6: path C — historical message retrieval --
        if enable_history:
            try:
                hist_limit = getattr(self._f.valves, "ltm_history_limit", 5)
                hist_hits = await self.retrieve_historical_messages(
                    query=effective_query,
                    project_id=project_id,
                    limit=hist_limit,
                    is_continuation=is_continuation,
                )
                for hit in hist_hits:
                    _add_hit(
                        hit.get("entry_id", hit.get("id", "")),
                        hit.get("content", ""),
                        hit.get("metadata", {}),
                        hit.get("score", 0.5),
                    )
            except Exception as e:
                self._f._log_debug(
                    f"retrieve_memories_unified: history path failed: {e}"
                )

        if not all_hits:
            return []

        # -- Step 7: sort by score descending --
        all_hits.sort(key=lambda h: h["score"], reverse=True)
        candidates = all_hits[:max_memories]

        # -- Step 8: cross-encoder rerank if available --
        if len(candidates) > 1:
            try:
                docs_for_rerank = [h["content"] for h in candidates]
                reranked_docs = await self._rerank_results(
                    effective_query, docs_for_rerank, top_k=len(candidates)
                )
                if reranked_docs:
                    doc_to_hit = {h["content"]: h for h in candidates}
                    reranked_hits = [
                        doc_to_hit[d] for d in reranked_docs if d in doc_to_hit
                    ]
                    if reranked_hits:
                        candidates = reranked_hits
            except Exception as e:
                self._f._log_debug(
                    f"retrieve_memories_unified: rerank failed, "
                    f"using score order: {e}"
                )

        # -- Step 9: return top-k --
        result = candidates[:top_k]
        self._f._log_debug(
            f"retrieve_memories_unified: {len(all_hits)} raw hits → "
            f"{len(result)} returned "
            f"(sym={enable_symbol}, sem={enable_semantic}, "
            f"hist={enable_history})"
        )
        return result

    async def retrieve_historical_messages(
        self, query: str, project_id: str, limit: int, is_continuation: bool = False
    ) -> list:
        """Retrieve historically relevant messages from ChromaDB LTM."""
        if not HAS_SENTENCE or not HAS_CHROMA or self._f.memory_collection is None:
            return []

        forced_symbol, cleaned_query = self._parse_forced_symbol_query(query)
        if forced_symbol:
            memories = await self._retrieve_by_symbol(
                forced_symbol, cleaned_query, project_id
            )
            return [{"role": "user", "content": m["doc"]} for m in memories]

        try:
            # Requires an embedder supporting 32768 context or more.
            q_emb = await anyio.to_thread.run_sync(
                lambda: self._f.embedder.encode(
                    self._f._tokens.truncate_text_to_tokens(query, 32768)
                ).tolist()
            )
            now = time.time()
            where_filter = {"$and": [{"project_id": {"$eq": project_id}}]}

            # ── FIX 11: Expiration filter with OR for summaries ──
            if self._f.valves.long_term_memory_expiration_days > 0:
                where_filter["$and"].append(
                    {
                        "$or": [
                            {"expires_at": {"$gt": now}},
                            {"is_session_summary": {"$eq": True}},
                            {"is_turn_summary": {"$eq": True}},
                            {"is_raptor_summary": {"$eq": True}},
                            {"is_hierarchical_summary": {"$eq": True}},
                        ]
                    }
                )

            results = await anyio.to_thread.run_sync(
                lambda: self._f.memory_collection.query(
                    query_embeddings=[q_emb],
                    n_results=limit * 3,
                    where=where_filter,
                    include=["documents", "metadatas", "distances"],
                )
            )

            query_symbols = set()
            if self._f.valves.ltm_symbol_boost_enabled and query:
                query_symbols = self._extract_query_symbols(query, project_id)

            scored_regular = []
            scored_summaries = []
            if results and results["documents"]:
                for i, doc in enumerate(results["documents"][0]):
                    meta = results["metadatas"][0][i]
                    dist = results["distances"][0][i]
                    sim = 1.0 - (dist / 2.0)
                    if (
                        query_symbols
                        and sim >= self._f.valves.ltm_symbol_boost_min_similarity
                    ):
                        meta_symbols_str = meta.get("code_symbols", "")
                        if meta_symbols_str:
                            meta_symbols = set(meta_symbols_str.split(","))
                            common = query_symbols.intersection(meta_symbols)
                            if common:
                                sim *= self._f.valves.ltm_symbol_boost_factor
                    role = meta.get("role", "user")
                    is_summary = meta.get("is_hierarchical_summary", False) or meta.get(
                        "is_session_summary", False
                    )
                    entry = (sim, {"role": role, "content": doc})
                    if is_summary:
                        scored_summaries.append(entry)
                    else:
                        scored_regular.append(entry)

            scored_summaries.sort(key=lambda x: x[0], reverse=True)
            scored_regular.sort(key=lambda x: x[0], reverse=True)

            messages = [msg for _, msg in scored_summaries] + [
                msg for _, msg in scored_regular
            ]

            if (
                self._f.valves.enable_reranking
                and self._f._cross_encoder
                and len(messages) > 1
            ):
                docs = [m["content"] for m in messages]
                reranked = await self._rerank_results(query, docs, limit)
                doc_to_msg = {m["content"]: m for m in messages}
                messages = [doc_to_msg[doc] for doc in reranked if doc in doc_to_msg]

            return messages[:limit]
        except Exception as e:
            logger.warning(f"Historical message retrieval failed: {e}")
            return []

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Message storage
    # ═══════════════════════════════════════════════════════════════════════════

    # ── M1: strip CoT scaffolding ──────────────────────────────────────────
    _LTM_STRIP_RE = re.compile(
        r"<details[^>]*>.*?</details>",
        re.DOTALL | re.IGNORECASE,
    )

    def _prepare_text_for_ltm(self, text: str, role: str) -> str:
        """Strip model CoT scaffolding before embedding into ChromaDB.
        Only applied to assistant messages. The original message content
        shown to the user is NOT modified."""
        if role != "assistant":
            return text
        stripped = self._LTM_STRIP_RE.sub("", text).strip()
        return stripped

    # ── M2: skip partial multi‑phase responses ─────────────────────────────
    _MULTI_PHASE_CONTINUATION_MARKER = "▶ CONTINÚA:"
    _MULTI_PHASE_PART_RE = re.compile(
        r"##\s+C[oó]digo\s*[—–-]\s*Parte\s+\d+/\d+", re.IGNORECASE
    )

    def _is_partial_multi_phase(self, text: str) -> bool:
        return self._MULTI_PHASE_CONTINUATION_MARKER in text or bool(
            self._MULTI_PHASE_PART_RE.search(text)
        )

    async def store_messages(
        self,
        project_id: str,
        messages: list,
        wait: bool = True,
    ) -> None:
        """
        Store a batch of conversation messages in LTM (ChromaDB + SQLite).

        Filters out messages that are empty, role-less, or have non-string
        content before dispatching to _store_messages_async.

        When wait=False, the storage is dispatched as a background task.
        The task is registered on the running event loop with a done-callback
        that logs exceptions so failures are always visible in the debug log.
        asyncio.ensure_future is wrapped in try/except to handle the case where
        the event loop is closing during server shutdown.

        Steps:
            1.  Filter messages to valid candidates.
            2.  Early exit when nothing to store.
            3.  Dispatch: await directly when wait=True, background task otherwise.
        """
        # -- Step 1: filter to valid messages --
        valid: List[dict] = []
        for msg in messages:
            role = msg.get("role", "")
            content = msg.get("content")
            if role not in ("user", "assistant", "system"):
                continue
            if content is None or not isinstance(content, str):
                continue
            if not content.strip():
                continue
            valid.append({"role": role, "content": content})

        # -- Step 2: early exit --
        if not valid:
            return

        # -- Step 3: dispatch --
        if wait:
            await self._store_messages_async(project_id, valid)
            return

        # Fire-and-forget with exception surfacing.
        try:
            task = asyncio.ensure_future(self._store_messages_async(project_id, valid))

            def _on_done(t: asyncio.Task) -> None:
                exc = t.exception()
                if exc:
                    self._f._log_debug(
                        f"store_messages (background): failed for "
                        f"'{project_id}': {type(exc).__name__}: {exc}"
                    )

            task.add_done_callback(_on_done)

        except RuntimeError as e:
            # Event loop not running or closing — fall back to best-effort
            # synchronous store so messages are not completely lost.
            self._f._log_debug(
                f"store_messages: ensure_future failed ({e}), "
                f"attempting synchronous fallback for '{project_id}'"
            )
            try:
                await self._store_messages_async(project_id, valid)
            except Exception as e2:
                self._f._log_debug(
                    f"store_messages: synchronous fallback also failed: "
                    f"{type(e2).__name__}: {e2}"
                )

    async def _store_messages_async(self, project_id: str, valid: list) -> None:
        """Store each message one by one, offloading embedding to a thread."""
        for msg in valid:
            try:
                await self._store_single_message(project_id, msg)
            except Exception as e:
                self._f._log_debug(f"Async LTM store failed: {e}")

    async def _store_single_message(
        self,
        project_id: str,
        msg: dict,
    ) -> None:
        """
        Embed and persist a single conversation message to ChromaDB and SQLite.

        Content is truncated to ltm_max_embedding_tokens before embedding to
        prevent silent truncation or errors from the embedding model's internal
        token limit. Without this truncation, assistant messages containing
        large code blocks produce degraded or failed embeddings that pollute
        the retrieval index.

        Steps:
            1.  Prepare content and metadata.
            2.  Truncate content to embedding model's safe token limit.
            3.  Compute embedding; abort on failure.
            4.  Build a stable entry_id from (project_id, role, content_hash).
            5.  Upsert to ChromaDB.
            6.  Persist raw content to SQLite for full-text retrieval.
        """
        role = msg.get("role", "user")
        content = msg.get("content", "")
        if not content.strip():
            return

        # -- Step 1: metadata --
        content_hash = hashlib.md5(
            content.encode("utf-8", errors="replace")
        ).hexdigest()
        timestamp = time.time()
        metadata = {
            "project_id": project_id,
            "role": role,
            "timestamp": timestamp,
            "hash": content_hash,
            "type": "message",
        }

        # -- Step 2: truncate before embedding --
        max_embed_tokens = getattr(self._f.valves, "ltm_max_embedding_tokens", 400)
        text_for_embedding = self._f._tokens.truncate_text_to_tokens(
            content, max_embed_tokens
        )

        # -- Step 3: embed --
        if not self._f.embedder or not self._f.memory_collection:
            return
        try:
            embedding = await anyio.to_thread.run_sync(
                lambda: self._f.embedder.encode(
                    [text_for_embedding], show_progress_bar=False
                )[0].tolist()
            )
        except Exception as e:
            self._f._log_debug(
                f"_store_single_message: embedding failed for "
                f"'{project_id}' ({role}): {type(e).__name__}: {e}"
            )
            return

        # -- Step 4: stable entry_id --
        entry_id = f"{project_id}_msg_{role}_{content_hash}"

        # -- Step 5: upsert to ChromaDB --
        try:
            await anyio.to_thread.run_sync(
                lambda: self._f.memory_collection.upsert(
                    ids=[entry_id],
                    embeddings=[embedding],
                    documents=[content],
                    metadatas=[metadata],
                )
            )
        except Exception as e:
            self._f._log_debug(
                f"_store_single_message: ChromaDB upsert failed for "
                f"'{project_id}': {type(e).__name__}: {e}"
            )
            return

        # -- Step 6: persist raw content to SQLite --
        try:
            await self._f._state_store._db_enqueue(
                self._f._db_conn.execute,
                args=(
                    "INSERT OR REPLACE INTO ltm_messages "
                    "(entry_id, project_id, role, content, timestamp) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (entry_id, project_id, role, content, timestamp),
                ),
            )
        except Exception as e:
            self._f._log_debug(
                f"_store_single_message: SQLite persist failed for "
                f"'{project_id}': {type(e).__name__}: {e}"
            )

    async def store_response_in_cache(
        self,
        query: str,
        response: str,
        context_hash: str,
        state: dict,
        code_state_hash: str,
        wait: bool = True,
    ) -> None:
        """Store a response in the ChromaDB response cache for future reuse.
        If `wait` is False, the embedding and upsert are offloaded to a background task.
        """
        if not self._f.valves.enable_response_cache or not HAS_SENTENCE:
            return
        if not query or not response:
            return

        if not wait:
            asyncio.create_task(
                self._store_response_in_cache_async(
                    query, response, context_hash, state, code_state_hash
                )
            )
            return

        await self._store_response_in_cache_sync(
            query, response, context_hash, state, code_state_hash
        )

    async def _store_response_in_cache_sync(
        self,
        query: str,
        response: str,
        context_hash: str,
        state: dict,
        code_state_hash: str,
    ) -> None:
        """
        Synchronously store a response in the ChromaDB response cache.

        This method embeds the query, stores the response document, and
        updates metadata including the code_state_hash for staleness detection.
        The query is truncated to 500 characters in metadata to keep the field
        compact and human-readable; this does not affect the embedding or
        retrieval quality.

        If the cache collection is missing or corrupted, this method attempts
        to recreate it automatically, preventing the common
        "Error getting collection: Failed to get segments" error.

        Args:
            query (str): The user query that generated the response.
            response (str): The assistant's response.
            context_hash (str): Hash of the context (unused, kept for API compatibility).
            state (dict): The conversation state (unused, kept for API compatibility).
            code_state_hash (str): Hash of the code state for staleness detection.
        """
        # --- Get the cache collection, recreating it if necessary ---
        col = getattr(self._f, "_response_cache_collection", None)

        if col is None:
            self._f._log_debug(
                "Response cache collection missing, attempting to recreate..."
            )
            try:
                cache_name = f"response_cache_{self._f.valves.project_id or 'default'}"
                col = self._f.chroma_client.get_or_create_collection(
                    name=cache_name,
                    metadata={"hnsw:space": "cosine"},
                )
                self._f._response_cache_collection = col
                self._f._log_debug("Recreated response cache collection during store")
            except Exception as e:
                self._f._log_debug(f"Could not recreate cache collection: {e}")
                return

        # --- Prepare the entry ---
        project = self._f.valves.project_id
        entry_id = hashlib.md5(f"{project}|{query}".encode()).hexdigest()[:32]

        # Embed the query
        embedding = await anyio.to_thread.run_sync(
            lambda: self._f.embedder.encode([query], convert_to_numpy=True)[0].tolist()
        )

        max_entries = self._f.valves.response_cache_max_entries
        pstate = self._f._project_state_manager.get_pstate(project)
        current_size = pstate.get("response_cache_count", 0)

        # Enforce cache size limit (LRU eviction)
        if current_size >= max_entries:
            to_delete_count = max(1, max_entries // 10)
            try:
                old_entries = await anyio.to_thread.run_sync(
                    lambda: col.get(
                        where={"project_id": project},
                        include=["metadatas"],
                        limit=to_delete_count,
                    )
                )
                if old_entries and old_entries["ids"]:
                    await anyio.to_thread.run_sync(
                        lambda: col.delete(ids=old_entries["ids"])
                    )
                    pstate["response_cache_count"] = max(
                        0, current_size - len(old_entries["ids"])
                    )
            except Exception as e:
                self._f._log_debug(f"Failed to evict old cache entries: {e}")

        # Upsert the new entry
        try:
            await anyio.to_thread.run_sync(
                lambda: col.upsert(
                    ids=[entry_id],
                    embeddings=[embedding],
                    documents=[response],
                    metadatas=[
                        {
                            "query": query[:500],
                            "project_id": project,
                            "context_hash": "",  # Kept for compatibility
                            "code_state_hash": code_state_hash,
                            "timestamp": time.time(),
                        }
                    ],
                )
            )
            pstate["response_cache_count"] = pstate.get("response_cache_count", 0) + 1
        except Exception as e:
            self._f._log_debug(f"Failed to store response in cache: {e}")
            # If the operation fails, mark the collection as invalid so it gets recreated next time
            self._f._response_cache_collection = None

    async def _store_response_in_cache_async(
        self,
        query: str,
        response: str,
        context_hash: str,
        state: dict,
        code_state_hash: str,
    ) -> None:
        """Background wrapper for response cache storage."""
        try:
            await self._store_response_in_cache_sync(
                query, response, context_hash, state, code_state_hash
            )
        except Exception as e:
            self._f._log_debug(f"Async response cache store failed: {e}")

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Maintenance (purge expired memories)
    # ═══════════════════════════════════════════════════════════════════════════

    async def purge_expired_memories(self) -> None:
        """Remove memories whose expires_at timestamp is in the past."""
        await asyncio.sleep(0)
        if not HAS_CHROMA or self._f.memory_collection is None:
            return
        if self._f.valves.long_term_memory_expiration_days <= 0:
            return
        try:
            await anyio.to_thread.run_sync(self._do_purge)
        except Exception as e:
            logger.warning(f"Purge failed: {e}")

    def _do_purge(self) -> None:
        now = time.time()
        expired = self._f.memory_collection.get(where={"expires_at": {"$lt": now}})
        if expired and expired["ids"]:
            self._f.memory_collection.delete(ids=expired["ids"])
            self._f._log_debug(f"Purged {len(expired['ids'])} expired memories")

    # ═══════════════════════════════════════════════════════════════════════════
    # 7. Project purge – NEW (C3)
    # ═══════════════════════════════════════════════════════════════════════════

    def purge_project(self, project_id: str) -> int:
        """Delete all ChromaDB documents for a project.

        Returns the number of documents deleted.
        """
        try:
            existing = self._f.memory_collection.get(
                where={"project_id": {"$eq": project_id}}
            )
            ids_to_delete: List[str] = existing.get("ids", [])
            if ids_to_delete:
                self._f.memory_collection.delete(ids=ids_to_delete)
                self._f._log_debug(
                    f"LTM: purged {len(ids_to_delete)} documents for project '{project_id}'"
                )
            return len(ids_to_delete)
        except Exception as e:
            self._f._log_debug(f"LTM: purge_project failed for '{project_id}': {e}")
            return 0

    # ═══════════════════════════════════════════════════════════════════════════
    # 8. Embedding model validation – NEW (C4)
    # ═══════════════════════════════════════════════════════════════════════════

    def _get_embedding_dimension(self) -> int:
        """Return the output dimension of the current embedding model."""
        test_vec = self._f.embedder.encode(["test"])
        return len(test_vec[0]) if test_vec else 0

    def _validate_embedding_model(self) -> bool:
        """
        Validate that the current embedding model matches the stored fingerprint.

        Reads/writes model metadata from the ChromaDB collection.
        On the first run (no fingerprint stored yet), persists the current
        model name and dimension. On subsequent runs, compares against the
        stored fingerprint and disables LTM retrieval if they differ.

        Returns False and sets _retrieval_disabled_reason if a mismatch is
        found. Returns True if the model matches or on the first run.

        Bug fixed: the original check was `if stored_model is None` which
        is always False because str() never returns None — so the first-run
        fingerprint was never persisted. Changed to `if not stored_model`
        to correctly detect an empty string (= no fingerprint yet).
        """
        try:
            current_model: str = str(
                getattr(self._f.valves, "embedding_model_name", "unknown")
            )
            current_dim: int = int(self._get_embedding_dimension() or 0)

            coll_meta: dict = self._f.memory_collection.metadata or {}
            stored_model: str = str(coll_meta.get("_codeaware_embedding_model", ""))
            stored_dim: int = int(coll_meta.get("_codeaware_embedding_dim", 0) or 0)

            # Empty string means no fingerprint has been persisted yet (first run).
            if not stored_model:
                self._f.memory_collection.modify(
                    metadata={
                        **coll_meta,
                        "_codeaware_embedding_model": current_model,
                        "_codeaware_embedding_dim": current_dim,
                    }
                )
                self._f._log_debug(
                    f"LTM: embedding fingerprint stored "
                    f"(model={current_model}, dim={current_dim})"
                )
                return True

            if stored_model != current_model or stored_dim != current_dim:
                reason = (
                    f"LTM embedding mismatch — collection built with "
                    f"'{stored_model}' (dim={stored_dim}), "
                    f"current model is '{current_model}' (dim={current_dim}). "
                    f"LTM retrieval DISABLED. To fix: clear the ChromaDB collection."
                )
                self._f._log_debug(reason)
                self._retrieval_disabled_reason = reason
                return False

            return True

        except Exception as e:
            # Fail open to avoid breaking existing installs that lack the metadata.
            self._f._log_debug(f"LTM: could not validate embedding model: {e}")
            return True


class LLMOrchestrator:
    """Centralised LLM caller with built‑in response cache, retry logic,
    and task deduplication.

    Provides:
    * ``call_llm(prompt, ...)`` — the single entry point for all LLM calls.
      Retries transient failures (429, 5xx) with a configurable total
      deadline and an exponential backoff.
    * In‑memory response cache (``AsyncLRUCache``) keyed by prompt hash,
      shared across the whole process.
    * Deduplication of concurrent identical prompts via per‑key futures,
      so parallel background tasks (docstrings, summaries) never fire
      duplicate LLM requests.
    * A concurrency semaphore (``_llm_semaphore``) that serialises
      inference for llama.cpp's ``--parallel 1`` mode.
    * ``should_keep_full_code(query)`` — lightweight CrossEncoder call
      that decides whether the user wants the full implementation or a
      summary.
    * ``wait_for_slot()`` / ``wait_for_llm_tasks()`` — coordination
      primitives used by the inlet and outlet to avoid dirtying the KV
      cache while auxiliary LLM work is in flight.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Cache & concurrency initialization
    # ═══════════════════════════════════════════════════════════════════════════

    def init_cache(self) -> None:
        """Return the shared AsyncLRUCache instance for LLM response caching."""
        self._f._llm_cache = _AsyncLRUCache(
            max_size=self._f.valves.LLM_CACHE_MAX_SIZE,
            ttl=self._f.valves.LLM_CACHE_TTL,
        )

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Main LLM caller (with retries, cache, deduplication)
    # ═══════════════════════════════════════════════════════════════════════════

    async def call_llm(
        self,
        prompt: str,
        system_prompt: str,
        model_override: Optional[str] = None,
        max_tokens: Optional[int] = None,
        temperature: float = 0.3,
        label: str = "",
        total_timeout: Optional[float] = None,
        endpoint_type: Optional[str] = None,
        response_format: Optional[Dict[str, Any]] = None,
        enable_thinking: bool = True,
        log_raw_response: bool = False,
    ) -> Optional[str]:
        """
        Call the LLM with in-memory response cache and call deduplication.
        """
        if getattr(self._f, "_is_silent_ingestion", False) and label not in (
            "bg_docstring",
            "lazy_docstring_batch",
        ):
            return None

        dedup_key = hashlib.md5(
            f"{prompt}|{system_prompt}|{temperature}|{max_tokens}|{model_override}".encode()
        ).hexdigest()
        async with self._f._pending_llm_lock:
            if dedup_key in self._f._pending_llm:
                future = self._f._pending_llm[dedup_key]
                is_producer = False
            else:
                future = asyncio.Future()
                self._f._pending_llm[dedup_key] = future
                is_producer = True

        if not is_producer:
            return await future

        t_start = time.monotonic()
        label_str = f" ({label})" if label else ""

        async with self._f._llm_semaphore:
            try:
                model = model_override or self._f.valves.llm_model
                if not model:
                    logger.warning(f"[LLM]{label_str} No model configured")
                    future.set_result(None)
                    return None

                cache_key = hashlib.md5(
                    f"{model}|{prompt}|{system_prompt}|{temperature}|{max_tokens}"
                    f"|{response_format}|{enable_thinking}".encode()
                ).hexdigest()

                cached = await self._f._llm_cache.get(cache_key)
                if cached is not None:
                    future.set_result(cached)
                    self._f._log_debug(
                        f"[LLM] {model}{label_str} (cached) "
                        f"took {time.monotonic() - t_start:.3f}s"
                    )
                    return cached

                if endpoint_type is not None:
                    ep_type = endpoint_type
                else:
                    ep_type = "chat"
                    if get_model_backend(model) == "llamacpp":
                        ep_type = self._f.valves.llamacpp_endpoint_type

                if self._f.tokenizer:
                    prompt_tokens = len(self._f.tokenizer.encode(prompt))
                    self._f._log_debug(
                        f"LLM call to {model}{label_str} – "
                        f"prompt size: ~{prompt_tokens} tokens"
                    )

                task = asyncio.current_task()
                async with self._f._active_llm_tasks_lock:
                    self._f._active_llm_tasks.add(task)

                try:
                    content = await _shared_call_llm(
                        prompt=prompt,
                        system=system_prompt,
                        base_url=self._f.valves.LLM_BASE_URL,
                        model=model,
                        api_token=self._f.valves.LLM_API_TOKEN,
                        temperature=temperature,
                        max_tokens=max_tokens,
                        timeout=self._f.valves.llm_request_timeout,
                        endpoint_type=ep_type,
                        response_format=response_format,
                        enable_thinking=enable_thinking,
                        log_raw_response=log_raw_response,
                        label=label,
                    )

                    if content:
                        await self._f._llm_cache.set(cache_key, content)
                        future.set_result(content)
                        async with self._f._model_lock:
                            self._f._last_used_model = model
                        in_tokens = (
                            len(self._f.tokenizer.encode(prompt))
                            if self._f.tokenizer
                            else "?"
                        )
                        out_tokens = (
                            len(self._f.tokenizer.encode(content))
                            if self._f.tokenizer
                            else "?"
                        )
                        self._f._log_debug(
                            f"[LLM] {model}{label_str} – "
                            f"in:{in_tokens} out:{out_tokens} "
                            f"took {time.monotonic() - t_start:.3f}s"
                        )
                        return content
                    else:
                        future.set_result(None)
                        return None

                finally:
                    async with self._f._active_llm_tasks_lock:
                        self._f._active_llm_tasks.discard(task)

            except Exception as exc:
                future.set_exception(exc)
                raise
            finally:
                async with self._f._pending_llm_lock:
                    self._f._pending_llm.pop(dedup_key, None)

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Coordination primitives (slot & task waiting)
    # ═══════════════════════════════════════════════════════════════════════════

    async def wait_for_llm_tasks(self) -> None:
        """
        Wait until all LLM-using tasks have completed.

        Since all LLM calls are serialized via `_llm_semaphore` (limit 1),
        waiting for the semaphore to be fully available guarantees that
        no LLM calls are currently in progress and no tasks are pending.
        """
        async with self._f._llm_semaphore:
            pass

    async def wait_for_slot(self) -> None:
        """
        Wait until the inference slot is free.

        This is an alias for `wait_for_llm_tasks()` that provides semantic
        clarity when the caller only needs to know the slot is available.
        """
        async with self._f._llm_semaphore:
            pass

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. CrossEncoder helper (keep full code decision)
    # ═══════════════════════════════════════════════════════════════════════════

    async def should_keep_full_code(
        self, user_question: str, project_id: str = ""
    ) -> bool:
        """
        Decide whether to keep the full code in context or provide only a summary.

        Cascade:
        1. Heuristic reinforcement (keywords for summary/full) with weight.
        2. CrossEncoder (primary).
        3. LLM (only when extremely uncertain, diff < LLM_THRESHOLD).
        4. Conservative default (True) in middle zone or on failure.

        Restores KV slot after any LLM call.

        Args:
            user_question (str): The user's question.
            project_id (str): Project id for slot restoration.

        Returns:
            bool: True if full code should be kept.
        """
        if not user_question.strip():
            return False

        context_parts = []
        if any(
            kw in user_question
            for kw in ("```", "def ", "class ", "import ", "from ", "function ")
        ):
            context_parts.append("[CODE]")
        if len(user_question.split()) < 10:
            context_parts.append("[SHORT]")
        context_prefix = " ".join(context_parts)
        query = f"{context_prefix} {user_question}" if context_parts else user_question

        pairs = [
            (
                query,
                "The user explicitly asks for the full implementation, detailed code, or exact syntax of a function.",
            ),
            (
                query,
                "The user only needs a summary, explanation of concepts, or high-level overview, not the full code.",
            ),
        ]
        scores = await self._f._commands._predict_cross_encoder(pairs)

        if scores is None or len(scores) < 2:
            return await self._should_keep_full_code_with_llm(
                user_question, None, project_id
            )

        # ── Heuristic reinforcement with weight ──
        content_lower = user_question.lower()
        summary_keywords = (
            "resume",
            "summary",
            "explica brevemente",
            "resumen",
            "briefly explain",
            "high-level",
        )
        full_code_keywords = (
            "implementa",
            "código",
            "función",
            "implement",
            "code",
            "function",
            "write",
        )
        h_weight = self._f.valves.heuristic_reinforcement_weight

        scores_reinforced = list(scores)
        if any(kw in content_lower for kw in summary_keywords):
            scores_reinforced[1] += h_weight * 0.2
        if any(kw in content_lower for kw in full_code_keywords):
            scores_reinforced[0] += h_weight * 0.2

        diff = scores_reinforced[0] - scores_reinforced[1]
        CE_CONFIDENCE_THRESHOLD = self._f.valves.keep_full_code_ce_threshold
        LLM_FALLBACK_THRESHOLD = self._f.valves.keep_full_code_llm_threshold

        if diff >= CE_CONFIDENCE_THRESHOLD:
            result = scores_reinforced[0] > scores_reinforced[1]
            self._f._log_debug(
                f"should_keep_full_code: CE confident (diff={diff:.2f}) → {result}"
            )
            return result
        elif diff < LLM_FALLBACK_THRESHOLD:
            self._f._log_debug(
                f"should_keep_full_code: CE uncertain (diff={diff:.2f} < {LLM_FALLBACK_THRESHOLD:.2f}), "
                "using LLM"
            )
            return await self._should_keep_full_code_with_llm(
                user_question, scores_reinforced, project_id
            )

        # Middle zone: conservative (keep full code)
        return True

    async def _should_keep_full_code_with_llm(
        self,
        user_question: str,
        ce_scores: Optional[List[float]] = None,
        project_id: str = "",
    ) -> bool:
        """
        LLM fallback to decide whether to show full code or a summary.

        Called when the CrossEncoder diff falls below keep_full_code_llm_threshold.
        Uses response_format={"type":"json_object"} and enable_thinking=False for
        a clean structured answer with no reasoning preamble.

        The default on parse failure is True (keep full code) to avoid silently
        omitting implementation details the user may need.

        Args:
            user_question: The user's message (truncated to 500 chars).
            ce_scores: Optional [full_score, summary_score] from the CrossEncoder.
            project_id: Current project identifier, used for slot restoration.

        Returns:
            bool: True to keep full code, False to use summary only.
        """
        if ce_scores is not None:
            ce_block = (
                f"CrossEncoder scores — keep_full: {ce_scores[0]:.2f}, "
                f"summary_only: {ce_scores[1]:.2f}\n\n"
            )
        else:
            ce_block = ""

        prompt = (
            f"{ce_block}"
            f"User question:\n{user_question[:500]}\n\n"
            f"Decide whether to show the full code or a summary.\n"
            f'Output {{"keep_full": true}} when the user asks for implementation '
            f"details, exact syntax, or complete code.\n"
            f'Output {{"keep_full": false}} when the user asks for explanation, '
            f"overview, or conceptual understanding.\n"
            f"When uncertain, prefer true to avoid omitting critical code."
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a decision engine. "
                "Output ONLY a valid JSON object with a single boolean field 'keep_full'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="keep_full_code_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        # Restore the KV slot after any auxiliary LLM call.
        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            self._f._log_debug(
                "_should_keep_full_code_with_llm: empty response, defaulting to FULL"
            )
            return True

        try:
            data = json.loads(response)
            result = bool(data.get("keep_full", True))
            self._f._log_debug(
                f"_should_keep_full_code_with_llm: decided {'FULL' if result else 'SUMMARY'}"
            )
            return result
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_should_keep_full_code_with_llm: JSON parse error — "
                f"response: {response[:200]!r}, defaulting to FULL"
            )
            return True


class ReasoningEngine:
    """Detects when Chain‑of‑Thought reasoning is appropriate and generates
    reasoning chains using the LLM.

    Provides:
    * ``detect_cot_level(query)`` — returns 0‑3 (inconclusive → deep
      scientific reasoning) using either a CrossEncoder classifier or a
      keyword‑based heuristic.
    * ``generate_cot_reasoning(question, context)`` — produces a step‑by‑step
      reasoning block (Level 2).
    * ``generate_architecture_reasoning(question, skeleton, project_id)`` —
      Level 2 reasoning that works on the code skeleton (contracts only)
      instead of the full system prompt, producing /expand hints for
      implementation.
    * ``generate_scientific_reasoning_L3(question, context, project_id)`` —
      multi‑hypothesis reasoning validated against the SymbolGraph
      (StaticEvidence).
    * ``generate_scientific_architecture_reasoning(...)`` — Level 3
      architecture reasoning that evaluates competing design options
      against structural evidence.
    * ``is_architecture_query(query)`` — fast regex test to route design /
      refactor queries to the skeleton‑based reasoning path.
    * ``parse_cot_intent(content)`` — extracts the question and level from
      explicit ``/think`` commands.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref

    # ── Architecture/design intent detection (regex) ─────────────────────

    _ARCH_INTENT_RE = re.compile(
        r"\b(arquitectura|architecture|diseño|design|refactor(?:iza)?r?|"
        r"plan\s+de\s+(implementaci[oó]n|cambios)|dise[ñn]a|restructur|"
        r"reorganiz|breakdown|dependency|dependencias|"
        r"c[oó]mo\s+(estructurar|organizar|dividir)|"
        r"qu[eé]\s+(clases|m[oó]dulos|componentes)\s+(necesito|crear|a[ñn]adir)|"
        r"propuesta\s+de|propose\s+(a\s+)?design|"
        r"abstract\s+(base\s+)?class|interface\s+design|"
        r"contrato|contracts?|API\s+surface|surface\s+area)\b",
        re.IGNORECASE,
    )

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Query classification (architecture intent, /think command parsing)
    # ═══════════════════════════════════════════════════════════════════════════

    def is_architecture_query(self, user_content: str) -> bool:
        """True when the query targets design / architecture / refactoring."""
        return bool(self._ARCH_INTENT_RE.search(user_content))

    async def parse_cot_intent(self, user_content: str) -> Tuple[Optional[str], int]:
        """Parse /think command: returns (question, level) or (None, 2)."""
        content = user_content.strip()
        if not content.startswith("/think"):
            return None, 2
        rest = content[6:].strip()
        if not rest:
            return None, 2
        parts = rest.split(maxsplit=1)
        if parts[0].isdigit():
            level = int(parts[0])
            if level not in (1, 2, 3):
                level = 2
            question = parts[1] if len(parts) > 1 else ""
        else:
            level = 2
            question = rest
        return question, level

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. CoT level detection (CrossEncoder / heuristic)
    # ═══════════════════════════════════════════════════════════════════════════

    def _reinforce_cot_level_detection_with_heuristic(
        self, user_content: str, ce_scores: List[float]
    ) -> List[float]:
        """
        Reinforce CrossEncoder scores with heuristic keyword analysis.

        The heuristic adds a bonus to the level that best matches the detected
        keywords in the user's message. This improves CrossEncoder accuracy
        without replacing its decision.

        The reinforcement is additive: the bonus is added directly to the
        CrossEncoder score for the target level. This influences the final
        decision only when the CrossEncoder is confident or the bonus pushes
        a level above the others.

        Args:
            user_content (str): The user's message content.
            ce_scores (List[float]): The 4 scores from the CrossEncoder.

        Returns:
            List[float]: The reinforced scores (CE + heuristic bonus).
        """
        if not user_content:
            return ce_scores

        content_lower = user_content.lower()

        # ── Keyword sets for each level ──
        # Level 0: Trivial (no specific keywords)
        # Level 1: Simple reasoning
        level1_keywords = [
            "explica",
            "explain",
            "describe",
            "qué es",
            "what is",
            "como funciona",
            "how works",
        ]
        # Level 2: Complex reasoning
        level2_keywords = [
            "depura",
            "debug",
            "analiza",
            "analyze",
            "paso a paso",
            "step by step",
            "implementa",
            "implement",
            "diseño",
            "design",
            "arquitectura",
            "architecture",
            "refactor",
            "cómo",
            "how to",
        ]
        # Level 3: Deep reasoning
        level3_keywords = [
            "impacto",
            "impact",
            "sistémico",
            "system-wide",
            "científico",
            "scientific",
            "exhaustivo",
            "exhaustive",
            "multi-hipótesis",
            "multi-hypothesis",
        ]

        # ── Count matches per level ──
        level1_score = sum(1 for kw in level1_keywords if kw in content_lower)
        level2_score = sum(1 for kw in level2_keywords if kw in content_lower)
        level3_score = sum(1 for kw in level3_keywords if kw in content_lower)

        # ── Determine bonus based on strongest keyword signal ──
        if level3_score >= 2:
            bonus = 0.3
            target_level = 3
        elif level2_score >= 2:
            bonus = 0.2
            target_level = 2
        elif level1_score >= 2:
            bonus = 0.1
            target_level = 1
        else:
            # No clear signal, return original scores
            return ce_scores

        # ── Apply bonus to the target level ──
        reinforced_scores = list(ce_scores)
        reinforced_scores[target_level] += bonus

        return reinforced_scores

    async def detect_cot_configuration(
        self,
        user_content: str,
        is_code_session: bool,
        state: dict,
        signal_vector: Optional[Dict[str, int]] = None,
        is_continuation: bool = False,
        project_id: str = "",
    ) -> Dict[str, Any]:
        """
        Detect the full CoT configuration for the current turn.

        Returns a dict with the following guaranteed keys and types:
            level                  : int   in [1, 3]
            enable_scientific_cot  : bool
            enable_architecture_mode: bool
            cot_label              : str
            use_multi_focus        : bool
            focus_questions        : list

        All keys are normalized after LLM classification. Without normalization,
        a partial LLM response (missing keys) causes KeyError in callers, and
        truthy string values like "true" / "false" are not automatically cast
        to bool, causing silent logic errors in conditions like
        `if cot_config["enable_scientific_cot"]`.

        Steps:
            1.  Detect CoT level.
            2.  Compute feature hints and signal vector.
            3.  Call _classify_cot_config_with_llm.
            4.  Normalize: ensure all canonical keys exist with correct types.
            5.  Apply valve-based overrides.
            6.  Return.
        """
        _DEFAULTS: Dict[str, Any] = {
            "level": 1,
            "enable_scientific_cot": False,
            "enable_architecture_mode": False,
            "cot_label": "General Programming",
            "use_multi_focus": False,
            "focus_questions": [],
        }

        # -- Step 1: detect CoT level --
        level = await self.detect_cot_level(
            user_content, is_code_session, state, is_continuation
        )

        # -- Step 2: compute hints --
        if signal_vector is None:
            signal_vector = {}
        hints = self._compute_feature_hints(
            user_content, is_code_session, signal_vector, level
        )

        # -- Step 3: LLM config classification --
        raw: Dict[str, Any] = {}
        try:
            level_scores = hints.get("level_scores")
            sci_scores = hints.get("sci_scores")
            raw = await self._classify_cot_config_with_llm(
                user_content=user_content,
                is_code_session=is_code_session,
                level_scores=level_scores,
                sci_scores=sci_scores,
                hints=hints,
                project_id=project_id,
            )
            if not isinstance(raw, dict):
                raw = {}
        except Exception as e:
            self._f._log_debug(
                f"detect_cot_configuration: LLM failed for '{project_id}': "
                f"{type(e).__name__}: {e}"
            )

        # -- Step 4: normalize all keys to correct types --
        config: Dict[str, Any] = dict(_DEFAULTS)
        config["level"] = level  # always use the clamped value from Step 1

        def _to_bool(val: Any, default: bool) -> bool:
            if isinstance(val, bool):
                return val
            if isinstance(val, int):
                return bool(val)
            if isinstance(val, str):
                return val.strip().lower() in ("true", "1", "yes")
            return default

        def _to_int(val: Any, default: int, lo: int, hi: int) -> int:
            try:
                return max(lo, min(hi, int(float(str(val)))))
            except (TypeError, ValueError):
                return default

        if "level" in raw:
            config["level"] = _to_int(raw["level"], level, 1, 3)

        if "enable_scientific_cot" in raw:
            config["enable_scientific_cot"] = _to_bool(
                raw["enable_scientific_cot"], False
            )

        if "enable_architecture_mode" in raw:
            config["enable_architecture_mode"] = _to_bool(
                raw["enable_architecture_mode"], False
            )

        if "cot_label" in raw:
            label_raw = raw["cot_label"]
            config["cot_label"] = (
                str(label_raw).strip() if label_raw else _DEFAULTS["cot_label"]
            )

        if "use_multi_focus" in raw:
            config["use_multi_focus"] = _to_bool(raw["use_multi_focus"], False)

        if "focus_questions" in raw:
            fq = raw["focus_questions"]
            config["focus_questions"] = fq if isinstance(fq, list) else []

        # -- Step 5: valve overrides --
        if not self._f.valves.enable_scientific_cot:
            config["enable_scientific_cot"] = False

        if self.is_architecture_query(user_content):
            config["enable_architecture_mode"] = True
            config["level"] = 3

        if not is_code_session:
            config["enable_architecture_mode"] = False

        self._f._log_debug(
            f"detect_cot_configuration: L{config['level']}, "
            f"sci={config['enable_scientific_cot']}, "
            f"arch={config['enable_architecture_mode']}, "
            f"label='{config['cot_label']}' "
            f"for '{project_id}'"
        )

        # -- Step 6: return --
        return config

    async def _classify_cot_config_with_llm(
        self,
        user_content: str,
        is_code_session: bool,
        level_scores: Optional[List[float]],
        sci_scores: Optional[List[float]],
        hints: Dict[str, Any],
        project_id: str,
    ) -> Dict[str, Any]:
        """
        LLM arbiter for CoT feature configuration.
        Called when CrossEncoder lacks confidence on any dimension,
        or when CrossEncoder is entirely unavailable.

        Receives the full cascaded signal picture:
        - Raw + reinforced CE scores (level + scientific) if available
        - SymbolGraph signal (n_found, structural_hits, n_relations)
        - Heuristic estimates (ambiguity_score, traceback, heuristic_level)
        - The query itself

        This is the ONLY stage where human-quality semantic judgment
        is applied. Every prior stage has already filtered and enriched
        the context so the LLM can make the most informed decision.

        Falls back to heuristic estimate on any failure.
        Uses summarization_model (fast, cheap).
        """
        _fallback = {
            "level": max(hints.get("heuristic_level", 2), 1),
            "use_scientific": hints.get("heuristic_suggests_scientific", False),
            "decompose": hints.get("multi_question", False),
            "source": "heuristic_fallback",
            "rationale": "LLM classification unavailable",
        }

        # ── Build CE summary ──────────────────────────────────────────────
        if level_scores and len(level_scores) >= 4:
            ce_level_line = (
                f"L0 trivial={level_scores[0]:.2f}  "
                f"L1 simple={level_scores[1]:.2f}  "
                f"L2 step-by-step={level_scores[2]:.2f}  "
                f"L3 system-wide={level_scores[3]:.2f}"
            )
        else:
            ce_level_line = "Level scores: CrossEncoder unavailable"

        if sci_scores and len(sci_scores) >= 2:
            ce_sci_line = (
                f"Scientific/multi-hypothesis={sci_scores[0]:.2f}  "
                f"Linear/single-direction={sci_scores[1]:.2f}"
            )
        else:
            ce_sci_line = "Mode scores: CrossEncoder unavailable"

        prompt = (
            f"=== CrossEncoder scores (after heuristic reinforcement) ===\n"
            f"Level:  {ce_level_line}\n"
            f"Mode:   {ce_sci_line}\n\n"
            f"=== Heuristic and structural signals ===\n"
            f"Heuristic level estimate:    L{hints.get('heuristic_level', '?')}\n"
            f"Heuristic suggests sci:      {hints.get('heuristic_suggests_scientific', False)}\n"
            f"Ambiguity patterns matched:  {hints.get('ambiguity_score', 0)}\n"
            f"Traceback present:           {hints.get('has_traceback', False)}\n"
            f"Multiple independent Qs:     {hints.get('multi_question', False)}\n"
            f"Codebase symbols found:      {hints.get('n_found', 0)} verified, "
            f"{hints.get('n_mentioned', 0)} mentioned, "
            f"{hints.get('n_relations', 0)} call relations\n\n"
            f"=== User query ===\n"
            f"{user_content[:500]}\n\n"
            f"=== Task ===\n"
            "Determine the optimal reasoning configuration.\n\n"
            "LEVEL (depth of reasoning chain to generate):\n"
            "  0 — trivial: single fact, definition, direct command\n"
            "  1 — simple: some logic, one clear answer\n"
            "  2 — step-by-step: multi-step reasoning, clear direction\n"
            "  3 — deep: system-wide, multi-component, impact analysis\n\n"
            "USE_SCIENTIFIC — activate multi-hypothesis competition validated\n"
            "against the codebase SymbolGraph. Set true ONLY when ALL hold:\n"
            "  - level >= 2\n"
            "  - root cause or best approach is genuinely ambiguous\n"
            "    (multiple structural possibilities exist)\n"
            "  - at least 1 known codebase symbol is mentioned (n_found >= 1)\n"
            "  TRUE for: debugging with unclear cause, non-deterministic\n"
            "    failures, cascading impact of a specific change.\n"
            "  FALSE for: general explanations, implementing a known pattern,\n"
            "    architecture queries where one design direction is clear,\n"
            "    any query without specific symbols (n_found == 0).\n\n"
            "DECOMPOSE — query contains 2+ genuinely independent questions\n"
            "  needing separate code contexts to answer well.\n\n"
            'Output ONLY valid JSON: {"level": 0|1|2|3, '
            '"use_scientific": true|false, "decompose": true|false, '
            '"rationale": "one concise line explaining the key decision"}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a reasoning configuration classifier for a code-aware "
                "AI assistant. Output ONLY a valid JSON object. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="cot_config_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            self._f._log_debug("cot_config_llm: no response → heuristic fallback")
            return _fallback

        try:
            data = json.loads(response)
            level = int(data.get("level", hints.get("heuristic_level", 2)))
            if level not in (0, 1, 2, 3):
                level = 2
            config = {
                "level": level,
                "use_scientific": bool(data.get("use_scientific", False)),
                "decompose": bool(data.get("decompose", False)),
                "source": "llm",
                "rationale": str(data.get("rationale", ""))[:120],
            }
            self._f._log_debug(
                f"cot_config_llm: level={config['level']}, "
                f"scientific={config['use_scientific']}, "
                f"decompose={config['decompose']}, "
                f"rationale='{config['rationale']}'"
            )
            return config
        except (json.JSONDecodeError, Exception) as e:
            self._f._log_debug(
                f"cot_config_llm: parse error ({type(e).__name__}) → heuristic fallback"
            )
            return _fallback

    def _compute_feature_hints(
        self,
        user_content: str,
        is_code_session: bool,
        signal_vector: Dict[str, int],
        heuristic_level: int,
    ) -> Dict[str, Any]:
        """
        Compute feature hints from deterministic signals.
        No LLM. No GPU. Always runs after the heuristic.

        Feeds three downstream consumers:
        1. _reinforce_cot_scores — adjusts CE scores (additive nudges)
        2. _classify_cot_config_with_llm — LLM prompt context
        3. CoTConfig fallback when LLM is unavailable

        ambiguity_score: count of patterns suggesting the query has multiple
            plausible structural root causes. Primary signal for recommending
            scientific (multi-hypothesis) mode. Weighted: strong patterns
            count 2, medium patterns count 1.

        heuristic_suggests_scientific: pre-computed recommendation.
            True when: ambiguity_score >= 2
                    OR (has_traceback AND n_found >= 1)
                    OR (ambiguity_score >= 1 AND n_found >= 2)
            Advisory — CE reinforcement and LLM can confirm or override.
        """
        content_lower = user_content.lower()
        n_found = signal_vector.get("n_found", 0)

        # ── Ambiguity patterns ────────────────────────────────────────────
        # Strong (+2): explicit root-cause uncertainty, non-determinism
        _STRONG: List[Tuple[str, int]] = [
            (r"por\s+qu[eé]\s+(falla|no\s+funciona|devuelve|retorna|no\s+trabaja)", 2),
            (
                r"why\s+(does\s+it|is\s+it|do(?:es)?)\s+(?:fail|return|not\s+work|break|crash)",
                2,
            ),
            (
                r"\b(?:sometimes|intermitent(?:e|ly)|a\s+veces|no\s+siempre|not\s+always)\b",
                2,
            ),
            (r"\b(?:root\s+cause|causa\s+ra[íi]z)\b", 2),
            (r"returns?\s+(?:none|null)\b", 2),
            (
                r"(?:no\s+s[eé]|not\s+sure|can'?t\s+figure\s+out)\s+(?:why|por\s+qu[eé])",
                2,
            ),
            (r"\b(?:unexpected|inesperado|not\s+what\s+i\s+expect)", 2),
        ]
        # Medium (+1): softer hints at ambiguity
        _MEDIUM: List[Tuple[str, int]] = [
            (r"\b(?:could\s+it\s+be|podr[íi]a\s+ser|might\s+be)\b", 1),
            (r"\b(?:strange|raro|weird|odd|extra[ñn]o)\b", 1),
            (r"(?:doesn'?t\s+make\s+sense|no\s+tiene\s+sentido)", 1),
            (
                r"\b(?:multiple|varios|varias)\s+(?:causes?|razones?|reasons?|posibilidades)",
                1,
            ),
            (r"\b(?:randomly|aleator(?:io|iamente)|random(?:ly)?)\b", 1),
            (r"(?:works?\s+(?:locally|in\s+dev)|fails?\s+in\s+(?:prod|production))", 1),
            (r"(?:no\s+siempre|not\s+consistent)", 1),
        ]

        ambiguity_score = 0
        for pattern, weight in _STRONG + _MEDIUM:
            if re.search(pattern, content_lower):
                ambiguity_score += weight

        # ── Traceback ─────────────────────────────────────────────────────
        has_traceback = bool(
            re.search(
                r"traceback\s*\(most\s+recent|"
                r"file\s+\"[^\"]+\",\s+line\s+\d+|"
                r"at\s+\w+\.\w+\([\w.:]+:\d+\)",
                content_lower,
            )
        )

        # ── Multi-question ─────────────────────────────────────────────────
        paragraphs_with_q = [
            p.strip()
            for p in re.split(r"\n\s*\n", user_content)
            if "?" in p and len(p.strip()) > 15
        ]
        spanish_questions = re.findall(r"¿[^¿?]+\?", user_content)
        multi_question = len(paragraphs_with_q) >= 2 or len(spanish_questions) >= 2

        # ── Derived recommendation ─────────────────────────────────────────
        heuristic_suggests_scientific = bool(
            ambiguity_score >= 2
            or (has_traceback and n_found >= 1)
            or (ambiguity_score >= 1 and n_found >= 2)
        )

        return {
            "ambiguity_score": ambiguity_score,
            "has_traceback": has_traceback,
            "multi_question": multi_question,
            "n_found": n_found,
            "structural_hits": signal_vector.get("structural_hits", 0),
            "n_mentioned": signal_vector.get("n_mentioned", 0),
            "n_relations": signal_vector.get("n_relations", 0),
            "heuristic_level": heuristic_level,
            "heuristic_suggests_scientific": heuristic_suggests_scientific,
        }

    def _reinforce_cot_scores(
        self,
        level_scores: List[float],
        sci_scores: List[float],
        hints: Dict[str, Any],
    ) -> Tuple[List[float], List[float]]:
        """
        Adjust CrossEncoder scores using deterministic heuristic signals.
        Extends _reinforce_cot_level_detection_with_heuristic to also
        handle the scientific/linear dimension.

        Philosophy: additive nudges, never multiplicative overrides.
        The CE's semantic understanding dominates; hints add factual
        context the CE couldn't see in the text alone (e.g., "this query
        mentions 3 known symbols verified in the SymbolGraph").

        All scores clamped to [0.0, 1.0].

        level_scores: [L0, L1, L2, L3] from CrossEncoder
        sci_scores:   [scientific, linear] from CrossEncoder

        Returns reinforced (level_scores, sci_scores).
        """
        lv = list(level_scores)
        sc = list(sci_scores)

        ambiguity = hints.get("ambiguity_score", 0)
        has_tb = hints.get("has_traceback", False)
        n_found = hints.get("n_found", 0)
        s_hits = hints.get("structural_hits", 0)
        multi_q = hints.get("multi_question", False)
        h_level = hints.get("heuristic_level", 0)
        h_sci = hints.get("heuristic_suggests_scientific", False)

        # ── Level reinforcement ───────────────────────────────────────────
        if has_tb:
            lv[3] = min(1.0, lv[3] + 0.20)  # traceback → deep analysis
            lv[0] = max(0.0, lv[0] - 0.20)  # definitely not trivial
            lv[1] = max(0.0, lv[1] - 0.10)

        if multi_q:
            lv[3] = min(1.0, lv[3] + 0.10)

        if h_level == 3:
            lv[3] = min(1.0, lv[3] + 0.15)
        elif h_level == 2:
            lv[2] = min(1.0, lv[2] + 0.10)
        elif h_level <= 0:
            lv[0] = min(1.0, lv[0] + 0.10)

        # ── Scientific reinforcement ──────────────────────────────────────
        # Ambiguity patterns
        if ambiguity >= 2:
            sc[0] = min(1.0, sc[0] + min(0.30, 0.10 * ambiguity))
        elif ambiguity == 1:
            sc[0] = min(1.0, sc[0] + 0.08)

        # Traceback: cause unknown → multi-hypothesis value
        if has_tb:
            sc[0] = min(1.0, sc[0] + 0.15)

        # Rich structural context → competition makes sense
        if n_found >= 2 and s_hits >= 3:
            sc[0] = min(1.0, sc[0] + 0.15)
        elif n_found >= 1 and s_hits >= 2:
            sc[0] = min(1.0, sc[0] + 0.08)

        # No known symbols → suppress scientific (nothing to falsify)
        if n_found == 0:
            sc[0] = max(0.0, sc[0] - 0.20)
            sc[1] = min(1.0, sc[1] + 0.10)

        # Heuristic consensus
        if h_sci:
            sc[0] = min(1.0, sc[0] + 0.10)

        return lv, sc

    async def detect_cot_level(
        self,
        user_content: str,
        is_code_session: bool,
        state: dict,
        is_continuation: bool = False,
    ) -> int:
        """
        Classify the required Chain-of-Thought depth for the current message.

        Returns an integer in [1, 3]:
            1 — direct answer, minimal reasoning
            2 — structured explanation, moderate reasoning
            3 — scientific / architectural deep reasoning

        The result is always clamped to [1, 3] after classification, regardless
        of what the heuristic or LLM returns. Without the clamp, a malformed
        LLM response of "0" or "4" propagates to callers that assume the value
        is in the valid range, silently disabling or over-triggering CoT.

        Steps:
            1.  Heuristic fast path via _detect_cot_level_heuristic.
            2.  Run cross-encoder against CoT-level exemplars.
            3.  Call _classify_with_crossencoder_and_llm when heuristic is uncertain.
            4.  Clamp final result to [1, 3] and return.
        """
        # -- Step 1: heuristic --
        heuristic_level = self._detect_cot_level_heuristic(
            user_content, is_code_session, state
        )

        heuristic_threshold = getattr(
            self._f.valves, "cot_heuristic_confidence_threshold", 0.85
        )

        # Architecture queries always get L3 regardless of heuristic confidence
        if self.is_architecture_query(user_content):
            self._f._log_debug("detect_cot_level: architecture query → L3")
            return 3

        # -- Step 2: cross-encoder --
        exemplars = [
            "simple quick question answer fact lookup",
            "explain how implement step by step detailed",
            "design architecture analyze system scientific hypothesis",
        ]
        pairs = [(user_content[:512], ex) for ex in exemplars]
        raw_ce = await self._f._command_router._predict_cross_encoder(pairs)
        ce_scores: List[float] = (
            [self._f._command_router._normalize_cross_encoder_score(s) for s in raw_ce]
            if raw_ce is not None
            else []
        )

        if ce_scores and len(ce_scores) == 3:
            ce_scores = self._reinforce_cot_level_detection_with_heuristic(
                user_content, ce_scores
            )
            max_score = max(ce_scores)
            ce_level = ce_scores.index(max_score) + 1

            if max_score >= heuristic_threshold:
                result = ce_level
                self._f._log_debug(
                    f"detect_cot_level: CE sufficient "
                    f"(L{ce_level}, score={max_score:.2f})"
                )
                return max(1, min(3, result))

        # -- Step 3: LLM classification --
        try:
            raw_level = await self._classify_with_crossencoder_and_llm(
                user_content=user_content,
                is_code_session=is_code_session,
                crossencoder_scores=ce_scores or None,
            )
        except Exception as e:
            self._f._log_debug(
                f"detect_cot_level: LLM failed, using heuristic "
                f"L{heuristic_level}: {type(e).__name__}: {e}"
            )
            raw_level = heuristic_level

        # -- Step 4: clamp to [1, 3] --
        try:
            level = int(float(str(raw_level).strip()))
        except (ValueError, TypeError):
            self._f._log_debug(
                f"detect_cot_level: unparseable level '{raw_level}', "
                f"falling back to heuristic L{heuristic_level}"
            )
            level = heuristic_level

        clamped = max(1, min(3, level))
        if clamped != level:
            self._f._log_debug(f"detect_cot_level: clamped L{level} → L{clamped}")

        return clamped

    async def _classify_with_crossencoder_and_llm(
        self,
        user_content: str,
        is_code_session: bool,
        crossencoder_scores: Optional[List[float]] = None,
    ) -> int:
        """
        Use the LLM to classify the CoT level, optionally informed by CrossEncoder scores.

        If crossencoder_scores is provided, they are included in the prompt as context.
        If None, the LLM classifies without CrossEncoder context (pure LLM mode).

        If the LLM returns an invalid response, default to level 2 (complex), which
        is the safest assumption for code-related questions.

        Args:
            user_content (str): The user's message content.
            is_code_session (bool): Whether the session is code-aware.
            crossencoder_scores (Optional[List[float]]): The 4 scores from the CrossEncoder,
                or None if not available.

        Returns:
            int: 0-3 (same as detect_cot_level).
        """
        # ── Build the prompt ──
        if crossencoder_scores is not None:
            # ── With CrossEncoder context ──
            max_score = max(crossencoder_scores)
            best_level = int(np.argmax(crossencoder_scores))
            second_max = (
                sorted(crossencoder_scores, reverse=True)[1]
                if len(crossencoder_scores) > 1
                else 0
            )
            diff = max_score - second_max
            confidence = "high" if diff > 0.5 else "medium" if diff > 0.3 else "low"

            ce_summary = f"""
The CrossEncoder has analyzed the question and provides the following scores:
- Level 0 (Trivial): {crossencoder_scores[0]:.2f}
- Level 1 (Moderate): {crossencoder_scores[1]:.2f}
- Level 2 (Complex): {crossencoder_scores[2]:.2f}
- Level 3 (Deep): {crossencoder_scores[3]:.2f}

The highest score is Level {best_level} (score: {max_score:.2f}), with {confidence} confidence.
"""

            prompt = f"""
{ce_summary}

Now, independently analyze the user's question and determine the appropriate reasoning level.

User question:
{user_content[:500]}

Level definitions:
- Level 0: Simple fact, definition, or direct command. No reasoning needed.
- Level 1: Requires some logical reasoning but the answer is straightforward.
- Level 2: Requires step-by-step reasoning, analysis of multiple steps or dependencies.
- Level 3: Requires deep, open-ended, or system-wide analysis, scientific reasoning, or impact evaluation.

Output only the number (0, 1, 2, or 3) that best represents the reasoning complexity required.
"""
        else:
            # ── Without CrossEncoder context (pure LLM) ──
            prompt = f"""
Classify the following user question into one of four levels of reasoning complexity:

Level 0: Simple fact, definition, or direct command. No reasoning needed.
Level 1: Requires some logical reasoning but the answer is straightforward.
Level 2: Requires step-by-step reasoning, analysis of multiple steps or dependencies.
Level 3: Requires deep, open-ended, or system-wide analysis, scientific reasoning, or impact evaluation.

User question:
{user_content[:500]}

Output only the number (0, 1, 2, or 3):
"""

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt="You are a classifier. Output only a single number from 0 to 3.",
            model_override=self._f.valves.summarization_model,
            max_tokens=5,
            temperature=0.0,
            label="cot_llm_with_ce" if crossencoder_scores else "cot_llm_pure",
        )

        if response and response.strip().isdigit():
            level = int(response.strip())
            if 0 <= level <= 3:
                return level

        # ── If LLM fails, default to level 2 (complex) ──
        # Level 2 is the safest assumption for code-related questions.
        self._f._log_debug(
            "CoT detection: LLM returned invalid response, defaulting to level 2."
        )
        return 2

    async def _detect_cot_level_via_llm(
        self,
        user_content: str,
        is_code_session: bool,
        state: dict,
        is_continuation: bool = False,
    ) -> int:
        """
        Determine CoT depth using a hybrid approach.

        1. CrossEncoder provides an initial assessment.
        2. If enabled, heuristic reinforces the CrossEncoder scores (adds bonus based on keywords).
        3. If confident, use the reinforced (or raw) CrossEncoder.
        4. If uncertain, use LLM with CrossEncoder context.
        5. If CrossEncoder unavailable, use LLM alone (pure).
        6. If LLM fails, default to level 2 (complex) as a safe assumption.

        The heuristic reinforcement can be toggled via the
        enable_cot_heuristic_reinforcement valve for A/B testing.

        Args:
            user_content (str): The user's message content.
            is_code_session (bool): Whether the session is code-aware.
            state (dict): The conversation state (unused, kept for API consistency).
            is_continuation (bool): Whether this is a continuation turn.

        Returns:
            int: 0 (no CoT), 1 (simple), 2 (complex), or 3 (deep).
        """
        session_type = "code" if is_code_session else "general"
        intent_hint = ""
        if (
            hasattr(self._f, "_user_intent_full_code")
            and self._f._user_intent_full_code is not None
        ):
            intent_hint = (
                "The user likely needs the full code."
                if self._f._user_intent_full_code
                else "The user likely needs only a summary of the code."
            )

        # ── Enrich query with context tags ──
        context_parts = []
        if "```" in user_content or any(
            kw in user_content
            for kw in ("def ", "class ", "import ", "from ", "function ")
        ):
            context_parts.append("[CODE]")
        if "traceback" in user_content.lower() or 'File "' in user_content:
            context_parts.append("[TRACEBACK]")
        if is_continuation:
            context_parts.append("[CONTINUATION]")
        context_prefix = " ".join(context_parts)
        base_query = f"[Session: {session_type}] {intent_hint} {user_content[:500]}"
        query = f"{context_prefix} {base_query}" if context_parts else base_query

        # ── Build pairs with improved level descriptions ──
        pairs = [
            (
                query,
                "The user asks a trivial question about code: a simple fact, a definition, or a direct command that does not require reasoning or analysis.",
            ),
            (
                query,
                "The user asks a moderately complex question about code that requires some logical reasoning, but the answer is straightforward and does not require deep analysis.",
            ),
            (
                query,
                "The user asks a complex question about code that involves multiple steps, dependencies, architectural decisions, or debugging that requires step-by-step reasoning.",
            ),
            (
                query,
                "The user asks a deep, open-ended, or system-wide question about code that requires exhaustive analysis, impact evaluation, scientific reasoning, or multi-hypothesis validation.",
            ),
        ]
        scores = await self._f._commands._predict_cross_encoder(pairs)

        # ── CrossEncoder available ──
        if scores is not None:
            # ── Apply heuristic reinforcement if enabled ──
            if self._f.valves.enable_cot_heuristic_reinforcement:
                scores_for_decision = (
                    self._reinforce_cot_level_detection_with_heuristic(
                        user_content, scores
                    )
                )
                reinforcement_status = "with heuristic reinforcement"
            else:
                scores_for_decision = scores
                reinforcement_status = "without heuristic reinforcement"

            # If cascade is disabled, use LLM alone (without CE context)
            if not self._f.valves.enable_cot_cascade:
                self._f._log_debug(f"CoT detection: Cascade disabled, using LLM alone.")
                return await self._classify_with_crossencoder_and_llm(
                    user_content, is_code_session, crossencoder_scores=None
                )

            # Check confidence threshold on the chosen scores
            max_score = max(scores_for_decision)
            second_max = (
                sorted(scores_for_decision, reverse=True)[1]
                if len(scores_for_decision) > 1
                else 0
            )
            diff = max_score - second_max
            threshold = self._f.valves.cot_cascade_uncertainty_threshold

            # If CrossEncoder is confident, use it directly
            if diff >= threshold:
                best_level = int(np.argmax(scores_for_decision))
                self._f._log_debug(
                    f"CoT detection: CrossEncoder confident {reinforcement_status} "
                    f"(diff={diff:.2f} >= {threshold:.2f}), using level {best_level}"
                )
                return best_level

            # CrossEncoder uncertain → LLM with CE context
            self._f._log_debug(
                f"CoT detection: CrossEncoder uncertain {reinforcement_status} "
                f"(diff={diff:.2f} < {threshold:.2f}), using LLM with CrossEncoder context"
            )
            return await self._classify_with_crossencoder_and_llm(
                user_content, is_code_session, crossencoder_scores=scores
            )

        # ── CrossEncoder unavailable → LLM alone (pure) ──
        self._f._log_debug("CoT detection: CrossEncoder unavailable, using LLM alone.")
        return await self._classify_with_crossencoder_and_llm(
            user_content, is_code_session, crossencoder_scores=None
        )

    def _detect_cot_level_heuristic(
        self, user_content: str, is_code_session: bool, state: dict
    ) -> int:
        """
        Determine the depth of Chain-of-Thought reasoning needed using heuristic keyword analysis.

        Returns:
            0 — inconclusive, let LLM decide
            1 — simple, inject a think-step-by-step prompt
            2 — complex, generate a CoT reasoning chain
            3 — deep, generate CoT reasoning + self-reflection
        """
        # ── Keyword sets ────────────────────────────────────────────────────
        complex_keywords_generic = {
            "explain how",
            "explica cómo",
            "how does",
            "cómo funciona",
            "how to implement",
            "cómo implementar",
            "why does",
            "por qué falla",
            "why is",
            "por qué es",
            "implement",
            "implementa",
            "system design",
            "diseño del sistema",
            "design a",
            "diseña un",
            "design the",
            "diseña el",
            "architecture",
            "arquitectura",
            "build a",
            "construye",
            "create a class",
            "crea una clase",
            "add support for",
            "añadir soporte para",
            "extend the",
            "extiende el",
            "debug",
            "depura",
            "fix the",
            "corrige el",
            "not working",
            "no funciona",
            "doesn't work",
            "no me funciona",
            "keeps failing",
            "sigue fallando",
            "throws an error",
            "lanza un error",
            "unexpected behavior",
            "comportamiento inesperado",
            "memory leak",
            "fuga de memoria",
            "bottleneck",
            "cuello de botella",
            "optimize",
            "optimiza",
            "refactor",
            "refactoriza",
            "migrate",
            "migra",
            "code review",
            "revisión de código",
            "audit",
            "audita",
            "integrate",
            "integra",
            "deploy",
            "despliega",
            "set up",
            "configura el entorno",
            "step by step",
            "paso a paso",
            "full implementation",
            "implementación completa",
            "best practices",
            "buenas prácticas",
            "comprehensive",
            "completo y detallado",
        }

        complex_keywords_code_only = {
            "test",
            "prueba",
            "configure",
            "configura",
            "scaffold",
            "fix",
            "corrige",
            "review",
            "revisa",
            "structure",
            "estructura",
            "compare",
            "compara",
            "improve",
            "mejora",
            "validate",
            "valida",
        }

        deep_keywords = {
            "deep review",
            "revisión profunda",
            "check every step",
            "comprueba cada paso",
            "razonamiento exhaustivo",
            "production ready",
            "listo para producción",
            "edge cases",
            "casos límite",
            "trade-offs",
            "ventajas y desventajas",
            "security review",
            "revisión de seguridad",
            "performance analysis",
            "análisis de rendimiento",
            "ensure correctness",
            "garantiza la corrección",
            "deep reflection",
            "reflexión profunda",
            "self-reflection",
            "auto-reflexión",
            "auto-evalúa",
            "itera varias veces",
            "exhaustive",
            "exhaustivo",
            "all edge cases",
            "todos los casos límite",
        }

        # ── Optional accent normalisation ───────────────────────────────────
        if self._f.ENABLE_ACCENT_NORMALIZATION:
            import unicodedata

            def _normalize(text: str) -> str:
                nfkd = unicodedata.normalize("NFKD", text)
                return nfkd.encode("ascii", "ignore").decode("ascii")

            content_lower = _normalize(user_content.lower())
            complex_keywords_generic = {_normalize(k) for k in complex_keywords_generic}
            complex_keywords_code_only = {
                _normalize(k) for k in complex_keywords_code_only
            }
            deep_keywords = {_normalize(k) for k in deep_keywords}
        else:
            content_lower = user_content.lower()

        word_count = len(user_content.split())
        has_code = "```" in user_content
        length_ok = len(user_content) >= self._f.valves.auto_cot_min_chars
        too_short = word_count < 5

        # ── Context: expand active set when in a code session ──────────────
        active_complex = set(complex_keywords_generic)
        if is_code_session:
            active_complex |= complex_keywords_code_only

        # ── Negation guard ─────────────────────────────────────────────────
        def _is_negated(text: str, kw: str) -> bool:
            start = 0
            while True:
                idx = text.find(kw, start)
                if idx == -1:
                    break
                before = text[:idx].strip().split()[-3:]
                if not any(neg in before for neg in self._f._COT_NEGATION_PREFIXES):
                    return False
                start = idx + 1
            return True

        _sorted_deep = sorted(deep_keywords, key=len, reverse=True)
        _sorted_complex = sorted(active_complex, key=len, reverse=True)

        def _contains_any(text: str, sorted_kw: list) -> bool:
            for kw in sorted_kw:
                if kw in text and not _is_negated(text, kw):
                    return True
            return False

        if too_short and not has_code:
            return 0

        if _contains_any(content_lower, _sorted_deep):
            return 3

        has_complex_kw = _contains_any(content_lower, _sorted_complex)
        is_elaborate = length_ok or word_count > 30

        signals = 0
        if self._f.ENABLE_KEYWORD_COUNT_WEIGHT:
            kw_matches = sum(
                1
                for kw in _sorted_complex
                if kw in content_lower and not _is_negated(content_lower, kw)
            )
            signals += min(kw_matches + 2, 4)
        else:
            if has_complex_kw:
                signals += 3

        if has_code:
            signals += 1
        if is_elaborate:
            signals += 1
        if user_content.count("?") >= 2:
            signals += 1
        if is_code_session and has_complex_kw:
            signals += 1

        for phrase in ("in detail", "en detalle"):
            if phrase in content_lower and not _is_negated(content_lower, phrase):
                signals += 1
                break

        if is_code_session:
            has_stack_trace = (
                "traceback (most recent call last)" in content_lower
                or "traceback:" in content_lower
                or ("exception" in content_lower and "at line" in content_lower)
                or bool(re.search(r'file ".+", line \d+', content_lower))
                or bool(re.search(r"at \w+\.\w+\([\w.]+:\d+\)", content_lower))
            )
            if has_stack_trace:
                signals += 2

        code_block_count = user_content.count("```") // 2
        if code_block_count >= 2:
            signals += 1

        if self._f.ENABLE_COT_STICKY:
            prev_level = state.last_cot_level
            if prev_level >= 2 and has_complex_kw:
                signals += 1

        if signals >= 5:
            return 2
        elif signals >= 3:
            return 1
        else:
            return 0

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Step‑back prompting (architectural context for better CoT)
    # ═══════════════════════════════════════════════════════════════════════════

    async def _generate_step_back_context(
        self, question: str, code_context: str
    ) -> str:
        """
        Generate an architectural step-back for better CoT hypothesis quality.

        Asks: "What high-level principle governs this code?" before diving
        into the specific bug/question.

        Returns a formatted string to prepend to the CoT context,
        or empty string if disabled or the LLM call fails.
        """
        if not self._f.valves.enable_step_back_prompting:
            return ""
        if len(question.strip()) < 15:
            return ""

        debug_signals = (
            "error",
            "fail",
            "bug",
            "wrong",
            "exception",
            "traceback",
            "falla",
            "error",
            "excepción",
            "no funciona",
        )
        question_lower = question.lower()
        if not any(signal in question_lower for signal in debug_signals):
            if not self._f.valves.step_back_always:
                return ""

        step_back_prompt = (
            f"A programmer is debugging this specific issue:\n{question[:300]}\n\n"
            "What is the underlying architectural principle, design invariant, or "
            "general concept that governs correct behavior here? "
            "State it as an abstract question and answer it in 2-3 sentences. "
            "Focus on system-level understanding, not the specific bug."
        )

        step_back_response = await self._f._llm_orchestrator.call_llm(
            prompt=step_back_prompt,
            system_prompt=(
                "You are a senior software architect. "
                "Answer the abstract question concisely (2-3 sentences). "
                "Focus on principles, not the specific implementation."
            ),
            model_override=self._f.valves.cot_model_level2,
            max_tokens=self._f.valves.step_back_max_tokens,
            temperature=0.3,
            label="step_back",
        )

        if step_back_response and step_back_response.strip():
            self._f._log_debug(
                "Step-back context generated "
                f"({len(step_back_response.split())} words)"
            )
            return (
                "## Architectural Context (Step-Back)\n"
                f"{step_back_response.strip()}\n\n"
                "---\n\n"
            )
        return ""

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Level 2 reasoning generation (standard CoT + architecture mode)
    # ═══════════════════════════════════════════════════════════════════════════

    async def generate_cot_reasoning(
        self, question: str, context: str, label: str = ""
    ) -> str:
        """
        Generate a Chain‑of‑Thought reasoning chain for the given question.

        This method is used for CoT levels 2 and 3 (moderately complex to
        deep reasoning). It takes the user's question and a context
        (typically the system prompt or skeleton) and asks the LLM to
        produce a step‑by‑step reasoning chain.

        The context is truncated to a token limit derived from the active
        context max tokens divided by 3. This balances providing enough
        context for reasoning while keeping the prompt size manageable
        and avoiding excessive latency.

        Args:
            question (str): The user's question to reason about.
            context (str): The context (system prompt, code, etc.) to reason on.
            label (str): Optional label for LLM call logging.

        Returns:
            str: A formatted reasoning chain with a header indicating the
            CoT level and model used, or "Unable to generate reasoning." on failure.
        """
        # ── REGION 1: Configure token limits ──
        effective_max_tokens = (
            self._f.valves.cot_max_tokens if self._f.valves.cot_max_tokens > 0 else None
        )

        # ── REGION 2: Optionally generate step‑back context ──
        step_back = await self._generate_step_back_context(question, context)
        enriched_context = step_back + context if step_back else context

        # ── REGION 3: Build the reasoning prompt ──
        # The question is passed in full (no truncation). The context is
        # truncated to a token limit that is a fraction of the model's
        # context window to keep the prompt manageable.
        prompt = (
            f"Context:\n{enriched_context}\n\n"
            f"Question:\n{question}\n\n"
            "Think step by step and provide your reasoning:"
        )

        # ── REGION 4: Call the LLM ──
        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a helpful assistant that thinks step by step before answering."
            ),
            model_override=self._f.valves.cot_model_level2,
            max_tokens=effective_max_tokens,
            temperature=0.4,
            label=label,
        )

        # ── REGION 5: Format and return ──
        if response:
            prefix = (
                "## 🔎 Automated Chain-of-Thought Reasoning (Level 2)\n"
                f"*Generated by {self._f.valves.cot_model_level2}.*"
            )
            if step_back:
                prefix += " *Includes step-back architectural context.*"
            return f"{prefix}\n\n{response}"
        return "Unable to generate reasoning."

    async def generate_architecture_reasoning(
        self,
        question: str,
        skeleton_context: str,
        project_id: str,
        label: str = "",
    ) -> str:
        """
        Generate architecture‑level reasoning using the code skeleton.

        This method is used for architecture, design, and refactoring queries
        where the full system prompt would be too large or noisy. It uses
        the project skeleton (signatures only, bodies as `...`) as the
        reasoning context, which is more focused on contracts and interfaces.

        The output includes concrete signature proposals and `/expand <name>`
        hints for implementation details, keeping the reasoning at the
        contract level.

        Args:
            question (str): The user's architecture/design question.
            skeleton_context (str): The project skeleton (signatures only).
            project_id (str): The current project identifier (unused but kept).
            label (str): Optional label for LLM call logging.

        Returns:
            str: Formatted architecture reasoning with signature proposals
            and /expand hints, or a fallback standard CoT if the skeleton
            is empty or the LLM call fails.
        """
        # ── REGION 1: Fallback to standard CoT if no skeleton is available ──
        if not skeleton_context.strip():
            return await self.generate_cot_reasoning(question, "", label=label)

        # ── REGION 2: Configure token limits ──
        effective_max_tokens = (
            self._f.valves.skeleton_cot_max_tokens
            if self._f.valves.skeleton_cot_max_tokens > 0
            else 600
        )

        # ── REGION 3: Build the architecture reasoning prompt ──
        # The question is passed in full (no truncation) to preserve all
        # context for the reasoning. The skeleton_context is capped to
        # 4000 characters to keep the prompt manageable.
        prompt = (
            f"Code skeleton (contracts only — bodies as `...`):\n"
            f"{skeleton_context[:4000]}\n\n"
            f"Architecture question:\n{question}\n\n"
            "Reason step by step at the CONTRACT level:\n"
            "1. Which classes / methods are affected and why?\n"
            "2. What invariants or interfaces must be preserved or changed?\n"
            "3. What new signatures are needed? Write them as skeleton lines.\n"
            "4. Which existing bodies need to change? List as `/expand <name>`.\n"
            "Be specific about signatures; avoid implementation details."
        )

        # ── REGION 4: Call the LLM for architecture reasoning ──
        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a software architect reasoning about code structure and "
                "contracts. Focus on interfaces, dependencies, and invariants. "
                "When a full implementation is needed, write `/expand <SymbolName>` "
                "instead of generating code."
            ),
            model_override=self._f.valves.cot_model_level2,
            max_tokens=effective_max_tokens,
            temperature=0.0,
            label=label or "arch_cot",
        )

        # ── REGION 5: Handle failure gracefully ──
        if not response or response.strip() == "Unable to generate reasoning.":
            self._f._log_debug("Architecture CoT failed — falling back to standard CoT")
            return await self.generate_cot_reasoning(
                question, skeleton_context, label=label
            )

        # ── REGION 6: Format and return the reasoning ──
        prefix = (
            "## 🏗️ Architecture Reasoning (skeleton-based CoT)\n"
            f"*Reasoning on contracts — use `/expand <name>` for implementations.*"
        )
        return f"{prefix}\n\n{response}"

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Level 3 scientific reasoning (multi‑hypothesis, evidence‑validated)
    # ═══════════════════════════════════════════════════════════════════════════

    async def _generate_initial_hypotheses(
        self,
        question: str,
        context: str,
        max_hypotheses: int,
        project_id: str,
        label: str = "",
    ) -> List[Tuple[str, float]]:
        """
        Generate the initial set of hypotheses for the scientific reasoning loop.
        Extracted from generate_scientific_reasoning_L3 REGION 2.
        Slot is restored after the LLM call.
        """
        prompt = (
            f"Context:\n{context[:3000]}\n\n"
            f"Question:\n{question}\n\n"
            f"Propose {max_hypotheses} distinct hypotheses that could explain "
            f"the issue or solve the problem. For each, state:\n"
            f"Hypothesis: <one concise sentence>\n"
            f"Confidence: <0.0-1.0>\n\n"
            f"Be specific: mention function names, files, or data flows if possible."
        )
        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a scientific reasoning engine. Output exactly the "
                "requested hypotheses with confidence scores. No extra commentary."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=600,
            temperature=0.4,
            label=f"{label}_gen_hypotheses" if label else "sci_gen_hypotheses",
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return []
        return MetacognitiveReasoningEngine._parse_hypotheses_from_response(response)

    async def _generate_initial_arch_hypotheses(
        self,
        question: str,
        skeleton_context: str,
        max_hypotheses: int,
        project_id: str,
        label: str = "",
    ) -> List[Tuple[str, float]]:
        """
        Generate initial design option hypotheses for architecture reasoning.
        Extracted from generate_scientific_architecture_reasoning Step 1.
        Slot is restored after the LLM call.
        """
        prompt = (
            f"Code skeleton (contracts — bodies as `...`):\n"
            f"{skeleton_context[:3000]}\n\n"
            f"Architecture question:\n{question[:400]}\n\n"
            f"Propose {max_hypotheses} distinct design options to address this. "
            f"Each option should be concrete: name the classes/methods affected, "
            f"propose new signatures or interfaces as skeleton lines.\n\n"
            f"Format each option as:\n"
            f"Design Option N: <one sentence describing the approach>\n"
            f"Confidence: <0.0-1.0 — how well this fits the existing structure>\n\n"
            f"Consider reuse of existing symbols (higher confidence) vs "
            f"creating new ones (lower until validated)."
        )
        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a software architect generating competing design options. "
                "Each option must be concrete and reference existing symbol names "
                "from the skeleton. Output exactly the requested format."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=600,
            temperature=0.4,
            label=f"{label}_gen_options" if label else "sci_arch_gen",
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return []
        return MetacognitiveReasoningEngine._parse_hypotheses_from_response(response)

    async def _synthesize_scientific_reasoning(
        self,
        question: str,
        context: str,
        best_hyp: str,
        best_score: float,
        best_evidence: "StaticEvidence",
        project_id: str,
        peer_review: Optional["PeerReviewResult"] = None,
        label: str = "",
    ) -> str:
        """
        Synthesize final reasoning from winning hypothesis + evidence.
        Extracted from generate_scientific_reasoning_L3 REGIONS 4-5.

        Receives peer_review to include verdict in the header (H6 dialectical
        synthesis has already happened inside compete_hypotheses — best_hyp
        may already be a scoped hypothesis).
        """
        final_prompt = (
            f"Context:\n{context[:3000]}\n\n"
            f"Question:\n{question}\n\n"
            f"The best validated hypothesis (score {best_score:.3f}):\n"
            f"{best_hyp}\n\n"
            f"Structural evidence supporting it:\n"
            f"- Symbols found: {best_evidence.symbols_found}\n"
            f"- Call relations valid: {best_evidence.call_relations_valid}\n"
            f"- Recent changes: {best_evidence.recent_changes}\n"
            f"- Data flow upstream: {best_evidence.data_flow_upstream}\n\n"
            f"Provide a step-by-step reasoning to answer the question, "
            f"grounded in this evidence."
        )
        reasoning = await self._f._llm_orchestrator.call_llm(
            prompt=final_prompt,
            system_prompt=(
                "You are a helpful assistant that reasons step by step "
                "based on verified evidence."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=self._f.valves.cot_max_tokens,
            temperature=0.3,
            label=f"{label}_synthesize" if label else "sci_synthesize",
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not reasoning:
            return ""

        peer_note = ""
        if peer_review and peer_review.verdict != "APPROVE":
            peer_note = f" | {peer_review.verdict} by {peer_review.reviewer_model}"

        return (
            f"## 🔬 Scientific Reasoning (Level 3)\n"
            f"*Validated against code structure. "
            f"Best hypothesis score: {best_score:.2f}{peer_note}*\n\n"
            f"{reasoning}"
        )

    async def _synthesize_scientific_architecture_reasoning(
        self,
        question: str,
        skeleton_context: str,
        best_hyp: str,
        best_score: float,
        best_evidence: "StaticEvidence",
        project_id: str,
        peer_review: Optional["PeerReviewResult"] = None,
        label: str = "",
    ) -> str:
        """
        Synthesize final architecture proposal from winning design option.
        Extracted from generate_scientific_architecture_reasoning Step 4.
        """
        evidence_summary = (
            (
                f"Symbols confirmed in index: "
                f"{[k for k, v in best_evidence.symbols_found.items() if v]}\n"
                f"Symbols to create: "
                f"{[k for k, v in best_evidence.symbols_found.items() if not v]}\n"
                f"Valid call relationships: "
                f"{[k for k, v in best_evidence.call_relations_valid.items() if v]}\n"
                f"Recent changes affecting this area: "
                f"{best_evidence.recent_changes}\n"
            )
            if best_evidence
            else ""
        )

        synthesis_prompt = (
            f"Skeleton:\n{skeleton_context[:2000]}\n\n"
            f"Architecture question:\n{question[:400]}\n\n"
            f"Best design option (score {best_score:.2f}):\n{best_hyp}\n\n"
            f"Structural evidence:\n{evidence_summary}\n\n"
            "Produce a final architecture proposal:\n"
            "1. Concrete signatures of new/modified classes and methods "
            "(as skeleton lines: `def foo(self, x: int) -> str: ...`).\n"
            "2. Which existing bodies need implementation changes "
            "(write `/expand <SymbolName>` for each — DO NOT write the implementation).\n"
            "3. Migration path: what changes in what order.\n"
            "Be specific. No vague descriptions."
        )
        synthesis = await self._f._llm_orchestrator.call_llm(
            prompt=synthesis_prompt,
            system_prompt=(
                "You are a software architect producing a final design proposal. "
                "Output concrete signatures and migration steps. "
                "Use `/expand <Name>` instead of writing full implementations."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=(
                self._f.valves.skeleton_cot_max_tokens * 2
                if self._f.valves.skeleton_cot_max_tokens > 0
                else 1200
            ),
            temperature=0.25,
            label=f"{label}_synthesize" if label else "sci_arch_synth",
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not synthesis:
            return ""

        peer_note = ""
        if peer_review and peer_review.verdict != "APPROVE":
            peer_note = f" | {peer_review.verdict} by {peer_review.reviewer_model}"

        return (
            f"## 🔬🏗️ Scientific Architecture Reasoning (Level 3)\n"
            f"*{self._f.valves.scientific_hypotheses_count} design options evaluated "
            f"against the SymbolGraph. "
            f"Best option score: {best_score:.2f}{peer_note}*\n\n"
            f"{synthesis}"
        )

    async def generate_scientific_reasoning_L3(
        self, question: str, context: str, project_id: str, label: str = ""
    ) -> str:
        """
        Generate scientific Chain-of-Thought reasoning with structural validation.
        Thin wrapper — delegates to MetacognitiveReasoningEngine.compete_hypotheses().
        """
        max_hypotheses = self._f.valves.scientific_hypotheses_count
        threshold = self._f.valves.scientific_confidence_threshold
        max_iters = self._f.valves.scientific_max_iterations

        hypotheses = await self._generate_initial_hypotheses(
            question, context, max_hypotheses, project_id, label
        )
        if len(hypotheses) < 2:
            self._f._log_debug(
                "Scientific L3: insufficient hypotheses — falling back to L2 CoT"
            )
            return await self.generate_cot_reasoning(question, context, label)

        best_hyp, best_score, best_evidence, peer_review = (
            await self._f._meta_reasoning.compete_hypotheses(
                hypotheses=hypotheses,
                project_id=project_id,
                max_iters=max_iters,
                threshold=threshold,
                label=label,
                obj_weight=0.5,
                llm_weight=0.5,
            )
        )

        if not best_hyp or best_score == 0.0:
            self._f._log_debug(
                "Scientific L3: no valid hypothesis survived — falling back to L2 CoT"
            )
            return await self.generate_cot_reasoning(question, context, label)

        reasoning = await self._synthesize_scientific_reasoning(
            question,
            context,
            best_hyp,
            best_score,
            best_evidence,
            project_id=project_id,
            peer_review=peer_review,
            label=label,
        )

        if not reasoning:
            return "Unable to synthesize scientific reasoning."
        return reasoning

    async def generate_scientific_architecture_reasoning(
        self,
        question: str,
        skeleton_context: str,
        project_id: str,
        label: str = "",
    ) -> str:
        """
        Scientific-method architecture reasoning on skeleton contracts.
        Thin wrapper — delegates to MetacognitiveReasoningEngine.compete_hypotheses().
        obj_weight=0.4 / llm_weight=0.6: proposing changes, LLM judgment weighted higher.
        """
        if not skeleton_context.strip():
            return await self.generate_architecture_reasoning(
                question, skeleton_context, project_id, label=label
            )

        max_hypotheses = self._f.valves.scientific_hypotheses_count
        threshold = self._f.valves.scientific_confidence_threshold
        max_iters = self._f.valves.scientific_max_iterations

        hypotheses = await self._generate_initial_arch_hypotheses(
            question, skeleton_context, max_hypotheses, project_id, label
        )
        if len(hypotheses) < 2:
            self._f._log_debug(
                "Scientific arch: insufficient hypotheses — falling back to L2 arch"
            )
            return await self.generate_architecture_reasoning(
                question, skeleton_context, project_id, label=label
            )

        best_hyp, best_score, best_evidence, peer_review = (
            await self._f._meta_reasoning.compete_hypotheses(
                hypotheses=hypotheses,
                project_id=project_id,
                max_iters=max_iters,
                threshold=threshold,
                label=label,
                obj_weight=0.4,
                llm_weight=0.6,
            )
        )

        if not best_hyp or best_score == 0.0:
            self._f._log_debug(
                "Scientific arch: no valid option survived — falling back to L2 arch"
            )
            return await self.generate_architecture_reasoning(
                question, skeleton_context, project_id, label=label
            )

        synthesis = await self._synthesize_scientific_architecture_reasoning(
            question,
            skeleton_context,
            best_hyp,
            best_score,
            best_evidence,
            project_id=project_id,
            peer_review=peer_review,
            label=label,
        )

        if not synthesis:
            return await self.generate_architecture_reasoning(
                question, skeleton_context, project_id, label=label
            )
        return synthesis


class MultiPhasePlanner:
    """Generates the multi‑phase protocol instructions injected into the
    system prompt when the response budget is tight, and appends wrap‑up
    hints when the token window is critically low.

    Provides:
    * ``build_multi_phase_instructions(available_tokens, query, ...)`` —
      returns a complete multi‑phase protocol block (analysis → architecture
      → contract → code parts → verification) tailored to whether the task
      is code‑generation or a general long‑form answer.
    * ``append_critical_wrap_up_hint(messages)`` — appends a short (~25
      token) reminder to the last user message telling the model to stop
      cleanly and write a continuation marker, without consuming system
      prompt budget.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Build multi‑phase protocol instructions
    # ═══════════════════════════════════════════════════════════════════════════

    def build_multi_phase_instructions(
        self,
        available_tokens: int,
        user_query: str,
        cot_degraded_to_l1: bool = False,
        is_continuation: bool = False,
    ) -> str:
        """
        Build the multi-phase response instructions injected into the final
        user message before the model call.

        Guards against a zero or negative available_tokens budget. When the
        context is nearly full, WindowManager may leave fewer tokens than the
        minimum viable phase size; in that case the function falls back to a
        single-phase instruction rather than producing directives like
        "write Part 1 in 0 tokens" which confuse the model.

        When cot_degraded_to_l1=True the reasoning preamble phase is omitted
        from the phase plan. Without this check the planner still schedules
        a reasoning phase even though ReasoningEngine already downgraded CoT
        to L1 (direct answer), wasting tokens on unwanted meta-commentary.

        Steps:
            1.  Guard: return single-phase fallback when budget is too small.
            2.  Compute phase count and per-phase budget.
            3.  Build phase descriptors; skip reasoning phase when cot_degraded.
            4.  Format and return instruction string.
        """
        v = self._f.valves

        min_phase_tokens = getattr(v, "multi_phase_min_tokens_per_phase", 200)
        default_phases = getattr(v, "multi_phase_default_phases", 3)
        tokens_per_phase = getattr(v, "multi_phase_tokens_per_phase", 0)

        # -- Step 1: budget guard --
        effective_budget = max(0, available_tokens)

        if effective_budget < min_phase_tokens * 2:
            # Not enough room for at least two meaningful phases.
            fallback_tokens = effective_budget or getattr(
                v, "multi_phase_effective_max_tokens", 2048
            )
            return (
                f"Respond completely in one part. "
                f"Use at most ~{fallback_tokens} tokens. "
                f"Be concise and prioritise the most important information."
            )

        # -- Step 2: compute phase count and per-phase budget --
        if tokens_per_phase and tokens_per_phase > 0:
            n_phases = max(1, effective_budget // tokens_per_phase)
            per_phase = tokens_per_phase
        else:
            n_phases = default_phases
            per_phase = effective_budget // n_phases

        # Clamp to minimum useful size per phase
        if per_phase < min_phase_tokens:
            n_phases = max(1, effective_budget // min_phase_tokens)
            per_phase = effective_budget // n_phases

        n_phases = min(n_phases, getattr(v, "multi_phase_max_phases", 5))

        # -- Step 3: build phase descriptors --
        phases: List[str] = []
        phase_num = 1

        # Reasoning preamble — omitted when CoT was degraded to L1
        if (
            not cot_degraded_to_l1
            and not is_continuation
            and getattr(v, "multi_phase_include_reasoning_phase", True)
            and n_phases >= 3
        ):
            reasoning_budget = max(min_phase_tokens, per_phase // 2)
            phases.append(
                f"**Part {phase_num}** (~{reasoning_budget} tokens): "
                f"Think through the problem. Outline your approach. "
                f"Do NOT write final code yet."
            )
            phase_num += 1

        # Middle parts — implementation / explanation
        while phase_num < n_phases:
            phases.append(
                f"**Part {phase_num}** (~{per_phase} tokens): "
                f"Continue the implementation or explanation. "
                f"Signal readiness to continue with "
                f"'[CONTINUE to Part {phase_num + 1}]' at the end."
            )
            phase_num += 1

        # Final part
        phases.append(
            f"**Part {phase_num}** (~{per_phase} tokens): "
            f"Complete your response. Summarise key points. "
            f"Do NOT add a continuation signal."
        )

        # -- Step 4: format --
        header = (
            f"Your response must be split into {len(phases)} parts "
            f"(~{per_phase} tokens each, {effective_budget} total available):\n\n"
        )
        return header + "\n\n".join(phases)

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Wrap‑up hint (appended to user message when token window is critical)
    # ═══════════════════════════════════════════════════════════════════════════

    def append_critical_wrap_up_hint(self, messages: list) -> list:
        """
        Inject a wrap-up reminder into the last user message of the list.

        The hint is appended to the CONTENT of the last user message rather
        than added as a separate message. Adding a standalone user message
        produces two consecutive user-role entries, which several LLM providers
        reject with a 400 error, and which confuses models into treating the
        second entry as a correction or clarification of the first.

        Returns a new list with a shallow-copied last message so the caller's
        original messages list and message dict are not modified in place.

        Steps:
            1.  Guard: return the original list unchanged if empty or no user
                message is found.
            2.  Make a shallow copy of the list.
            3.  Copy the last user message dict and append the hint to its content.
            4.  Replace the last entry in the copied list and return.
        """
        # -- Step 1: guard --
        if not messages:
            return messages

        # Find the last user message index
        last_user_idx = None
        for i in range(len(messages) - 1, -1, -1):
            if messages[i].get("role") == "user":
                last_user_idx = i
                break

        if last_user_idx is None:
            return messages

        hint_text = getattr(
            self._f.valves,
            "multi_phase_wrap_up_hint",
            "\n\n[This is the final part. Complete your response now. "
            "Do NOT add a continuation signal.]",
        )

        # -- Step 2: shallow copy of list --
        new_messages = list(messages)

        # -- Step 3: copy the message dict and append hint --
        original_msg = messages[last_user_idx]
        original_content = original_msg.get("content") or ""
        new_msg = {**original_msg, "content": original_content + hint_text}

        # -- Step 4: replace in copied list --
        new_messages[last_user_idx] = new_msg
        return new_messages


class CommandRouter:
    """
    Dispatches explicit slash‑commands, interprets natural‑language
    intents, and injects proactive suggestions into the conversation.

    Provides:
    * ``handle_explicit_commands(messages, ...)`` — processes ``/forget``,
      ``/status``, ``/clean``, and ``/expand`` commands, returning a
      fully‑formed assistant response when one is triggered.
    * ``handle_natural_intents(messages, ...)`` — detects forget / remember /
      obsolete requests expressed in natural language using the CrossEncoder
      and executes them without an explicit command prefix.
    * ``outlet_intercept_expand(assistant_content, project_id)`` — scans the
      assistant's response for ``/expand`` commands and replaces them inline
      with the actual symbol bodies from the SymbolIndex, so the user sees
      the code immediately.
    * ``classify_intent(query)`` — returns a probability distribution over
      explain / modify / debug / refactor using the CrossEncoder.
    * ``suggest_commands(project_id, state)`` — returns context‑management
      tips (``/forget``, ``/status``, ``/clean``) after the conversation
      reaches a threshold, with a cooldown between suggestions.
    * ``is_code_only_message(content)`` — detects messages that contain only
      code without a question, used by the inlet to trigger silent ingestion.
    """

    # ── Class constants ────────────────────────────────────────────────────

    _EXPAND_DOTTED = re.compile(r"^([A-Za-z_]\w*)\.([A-Za-z_]\w*)$")

    # ── Silent-ingestion code-only detection ───────────────────────────────
    # Lines that start a new statement/construct (multi-language, best-effort).
    _STRUCTURAL_LINE_START = re.compile(
        r"^\s*(?:"
        r"def |async def |class |import |from |@\w|"
        r"if |elif |else\b|for |while |try:|except|finally:|with |"
        r"return |yield |raise |pass\b|break\b|continue\b|#|"
        r"global |nonlocal |assert |del |lambda |"
        r"function |const |let |var |export |interface |type |enum |"
        r"func |struct |impl |use |pub |fn |trait |"
        r"package |public |private |protected |static |void |"
        r"#include |namespace |template "
        r")"
    )
    # Lines that continue a multi-line statement (dict/list entries, wrapped
    # calls, closing brackets, typed attributes...) rather than starting a
    # new construct. Without this, normally-formatted code (Field(...) calls,
    # multi-line regex, dataclass-style fields) gets misread as "prose".
    _CONTINUATION_OR_LITERAL = re.compile(
        r"^\s*(?:"
        r"[\)\]\}]|"
        r"[\"'`]|"
        r"[,\.]|"
        r"\*\*?\w|"
        r"-?\d|"
        r"[\w.\[\]]+\s*[:=\(\[{]"
        r")"
    )
    # Noise-stripping patterns: blanked out (newlines preserved) before
    # checking for a real '?' question, so docstrings and regex literals
    # (`(?:...)`, `\?`) never get mistaken for an explicit user question.
    _TRIPLE_QUOTE_RE = re.compile(r'("""|\'\'\')([\s\S]*?)\1')
    _BLOCK_COMMENT_RE = re.compile(r"/\*[\s\S]*?\*/")
    _STRING_RE = re.compile(r'"(?:[^"\\\n]|\\.)*"|\'(?:[^\'\\\n]|\\.)*\'')
    _LINE_COMMENT_RE = re.compile(r"(#|//).*")

    # ── Intent keywords ──────────────────────────────────────────────────
    INTENT_KEYWORDS = {
        "forget",
        "olvida",
        "olvid",
        "remember",
        "recuerda",
        "pin",
        "fija",
        "guarda",
        "obsolete",
        "obsoleto",
        "deprecated",
        "ya no",
        "remove",
        "elimina",
        "borra",
        "quita",
        "keep",
        "mantén",
        "conserva",
    }

    _FENCED_CODE_BLOCK_RE = re.compile(r"```[^\n]*\n.*?```", re.DOTALL)
    _INDENTED_CODE_RE = re.compile(r"(?m)^(?:    |\t).+$")
    _EXCESS_NEWLINES_RE = re.compile(r"\n{3,}")

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Initialization
    # ═══════════════════════════════════════════════════════════════════════

    def __init__(self, filter_ref: "Filter") -> None:
        """Store a reference to the parent Filter for shared state."""
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════
    # 2. CrossEncoder & ML helpers
    # ═══════════════════════════════════════════════════════════════════════

    async def _predict_cross_encoder(self, pairs: list) -> Optional[list]:
        """
        Run the CrossEncoder on (text_a, text_b) pairs.
        Returns raw scores (logits) or None if the model is not loaded.

        Each pair is truncated to the model's maximum length (512) using the
        CrossEncoder's own tokenizer BEFORE prediction. This is done centrally
        so that no call site has to guess character limits.
        """
        if self._f._cross_encoder is None:
            if not self._f._cross_encoder_unavailable_logged:
                self._f._log_debug(
                    "CrossEncoder not loaded – predictions will return None."
                )
                self._f._cross_encoder_unavailable_logged = True
            return None

        ce = self._f._cross_encoder

        def _predict_safely():
            return ce.predict(self._truncate_pairs_for_cross_encoder(ce, pairs))

        async with self._f._cross_encoder_lock:
            return await anyio.to_thread.run_sync(_predict_safely)

    @staticmethod
    def _truncate_pairs_for_cross_encoder(
        ce, pairs: list, max_tokens: int = 512
    ) -> list:
        """
        Truncate each pair (a, b) so that the combined length fits within the
        CrossEncoder's token limit. Keeps the short side intact and truncates
        the long side (only splits evenly when BOTH sides are long).
        """
        budget = max(8, max_tokens - 4)  # margin for [CLS] a [SEP] b [SEP]
        tok = getattr(ce, "tokenizer", None)

        if tok is None:
            cap = (budget // 2) * 4
            return [(str(a)[:cap], str(b)[:cap]) for a, b in pairs]

        enc = lambda t: tok.encode(str(t), add_special_tokens=False)
        dec = lambda ids: tok.decode(ids, skip_special_tokens=True)

        out = []
        for a, b in pairs:
            ai, bi = enc(a), enc(b)
            la, lb = len(ai), len(bi)
            if la + lb <= budget:
                out.append((a, b))
            elif la <= budget // 2:
                out.append((a, dec(bi[: budget - la])))
            elif lb <= budget // 2:
                out.append((dec(ai[: budget - lb]), b))
            else:
                half = budget // 2
                out.append((dec(ai[:half]), dec(bi[:half])))
        return out

    @staticmethod
    def _normalize_cross_encoder_score(raw_score: float) -> float:
        """
        Convert a raw CrossEncoder logit to a probability in [0,1] via sigmoid.
        """
        return 1.0 / (1.0 + math.exp(-raw_score))

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Contradiction detection (cascade: Heuristic → CE → LLM)
    # ═══════════════════════════════════════════════════════════════════════

    async def _detect_contradictions(
        self, messages: list, project_id: str
    ) -> Optional[str]:
        """
        Check if the last user message contradicts recent conversation history.
        Returns a warning string if a contradiction is detected, else None.

        Args:
            messages: The list of conversation messages.
            project_id: The current project identifier (used for slot restoration if needed).
        """
        if not self._f.valves.enable_contradiction_detection or len(messages) < 3:
            return None

        last_user = next(
            (m for m in reversed(messages) if m.get("role") == "user"), None
        )
        if not last_user:
            return None

        history = messages[:-1]
        if not history:
            return None

        history_text = "\n".join(
            [f"{m['role']}: {m['content']}" for m in history if m.get("content")]
        )
        if not history_text.strip():
            return None

        hist = history_text[-8000:]
        new_msg = last_user["content"]

        # Heuristic reinforcement
        content_lower = new_msg.lower()
        contradiction_keywords = (
            "but",
            "actually",
            "instead",
            "wait",
            "no",
            "not",
            "error",
            "wrong",
            "correction",
        )
        h_weight = self._f.valves.heuristic_reinforcement_weight
        heuristic_boost = (
            0.2 if any(kw in content_lower for kw in contradiction_keywords) else 0.0
        )

        pairs = [
            (
                f"History: {hist}\n\nNew message: {new_msg}",
                "The new message directly contradicts a specific previous statement or decision in the conversation.",
            ),
            (
                f"History: {hist}\n\nNew message: {new_msg}",
                "The new message is consistent with and builds upon the previous conversation history.",
            ),
        ]
        scores = await self._predict_cross_encoder(pairs)

        if scores is None or len(scores) < 2:
            return None

        scores_reinforced = list(scores)
        scores_reinforced[0] += h_weight * heuristic_boost

        diff = scores_reinforced[0] - scores_reinforced[1]
        CE_CONFIDENCE_THRESHOLD = self._f.valves.contradiction_ce_threshold
        LLM_FALLBACK_THRESHOLD = self._f.valves.contradiction_llm_threshold

        if diff >= CE_CONFIDENCE_THRESHOLD:
            if scores_reinforced[0] > scores_reinforced[1]:
                return (
                    "⚠️ **Contradiction detected**: The last message appears to contradict something established earlier. "
                    "Please review and clarify if needed."
                )
            return None

        elif diff < LLM_FALLBACK_THRESHOLD:
            # LLM fallback
            return await self._detect_contradictions_with_llm(
                hist, new_msg, scores_reinforced, project_id
            )

        return None

    async def _detect_contradictions_with_llm(
        self,
        history: str,
        new_msg: str,
        ce_scores: List[float],
        project_id: str,
    ) -> Optional[str]:
        """
        LLM fallback for contradiction detection when the CrossEncoder diff
        falls below contradiction_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer with no reasoning preamble.

        Args:
            history: Excerpt of the conversation history (truncated to 1500 chars).
            new_msg: The new user message to check (truncated to 500 chars).
            ce_scores: [contradiction_score, consistent_score] from the CrossEncoder.
            project_id: Current project identifier, used for slot restoration.

        Returns:
            Optional[str]: A warning string if a contradiction is detected,
                           or None if the message is consistent.
        """
        prompt = (
            f"CrossEncoder scores — contradiction: {ce_scores[0]:.2f}, "
            f"consistent: {ce_scores[1]:.2f}\n\n"
            f"Conversation history (excerpt):\n{history[:1500]}\n\n"
            f"New message:\n{new_msg[:500]}\n\n"
            f"Does the new message contradict something established in the history?\n"
            f'Output {{"contradiction": true}} if yes, {{"contradiction": false}} if no.'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a contradiction detector. "
                "Output ONLY a valid JSON object with a single boolean field 'contradiction'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="contradiction_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        # Restore the KV slot after any auxiliary LLM call.
        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return None

        try:
            data = json.loads(response)
            if data.get("contradiction", False):
                return (
                    "⚠️ **Contradiction detected**: The last message appears to "
                    "contradict something established earlier. "
                    "Please review and clarify if needed."
                )
            return None
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_detect_contradictions_with_llm: JSON parse error — "
                f"response: {response[:200]!r}"
            )
            return None

    # ═══════════════════════════════════════════════════════════════════════
    # 4. Text extraction & intent classification (cascade: Heuristic → CE → LLM)
    # ═══════════════════════════════════════════════════════════════════════

    def _extract_text_for_classification(self, message: str) -> str:
        """
        Extract only non-code portions of the user message for intent classification.

        CrossEncoders are typically limited to 512 tokens. Passing full messages
        that contain pasted code causes silent truncation that often removes the
        actual question (usually at the end of the message).

        Code blocks are replaced with a '[CODE]' placeholder so the classifier
        can still infer 'there was code here' without ingesting the tokens.
        """
        if not message:
            return ""

        text = self._FENCED_CODE_BLOCK_RE.sub("[CODE]", message)
        text = self._INDENTED_CODE_RE.sub("", text)
        text = self._EXCESS_NEWLINES_RE.sub("\n\n", text).strip()

        if not text or text == "[CODE]":
            return "[CODE ONLY — no natural language text]"

        return text

    async def classify_intent(
        self,
        user_query: str,
        project_id: str,
    ) -> dict:
        """
        Classify the user query into a weighted intent vector.

        Returns a dict with float weights in [0.0, 1.0] for each of the
        canonical intent keys. Weights do not need to sum to 1.

        Canonical keys (all guaranteed present in the returned dict):
            debug, modify, refactor, explain, generate, review, architecture

        Classification cascade:
            1.  Strip noise from the raw query.
            2.  Build cross-encoder pairs (query vs. intent label exemplars).
            3.  Run cross-encoder. If the model is unavailable, ce_scores is None;
                the LLM path receives an empty list rather than None so it can
                still function without indexing errors.
            4.  Apply heuristic boosting via _reinforce_cot_level_detection.
            5.  If heuristic confidence is sufficient, return heuristic result.
            6.  Otherwise call _classify_intent_with_llm.
            7.  Normalize the returned dict to guarantee all canonical keys exist
                with float values, preventing KeyError in callers that do not
                use .get() with a default.
        """
        _CANONICAL_KEYS = {
            "debug": 0.0,
            "modify": 0.0,
            "refactor": 0.0,
            "explain": 0.0,
            "generate": 0.0,
            "review": 0.0,
            "architecture": 0.0,
        }

        # -- Step 1: strip noise --
        stripped = self._strip_code_noise(user_query)
        query_for_ce = stripped if stripped.strip() else user_query

        # -- Step 2: build cross-encoder pairs --
        intent_exemplars = {
            "debug": "fix bug error traceback exception crash failing test",
            "modify": "change update edit add remove implement feature",
            "refactor": "refactor restructure clean up improve reorganize",
            "explain": "explain how does what is describe walk me through",
            "generate": "write create generate new code function class",
            "review": "review check code quality is this correct best practice",
            "architecture": "design architecture system structure high level overview",
        }
        pairs = [(query_for_ce, exemplar) for exemplar in intent_exemplars.values()]
        intent_keys_ordered = list(intent_exemplars.keys())

        # -- Step 3: run cross-encoder --
        raw_ce_scores = await self._predict_cross_encoder(pairs)

        # Normalise to list before any downstream use. None means the
        # cross-encoder model is not loaded; an empty list is safe to pass
        # to _classify_intent_with_llm and avoids TypeError on indexing.
        ce_scores: List[float] = (
            [self._normalize_cross_encoder_score(s) for s in raw_ce_scores]
            if raw_ce_scores is not None
            else []
        )

        # -- Step 4: build heuristic intent dict from ce_scores --
        heuristic: Dict[str, float] = dict(_CANONICAL_KEYS)
        if ce_scores and len(ce_scores) == len(intent_keys_ordered):
            for key, score in zip(intent_keys_ordered, ce_scores):
                heuristic[key] = float(score)

        # -- Step 5: heuristic confidence gate --
        max_score = max(heuristic.values()) if heuristic else 0.0
        confidence_threshold = getattr(
            self._f.valves, "intent_heuristic_confidence_threshold", 0.75
        )
        if max_score >= confidence_threshold and ce_scores:
            self._f._log_debug(
                f"classify_intent: heuristic sufficient "
                f"(max={max_score:.2f} >= {confidence_threshold})"
            )
            return heuristic

        # -- Step 6: LLM classification --
        try:
            llm_result = await self._classify_intent_with_llm(
                user_query=user_query,
                ce_scores=ce_scores,  # guaranteed list, never None
                stripped_query=stripped,
                project_id=project_id,
            )
        except Exception as e:
            self._f._log_debug(
                f"classify_intent: LLM failed, falling back to heuristic: "
                f"{type(e).__name__}: {e}"
            )
            return heuristic

        if not llm_result or not isinstance(llm_result, dict):
            return heuristic

        # -- Step 7: normalize result --
        # Guarantee all canonical keys exist with float values so callers
        # that do intent_vector["debug"] rather than .get("debug", 0.0)
        # do not raise KeyError.
        normalized: Dict[str, float] = dict(_CANONICAL_KEYS)
        for key in _CANONICAL_KEYS:
            raw = llm_result.get(key)
            if raw is not None:
                try:
                    normalized[key] = max(0.0, min(1.0, float(raw)))
                except (TypeError, ValueError):
                    pass  # keep default 0.0

        self._f._log_debug(
            f"classify_intent: {normalized} "
            f"(ce_scores={'yes' if ce_scores else 'none'})"
        )
        return normalized

    async def _classify_intent_with_llm(
        self,
        user_query: str,
        ce_scores: Optional[List[float]] = None,
        stripped_query: str = "",
        project_id: str = "",
    ) -> dict:
        """
        LLM fallback for intent classification when the CrossEncoder diff falls
        below intent_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer. Default on failure is a conservative
        distribution across all intents.

        Args:
            user_query: The user's message (truncated to 500 chars).
            ce_scores: Optional [explain, modify, debug, refactor] CE scores.
            stripped_query: Pre-cleaned version of the query (unused here,
                            kept for API compatibility).
            project_id: Current project identifier, used for slot restoration.

        Returns:
            dict: Intent vector with keys explain/modify/debug/refactor,
                  where the winning intent is 1.0 and the rest are 0.0.
                  Falls back to a conservative distribution on failure.
        """
        _INTENT_NAMES = ["Explain", "Modify", "Debug", "Refactor"]

        if ce_scores is not None:
            best = _INTENT_NAMES[int(np.argmax(ce_scores))]
            ce_block = (
                f"CrossEncoder scores — "
                f"Explain: {ce_scores[0]:.2f}, "
                f"Modify: {ce_scores[1]:.2f}, "
                f"Debug: {ce_scores[2]:.2f}, "
                f"Refactor: {ce_scores[3]:.2f}. "
                f"Best: {best}.\n\n"
            )
        else:
            ce_block = ""

        prompt = (
            f"{ce_block}"
            f"User question:\n{user_query[:500]}\n\n"
            f"Classify the intent. When ambiguous, prefer the more specific intent "
            f"(Debug > Refactor > Modify > Explain).\n\n"
            f"Intent definitions:\n"
            f"  Explain   — understand or explain code; clues: 'how', 'why'\n"
            f"  Modify    — change or create code; clues: 'write', 'fix', 'add'\n"
            f"  Debug     — fix errors or unexpected behaviour; clues: 'bug', 'error', 'traceback'\n"
            f"  Refactor  — restructure without changing behaviour; clues: 'refactor', 'clean'\n\n"
            f'Output only the JSON object, e.g. {{"intent": "Debug"}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are an intent classifier. "
                "Output ONLY a valid JSON object with a single string field 'intent' "
                "whose value is one of: Explain, Modify, Debug, Refactor. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="intent_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        # Restore the KV slot after any auxiliary LLM call.
        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        _CONSERVATIVE_FALLBACK = {
            "explain": 0.2,
            "modify": 0.3,
            "debug": 0.3,
            "refactor": 0.2,
        }

        if not response:
            self._f._log_debug(
                "_classify_intent_with_llm: empty response, using conservative fallback"
            )
            return _CONSERVATIVE_FALLBACK

        try:
            data = json.loads(response)
            raw = str(data.get("intent", "")).strip().lower()
            _valid = {"explain", "modify", "debug", "refactor"}
            if raw in _valid:
                result = {"explain": 0.0, "modify": 0.0, "debug": 0.0, "refactor": 0.0}
                result[raw] = 1.0
                self._f._log_debug(f"_classify_intent_with_llm: intent={raw!r}")
                return result
            self._f._log_debug(
                f"_classify_intent_with_llm: unknown intent {raw!r}, "
                f"using conservative fallback"
            )
            return _CONSERVATIVE_FALLBACK
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_classify_intent_with_llm: JSON parse error — "
                f"response: {response[:200]!r}, using conservative fallback"
            )
            return _CONSERVATIVE_FALLBACK

    # ═══════════════════════════════════════════════════════════════════════
    # 5. Natural language intents (forget, remember, obsolete)
    # ═══════════════════════════════════════════════════════════════════════

    async def handle_natural_intents(
        self,
        messages: list,
        project_id: str,
        is_explicit_command: bool,
        last_user_msg: Optional[dict],
        slot_free: bool = True,
    ) -> Tuple[bool, Optional[list]]:
        """Handle natural language intents (forget, remember, obsolete).
        Returns (handled, messages) if an intent was processed, else (False, None).
        """
        if (
            not self._f.valves.enable_natural_language_forget
            or not last_user_msg
            or is_explicit_command
            or self.has_code_indicators(last_user_msg.get("content", ""))
        ):
            return False, None

        if not slot_free:
            self._f._log_debug(
                "⚡ COMMAND HANDLING – Natural intents skipped (no free slot)"
            )
            return False, None

        intents = await self._parse_all_intents(
            last_user_msg.get("content", ""), project_id
        )
        for intent_type in ("forget", "remember", "obsolete"):
            fi = intents.get(intent_type, {})
            if fi.get("action") in (None, "none"):
                continue
            if intent_type == "forget":
                confirmation = await self._execute_forget_intent(project_id, fi)
            elif intent_type == "remember":
                confirmation = await self._execute_remember_intent(project_id, fi)
            elif intent_type == "obsolete" and self._f.valves.enable_obsolete_marking:
                confirmation = await self._execute_obsolete_intent(project_id, fi)
            else:
                continue

            status_msg = f"[CodeAware] {confirmation}"
            messages.insert(0, {"role": "system", "content": status_msg})
            messages.pop()
            messages.append({"role": "assistant", "content": confirmation})
            return True, self._f._inlet_orch.ensure_last_message_is_user(messages)

        return False, None

    async def _parse_all_intents(
        self, user_message: str, project_id: str
    ) -> Dict[str, Any]:
        """
        Detect natural-language intents (forget, remember, obsolete) using a cascade.

        Cascade:
        1. Heuristic reinforcement: code indicators boost relevance of code-related actions.
        2. CrossEncoder (fast) scores candidate actions.
        3. If confident (diff >= CE_THRESHOLD), use the highest-scoring action.
        4. If extremely uncertain (diff < LLM_THRESHOLD), call LLM with CE context.
        5. Middle zone: default to "none" (conservative, no action).

        Restores KV slot after any LLM call.
        """
        if not self._f.valves.enable_natural_language_forget:
            none = {"action": "none"}
            return {"forget": none, "remember": none, "obsolete": none}

        try:
            code_spans = await self._f._code_blocks.get_code_spans(user_message)
        except Exception:
            code_spans = []
        prose = (
            CodeBlockManager.remove_code_spans(user_message, code_spans).strip()
            if code_spans
            else user_message
        )
        if not prose or len(prose) < 3:
            none = {"action": "none"}
            return {"forget": none, "remember": none, "obsolete": none}

        context_parts = []
        if code_spans or "```" in user_message:
            context_parts.append("[CODE]")
        context_prefix = " ".join(context_parts)
        query = f"{context_prefix} {prose}" if context_parts else prose

        candidates: List[Tuple[str, str, dict]] = [
            (
                "forget",
                "The user wants to forget or discard the last code block mentioned.",
                {"action": "forget_last"},
            ),
            (
                "forget",
                "The user wants to forget or discard all context and start fresh.",
                {"action": "forget_all"},
            ),
            (
                "forget",
                "The user wants to forget or discard this specific code block or file.",
                {"action": "forget_last"},
            ),
            (
                "remember",
                "The user wants to pin or remember the last code block so it is kept.",
                {"action": "pin_last"},
            ),
            (
                "remember",
                "The user wants to pin or remember this specific code block.",
                {"action": "pin_last"},
            ),
            (
                "remember",
                "The user wants to unpin or forget the last code block.",
                {"action": "unpin_last"},
            ),
            (
                "remember",
                "The user wants to unpin or forget all pinned code blocks.",
                {"action": "unpin_all"},
            ),
            (
                "obsolete",
                "The user wants to mark the last code block as obsolete or deprecated.",
                {"action": "obsolete_last"},
            ),
            (
                "obsolete",
                "The user wants to mark all code blocks as obsolete.",
                {"action": "obsolete_all"},
            ),
            (
                "obsolete",
                "The user wants to revive or unmark the last code block as obsolete.",
                {"action": "revive_last"},
            ),
            (
                "obsolete",
                "The user wants to revive or unmark all code blocks as obsolete.",
                {"action": "revive_all"},
            ),
            ("none", "The user is not requesting any action.", {"action": "none"}),
        ]

        pairs = [(query, desc) for _, desc, _ in candidates]
        scores = await self._predict_cross_encoder(pairs)

        none = {"action": "none"}
        if scores is None:
            return await self._parse_all_intents_heuristic(prose)

        scores_reinforced = list(scores)
        h_weight = self._f.valves.heuristic_reinforcement_weight
        content_lower = prose.lower()

        if any(
            kw in content_lower
            for kw in ("code", "block", "file", "hash", "func", "class")
        ):
            for i, (category, _, action) in enumerate(candidates):
                if action["action"] in (
                    "forget_last",
                    "pin_last",
                    "obsolete_last",
                    "revive_last",
                ):
                    scores_reinforced[i] += h_weight * 0.1

        max_score = max(scores_reinforced)
        second_max = (
            sorted(scores_reinforced, reverse=True)[1]
            if len(scores_reinforced) > 1
            else 0
        )
        diff = max_score - second_max

        CE_CONFIDENCE_THRESHOLD = self._f.valves.nl_intent_ce_threshold
        LLM_FALLBACK_THRESHOLD = self._f.valves.nl_intent_llm_threshold

        if diff >= CE_CONFIDENCE_THRESHOLD:
            best: Dict[str, Tuple[float, dict]] = {}
            for (category, _, action), score in zip(candidates, scores_reinforced):
                if score > best.get(category, (-1.0, none))[0]:
                    best[category] = (score, action)

            result: Dict[str, dict] = {
                "forget": none,
                "remember": none,
                "obsolete": none,
            }
            CONFIDENCE_THRESHOLD = 0.5
            for category, (score, action) in best.items():
                if score >= CONFIDENCE_THRESHOLD and action["action"] != "none":
                    result[category] = action
            return result

        elif diff < LLM_FALLBACK_THRESHOLD:
            self._f._log_debug(
                f"_parse_all_intents: CrossEncoder uncertain (diff={diff:.2f} < {LLM_FALLBACK_THRESHOLD:.2f}), "
                "using LLM with CrossEncoder context"
            )
            return await self._parse_all_intents_with_llm(
                query, candidates, scores_reinforced, project_id
            )

        return await self._parse_all_intents_heuristic(prose)

    async def _parse_all_intents_with_llm(
        self,
        query: str,
        candidates: List[Tuple[str, str, dict]],
        ce_scores: List[float],
        project_id: str,
    ) -> Dict[str, Any]:
        """
        LLM fallback for natural language intent detection when the CrossEncoder
        diff falls below nl_intent_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer. Falls back to the heuristic parser on
        any parse failure.

        Args:
            query: The user's message (truncated to 500 chars).
            candidates: List of (category, description, meta) tuples.
            ce_scores: CE score for each candidate (parallel list).
            project_id: Current project identifier, used for slot restoration.

        Returns:
            Dict[str, Any]: Intent dict with keys forget/remember/obsolete,
                            each containing {"action": <action_name>}.
        """
        # Build the CE summary showing the top-3 candidates by score.
        scored = sorted(zip(candidates, ce_scores), key=lambda x: x[1], reverse=True)
        ce_block = "\n".join(
            f"  {cat} (score: {score:.2f}) — {desc}"
            for (cat, desc, _), score in scored[:3]
        )

        _VALID_ACTIONS = {
            "forget_last",
            "forget_all",
            "pin_last",
            "unpin_last",
            "unpin_all",
            "obsolete_last",
            "obsolete_all",
            "revive_last",
            "revive_all",
            "none",
        }

        prompt = (
            f"CrossEncoder top candidates:\n{ce_block}\n\n"
            f"User message:\n{query[:500]}\n\n"
            f"Determine if the user wants to perform one of these memory actions:\n"
            f"  forget_last / forget_all      — remove code block(s) from context\n"
            f"  pin_last / unpin_last / unpin_all — keep or release a code block\n"
            f"  obsolete_last / obsolete_all  — mark code block(s) as obsolete\n"
            f"  revive_last / revive_all      — un-mark obsolete code block(s)\n"
            f"  none                          — no memory action intended\n\n"
            f'Output only the JSON object, e.g. {{"action": "forget_last"}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a memory action classifier. "
                "Output ONLY a valid JSON object with a single string field 'action' "
                "whose value is one of: forget_last, forget_all, pin_last, unpin_last, "
                "unpin_all, obsolete_last, obsolete_all, revive_last, revive_all, none. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="nl_intent_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        # Restore the KV slot after any auxiliary LLM call.
        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        _NONE = {"action": "none"}
        _FALLBACK = {"forget": _NONE, "remember": _NONE, "obsolete": _NONE}

        if not response:
            self._f._log_debug(
                "_parse_all_intents_with_llm: empty response, falling back to heuristic"
            )
            return await self._parse_all_intents_heuristic(query)

        try:
            data = json.loads(response)
            action = str(data.get("action", "none")).strip().lower()

            if action not in _VALID_ACTIONS:
                self._f._log_debug(
                    f"_parse_all_intents_with_llm: unknown action {action!r}, "
                    f"falling back to heuristic"
                )
                return await self._parse_all_intents_heuristic(query)

            result = {"forget": _NONE, "remember": _NONE, "obsolete": _NONE}
            if action.startswith("forget"):
                result["forget"] = {"action": action}
            elif action.startswith("pin") or action.startswith("unpin"):
                result["remember"] = {"action": action}
            elif action.startswith("obsolete") or action.startswith("revive"):
                result["obsolete"] = {"action": action}

            self._f._log_debug(f"_parse_all_intents_with_llm: action={action!r}")
            return result

        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_parse_all_intents_with_llm: JSON parse error — "
                f"response: {response[:200]!r}, falling back to heuristic"
            )
            return await self._parse_all_intents_heuristic(query)

    async def _parse_all_intents_heuristic(self, prose: str) -> Dict[str, Any]:
        """Heuristic fallback for natural language intent detection."""
        none = {"action": "none"}
        result = {"forget": none, "remember": none, "obsolete": none}
        content_lower = prose.lower()

        if any(
            kw in content_lower
            for kw in ("forget", "olvida", "olvid", "remove", "borra", "quita")
        ):
            if "all" in content_lower or "todo" in content_lower:
                result["forget"] = {"action": "forget_all"}
            else:
                result["forget"] = {"action": "forget_last"}
        elif any(
            kw in content_lower
            for kw in ("pin", "fija", "remember", "recuerda", "keep", "mantén")
        ):
            if "all" in content_lower or "todo" in content_lower:
                result["remember"] = {"action": "pin_all"}
            else:
                result["remember"] = {"action": "pin_last"}
        elif any(
            kw in content_lower
            for kw in (
                "obsolete",
                "obsoleto",
                "deprecated",
                "ya no",
                "revive",
                "revivir",
            )
        ):
            if "all" in content_lower or "todo" in content_lower:
                result["obsolete"] = {"action": "obsolete_all"}
            else:
                result["obsolete"] = {"action": "obsolete_last"}

        return result

    # ═══════════════════════════════════════════════════════════════════════
    # 6. Executors for natural language intents
    # ═══════════════════════════════════════════════════════════════════════

    async def _execute_forget_intent(self, project_id: str, intent: Dict) -> str:
        """Execute a natural-language forget intent. Returns a user message."""
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            state = self._f._conversation_state_manager.get(project_id)
            if not state:
                return "No active context to forget."

            action = intent.get("action")
            if action == "forget_all":
                return (
                    "⚠️ For safety, the natural language 'forget all' is disabled. "
                    "Please type `/forget all` explicitly to confirm."
                )

            if action == "forget_last":
                if state.active_blocks:
                    last_hash = max(
                        state.active_blocks.keys(),
                        key=lambda h: state.active_blocks[h].timestamp,
                    )
                    block = state.active_blocks.get(last_hash)
                    if block:
                        self._f._symbol_index.remove_all_for_block(
                            block.hash, block.symbols, project_id
                        )
                    del state.active_blocks[last_hash]
                    self._f._activation.invalidate_lightweight_cache(project_id)
                return "Forgotten the last context block."

            elif action == "forget_n":
                n = intent.get("n", 1)
                blocks_by_time = sorted(
                    state.active_blocks.items(),
                    key=lambda x: x[1].timestamp,
                    reverse=True,
                )
                removed = 0
                for h, block in blocks_by_time[:n]:
                    if h in state.active_blocks:
                        self._f._symbol_index.remove_all_for_block(
                            block.hash, block.symbols, project_id
                        )
                        del state.active_blocks[h]
                        removed += 1
                if removed:
                    self._f._activation.invalidate_lightweight_cache(project_id)
                return f"Forgotten the last {removed} context block(s)."

            elif action == "forget_file":
                file_path = intent.get("file", "")
                if not file_path:
                    return "No file specified."
                to_remove = [
                    h
                    for h, blk in state.active_blocks.items()
                    if blk.file_path and file_path in blk.file_path
                ]
                for h in to_remove:
                    block = state.active_blocks.get(h)
                    if block:
                        self._f._symbol_index.remove_all_for_block(
                            block.hash, block.symbols, project_id
                        )
                    del state.active_blocks[h]
                if to_remove:
                    self._f._activation.invalidate_lightweight_cache(project_id)
                return f"Forgotten {len(to_remove)} block(s) related to {file_path}."

            elif action == "forget_block":
                block_id = intent.get("hash") or intent.get("id") or ""
                if not block_id:
                    return "No block specified."
                if block_id in state.active_blocks:
                    block = state.active_blocks[block_id]
                    self._f._symbol_index.remove_all_for_block(
                        block.hash, block.symbols, project_id
                    )
                    del state.active_blocks[block_id]
                    self._f._activation.invalidate_lightweight_cache(project_id)
                    return f"Forgotten block {block_id}."
                matches = [h for h in state.active_blocks if block_id in h]
                if matches:
                    for h in matches:
                        block = state.active_blocks.get(h)
                        if block:
                            self._f._symbol_index.remove_all_for_block(
                                block.hash, block.symbols, project_id
                            )
                        del state.active_blocks[h]
                    self._f._activation.invalidate_lightweight_cache(project_id)
                    return f"Forgotten {len(matches)} block(s) matching {block_id}."
                return f"No block found for {block_id}."

            else:
                return "Unrecognized forget action."

    async def _execute_remember_intent(self, project_id: str, intent: Dict) -> str:
        """Execute a natural-language remember/pin intent."""
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            state = self._f._conversation_state_manager.get(project_id)
            if not state:
                return "No active context to pin."

            def set_pinned(blocks, pinned_value):
                count = 0
                for blk in blocks:
                    blk.pinned = pinned_value
                    if pinned_value:
                        blk.importance_score = 10.0
                    else:
                        blk._update_importance()
                    count += 1
                return count

            action = intent.get("action", "")
            blocks = list(state.active_blocks.values())
            if not blocks:
                return "No blocks available."

            if action == "pin_last":
                last_block = max(blocks, key=lambda b: b.timestamp)
                set_pinned([last_block], True)
                return "Pinned last code block."
            elif action == "pin_n":
                n = intent.get("n", 1)
                blocks_by_time = sorted(blocks, key=lambda b: b.timestamp, reverse=True)
                to_pin = blocks_by_time[:n]
                count = set_pinned(to_pin, True)
                return f"Pinned {count} block(s)."
            elif action == "pin_file":
                file_path = intent.get("file", "")
                if not file_path:
                    return "No file specified."
                to_pin = [
                    blk
                    for blk in blocks
                    if blk.file_path and file_path in blk.file_path
                ]
                count = set_pinned(to_pin, True)
                return f"Pinned {count} block(s) related to {file_path}."
            elif action == "pin_block":
                desc = intent.get("description", "") or intent.get("hash", "")
                if not desc:
                    return "No block identifier."
                matches = [
                    blk
                    for blk in blocks
                    if desc in blk.content
                    or (blk.hash and desc in blk.hash)
                    or (blk.file_path and desc in blk.file_path)
                ]
                count = set_pinned(matches, True)
                return f"Pinned {count} block(s) matching '{desc}'."
            elif action == "pin_all":
                count = set_pinned(blocks, True)
                return f"Pinned all {count} active blocks."
            elif action == "unpin_last":
                last_block = max(blocks, key=lambda b: b.timestamp)
                set_pinned([last_block], False)
                return "Unpinned last block."
            elif action == "unpin_file":
                file_path = intent.get("file", "")
                if not file_path:
                    return "No file specified."
                to_unpin = [
                    blk
                    for blk in blocks
                    if blk.file_path and file_path in blk.file_path
                ]
                count = set_pinned(to_unpin, False)
                return f"Unpinned {count} block(s) related to {file_path}."
            elif action == "unpin_all":
                count = set_pinned(blocks, False)
                return f"Unpinned all {count} blocks."
            else:
                return "Unrecognized pin action."

    async def _execute_obsolete_intent(self, project_id: str, intent: Dict) -> str:
        """Execute a natural-language obsolete/revive intent."""
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            state = self._f._conversation_state_manager.get(project_id)
            if not state:
                return "No active context to mark as obsolete."

            action = intent.get("action", "")
            if action == "obsolete_all":
                return (
                    "⚠️ For safety, the natural language 'obsolete all' is disabled. "
                    "Please type `/obsolete all` explicitly to confirm."
                )

            blocks = list(state.active_blocks.values())
            if not blocks:
                return "No blocks available."

            def set_obsolete(blks, val):
                for b in blks:
                    b.obsolete = val
                    b._update_importance()
                return len(blks)

            if action == "obsolete_last":
                last_block = max(blocks, key=lambda b: b.timestamp)
                set_obsolete([last_block], True)
                return "Marked last code block as obsolete."

            elif action == "obsolete_n":
                n = intent.get("n", 1)
                blocks_by_time = sorted(blocks, key=lambda b: b.timestamp, reverse=True)
                to_obsolete = blocks_by_time[:n]
                count = set_obsolete(to_obsolete, True)
                return f"Marked {count} block(s) as obsolete."

            elif action == "obsolete_file":
                file_path = intent.get("file", "")
                if not file_path:
                    return "No file specified."
                to_obsolete = [
                    blk
                    for blk in blocks
                    if blk.file_path and file_path in blk.file_path
                ]
                count = set_obsolete(to_obsolete, True)
                return f"Marked {count} block(s) related to {file_path} as obsolete."

            elif action == "obsolete_block":
                desc = intent.get("description", "") or intent.get("hash", "")
                if not desc:
                    return "No block identifier."
                matches = [
                    blk
                    for blk in blocks
                    if desc in blk.content
                    or (blk.hash and desc in blk.hash)
                    or (blk.file_path and desc in blk.file_path)
                ]
                count = set_obsolete(matches, True)
                return f"Marked {count} block(s) matching '{desc}' as obsolete."

            elif action == "revive_last":
                last_block = max(blocks, key=lambda b: b.timestamp)
                set_obsolete([last_block], False)
                return "Removed obsolete mark from last block."

            elif action == "revive_file":
                file_path = intent.get("file", "")
                if not file_path:
                    return "No file specified."
                to_revive = [
                    blk
                    for blk in blocks
                    if blk.file_path and file_path in blk.file_path
                ]
                count = set_obsolete(to_revive, False)
                return f"Removed obsolete mark from {count} block(s) related to {file_path}."

            elif action == "revive_all":
                count = set_obsolete(blocks, False)
                return f"Removed obsolete mark from all {count} block(s)."

            else:
                return "Unrecognized obsolete action."

    # ═══════════════════════════════════════════════════════════════════════
    # 7. Explicit commands (/forget, /status, /clean, /expand)
    # ═══════════════════════════════════════════════════════════════════════

    async def handle_explicit_commands(
        self,
        messages: list,
        project_id: str,
        is_explicit_command: bool,
        last_user_msg: Optional[dict],
        __user__: Optional[dict],
    ) -> Tuple[bool, Optional[list]]:
        """Handle /forget, /status, /clean, /expand.
        Returns (handled, messages) if a command was processed, else (False, None).
        """
        if not last_user_msg:
            return False, None

        content = last_user_msg.get("content", "").strip()

        if self._f.valves.enable_forget_command and is_explicit_command:
            new_messages, handled = await self._handle_forget_command(
                messages, project_id, __user__
            )
            if handled:
                return True, self._f._inlet_orch.ensure_last_message_is_user(
                    new_messages
                )

        if (
            content == "/status"
            and self._f.valves.cleanup_status_command_enabled
            and self._f.valves.cleanup_suggestions_enabled
        ):
            candidates = self._f._activation.get_inactive_block_candidates(project_id)
            if not candidates:
                response = "✅ No inactive blocks detected."
            else:
                lines = [
                    f"⚠️ {len(candidates)} inactive block(s) (not mentioned in last "
                    f"{self._f.valves.cleanup_inactive_threshold_messages} messages):"
                ]
                state = self._f._conversation_state_manager.get(project_id)
                for h in candidates:
                    blk = state.active_blocks.get(h)
                    if blk:
                        snippet = blk.content[:80].replace("\n", " ")
                        file_info = f" ({blk.file_path})" if blk.file_path else ""
                        lines.append(f"- `{h[:8]}...`{file_info}: {snippet}...")
                response = "\n".join(lines)
            messages.pop()
            messages.append({"role": "assistant", "content": response})
            return True, self._f._inlet_orch.ensure_last_message_is_user(messages)

        if (
            content.startswith("/clean")
            and self._f.valves.cleanup_command_enabled
            and self._f.valves.cleanup_suggestions_enabled
        ):
            response = await self._handle_clean_command(content, project_id)
            messages.pop()
            messages.append({"role": "assistant", "content": response})
            return True, self._f._inlet_orch.ensure_last_message_is_user(messages)

        if content.startswith("/expand"):
            response = await self._handle_expand_command(content, project_id)
            messages.pop()
            messages.append({"role": "assistant", "content": response})
            return True, self._f._inlet_orch.ensure_last_message_is_user(messages)

        return False, None

    async def _handle_forget_command(
        self, messages: List[dict], project_id: str, __user__: Optional[dict]
    ) -> Tuple[List[dict], bool]:
        """Handle /forget [all|last|<file_or_hash>].
        Returns (messages, was_handled).
        """
        if not (
            self._f.valves.enable_forget_command
            or self._f.valves.enable_natural_language_forget
        ):
            return messages, False
        if not messages:
            return messages, False
        last_msg = messages[-1]
        if last_msg.get("role") != "user":
            return messages, False
        content = last_msg.get("content", "").strip()
        if self._f.valves.enable_forget_command and content.startswith("/forget"):
            parts = content.split(maxsplit=1)
            target = parts[1] if len(parts) > 1 else ""
            state = self._f._conversation_state_manager.get(project_id)
            if not state:
                return messages, False
            if target == "all":
                for block in state.active_blocks.values():
                    self._f._symbol_index.remove_all_for_block(
                        block.hash, block.symbols, project_id
                    )
                state.active_blocks.clear()
                state.recent_changes.clear()
                state.committed_changes.clear()
                state.has_any_calls = False
                self._f._activation.invalidate_lightweight_cache(project_id)
                confirmation = "Forgotten all context."
            elif target == "last":
                if state.active_blocks:
                    last_hash = max(
                        state.active_blocks.keys(),
                        key=lambda h: state.active_blocks[h].timestamp,
                    )
                    block = state.active_blocks.get(last_hash)
                    if block:
                        self._f._symbol_index.remove_all_for_block(
                            block.hash, block.symbols, project_id
                        )
                    del state.active_blocks[last_hash]
                    self._f._activation.invalidate_lightweight_cache(project_id)
                    confirmation = "Forgotten the last context block."
                else:
                    confirmation = "No blocks to forget."
            else:
                to_remove = [
                    h
                    for h, blk in state.active_blocks.items()
                    if (blk.file_path and target in blk.file_path) or target in h
                ]
                for h in to_remove:
                    block = state.active_blocks.get(h)
                    if block:
                        self._f._symbol_index.remove_all_for_block(
                            block.hash, block.symbols, project_id
                        )
                    del state.active_blocks[h]
                self._f._activation.invalidate_lightweight_cache(project_id)
                confirmation = (
                    f"Forgotten {len(to_remove)} block(s) matching '{target}'."
                )
            self._f._conversation_state_manager.set(project_id, state)
            messages.pop()
            messages.append({"role": "assistant", "content": confirmation})
            return messages, True
        return messages, False

    def _resolve_expand_target(self, token: str, project_id: str):
        """Classify an /expand target.
        Returns ('method', id) | ('class', name) | ('symbol', name).
        """
        m = self._EXPAND_DOTTED.match(token)
        if m:
            cls, meth = m.group(1), m.group(2)
            qid = qualify_symbol_name(meth, cls)
            if self._f._symbol_index.find_blocks(qid, project_id):
                return ("method", qid)
            if meth in self._f._symbol_index.get_all_names(project_id):
                return ("method", meth)
        if token in self._f._symbol_index.get_classes(project_id):
            members = self._f._symbol_index.get_class_members(token, project_id)
            if members:
                return ("class", token)
        return ("symbol", token)

    async def _handle_expand_command(self, content: str, project_id: str) -> str:
        """
        Process /expand [depth] <symbol|Class|Class.method>.
        Returns the expanded code or an error message.
        """
        parts = content.strip().split()
        if len(parts) < 2:
            return "Usage: /expand [depth] <name|Class|Class.method>"

        depth = self._f.valves.expand_default_depth
        token = parts[-1]
        for i in range(1, len(parts)):
            if parts[i].isdigit():
                depth = int(parts[i])
            else:
                token = " ".join(parts[i:])
                break

        target_type, target_name = self._resolve_expand_target(token, project_id)

        if target_type == "class":
            members = self._f._symbol_index.get_class_members(target_name, project_id)
            if not members:
                return f"Class `{target_name}` has no indexed members."
            state = self._f._conversation_state_manager.get(project_id)
            parts_out = [f"## class `{target_name}` ({len(members)} methods)\n"]
            seen_pairs: Set[Tuple[str, str]] = set()
            for mname in members:
                for bh in self._f._symbol_index.find_blocks(mname, project_id):
                    pair = (bh, mname)
                    if pair in seen_pairs:
                        continue
                    seen_pairs.add(pair)
                    block = state.active_blocks.get(bh)
                    if block and not block.obsolete:
                        lang = block.symbols[0].language if block.symbols else ""
                        body = CodeBlockManager.extract_symbol_body(block, mname)
                        parts_out.append(f"### `{mname}`\n```{lang}\n{body}\n```\n")
            if len(parts_out) == 1:
                return f"Class `{target_name}` found but no code blocks available."
            return "\n".join(parts_out)

        elif target_type == "method":
            expanded = await self._expand_symbol_dependencies(
                target_name, depth, project_id
            )
            if expanded:
                return f"[Retrieved `{target_name}`]\n{expanded}"
            return f"Symbol `{target_name}` not found or has no code."

        else:
            expanded = await self._expand_symbol_dependencies(
                target_name, depth, project_id
            )
            if expanded:
                return f"[Retrieved `{target_name}`]\n{expanded}"
            return f"Symbol `{target_name}` not found or has no code."

    async def _expand_symbol_dependencies(
        self, name: str, max_depth: int, project_id: str
    ) -> str:
        """
        Recursively expand a symbol and its callees up to max_depth.
        """
        state = self._f._conversation_state_manager.get(project_id)
        if not state:
            return ""
        visited = set()
        lines = []

        async def recurse(current_name, current_depth):
            if current_depth > max_depth or current_name in visited:
                return
            visited.add(current_name)
            blocks = self._f._symbol_index.find_blocks(current_name, project_id)
            for h in blocks:
                block = state.active_blocks.get(h)
                if block and not block.obsolete:
                    loc = f" (file: {block.file_path})" if block.file_path else ""
                    body = CodeBlockManager.extract_symbol_body(block, current_name)
                    lines.append(
                        f"### `{current_name}` (depth {current_depth}){loc}\n"
                        f"```\n{body}\n```"
                    )
                    for sym in block.symbols:
                        if (
                            sym.name == current_name
                            or qualify_symbol_name(sym.name, sym.parent_symbol)
                            == current_name
                        ):
                            for callee in sym.calls:
                                await recurse(callee, current_depth + 1)
                            break
                    break

        await recurse(name, 1)
        return "\n".join(lines)

    async def outlet_intercept_expand(
        self,
        assistant_content: str,
        project_id: str,
    ) -> Tuple[str, bool]:
        """
        Intercept /expand commands in the assistant's response and replace them
        with the actual expanded symbol code from the SymbolIndex.
        """
        if not self._f.valves.outlet_expand_intercept_enabled:
            return assistant_content, False

        EXPAND_RE = re.compile(r"/expand\s+(?:(\d+)\s+)?(\S+)", re.IGNORECASE)
        matches = list(EXPAND_RE.finditer(assistant_content))
        if not matches:
            return assistant_content, False

        replaced_content = assistant_content
        did_any = False
        state = self._f._conversation_state_manager.get(project_id)

        max_syms = self._f.valves.outlet_expand_intercept_max_symbols
        matches_to_process = matches if max_syms == 0 else matches[:max_syms]

        for match in matches_to_process:
            depth_str = match.group(1)
            token = match.group(2)
            depth = (
                int(depth_str)
                if depth_str
                else self._f.valves.outlet_expand_intercept_depth
            )
            if depth == 0:
                depth = 9999

            target_type, target_name = self._resolve_expand_target(token, project_id)

            if target_type == "class":
                members = self._f._symbol_index.get_class_members(
                    target_name, project_id
                )
                if not members:
                    continue
                seen_pairs: Set[Tuple[str, str]] = set()
                buf = [f"## class `{target_name}` ({len(members)} methods)\n"]
                for mname in members:
                    for bh in self._f._symbol_index.find_blocks(mname, project_id):
                        pair = (bh, mname)
                        if pair in seen_pairs:
                            continue
                        seen_pairs.add(pair)
                        block = state.active_blocks.get(bh)
                        if block and not block.obsolete:
                            lang = block.symbols[0].language if block.symbols else ""
                            body = CodeBlockManager.extract_symbol_body(block, mname)
                            buf.append(f"### `{mname}`\n```{lang}\n{body}\n```\n")
                if len(buf) > 1:
                    replacement = "\n".join(buf)
                else:
                    continue

            elif target_type in ("method", "symbol"):
                expanded = await self._expand_symbol_dependencies(
                    target_name, depth, project_id
                )
                if not expanded:
                    continue
                replacement = f"[Retrieved `{target_name}`]\n{expanded}"

            else:
                continue

            did_any = True
            replaced_content = replaced_content.replace(match.group(0), replacement, 1)

            if target_type != "class":
                lock = await self._f._state_store.get_project_lock(project_id)
                async with lock:
                    block_hashes = self._f._symbol_index.find_blocks(
                        target_name, project_id
                    )
                    for h in block_hashes:
                        block = state.active_blocks.get(h)
                        if block and not block.obsolete:
                            block.is_raw = True
                            block.pinned = True
                            block.importance_score = 10.0
                            block.last_mentioned = time.time()
                            block.last_mentioned_msg_idx = state.message_count
                            break
                    self._f._activation.invalidate_lightweight_cache(project_id)
                    self._f._conversation_state_manager.set(project_id, state)

        return replaced_content, did_any

    # ═══════════════════════════════════════════════════════════════════════
    # 8. Proactive suggestions & cleanup
    # ═══════════════════════════════════════════════════════════════════════

    async def suggest_commands(self, project_id: str, state: dict) -> Optional[str]:
        """Suggest context management commands to the user after enough messages."""
        if not self._f.valves.enable_command_suggestions:
            return None
        now = time.time()
        last_sugg = state.last_suggestion_timestamp
        if now - last_sugg < self._f.valves.command_suggestion_cooldown_minutes * 60:
            return None
        if state.message_count > 15 and not state.has_any_calls:
            state.last_suggestion_timestamp = now
            return (
                "[CodeAware] Tip: You can manage context with commands like "
                "`/forget`, `/remember`, `/status`, `/clean`. Use `/help` for more info."
            )
        return None

    def _get_inactive_block_candidates(self, project_id: str) -> List[str]:
        """Delegate to ActivationEngine — single source of truth for inactive block detection."""
        return self._f._activation.get_inactive_block_candidates(project_id)

    async def _handle_clean_command(self, command_text: str, project_id: str) -> str:
        """Handle /clean [all|<hash>]. Lists or removes inactive blocks."""
        if (
            not self._f.valves.cleanup_suggestions_enabled
            or not self._f.valves.cleanup_command_enabled
        ):
            return "Cleanup is disabled."
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            state = self._f._conversation_state_manager.get(project_id)
            candidates = self._get_inactive_block_candidates(project_id)
            parts = command_text.split(maxsplit=1)
            subcommand = parts[1].strip() if len(parts) > 1 else ""
            if not subcommand:
                if not candidates:
                    return "✅ No inactive blocks to clean."
                lines = [
                    f"⚠️ {len(candidates)} inactive block(s) (not mentioned in last {self._f.valves.cleanup_inactive_threshold_messages} messages):"
                ]
                for h in candidates:
                    blk = state.active_blocks.get(h)
                    if blk:
                        snippet = blk.content[:80].replace("\n", " ")
                        file_info = f" ({blk.file_path})" if blk.file_path else ""
                        lines.append(f"- `{h[:8]}...`{file_info}: {snippet}...")
                lines.append(
                    "\nUse `/clean all` to remove all, or `/clean <hash>` for a specific block."
                )
                return "\n".join(lines)
            if subcommand.lower() == "all":
                if not candidates:
                    return "✅ No inactive blocks to clean."
                for h in candidates:
                    block = state.active_blocks.pop(h, None)
                    if block:
                        self._f._symbol_index.remove_all_for_block(
                            block.hash, block.symbols, project_id
                        )
                state.recent_changes = [
                    c for c in state.recent_changes if c.hash not in candidates
                ]
                state.committed_changes = [
                    c for c in state.committed_changes if c.hash not in candidates
                ]
                self._f._activation.invalidate_lightweight_cache(project_id)
                self._f._conversation_state_manager.set(project_id, state)
                return f"✅ Cleaned {len(candidates)} inactive block(s)."
            target_hash = subcommand.strip()
            if target_hash in candidates:
                block = state.active_blocks.pop(target_hash, None)
                if block:
                    self._f._symbol_index.remove_all_for_block(
                        block.hash, block.symbols, project_id
                    )
                self._f._activation.invalidate_lightweight_cache(project_id)
                self._f._conversation_state_manager.set(project_id, state)
                return f"✅ Cleaned block `{target_hash[:8]}...`."
            else:
                matched = [h for h in state.active_blocks if target_hash in h]
                for h in matched:
                    if h in candidates:
                        block = state.active_blocks.pop(h, None)
                        if block:
                            self._f._symbol_index.remove_all_for_block(
                                block.hash, block.symbols, project_id
                            )
                        self._f._activation.invalidate_lightweight_cache(project_id)
                        self._f._conversation_state_manager.set(project_id, state)
                        return f"✅ Cleaned block `{h[:8]}...` (matched partial hash)."
                return "❌ Block not found among inactive candidates. Use `/status` to see candidates."

    # ═══════════════════════════════════════════════════════════════════════
    # 9. Code detection helpers
    # ═══════════════════════════════════════════════════════════════════════

    async def is_code_only_message(self, content: str, project_id: str) -> bool:
        """
        Detect if a message contains only code without a question.

        Cascade:
        1. Tree-sitter (fast): parses the message as markdown to detect fenced
           code blocks. If the text outside the fences is minimal and contains
           no question marker, classifies as code-only immediately.
        2. CrossEncoder with heuristic reinforcement: handles large files and
           unfenced code with high structural line ratios.
        3. LLM (only when CrossEncoder diff < llm_threshold).
        4. Heuristic structural fallback (when ce_threshold > diff >= llm_threshold).

        Restores KV slot after any LLM call.
        """
        if not content or len(content.strip()) < 20:
            return False

        stripped = content.strip()
        estimated_tokens = self._f._tokens.estimate_code_tokens(content)
        total_lines = len(stripped.splitlines())
        non_empty_lines = [l for l in stripped.splitlines() if l.strip()]

        # ── Step 1: Tree-sitter ──
        # Parse the message as markdown to locate fenced code block spans.
        # ProcessConfig() without a language defaults to '' which triggers a
        # grammar download attempt for an unknown language and always fails.
        # "markdown" is the correct grammar: we want fence detection, not
        # source-code parsing.
        #
        # Threshold is 80 chars (not the original 30) so that short questions
        # adjacent to a fence — e.g. "¿Puedes arreglarlo?" (22 chars) or
        # "can you fix this?" (17 chars) — are not misclassified as code-only.
        # The '?' guard catches interrogative sentences regardless of length.
        # Unfenced code is handled by Step 3 (structural heuristic).
        if HAS_TREE_SITTER:
            try:
                from tree_sitter_language_pack import process, ProcessConfig

                config = ProcessConfig()
                config.language = "markdown"
                blocks = process(content, config)
                if blocks and hasattr(blocks, "blocks"):
                    spans = [(b.start_byte, b.end_byte) for b in blocks.blocks]
                    text_outside = CodeBlockManager.remove_code_spans(
                        content, spans
                    ).strip()
                    if not text_outside or (
                        len(text_outside) < 80 and "?" not in text_outside
                    ):
                        return True
            except Exception:
                pass

        # ── Step 2: CrossEncoder ──
        if estimated_tokens >= self._f.valves.lean_user_code_min_tokens // 2:
            query = content[:500]
            pairs = [
                (
                    query,
                    "This is a code snippet or technical content without a question.",
                ),
                (query, "This is a natural language question or explanation."),
            ]
            scores = await self._predict_cross_encoder(pairs)
            if scores is not None and len(scores) >= 2:
                scores_reinforced = list(scores)
                if "?" not in content and len(content.split()) < 30:
                    scores_reinforced[0] += 0.2

                if total_lines > 500:
                    structural_lines = sum(
                        1
                        for l in non_empty_lines
                        if self._STRUCTURAL_LINE_START.match(l)
                        or self._CONTINUATION_OR_LITERAL.match(l)
                    )
                    ratio = (
                        structural_lines / len(non_empty_lines)
                        if non_empty_lines
                        else 0
                    )
                    if ratio > 0.6:
                        return True
                    if total_lines > 1000 and content.count("?") < 3:
                        return True

                diff = scores_reinforced[0] - scores_reinforced[1]
                CE_CONFIDENCE_THRESHOLD = self._f.valves.code_only_ce_threshold
                LLM_FALLBACK_THRESHOLD = self._f.valves.code_only_llm_threshold
                if diff >= CE_CONFIDENCE_THRESHOLD:
                    return scores_reinforced[0] > scores_reinforced[1]
                elif diff < LLM_FALLBACK_THRESHOLD:
                    return await self._is_code_only_with_llm(
                        query, scores_reinforced, project_id
                    )

        # ── Step 3: Heuristic fallback ──
        raw_lines = stripped.splitlines()
        cleaned_lines = self._strip_code_noise(stripped).splitlines()
        non_blank_idx = [i for i, l in enumerate(raw_lines) if l.strip()]
        total_lines = len(non_blank_idx)
        if total_lines == 0:
            return False

        structural_lines = 0
        prose_candidates: List[str] = []
        for i in non_blank_idx:
            raw_line = raw_lines[i]
            if self._STRUCTURAL_LINE_START.match(
                raw_line
            ) or self._CONTINUATION_OR_LITERAL.match(raw_line):
                structural_lines += 1
                continue
            cleaned_line = cleaned_lines[i].strip() if i < len(cleaned_lines) else ""
            if not cleaned_line:
                structural_lines += 1
                continue
            prose_candidates.append(cleaned_line)

        structural_ratio = structural_lines / total_lines if total_lines else 0
        if structural_ratio > 0.70:
            return True
        prose_text = " ".join(prose_candidates).strip()
        if not prose_text or len(prose_text) < 30:
            return True
        if "?" in prose_text:
            return False
        return True

    async def _is_code_only_with_llm(
        self, query: str, ce_scores: list, project_id: str
    ) -> bool:
        """
        LLM fallback for code-only detection when the CrossEncoder diff is below
        the confidence threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False to
        get a clean structured answer with no reasoning preamble. The server-side
        GBNF grammar guarantees the response is valid JSON, so no text stripping
        is needed.

        Args:
            query: The message text to classify (truncated to 500 chars).
            ce_scores: [code_score, text_score] from the CrossEncoder.
            project_id: Current project identifier, used for slot restoration.

        Returns:
            bool: True if the message is code-only, False otherwise.
        """
        prompt = (
            f"CrossEncoder scores — code_only: {ce_scores[0]:.2f}, "
            f"not_code_only: {ce_scores[1]:.2f}\n\n"
            f"Message:\n{query}\n\n"
            f"Examples:\n"
            f'  "def foo(): pass"                    → {{"is_code_only": true}}\n'
            f'  "def foo(): pass  # what does this?" → {{"is_code_only": false}}\n'
            f'  "how to fix this bug?"               → {{"is_code_only": false}}\n\n'
            f"Classify the message. Output only the JSON object."
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a strict binary classifier. "
                "Output ONLY a valid JSON object with a single boolean field 'is_code_only'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="code_only_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        # Restore the KV slot after any LLM call (auxiliary calls dirty the slot
        # due to the SWA architecture).
        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return False

        try:
            data = json.loads(response)
            return bool(data.get("is_code_only", False))
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_is_code_only_with_llm: JSON parse error — response: {response[:200]!r}"
            )
            return False

    @staticmethod
    def has_code_indicators(content: str) -> bool:
        """True if the content looks like it contains source code."""
        if "```" in content:
            return True
        if re.search(
            r"\b(def |class |import |from |function |const |let |var |"
            r"#include |package |fn |func )",
            content,
        ):
            return True
        if re.search(
            r"\b[\w\-/]+\.(py|js|ts|jsx|tsx|go|rs|java|cpp|c|h|hpp)\b", content
        ):
            return True
        return False

    @classmethod
    def _strip_code_noise(cls, text: str) -> str:
        """
        Blank out triple-quoted strings, block/line comments, and quoted
        string literals while preserving every line break, so line counts
        stay aligned with the original text and any leftover '?' reflects
        real prose — never regex syntax, docstring text, or string content.
        """

        def _blank(m: "re.Match") -> str:
            return "\n".join(" " * len(part) for part in m.group(0).split("\n"))

        text = cls._TRIPLE_QUOTE_RE.sub(_blank, text)
        text = cls._BLOCK_COMMENT_RE.sub(_blank, text)
        text = cls._STRING_RE.sub(_blank, text)
        text = cls._LINE_COMMENT_RE.sub(_blank, text)
        return text

    @staticmethod
    def _blank(m: "re.Match") -> str:
        return "\n".join(" " * len(part) for part in m.group(0).split("\n"))


class CodeBlockManager:
    """
    Extract, classify, and manage code blocks throughout the conversation lifecycle.

    This class handles the full pipeline for code blocks:
    - Extraction from user/assistant messages (fenced or indented)
    - Language detection via tree-sitter with heuristics
    - Classification by content type (base code, diffs, errors, etc.)
    - Deduplication using AST similarity (Python) or fuzzy matching
    - Symbol body extraction via line-range slicing
    - Unified diff application onto existing blocks
    - Data-flow edge extraction for the call graph

    All methods are designed to be deterministic and avoid LLM calls unless
    explicitly noted. Caching is used where parsing is expensive.

    Attributes:
        _code_spans_cache: Cache of tree-sitter byte spans by content hash.
        _ast_signature_cache: Cache of AST signatures (dump + node-type Counter)
            by content hash for deduplication.
        _f: Reference to the parent Filter, for valves and shared state.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the CodeBlockManager with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._code_spans_cache: Dict[str, List[Tuple[int, int]]] = {}
        # Memoizes (stripped-AST dump, node-type Counter) by content hash
        self._ast_signature_cache: "OrderedDict[str, Tuple[str, Counter]]" = (
            OrderedDict()
        )
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Block extraction
    # ═══════════════════════════════════════════════════════════════════════════

    async def get_code_spans(self, content: str) -> List[Tuple[int, int]]:
        """
        Return tree-sitter code spans for the given content, with caching.

        Parses the content as markdown to identify fenced code regions.
        Results are cached by MD5 hash to avoid re-parsing the same text.

        Args:
            content: The raw text to scan for code spans.

        Returns:
            List of (start_byte, end_byte) tuples identifying code regions.
            Empty list if tree-sitter is unavailable or parsing fails.
        """
        if not HAS_TREE_SITTER:
            return []

        cache_key = hashlib.md5(content.encode()).hexdigest()[:16]
        if cache_key in self._code_spans_cache:
            return self._code_spans_cache[cache_key]

        try:
            from tree_sitter_language_pack import process, ProcessConfig

            # Parse as markdown to detect fenced code block spans.
            # ProcessConfig() without a language defaults to '' which triggers
            # a grammar download attempt for an unknown language and always
            # fails. "markdown" is the correct grammar for this use case —
            # we want to find fence boundaries, not parse source code.
            config = ProcessConfig()
            config.language = "markdown"
            blocks = process(content, config)
            spans = [(b.start_byte, b.end_byte) for b in blocks]
        except Exception:
            spans = []

        if len(self._code_spans_cache) >= 200:
            keys_to_evict = list(self._code_spans_cache.keys())[:50]
            for key in keys_to_evict:
                del self._code_spans_cache[key]

        self._code_spans_cache[cache_key] = spans
        return spans

    @staticmethod
    def remove_code_spans(content: str, spans: List[Tuple[int, int]]) -> str:
        """
        Replace code regions with spaces, preserving line lengths.

        This blanking approach ensures that the surrounding text keeps its
        character positions, which is useful for line-number sensitive operations.

        Args:
            content: The original text containing code.
            spans: A list of (start_byte, end_byte) tuples identifying code regions.

        Returns:
            The text with code regions replaced by spaces.
        """
        chars = list(content)
        for start, end in spans:
            for i in range(start, min(end, len(chars))):
                chars[i] = " "
        return "".join(chars)

    async def _extract_full_document_symbols(
        self,
        content: str,
        file_path: Optional[str],
        project_id: Optional[str] = None,
    ) -> Tuple[List["CodeSymbol"], str]:
        """
        Parse the entire document once to preserve nested class context.

        This is the key method that enables parent_symbol resolution. Unlike
        chunked parsing, this parses the whole document so that methods know
        which class they belong to, even when later split into separate blocks.

        Args:
            content (str): The full document source code.
            file_path (Optional[str]): Optional file path for language detection.
            project_id (Optional[str]): The project ID for per-project state.
                                        If None, uses self._f.valves.project_id.

        Returns:
            Tuple[List[CodeSymbol], str]: A tuple of (symbols_list, detected_language).
                                          symbols_list may be empty if language
                                          detection fails or tree-sitter is unavailable.
        """
        # --- 1. Resolve project state ---
        if project_id is None:
            project_id = self._f.valves.project_id
        pstate = self._f._project_state_manager.get_pstate(project_id)

        # --- 2. Detect language ---
        lang = pstate.get("ingested_lang") or SignatureExtractor._guess_language(
            file_path, content
        )
        if lang == "unknown":
            return [], lang

        # --- 3. Extract symbols ---
        symbols = await SignatureExtractor.extract_async(
            content, file_path, language=lang
        )

        # --- 4. Enrich with parent symbol info ---
        if symbols:
            symbols = SignatureExtractor.enrich_symbols_with_parent_info(
                symbols, content
            )

        return symbols, lang

    def _assign_symbols_to_span(
        self,
        full_doc_symbols: List["CodeSymbol"],
        chunk_start_line: int,
        chunk_end_line: int,
    ) -> List["CodeSymbol"]:
        """
        Filter symbols to those whose definition falls within a line range.

        Used when splitting a document into chunks: we pre-parse the whole
        document (so class context is preserved), then assign each symbol to
        the chunk that contains its definition line.

        Args:
            full_doc_symbols: Symbols extracted from the full document.
            chunk_start_line: Start line of the chunk (1-indexed).
            chunk_end_line: End line of the chunk (1-indexed).

        Returns:
            A subset of symbols whose line_start falls within the chunk range.
        """
        # --- 1. Filter symbols by line range ---
        # Since both symbol line numbers and chunk boundaries are in document
        # coordinates, direct comparison is sufficient. No offset arithmetic
        # is needed.
        return [
            s
            for s in full_doc_symbols
            if s.line_start is not None
            and chunk_start_line <= s.line_start <= chunk_end_line
        ]

    @staticmethod
    def _is_likely_code(text: str, languages: Optional[List[str]] = None) -> bool:
        """
        Determine if the given text is likely source code, using tree-sitter.

        To keep it fast, only the first SAMPLE_SIZE characters are analyzed.
        This is sufficient because the nature of the code (keywords, structure)
        is usually evident in the first few lines.

        Args:
            text (str): The text to test.
            languages (Optional[List[str]]): List of language names to try.
                                             Defaults to common languages.

        Returns:
            bool: True if the text is likely code, False otherwise.
        """
        SAMPLE_SIZE = 500  # Reduced from 5000 to 500 for speed

        if not text or len(text.strip()) < 20:
            return False

        # Use a sample to keep it fast
        sample = text[:SAMPLE_SIZE]

        if not HAS_TREE_SITTER:
            # Fallback to simple heuristics when tree-sitter is unavailable
            return bool(
                re.search(
                    r"\b(def|class|import|from|function|const|let|var|fn|pub|use|"
                    r"package|interface|type|enum|struct|impl|trait|"
                    r"public|private|protected|static|void|int|float|string|bool)\b",
                    sample,
                )
            )

        if languages is None:
            languages = [
                "python",
                "javascript",
                "tsx",
                "go",
                "rust",
                "java",
                "cpp",
                "c",
                "ruby",
                "php",
                "c_sharp",
                "swift",
                "kotlin",
                "typescript",
            ]

        from tree_sitter import Parser as TSParser
        from tree_sitter_language_pack import get_language

        for lang in languages:
            try:
                lang_obj = get_language(lang)
                parser = TSParser(lang_obj)
                tree = parser.parse(sample.encode())
                root = tree.root_node
                if root.children and any(n.type != "ERROR" for n in root.children):
                    return True
            except Exception:
                continue

        return False

    async def extract_code_blocks(
        self, content: str, project_id: Optional[str] = None
    ) -> Tuple[List[Dict[str, Any]], List[Tuple[int, int]]]:
        """
        Extract code blocks from a message using tree-sitter Markdown detection.

        Uses tree-sitter process() as a Markdown block detector (without
        extract_symbols=True), falling back to regex for fenced blocks and
        indentation scanning for plain text code snippets.

        Args:
            content: Raw message content.
            project_id: Project identifier for state lookup.

        Returns:
            Tuple of (list of block dicts, list of byte spans).
        """
        if project_id is None:
            project_id = self._f.valves.project_id
        pstate = self._f._project_state_manager.get_pstate(project_id)

        blocks = []
        spans = []
        if not self._f.valves.auto_detect_code_blocks:
            return blocks, spans

        # ── Section 1: Silent ingestion path (pre-extracted symbols) ──────
        raw = pstate.get("raw_ingested_symbols")
        if raw is not None:
            pstate["raw_ingested_symbols"] = None
            lang = pstate.get("ingested_lang", "python")
            block = {
                "language": lang,
                "code": content,
                "type": "indented",
                "precomputed_symbols": raw,
            }
            block["file_path"] = self._guess_file_path(content)
            if not self._is_filter_internal(block["file_path"]):
                return [block], [(0, len(content))]
            return [], []

        # ── Section 2: Tree-sitter Markdown block detection ───────────────
        # Parse as markdown to locate fenced code block spans.
        # ProcessConfig() without a language defaults to '' which triggers a
        # grammar download attempt for an unknown language and always fails.
        # "markdown" is the correct grammar: we want fence detection, not
        # source-code parsing. extract_symbols is intentionally NOT set here.
        if HAS_TREE_SITTER:
            try:
                from tree_sitter_language_pack import process, ProcessConfig

                config = ProcessConfig()
                config.language = "markdown"
                result = process(content, config)
                if hasattr(result, "blocks"):
                    self._f._log_debug(
                        f"extract_code_blocks: process() found {len(result.blocks)} block(s)"
                    )
                    for b in result.blocks:
                        lang = getattr(b, "language", None) or "text"
                        code = content[b.start_byte : b.end_byte].strip()
                        blocks.append(
                            {"language": lang, "code": code, "type": "fenced"}
                        )
                        spans.append((b.start_byte, b.end_byte))
                    if blocks:
                        self._f._log_debug(
                            f"tree-sitter path extracted {len(blocks)} block(s)"
                        )
                        return self._postprocess_blocks(blocks, spans, content)
            except Exception as e:
                self._f._log_debug(
                    f"tree-sitter failed ({e}), falling through to regex"
                )

        # ── Section 3: Regex fallback for fenced code blocks ──────────────
        for match in self._f.code_pattern.finditer(content):
            lang = match.group(1) or "text"
            code = match.group(2).strip()
            if len(code) > 200_000:
                self._f._log_debug(
                    f"Skipping oversized fenced block ({len(code)} chars)"
                )
                continue
            blocks.append({"language": lang, "code": code, "type": "fenced"})
            spans.append((match.start(), match.end()))

        if blocks:
            self._f._log_debug(f"regex found {len(blocks)} fenced block(s)")
            return self._postprocess_blocks(blocks, spans, content)

        # ── Section 4: Indented blocks (only if no fenced blocks) ─────────
        lines = content.split("\n")
        line_offsets = [0]
        for line in lines:
            line_offsets.append(line_offsets[-1] + len(line) + 1)

        total_lines = len(lines)
        i = 0
        indented = []
        while i < total_lines:
            line = lines[i]
            if line.startswith(("    ", "\t")):
                indented.append(line.lstrip(" \t"))
                i += 1
            else:
                if len(indented) >= 3:
                    code = "\n".join(indented)
                    if self._is_likely_code(code) and len(code) <= 200_000:
                        lang = SignatureExtractor._guess_language(None, code) or "text"
                        blocks.append(
                            {"language": lang, "code": code, "type": "indented"}
                        )
                        start_offset = line_offsets[i - len(indented)]
                        end_offset = line_offsets[i] - 1
                        spans.append((start_offset, end_offset))
                    indented = []
                else:
                    indented = []
                i += 1

        if len(indented) >= 3:
            code = "\n".join(indented)
            if self._is_likely_code(code) and len(code) <= 200_000:
                lang = SignatureExtractor._guess_language(None, code) or "text"
                blocks.append({"language": lang, "code": code, "type": "indented"})
                start_offset = line_offsets[total_lines - len(indented)]
                end_offset = line_offsets[total_lines] - 1
                spans.append((start_offset, end_offset))

        # ── Section 5: Entire small content as a single block ─────────────
        if not blocks and len(content) <= 20_000 and self._is_likely_code(content):
            lang = SignatureExtractor._guess_language(None, content) or "text"
            blocks.append({"language": lang, "code": content, "type": "indented"})
            spans.append((0, len(content)))
            self._f._log_debug(
                f"treating entire small message as code ({len(content)} chars)"
            )

        return self._postprocess_blocks(blocks, spans, content)

    def _postprocess_blocks(
        self, blocks: List[Dict], spans: List[Tuple[int, int]], content: str
    ) -> Tuple[List[Dict], List[Tuple[int, int]]]:
        """
        Attach file paths to blocks and filter out internal system paths.

        Args:
            blocks: List of extracted block dictionaries.
            spans: List of corresponding byte spans.
            content: Original message content for path extraction.

        Returns:
            Filtered list of blocks and spans.
        """
        processed_blocks = []
        processed_spans = []
        for idx, block in enumerate(blocks):
            blk_file = None
            if self._f.valves.track_file_paths and idx < len(spans):
                blk_file = self.extract_file_path_for_block(content, spans[idx][0])
            if not blk_file and len(blocks) == 1:
                paths = self.extract_file_paths(content)
                blk_file = paths[0] if paths else None

            if self._f.valves.exclude_filter_internals and blk_file:
                if (
                    "/app/backend/data/functions/" in blk_file
                    or "open-webui/functions/" in blk_file
                ):
                    continue

            block["file_path"] = blk_file
            processed_blocks.append(block)
            processed_spans.append(spans[idx] if idx < len(spans) else (0, 0))

        return processed_blocks, processed_spans

    @staticmethod
    def _is_likely_code(text: str) -> bool:
        """
        Lightweight heuristic to determine if text looks like source code.

        This is a fallback when tree-sitter Markdown detection is unavailable.
        It does NOT parse grammar; it simply checks for structural keywords.

        Args:
            text: The text to evaluate.

        Returns:
            True if it looks like code, False otherwise.
        """
        if not text or len(text.strip()) < 20:
            return False
        sample = text[:500]
        return bool(
            re.search(
                r"\b(def|class|import|from|function|const|let|var|fn|pub|use|"
                r"package|interface|type|enum|struct|impl|trait|"
                r"public|private|protected|static|void|int|float|string|bool)\b",
                sample,
            )
        )

    def _is_filter_internal(self, file_path: Optional[str]) -> bool:
        """
        Check if a file path belongs to the filter's internal directories.

        Args:
            file_path: The file path to check.

        Returns:
            True if the path is internal and should be excluded.
        """
        if not file_path:
            return False
        return (
            "/app/backend/data/functions/" in file_path
            or "open-webui/functions/" in file_path
        )

    def _guess_file_path(self, content: str) -> Optional[str]:
        """
        Attempt to extract a file path from the beginning of the content.

        Args:
            content: The message content.

        Returns:
            The first matching file path, or None.
        """
        if not self._f.valves.track_file_paths:
            return None
        paths = self.extract_file_paths(content)
        return paths[0] if paths else None

    async def _infer_code_language(self, code_snippet: str) -> str:
        """
        Simple heuristic language detection for a code snippet.

        Used as a fallback when tree-sitter language detection fails or
        returns "unknown". Only detects Python and JavaScript currently.

        Args:
            code_snippet: The source code to analyze.

        Returns:
            A language string ("python", "javascript", or "unknown").
        """
        if re.search(r"\bdef\s+\w+\s*\(", code_snippet):
            return "python"
        if re.search(r"\bfunction\s+\w+\s*\(", code_snippet):
            return "javascript"
        return "unknown"

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Content classification
    # ═══════════════════════════════════════════════════════════════════════════

    def classify_content(self, content: str, extracted_blocks: list) -> "ContentType":
        """
        Classify a message's content into one of the ContentType categories.

        Detection order (first match wins):
        1. Diff pattern (unified diff) → PROPOSED_CHANGE
        2. Commit pattern (hash) → COMMITTED_CHANGE if "applied/committed/merged"
           in text, otherwise PROPOSED_CHANGE
        3. Traceback/error indicators → ERROR
        4. Tool/function call indicators → TOOL_CALL
        5. Structural code in extracted blocks (def/class/function) → BASE_CODE
        6. Default → GENERAL

        Args:
            content: The raw message content.
            extracted_blocks: List of code blocks extracted from the content.

        Returns:
            A ContentType enum value.
        """
        cl = content.lower()

        # ── 1. Diff pattern ──────────────────────────────────────────────────
        if self._f.diff_pattern.search(content) or "diff --git" in content:
            return ContentType.PROPOSED_CHANGE

        # ── 2. Commit pattern ───────────────────────────────────────────────
        if self._f.commit_pattern.search(content):
            if "applied" in cl or "committed" in cl or "merged" in cl:
                return ContentType.COMMITTED_CHANGE
            return ContentType.PROPOSED_CHANGE

        # ── 3. Error / traceback ────────────────────────────────────────────
        if (
            "traceback" in cl
            or ('file "' in cl and "line " in cl)
            or ("exception" in cl and ("traceback" in cl or 'file "' in cl))
        ):
            return ContentType.ERROR

        # ── 4. Tool call ────────────────────────────────────────────────────
        if '"tool_calls"' in content or '"function"' in content:
            return ContentType.TOOL_CALL

        # ── 5. Base code ────────────────────────────────────────────────────
        for blk in extracted_blocks:
            if blk["language"] in [
                "python",
                "javascript",
                "typescript",
                "go",
                "rust",
                "java",
                "cpp",
            ]:
                if (
                    "def " in blk["code"]
                    or "class " in blk["code"]
                    or "function " in blk["code"]
                ):
                    return ContentType.BASE_CODE

        # ── 6. Default ──────────────────────────────────────────────────────
        return ContentType.GENERAL

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. File path extraction
    # ═══════════════════════════════════════════════════════════════════════════

    def extract_file_paths(self, content: str) -> list:
        """
        Extract all file paths matching the configured pattern from content.

        Uses the regex pattern defined in `valves.file_path_pattern` to find
        file paths. Returns them as strings (unwraps tuple captures if present).

        Args:
            content: The text to scan for file paths.

        Returns:
            A list of file path strings (may be empty).
        """
        if not self._f.valves.track_file_paths:
            return []
        matches = re.findall(self._f.valves.file_path_pattern, content)
        return [m[0] if isinstance(m, tuple) else m for m in matches]

    def extract_file_path_for_block(
        self, content: str, block_start: int
    ) -> Optional[str]:
        """
        Try to find a file path associated with a code block by scanning backwards.

        Searches the text immediately preceding the block for a file path pattern.
        Used to infer the file that a code snippet belongs to.

        Args:
            content: The full text content.
            block_start: The byte offset where the block begins.

        Returns:
            The file path if found, otherwise None.
        """
        if block_start <= 0:
            return None

        # ── 1. Scan backwards from the block start ──────────────────────────
        before = content[:block_start]
        lines = before.splitlines()

        for line in reversed(lines):
            line = line.strip()
            if not line:
                continue

            # ── 1a. Try direct file path pattern ────────────────────────────
            match = re.search(self._f.valves.file_path_pattern, line)
            if match:
                return match.group(1) if match.lastindex else match.group(0)

            # ── 1b. Try line-range extraction ──────────────────────────────
            file_path, _, _ = self._extract_line_range(line)
            if file_path:
                return file_path

            break  # Only look at the nearest non-empty line

        return None

    def _extract_line_range(
        self, content: str
    ) -> Tuple[Optional[str], Optional[int], Optional[int]]:
        """
        Extract file path and line numbers from a reference string.

        Matches patterns like "file.py:42" or "file.py:10-20" to extract
        the file path, start line, and end line.

        Args:
            content: A string that may contain a file:line reference.

        Returns:
            A tuple of (file_path, start_line, end_line). Any field may be None.
        """
        if not self._f.valves.track_line_numbers:
            return None, None, None

        pattern = r"(?:^|\s)([^\s:]+\.\w+):(\d+)(?:-(\d+))?"
        match = re.search(pattern, content)
        if match:
            return (
                match.group(1),
                int(match.group(2)),
                int(match.group(3)) if match.group(3) else int(match.group(2)),
            )
        return None, None, None

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. General utilities
    # ═══════════════════════════════════════════════════════════════════════════

    @staticmethod
    def sanitize_text(text: str) -> str:
        """
        Remove non-printable characters and replace backticks with single quotes.

        This prevents control characters from breaking the prompt formatting
        and ensures backticks don't interfere with fenced code blocks.

        Args:
            text: The text to sanitize.

        Returns:
            Sanitized text with no control characters and backticks replaced.
        """
        cleaned = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f-\x9f]", "", text)
        cleaned = cleaned.replace("`", "'")
        return cleaned

    @staticmethod
    def format_block_context(block: "CodeBlock", is_latest: bool) -> str:
        """
        Render a single active CodeBlock for injection into the system prompt.

        Produces a formatted block with:
        - A header line with block hash, file path (if available), and a [LATEST] marker.
        - A fenced code block with the language tag and the full code body.

        Args:
            block: The CodeBlock to render.
            is_latest: Whether this is the most recent version of the file.

        Returns:
            A formatted string ready for inclusion in the system prompt.
        """
        latest_tag = " [LATEST]" if is_latest else ""
        location = f" `{block.file_path}`" if block.file_path else ""
        language = block.symbols[0].language if block.symbols else ""
        header = f"#### Block {block.hash[:8]}{location}{latest_tag}"
        return f"{header}\n```{language}\n{block.content}\n```"

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Symbol body extraction
    # ═══════════════════════════════════════════════════════════════════════════

    @staticmethod
    def extract_symbol_body(
        block: "CodeBlock", node_id: str, max_chars: int = 0
    ) -> str:
        """
        Extract the source body of a symbol using its line range.

        This is the key method for precise symbol extraction: given a block
        and a symbol identifier, it finds the symbol's line range and slices
        the block content to return only that symbol's code.

        The method handles three matching strategies:
        1. Full qualified id (with file_path) — most precise.
        2. Qualified id (without file_path) — for cross-file consistency.
        3. Bare name — fallback for when only the name is known.

        Args:
            block: The CodeBlock containing the symbol.
            node_id: The qualified symbol id (e.g. "ClassName.method").
            max_chars: Optional character limit for the returned body.

        Returns:
            The sliced source body, or the whole block content if slicing fails.
        """
        # ── 1. Locate the symbol in the block ──────────────────────────────
        target = None
        for sym in block.symbols:
            # Try full qualified id (with file_path), then without, then bare name.
            if (
                qualify_symbol_name(sym.name, sym.parent_symbol, sym.file_path)
                == node_id
                or qualify_symbol_name(sym.name, sym.parent_symbol) == node_id
                or sym.name == node_id
            ):
                target = sym
                break

        # ── 2. Slice the block content by the symbol's line range ──────────
        body = block.content
        if target is not None and target.line_start and target.line_end:
            lines = block.content.split("\n")
            # Defensive bounds check to ensure line numbers are valid.
            if 1 <= target.line_start <= len(lines) and target.line_end <= len(lines):
                sliced = "\n".join(
                    lines[target.line_start - 1 : target.line_end]
                ).strip()
                if sliced:
                    body = sliced

        # ── 3. Apply character limit if requested ──────────────────────────
        if max_chars and len(body) > max_chars:
            body = body[:max_chars] + "\n# ... [truncated]"

        return body

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Similarity & deduplication
    # ═══════════════════════════════════════════════════════════════════════════

    def calculate_code_similarity(self, code1: str, code2: str) -> float:
        """
        Compute similarity between two code snippets.

        Uses two strategies in order:
        1. AST-based structural similarity for Python code (if enabled).
        2. Fuzzy matching (token sort ratio) as fallback.

        Args:
            code1: First code snippet.
            code2: Second code snippet.

        Returns:
            A similarity score in [0.0, 1.0]. Higher = more similar.
        """
        # ── 1. AST similarity (Python only) ─────────────────────────────────
        if (
            self._f.valves.enable_ast_deduplication
            and len(code1) > 30
            and len(code2) > 30
        ):
            ast_sim = self._ast_similarity(code1, code2)
            if ast_sim is not None:
                return ast_sim

        # ── 2. Fallback: token-sort ratio or character-level similarity ────
        if not HAS_FUZZ:
            min_len = min(len(code1), len(code2))
            if min_len == 0:
                return 0.0
            common = sum(1 for a, b in zip(code1[:min_len], code2[:min_len]) if a == b)
            return common / max(len(code1), len(code2))

        return fuzz.token_sort_ratio(code1, code2) / 100.0

    def _ast_similarity(self, code1: str, code2: str) -> Optional[float]:
        """
        Compute Jaccard similarity on AST node type distributions.

        For Python code only. Uses memoized AST signatures to avoid re-parsing
        the same code multiple times within a single deduplication pass.

        Args:
            code1: First Python code snippet.
            code2: Second Python code snippet.

        Returns:
            A similarity score in [0.0, 1.0], or None if either snippet
            is not Python or parsing fails.
        """
        # ── 1. Quick check: both snippets look like Python ──────────────────
        if not (
            re.search(r"\bdef\s+\w+\s*\(", code1) or re.search(r"\bclass\s+\w+", code1)
        ):
            return None

        # ── 2. Get memoized AST signatures ──────────────────────────────────
        sig1 = self._parsed_ast_signature(code1)
        sig2 = self._parsed_ast_signature(code2)
        if sig1 is None or sig2 is None:
            return None

        dump1, c1 = sig1
        dump2, c2 = sig2

        # ── 3. Quick exit: structurally identical ──────────────────────────
        if dump1 == dump2:
            return 1.0

        # ── 4. Compute Jaccard similarity on node types ─────────────────────
        all_types = set(c1.keys()) | set(c2.keys())
        if not all_types:
            return 0.0

        intersection = sum(min(c1.get(t, 0), c2.get(t, 0)) for t in all_types)
        union = sum(max(c1.get(t, 0), c2.get(t, 0)) for t in all_types)

        return intersection / union if union > 0 else 0.0

    def _parsed_ast_signature(self, code: str) -> Optional[Tuple[str, Counter]]:
        """
        Parse code into its AST signature: stripped dump + node-type Counter.

        Memoized by content hash so the same code is never parsed twice within
        a single deduplication pass. Docstrings are stripped from the AST dump
        because they don't affect structural similarity.

        Args:
            code: The source code to parse.

        Returns:
            A tuple of (stripped_ast_dump, node_type_counter), or None
            if parsing fails. The result is cached for future calls.
        """
        # ── 1. Check cache ───────────────────────────────────────────────────
        key = hashlib.md5(code.encode()).hexdigest()
        cached = self._ast_signature_cache.get(key)
        if cached is not None:
            self._ast_signature_cache.move_to_end(key)
            return cached

        # ── 2. Parse the code ───────────────────────────────────────────────
        try:
            tree = ast.parse(code)
        except (SyntaxError, MemoryError, RecursionError, ValueError):
            return None

        # ── 3. Strip docstrings from the AST ────────────────────────────────
        for node in ast.walk(tree):
            if not isinstance(
                node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Module)
            ):
                continue
            if (
                node.body
                and isinstance(node.body[0], ast.Expr)
                and isinstance(node.body[0].value, ast.Constant)
                and isinstance(node.body[0].value.value, str)
            ):
                node.body = node.body[1:]
                if not node.body:
                    node.body = [ast.Pass()]

        # ── 4. Build signature ──────────────────────────────────────────────
        result = (
            ast.dump(tree),
            Counter(type(node).__name__ for node in ast.walk(tree)),
        )

        # ── 5. Cache with LRU eviction ──────────────────────────────────────
        self._ast_signature_cache[key] = result
        if len(self._ast_signature_cache) > 200:
            self._ast_signature_cache.popitem(last=False)

        return result

    def remove_duplicate_blocks(self, state: dict, project_id: str) -> None:
        """
        Remove duplicate or near-duplicate code blocks from the active set.

        Uses three strategies:
        1. Pairwise similarity comparison (AST or fuzzy matching).
        2. Age-based: keep newer blocks if similarity threshold is met.
        3. Per-file version limiting: keep only the most recent version.

        Args:
            state: The conversation state containing active_blocks.
            project_id: The current project identifier.
        """
        if not self._f.valves.auto_remove_duplicate_blocks:
            return

        blocks = list(state.active_blocks.values())
        to_remove = set()

        # ── 1. Pairwise similarity comparison ──────────────────────────────
        for i, block in enumerate(blocks):
            if block.hash in to_remove or block.pinned or block.obsolete:
                continue

            for j, other in enumerate(blocks[i + 1 :], start=i + 1):
                if other.hash in to_remove or other.pinned or other.obsolete:
                    continue

                sim = self.calculate_code_similarity(block.content, other.content)
                if sim >= self._f.valves.code_similarity_threshold:
                    age_diff = abs(block.timestamp - other.timestamp) / 3600

                    # ── 1a. If age difference is significant ──────────────
                    if age_diff > self._f.valves.max_duplicate_age_hours:
                        if (
                            block.timestamp < other.timestamp
                            and block.importance_score < 5.0
                        ):
                            to_remove.add(block.hash)
                        elif (
                            other.timestamp < block.timestamp
                            and other.importance_score < 5.0
                        ):
                            to_remove.add(other.hash)
                        continue

                    # ── 1b. Compare by importance score ─────────────────────
                    score_diff = abs(block.importance_score - other.importance_score)
                    if score_diff < 1.0:
                        # If scores are similar, keep the newer one.
                        if block.timestamp >= other.timestamp:
                            to_remove.add(other.hash)
                        else:
                            to_remove.add(block.hash)
                    elif block.importance_score >= other.importance_score:
                        to_remove.add(other.hash)
                    else:
                        to_remove.add(block.hash)

        # ── 2. Per-file version limiting ────────────────────────────────────
        blocks_by_file = defaultdict(list)
        for b in blocks:
            if b.file_path and not b.pinned:
                blocks_by_file[b.file_path].append(b)

        for file_path, blks in blocks_by_file.items():
            if len(blks) > 1:
                blks.sort(key=lambda b: b.timestamp, reverse=True)
                for b in blks[1:]:
                    to_remove.add(b.hash)

        # ── 3. Apply removal ────────────────────────────────────────────────
        for h in to_remove:
            if h in state.active_blocks:
                block = state.active_blocks[h]
                self._f._symbol_index.remove_all_for_block(
                    block.hash, block.symbols, project_id
                )
                del state.active_blocks[h]

        # ── 4. Clean up dependent lists ─────────────────────────────────────
        state.recent_changes = [
            b for b in state.recent_changes if b.hash not in to_remove
        ]
        state.committed_changes = [
            b for b in state.committed_changes if b.hash not in to_remove
        ]

        # ── 5. Update state and invalidate cache ───────────────────────────
        if to_remove:
            state.has_any_calls = any(
                any(s.calls for s in b.symbols) for b in state.active_blocks.values()
            )
            self._f._activation.invalidate_lightweight_cache(project_id)

    # ═══════════════════════════════════════════════════════════════════════════
    # 7. Proposed changes & diffs
    # ═══════════════════════════════════════════════════════════════════════════

    def has_conflicting_proposed_changes(
        self,
        state: dict,
        new_block: "CodeBlock",
    ) -> bool:
        """
        Return True when an active assistant-generated block targets the same
        file as new_block and was created more recently than new_block.

        A conflict indicates that a prior proposed change is still active and
        has not been superseded. The caller uses this to decide whether to
        update the existing block in place (dedup) or add a new one.

        file_path=None blocks are never considered conflicting with each other.
        Anonymous code snippets (no file path) are independent regardless of
        content: two code blocks without a file path are not targeting the same
        file by definition. Without this guard, None == None evaluates to True
        and every anonymous block in the session conflicts with every other,
        causing all but the first to be silently rejected.

        Steps:
            1.  Return False when new_block has no file_path.
            2.  Iterate active blocks: match file_path, assistant-generated,
                non-obsolete, timestamp newer than new_block.
            3.  Return True on first match, False when none found.
        """
        # -- Step 1: anonymous block guard --
        if not new_block.file_path:
            return False

        active_blocks = (
            state.active_blocks
            if isinstance(state, dict)
            else getattr(state, "active_blocks", {})
        )

        new_ts = new_block.timestamp

        # -- Steps 2-3: scan active blocks --
        for block in active_blocks.values():
            if block.obsolete:
                continue
            if not block.generated_by_assistant:
                continue
            if not block.file_path:
                continue
            if block.file_path != new_block.file_path:
                continue
            if block.timestamp <= new_ts:
                continue
            self._f._log_debug(
                f"has_conflicting_proposed_changes: conflict found for "
                f"'{new_block.file_path}' "
                f"(existing ts={block.timestamp:.3f} > new ts={new_ts:.3f})"
            )
            return True

        return False

    def _apply_unified_diff(
        self,
        original: str,
        diff_text: str,
    ) -> Optional[str]:
        """
        Apply a unified diff to original content and return the patched result.

        Normalises both the original content and the diff to LF line endings
        before patching so that CR+LF originals (Windows editors, clipboard
        paste) and LF diffs (standard diff output) do not cause a line-mismatch
        failure. The result is returned with LF endings; callers that need to
        preserve the original line-ending style must post-process.

        Returns None when:
            - diff_text is empty or does not contain a valid unified diff header
            - the patch library is unavailable
            - patching fails after line-ending normalisation

        Steps:
            1.  Validate inputs; return None on empty diff.
            2.  Normalize line endings in both original and diff_text.
            3.  Attempt to parse and apply the patch.
            4.  Return patched string or None on failure.
        """
        # -- Step 1: validate inputs --
        if not diff_text or not diff_text.strip():
            return None
        if "---" not in diff_text or "+++" not in diff_text:
            self._f._log_debug(
                "_apply_unified_diff: diff_text does not contain a valid "
                "unified diff header, skipping"
            )
            return None

        # -- Step 2: normalize line endings --
        original_lf = original.replace("\r\n", "\n").replace("\r", "\n")
        diff_text_lf = diff_text.replace("\r\n", "\n").replace("\r", "\n")

        # -- Step 3: apply patch --
        try:
            import patch as patch_lib  # python-patch

            pset = patch_lib.fromstring(diff_text_lf.encode("utf-8"))
            if not pset:
                self._f._log_debug(
                    "_apply_unified_diff: patch.fromstring returned empty patchset"
                )
                return None

            # patch_lib.apply works on bytes; encode, apply, decode
            patched_bytes = pset.apply(original_lf.encode("utf-8"), root=b"")
            if patched_bytes is False or patched_bytes is None:
                self._f._log_debug(
                    "_apply_unified_diff: patch application failed "
                    "(hunk mismatch after LF normalisation)"
                )
                return None

            return patched_bytes.decode("utf-8", errors="replace")

        except ImportError:
            # Fallback: use difflib.restore if python-patch not available
            try:
                import difflib

                original_lines = original_lf.splitlines(keepends=True)
                diff_lines = diff_text_lf.splitlines(keepends=True)
                result_lines = list(difflib.restore(diff_lines, which=2))
                return "".join(result_lines)
            except Exception as e:
                self._f._log_debug(
                    f"_apply_unified_diff: difflib fallback failed: "
                    f"{type(e).__name__}: {e}"
                )
                return None

        except Exception as e:
            self._f._log_debug(
                f"_apply_unified_diff: patch failed: {type(e).__name__}: {e}"
            )
            return None

    async def apply_change_with_diff(
        self, base_block: "CodeBlock", proposed_block: "CodeBlock"
    ) -> bool:
        """
        Apply a unified diff from a proposed change onto a base block.

        If the diff applies successfully, the base block is updated with the
        new content, symbols are re-extracted, and the symbol index is updated.

        Args:
            base_block: The original code block to patch.
            proposed_block: The diff-containing proposed change.

        Returns:
            True if the diff was applied successfully, False otherwise.
        """
        # ── 1. Validate inputs ──────────────────────────────────────────────
        if proposed_block.content_type != ContentType.PROPOSED_CHANGE:
            return False

        if not (
            "@@" in proposed_block.content
            and ("-" in proposed_block.content or "+" in proposed_block.content)
        ):
            return False

        # ── 2. Apply the diff ───────────────────────────────────────────────
        new_code = self._apply_unified_diff(base_block.content, proposed_block.content)
        if not new_code or new_code == base_block.content:
            return False

        project_id = self._f.valves.project_id

        # ── 3. Remove old symbols from index ───────────────────────────────
        self._f._symbol_index.remove_all_for_block(
            base_block.hash, base_block.symbols, project_id
        )

        # ── 4. Update block content and hash ───────────────────────────────
        base_block.content = new_code
        base_block.hash = hashlib.md5(new_code.encode()).hexdigest()[:16]

        # ── 5. Re-extract symbols ───────────────────────────────────────────
        base_block.symbols = await SignatureExtractor.extract_async(
            new_code, base_block.file_path
        )

        # ── 6. Re-index symbols ─────────────────────────────────────────────
        for sym in base_block.symbols:
            sym.parent_block_hash = base_block.hash
            self._f._symbol_index.add(sym, base_block.hash, project_id)

        # ── 7. Update cached token count ───────────────────────────────────
        if self._f.tokenizer:
            base_block._cached_token_count = len(self._f.tokenizer.encode(new_code))
        else:
            base_block._cached_token_count = len(new_code) // 4

        # ── 8. Update metadata ─────────────────────────────────────────────
        base_block.timestamp = time.time()
        base_block.is_active = True
        base_block.importance_score = min(base_block.importance_score + 2.0, 10.0)

        # ── 9. Invalidate cache ─────────────────────────────────────────────
        self._f._activation.invalidate_lightweight_cache(project_id)

        return True

    # ═══════════════════════════════════════════════════════════════════════════
    # 8. Data flow edges
    # ═══════════════════════════════════════════════════════════════════════════

    def _extract_data_flow_edges_regex(
        self, code: str, project_id: str
    ) -> List["Edge"]:
        """
        Fallback data flow extraction for non-Python languages via regex.

        This is a best-effort heuristic that identifies:
        1. Assignments to variables from function calls.
        2. Subsequent usage of those variables as function arguments.

        Args:
            code: The source code to analyze.
            project_id: The current project identifier.

        Returns:
            A list of Edge objects representing data flow relationships.
        """
        all_names = self._f._symbol_index.get_all_names(project_id)
        edges: List[Edge] = []

        # ── 1. Find assignments from function calls ─────────────────────────
        pattern = re.compile(
            r"\b(\w+)\s*=\s*(" + "|".join(re.escape(n) for n in all_names) + r")\s*\("
        )

        for match in pattern.finditer(code):
            callee = match.group(2)
            var_name = match.group(1)

            # ── 2. Find subsequent usage of the variable ────────────────────
            use_pattern = re.compile(
                r"\b("
                + "|".join(re.escape(n) for n in all_names)
                + r")\s*\([^)]*\b"
                + re.escape(var_name)
                + r"\b"
            )

            for use_match in use_pattern.finditer(code):
                consumer = use_match.group(1)
                if consumer != callee:
                    edges.append(
                        Edge(
                            src=callee,
                            dst=consumer,
                            type="data_flow",
                            weight=EDGE_WEIGHTS["data_flow"],
                            confidence=0.5,
                        )
                    )

        return edges

    def extract_data_flow_edges(
        self, code: str, file_path: Optional[str], project_id: str
    ) -> List["Edge"]:
        """
        Extract data flow edges from Python code using AST, with regex fallback.

        For Python code, this uses AST analysis to track:
        1. Variable assignments.
        2. Which variables are passed as arguments to function calls.
        3. The flow of data from producers to consumers.

        The key insight is that if a variable is assigned from a function call
        and later passed to another function, there's a data flow edge from
        the producer to the consumer.

        Args:
            code: The source code to analyze.
            file_path: The file path (used to determine language).
            project_id: The current project identifier.

        Returns:
            A list of Edge objects representing data flow relationships.
        """
        # ── 1. Non-Python: use regex fallback ──────────────────────────────
        if not file_path or not file_path.endswith(".py"):
            return self._extract_data_flow_edges_regex(code, project_id)

        all_names = self._f._symbol_index.get_all_names(project_id)
        if not all_names:
            return []

        edges: List[Edge] = []

        # ── 2. Parse Python AST ─────────────────────────────────────────────
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return []

        # ── 3. Map line numbers to enclosing classes ────────────────────────
        line_to_class: Dict[int, str] = {}

        def _mark_classes(node, current_class: str) -> None:
            """Recursively mark lines with their enclosing class name."""
            for child in ast.iter_child_nodes(node):
                if isinstance(child, ast.ClassDef):
                    end = getattr(child, "end_lineno", child.lineno)
                    for ln in range(child.lineno, end + 1):
                        line_to_class[ln] = current_class
                    _mark_classes(child, child.name)
                elif isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    end = getattr(child, "end_lineno", child.lineno)
                    for ln in range(child.lineno, end + 1):
                        line_to_class[ln] = current_class
                    _mark_classes(child, current_class)
                else:
                    _mark_classes(child, current_class)

        _mark_classes(tree, "")

        # ── 4. Analyze each function for data flow ──────────────────────────
        for func_node in ast.walk(tree):
            if not isinstance(func_node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue

            caller_name = func_node.name
            if caller_name not in all_names:
                continue

            caller_class = line_to_class.get(func_node.lineno, "")
            caller_qid = qualify_symbol_name(caller_name, caller_class)

            # ── 4a. Collect variables assigned in this function ────────────
            assigned_vars: Set[str] = set()
            for child in ast.walk(func_node):
                if isinstance(child, ast.Assign):
                    for target in child.targets:
                        if isinstance(target, ast.Name):
                            assigned_vars.add(target.id)

            # ── 4b. Find calls that use assigned variables as arguments ────
            for child in ast.walk(func_node):
                if not isinstance(child, ast.Call):
                    continue

                callee_name = None
                if isinstance(child.func, ast.Name):
                    callee_name = child.func.id
                elif isinstance(child.func, ast.Attribute):
                    callee_name = child.func.attr

                if callee_name not in all_names or callee_name == caller_name:
                    continue

                # Check if any argument is a variable assigned earlier.
                args_are_local_vars = any(
                    isinstance(arg, ast.Name) and arg.id in assigned_vars
                    for arg in child.args
                )

                if args_are_local_vars or child.args:
                    edges.append(
                        Edge(
                            src=caller_qid,
                            dst=callee_name,
                            type="data_flow",
                            weight=EDGE_WEIGHTS["data_flow"],
                            confidence=0.7,
                        )
                    )

        return edges


class ActivationEngine:
    """Builds activation graphs from query seeds and the symbol call graph,
    determining which code blocks are relevant to the current user message.

    Provides:
    * ``build_activation_graph(query, project_id)`` — produces an
      ``ActivationGraph`` with scores for every symbol reachable from
      query‑matched seeds, traceback frames, and recent history.
    * ``get_active_code_context(project_id, query)`` — returns a formatted
      string of all active blocks, sorted by relevance, for injection
      when path analysis is disabled.
    * ``rebuild_path_index(project_id)`` — reconstructs the ``PathIndex``
      from the current ``SymbolIndex`` after code changes.
    * ``resolve_dangling_edges(project_id)`` — upgrades provisional cross‑chunk
      call edges when the referenced symbol is later defined.
    * ``speculative_prefetch(project_id, last_activated)`` — pre‑builds
      ``CodePathView`` objects for symbols likely to be needed in the next
      request.
    * ``compute_code_state_hash(project_id)`` — returns a hash of the active
      blocks, used to detect KV‑cache invalidations and staleness.
    * ``invalidate_lightweight_cache(project_id)`` — clears cached context
      and centrality so the next request rebuilds them from scratch.

    Docs 10–13 backported:
        E7 – normalizes PPR scores to [0,1] within the project distribution.
    """

    # ── Q2: PPR cache (nested class) ──────────────────────────────────────────
    class _PPRCache:
        """
        LRU cache for Personalized PageRank score vectors keyed by
        (code_hash, frozenset_of_seed_qids).

        Uses OrderedDict to maintain true LRU order: every get() moves the
        accessed entry to the end; eviction always removes from the front.

        Stores defensive copies of score dicts so that the caller mutating
        their dict after set() cannot corrupt cached entries.
        """

        def __init__(self, maxsize: int = 20) -> None:
            """
            Initialise the cache with a fixed maximum number of entries.

            maxsize: maximum number of (code_hash, seeds) vectors to retain.
            Using an OrderedDict allows O(1) LRU tracking via move_to_end.
            """
            self._cache: "OrderedDict[Tuple[str, frozenset], Dict[str, float]]" = (
                OrderedDict()
            )
            self._maxsize = maxsize
            self._hits = 0
            self._misses = 0

        def get(self, code_hash: str, seeds: frozenset) -> "Optional[Dict[str, float]]":
            """
            Return the cached score vector for (code_hash, seeds), or None on miss.

            Moves the entry to the end of the OrderedDict on every cache hit to
            record it as the most recently used. Without this call, all entries
            age at the same rate regardless of access frequency, making the cache
            degrade from LRU to FIFO.
            """
            key = (code_hash, seeds)
            if key not in self._cache:
                self._misses += 1
                return None

            # Move to end before returning to maintain LRU order
            self._cache.move_to_end(key)
            self._hits += 1
            return self._cache[key]

        def set(
            self,
            code_hash: str,
            seeds: frozenset,
            scores: "Dict[str, float]",
        ) -> None:
            """
            Store a score vector, evicting the LRU entry if the cache is full.

            Stores dict(scores) — a shallow copy — rather than the dict itself.
            Without the copy, any in-place mutation of the caller's scores dict
            after this call (e.g. normalisation in _normalize_ppr_scores, or
            score adjustments in _build_multi_seed_graph) silently corrupts the
            cached entry and causes stale or wrong scores on subsequent cache hits.

            If the key already exists, its value is updated in place and it is
            moved to the end (most recently used position).
            """
            key = (code_hash, seeds)

            if key in self._cache:
                self._cache.move_to_end(key)
                self._cache[key] = dict(scores)
                return

            if len(self._cache) >= self._maxsize:
                # Evict least recently used entry (front of OrderedDict)
                self._cache.popitem(last=False)

            self._cache[key] = dict(scores)

        @property
        def stats(self) -> str:
            """
            Human-readable hit/miss statistics for debug logging.
            """
            total = self._hits + self._misses
            hit_rate = self._hits / total if total > 0 else 0.0
            return (
                f"PPRCache: {len(self._cache)}/{self._maxsize} entries | "
                f"{self._hits} hits / {self._misses} misses "
                f"({hit_rate:.1%} hit rate)"
            )

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref
        self._ppr_cache = self._PPRCache(maxsize=20)

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Active code context (fallback when path analysis is disabled)
    # ═══════════════════════════════════════════════════════════════════════════

    def get_active_code_context(self, project_id: str, user_query: str = "") -> str:
        """Return a formatted string with the currently active code context for the LLM."""
        state = self._f._conversation_state_manager.get(project_id)
        if not state or not state.active_blocks:
            return ""

        now = time.time()
        active = []
        for block in state.active_blocks.values():
            if block.obsolete:
                continue
            if not block.is_active and self._f.valves.track_active_code_age:
                if (
                    now - block.timestamp
                    > self._f.valves.active_code_timeout_minutes * 60
                ):
                    continue
            active.append(block)

        if not active:
            return ""

        recent_window = self._f.valves.recent_activity_window_minutes * 60
        recent_files = {}
        for b in active:
            if b.file_path:
                if (
                    b.file_path not in recent_files
                    or b.timestamp > recent_files[b.file_path]
                ):
                    recent_files[b.file_path] = b.timestamp

        recent_lines = []
        for file_path, ts in recent_files.items():
            age_seconds = now - ts
            if age_seconds <= recent_window:
                minutes_ago = int(age_seconds / 60)
                time_str = f"{minutes_ago} min ago" if minutes_ago > 0 else "just now"
                recent_lines.append(f"- `{file_path}` ({time_str})")

        recent_section = ""
        if recent_lines:
            recent_section = (
                f"## Recent Activity (last {self._f.valves.recent_activity_window_minutes} min)\n"
                + "\n".join(recent_lines)
                + "\n\n"
            )

        mentioned_files = set()
        mentioned_symbols = set()
        if user_query:
            mentioned_files = set(
                re.findall(self._f.valves.file_path_pattern, user_query)
            )
            all_symbol_names = self._f._symbol_index.get_all_names(project_id)
            words = set(re.findall(r"\b[\w-]+\b", user_query))
            mentioned_symbols = all_symbol_names.intersection(words)

        BOOST = 5.0

        def relevance_boost(block: "CodeBlock") -> float:
            score = 0.0
            if block.file_path and block.file_path in mentioned_files:
                score += BOOST
            for sym in block.symbols:
                if sym.name in mentioned_symbols:
                    score += BOOST
                    break
            return score

        boosted_active = []
        for b in active:
            boost = relevance_boost(b)
            boosted_active.append((b, boost))

        boost_priority = self._f.valves.raw_file_priority_boost
        boosted_active.sort(
            key=lambda pair: (
                pair[1] > 0,
                pair[1],
                pair[0].importance_score + (boost_priority if pair[0].is_raw else 0),
            ),
            reverse=True,
        )

        latest_per_file = {}
        for b in active:
            if b.file_path:
                if (
                    b.file_path not in latest_per_file
                    or b.timestamp > latest_per_file[b.file_path].timestamp
                ):
                    latest_per_file[b.file_path] = b
        latest_hashes = {b.hash for b in latest_per_file.values()}

        base_codes = [
            b for b, _ in boosted_active if b.content_type == ContentType.BASE_CODE
        ][: self._f.valves.max_base_code_blocks]
        proposed = [
            b
            for b, _ in boosted_active
            if b.content_type == ContentType.PROPOSED_CHANGE
        ][: self._f.valves.max_proposed_changes]
        committed = [
            b
            for b, _ in boosted_active
            if b.content_type == ContentType.COMMITTED_CHANGE
        ][: self._f.valves.max_committed_changes]
        errors = (
            [b for b, _ in boosted_active if b.content_type == ContentType.ERROR][:3]
            if self._f.valves.preserve_error_context
            else []
        )

        parts = ["## Currently Active Code Context (by importance)\n"]
        parts.insert(
            1,
            "> **Note**: If multiple versions of a file appear, the one marked [LATEST] is the most recent and should be used.\n",
        )
        if recent_section:
            parts.insert(0, recent_section)

        if base_codes:
            parts.append("### Base Code (current work):")
            for b in base_codes:
                is_latest = b.hash in latest_hashes
                tag = " [RELEVANT]" if relevance_boost(b) > 0 else ""
                parts.append(CodeBlockManager.format_block_context(b, is_latest) + tag)

        if proposed:
            parts.append("### Proposed Changes (pending review):")
            for b in proposed:
                is_latest = b.hash in latest_hashes
                tag = " [RELEVANT]" if relevance_boost(b) > 0 else ""
                parts.append(CodeBlockManager.format_block_context(b, is_latest) + tag)

        if committed:
            parts.append("### Recently Committed Changes:")
            for b in committed:
                is_latest = b.hash in latest_hashes
                tag = " [RELEVANT]" if relevance_boost(b) > 0 else ""
                parts.append(CodeBlockManager.format_block_context(b, is_latest) + tag)

        if errors:
            parts.append("### Recent Errors:")
            for b in errors:
                is_latest = b.hash in latest_hashes
                tag = " [RELEVANT]" if relevance_boost(b) > 0 else ""
                parts.append(CodeBlockManager.format_block_context(b, is_latest) + tag)

        psm = self._f._project_state_manager
        used_system = psm.get_last_system_tokens(project_id)

        effective_budget = max(
            4000,
            self._f.valves.context_window_tokens
            - used_system
            - self._f.valves.response_reserve_tokens,
        )
        max_tokens = min(
            self._f.valves.active_context_max_tokens or effective_budget,
            effective_budget,
        )

        if max_tokens > 0 and self._f.tokenizer:
            part_tokens = [len(self._f.tokenizer.encode(p)) for p in parts]
            current_tokens = sum(part_tokens)
            truncation_done = False

            while current_tokens > max_tokens and len(parts) > 2:
                excess = current_tokens - max_tokens

                largest_idx = max(range(len(parts)), key=lambda i: part_tokens[i])
                largest_tok = part_tokens[largest_idx]

                if largest_tok >= excess + 100:
                    target = max(100, largest_tok - excess - 50)
                    truncated_text = self._f._tokens.truncate_text_to_tokens(
                        parts[largest_idx], target
                    )
                    if self._has_open_fence(truncated_text):
                        truncated_text += "\n```"
                    parts[largest_idx] = truncated_text + "\n[...truncado...]"
                    part_tokens[largest_idx] = len(
                        self._f.tokenizer.encode(parts[largest_idx])
                    )
                    current_tokens = sum(part_tokens)
                    truncation_done = True
                else:
                    parts.pop()
                    part_tokens.pop()
                    current_tokens = sum(part_tokens)

            if not truncation_done and current_tokens > max_tokens:
                parts.append(f"[Context truncated to fit token limit ({max_tokens})]")

        return "\n".join(parts)

    @staticmethod
    def _has_open_fence(text: str) -> bool:
        """True if the text ends inside an unclosed fenced code block."""
        inside = False
        for line in text.splitlines():
            if line.strip().startswith("```"):
                inside = not inside
        return inside

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Seed extraction helpers
    # ═══════════════════════════════════════════════════════════════════════════

    async def _extract_query_seeds(
        self, query: str, project_id: str
    ) -> Tuple[List[str], List[str]]:
        """
        Extract seed symbols from the query using exact match, CrossEncoder, and LLM.

        Args:
            query: The user query.
            project_id: Current project identifier.

        Returns:
            A tuple of (exact_matches, partial_matches).
        """
        all_names = self._f._symbol_index.get_all_names(project_id)
        query_words = set(re.findall(r"\b\w+\b", query))

        exact = list(all_names.intersection(query_words))
        partial = []

        if len(exact) < 3 and len(query_words) > 0 and len(all_names) > 0:
            candidates = set()
            for word in query_words:
                if len(word) < 3:
                    continue
                for name in all_names:
                    if word.lower() in name.lower() and name not in exact:
                        candidates.add(name)
                        if len(candidates) >= 20:
                            break
                if len(candidates) >= 20:
                    break

            if candidates:
                pairs = [(query, name) for name in candidates]
                scores = await self._f._commands._predict_cross_encoder(pairs)
                if scores is not None:
                    scored = sorted(
                        zip(candidates, scores), key=lambda x: x[1], reverse=True
                    )
                    ce_threshold = 0.5
                    best = [name for name, sc in scored if sc > ce_threshold]
                    if best:
                        partial = best[:5]
                    else:
                        if len(scored) >= 2:
                            diff = scored[0][1] - scored[1][1]
                            if diff < 0.10:
                                llm_choice = await self._extract_seeds_with_llm(
                                    query, scored[:5], project_id
                                )
                                if llm_choice:
                                    partial = [llm_choice]
                                else:
                                    partial = [scored[0][0]]
                            else:
                                partial = [scored[0][0]]
                        elif scored:
                            partial = [scored[0][0]]

        if len(partial) < 3:
            for word in query_words:
                if len(word) < 4:
                    continue
                for name in all_names:
                    if (
                        word.lower() in name.lower()
                        and name not in exact
                        and name not in partial
                    ):
                        partial.append(name)
                        if len(partial) >= 5:
                            break
                if len(partial) >= 5:
                    break

        return exact, partial

    async def _extract_seeds_with_llm(
        self, query: str, candidates: list, project_id: str
    ) -> Optional[str]:
        """
        Use the LLM to disambiguate between multiple candidate symbols.

        Args:
            query: The user query.
            candidates: List of (symbol_name, score) tuples from CrossEncoder.
            project_id: Current project identifier.

        Returns:
            The selected symbol name, or None.
        """
        if not candidates:
            return None
        scores_str = "\n".join([f"{name}: {score:.2f}" for name, score in candidates])
        prompt = f"""
The CrossEncoder is uncertain between these symbols for the query "{query}".

Scores:
{scores_str}

Choose the symbol that best matches the query's intent.
Output only the symbol name.
"""
        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt="You are a symbol disambiguator. Output only the best matching symbol name.",
            model_override=self._f.valves.summarization_model,
            max_tokens=10,
            temperature=0.0,
            label="seed_disambiguate_llm",
        )
        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)
        return response.strip() if response else None

    def _extract_traceback_seeds(
        self, content: str, project_id: str
    ) -> List[Tuple[str, float]]:
        """
        Extract function names from a traceback with scores proportional
        to their depth in the call stack.
        """
        all_names = self._f._symbol_index.get_all_names(project_id)
        if not all_names:
            return []

        frames: List[str] = []

        # Python traceback
        py_pattern = re.compile(
            r'File\s+"[^"]+",\s+line\s+\d+,\s+in\s+(\w+)',
            re.MULTILINE,
        )
        for match in py_pattern.finditer(content):
            func = match.group(1)
            if func in all_names and func != "<module>":
                frames.append(func)

        # JavaScript / TypeScript
        js_pattern = re.compile(
            r"\bat\s+(\w+)\s*\([^)]*:\d+:\d+\)",
            re.MULTILINE,
        )
        for match in js_pattern.finditer(content):
            func = match.group(1)
            if func in all_names:
                frames.append(func)

        # Java / Kotlin
        java_pattern = re.compile(
            r"\bat\s+[\w.]+\.(\w+)\(\w+\.(?:java|kt):\d+\)",
            re.MULTILINE,
        )
        for match in java_pattern.finditer(content):
            func = match.group(1)
            if func in all_names:
                frames.append(func)

        if not frames:
            return []

        seen: Set[str] = set()
        unique_frames: List[str] = []
        for f in frames:
            if f not in seen:
                seen.add(f)
                unique_frames.append(f)

        n = len(unique_frames)
        results = []
        for i, func_name in enumerate(unique_frames):
            score = 0.5 + 0.5 * (i / max(n - 1, 1))
            specificity = self._compute_node_specificity(func_name, project_id)
            adjusted = min(1.0, score * min(specificity, 1.5))
            results.append((func_name, adjusted))

        self._f._log_debug(
            f"Traceback seeds: {len(results)} frame(s) detected "
            f"({[r[0] for r in results]})"
        )
        return results

    def _compute_node_specificity(self, symbol_name: str, project_id: str) -> float:
        """
        IDF-like specificity of a symbol.
        Symbols appearing in many blocks are less specific (like stop-words).
        Returns a multiplier in [0.1, 3.0] to adjust its weight as a seed.
        """

        all_names = self._f._symbol_index.get_all_names(project_id)
        total = max(len(all_names), 1)
        n_blocks = len(self._f._symbol_index.find_blocks(symbol_name, project_id))
        if n_blocks == 0:
            return 1.0
        specificity = math.log(total / n_blocks) + 1.0
        return max(0.1, min(3.0, specificity))

    def _extract_history_seeds(
        self, messages: Optional[List[dict]], project_id: str, lookback: int = 6
    ) -> Dict[str, float]:
        """
        Extract symbols with high mention frequency in recent messages.
        Returns {symbol_name: boost_score} where boost_score ∈ (0.0, 0.6].
        """
        all_names = self._f._symbol_index.get_all_names(project_id)
        if not all_names or not messages:
            return {}

        recent = messages[-lookback:] if len(messages) > lookback else messages
        mention_counts: Counter = Counter()

        for msg in recent:
            content = msg.get("content", "")
            if not content:
                continue
            words = set(re.findall(r"\b\w+\b", content))
            for sym in all_names.intersection(words):
                mention_counts[sym] += 1

        if not mention_counts:
            return {}

        max_count = max(mention_counts.values())
        return {
            sym: min(
                self._f.valves.history_seeds_max_boost,
                self._f.valves.history_seeds_max_boost * (count / max_count),
            )
            for sym, count in mention_counts.items()
            if count > 0
        }

    async def _prepare_seed_symbols(
        self, query: str, project_id: str, messages: Optional[List[dict]]
    ) -> Tuple[List[str], List[str], List[Tuple[str, float]], Dict[str, float]]:
        """Extract exact, partial, traceback and historical seed symbols."""
        exact_seeds, partial_seeds = await self._extract_query_seeds(query, project_id)
        tb_seeds = (
            self._extract_traceback_seeds(query, project_id)
            if self._f.valves.enable_traceback_activation
            else []
        )
        history_boosts = (
            self._extract_history_seeds(
                messages, project_id, lookback=self._f.valves.history_seeds_lookback
            )
            if (self._f.valves.enable_history_seeds and messages)
            else {}
        )
        return exact_seeds, partial_seeds, tb_seeds, history_boosts

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. PPR computation with caching (Q2)
    # ═══════════════════════════════════════════════════════════════════════════

    def _get_or_compute_ppr_scores(
        self,
        seed_qids: List[str],
        project_id: str,
        code_state_hash: str,
        edges_out: Dict[str, List[Edge]],
        max_steps: int = 20,
        min_score: float = 0.05,
        alpha: float = 0.85,
    ) -> Dict[str, float]:
        """
        Compute PPR scores with LRU caching.

        Q2 fix: Caches results by (code_state_hash, frozenset(seed_qids)).
        Avoids recomputation when the same seeds are used on the same code.

        Args:
            seed_qids: List of qualified symbol ids to seed.
            project_id: Current project identifier.
            code_state_hash: Hash of the code state (cache invalidation key).
            edges_out: Call graph edges (outgoing).
            max_steps: PPR propagation steps.
            min_score: Minimum score to keep.
            alpha: Damping factor.

        Returns:
            Dict[str, float]: qid → PPR score.
        """
        seed_frozenset = frozenset(seed_qids)

        cached = self._ppr_cache.get(code_state_hash, seed_frozenset)
        if cached is not None:
            self._f._log_debug(f"PPR: cache hit ({self._ppr_cache.stats})")
            return cached

        ag = ActivationGraph()

        total_seed_score = len(seed_qids)
        if total_seed_score == 0:
            psm = self._f._project_state_manager
            centrality = psm.get_node_centrality(project_id)
            entry_points = self._f._path_index.find_entry_points(
                self._f._symbol_index, project_id
            )
            if entry_points:
                sorted_eps = sorted(
                    entry_points, key=lambda ep: centrality.get(ep, 0.0), reverse=True
                )
                for sym_name in sorted_eps[:3]:
                    cent_score = centrality.get(sym_name, 0.0)
                    seed_score = 0.2 + 0.2 * cent_score
                    ag.seed([sym_name], initial_score=seed_score)
        else:
            init_score = 1.0 / total_seed_score
            ag.seed(seed_qids, initial_score=init_score)

        ag.propagate(
            edges_out=edges_out,
            max_steps=max_steps,
            min_score=min_score,
            alpha=alpha,
        )

        scores = ag.get_activated_nodes(threshold=min_score)

        self._ppr_cache.set(code_state_hash, seed_frozenset, scores)
        self._f._log_debug(f"PPR: computed and cached ({self._ppr_cache.stats})")

        if hasattr(self._f, "_write_counter") and self._f._write_counter % 50 == 0:
            self._f._log_debug(self._ppr_cache.stats)

        return scores

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Activation graph builders
    # ═══════════════════════════════════════════════════════════════════════════

    def _build_single_seed_graph(
        self,
        exact_seeds: List[str],
        partial_seeds: List[str],
        tb_seeds: List[Tuple[str, float]],
        history_boosts: Dict[str, float],
        edges_out: dict,
        project_id: str,
        inferred_seeds: Optional[Dict[str, float]] = None,
        cached_scores: Optional[Dict[str, float]] = None,
    ) -> "ActivationGraph":
        """
        Build an ActivationGraph by merging all seed vectors into a single
        unified seed set and running one PPR propagation pass.

        Used when the query produces a small, coherent seed set that does not
        benefit from the three-graph weighting strategy of _build_multi_seed_graph.

        When cached_scores is provided the method skips PPR propagation entirely.
        The seed set is still resolved so that source annotation ('seed' vs
        'propagation') is accurate in the returned graph.

        Seed scoring rules:
            exact_seeds     → 0.5 + 0.5 * specificity  (capped at 1.0)
            partial_seeds   → 0.3 + 0.3 * specificity  (capped at 0.6)
            tb_seeds        → original tb_score × 0.4 boost
            inferred_seeds  → score as provided, merged with max()
            history_boosts  → applied after propagation via speculative prefetch

        Steps:
            1.  Resolve unified seed set from all four seed sources.
            2.  Early return from cache when cached_scores is provided.
            3.  Propagate PPR from the unified seed set.
            4.  Apply history boosts to propagated scores.
            5.  Return the populated ActivationGraph.
        """
        symbol_index = self._f._symbol_index

        # -- Step 1: resolve unified seed set --
        ag = ActivationGraph()
        seed_qids: Set[str] = set()

        for sym_name in exact_seeds:
            specificity = self._compute_node_specificity(sym_name, project_id)
            score = min(1.0, 0.5 + 0.5 * min(specificity, 1.0))
            qids = symbol_index.get_qualified_names_for(sym_name, project_id)
            seed_qids.update(qids)
            share = score / len(qids) if qids else 0.0
            for qid in qids:
                ag._activations[qid] = ActivationState(
                    node_id=qid, score=share, depth=0, source="seed"
                )

        for sym_name in partial_seeds:
            specificity = self._compute_node_specificity(sym_name, project_id)
            score = min(0.6, 0.3 + 0.3 * min(specificity, 1.0))
            qids = symbol_index.get_qualified_names_for(sym_name, project_id)
            seed_qids.update(qids)
            share = score / len(qids) if qids else 0.0
            for qid in qids:
                existing = ag._activations.get(qid)
                ag._activations[qid] = ActivationState(
                    node_id=qid,
                    score=max(existing.score if existing else 0.0, share),
                    depth=0,
                    source="seed",
                )

        for sym_name, tb_score in tb_seeds:
            qids = symbol_index.get_qualified_names_for(sym_name, project_id)
            seed_qids.update(qids)
            share = tb_score / len(qids) if qids else 0.0
            for qid in qids:
                existing = ag._activations.get(qid)
                ag._activations[qid] = ActivationState(
                    node_id=qid,
                    score=min(1.0, (existing.score if existing else 0.0) + share * 0.4),
                    depth=0,
                    source="seed",
                )

        for qid, inf_score in (inferred_seeds or {}).items():
            seed_qids.add(qid)
            existing = ag._activations.get(qid)
            ag._activations[qid] = ActivationState(
                node_id=qid,
                score=min(1.0, max(existing.score if existing else 0.0, inf_score)),
                depth=0,
                source="seed",
            )

        # -- Step 2: early return from cache --
        # Avoids the full PPR propagation pass (O(V·E·steps)) on cache hit.
        if cached_scores is not None:
            ag_cached = ActivationGraph()
            for qid, score in cached_scores.items():
                if score >= 0.01:
                    source = "seed" if qid in seed_qids else "propagation"
                    ag_cached._activations[qid] = ActivationState(
                        node_id=qid, score=score, depth=0, source=source
                    )
            self._f._log_debug(
                f"PPR single-seed: loaded {len(cached_scores)} scores from cache"
            )
            return ag_cached

        if not ag._activations:
            self._f._log_debug(
                f"_build_single_seed_graph: no seeds resolved for '{project_id}'"
            )
            return ag

        # -- Step 3: PPR propagation --
        ag.propagate(
            edges_out=edges_out,
            max_steps=20,
            min_score=0.03,
            alpha=self._f.valves.ppr_alpha,
        )

        # -- Step 4: apply history boosts --
        for sym_name, boost in (history_boosts or {}).items():
            qids = symbol_index.get_qualified_names_for(sym_name, project_id)
            for qid in qids:
                existing = ag._activations.get(qid)
                if existing:
                    existing.score = min(1.0, existing.score + boost * 0.2)
                else:
                    ag._activations[qid] = ActivationState(
                        node_id=qid, score=boost * 0.2, depth=3, source="propagation"
                    )

        # -- Step 5: return --
        activated_count = len(ag.get_activated_nodes(threshold=0.05))
        self._f._log_debug(
            f"Single-seed ActivationGraph: {activated_count} nodes activated "
            f"from {len(seed_qids)} seed qid(s)"
        )
        return ag

    def _build_multi_seed_graph(
        self,
        exact_seeds: List[str],
        partial_seeds: List[str],
        tb_seeds: List[Tuple[str, float]],
        history_boosts: Dict[str, float],
        edges_out: dict,
        project_id: str,
        inferred_seeds: Optional[Dict[str, float]] = None,
        cached_scores: Optional[Dict[str, float]] = None,
    ) -> "ActivationGraph":
        """
        Build an ActivationGraph by combining three independent seed vectors
        with configurable weights (lexical, structural, historical).

        When cached_scores is provided, the method skips all three PPR propagation
        passes. The seed set is still resolved so that the source annotation
        ('seed' vs 'propagation') on each node is accurate in the returned graph.

        Weight configuration valves:
            multi_seed_weight_lexical    — query-term and inferred seeds
            multi_seed_weight_structural — entry-point seeds from PathIndex views
            multi_seed_weight_historical — mention-frequency seeds from history
        """
        w_lex = self._f.valves.multi_seed_weight_lexical
        w_str = self._f.valves.multi_seed_weight_structural
        w_his = self._f.valves.multi_seed_weight_historical
        symbol_index = self._f._symbol_index

        # -- Step 1: resolve lexical seed set (needed even on cache hit for
        #            source annotation) --
        ag_lex = ActivationGraph()
        lexical_seed_qids: Set[str] = set()

        for sym_name in exact_seeds:
            specificity = self._compute_node_specificity(sym_name, project_id)
            score = min(1.0, 0.5 + 0.5 * min(specificity, 1.0))
            qids = symbol_index.get_qualified_names_for(sym_name, project_id)
            lexical_seed_qids.update(qids)
            share = score / len(qids) if qids else 0.0
            for qid in qids:
                ag_lex._activations[qid] = ActivationState(
                    node_id=qid, score=share, depth=0, source="seed"
                )

        for sym_name in partial_seeds:
            specificity = self._compute_node_specificity(sym_name, project_id)
            score = min(0.6, 0.3 + 0.3 * min(specificity, 1.0))
            qids = symbol_index.get_qualified_names_for(sym_name, project_id)
            lexical_seed_qids.update(qids)
            share = score / len(qids) if qids else 0.0
            for qid in qids:
                ag_lex._activations[qid] = ActivationState(
                    node_id=qid, score=share, depth=0, source="seed"
                )

        for sym_name, tb_score in tb_seeds:
            qids = symbol_index.get_qualified_names_for(sym_name, project_id)
            lexical_seed_qids.update(qids)
            share = tb_score / len(qids) if qids else 0.0
            for qid in qids:
                existing = ag_lex._activations.get(qid)
                ag_lex._activations[qid] = ActivationState(
                    node_id=qid,
                    score=min(1.0, (existing.score if existing else 0.0) + share * 0.4),
                    depth=0,
                    source="seed",
                )

        for qid, inf_score in (inferred_seeds or {}).items():
            lexical_seed_qids.add(qid)
            existing = ag_lex._activations.get(qid)
            ag_lex._activations[qid] = ActivationState(
                node_id=qid,
                score=min(1.0, max(existing.score if existing else 0.0, inf_score)),
                depth=0,
                source="seed",
            )

        # -- Step 2: early return from cache --
        # Avoids three PPR propagation passes (O(V·E·steps) each) on cache hit.
        if cached_scores is not None:
            ag_final = ActivationGraph()
            for qid, score in cached_scores.items():
                if score >= 0.01:
                    source = "seed" if qid in lexical_seed_qids else "propagation"
                    ag_final._activations[qid] = ActivationState(
                        node_id=qid,
                        score=score,
                        depth=0,
                        source=source,
                    )
            self._f._log_debug(
                f"PPR multi-seed: loaded {len(cached_scores)} scores from cache"
            )
            return ag_final

        # -- Step 3: propagate lexical graph --
        if ag_lex._activations:
            ag_lex.propagate(
                edges_out=edges_out,
                max_steps=20,
                min_score=0.03,
                alpha=self._f.valves.ppr_alpha,
            )

        # -- Step 4: build and propagate structural graph --
        ag_str = ActivationGraph()
        structural_seeds: Set[str] = set()
        for view in self._f._path_index.get_all(project_id):
            for lex_seed in lexical_seed_qids:
                if lex_seed in view.induced_nodes:
                    structural_seeds.add(view.entry_point)
                    break
        if structural_seeds:
            for sym_name in structural_seeds:
                specificity = self._compute_node_specificity(sym_name, project_id)
                score = min(0.8, 0.5 * min(specificity, 1.4))
                qids = symbol_index.get_qualified_names_for(sym_name, project_id)
                share = score / len(qids) if qids else 0.0
                for qid in qids:
                    ag_str._activations[qid] = ActivationState(
                        node_id=qid, score=share, depth=0, source="seed"
                    )
            ag_str.propagate(
                edges_out=edges_out,
                max_steps=20,
                min_score=0.03,
                alpha=self._f.valves.ppr_alpha,
            )

        # -- Step 5: build and propagate historical graph --
        ag_his = ActivationGraph()
        if history_boosts:
            for sym_name, boost in history_boosts.items():
                qids = symbol_index.get_qualified_names_for(sym_name, project_id)
                share = boost / len(qids) if qids else 0.0
                for qid in qids:
                    ag_his._activations[qid] = ActivationState(
                        node_id=qid, score=share, depth=0, source="seed"
                    )
            ag_his.propagate(
                edges_out=edges_out,
                max_steps=20,
                min_score=0.03,
                alpha=self._f.valves.ppr_alpha,
            )

        # -- Step 6: combine the three graphs --
        all_activated = (
            set(ag_lex.get_activated_nodes(0.01).keys())
            | set(ag_str.get_activated_nodes(0.01).keys())
            | set(ag_his.get_activated_nodes(0.01).keys())
        )

        ag_final = ActivationGraph()
        if not all_activated:
            psm = self._f._project_state_manager
            centrality = psm.get_node_centrality(project_id)
            entry_points = self._f._path_index.find_entry_points(
                symbol_index, project_id
            )
            if entry_points:
                sorted_eps = sorted(
                    entry_points,
                    key=lambda ep: centrality.get(ep, 0.0),
                    reverse=True,
                )
                for sym_name in sorted_eps[:3]:
                    cent_score = centrality.get(sym_name, 0.0)
                    seed_score = 0.2 + 0.2 * cent_score
                    ag_final._activations[sym_name] = ActivationState(
                        node_id=sym_name, score=seed_score, depth=0, source="seed"
                    )
        else:
            for node in all_activated:
                combined = (
                    w_lex * ag_lex.get_score(node)
                    + w_str * ag_str.get_score(node)
                    + w_his * ag_his.get_score(node)
                )
                if combined >= 0.01:
                    source = "seed" if node in lexical_seed_qids else "propagation"
                    depth = min(
                        ag_lex._activations.get(
                            node,
                            ActivationState(
                                node_id=node, score=0, depth=99, source="propagation"
                            ),
                        ).depth,
                        ag_str._activations.get(
                            node,
                            ActivationState(
                                node_id=node, score=0, depth=99, source="propagation"
                            ),
                        ).depth,
                    )
                    ag_final._activations[node] = ActivationState(
                        node_id=node,
                        score=min(1.0, combined),
                        depth=depth,
                        source=source,
                    )

        activated_count = len(ag_final.get_activated_nodes(threshold=0.05))
        self._f._log_debug(
            f"Multi-seed ActivationGraph: {activated_count} nodes activated "
            f"(lex={len(ag_lex.get_activated_nodes(0.01))}, "
            f"str={len(ag_str.get_activated_nodes(0.01))}, "
            f"his={len(ag_his.get_activated_nodes(0.01))})"
        )
        return ag_final

    def _store_activation_scores(self, ag: ActivationGraph, project_id: str) -> None:
        """Save activation scores for speculative prefetch and LOD tracking."""
        activated = ag.get_activated_nodes(
            threshold=self._f.valves.path_activation_threshold
        )
        if not hasattr(self._f, "_last_activation_scores"):
            self._f._last_activation_scores: Dict[str, Dict[str, float]] = {}
        self._f._last_activation_scores[project_id] = activated

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Main entry point: build_activation_graph
    # ═══════════════════════════════════════════════════════════════════════════

    async def build_activation_graph(
        self,
        query: str,
        project_id: str,
        max_propagation_steps: int = 4,
        messages: Optional[List[dict]] = None,
        inferred_seeds: Optional[Dict[str, float]] = None,
        persist: bool = True,
    ) -> "ActivationGraph":
        """
        Build an ActivationGraph combining up to three independent seed vectors.

        Args:
            query: The user query string.
            project_id: Current project identifier.
            max_propagation_steps: Steps for PPR propagation.
            messages: Recent conversation messages (for historical seeds).
            inferred_seeds: Optional {qid: score} from LLM‑guided inference.
            persist: If False, activation scores are NOT written to
                _last_activation_scores and do NOT affect pstate.
                Used by MetacognitiveReasoningEngine.reason_per_focus()
                for per-question volatile activation (FocalReasoning).

        Returns:
            ActivationGraph with propagated scores.
        """
        self._f._log_debug(
            f"[PPR] build_activation_graph: query='{query[:100]}', "
            f"project_id='{project_id}', "
            f"max_steps={max_propagation_steps}, "
            f"has_messages={bool(messages)}, "
            f"persist={persist}"
        )

        edges_out = self._f._symbol_index.get_all_edges_out(project_id)

        # ------------------------------------------------------------------
        # Step 1: Extract seeds from query, traceback, and history.
        # ------------------------------------------------------------------
        exact_seeds, partial_seeds, tb_seeds, history_boosts = (
            await self._prepare_seed_symbols(query, project_id, messages)
        )

        self._f._log_debug(
            f"[PPR] Seeds extracted: exact={len(exact_seeds)} ({exact_seeds[:5] if exact_seeds else 'none'}), "
            f"partial={len(partial_seeds)} ({partial_seeds[:5] if partial_seeds else 'none'}), "
            f"tb={len(tb_seeds)}, history={len(history_boosts)}"
        )

        seed_qids: List[str] = []
        all_qids = self._f._symbol_index.get_all_qualified_names(project_id)

        for sym in exact_seeds:
            qids = self._f._symbol_index.get_qualified_names_for(sym, project_id)
            seed_qids.extend(qids)
        for sym in partial_seeds:
            qids = self._f._symbol_index.get_qualified_names_for(sym, project_id)
            seed_qids.extend(qids)
        for sym, _ in tb_seeds:
            qids = self._f._symbol_index.get_qualified_names_for(sym, project_id)
            seed_qids.extend(qids)
        if inferred_seeds:
            seed_qids.extend(inferred_seeds.keys())
        seed_qids = list(set(seed_qids) & set(all_qids))

        # ------------------------------------------------------------------
        # Step 2: Get or compute PPR scores (with cache).
        # ------------------------------------------------------------------
        code_state_hash = self.compute_code_state_hash(project_id)

        cached_scores = self._get_or_compute_ppr_scores(
            seed_qids=seed_qids,
            project_id=project_id,
            code_state_hash=code_state_hash,
            edges_out=edges_out,
            max_steps=max_propagation_steps,
            min_score=0.05,
            alpha=self._f.valves.ppr_alpha,
        )

        # ------------------------------------------------------------------
        # Step 3: Build the activation graph (single or multi-seed).
        # ------------------------------------------------------------------
        _inferred = inferred_seeds or {}
        if not self._f.valves.enable_multi_seed_activation:
            self._f._log_debug("[PPR] Using SINGLE-SEED activation mode")
            ag = self._build_single_seed_graph(
                exact_seeds,
                partial_seeds,
                tb_seeds,
                history_boosts,
                edges_out,
                project_id,
                _inferred,
                cached_scores=cached_scores,
            )
        else:
            self._f._log_debug("[PPR] Using MULTI-SEED activation mode")
            ag = self._build_multi_seed_graph(
                exact_seeds,
                partial_seeds,
                tb_seeds,
                history_boosts,
                edges_out,
                project_id,
                _inferred,
                cached_scores=cached_scores,
            )

        # Persist activation scores only when not running in volatile mode.
        # FocalReasoning uses persist=False to avoid contaminating the main
        # activation state with per-question intermediate activations.
        if persist:
            self._store_activation_scores(ag, project_id)

        # ------------------------------------------------------------------
        # Step 4: Get activated nodes and normalize scores.
        # ------------------------------------------------------------------
        activated = ag.get_activated_nodes(
            threshold=self._f.valves.path_activation_threshold
        )
        activated = self._normalize_ppr_scores(activated)

        self._f._log_debug(
            f"[PPR] Activation complete: {len(activated)} nodes activated "
            f"(threshold={self._f.valves.path_activation_threshold})"
        )

        # ------------------------------------------------------------------
        # Step 5: Log score distribution for debugging (Point 6).
        # ------------------------------------------------------------------
        if self._f.valves.debug and activated:
            sorted_scores = sorted(activated.values(), reverse=True)
            if sorted_scores:
                p50 = sorted_scores[len(sorted_scores) // 2]
                self._f._log_debug(
                    f"[PPR] score dist: max={sorted_scores[0]:.3f}, "
                    f"p50={p50:.3f}, "
                    f"min={sorted_scores[-1]:.3f}, "
                    f"above={sum(1 for s in activated.values() if s >= self._f.valves.path_activation_threshold)}/{len(activated)}"
                )

        return ag

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Path index & cross‑chunk edges
    # ═══════════════════════════════════════════════════════════════════════════

    async def _build_view_from_activation(
        self, entry_point: str, ag: ActivationGraph, project_id: str
    ) -> Optional[CodePathView]:
        """Build a CodePathView from an ActivationGraph and register it in PathIndex."""
        edges_out = self._f._symbol_index.get_all_edges_out(project_id)
        edges_in_map: Dict[str, List[Edge]] = defaultdict(list)
        for sym, edge_list in edges_out.items():
            for e in edge_list:
                edges_in_map[e.dst].append(e)

        extractor = SubgraphExtractor(
            activation_threshold=self._f.valves.path_activation_threshold,
            expand_hops=1,
        )
        induced_nodes_set, induced_edges = extractor.extract(
            ag, edges_out, edges_in_map
        )

        if not induced_nodes_set:
            return None

        induced_nodes_scored = {node: ag.get_score(node) for node in induced_nodes_set}

        path_id = hashlib.md5(
            f"{entry_point}|{'|'.join(sorted(induced_nodes_set))}".encode()
        ).hexdigest()[:16]

        existing = self._f._path_index.get(path_id, project_id)
        structural_hash = self.compute_structural_hash(induced_nodes_set, project_id)
        call_graph_hash = self.compute_call_graph_hash(induced_nodes_set, project_id)

        view = CodePathView(
            path_id=path_id,
            entry_point=entry_point,
            seed_nodes=[entry_point],
            induced_nodes=induced_nodes_scored,
            induced_edges=induced_edges,
            activation_score=ag.aggregate_path_score(list(induced_nodes_set)),
            structural_hash=structural_hash,
            call_graph_hash=call_graph_hash,
        )

        if (
            existing
            and not existing.is_stale(structural_hash, call_graph_hash)
            and existing.business_label
        ):
            view.business_label = existing.business_label
            view.summary = existing.summary
            view.label_confidence = existing.label_confidence

        self._f._path_index.add(view, project_id)
        return view

    async def rebuild_path_index(self, project_id: str) -> None:
        """
        Reconstruct PathIndex from SymbolIndex for all entry points.

        This method rebuilds the in-memory path index by iterating over all
        entry points (symbols with no callers) and building a CodePathView
        for each one. It also precomputes centrality if enabled.

        Args:
            project_id: Current project identifier.
        """
        # ------------------------------------------------------------------
        # Step 1: Get the conversation state and check for active blocks.
        # ------------------------------------------------------------------
        state = self._f._conversation_state_manager.get(project_id)
        if not state or not state.active_blocks:
            return

        # ------------------------------------------------------------------
        # Step 2: Find all entry points (symbols with no known callers).
        # ------------------------------------------------------------------
        entry_points = self._f._path_index.find_entry_points(
            self._f._symbol_index, project_id
        )

        # ------------------------------------------------------------------
        # Step 3: Build a CodePathView for each entry point.
        # ------------------------------------------------------------------
        for ep in entry_points:
            ag = await self.build_activation_graph(ep, project_id)
            await self._build_view_from_activation(ep, ag, project_id)

        # ------------------------------------------------------------------
        # Step 4: Precompute centrality if enabled.
        # ------------------------------------------------------------------
        if self._f.valves.enable_centrality_prior:
            psm = self._f._project_state_manager
            psm.set_node_centrality(
                project_id,
                self._f._symbol_index.precompute_centrality(project_id),
            )

    async def resolve_dangling_edges(self, project_id: str) -> int:
        """
        Resolve cross-chunk symbol references.

        A 'dangling edge' is an edge whose destination is referenced in the
        call graph but has no code block yet. When a new chunk defines that
        symbol, the edge confidence is raised from 0.3 (provisional) to 1.0.

        Conversely, edges pointing to symbols that are referenced but not
        defined are marked with confidence 0.3.

        Returns the number of edges resolved.
        """
        all_names = self._f._symbol_index.get_all_names(project_id)
        resolved = 0

        for sym_name in all_names:
            has_definition = bool(
                self._f._symbol_index.find_blocks(sym_name, project_id)
            )
            edges_in = self._f._symbol_index.get_edges_in(sym_name, project_id)

            for edge in edges_in:
                if has_definition and edge.confidence < 1.0:
                    edge.confidence = 1.0
                    resolved += 1
                elif not has_definition and edge.confidence == 1.0:
                    edge.confidence = 0.3

        if resolved > 0:
            self._f._log_debug(
                f"Cross-chunk resolution: {resolved} edge(s) resolved "
                f"(references confirmed with definitions)"
            )
        return resolved

    # ═══════════════════════════════════════════════════════════════════════════
    # 7. Speculative prefetch
    # ═══════════════════════════════════════════════════════════════════════════

    async def speculative_prefetch(
        self,
        project_id: str,
        last_activated: dict,
    ) -> None:
        """
        Pre‑build CodePathViews for symbols likely to be relevant in the next query.

        Prediction: high‑confidence direct callees of the top‑N activated symbols.
        """
        if not self._f.valves.enable_speculative_prefetch:
            return
        if not last_activated:
            return

        top_syms = sorted(last_activated, key=last_activated.get, reverse=True)[:3]

        prefetch_candidates: Set[str] = set()
        for sym in top_syms:
            for edge in self._f._symbol_index.get_edges_out(sym, project_id):
                if (
                    edge.type == "calls"
                    and edge.effective_weight() >= 0.7
                    and edge.dst not in last_activated
                ):
                    prefetch_candidates.add(edge.dst)

        if not prefetch_candidates:
            return

        candidates = list(prefetch_candidates)[
            : self._f.valves.speculative_prefetch_max
        ]
        self._f._log_debug(
            f"Speculative prefetch: pre-building {len(candidates)} CodePathView(s) "
            f"for next likely query"
        )

        edges_out = self._f._symbol_index.get_all_edges_out(project_id)
        for sym_name in candidates:
            if not self._f._symbol_index.find_blocks(sym_name, project_id):
                continue
            qids = self._f._symbol_index.get_qualified_names_for(sym_name, project_id)
            ag = ActivationGraph()
            ag.seed(list(qids), initial_score=1.0)
            ag.propagate(edges_out, max_steps=2, min_score=0.1)
            await self._build_view_from_activation(sym_name, ag, project_id)

    async def speculative_prefetch_background(
        self,
        project_id: str,
        last_activated: dict,
        stop_event: asyncio.Event = None,
    ) -> None:
        """
        Pre-warm the PPR cache for symbols likely to be activated on the next turn.

        For each hub-tier symbol that was highly activated this turn, computes
        an activation graph as if that symbol were the sole entry point on the
        next query, and stores the result in _PPRCache. This turns a cache miss
        at the start of the next inlet into a cache hit.

        Takes a defensive copy of last_activated immediately to avoid
        RuntimeError when the main inlet path updates the same dict concurrently.

        Checks stop_event between each PPR computation so the background task
        can be cleanly cancelled during server shutdown or plugin reload without
        waiting for the entire prefetch batch to finish.

        Steps:
            1.  Defensive copy of last_activated; early exit if empty.
            2.  Identify prefetch candidates: top-N activated hub symbols.
            3.  Compute code_state_hash once for cache key.
            4.  For each candidate: check stop_event, compute PPR, cache result.
        """
        # -- Step 1: defensive copy + stop check --
        if stop_event and stop_event.is_set():
            return

        activated_snapshot: Dict[str, float] = dict(last_activated)
        if not activated_snapshot:
            return

        # -- Step 2: identify prefetch candidates --
        psm = self._f._project_state_manager
        centrality = psm.get_node_centrality(project_id)
        hub_qids = set(psm.get_hub_tier_qids(project_id))
        top_n = getattr(self._f.valves, "speculative_prefetch_top_n", 3)
        min_score = getattr(self._f.valves, "speculative_prefetch_min_score", 0.3)

        candidates: List[Tuple[str, float]] = sorted(
            [
                (qid, score)
                for qid, score in activated_snapshot.items()
                if score >= min_score and qid in hub_qids
            ],
            key=lambda x: x[1],
            reverse=True,
        )[:top_n]

        if not candidates:
            self._f._log_debug(
                f"speculative_prefetch_background: no candidates for '{project_id}'"
            )
            return

        # -- Step 3: code state hash (stable across the batch) --
        code_state_hash = self.compute_code_state_hash(project_id)
        if not code_state_hash:
            return

        edges_out = self._f._symbol_index.get_all_edges_out(project_id)

        self._f._log_debug(
            f"speculative_prefetch_background: prefetching {len(candidates)} "
            f"candidate(s) for '{project_id}'"
        )

        # -- Step 4: compute and cache PPR per candidate --
        for qid, score in candidates:
            # Check stop_event BEFORE each PPR computation, not just once at start.
            if stop_event and stop_event.is_set():
                self._f._log_debug(
                    f"speculative_prefetch_background: stop_event set, "
                    f"aborting remaining {len(candidates)} prefetch(es)"
                )
                return

            existing = self._ppr_cache.get(code_state_hash, frozenset([qid]))
            if existing is not None:
                self._f._log_debug(
                    f"speculative_prefetch_background: cache hit for {qid[:30]}, skipping"
                )
                continue

            try:
                ppr_scores = self._get_or_compute_ppr_scores(
                    seed_qids=[qid],
                    project_id=project_id,
                    code_state_hash=code_state_hash,
                    edges_out=edges_out,
                    max_steps=15,
                    min_score=0.05,
                    alpha=self._f.valves.ppr_alpha,
                )
                if ppr_scores:
                    self._ppr_cache.set(code_state_hash, frozenset([qid]), ppr_scores)
                    self._f._log_debug(
                        f"speculative_prefetch_background: cached PPR for "
                        f"'{qid[:30]}' ({len(ppr_scores)} nodes)"
                    )
            except asyncio.CancelledError:
                raise
            except Exception as e:
                self._f._log_debug(
                    f"speculative_prefetch_background: PPR failed for "
                    f"'{qid[:30]}': {type(e).__name__}: {e}"
                )

            # Yield to the event loop between PPR computations so other
            # coroutines (inlet, docstring loop) are not starved.
            await asyncio.sleep(0)

    # ═══════════════════════════════════════════════════════════════════════════
    # 8. Hash utilities
    # ═══════════════════════════════════════════════════════════════════════════

    def compute_structural_hash(
        self, symbol_names: Iterable[str], project_id: str
    ) -> str:
        """Hash of the symbols' content blocks (changes when code changes)."""
        state = self._f._conversation_state_manager.get(project_id)
        hashes = []
        for name in sorted(symbol_names):
            for bh in sorted(self._f._symbol_index.find_blocks(name, project_id)):
                hashes.append(bh)
        return hashlib.md5("|".join(hashes).encode()).hexdigest()[:16] if hashes else ""

    def compute_call_graph_hash(
        self, symbol_names: Iterable[str], project_id: str
    ) -> str:
        """Hash of the call relationships (changes when the graph changes)."""
        edge_strs = []
        for name in sorted(symbol_names):
            for edge in self._f._symbol_index.get_edges_out(name, project_id):
                edge_strs.append(f"{edge.src}:{edge.type}:{edge.dst}")
        return (
            hashlib.md5("|".join(sorted(edge_strs)).encode()).hexdigest()[:16]
            if edge_strs
            else ""
        )

    def compute_code_state_hash(self, project_id: str) -> str:
        """Return a hash that changes when the set of active blocks changes."""
        pstate = self._f._project_state_manager.get_pstate(project_id)
        cached = pstate.get("cached_code_state_hash")
        if cached is not None:
            return cached
        state = self._f._conversation_state_manager.get(project_id)
        h = self._compute_code_state_hash_from_state(state)
        pstate["cached_code_state_hash"] = h
        return h

    def _compute_code_state_hash_from_state(self, state: dict) -> str:
        if not state or not state.active_blocks:
            return ""
        sorted_hashes = sorted(
            h for h, b in state.active_blocks.items() if not b.obsolete
        )
        return hashlib.md5("|".join(sorted_hashes).encode()).hexdigest()[:16]

    def _normalize_ppr_scores(
        self,
        raw_scores: Dict[str, float],
    ) -> Dict[str, float]:
        """Normalize PPR scores to [0, 1] within the project's distribution.

        E7: prevents threshold miscalibration across projects of different sizes.
        After normalization, lod2_threshold=0.10 means "top 10% by PPR rank",
        regardless of how many symbols the project has.
        """
        if not raw_scores:
            return raw_scores
        min_s = min(raw_scores.values())
        max_s = max(raw_scores.values())
        if max_s <= min_s:
            return {qid: 0.5 for qid in raw_scores}
        return {
            qid: (score - min_s) / (max_s - min_s) for qid, score in raw_scores.items()
        }

    def compute_context_hash(self, messages: list) -> str:
        """Hash of system message content, used for response cache keying."""
        if not self._f.valves.response_cache_include_context_hash:
            return ""
        sys_msgs = [m for m in messages if m.get("role") == "system"]
        context_str = "\n".join([m.get("content", "") for m in sys_msgs])
        return hashlib.md5(context_str.encode()).hexdigest()[:16]

    # ═══════════════════════════════════════════════════════════════════════════
    # 9. Inactive block candidates & cache invalidation
    # ═══════════════════════════════════════════════════════════════════════════

    def get_inactive_block_candidates(self, project_id: str) -> list:
        """
        Return block hashes that haven't been mentioned in the last
        `cleanup_inactive_threshold_messages` messages, excluding pinned,
        obsolete, and content types listed in `cleanup_excluded_content_types`.
        """
        state = self._f._conversation_state_manager.get(project_id)
        if not state or not state.active_blocks:
            return []
        threshold = self._f.valves.cleanup_inactive_threshold_messages
        excluded_types = set(self._f.valves.cleanup_excluded_content_types)
        current_msg_idx = state.message_count
        candidates = []
        for h, block in state.active_blocks.items():
            if block.pinned or block.obsolete:
                continue
            if block.content_type.value in excluded_types:
                continue
            last_idx = block.last_mentioned_msg_idx
            if last_idx is None:
                last_idx = current_msg_idx
            if current_msg_idx - last_idx > threshold:
                candidates.append(h)
        return candidates

    def invalidate_lightweight_cache(self, project_id: str) -> None:
        """Clear cached lightweight context and centrality so the next request rebuilds them."""
        psm = self._f._project_state_manager
        pstate = psm.get_pstate(project_id)
        pstate["cached_lightweight_context"] = ""
        pstate["cached_code_state_hash"] = None
        psm.set_node_centrality(project_id, {})

    # ═══════════════════════════════════════════════════════════════════════════
    # 10. Static evidence (for scientific CoT)
    # ═══════════════════════════════════════════════════════════════════════════

    def _gather_static_evidence(
        self, hypothesis_text: str, project_id: str
    ) -> "StaticEvidence":
        """
        Delegated to MetacognitiveReasoningEngine.gather_evidence().

        Kept here for backward compatibility — existing call sites in
        ReasoningEngine continue to work unchanged until Fase 3 converts
        generate_scientific_reasoning_L3 into a thin wrapper that calls
        compete_hypotheses() directly.
        """
        return self._f._meta_reasoning.gather_evidence(hypothesis_text, project_id)


class MetacognitiveReasoningEngine:
    """
    Operates above ReasoningEngine and ActivationEngine.
    Decides WHAT to reason about, HOW to structure reasoning,
    and provides epistemic tools that reasoning methods can use.

    Temporal hierarchy (H5):
    ┌─ ITERATION LEVEL (PID/OODA) ──────────────────────────────────────┐
    │  stagnation_detection on obj_score_history (deterministic)         │
    │  _build_refinement_constraints (PID output → LLM input)            │
    │  _generate_divergent_hypotheses (escape from local optima)         │
    └────────────────────────────────────────────────────────────────────┘
    ┌─ TURN LEVEL (Scientific method + Active Learning) ─────────────────┐
    │  design_critical_experiment → generate_predictions                  │
    │  gather_evidence → Active Learning → is_falsified                   │
    │  compute_weighted_score → _compute_epistemic_uncertainty            │
    └────────────────────────────────────────────────────────────────────┘
    ┌─ CONVERSATION LEVEL (Dialectical — H6) ────────────────────────────┐
    │  experimentum_crucis (tiebreaker)                                   │
    │  peer_review (antithesis) BEFORE delimit_scope (synthesis)          │
    └────────────────────────────────────────────────────────────────────┘
    ┌─ PROJECT LEVEL (Bayesian — H5) ────────────────────────────────────┐
    │  _debrief_competition → _performance_history                        │
    │  _get_adaptive_strategy → constraints for next competition          │
    └────────────────────────────────────────────────────────────────────┘

    Key epistemic principle:
    The LLM never evaluates itself. The SymbolGraph is the ground truth
    mirror. All metacognitive signals are derived from deterministic
    structural data — never from LLM introspection.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref
        # ExperimentDesign cache keyed by hypothesis MD5.
        # Avoids re-designing on iterations where hypothesis text hasn't changed.
        self._design_cache: Dict[str, "ExperimentDesign"] = {}
        # CompetitionRecord history keyed by project_id.
        # Enables project-level strategy adaptation.
        self._performance_history: Dict[str, List["CompetitionRecord"]] = {}

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Epistemic toolkit — evidence collection and analysis
    # ═══════════════════════════════════════════════════════════════════════

    def gather_evidence(self, hypothesis: str, project_id: str) -> "StaticEvidence":
        """
        Gather deterministic structural evidence for a hypothesis.

        Migrated from ActivationEngine._gather_static_evidence.
        No LLM. No GPU. Instant.

        Called N × M times per competition turn (N hypotheses × M iterations +
        Active Learning re-gathers). Must be fully side-effect free.
        mark_stale_for_symbol intentionally omitted — path staleness is
        managed by the main activation pipeline, not by evidence gathering.
        """
        _EMPTY = StaticEvidence(
            symbols_found={},
            call_relations_valid={},
            recent_changes=[],
            entry_points_mentioned=[],
            path_memberships={},
            data_flow_upstream={},
            objective_score=0.5,
        )

        all_names = self._f._symbol_index.get_all_names(project_id)
        state = self._f._conversation_state_manager.get(project_id)

        # Guard: state may be None on first turn or fresh project
        if state is None:
            self._f._log_debug(
                "gather_evidence: state is None for project_id="
                f"'{project_id}' — returning empty evidence"
            )
            return _EMPTY

        words = set(re.findall(r"\b\w+\b", hypothesis))
        mentioned = all_names.intersection(words)

        symbols_found = {
            name: bool(self._f._symbol_index.find_blocks(name, project_id))
            for name in mentioned
        }

        call_patterns = re.findall(
            r"`?(\w+)`?\s+(?:calls?|invokes?|uses?|depends on)\s+`?(\w+)`?",
            hypothesis,
            re.IGNORECASE,
        )
        call_relations_valid = {}
        for caller, callee in call_patterns:
            if caller not in all_names or callee not in all_names:
                continue
            key = f"{caller}_calls_{callee}"
            caller_edges = self._f._symbol_index.get_edges_out(caller, project_id)
            verified = any(
                e.dst == callee and e.type in ("calls", "reads", "writes")
                for e in caller_edges
            )
            call_relations_valid[key] = verified

        now = time.time()
        recent_window = 3600
        recent_changes = []
        for name in mentioned:
            for bh in self._f._symbol_index.find_blocks(name, project_id):
                block = state.active_blocks.get(bh)
                if block is not None and (now - block.timestamp) < recent_window:
                    recent_changes.append(name)
                    break

        all_views = self._f._path_index.get_all(project_id)
        entry_points_mentioned = [
            v.entry_point for v in all_views if v.entry_point in mentioned
        ]

        # Side-effect free: read path memberships without marking stale.
        # mark_stale_for_symbol is intentionally omitted — gather_evidence
        # is called N×M times per competition and must not degrade PathIndex.
        path_memberships: Dict[str, List[str]] = {}

        data_flow_upstream: Dict[str, List[str]] = {}
        for sym_name in mentioned:
            incoming = self._f._symbol_index.get_edges_in(sym_name, project_id)
            sources = [e.src for e in incoming if e.type == "data_flow"]
            if sources:
                data_flow_upstream[sym_name] = sources

        verifiable = len(symbols_found) + len(call_relations_valid)
        if verifiable == 0:
            objective_score = 0.5
        else:
            verified_true = sum(1 for v in symbols_found.values() if v) + sum(
                1 for v in call_relations_valid.values() if v
            )
            objective_score = verified_true / verifiable

        return StaticEvidence(
            symbols_found=symbols_found,
            call_relations_valid=call_relations_valid,
            recent_changes=recent_changes,
            entry_points_mentioned=entry_points_mentioned,
            path_memberships=path_memberships,
            data_flow_upstream=data_flow_upstream,
            objective_score=objective_score,
        )

    def positive_evidence(self, evidence: "StaticEvidence") -> Dict[str, Any]:
        """Extract facts that SUPPORT the hypothesis."""
        return {
            "symbols_confirmed": [k for k, v in evidence.symbols_found.items() if v],
            "relations_confirmed": [
                k for k, v in evidence.call_relations_valid.items() if v
            ],
            "recent_activity": evidence.recent_changes,
            "entry_points_confirmed": evidence.entry_points_mentioned,
        }

    def negative_evidence(self, evidence: "StaticEvidence") -> Dict[str, Any]:
        """Extract facts that CONTRADICT the hypothesis."""
        return {
            "symbols_missing": [k for k, v in evidence.symbols_found.items() if not v],
            "relations_invalid": [
                k for k, v in evidence.call_relations_valid.items() if not v
            ],
        }

    def _compute_coverage_score(
        self,
        design: "ExperimentDesign",
    ) -> float:
        """
        Coverage = verifiable_claims / total_claims.

        Unknown claims represent epistemic blind spots — claims the LLM
        made that we cannot check structurally. A high obj_score with
        low coverage is unreliable (availability bias): the engine scored
        well on the 20% it could check, ignoring the 80% it couldn't.

        Returns 1.0 when no claims exist (vacuously covered).
        """
        total = (
            len(design.critical_claims)
            + len(design.supportive_claims)
            + len(design.unknown_claims)
        )
        if total == 0:
            return 1.0
        verifiable = len(design.critical_claims) + len(design.supportive_claims)
        return verifiable / total

    def _compute_epistemic_uncertainty(
        self,
        obj_score: float,
        coverage_score: float,
        predictions_verified: int,
        predictions_total: int,
    ) -> float:
        """
        Bayesian-inspired epistemic uncertainty estimate.
        Deterministic — no LLM.

        Three objective signals (all SymbolGraph-derived):
        1. Coverage uncertainty (50%): low coverage → high uncertainty
        2. Prediction uncertainty (20%): failed predictions → high uncertainty
        3. Score ambiguity (30%): score near 0.5 → high uncertainty

        Returns uncertainty in [0, 1]:
            0.0 = high confidence
            1.0 = high uncertainty

        Used to gate peer review — only when uncertainty > threshold
        does peer review add epistemic value.
        """
        coverage_uncertainty = 1.0 - coverage_score

        if predictions_total > 0:
            pred_uncertainty = 1.0 - (predictions_verified / predictions_total)
        else:
            pred_uncertainty = 0.5  # no predictions = genuinely unknown

        # Peaks at 0.5, zero at 0 or 1
        score_uncertainty = 1.0 - abs(obj_score - 0.5) * 2.0

        uncertainty = (
            0.5 * coverage_uncertainty
            + 0.2 * pred_uncertainty
            + 0.3 * score_uncertainty
        )
        return min(1.0, max(0.0, uncertainty))

    def _claim_verified(self, claim: str, evidence: "StaticEvidence") -> bool:
        """
        Check if a textual claim is confirmed by the structural evidence.

        Normalizes spaces→underscores before matching:
            LLM claims use natural language: "foo calls bar"
            Evidence keys use underscores:   "foo_calls_bar"
        Both variants are tried to avoid false negatives caused by
        format mismatch. Without normalization, is_falsified can never
        detect call relation contradictions (critical bug D).

        Unverifiable claims (no match in evidence) get benefit of the doubt
        and return True.
        """
        claim_lower = claim.lower()
        claim_normalized = claim_lower.replace(" ", "_")
        claim_variants = {claim_lower, claim_normalized}

        for relation, valid in evidence.call_relations_valid.items():
            relation_lower = relation.lower()
            if any(v in relation_lower for v in claim_variants):
                return valid
        for symbol, found in evidence.symbols_found.items():
            symbol_lower = symbol.lower()
            if any(v in symbol_lower for v in claim_variants):
                return found
        return True  # unverifiable → benefit of doubt

    def is_falsified(
        self,
        evidence: "StaticEvidence",
        design: "ExperimentDesign",
        coverage_score: float = 1.0,
    ) -> Tuple[bool, Optional[str]]:
        """
        Popperian asymmetric falsification with coverage guard.

        Claim matching normalizes spaces→underscores in both directions
        so that natural language claims ("foo calls bar") match
        underscore-keyed evidence ("foo_calls_bar").

        Coverage guard (H4 + H2 interaction):
            If coverage_score < min_coverage_for_falsification and
            enable_coverage_guard_for_falsification=True, we've only
            verified a small fraction of the hypothesis's claims.
            A failed critical claim may reflect incomplete sampling,
            not a true structural contradiction.
            In this case: returns (False, reason) — caller applies
            a penalty via compute_weighted_score instead of killing.

        With sufficient coverage AND design:
            ANY critical claim False → immediate hard kill.
            Supportive claim failures → score penalty only.

        Without design (fallback — enable_experiment_design=False):
            Symmetric ratio > 0.5 → falsified.

        Returns (falsified, reason_string).
        """
        _coverage_guard_active = (
            self._f.valves.enable_coverage_guard_for_falsification
            and coverage_score < self._f.valves.min_coverage_for_falsification
            and self._f.valves.enable_experiment_design
            and design.critical_claims
        )

        if not self._f.valves.enable_experiment_design or not design.critical_claims:
            # Symmetric fallback — existing behaviour when design is disabled
            neg = self.negative_evidence(evidence)
            total = len(evidence.symbols_found) + len(evidence.call_relations_valid)
            if total == 0:
                return False, None
            contradictions = len(neg["symbols_missing"]) + len(neg["relations_invalid"])
            if contradictions / total > 0.5:
                return (
                    True,
                    f"Symmetric falsification: {contradictions}/{total} claims false",
                )
            return False, None

        # Asymmetric: ONE critical claim failure → hard kill (or downgrade)
        for claim in design.critical_claims:
            claim_lower = claim.lower()
            # Normalize spaces→underscores to match evidence key format
            # LLM writes "foo calls bar", evidence uses "foo_calls_bar"
            claim_normalized = claim_lower.replace(" ", "_")
            claim_variants = {claim_lower, claim_normalized}

            for relation, valid in evidence.call_relations_valid.items():
                if any(v in relation.lower() for v in claim_variants) and not valid:
                    reason = (
                        f"Critical claim falsified: '{claim}' — "
                        f"relation '{relation}' does not exist in SymbolGraph"
                    )
                    if _coverage_guard_active:
                        self._f._log_debug(
                            f"is_falsified: coverage guard active "
                            f"(coverage={coverage_score:.2f} < "
                            f"{self._f.valves.min_coverage_for_falsification:.2f}) "
                            f"→ downgrading hard kill to penalty"
                        )
                        return False, reason  # caller applies penalty
                    return True, reason  # hard kill

            for symbol, found in evidence.symbols_found.items():
                if any(v in symbol.lower() for v in claim_variants) and not found:
                    reason = (
                        f"Critical claim falsified: '{claim}' — "
                        f"symbol '{symbol}' not found in SymbolGraph"
                    )
                    if _coverage_guard_active:
                        self._f._log_debug(
                            f"is_falsified: coverage guard active "
                            f"(coverage={coverage_score:.2f}) "
                            f"→ downgrading hard kill to penalty"
                        )
                        return False, reason  # caller applies penalty
                    return True, reason  # hard kill

        return False, None

    def compute_weighted_score(
        self,
        evidence: "StaticEvidence",
        design: "ExperimentDesign",
        llm_conf: float,
        predictions_verified: int = 0,
        predictions_total: int = 0,
        downgraded_reason: Optional[str] = None,
        obj_weight: float = 0.5,
        llm_weight: float = 0.5,
    ) -> Tuple[float, float, float]:
        """
        Compute (obj_score, combined_score, coverage_score).

        obj_weight / llm_weight control the balance between structural
        evidence (deterministic) and LLM confidence (self-reported).

        Default 50/50 for debugging/verification queries.
        Architecture queries use 40/60 (proposing new design, not verifying
        existing behavior — LLM design judgment matters more).

        Scoring layers:
        1. Structural: critical claims 10x, supportive 1x.
        2. Downgrade penalty: if is_falsified() was coverage-guarded.
        3. Prediction bonus: verified predictions +10% max.
        4. Coverage penalty: low coverage penalizes combined proportionally.

        Returns (obj_score, combined_score, coverage_score).
        """
        CRITICAL_WEIGHT = 10.0
        SUPPORTIVE_WEIGHT = 1.0

        coverage_score = self._compute_coverage_score(design)

        if not self._f.valves.enable_weighted_scoring or not design.critical_claims:
            verifiable = len(evidence.symbols_found) + len(
                evidence.call_relations_valid
            )
            if verifiable == 0:
                obj_score = 0.5
            else:
                verified = sum(1 for v in evidence.symbols_found.values() if v) + sum(
                    1 for v in evidence.call_relations_valid.values() if v
                )
                obj_score = verified / verifiable
        else:
            total_weight = 0.0
            verified_weight = 0.0
            for claim in design.critical_claims:
                total_weight += CRITICAL_WEIGHT
                if self._claim_verified(claim, evidence):
                    verified_weight += CRITICAL_WEIGHT
            for claim in design.supportive_claims:
                total_weight += SUPPORTIVE_WEIGHT
                if self._claim_verified(claim, evidence):
                    verified_weight += SUPPORTIVE_WEIGHT
            obj_score = verified_weight / total_weight if total_weight > 0 else 0.5

        # Downgrade penalty — coverage-guarded falsification
        if downgraded_reason:
            obj_score = max(0.0, obj_score - 0.3)
            self._f._log_debug(
                f"compute_weighted_score: downgrade penalty applied "
                f"({downgraded_reason[:60]})"
            )

        # Prediction bonus
        if predictions_total > 0:
            prediction_ratio = predictions_verified / predictions_total
            obj_score = min(1.0, obj_score + 0.1 * prediction_ratio)

        # Coverage penalty on combined score
        low_cov = self._f.valves.low_coverage_threshold
        if coverage_score < low_cov:
            penalty = 0.5 * (low_cov - coverage_score) / low_cov
            combined_raw = obj_weight * obj_score + llm_weight * llm_conf
            combined = max(0.0, combined_raw * (1.0 - penalty))
            self._f._log_debug(
                f"compute_weighted_score: coverage penalty "
                f"(coverage={coverage_score:.2f}) "
                f"→ {combined_raw:.3f} → {combined:.3f}"
            )
        else:
            combined = obj_weight * obj_score + llm_weight * llm_conf

        return obj_score, combined, coverage_score

    def _compute_signal_vector(
        self,
        user_content: str,
        project_id: str,
        min_symbol_length: int = 4,
    ) -> Dict[str, int]:
        """
        Synchronous SymbolGraph pre-scan.

        Runs gather_evidence() on the raw user message — treating it as
        if it were a hypothesis — to measure how many known codebase symbols
        it mentions and whether any call-relation patterns are detectable.

        This is a reinforcement signal, not a trigger. High count means
        the user is asking about specific indexed code. Low count means
        the query is generic — fine for linear CoT, poor fit for
        compete_hypotheses (nothing to falsify structurally).

        min_symbol_length filters short generic words that happen to
        match symbol names ('id', 'db', 'run'). Default 4.

        Called synchronously BEFORE the parallel gather in
        _detect_and_generate_cot so it adds zero perceived latency.

        Returns:
            n_mentioned:     symbols from query present in index
                             (regardless of active block presence)
            n_found:         symbols both mentioned AND verified in graph
            n_relations:     call-relation patterns detected in query text
            structural_hits: n_mentioned + n_relations (total signal)
        """
        _empty = {
            "n_mentioned": 0,
            "n_found": 0,
            "n_relations": 0,
            "structural_hits": 0,
        }

        if not user_content or not project_id:
            return _empty

        try:
            evidence = self.gather_evidence(user_content, project_id)

            n_mentioned = sum(
                1 for name in evidence.symbols_found if len(name) >= min_symbol_length
            )
            n_found = sum(
                1
                for name, found in evidence.symbols_found.items()
                if found and len(name) >= min_symbol_length
            )
            n_relations = len(evidence.call_relations_valid)

            return {
                "n_mentioned": n_mentioned,
                "n_found": n_found,
                "n_relations": n_relations,
                "structural_hits": n_mentioned + n_relations,
            }
        except Exception as e:
            self._f._log_debug(
                f"_compute_signal_vector: failed ({type(e).__name__}: {e}) "
                f"→ returning empty signal"
            )
            return _empty

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Pre-evidence design and prediction generation
    # ═══════════════════════════════════════════════════════════════════════

    async def design_critical_experiment(
        self,
        hypothesis: str,
        project_id: str,
    ) -> "ExperimentDesign":
        """
        Classify hypothesis claims BEFORE gathering evidence.
        TURN LEVEL (H5 temporal hierarchy).
        Gated by enable_experiment_design valve.

        Classifies each structural claim as:
            CRITICAL   — hard kill if false (sine qua non)
            SUPPORTIVE — score penalty only if false
            UNKNOWN    — not directly verifiable in SymbolGraph

        Results are cached by hypothesis MD5 to avoid re-designing on
        iterations where the hypothesis text hasn't changed.
        """
        _empty = ExperimentDesign(
            critical_claims=[], supportive_claims=[], unknown_claims=[]
        )

        if not self._f.valves.enable_experiment_design:
            return _empty

        h_hash = hashlib.md5(hypothesis.encode()).hexdigest()[:16]
        if h_hash in self._design_cache:
            self._f._log_debug(f"design_critical_experiment: cache hit ({h_hash})")
            return self._design_cache[h_hash]

        prompt = (
            f"Hypothesis:\n{hypothesis}\n\n"
            f"Extract all structural claims this hypothesis makes about the code. "
            f"Classify each claim:\n"
            f"  CRITICAL   — if false, the hypothesis cannot be correct "
            f"(sine qua non)\n"
            f"  SUPPORTIVE — if false, it weakens the hypothesis but does not "
            f"kill it\n"
            f"  UNKNOWN    — cannot be verified structurally in a symbol graph\n\n"
            f"Reason about why each claim is critical or not before classifying.\n\n"
            f'Output only the JSON object, e.g. {{"critical": ["A calls B"], '
            f'"supportive": ["C exists"], "unknown": ["D might be related"]}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a structural claim classifier for software architecture. "
                "Output ONLY a valid JSON object with three keys: "
                "'critical', 'supportive', 'unknown' (all lists of strings). "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=0,
            temperature=0.0,
            label="design_critical_experiment",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return _empty

        try:
            data = json.loads(response)
            design = ExperimentDesign(
                critical_claims=[str(c) for c in data.get("critical", []) if c],
                supportive_claims=[str(c) for c in data.get("supportive", []) if c],
                unknown_claims=[str(c) for c in data.get("unknown", []) if c],
                hypothesis_hash=h_hash,
            )
            if len(self._design_cache) >= 50:
                self._design_cache.clear()
            self._design_cache[h_hash] = design
            self._f._log_debug(
                f"design_critical_experiment: {len(design.critical_claims)} critical, "
                f"{len(design.supportive_claims)} supportive, "
                f"{len(design.unknown_claims)} unknown"
            )
            return design
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"design_critical_experiment: parse error — {response[:200]!r}"
            )
            return _empty

    async def generate_predictions(
        self,
        hypothesis: str,
        project_id: str,
    ) -> List[str]:
        """
        Deduce structural consequences of the hypothesis.
        TURN LEVEL (H5 temporal hierarchy).
        Gated by enable_generate_predictions valve.

        Asks: 'If this hypothesis is correct, what OTHER structural facts
        should be true in the codebase?' beyond what it explicitly states.

        These predictions are verified by gather_evidence() in the next
        iteration, closing the hypothetico-deductive cycle.

        Note: skeleton context is fetched via _format_skeleton (synchronous).
        If unavailable, predictions are generated without code structure
        context and will be more generic. This degrades gracefully —
        the absence is logged explicitly.
        """
        if not self._f.valves.enable_generate_predictions:
            return []

        skeleton_ctx = ""
        try:
            skeleton = self._f._ctx_builder._format_skeleton(
                project_id
            )  # sync — no await
            skeleton_ctx = skeleton[:2000] if skeleton else ""
        except Exception as e:
            self._f._log_debug(
                f"generate_predictions: skeleton unavailable "
                f"({type(e).__name__}: {e}) — "
                f"predictions generated without code structure context"
            )

        prompt = (
            f"Hypothesis:\n{hypothesis}\n\n"
            + (
                f"Code structure (signatures only):\n{skeleton_ctx}\n\n"
                if skeleton_ctx
                else ""
            )
            + "If this hypothesis is correct, what additional structural facts "
            "MUST be true in the codebase?\n"
            "List 2-3 concrete, directly verifiable claims "
            "(e.g. 'X calls Y', 'Z exists', 'A inherits from B').\n"
            "Only include claims checkable against the symbol graph.\n"
            "Do NOT repeat claims already explicit in the hypothesis.\n\n"
            f'Output only the JSON object: {{"predictions": ["claim1", "claim2"]}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a structural prediction generator for software architecture. "
                "Output ONLY a valid JSON object with key 'predictions' "
                "(list of strings). "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=0,
            temperature=0.3,
            label="generate_predictions",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return []

        try:
            data = json.loads(response)
            predictions = [str(p) for p in data.get("predictions", []) if p]
            self._f._log_debug(
                f"generate_predictions: {len(predictions)} prediction(s) "
                f"(skeleton_ctx={'yes' if skeleton_ctx else 'no'})"
            )
            return predictions
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"generate_predictions: parse error — {response[:200]!r}"
            )
            return []

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Active Learning (H4)
    # ═══════════════════════════════════════════════════════════════════════

    def _identify_missing_information(
        self,
        design: "ExperimentDesign",
        project_id: str,
    ) -> List[str]:
        """
        Active Learning: identify unknown_claims that mention symbols
        present in the SymbolGraph but not recognized as verifiable
        by the experiment design.

        These are 'almost verifiable' claims — the LLM classified them
        as unknown, but we CAN check them structurally.

        Deterministic — no LLM. Pure SymbolGraph lookup.
        Gated by enable_active_learning valve.
        """
        if not self._f.valves.enable_active_learning:
            return []
        if not design.unknown_claims:
            return []

        all_names = self._f._symbol_index.get_all_names(project_id)
        resolvable: List[str] = []

        for claim in design.unknown_claims:
            words = set(re.findall(r"\b\w+\b", claim))
            candidates = words.intersection(all_names)
            resolvable.extend(candidates)

        return list(set(resolvable))

    def _resolve_unknown_claims(
        self,
        design: "ExperimentDesign",
        resolvable_symbols: List[str],
        project_id: str,
    ) -> "ExperimentDesign":
        """
        Active Learning: reclassify unknown_claims as supportive_claims
        when their mentioned symbols exist in the SymbolGraph.

        Deterministic reclassification — no LLM.
        Effect: increases coverage_score before falsification runs.

        Limited to active_learning_max_reclassifications to avoid
        over-expanding the verification scope.
        Invalidates the design cache entry so the next hit re-fetches
        the updated design.
        """
        if not resolvable_symbols:
            return design

        max_reclass = self._f.valves.active_learning_max_reclassifications
        new_supportive = list(design.supportive_claims)
        new_unknown = []
        reclassified = 0

        for claim in design.unknown_claims:
            if reclassified >= max_reclass:
                new_unknown.append(claim)
                continue
            words = set(re.findall(r"\b\w+\b", claim))
            if words.intersection(set(resolvable_symbols)):
                new_supportive.append(claim)
                reclassified += 1
                self._f._log_debug(
                    f"active_learning: reclassified unknown → supportive: "
                    f"'{claim[:60]}'"
                )
            else:
                new_unknown.append(claim)

        if reclassified > 0:
            self._f._log_debug(f"active_learning: {reclassified} claim(s) reclassified")
            h_hash = design.hypothesis_hash
            if h_hash in self._design_cache:
                del self._design_cache[h_hash]

        return ExperimentDesign(
            critical_claims=design.critical_claims,
            supportive_claims=new_supportive,
            unknown_claims=new_unknown,
            hypothesis_hash=design.hypothesis_hash,
        )

    # ═══════════════════════════════════════════════════════════════════════
    # 4. Competition loop helpers
    # ═══════════════════════════════════════════════════════════════════════

    @staticmethod
    def _parse_hypotheses_from_response(
        text: str,
    ) -> List[Tuple[str, float]]:
        """
        Extract (hypothesis_text, confidence) pairs from an LLM response.

        Accepts two formats:
            Hypothesis N: <text>        ← standard scientific reasoning
            Design Option N: <text>     ← architecture reasoning
        Both followed by: Confidence: <0.0-1.0>
        """
        results = []
        pattern = re.compile(
            r"(?:(?:Design\s+)?(?:Option|Hypothesis))\s*\d*\s*:\s*"
            r"(.+?)\s*Confidence\s*:\s*([\d.]+)",
            re.IGNORECASE | re.DOTALL,
        )
        for match in pattern.finditer(text):
            hyp_text = match.group(1).strip().rstrip(".")
            try:
                conf = float(match.group(2))
                conf = max(0.0, min(1.0, conf))
            except ValueError:
                conf = 0.5
            results.append((hyp_text, conf))
        return results

    def _detect_stagnation(
        self,
        obj_score_history: List[float],
        window: int = 2,
        min_delta: float = 0.02,
    ) -> bool:
        """
        Return True when the objective score has not improved meaningfully over
        the last `window` iterations.

        Requires at least window+1 data points to make a meaningful comparison.
        Returns False (not stagnated) when history is too short, which is the
        correct signal: on early iterations there is not enough data to declare
        stagnation, so refinement should proceed normally.

        Steps:
            1.  Return False immediately when history has fewer than window+1
                entries — avoids IndexError and gives early iterations the benefit
                of the doubt.
            2.  Compute the per-step deltas within the window.
            3.  Return True if every delta is below min_delta (flat or regressing).
        """
        # -- Step 1: minimum history guard --
        if len(obj_score_history) < window + 1:
            return False

        # -- Step 2: compute deltas within window --
        recent = obj_score_history[-(window + 1) :]
        deltas = [recent[i + 1] - recent[i] for i in range(len(recent) - 1)]

        # -- Step 3: stagnation when all deltas below threshold --
        return all(d < min_delta for d in deltas)

    def _build_refinement_constraints(
        self,
        coverage_score: float,
        strategy: Dict[str, Any],
        stagnated: bool,
    ) -> str:
        """
        Build deterministic prompt constraints based on objective metrics.
        ITERATION LEVEL — PID output injected into LLM inputs.

        The LLM receives constraints derived from SymbolGraph reality —
        NOT self-evaluation requests. It never knows these are
        metacognitive adjustments. This is the PID/OODA control loop:
        objective signals → prompt modifications → better LLM outputs.

        Three constraint types (all deterministic):
        1. Coverage: when evidence is sparse → demand atomic verifiable claims
        2. Pattern: when a failure mode dominates this project historically
        3. Divergence: when stagnation was detected → demand new directions
        """
        constraints: List[str] = []

        if coverage_score < self._f.valves.low_coverage_threshold:
            constraints.append(
                "CONSTRAINT: Many claims in the previous hypothesis could not be "
                "verified structurally. In the new hypotheses, express all claims "
                "as direct, atomic checks: symbol existence ('X exists'), call "
                "relations ('A calls B'), or inheritance ('C inherits D'). "
                "Avoid abstract architectural descriptions without structural anchors."
            )

        call_fail_rate = strategy.get("call_fail_rate", 0.0)
        if call_fail_rate > 0.6:
            constraints.append(
                "CONSTRAINT: In this codebase, call relation claims frequently "
                "fail structural verification. Prioritize hypotheses grounded in "
                "symbol existence over call graph assumptions."
            )
        elif strategy.get("prefer_symbol_verification"):
            constraints.append(
                "CONSTRAINT: Symbol existence checks are more reliable than "
                "call relation checks in this codebase. Weight them accordingly."
            )

        if stagnated:
            constraints.append(
                "CONSTRAINT: Previous hypotheses converged without reaching the "
                "confidence threshold. Generate structurally diverse alternatives. "
                "Consider indirect dependencies, non-obvious modules, or "
                "completely different root causes. Avoid variations of the "
                "previous hypothesis."
            )

        return "\n".join(constraints) if constraints else ""

    async def _generate_divergent_hypotheses(
        self,
        best: "ScoredHypothesis",
        max_hypotheses: int,
        project_id: str,
        label: str = "",
    ) -> List[Tuple[str, float]]:
        """
        Break out of local optima by generating radically alternative
        hypotheses using a contrarian, high-temperature prompt.
        ITERATION LEVEL — stagnation escape.

        Intentionally ignores the current best hypothesis to avoid
        anchoring on a failed direction. Uses temperature=0.9 for
        maximum diversity.

        The LLM is asked to ignore its previous reasoning — this is
        NOT self-evaluation, it is a forced context reset.
        """
        neg = self.negative_evidence(best.evidence)

        prompt = (
            f"The following hypothesis has stagnated at score {best.score:.2f}:\n"
            f"'{best.text}'\n\n"
            f"Structural contradictions that block it:\n"
            f"  Missing symbols: {neg['symbols_missing']}\n"
            f"  Invalid relations: {neg['relations_invalid']}\n\n"
            f"IGNORE the current hypothesis entirely.\n"
            f"Propose {max_hypotheses} RADICALLY DIFFERENT explanations. "
            f"Think contrarian: consider indirect paths, alternative root causes, "
            f"or completely different modules as the source.\n\n"
            f"For each:\n"
            f"Hypothesis: <one concise sentence>\n"
            f"Confidence: <0.0-1.0>"
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a divergent thinking engine for software architecture. "
                "Your goal is to break out of local optima. "
                "Propose the most contrarian, unexpected hypotheses grounded "
                "in the structural evidence provided."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=600,
            temperature=0.9,
            label=f"{label}_divergent" if label else "sci_divergent",
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return []

        new_hypotheses = self._parse_hypotheses_from_response(response)
        if new_hypotheses:
            self._f._log_debug(
                f"_generate_divergent_hypotheses: {len(new_hypotheses)} "
                f"divergent hypotheses generated"
            )
        return new_hypotheses if len(new_hypotheses) >= 2 else []

    async def _refine_hypotheses(
        self,
        best: "ScoredHypothesis",
        max_hypotheses: int,
        project_id: str,
        label: str = "",
        constraints: str = "",
    ) -> List[Tuple[str, float]]:
        """
        Refine hypotheses based on evidence feedback.
        ITERATION LEVEL — convergent refinement.

        Constraints from _build_refinement_constraints() are prepended
        to the prompt. The LLM receives them as context restrictions,
        never as self-evaluation requests.
        """
        neg = self.negative_evidence(best.evidence)
        pos = self.positive_evidence(best.evidence)

        evidence_feedback = (
            f"Previous best hypothesis "
            f"(score {best.score:.2f}, coverage {best.coverage_score:.2f}):\n"
            f"{best.text}\n\n"
            f"Structural evidence:\n"
            f"- Symbols confirmed: {pos['symbols_confirmed']}\n"
            f"- Relations confirmed: {pos['relations_confirmed']}\n"
            f"- Symbols missing: {neg['symbols_missing']}\n"
            f"- Relations invalid: {neg['relations_invalid']}\n"
            f"- Recent changes: {best.evidence.recent_changes}\n"
            f"- Objective score: {best.evidence.objective_score:.2f}\n\n"
            f"Based on this evidence, propose {max_hypotheses} improved hypotheses. "
            f"Address the structural contradictions. Be specific."
        )

        full_prompt = (
            f"{constraints}\n\n{evidence_feedback}"
            if constraints
            else evidence_feedback
        )

        refine_prompt = (
            f"{full_prompt}\n\n"
            f"Output the same format:\n"
            f"Hypothesis: <one concise sentence>\n"
            f"Confidence: <0.0-1.0>"
        )

        refine_response = await self._f._llm_orchestrator.call_llm(
            prompt=refine_prompt,
            system_prompt=(
                "You are a scientific reasoning engine refining hypotheses "
                "based on structural evidence from the codebase."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=600,
            temperature=0.4,
            label=f"{label}_refine" if label else "sci_refine",
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not refine_response:
            return []

        new_hypotheses = self._parse_hypotheses_from_response(refine_response)
        return new_hypotheses if len(new_hypotheses) >= 2 else []

    async def compete_hypotheses(
        self,
        hypotheses: List[Tuple[str, float]],
        project_id: str,
        max_iters: int = 3,
        threshold: float = 0.75,
        label: str = "",
        obj_weight: float = 0.5,
        llm_weight: float = 0.5,
    ) -> Tuple[str, float, "StaticEvidence", Optional["PeerReviewResult"]]:
        """
        Run multi-iteration hypothesis competition to find the strongest explanation.

        Each iteration: evaluates all active (non-falsified) hypotheses against
        static evidence and LLM confidence, falsifies weak ones, refines or
        diversifies survivors, and checks for convergence.

        Returns the best surviving hypothesis, its score, its evidence, and an
        optional peer review result.

        Fallback when all hypotheses are falsified:
            The least-bad entry in scored_list is returned with a low score rather
            than crashing. This preserves a usable (if low-confidence) answer for
            the caller rather than propagating StopIteration or IndexError.

        Steps:
            1.  Guard: empty input returns a null hypothesis immediately.
            2.  Initialise scored_list from input hypotheses.
            3.  Competition loop (up to max_iters):
                a.  Evaluate each active hypothesis.
                b.  Falsify those below the falsification threshold.
                c.  Find current best among survivors.
                d.  Check early-exit on threshold or stagnation.
                e.  Seek experimentum crucis between top-2 survivors.
                f.  Refine or diversify based on stagnation signal.
            4.  Select winner: best non-falsified entry; fallback to least-bad
                if all are falsified.
            5.  Run peer review on winner.
            6.  Debrief competition for adaptive strategy update.
            7.  Return (winner_text, score, evidence, peer_review).
        """
        # -- Step 1: empty input guard --
        if not hypotheses:
            self._f._log_debug(
                f"compete_hypotheses: called with empty hypotheses list "
                f"for '{project_id}' ({label}), returning null hypothesis"
            )
            null_evidence = self.gather_evidence("", project_id)
            return "", 0.0, null_evidence, None

        # -- Step 2: initialise scored_list --
        scored_list: List[ScoredHypothesis] = []
        for text, llm_conf in hypotheses:
            evidence = self.gather_evidence(text, project_id)
            design = await self.design_critical_experiment(text, project_id)
            score, coverage, uncertainty = self.compute_weighted_score(
                evidence,
                design,
                llm_conf,
                obj_weight=obj_weight,
                llm_weight=llm_weight,
            )
            scored_list.append(
                ScoredHypothesis(
                    text=text,
                    score=score,
                    llm_conf=llm_conf,
                    obj_score=evidence.objective_score,
                    evidence=evidence,
                    design=design,
                    falsified=False,
                    falsification_reason=None,
                    scope="",
                    predictions_verified=0,
                    predictions_total=0,
                    coverage_score=coverage,
                    epistemic_uncertainty=uncertainty,
                )
            )

        obj_score_history: List[float] = []
        peer_review: Optional[PeerReviewResult] = None

        # -- Step 3: competition loop --
        for iteration in range(max_iters):
            active = [h for h in scored_list if not h.falsified]
            if not active:
                self._f._log_debug(
                    f"compete_hypotheses: all hypotheses falsified after "
                    f"iteration {iteration} for '{project_id}'"
                )
                break

            # -- 3a: evaluate active hypotheses --
            for h in active:
                evidence = self.gather_evidence(h.text, project_id)
                design = h.design
                score, coverage, uncertainty = self.compute_weighted_score(
                    evidence,
                    design,
                    h.llm_conf,
                    obj_weight=obj_weight,
                    llm_weight=llm_weight,
                )
                h.score = score
                h.obj_score = evidence.objective_score
                h.evidence = evidence
                h.coverage_score = coverage
                h.epistemic_uncertainty = uncertainty

            # -- 3b: falsify weak hypotheses --
            active_scores = sorted([h.score for h in active], reverse=True)
            falsification_floor = (
                active_scores[0] * self._f.valves.hypothesis_falsification_ratio
                if active_scores
                and hasattr(self._f.valves, "hypothesis_falsification_ratio")
                else 0.0
            )
            for h in active:
                falsified, reason = self.is_falsified(
                    h.evidence, h.design, h.coverage_score
                )
                if falsified or h.score < falsification_floor:
                    h.falsified = True
                    h.falsification_reason = reason or "score below floor"

            active = [h for h in scored_list if not h.falsified]
            if not active:
                break

            # -- 3c: find current best --
            best = max(active, key=lambda h: h.score)
            obj_score_history.append(best.obj_score)

            self._f._log_debug(
                f"compete_hypotheses: iter {iteration+1}/{max_iters} — "
                f"best score={best.score:.3f}, "
                f"{len(active)} active / {len(scored_list)} total "
                f"({label})"
            )

            # -- 3d: convergence check --
            if best.score >= threshold:
                self._f._log_debug(
                    f"compete_hypotheses: threshold {threshold} reached "
                    f"at iter {iteration+1}"
                )
                break

            stagnated = self._detect_stagnation(obj_score_history)

            # -- 3e: experimentum crucis for top-2 survivors --
            if len(active) >= 2:
                sorted_active = sorted(active, key=lambda h: h.score, reverse=True)
                try:
                    crucis = await self.find_experimentum_crucis(
                        sorted_active[0].text, sorted_active[1].text, project_id
                    )
                    if crucis:
                        self._f._log_debug(
                            f"compete_hypotheses: experimentum crucis found"
                        )
                except Exception as e:
                    self._f._log_debug(
                        f"compete_hypotheses: experimentum crucis failed: {e}"
                    )

            # -- 3f: refine or diversify --
            if iteration < max_iters - 1:
                try:
                    if stagnated:
                        new_pairs = await self._generate_divergent_hypotheses(
                            best,
                            max_hypotheses=2,
                            project_id=project_id,
                            label=label,
                        )
                    else:
                        constraints = self._build_refinement_constraints(
                            best.coverage_score,
                            self._get_adaptive_strategy(project_id),
                            stagnated,
                        )
                        new_pairs = await self._refine_hypotheses(
                            best,
                            max_hypotheses=2,
                            project_id=project_id,
                            label=label,
                            constraints=constraints,
                        )

                    for new_text, new_conf in new_pairs:
                        if not new_text:
                            continue
                        new_evidence = self.gather_evidence(new_text, project_id)
                        new_design = await self.design_critical_experiment(
                            new_text, project_id
                        )
                        new_score, new_cov, new_unc = self.compute_weighted_score(
                            new_evidence,
                            new_design,
                            new_conf,
                            obj_weight=obj_weight,
                            llm_weight=llm_weight,
                        )
                        scored_list.append(
                            ScoredHypothesis(
                                text=new_text,
                                score=new_score,
                                llm_conf=new_conf,
                                obj_score=new_evidence.objective_score,
                                evidence=new_evidence,
                                design=new_design,
                                falsified=False,
                                falsification_reason=None,
                                scope="",
                                predictions_verified=0,
                                predictions_total=0,
                                coverage_score=new_cov,
                                epistemic_uncertainty=new_unc,
                            )
                        )

                except Exception as e:
                    self._f._log_debug(
                        f"compete_hypotheses: refinement failed at iter "
                        f"{iteration+1}: {type(e).__name__}: {e}"
                    )

        # -- Step 4: select winner --
        # Primary: best non-falsified hypothesis.
        # Fallback: best by score among all entries (including falsified) so we
        # never return an empty string when all hypotheses were falsified.
        survivors = [h for h in scored_list if not h.falsified]
        if survivors:
            winner = max(survivors, key=lambda h: h.score)
        else:
            self._f._log_debug(
                f"compete_hypotheses: all {len(scored_list)} hypotheses falsified "
                f"for '{project_id}' ({label}) — using least-bad fallback"
            )
            winner = max(scored_list, key=lambda h: h.score)
            winner.score = min(winner.score, 0.3)  # cap to signal low confidence

        final_score = winner.score
        final_evidence = winner.evidence
        coverage = winner.coverage_score
        score_trajectory = obj_score_history

        # -- Step 5: peer review --
        try:
            peer_review = await self.peer_review_hypothesis(
                hypothesis=winner.text,
                evidence=final_evidence,
                design=winner.design,
                project_id=project_id,
            )
        except Exception as e:
            self._f._log_debug(
                f"compete_hypotheses: peer review failed: {type(e).__name__}: {e}"
            )
            peer_review = None

        # -- Step 6: debrief --
        try:
            await self._debrief_competition(
                scored_list,
                final_score,
                coverage,
                score_trajectory,
                stagnated=self._detect_stagnation(score_trajectory),
                project_id=project_id,
            )
        except Exception as e:
            self._f._log_debug(
                f"compete_hypotheses: debrief failed: {type(e).__name__}: {e}"
            )

        # -- Step 7: return --
        self._f._log_debug(
            f"compete_hypotheses: winner score={final_score:.3f}, "
            f"coverage={coverage:.2f}, "
            f"peer_review={'yes' if peer_review else 'no'} "
            f"({label})"
        )
        return winner.text, final_score, final_evidence, peer_review

    # ═══════════════════════════════════════════════════════════════════════
    # 5. Post-competition tools
    # ═══════════════════════════════════════════════════════════════════════

    async def find_experimentum_crucis(
        self,
        h1: str,
        h2: str,
        project_id: str,
    ) -> Optional[str]:
        """
        Design the minimal structural verification that distinguishes H1 from H2.
        CONVERSATION LEVEL (H5).

        Returns the winning hypothesis text, or None if inconclusive.
        Returns None when the tiebreaker claim is unverifiable in the SymbolGraph
        — an unverifiable claim gives no information and must not be used to decide.
        """
        prompt = (
            f"Two competing hypotheses with similar scores:\n\n"
            f"H1: {h1}\n\nH2: {h2}\n\n"
            f"What is the single simplest structural claim that:\n"
            f"  - Would be TRUE if H1 is correct and FALSE if H2 is correct\n"
            f"  - OR: TRUE if H2 is correct and FALSE if H1 is correct\n"
            f"The claim must be verifiable in a symbol graph "
            f"(e.g. 'X calls Y', 'Z exists', 'A inherits B').\n\n"
            f'Output only: {{"claim": "...", "supports": "H1" or "H2"}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a scientific experiment designer for software architecture. "
                "Output ONLY a valid JSON object with 'claim' (string) and "
                "'supports' ('H1' or 'H2'). "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=0,
            temperature=0.0,
            label="experimentum_crucis",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return None

        try:
            data = json.loads(response)
            claim = str(data.get("claim", "")).strip()
            supports = str(data.get("supports", "")).strip().upper()
            if not claim or supports not in ("H1", "H2"):
                return None

            evidence = self.gather_evidence(claim, project_id)

            # If claim mentions no symbols or relations from the SymbolGraph,
            # it is unverifiable — returning a winner would be arbitrary.
            if not evidence.symbols_found and not evidence.call_relations_valid:
                self._f._log_debug(
                    f"experimentum_crucis: claim '{claim[:60]}' is unverifiable "
                    f"in SymbolGraph — inconclusive, returning None"
                )
                return None

            pos = self.positive_evidence(evidence)
            claim_true = (
                len(pos["symbols_confirmed"]) > 0 or len(pos["relations_confirmed"]) > 0
            )

            self._f._log_debug(
                f"experimentum_crucis: claim='{claim[:60]}', "
                f"supports={supports}, claim_true={claim_true}"
            )

            if claim_true and supports == "H1":
                return h1
            elif claim_true and supports == "H2":
                return h2
            elif not claim_true and supports == "H1":
                return h2
            elif not claim_true and supports == "H2":
                return h1
            return None

        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"find_experimentum_crucis: parse error — {response[:200]!r}"
            )
            return None

    async def delimit_scope(
        self,
        hypothesis: str,
        evidence: "StaticEvidence",
        design: "ExperimentDesign",
        project_id: str,
        peer_review: Optional["PeerReviewResult"] = None,
    ) -> str:
        """
        Dialectical synthesis (H6 — Hegelian).
        CONVERSATION LEVEL (H5).

            Thesis:     best_hypothesis (winner of compete_hypotheses)
            Antithesis: peer_review critiques + negative structural evidence
            Synthesis:  scoped hypothesis incorporating the tension

        By receiving peer_review BEFORE delimiting scope, the synthesis
        is genuinely informed by independent critique. The antithesis
        must precede the synthesis for the dialectic to function.

        If no negative evidence AND no critique exist, the hypothesis
        is returned unchanged (no scope needed).
        Gated by enable_scope_delimitation valve.
        """
        if not self._f.valves.enable_scope_delimitation:
            return hypothesis

        neg = self.negative_evidence(evidence)
        has_negative = bool(neg["symbols_missing"] or neg["relations_invalid"])
        has_critique = bool(
            peer_review
            and peer_review.verdict in ("REJECT", "QUALIFY")
            and peer_review.critiques
        )

        if not has_negative and not has_critique:
            self._f._log_debug(
                "delimit_scope: no antithesis material, hypothesis unchanged"
            )
            return hypothesis

        limitations_parts = []
        if has_negative:
            limitations_parts.append(
                f"Structural gaps: "
                f"symbols missing={neg['symbols_missing'][:3]}, "
                f"relations invalid={neg['relations_invalid'][:3]}"
            )

        if has_critique:
            limitations_parts.append(
                "Independent review: " + "; ".join(peer_review.critiques[:3])
            )
            reviewer_note = (
                f"(reviewed by {peer_review.reviewer_model})"
                if peer_review.is_external
                else "(internal review)"
            )
            limitations_parts.append(reviewer_note)

        limitations_str = "\n".join(limitations_parts)

        prompt = (
            f"Thesis (hypothesis to refine):\n{hypothesis}\n\n"
            f"Antithesis (structural limitations and critique):\n"
            f"{limitations_str}\n\n"
            f"Produce a synthesis: rewrite the hypothesis adding explicit "
            f"conditions of validity that acknowledge the antithesis.\n"
            f"Format: '[Original claim] (valid for [scope], "
            f"excluding [exceptions] because [reason]).'\n"
            f"Be concise. Do not weaken the core claim unnecessarily.\n\n"
            f'Output only: {{"scoped_hypothesis": "..."}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a dialectical synthesizer for software architecture "
                "hypotheses. Given a thesis and its antithesis, produce a "
                "synthesis that honestly incorporates both. "
                "Output ONLY a valid JSON object with key 'scoped_hypothesis'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=0,
            temperature=0.2,
            label="delimit_scope",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return hypothesis

        try:
            data = json.loads(response)
            scoped = str(data.get("scoped_hypothesis", "")).strip()
            if scoped:
                self._f._log_debug(
                    f"delimit_scope: dialectical synthesis produced "
                    f"({len(scoped)} chars)"
                )
                return scoped
            return hypothesis
        except (json.JSONDecodeError, Exception):
            return hypothesis

    async def _debrief_competition(
        self,
        scored_list: List["ScoredHypothesis"],
        final_score: float,
        coverage_score: float,
        score_trajectory: List[float],
        stagnated: bool,
        project_id: str,
    ) -> None:
        """
        Post-competition metacognitive analysis.
        PROJECT LEVEL (H5 temporal hierarchy).

        Extracts failure patterns from competition results using ONLY
        deterministic SymbolGraph-derived data:
        - falsification_reason strings (from is_falsified — deterministic)
        - coverage_score (mathematical ratio)
        - score_trajectory (obj_score per iteration — no llm_conf)

        No LLM calls. The SymbolGraph is the ground truth mirror.
        The LLM never evaluates itself — the graph evaluates the LLM.

        Results stored in _performance_history[project_id] and consumed
        by _get_adaptive_strategy() on the next competition call.
        """
        if not self._f.valves.enable_metacognitive_debriefing:
            return

        call_failures = 0
        symbol_failures = 0
        low_cov_count = 0

        for s in scored_list:
            if s.falsification_reason:
                if "relation" in s.falsification_reason:
                    call_failures += 1
                elif "symbol" in s.falsification_reason:
                    symbol_failures += 1
            if s.coverage_score < self._f.valves.low_coverage_threshold:
                low_cov_count += 1

        primary = "none"
        if call_failures > symbol_failures:
            primary = "call_relations"
        elif symbol_failures > call_failures:
            primary = "symbols"

        record = CompetitionRecord(
            timestamp=time.time(),
            n_hypotheses_initial=len(scored_list),
            n_falsified=sum(1 for s in scored_list if s.falsified),
            primary_falsification_type=primary,
            final_score=final_score,
            coverage_score=coverage_score,
            iterations_used=len(score_trajectory),
            stagnated=stagnated,
            score_trajectory=score_trajectory,
            call_relation_failures=call_failures,
            symbol_failures=symbol_failures,
            low_coverage_count=low_cov_count,
        )

        if project_id not in self._performance_history:
            self._performance_history[project_id] = []

        history = self._performance_history[project_id]
        history.append(record)

        if len(history) > 20:
            self._performance_history[project_id] = history[-20:]

        self._f._log_debug(
            f"_debrief_competition: project={project_id}, "
            f"primary_failure={primary}, coverage={coverage_score:.2f}, "
            f"stagnated={stagnated}, score={final_score:.3f}, "
            f"call_failures={call_failures}, symbol_failures={symbol_failures}"
        )

    def _get_adaptive_strategy(self, project_id: str) -> Dict[str, Any]:
        """
        Derive strategy adjustments from competition history.
        PROJECT LEVEL (H5 temporal hierarchy).

        All decisions are deterministic — based on statistical rates
        from CompetitionRecord fields, never on LLM self-assessment.

        Returns defaults if fewer than 3 records exist.
        """
        history = self._performance_history.get(project_id, [])

        _DEFAULTS: Dict[str, Any] = {
            "call_fail_rate": 0.0,
            "prefer_symbol_verification": False,
            "suggest_divergent_start": False,
            "avg_historical_coverage": 1.0,
        }

        if len(history) < 3:
            return _DEFAULTS

        recent = history[-10:]
        n = len(recent)

        call_fail_rate = (
            sum(1 for r in recent if r.primary_falsification_type == "call_relations")
            / n
        )

        symbol_fail_rate = (
            sum(1 for r in recent if r.primary_falsification_type == "symbols") / n
        )

        stagnation_rate = sum(1 for r in recent if r.stagnated) / n
        avg_coverage = sum(r.coverage_score for r in recent) / n

        strategy: Dict[str, Any] = {
            "call_fail_rate": call_fail_rate,
            "prefer_symbol_verification": False,
            "suggest_divergent_start": False,
            "avg_historical_coverage": avg_coverage,
        }

        if symbol_fail_rate < call_fail_rate * 0.5:
            strategy["prefer_symbol_verification"] = True
            self._f._log_debug(
                f"_get_adaptive_strategy: symbols more reliable "
                f"(symbol_fail={symbol_fail_rate:.2f} < "
                f"call_fail*0.5={call_fail_rate * 0.5:.2f})"
            )

        if stagnation_rate > 0.5:
            strategy["suggest_divergent_start"] = True
            self._f._log_debug(
                f"_get_adaptive_strategy: stagnation_rate={stagnation_rate:.2f} > 0.5 "
                f"→ suggest_divergent_start=True"
            )

        if call_fail_rate > 0.6:
            self._f._log_debug(
                f"_get_adaptive_strategy: call_fail_rate={call_fail_rate:.2f} > 0.6 "
                f"→ call-relation constraint will be injected"
            )

        return strategy

    # ═══════════════════════════════════════════════════════════════════════
    # 6. Peer review
    # ═══════════════════════════════════════════════════════════════════════

    async def challenge_hypothesis(
        self,
        hypothesis: str,
        evidence: "StaticEvidence",
        project_id: str,
    ) -> Optional[str]:
        """
        Devil's advocate — internal reviewer with contrarian prompt.

        ⚠️ LIMITATION: Uses the same model as the primary reasoner.
        LLMs are poor self-evaluators (overconfidence, hallucinated
        rationalizations). This method adds value only when the
        contrarian prompt forces structurally different angles based
        on evidence facts — NOT subjective quality assessment.

        The prompt is designed to elicit structural contradictions from
        the SymbolGraph, not opinions about reasoning quality.
        Gated by enable_devil_advocate valve.
        """
        if not self._f.valves.enable_devil_advocate:
            return None

        neg = self.negative_evidence(evidence)
        pos = self.positive_evidence(evidence)
        evidence_summary = (
            f"Confirmed: {pos['symbols_confirmed'][:5]}\n"
            f"Missing: {neg['symbols_missing'][:5]}\n"
            f"Invalid relations: {neg['relations_invalid'][:5]}"
        )

        prompt = (
            f"Hypothesis to challenge:\n{hypothesis}\n\n"
            f"Structural evidence:\n{evidence_summary}\n\n"
            f"Find the STRONGEST structural argument AGAINST this hypothesis:\n"
            f"1. What structural fact does the evidence directly contradict?\n"
            f"2. What simpler structural explanation exists?\n"
            f"3. What critical assumption is structurally unverifiable?\n\n"
            f'Output only: {{"has_flaw": true/false, "critique": "..."}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a devil's advocate for software architecture hypotheses. "
                "Find real structural flaws grounded in the evidence provided. "
                "Output ONLY a valid JSON object with 'has_flaw' (bool) and "
                "'critique' (string). "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.cot_model_level3,
            max_tokens=0,
            temperature=0.5,
            label="devil_advocate",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return None

        try:
            data = json.loads(response)
            if data.get("has_flaw", False):
                critique = str(data.get("critique", "")).strip()
                return critique if critique else None
            return None
        except (json.JSONDecodeError, Exception):
            return None

    def _format_raw_evidence_for_review(
        self,
        evidence: "StaticEvidence",
        design: "ExperimentDesign",
    ) -> str:
        """
        Format raw structural evidence for blind peer review.
        Intentionally excludes the primary reasoning chain to prevent
        anchoring bias in the reviewer model.
        """
        pos = self.positive_evidence(evidence)
        neg = self.negative_evidence(evidence)
        lines = [
            "CONFIRMED symbols: "
            + ", ".join(pos["symbols_confirmed"][:10] or ["none"]),
            "CONFIRMED relations: "
            + ", ".join(pos["relations_confirmed"][:10] or ["none"]),
            "MISSING symbols: " + ", ".join(neg["symbols_missing"][:10] or ["none"]),
            "INVALID relations: "
            + ", ".join(neg["relations_invalid"][:10] or ["none"]),
            "Recent changes: " + ", ".join(evidence.recent_changes[:5] or ["none"]),
            f"Objective score: {evidence.objective_score:.3f}",
        ]
        if design.critical_claims:
            lines.append("Critical claims: " + "; ".join(design.critical_claims[:5]))
        return "\n".join(lines)

    async def peer_review_hypothesis(
        self,
        hypothesis: str,
        evidence: "StaticEvidence",
        design: "ExperimentDesign",
        project_id: str,
    ) -> Optional["PeerReviewResult"]:
        """
        External peer review of the winning hypothesis.
        CONVERSATION LEVEL (H5).

        Three execution paths:

        Path 1 — enable_peer_review=False:
            Returns None. Synthesis unaffected.

        Path 2 — same model or no model set:
            Degrades to challenge_hypothesis() (devil's advocate).
            Returns PeerReviewResult(is_external=False).

        Path 3 — different model (genuine peer review):
            Blind review — context excludes primary reasoning chain
            to prevent anchoring bias.
            Returns PeerReviewResult(is_external=True).

        Designed for future activation — peer_review_model is expected
        to be empty under current hardware constraints.
        """
        if not self._f.valves.enable_peer_review:
            return None

        _fallback_approve = PeerReviewResult(
            verdict="APPROVE", critiques=[], reviewer_model="", is_external=False
        )

        _same_model = (
            not self._f.valves.peer_review_model
            or self._f.valves.peer_review_model == self._f.valves.cot_model_level3
        )

        if _same_model:
            self._f._log_debug(
                "peer_review: degrading to devil's advocate "
                "(peer_review_model not set or identical to cot_model_level3)"
            )
            critique = await self.challenge_hypothesis(hypothesis, evidence, project_id)
            return PeerReviewResult(
                verdict="QUALIFY" if critique else "APPROVE",
                critiques=[critique] if critique else [],
                reviewer_model="internal_devil_advocate",
                is_external=False,
            )

        self._f._log_debug(
            f"peer_review: using external model "
            f"'{self._f.valves.peer_review_model}'"
        )
        await self._f._emit_status(
            f"🔍 Peer review with {self._f.valves.peer_review_model}..."
        )

        evidence_summary = self._format_raw_evidence_for_review(evidence, design)

        prompt = (
            f"Hypothesis under review:\n{hypothesis}\n\n"
            f"Verified structural evidence from the codebase:\n"
            f"{evidence_summary}\n\n"
            f"Find structural flaws:\n"
            f"1. Does the hypothesis assume relations the evidence contradicts?\n"
            f"2. Does it ignore critical symbols present in the evidence?\n"
            f"3. Is there a simpler structural explanation?\n\n"
            f'Output only the JSON object, e.g. {{"verdict": "QUALIFY", '
            f'"critiques": ["X calls Y but edge not found"]}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are an independent software architecture auditor. "
                "You have NOT seen the reasoning that generated this hypothesis — "
                "only the hypothesis and raw structural evidence. "
                "Output ONLY a valid JSON object with 'verdict' "
                "(APPROVE | REJECT | QUALIFY) and 'critiques' (list of strings). "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.peer_review_model,
            max_tokens=0,
            temperature=0.0,
            label="peer_review_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return PeerReviewResult(
                verdict="APPROVE",
                critiques=[],
                reviewer_model=self._f.valves.peer_review_model,
                is_external=True,
            )

        try:
            data = json.loads(response)
            raw_verdict = str(data.get("verdict", "APPROVE")).strip().upper()
            if raw_verdict not in ("APPROVE", "REJECT", "QUALIFY"):
                raw_verdict = "APPROVE"
            result = PeerReviewResult(
                verdict=raw_verdict,
                critiques=[str(c) for c in data.get("critiques", []) if c],
                reviewer_model=self._f.valves.peer_review_model,
                is_external=True,
            )
            self._f._log_debug(
                f"peer_review: verdict={result.verdict}, "
                f"critiques={len(result.critiques)}"
            )
            return result
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(f"peer_review: parse error — {response[:200]!r}")
            return PeerReviewResult(
                verdict="APPROVE",
                critiques=[],
                reviewer_model=self._f.valves.peer_review_model,
                is_external=True,
            )

    # ═══════════════════════════════════════════════════════════════════════
    # 7. QueryDecomposition (Capa 1)
    # ═══════════════════════════════════════════════════════════════════════

    async def decompose_questions(
        self,
        user_content: str,
        project_id: str,
    ) -> List[str]:
        """
        Detect independent questions in user_content.
        Gated by enable_query_decomposition valve.

        Cascade: Heuristic → CrossEncoder → LLM fallback.

        Conservative by design: false negative (misses 2 questions) =
        current behaviour. False positive (upgrades unnecessarily) =
        latency overhead.

        Returns:
            [user_content]   — single question (no decomposition)
            [Q1, Q2, ...]    — confirmed independent questions
        """
        if not self._f.valves.enable_query_decomposition:
            return [user_content]

        clean = self._f._commands._extract_text_for_classification(user_content)
        if not clean or "[CODE ONLY" in clean:
            return [user_content]

        candidates = self._detect_question_segments(clean)
        if len(candidates) < 2:
            return [user_content]

        return await self._confirm_independence_ce(candidates, user_content, project_id)

    def _detect_question_segments(self, clean: str) -> List[str]:
        """
        Heuristic detection of candidate question segments.
        Conservative — only strong, unambiguous signals qualify.

        Signal 1 (most reliable):
            Paragraphs separated by blank line, each containing '?'.
        Signal 2:
            Multiple ¿...? openers (Spanish).

        NOT a signal: multiple '?' in the same paragraph (too ambiguous).
        """
        max_q = self._f.valves.query_decomposition_max_questions

        paragraphs = [p.strip() for p in re.split(r"\n\s*\n", clean) if p.strip()]
        q_paragraphs = [p for p in paragraphs if "?" in p and len(p) > 15]
        if len(q_paragraphs) >= 2:
            return q_paragraphs[:max_q]

        spanish_questions = re.findall(r"¿[^¿?]+\?", clean)
        if len(spanish_questions) >= 2:
            return spanish_questions[:max_q]

        return [clean]

    async def _confirm_independence_ce(
        self,
        candidates: List[str],
        original: str,
        project_id: str,
    ) -> List[str]:
        """
        CrossEncoder confirms candidates are genuinely independent.
        LLM fallback if CE diff is below threshold.
        Middle zone → conservative (return [original]).
        Guards against malformed CE scores (None or len < 2).
        """
        if len(candidates) < 2:
            return [original]

        for i in range(len(candidates) - 1):
            qa, qb = candidates[i], candidates[i + 1]
            combined = f"{qa} [SEP] {qb}"

            pairs = [
                (
                    combined,
                    "These are independent questions requiring completely different "
                    "contexts to answer.",
                ),
                (
                    combined,
                    "These are related questions about the same topic that build "
                    "on each other.",
                ),
            ]

            scores = await self._f._commands._predict_cross_encoder(pairs)

            # Guard: CE unavailable or malformed response
            if scores is None or len(scores) < 2:
                self._f._log_debug(
                    "decompose_questions: CE unavailable or malformed scores "
                    f"(scores={scores}), trusting heuristic"
                )
                continue

            diff = scores[0] - scores[1]
            ce_threshold = self._f.valves.query_decomposition_ce_threshold
            llm_threshold = self._f.valves.query_decomposition_llm_threshold

            if diff >= ce_threshold:
                self._f._log_debug(
                    f"decompose_questions: CE confirms independence "
                    f"(diff={diff:.2f})"
                )
                continue
            elif diff < llm_threshold:
                self._f._log_debug(
                    f"decompose_questions: CE uncertain (diff={diff:.2f}), "
                    f"using LLM"
                )
                confirmed = await self._confirm_independence_llm(
                    qa, qb, scores, project_id
                )
                if not confirmed:
                    return [original]
            else:
                self._f._log_debug(
                    f"decompose_questions: middle zone (diff={diff:.2f}), "
                    f"treating as single question"
                )
                return [original]

        self._f._log_debug(
            f"decompose_questions: {len(candidates)} independent questions confirmed"
        )
        return candidates

    async def _confirm_independence_llm(
        self,
        qa: str,
        qb: str,
        ce_scores: list,
        project_id: str,
    ) -> bool:
        """LLM fallback for independence confirmation. Conservative on failure."""
        prompt = (
            f"CrossEncoder scores — "
            f"independent: {ce_scores[0]:.2f}, related: {ce_scores[1]:.2f}\n\n"
            f"Question A:\n{qa[:300]}\n\n"
            f"Question B:\n{qb[:300]}\n\n"
            f"Can Question A be answered completely WITHOUT knowing the answer "
            f"to Question B, AND vice versa?\n"
            f"Only answer true if both questions address genuinely different "
            f"topics or code areas.\n\n"
            f'Output only: {{"independent": true}} or {{"independent": false}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are an independence classifier for user questions. "
                "Output ONLY a valid JSON object with boolean field 'independent'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="decompose_questions_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
        )

        if self._f.valves.enable_slot_persistence and project_id:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return False

        try:
            data = json.loads(response)
            result = bool(data.get("independent", False))
            self._f._log_debug(f"decompose_questions LLM: independent={result}")
            return result
        except (json.JSONDecodeError, Exception):
            return False

    # ═══════════════════════════════════════════════════════════════════════
    # 8. FocalReasoning (Layer 2)
    # ═══════════════════════════════════════════════════════════════════════

    async def reason_per_focus(
        self,
        questions: List[str],
        project_id: str,
        cot_level: int,
        prelim_system: str,
    ) -> List[Tuple[str, str]]:
        """
        FocalReasoning: separate volatile activation + CoT per question.
        CONVERSATION LEVEL (H5). Gated by enable_focal_reasoning valve.

        Each iteration:
            slot_save()                              — isolate from open_webui.main state
            build_activation_graph(persist=False)   — volatile, no side effects
            _build_volatile_context()               — read-only, no side effects
            generate_cot_reasoning()                — LLM call
            slot_restore_for_continuity()           — restore main state

        If a question fails, it is skipped (not fatal).
        "Unable to generate reasoning." is treated as failure (not added to results).
        """
        if not self._f.valves.enable_focal_reasoning:
            return []

        _COT_ERROR = "Unable to generate reasoning."
        per_q_level = min(cot_level, self._f.valves.focal_reasoning_max_level)
        results: List[Tuple[str, str]] = []

        for i, question in enumerate(questions):
            await self._f._emit_status(
                f"🔍 Analyzing question {i + 1}/{len(questions)}: "
                f"{question[:60]}{'...' if len(question) > 60 else ''}"
            )
            try:
                if self._f.valves.enable_slot_persistence:
                    await self._f._project_state_manager.slot_save(project_id)

                ag = await self._f._activation.build_activation_graph(
                    question, project_id, persist=False
                )
                context = self._build_volatile_context(ag, project_id, prelim_system)

                if self._f.valves.enable_slot_persistence:
                    await self._f._project_state_manager.slot_restore_for_continuity(
                        project_id
                    )

                if per_q_level < 2:
                    continue

                await self._f._emit_status(
                    f"💭 Reasoning about question {i + 1}/{len(questions)}..."
                )

                reasoning = await self._f._reasoning.generate_cot_reasoning(
                    question, context
                )

                # Guard: error string is truthy but not valid reasoning
                if reasoning and reasoning != _COT_ERROR:
                    results.append((question, reasoning))
                    self._f._log_debug(
                        f"reason_per_focus: Q{i + 1} reasoning generated "
                        f"({len(reasoning)} chars)"
                    )
                else:
                    self._f._log_debug(
                        f"reason_per_focus: Q{i + 1} returned error or empty"
                    )

            except Exception as e:
                self._f._log_debug(
                    f"reason_per_focus: Q{i + 1} failed (non-fatal) — {e}"
                )
                if self._f.valves.enable_slot_persistence:
                    try:
                        await self._f._project_state_manager.slot_restore_for_continuity(
                            project_id
                        )
                    except Exception:
                        pass
                continue

        self._f._log_debug(
            f"reason_per_focus: {len(results)}/{len(questions)} questions reasoned"
        )
        return results

    def _build_volatile_context(
        self,
        ag: "ActivationGraph",
        project_id: str,
        prelim_system: str,
    ) -> str:
        """
        Build a context string for a specific ActivationGraph.

        ZERO side effects:
        - Read-only access to active_blocks.
        - Does NOT call ContextBuilder.build_block_b.
        - Does NOT modify _last_activation_scores.
        - Does NOT invalidate any cache.

        Falls back to prelim_system[:2000] when no blocks are activated.
        """
        state = self._f._conversation_state_manager.get(project_id)
        if not state or not state.active_blocks:
            return prelim_system[:2000]

        activated = ag.get_activated_nodes(
            threshold=self._f.valves.path_activation_threshold
        )
        if not activated:
            return prelim_system[:2000]

        relevant_blocks: List[Tuple[float, "CodeBlock"]] = []
        seen_hashes: set = set()

        for qid, score in sorted(activated.items(), key=lambda x: x[1], reverse=True)[
            :10
        ]:
            block_hashes = self._f._symbol_index.find_blocks(qid, project_id)
            for bh in block_hashes:
                if bh in seen_hashes:
                    continue
                block = state.active_blocks.get(bh)
                if block and not block.obsolete:
                    relevant_blocks.append((score, block))
                    seen_hashes.add(bh)
                    break

        if not relevant_blocks:
            return prelim_system[:2000]

        parts = ["## Context for this question (top activated symbols):\n"]
        for score, block in sorted(relevant_blocks, key=lambda x: x[0], reverse=True)[
            :5
        ]:
            lang = block.symbols[0].language if block.symbols else ""
            snippet = block.content[:600]
            if len(block.content) > 600:
                snippet += "\n# ... [truncated]"
            parts.append(f"```{lang}\n{snippet}\n```")

        return "\n\n".join(parts)

    def synthesize_focal_reasoning(
        self,
        per_question: List[Tuple[str, str]],
    ) -> str:
        """
        Combine N per-question reasonings into a structured block.
        No LLM call — pure concatenation.

        Empty → "" (caller falls back to unified reasoning).
        Single → returns that reasoning directly.
        Multiple → structured with question headers and separators.
        """
        if not per_question:
            return ""
        if len(per_question) == 1:
            return per_question[0][1]

        parts = []
        for i, (question, reasoning) in enumerate(per_question):
            header = f"### Question {i + 1}: {question[:120]}"
            if len(question) > 120:
                header += "..."
            parts.append(f"{header}\n\n{reasoning}")

        return "\n\n---\n\n".join(parts)


class HistoryCompressor:
    """
    Compresses conversation history and code blocks to keep the token
    budget under control without losing essential information.

    Provides:
    * ``compress_code_history(messages, project_id)`` — replaces old
      multi‑phase code parts with compact commit summaries when their
      symbols are safely indexed in the SymbolGraph.
    * ``lean_user_code_messages(messages, project_id)`` — replaces large
      code blocks in user messages with stubs when the SymbolGraph already
      covers every symbol, avoiding redundant token consumption.
    * ``compress_code_block(code, language, rate, query)`` — applies
      LLMLingua‑2 compression to a single code block, preserving structural
      tokens and optionally conditioning on the user's question.
    * ``summarize_messages(old_messages, is_code_context)`` — produces a
      single‑paragraph summary of trimmed conversation turns.
    * ``build_refactor_state_injection(messages)`` — builds a compact
      "Refactor Status" block from compressed code parts so the model knows
      what has already been written.
    * ``schedule_block_summary(block, project_id)`` — fire‑and‑forget
      background task that generates a summary for an oversized code block.
    * ``check_and_suggest_summarization(project_id, ...)`` — returns a
      proactive suggestion when the conversation is approaching the token
      window limit.

    Docs 10–13 backported:
        B5 – force‑compressed keys survive restarts via persistent set.
    """

    # ── Q4: Commit summary prompt ──────────────────────────────────────────
    COMMIT_SUMMARY_PROMPT = """\
You are summarizing a coding decision for long-term context compression.
Respond ONLY with a JSON object, no preamble, no markdown fences.

{
  "action": "<verb phrase: what was done, ≤15 words>",
  "rationale": "<why this approach: the constraint, tradeoff, or requirement that drove the decision, ≤20 words, or null if not stated>",
  "symbols": ["<fully_qualified_symbol_1>", "<fully_qualified_symbol_2>"]
}

User message to summarize:
\"\"\"
{user_message}
\"\"\"

Code context (recent symbols referenced):
{symbols_context}
"""

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the HistoryCompressor with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._f = filter_ref
        # block.hash -> in-flight background summary task, to avoid firing
        # a second summary attempt for the same block while one is pending.
        self._pending_block_summaries: Set[str] = set()
        self._summarizing_blocks: Set[str] = set()

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Code history compression (multi‑phase code parts → summaries)
    # ═══════════════════════════════════════════════════════════════════════

    async def compress_code_history(
        self,
        messages: list,
        project_id: str,
    ) -> list:
        """
        Replace code-dump assistant messages with compact commit-summary stubs.

        Only assistant messages that contain code indicators, meet the minimum
        character threshold, and have their symbols already indexed are replaced.
        All other messages pass through unchanged.

        Steps:
            1.  Defensive copy — the caller's list is never modified in place.
            2.  Early exits: compression disabled, state missing, no candidates.
            3.  Count total code-bearing assistant turns for part numbering.
            4.  Iterate messages: non-candidates pass through directly.
            5.  For each candidate verify symbol coverage, then call
                _build_code_commit_summary.
            6.  On success replace with the summary dict; on failure keep original.
        """
        # -- Step 1: defensive copy --
        messages = list(messages)

        # -- Step 2: early exits --
        if not self._f.valves.enable_code_history_compression:
            return messages

        state = self._f._conversation_state_manager.get(project_id)
        if not state:
            return messages

        min_chars = self._f.valves.compress_code_history_min_chars

        # -- Step 3: count total code-bearing assistant turns --
        total_parts = sum(
            1
            for m in messages
            if m.get("role") == "assistant"
            and self._f._code_blocks.has_code_indicators(m.get("content", ""))
            and len(m.get("content", "")) >= min_chars
        )
        if total_parts == 0:
            return messages

        # -- Steps 4-6: iterate and replace --
        result: List[dict] = []
        part_num = 0

        for msg in messages:
            role = msg.get("role", "")
            content = msg.get("content", "")

            is_candidate = (
                role == "assistant"
                and self._f._code_blocks.has_code_indicators(content)
                and len(content) >= min_chars
            )

            if not is_candidate:
                result.append(msg)
                continue

            part_num += 1
            is_indexed, coverage = self._verify_code_symbols_indexed(
                content, project_id
            )

            if not is_indexed:
                result.append(msg)
                continue

            force_no_expand = coverage < self._f.valves.compress_coverage_threshold

            try:
                summary = await self._build_code_commit_summary(
                    content,
                    project_id,
                    part_num,
                    total_parts,
                    force_no_expand=force_no_expand,
                )
            except Exception as e:
                self._f._log_debug(
                    f"compress_code_history: summary failed for part "
                    f"{part_num}/{total_parts}: {type(e).__name__}: {e}"
                )
                summary = None

            if summary:
                result.append({"role": "assistant", "content": summary})
            else:
                result.append(msg)

        self._f._log_debug(
            f"compress_code_history: {part_num} candidate(s) processed, "
            f"{sum(1 for m in result if '[commit]' in m.get('content','').lower())} "
            f"compressed"
        )
        return result

    def _verify_code_symbols_indexed(
        self, content: str, project_id: str
    ) -> Tuple[bool, float]:
        """
        Verify that code symbols in the content are indexed in the SymbolGraph.
        Returns (is_indexed, ratio).
        """
        _TOP_LEVEL = re.compile(r"^class\s+([A-Za-z_][A-Za-z0-9_]*)", re.MULTILINE)
        expected = set(_TOP_LEVEL.findall(content))
        if not expected:
            _TOP_FN = re.compile(
                r"^(?:async )?def\s+([A-Za-z_][A-Za-z0-9_]*)", re.MULTILINE
            )
            expected = set(_TOP_FN.findall(content))
        if not expected:
            return True, 1.0

        try:
            graph_symbols = self._f._symbol_index.get_all_names(project_id)
            ratio = len(expected & graph_symbols) / len(expected)
            return ratio >= self._f.valves.code_history_symbol_index_threshold, ratio
        except Exception as exc:
            self._f._log_debug(f"Symbol index check failed: {exc}")
            return False, 0.0

    # ── Q4: Commit summary builder with rationale ──────────────────────────

    def _parse_commit_summary_response(self, raw: str) -> dict:
        """
        Parse the LLM response for a commit summary.

        With response_format={"type":"json_object"} and enable_thinking=False,
        the server-side GBNF grammar guarantees the response is valid JSON
        starting with { and ending with }. No artifact stripping is needed.

        Falls back to a minimal dict on any parse failure so the caller can
        always safely access 'action', 'rationale', and 'symbols'.

        Args:
            raw: Raw LLM response string.

        Returns:
            dict: Parsed summary with keys action (str), rationale (str),
                  symbols (list[str]). Empty strings/lists on failure.
        """
        try:
            data = json.loads(raw)
            return {
                "action": str(data.get("action", "")).strip(),
                "rationale": str(data.get("rationale", "")).strip(),
                "symbols": [str(s) for s in data.get("symbols", []) if s],
            }
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_parse_commit_summary_response: JSON parse error — "
                f"response: {raw[:200]!r}"
            )
            return {"action": "", "rationale": "", "symbols": []}

    def _render_commit_summary(self, summary: dict, turn: int) -> str:
        """
        Render a commit summary for insertion into compressed history.

        Format:
            [T{turn}] {action}
              Rationale: {rationale}
              Symbols: {symbols}
        """
        action = summary.get("action", "unknown action")
        rationale = summary.get("rationale")
        symbols = summary.get("symbols", [])

        lines = [f"[T{turn}] {action}"]
        if rationale:
            lines.append(f"  Rationale: {rationale}")
        if symbols:
            lines.append(f"  Symbols: {', '.join(symbols)}")

        return "\n".join(lines)

    async def _build_code_commit_summary(
        self,
        content: str,
        project_id: str,
        part_num: int,
        total_parts: int,
        force_no_expand: bool = False,
    ) -> str:
        """
        Generate a compact commit summary for a compressed code message.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        to get a guaranteed clean JSON object with keys: action, rationale,
        symbols. Falls back to _build_legacy_commit_summary on any failure.

        Args:
            content: The code message content (truncated to 2000 chars in prompt).
            project_id: Current project identifier, used for slot restoration.
            part_num: The part number within a multi-phase message.
            total_parts: Total number of parts.
            force_no_expand: If True, skip LLM and use legacy summary directly.

        Returns:
            str: A rendered commit summary string.
        """
        if force_no_expand:
            return self._build_legacy_commit_summary(
                content, part_num, total_parts, force_no_expand=True
            )

        # Extract top symbols to give the LLM structural context.
        classes = re.findall(r"^class\s+([A-Za-z_]\w*)", content, re.MULTILINE)
        top_fns = re.findall(r"^(?:async )?def\s+([A-Za-z_]\w*)", content, re.MULTILINE)
        methods = re.findall(
            r"^\s{4,}(?:async )?def\s+([A-Za-z_]\w*)", content, re.MULTILINE
        )
        symbols = (classes + top_fns + methods)[:5]

        prompt = self.COMMIT_SUMMARY_PROMPT.format(
            user_message=content[:2000],
            symbols_context=", ".join(symbols) if symbols else "none",
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a code summarization assistant. "
                "Output ONLY a valid JSON object with exactly three keys: "
                "'action' (string: one-line description of what changed), "
                "'rationale' (string: why this change matters), "
                "'symbols' (list of strings: affected symbol names). "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.2,
            label="commit_summary",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        if self._f.valves.enable_slot_persistence:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return self._build_legacy_commit_summary(
                content, part_num, total_parts, force_no_expand=False
            )

        summary = self._parse_commit_summary_response(response)
        if not summary.get("action"):
            summary["action"] = "code change"
        summary["part_num"] = part_num
        summary["total_parts"] = total_parts
        return self._render_commit_summary(summary, turn=part_num)

    def _build_legacy_commit_summary(
        self,
        content: str,
        part_num: int,
        total_parts: int,
        force_no_expand: bool = False,
    ) -> str:
        """
        Legacy commit summary builder (fallback when LLM is unavailable
        or when force_no_expand is True).
        """
        classes = re.findall(r"^class\s+([A-Za-z_]\w*)", content, re.MULTILINE)
        top_fns = re.findall(r"^(?:async )?def\s+([A-Za-z_]\w*)", content, re.MULTILINE)
        methods = re.findall(
            r"^\s{4,}(?:async )?def\s+([A-Za-z_]\w*)", content, re.MULTILINE
        )

        code_bodies = re.findall(r"```(?:\w*)\n(.*?)```", content, re.DOTALL)
        code_lines = sum(b.count("\n") for b in code_bodies)
        code_tokens = (
            self._f._tokens.estimate_tokens("\n".join(code_bodies))
            if code_bodies
            else 0
        )

        header_m = re.search(
            r"##\s*Código\s*[—\-]\s*Parte\s*\d+/\d+[:\s]+(.+?)(?:\n|$)", content
        )
        part_label = header_m.group(1).strip() if header_m else ""

        imports = re.findall(r"^from\s+\S+\s+import\s+(.+)$", content, re.MULTILINE)
        dep_symbols: List[str] = []
        for imp in imports[:3]:
            dep_symbols.extend(s.strip() for s in imp.split(","))
        dep_symbols = dep_symbols[:6]

        if force_no_expand:
            title = f"[🗜️ CÓDIGO COMPRIMIDO — sin índice]"
            lines = [title]
            if classes:
                lines.append(f"Clases:    {', '.join(classes)}")
            if top_fns:
                lines.append(f"Funciones: {', '.join(top_fns[:6])}")
            if methods:
                lines.append(f"Métodos:   {len(methods)} implementados")
            lines.append(f"Volumen:   ~{code_lines} líneas / ~{code_tokens} tokens")
            if dep_symbols:
                lines.append(f"Deps usadas: {', '.join(dep_symbols)}")
            lines.append(
                "[CÓDIGO NO INDEXADO — la implementación no es recuperable via /expand]"
            )
            return "\n".join(lines)

        title = f"[🗜️ PARTE {part_num}/{total_parts}"
        if part_label:
            title += f": {part_label}"
        title += " — COMPRIMIDO]"

        lines = [title]
        if classes:
            lines.append(f"Clases:    {', '.join(classes)}")
        if top_fns:
            lines.append(f"Funciones: {', '.join(top_fns[:6])}")
        if methods:
            lines.append(f"Métodos:   {len(methods)} implementados")
        lines.append(f"Volumen:   ~{code_lines} líneas / ~{code_tokens} tokens")
        if dep_symbols:
            lines.append(f"Deps usadas: {', '.join(dep_symbols)}")
        if classes:
            lines.append(f"Recuperar: /expand {classes[0]}")
        lines.append(
            "[Todos los símbolos indexados en SymbolGraph — accesibles via LOD]"
        )

        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Lean user code compression (replace large user code blocks with stubs)
    # ═══════════════════════════════════════════════════════════════════════

    def _build_user_stub(self, symbol_count: int) -> str:
        """
        Generate a stub message for a large user code block.

        This stub is used both during silent ingestion and in the normal
        message compression flow. It informs the model that the code is
        already indexed and available via /expand, avoiding redundant
        token consumption.

        Args:
            symbol_count (int): Number of symbols currently indexed in the SymbolGraph.

        Returns:
            str: The stub text, ready for injection into the conversation history.
        """
        return (
            f"_(The code is internally available; no need to repeat it here.)_\n\n"
            f"_[{symbol_count} symbols indexed in SymbolGraph. Use /expand <name> to see any implementation.]_"
        )

    def ensure_compressed_user_messages(
        self,
        messages: list,
        state: "ConversationState",
        project_id: str,
    ) -> list:
        """
        Replace large user messages with compact stubs in the message list
        to reduce history token usage before context assembly.

        Returns a NEW list; the caller's list and message dicts are never
        modified in place. Without this guarantee, two callers that hold
        references to the same messages list (e.g. inlet and outlet) see
        content replaced under them.

        Compression tracking uses MD5 hashes (stored in state.compressed_user_messages
        as a set of hash strings) rather than full content strings. This is
        O(1) per lookup instead of O(content_len) and survives state reload
        because hashes are short and JSON-serialisable. Without hash-based
        tracking, a state eviction from the LRU cache resets compressed_user_messages
        to [] and all previously compressed messages are re-compressed on the
        next turn, producing double-stubs ("Code uploaded. [Code uploaded.]").

        Steps:
            1.  Resolve compression threshold from valves.
            2.  Ensure compressed_user_messages is a set of hash strings
                (migrate from list-of-content if needed).
            3.  Iterate messages; build a new list with replacements where needed.
            4.  Return the new list.
        """
        min_chars = getattr(self._f.valves, "compress_user_message_min_chars", 1500)

        # -- Step 1: check if feature is enabled --
        if not getattr(self._f.valves, "enable_compressed_user_messages", True):
            return messages

        # -- Step 2: migrate / normalise compression tracker to set of hashes --
        raw_tracker = getattr(state, "compressed_user_messages", None)
        if raw_tracker is None:
            compressed_hashes: set = set()
            state.compressed_user_messages = []
        elif isinstance(raw_tracker, list):
            # Migrate: entries may be full content strings (old format) or hashes.
            compressed_hashes = set()
            for entry in raw_tracker:
                if isinstance(entry, str) and len(entry) == 32:
                    compressed_hashes.add(entry)  # already a hash
                elif isinstance(entry, str):
                    compressed_hashes.add(
                        hashlib.md5(entry.encode("utf-8", errors="replace")).hexdigest()
                    )
            # Rewrite in normalised hash format
            state.compressed_user_messages = list(compressed_hashes)
        else:
            compressed_hashes = set(raw_tracker)

        # -- Step 3: build replacement list --
        new_messages: List[dict] = []
        dirty = False

        for msg in messages:
            role = msg.get("role", "")
            content = msg.get("content") or ""

            should_compress = (
                role == "user"
                and isinstance(content, str)
                and len(content) >= min_chars
                and self._f._code_blocks.has_code_indicators(content)
            )

            if should_compress:
                content_hash = hashlib.md5(
                    content.encode("utf-8", errors="replace")
                ).hexdigest()

                if content_hash not in compressed_hashes:
                    # First time seeing this content — compress it
                    symbol_count = len(
                        [
                            s
                            for bh, blk in (
                                self._f._conversation_state_manager.get(
                                    project_id
                                ).active_blocks.items()
                                if self._f._conversation_state_manager.get(project_id)
                                else {}
                            ).items()
                            for s in blk.symbols
                        ]
                    )
                    stub = self._build_user_stub(symbol_count)
                    new_messages.append({**msg, "content": stub})
                    compressed_hashes.add(content_hash)
                    dirty = True
                else:
                    # Already compressed in a prior turn — keep as stub
                    symbol_count = 0
                    new_messages.append(
                        {**msg, "content": self._build_user_stub(symbol_count)}
                    )
            else:
                new_messages.append(msg)

        # -- Step 4: persist updated tracker if modified --
        if dirty:
            state.compressed_user_messages = list(compressed_hashes)
            self._f._conversation_state_manager.mark_dirty(project_id)

        return new_messages

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Refactor state injection
    # ═══════════════════════════════════════════════════════════════════════

    def build_refactor_state_injection(self, messages: list) -> str:
        """
        Build a compact "Estado del Refactor" block from compressed code parts
        in conversation history.

        Injected into Block B when active multi-phase compression is detected.
        Gives the model awareness of what has been written without reading full messages.

        Returns empty string if no compressed parts found (no injection needed).
        """
        _COMPRESSED = re.compile(r"\[🗜️ PARTE (\d+)/(\d+)(?:: (.+?))? — COMPRIMIDO\]")

        completed: List[Tuple[int, str]] = []
        total_parts: Optional[int] = None

        for msg in messages:
            if msg.get("role") != "assistant":
                continue
            m = _COMPRESSED.search(msg.get("content", ""))
            if m:
                num = int(m.group(1))
                total = int(m.group(2))
                label = m.group(3) or f"Parte {num}"
                completed.append((num, label))
                total_parts = total

        if not completed or not total_parts:
            return ""

        done_nums = {n for n, _ in completed}
        pending = [i for i in range(1, total_parts + 1) if i not in done_nums]

        lines = ["## 📊 Estado del Refactor en Progreso"]
        for num, label in sorted(completed):
            lines.append(
                f"  ✓ Parte {num}/{total_parts}: {label} [indexado en SymbolGraph]"
            )
        for num in pending:
            lines.append(f"  ⏳ Parte {num}/{total_parts}: [pendiente]")
        lines.append(
            "Los símbolos de las partes completadas están disponibles via LOD "
            "(firmas en este prompt) o /expand para implementación completa."
        )

        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════
    # 4. LLMLingua‑2 code block compression
    # ═══════════════════════════════════════════════════════════════════════

    async def compress_code_block(
        self,
        code: str,
        language: str = "python",
        rate: float = 0.5,
        query: str = "",
    ) -> str:
        """
        Compress a code block using LLMLingua-2.
        Preserves critical language structural tokens.

        If `query` is not empty and enable_question_aware_compression=True,
        uses LongLLMLingua conditioned on the query: the compressor preserves
        tokens relevant to the specific question.

        rate: fraction of tokens to KEEP (0.5 = keep 50%).
        Recommended range: 0.4 (aggressive) to 0.7 (conservative).

        Returns the original code if the compressor is unavailable
        or the block is below the minimum token threshold.
        """
        _raw = self._f._conv_compressor.raw if self._f._conv_compressor else None
        if not _raw:
            return code

        estimated_tokens = self._f._tokens.estimate_code_tokens(code)
        if estimated_tokens < self._f.valves.code_compression_min_tokens:
            return code

        FORCE_TOKENS_BY_LANG = {
            "python": [
                "\n",
                ":",
                "def ",
                "class ",
                "return ",
                "import ",
                "from ",
                "if ",
                "else:",
                "elif ",
                "for ",
                "while ",
                "try:",
                "except",
                "with ",
                "async ",
                "await ",
            ],
            "javascript": [
                "\n",
                ":",
                "function ",
                "const ",
                "let ",
                "var ",
                "return ",
                "class ",
                "import ",
                "export ",
                "=>",
                "if ",
                "else ",
                "for ",
                "while ",
            ],
            "typescript": [
                "\n",
                ":",
                "function ",
                "const ",
                "let ",
                "var ",
                "return ",
                "class ",
                "import ",
                "export ",
                "=>",
                "interface ",
                "type ",
                "if ",
                "else ",
                "for ",
            ],
            "go": [
                "\n",
                ":",
                "func ",
                "type ",
                "struct ",
                "import ",
                "return ",
                "if ",
                "else ",
                "for ",
                "package ",
            ],
            "rust": [
                "\n",
                ":",
                "fn ",
                "struct ",
                "impl ",
                "use ",
                "return ",
                "if ",
                "else ",
                "for ",
                "let ",
                "pub ",
            ],
        }
        force_tokens = FORCE_TOKENS_BY_LANG.get(
            language.lower(), ["\n", ":", "return "]
        )

        try:
            compress_kwargs = {
                "rate": rate,
                "force_tokens": force_tokens,
                "force_reserve_digit": True,
            }
            if query and self._f.valves.enable_question_aware_compression:
                compress_kwargs["question"] = query[:300]
                self._f._log_debug(
                    f"LLMLingua-2: question-aware mode active "
                    f"(query={query[:60]}...)"
                )

            result = await anyio.to_thread.run_sync(
                lambda: _raw.compress_prompt(code, **compress_kwargs)
            )
            compressed = result.get("compressed_prompt", code)
            compressed_tokens = self._f._tokens.estimate_code_tokens(compressed)
            self._f._log_debug(
                f"LLMLingua-2: {estimated_tokens} → {compressed_tokens} tokens "
                f"({100*(1-compressed_tokens/max(estimated_tokens,1)):.0f}% reduction)"
            )
            return compressed
        except Exception as e:
            self._f._log_debug(f"LLMLingua-2 compression failed: {e} — using original")
            return code

    # ═══════════════════════════════════════════════════════════════════════
    # 5. Message summarization (for trimmed old messages)
    # ═══════════════════════════════════════════════════════════════════════

    async def summarize_messages(
        self,
        old_messages: list,
        is_code_context: bool = False,
    ) -> Optional[str]:
        """
        Generate a concise natural-language summary of a batch of conversation
        messages, suitable for inclusion in conversation_summaries as an L1 entry.

        Used by WindowManager when it evicts a batch of turns to free token budget.
        The summary should preserve the semantic content of the batch so the LLM
        can reason about earlier context without re-reading the full messages.

        Steps:
            1.  Guard empty or effectively-empty input — return None immediately
                rather than sending a vacuous prompt to the LLM.
            2.  Sanitize message content: replace None with empty string, strip
                nulls and control characters.
            3.  Build the conversation transcript, skipping empty messages.
            4.  Guard: if the sanitized transcript is empty, return None.
            5.  Build prompt with code-context hint if applicable.
            6.  Call LLM with a tight token budget.
            7.  Return cleaned summary or None on failure.
        """
        # -- Step 1: empty input guard --
        if not old_messages:
            self._f._log_debug(
                "summarize_messages: called with empty message list, returning None"
            )
            return None

        # -- Step 2: sanitize content --
        sanitized: List[dict] = []
        for msg in old_messages:
            role = msg.get("role", "unknown")
            content = msg.get("content")
            if content is None:
                content = ""
            elif not isinstance(content, str):
                try:
                    content = str(content)
                except Exception:
                    content = ""
            content = content.strip()
            sanitized.append({"role": role, "content": content})

        # -- Step 3: build transcript, skipping empty messages --
        lines: List[str] = []
        for msg in sanitized:
            content = msg["content"]
            if not content:
                continue
            role_label = msg["role"].upper()

            max_msg_tokens = getattr(
                self._f.valves, "summarize_max_tokens_per_message", 800
            )
            if max_msg_tokens > 0:
                content = self._f._tokens.truncate_text_to_tokens(
                    content, max_msg_tokens
                )
            lines.append(f"{role_label}: {content}")

        # -- Step 4: guard empty transcript after sanitization --
        if not lines:
            self._f._log_debug(
                "summarize_messages: all messages empty after sanitization, "
                "returning None"
            )
            return None

        transcript = "\n\n".join(lines)

        # -- Step 5: build prompt --
        code_hint = (
            " Pay special attention to code changes, function signatures, "
            "and architectural decisions discussed."
            if is_code_context
            else ""
        )

        prompt = (
            f"Summarize the following conversation excerpt concisely, "
            f"preserving all key decisions, code changes, and action items.{code_hint} "
            f"Write 2-4 sentences. Do not add commentary or meta-text.\n\n"
            f"---\n{transcript}\n---"
        )

        system = (
            "You are a technical writer summarising a developer conversation. "
            "Be precise and factual. Never invent information not present in "
            "the transcript."
        )

        # -- Step 6: LLM call --
        max_out = getattr(self._f.valves, "summarize_max_output_tokens", 256)
        try:
            raw = await self._f._llm.call_llm(
                prompt=prompt,
                system_prompt=system,
                max_tokens=max_out,
                temperature=0.2,
                enable_thinking=False,
                label="summarize_messages",
            )
        except Exception as e:
            self._f._log_debug(
                f"summarize_messages: LLM failed: {type(e).__name__}: {e}"
            )
            return None

        # -- Step 7: clean and return --
        if not raw:
            return None

        summary = raw.strip()
        if not summary:
            return None

        self._f._log_debug(
            f"summarize_messages: generated {len(summary)} char summary "
            f"from {len(old_messages)} message(s) "
            f"(code_context={is_code_context})"
        )
        return summary

    # ═══════════════════════════════════════════════════════════════════════
    # 6. Proactive summarization suggestion
    # ═══════════════════════════════════════════════════════════════════════

    async def check_and_suggest_summarization(
        self,
        project_id: str,
        total_tokens: int,
        max_tokens: int,
    ) -> Optional[str]:
        """Return a proactive suggestion when the conversation is using a high ratio of the token window."""
        if max_tokens <= 0:
            return None
        ratio = total_tokens / max_tokens
        if ratio > self._f.valves.proactive_summary_threshold:
            return (
                f"[CodeAware] The conversation is using {total_tokens}/{max_tokens} tokens "
                f"(≈{int(ratio*100)}%). Consider using `/forget` or asking me to summarize "
                f"older parts."
            )
        return None

    # ═══════════════════════════════════════════════════════════════════════
    # 7. Oversized block summary generation (fire-and-forget)
    # ═══════════════════════════════════════════════════════════════════════

    async def schedule_block_summary(
        self,
        block: "CodeBlock",
        project_id: str,
    ) -> None:
        """
        Gate before maybe_generate_block_summary.

        Skips blocks that already have a summary, are below the minimum size,
        are obsolete, or are already being summarized by a concurrent task.
        Passes project_id via block._project_id_hint so maybe_generate_block_summary
        can mark the state dirty without a separate project_id parameter.

        Steps:
            1.  Fast exits: existing summary, below threshold, obsolete.
            2.  Stash project_id on the block for use in maybe_generate.
            3.  Delegate to maybe_generate_block_summary.
        """
        # -- Step 1: fast exits --
        if block.block_summary:
            return
        if block.obsolete:
            return
        min_chars = getattr(self._f.valves, "block_summary_min_chars", 1000)
        if len(block.content) < min_chars:
            return

        # -- Step 2: stash project context --
        block._project_id_hint = project_id  # type: ignore[attr-defined]

        # -- Step 3: delegate --
        await self.maybe_generate_block_summary(block)

    async def maybe_generate_block_summary(self, block: "CodeBlock") -> None:
        """
        Generate and store a natural-language summary for an oversized code block.

        Uses _summarizing_blocks to ensure at most one LLM call is in-flight per
        block hash at any time. Without this guard, concurrent calls from two rapid
        inlet passes both observe block.block_summary == "" and launch duplicate
        LLM requests; the second overwrites the first and wastes tokens.

        Project context is read from block._project_id_hint, set by
        schedule_block_summary. Falls back to valves.project_id when absent.

        Steps:
            1.  Skip if block already has a summary.
            2.  Skip and return if generation is already in-progress for this hash.
            3.  Register hash in _summarizing_blocks.
            4.  Build a compact prompt from the block's content and symbols.
            5.  Call LLM; on success write to block.block_summary and mark dirty.
            6.  Always deregister the hash in a finally block.
        """
        # -- Step 1: already summarized --
        if block.block_summary:
            return

        # -- Step 2: in-progress guard --
        if block.hash in self._summarizing_blocks:
            self._f._log_debug(
                f"maybe_generate_block_summary: in-progress for {block.hash[:8]}, "
                f"skipping duplicate"
            )
            return

        # -- Step 3: register --
        self._summarizing_blocks.add(block.hash)

        project_id: str = (
            getattr(block, "_project_id_hint", None) or self._f.valves.project_id or ""
        )

        try:
            # -- Step 4: build prompt --
            sym_names = [s.name for s in block.symbols[:10]] if block.symbols else []
            sym_hint = f"Key symbols: {', '.join(sym_names)}. " if sym_names else ""
            file_hint = f"File: {block.file_path}. " if block.file_path else ""

            truncated = self._f._tokens.truncate_text_to_tokens(
                block.content,
                getattr(self._f.valves, "block_summary_context_tokens", 2000),
            )

            prompt = (
                f"Write a one-paragraph technical summary of the following code block. "
                f"{file_hint}{sym_hint}"
                f"Focus on what the code does and its main responsibilities.\n\n"
                f"```\n{truncated}\n```"
            )

            system = (
                "You are a senior software engineer. "
                "Reply with a single concise paragraph. No bullet points."
            )

            # -- Step 5: call LLM and store --
            result = await self._f._llm.call_llm(
                prompt=prompt,
                system_prompt=system,
                max_tokens=200,
                temperature=0.2,
                enable_thinking=False,
                label="block_summary",
            )

            if result:
                block.block_summary = result.strip()
                if project_id:
                    self._f._conversation_state_manager.mark_dirty(project_id)
                self._f._log_debug(
                    f"maybe_generate_block_summary: generated for {block.hash[:8]} "
                    f"(~{len(block.block_summary)} chars)"
                )

        except asyncio.CancelledError:
            raise
        except Exception as e:
            self._f._log_debug(
                f"maybe_generate_block_summary: LLM failed for "
                f"{block.hash[:8]}: {type(e).__name__}: {e}"
            )
        finally:
            # -- Step 6: always deregister --
            self._summarizing_blocks.discard(block.hash)


class TokenUtils:
    """Token‑level utilities for budget management and text truncation.

    Provides:
    * ``estimate_tokens(messages)`` — total token count for a list of
      message dicts (content + role overhead).
    * ``estimate_code_tokens(code)`` — token count for a raw code string.
    * ``truncate_text_to_tokens(text, max_tokens)`` — truncates text to
      approximately *max_tokens* while preserving word boundaries.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Token estimation
    # ═══════════════════════════════════════════════════════════════════════════

    def estimate_tokens(self, messages: list) -> int:
        """Estimate total token count for a list of messages."""
        if self._f.tokenizer:
            total = 0
            for m in messages:
                content = str(m.get("content", ""))
                total += len(self._f.tokenizer.encode(content))
                total += 4  # role and formatting overhead
            return total
        total_chars = sum(len(str(m.get("content", ""))) for m in messages)
        total_chars += sum(30 for _ in messages)
        return total_chars // 4

    def estimate_code_tokens(self, code: str) -> int:
        """Estimate token count for a code string."""
        if self._f.tokenizer:
            return len(self._f.tokenizer.encode(code))
        return len(code) // 4

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Text truncation
    # ═══════════════════════════════════════════════════════════════════════════

    def truncate_text_to_tokens(self, text: str, max_tokens: int) -> str:
        """Truncate text to approximately max_tokens while preserving word boundaries."""
        if not self._f.tokenizer:
            return text[: max_tokens * 4]
        tokens = self._f.tokenizer.encode(text)
        if len(tokens) <= max_tokens:
            return text
        truncated = self._f.tokenizer.decode(tokens[:max_tokens])
        for pattern in ("\n\n", "\n", ". ", " "):
            last = truncated.rfind(pattern)
            if last > max_tokens * 0.6:
                truncated = truncated[: last + len(pattern)]
                break
        return truncated.rstrip()


class EnrichmentTasks:
    """Runs post‑processing enrichment after each user or assistant message,
    keeping the symbol index, conversation state, and LOD thresholds aligned
    with the evolving conversation.

    Provides:
    * Change and session summaries persisted to LTM and SQLite.
    * Mention tracking that decays block importance over time.
    * Time‑ and turn‑based expiration of inactive blocks.
    * Adaptive LOD threshold tuning based on which symbols the LLM actually
      used in its response.
    * Feedback context injection into Block A.
    * Parallel contradiction detection, response cache lookup, and duplicate
      question detection.
    * Batched, lazy docstring generation for symbols that lack one,
      including a background loop that fills missing docstrings without
      blocking the request path.
    * Turn‑based conversation window management (summarise then evict old
      turns, with a no‑degradation guard).

    Docs 10–13 backported:
        M5 – dunder disambiguation in docstring batch parsing.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref
        self._lazy_docstrings_generated_this_turn: int = 0
        self._active_bg_task: Optional[asyncio.Task] = None
        self._bg_docstring_count: int = 0

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Change & session summaries
    # ═══════════════════════════════════════════════════════════════════════════

    async def generate_change_summary(
        self,
        block_hash: str,
        prev_content: str,
        new_content: str,
    ) -> None:
        """
        Generate and persist a one-sentence change summary immediately.

        The prompt constrains output to a single sentence of max 15 words,
        so no max_tokens ceiling is needed — the model terminates naturally.
        enable_thinking=False avoids reasoning overhead on a deterministic
        single-sentence task.
        """
        model = self._f.valves.llm_model
        prompt = (
            f"Summarise the code change in ONE short sentence (max 15 words).\n\n"
            f"Previous:\n```\n{prev_content[:1000]}\n```\n\n"
            f"New:\n```\n{new_content[:1000]}\n```\n\n"
            f"Change summary:"
        )
        summary = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a code change summariser. " "Output only one short sentence."
            ),
            model_override=model,
            max_tokens=0,
            temperature=0.1,
            label="change_summary",
            enable_thinking=False,
        )
        if summary:
            now = time.time()
            self._f._block_change_summaries[block_hash] = (summary.strip(), now)
            if len(self._f._block_change_summaries) > self._f._MAX_CHANGE_SUMMARIES:
                self._f._block_change_summaries.popitem(last=False)

            def _write():
                self._f._db_conn.execute(
                    "INSERT OR REPLACE INTO block_change_summaries "
                    "(block_hash, summary, created_at) VALUES (?, ?, ?)",
                    (block_hash, summary.strip(), now),
                )
                self._f._db_conn.execute(
                    "DELETE FROM block_change_summaries WHERE block_hash NOT IN "
                    "(SELECT block_hash FROM block_change_summaries "
                    "ORDER BY created_at DESC LIMIT ?)",
                    (self._f._MAX_CHANGE_SUMMARIES,),
                )
                self._f._db_conn.commit()

            await self._f._state_store._db_enqueue(_write)

    async def run_session_summary_task(
        self,
        params: dict,
        model: str,
        stop_event: Optional[asyncio.Event] = None,
    ) -> bool:
        """
        Generate an autobiographical session summary and store it in LTM.

        Args:
            params (dict): Parameters including 'project_id' and optionally 'code_state_hash'.
            model (str): Model to use for summarization.
            stop_event (Optional[asyncio.Event]): Optional event to signal early termination.

        Returns:
            bool: True if the summary was generated and stored successfully.
        """
        if stop_event and stop_event.is_set():
            return False

        project_id = params["project_id"]
        code_state_hash = params.get("code_state_hash", "")

        recent = await self._f._ltm.retrieve_historical_messages(
            query="recent conversation summary",
            project_id=project_id,
            limit=self._f.valves.session_summary_interval_messages,
        )
        if not recent:
            return False

        if stop_event and stop_event.is_set():
            return False

        conversation_text = "\n".join(
            f"{m['role']}: {m['content'][:300]}" for m in recent
        )
        prompt = (
            "Summarise the following conversation segment in 2-3 sentences, "
            "capturing the main task, decisions made, files modified, "
            "and architectural changes:\n\n"
            f"{conversation_text[:3000]}"
        )
        summary = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt="You are a helpful assistant that produces concise autobiographical session summaries.",
            model_override=model,
            max_tokens=self._f.valves.session_summary_max_tokens,
            temperature=0.2,
            label="session_summary",
        )
        if not summary:
            return False

        if stop_event and stop_event.is_set():
            return False

        msg_id = f"{project_id}_session_summary_{int(time.time())}"
        embedding = await anyio.to_thread.run_sync(
            lambda: self._f.embedder.encode(summary).tolist()
        )
        await anyio.to_thread.run_sync(
            lambda: self._f.memory_collection.upsert(
                ids=[msg_id],
                embeddings=[embedding],
                metadatas=[
                    {
                        "role": "assistant",
                        "project_id": project_id,
                        "timestamp": time.time(),
                        "is_session_summary": True,
                        "code_state_hash": code_state_hash,
                        "content_type": ContentType.GENERAL.value,
                        "has_code": False,
                    }
                ],
                documents=[f"[Session summary]\n{summary}"],
            )
        )
        self._f._log_debug(f"Session summary stored in LTM (msg_id={msg_id})")
        return True

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Block maintenance (mentions, expiration)
    # ═══════════════════════════════════════════════════════════════════════════

    def update_mentions_from_message(
        self,
        state: dict,
        message_content: str,
        project_id: str,
    ) -> None:
        """
        Increment mention counts for symbols referenced in the message content,
        and mark the corresponding blocks as recently mentioned.
        """
        if not message_content:
            return
        all_symbol_names = self._f._symbol_index.get_all_names(project_id)
        words = set(re.findall(r"\b[\w-]+\b", message_content))
        mentioned_names = all_symbol_names.intersection(words)
        if not mentioned_names:
            return
        affected_blocks: Set[str] = set()
        for name in mentioned_names:
            affected_blocks.update(self._f._symbol_index.find_blocks(name, project_id))
        for block_hash in affected_blocks:
            block = state.active_blocks.get(block_hash)
            if block:
                block.mention_count += 1
                block.last_mentioned = time.time()
                block.last_mentioned_msg_idx = state.message_count
                block._update_importance()

    async def expire_blocks_by_time(self, project_id: str) -> None:
        """Remove blocks that have not been mentioned recently, based on configured timeouts."""
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            state = self._f._conversation_state_manager.get(project_id)
            if not state:
                return
            now = time.time()
            expiration_seconds = self._f.valves.block_expiration_hours * 3600
            to_remove = []
            for h, block in state.active_blocks.items():
                if block.pinned or block.obsolete:
                    continue
                age = now - block.last_mentioned
                if (
                    block.content_type == ContentType.ERROR
                    and self._f.valves.error_retention_turns > 0
                ):
                    if age > max(
                        self._f.valves.error_retention_turns * 300, expiration_seconds
                    ):
                        to_remove.append(h)
                elif (
                    block.content_type == ContentType.PROPOSED_CHANGE
                    and self._f.valves.proposed_change_retention_turns > 0
                ):
                    if age > max(
                        self._f.valves.proposed_change_retention_turns * 300,
                        expiration_seconds,
                    ):
                        to_remove.append(h)
            for h in to_remove:
                if h in state.active_blocks:
                    block = state.active_blocks[h]
                    self._f._symbol_index.remove_all_for_block(
                        block.hash, block.symbols, project_id
                    )
                del state.active_blocks[h]
            if to_remove:
                state.has_any_calls = any(
                    any(s.calls for s in b.symbols)
                    for b in state.active_blocks.values()
                )
                self._f._activation.invalidate_lightweight_cache(project_id)
                self._f._conversation_state_manager.set(project_id, state)

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. LOD adaptive adjustment
    # ═══════════════════════════════════════════════════════════════════════════

    async def update_lod_thresholds_from_response(
        self,
        project_id: str,
        response_text: str,
        stop_event: Optional[asyncio.Event] = None,
    ) -> None:
        """
        Adjust lod3_threshold based on which symbols appear in the LLM's
        response compared to the LOD level they received.

        Args:
            project_id (str): The current project identifier.
            response_text (str): The assistant's response text.
            stop_event (Optional[asyncio.Event]): Optional event to signal early termination.
        """
        if stop_event and stop_event.is_set():
            return

        if not self._f.valves.enable_lod_adaptive:
            return

        psm = self._f._project_state_manager
        last_lod_map = psm.get_last_lod_levels(project_id)
        if not last_lod_map:
            return

        bare_names = self._f._symbol_index.get_all_names(project_id)
        response_words = set(re.findall(r"\b\w+\b", response_text))
        bare_referenced = bare_names.intersection(response_words)

        referenced: Set[str] = set()
        for bare in bare_referenced:
            referenced |= self._f._symbol_index.get_qualified_names_for(
                bare, project_id
            )

        underserved = [sym for sym in referenced if last_lod_map.get(sym, 3) < 3]
        overserved = [
            sym
            for sym in last_lod_map
            if last_lod_map[sym] == 3 and sym not in referenced
        ]

        old_threshold = self._f.valves.lod3_threshold
        changed = False

        if len(underserved) >= self._f.valves.lod_adapt_underserved_min:
            self._f.valves.lod3_threshold = max(
                self._f.valves.lod_adapt_min,
                self._f.valves.lod3_threshold - self._f.valves.lod_adapt_rate,
            )
            changed = True
            self._f._log_debug(
                f"LOD adaptive ↓: threshold {old_threshold:.2f} → "
                f"{self._f.valves.lod3_threshold:.2f} "
                f"({len(underserved)} underserved: {underserved[:3]})"
            )

        elif len(overserved) >= self._f.valves.lod_adapt_overserved_min:
            self._f.valves.lod3_threshold = min(
                self._f.valves.lod_adapt_max,
                self._f.valves.lod3_threshold + self._f.valves.lod_adapt_rate * 0.5,
            )
            changed = True
            self._f._log_debug(
                f"LOD adaptive ↑: threshold {old_threshold:.2f} → "
                f"{self._f.valves.lod3_threshold:.2f} "
                f"({len(overserved)} overserved symbols)"
            )

        if not changed:
            self._f._log_debug(
                f"LOD adaptive: no adjustment needed "
                f"(threshold={self._f.valves.lod3_threshold:.2f})"
            )

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Feedback context
    # ═══════════════════════════════════════════════════════════════════════════

    def get_feedback_context(self, project_id: str) -> str:
        """Return a formatted string of recent feedback for the given project."""
        state = self._f._conversation_state_manager.get(project_id)
        feedback = state.feedback_history
        if not feedback:
            return ""
        recent = feedback[-self._f.valves.feedback_history_limit :]
        lines = ["## Previous Feedback"]
        for fb in recent:
            success = "✅" if fb.success else "❌"
            lines.append(f"- {success} {fb.change_description[:100]}")
        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Parallel checks (contradiction, cache, duplicate)
    # ═══════════════════════════════════════════════════════════════════════════

    async def parallel_context_checks(
        self,
        messages: list,
        query: str,
        context_hash: str,
        project_id: str,
        state: dict,
        skip_contradiction: bool = False,
        skip_cache: bool = False,
        skip_duplicate: bool = False,
    ) -> Tuple[Optional[str], Optional[dict], Optional[dict]]:
        """
        Run contradiction detection, response cache lookup, and duplicate question
        detection in parallel. Returns (contradiction_warning, cached_response,
        duplicate_match). All three can be None.
        """
        tasks = [
            (
                self._f._commands._detect_contradictions(
                    messages, project_id
                )  # <-- project_id added
                if (
                    self._f.valves.enable_contradiction_detection
                    and not skip_contradiction
                )
                else asyncio.sleep(0, result=None)
            ),
            (
                self._f._ltm.find_cached_response(query, context_hash, state)
                if (
                    self._f.valves.enable_response_cache
                    and HAS_SENTENCE
                    and not skip_cache
                )
                else asyncio.sleep(0, result=None)
            ),
            (
                self._f._ltm.find_duplicate_question(query, project_id)
                if (
                    self._f.valves.duplicate_question_threshold
                    and HAS_SENTENCE
                    and not skip_duplicate
                )
                else asyncio.sleep(0, result=None)
            ),
        ]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        contradiction = results[0] if not isinstance(results[0], Exception) else None
        cached = results[1] if not isinstance(results[1], Exception) else None
        duplicate = results[2] if not isinstance(results[2], Exception) else None
        return contradiction, cached, duplicate

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Docstring generation (batch and background)
    # ═══════════════════════════════════════════════════════════════════════════

    def _build_docstring_batch_prompt(self, items: List[Tuple[str, str, str]]) -> str:
        """
        Build the user-turn prompt for a batch docstring generation call.

        The server-side response_format={"type": "json_object"} enforces JSON
        at the API level; the prompt text repeats the constraint so the model
        never falls back to prose or a numbered list.

        Args:
            items: List of (qid, signature, snippet) tuples. Only qid and
                   signature are consumed; snippet is reserved for future use.

        Returns:
            str: Ready-to-send prompt string.
        """
        lines: List[str] = []
        for qid, signature, _ in items:
            # Truncate long signatures to keep the prompt compact and
            # avoid pushing context beyond the model's effective attention span.
            sig = signature[:80] if signature else qid
            lines.append(f"  - {qid}: {sig}")

        listing = "\n".join(lines)
        max_chars = self._f.valves.docstring_max_chars

        return (
            f"Generate a JSON object mapping each identifier below to a "
            f"one-sentence description (under {max_chars} characters).\n\n"
            f"Rules:\n"
            f"  - Keys: exact identifiers as listed "
            f"(preserve 'ClassName.method' dot notation).\n"
            f"  - Values: plain strings, one sentence each.\n"
            f"  - Output ONLY the JSON object. "
            f"No markdown fences, no preamble, no explanation.\n\n"
            f"Identifiers:\n{listing}"
        )

    def _parse_docstring_batch_response(
        self, response: str, expected_names: Set[str]
    ) -> Dict[str, str]:
        """
        Parse the LLM response as a JSON object mapping identifiers to docstrings.

        The response is expected to be a valid JSON object produced under
        response_format={"type":"json_object"} with enable_thinking=False.
        The server-side GBNF grammar guarantees the output starts with { and
        ends with }, so no stripping of think blocks, markdown fences, or
        leading prose is needed.

        Only entries whose key is present in expected_names and whose value
        is a non-empty string are returned.

        Args:
            response: Raw LLM response string.
            expected_names: Set of qualified symbol identifiers that are valid.

        Returns:
            Dict[str, str]: Accepted {qid: docstring} mapping. Values are
            truncated to docstring_max_chars. Empty dict on any parse failure.
        """
        if not response or not response.strip():
            self._f._log_debug(
                "_parse_docstring_batch_response: received empty response"
            )
            return {}

        self._f._log_debug(
            f"_parse_docstring_batch_response: parsing {len(response)}-char response "
            f"(expecting {len(expected_names)} identifiers)"
        )

        try:
            data = json.loads(response)

            if not isinstance(data, dict):
                self._f._log_debug(
                    f"_parse_docstring_batch_response: top-level JSON value is "
                    f"{type(data).__name__}, expected dict"
                )
                return {}

            # Accept only entries matching expected identifiers; silently drop
            # hallucinated keys and non-string values.
            max_chars = self._f.valves.docstring_max_chars
            result: Dict[str, str] = {}
            for key, value in data.items():
                if key in expected_names and isinstance(value, str) and value.strip():
                    result[key] = value.strip()[:max_chars]

            skipped = len(data) - len(result)
            self._f._log_debug(
                f"_parse_docstring_batch_response: accepted {len(result)} / {len(data)} "
                f"entries ({skipped} skipped — not in expected_names or invalid type)"
            )
            return result

        except json.JSONDecodeError as exc:
            self._f._log_debug(
                f"_parse_docstring_batch_response: JSON decode error — {exc}. "
                f"Offending text preview: {response[:300]!r}"
            )
            return {}

        except Exception as exc:
            self._f._log_debug(
                f"_parse_docstring_batch_response: unexpected error — {exc}"
            )
            return {}

    async def ensure_docstrings_batch(
        self,
        qids: List[str],
        project_id: str,
        background: bool = False,
    ) -> Dict[str, str]:
        """
        Resolve docstrings for many symbols at once, identified by their
        QUALIFIED id (e.g. "ContextBuilder.__init__") — never by bare name.

        Uses response_format={"type": "json_object"} and enable_thinking=False
        to force clean JSON output from the server with no reasoning preamble.
        The server-side GBNF grammar guarantees valid JSON, so the parser
        calls json.loads directly with no artifact stripping.

        Cache hits (already in memory or SQLite) are resolved for free.
        Cache misses are generated in groups of lazy_docstring_batch_size.

        Args:
            qids: List of qualified symbol ids to resolve.
            project_id: Current project identifier.
            background: If True, this is a background task — uses label
                        'bg_docstring' (whitelisted during silent ingestion)
                        and bypasses the per-turn lazy_docstring_max_per_turn
                        budget. If False, uses label 'lazy_docstring_batch'
                        and respects the per-turn budget.

        Returns:
            Dict[str, str]: Mapping of qid to docstring for resolved symbols.
        """
        self._f._log_debug(
            f"ensure_docstrings_batch: starting with {len(qids)} qids "
            f"(background={background})"
        )

        state = self._f._conversation_state_manager.get(project_id)
        resolved: Dict[str, str] = {}
        pending: List[str] = []

        # Build a qid → (sym, block) lookup index once to avoid O(N²) scans
        # across the active_blocks dict during cache and batch phases.
        _qid_index: Dict[str, Tuple["CodeSymbol", "CodeBlock"]] = {}
        for _block in state.active_blocks.values():
            for _sym in _block.symbols:
                _q = qualify_symbol_name(_sym.name, _sym.parent_symbol)
                if _q not in _qid_index:
                    _qid_index[_q] = (_sym, _block)

        def _find_symbol(
            qid: str,
        ) -> Tuple[Optional["CodeSymbol"], Optional["CodeBlock"]]:
            return _qid_index.get(qid, (None, None))

        # ── Phase 1: resolve from in-memory symbol index then SQLite ─────────
        for qid in qids:
            sym, _ = _find_symbol(qid)
            found = sym.docstring if sym and sym.docstring else ""

            if not found:
                try:
                    row = await self._f._state_store._db_read(
                        lambda: self._f._db_conn.execute(
                            "SELECT docstring FROM symbol_docstrings "
                            "WHERE project_id=? AND symbol_name=?",
                            (project_id, qid),
                        ).fetchone()
                    )
                except Exception:
                    row = None

                if row and row[0]:
                    found = row[0]
                    if sym is not None:
                        sym.docstring = found
                    self._f._symbol_index.update_docstring(qid, project_id, found)

            if found:
                resolved[qid] = found
            else:
                pending.append(qid)

        self._f._log_debug(
            f"ensure_docstrings_batch: {len(pending)} pending after cache check"
        )

        if not pending:
            self._f._log_debug(
                "ensure_docstrings_batch: all resolved from cache, no LLM call needed"
            )
            return resolved

        # ── Phase 2: apply per-turn budget (foreground/lazy mode only) ────────
        if not background:
            budget = self._f.valves.lazy_docstring_max_per_turn
            if budget > 0:
                remaining = max(0, budget - self._lazy_docstrings_generated_this_turn)
                pending = pending[:remaining]
                self._f._log_debug(
                    f"ensure_docstrings_batch: {len(pending)} remaining after "
                    f"per-turn budget (used={self._lazy_docstrings_generated_this_turn}, "
                    f"limit={budget})"
                )
            if not pending:
                return resolved
        else:
            self._f._log_debug(
                "ensure_docstrings_batch: background mode — per-turn budget skipped"
            )

        # ── Phase 3: build (qid, signature, snippet) items for LLM ───────────
        items: List[Tuple[str, str, str]] = []
        for qid in pending:
            sym, block = _find_symbol(qid)
            if sym is not None and block is not None:
                signature = sym.signature
                if sym.line_start:
                    lines = block.content.split("\n")
                    start_idx = max(0, sym.line_start - 1)
                    end_idx = min(len(lines), (sym.line_end or sym.line_start + 30))
                    snippet = "\n".join(lines[start_idx:end_idx])[:500]
                else:
                    snippet = block.content[:500]
            else:
                signature, snippet = qid, ""
            items.append((qid, signature, snippet))

        batch_size = max(1, self._f.valves.lazy_docstring_batch_size)
        label = "bg_docstring" if background else "lazy_docstring_batch"

        self._f._log_debug(
            f"ensure_docstrings_batch: {len(items)} items to generate, "
            f"batch_size={batch_size}, label={label!r}"
        )

        # ── Phase 4: LLM batch loop ───────────────────────────────────────────
        for i in range(0, len(items), batch_size):
            batch = items[i : i + batch_size]
            expected = {q for q, _, _ in batch}
            prompt = self._build_docstring_batch_prompt(batch)

            batch_num = i // batch_size + 1
            total_batches = (len(items) + batch_size - 1) // batch_size
            prompt_tokens = (
                len(self._f.tokenizer.encode(prompt))
                if self._f.tokenizer
                else len(prompt) // 4
            )
            self._f._log_debug(
                f"ensure_docstrings_batch: batch {batch_num}/{total_batches} — "
                f"{len(batch)} symbols, ~{prompt_tokens} prompt tokens, "
                f"label={label!r}"
            )

            response = await self._f._llm_orchestrator.call_llm(
                prompt=prompt,
                system_prompt=(
                    "You are a code documentation assistant. "
                    "Output ONLY a valid JSON object. "
                    "Your entire response must start with { and end with }. "
                    "No text before { and no text after }."
                ),
                model_override=self._f.valves.llm_model,
                max_tokens=0,
                temperature=0.0,
                label=label,
                response_format={"type": "json_object"},
                log_raw_response=False,
                enable_thinking=False,
            )

            if not background:
                self._lazy_docstrings_generated_this_turn += len(batch)

            if response is None:
                self._f._log_debug(
                    f"ensure_docstrings_batch: batch {batch_num} — LLM returned None"
                )
                continue

            self._f._log_debug(
                f"ensure_docstrings_batch: batch {batch_num} — "
                f"received {len(response)}-char response"
            )

            parsed = self._parse_docstring_batch_response(response, expected)

            self._f._log_debug(
                f"ensure_docstrings_batch: batch {batch_num} — "
                f"parsed {len(parsed)} docstrings"
            )

            for qid, docstring in parsed.items():
                resolved[qid] = docstring
                sym, _ = _find_symbol(qid)
                if sym is not None:
                    sym.docstring = docstring
                self._f._symbol_index.update_docstring(qid, project_id, docstring)

            if parsed:
                rows = [
                    (project_id, qid, doc, time.time()) for qid, doc in parsed.items()
                ]

                def _write_batch(rows: list = rows) -> None:
                    self._f._db_conn.executemany(
                        "INSERT OR REPLACE INTO symbol_docstrings "
                        "(project_id, symbol_name, docstring, updated_at) "
                        "VALUES (?,?,?,?)",
                        rows,
                    )
                    self._f._db_conn.commit()

                await self._f._state_store._db_enqueue(_write_batch)

        self._f._log_debug(
            f"ensure_docstrings_batch: done — "
            f"resolved {len(resolved)} / {len(qids)} total"
        )
        return resolved

    async def ensure_cfg_batch(
        self, qids: List[str], project_id: str
    ) -> Dict[str, str]:
        """
        Resolve control-flow skeletons for many symbols, identified by their
        QUALIFIED id. Pure CPU, deterministic, no LLM call.
        """
        self._f._log_debug(f"CFG batch: invoked with {len(qids)} candidate(s): {qids}")
        state = self._f._conversation_state_manager.get(project_id)
        cfg_rows = []
        resolved: Dict[str, str] = {}

        _qid_index: Dict[str, Tuple["CodeSymbol", "CodeBlock"]] = {}
        for _block in state.active_blocks.values():
            for _sym in _block.symbols:
                _q = qualify_symbol_name(_sym.name, _sym.parent_symbol)
                if _q not in _qid_index:
                    _qid_index[_q] = (_sym, _block)

        def _find_symbol_and_block(qid: str):
            return _qid_index.get(qid, (None, None))

        for qid in qids:
            sym, block = _find_symbol_and_block(qid)
            if sym is None or block is None:
                self._f._log_debug(
                    f"CFG batch: '{qid}' NOT FOUND in active_blocks — skipping"
                )
                continue
            if not sym.line_start or not sym.line_end:
                self._f._log_debug(
                    f"CFG batch: '{qid}' has no line_start/line_end — skipping"
                )
                continue

            lines = block.content.split("\n")
            snippet = "\n".join(lines[max(0, sym.line_start - 1) : sym.line_end])
            current_hash = hashlib.md5(snippet.encode()).hexdigest()[:16]

            meta = self._f._symbol_index.get_symbol_meta(qid, project_id) or {}
            cached_skeleton = meta.get("cfg_skeleton", "")
            cached_hash = meta.get("cfg_body_hash", "")
            if cached_skeleton and cached_hash == current_hash:
                self._f._log_debug(f"CFG batch: '{qid}' cache HIT")
                resolved[qid] = cached_skeleton
                continue

            result = ControlFlowExtractor.extract_for_symbol(
                block.content, sym, max_lines=self._f.valves.cfg_skeleton_max_lines
            )
            if result is None:
                self._f._log_debug(f"CFG batch: '{qid}' extractor returned None")
                continue
            skeleton, body_hash = result
            self._f._log_debug(
                f"CFG batch: '{qid}' skeleton generated ({len(skeleton)} chars)"
            )
            self._f._symbol_index.update_cfg(qid, project_id, skeleton, body_hash)
            resolved[qid] = skeleton
            cfg_rows.append((project_id, qid, skeleton, body_hash, time.time()))

        if cfg_rows:

            def _write_cfg_batch(rows=cfg_rows):
                self._f._db_conn.executemany(
                    "INSERT OR REPLACE INTO symbol_cfg "
                    "(project_id, symbol_name, cfg_skeleton, body_hash, updated_at) "
                    "VALUES (?,?,?,?,?)",
                    rows,
                )
                self._f._db_conn.commit()

            await self._f._state_store._db_enqueue(_write_cfg_batch)
            self._f._log_debug(
                f"CFG batch: persisted {len(cfg_rows)} CFG entries in one batch"
            )

        self._f._log_debug(f"CFG batch: resolved {len(resolved)}/{len(qids)}")
        return resolved

    # ═══════════════════════════════════════════════════════════════════════════
    # 7. Background docstring loop (with Q5 prioritization)
    # ═══════════════════════════════════════════════════════════════════════════

    # ── Q5: Priorization of docstring targets (MIGRADO) ──────────────────────

    def _prioritize_docstring_targets(
        self,
        qids: List[str],
        project_id: str,
        pstate: dict,
    ) -> List[str]:
        """
        Sort symbols by docstring generation priority.

        Priority order:
        1. Symbols in skeleton tier (visible in Block A every turn)
        2. Symbols currently in Block B at LOD-2/3 (visible this turn)
        3. Hub symbols (high PPR — frequently referenced)
        4. Everything else (leaf symbols — rarely in context)
        """
        psm = self._f._project_state_manager
        skeleton_qids: Set[str] = set(psm.get_skeleton_tier_qids(project_id))
        block_b_qids: Set[str] = set(psm.get_block_b_qids_this_turn(project_id))

        # Get cached PPR scores if available (from Q2 fix cache)
        ppr_scores: Dict[str, float] = (
            self._f._activation._ppr_cache.get(
                pstate.get("code_state_hash", ""),
                frozenset(pstate.get("hub_tier_qids_persisted", [])),
            )
            or {}
        )

        def priority_key(qid: str) -> tuple:
            in_skeleton = 0 if qid in skeleton_qids else 1  # 0 = highest priority
            in_block_b = 0 if qid in block_b_qids else 1
            ppr = -ppr_scores.get(qid, 0.0)  # negate for desc sort
            return (in_skeleton, in_block_b, ppr, qid)

        return sorted(qids, key=priority_key)

    async def _docstring_generation_loop(
        self,
        project_id: str,
        stop_event: Optional[asyncio.Event] = None,
    ) -> None:
        """
        Background loop that generates docstrings for symbols that lack them.

        Runs indefinitely until stop_event is set or the task is cancelled.
        Errors at the per-symbol level are caught and logged with continue so
        one bad symbol cannot abort processing for the rest. Errors at the
        outer level (e.g. state cleared mid-loop, ChromaDB unavailable) are
        caught, logged, and followed by a longer sleep before retrying, so the
        loop survives transient infrastructure failures.

        Only CancelledError and stop_event propagate out of the loop.

        Steps (per iteration):
            1.  Check stop_event.
            2.  Collect and prioritize qids that need docstrings.
            3.  For each target: find block, find symbol, call _background_docstring.
                Per-symbol exceptions continue to next target.
            4.  Sleep between full passes.
            Outer exception handler: log + extended sleep + continue (not break).
        """
        base_sleep = max(
            1.0, getattr(self._f.valves, "docstring_loop_interval_seconds", 5.0)
        )
        error_sleep = base_sleep * 4
        symbol_yield = 0.05

        while True:
            # -- Step 1: stop check --
            if stop_event and stop_event.is_set():
                self._f._log_debug(
                    f"Docstring loop: stop_event set for '{project_id}', exiting"
                )
                return

            try:
                # -- Step 2: collect targets --
                all_qids = list(
                    self._f._symbol_index.get_all_qualified_names(project_id)
                )
                if not all_qids:
                    await asyncio.sleep(base_sleep)
                    continue

                state = self._f._conversation_state_manager.get(project_id)
                pstate = self._f._project_state_manager.get_pstate(project_id)

                targets = self._prioritize_docstring_targets(
                    all_qids, project_id, pstate
                )

                # -- Step 3: process each target --
                processed = 0
                for qid in targets:
                    if stop_event and stop_event.is_set():
                        return

                    existing = self._f._symbol_index.get_docstring(qid, project_id)
                    if existing:
                        continue

                    try:
                        block_hashes = self._f._symbol_index.find_blocks(
                            qid, project_id
                        )
                        if not block_hashes:
                            continue

                        bh = next(iter(block_hashes))
                        block = state.active_blocks.get(bh) if state else None
                        if not block or block.obsolete:
                            continue

                        sym = next(
                            (
                                s
                                for s in block.symbols
                                if qualify_symbol_name(
                                    s.name, s.parent_symbol, s.file_path
                                )
                                == qid
                            ),
                            None,
                        )
                        if not sym:
                            continue

                        await self._background_docstring(sym, block, project_id)
                        processed += 1
                        await asyncio.sleep(symbol_yield)

                    except asyncio.CancelledError:
                        raise
                    except Exception as e:
                        # Per-symbol error: log and continue to next symbol.
                        self._f._log_debug(
                            f"Docstring loop: failed for '{qid}': "
                            f"{type(e).__name__}: {e}"
                        )
                        continue

                if processed:
                    self._f._log_debug(
                        f"Docstring loop: generated {processed} docstring(s) "
                        f"for '{project_id}'"
                    )

            except asyncio.CancelledError:
                raise
            except Exception as e:
                # Outer error: infrastructure or state issue.
                # Log and sleep — do NOT break, the loop must survive.
                self._f._log_debug(
                    f"Docstring loop: outer error for '{project_id}': "
                    f"{type(e).__name__}: {e} — sleeping {error_sleep}s before retry"
                )
                await asyncio.sleep(error_sleep)
                continue

            # -- Step 4: sleep between passes --
            await asyncio.sleep(base_sleep)

    def start_docstring_loop(self, project_id: str) -> None:
        """
        Start the background docstring generation loop for this project if it is
        not already running.

        Called from TaskRegistry._lazy_docstrings on every turn, so the is_running
        guard is load-bearing: without it each turn spawns an additional concurrent
        loop, resulting in N×LLM calls per symbol after N turns.

        Uses BackgroundTaskManager.is_running() to check whether a loop task with
        the canonical name is already active before creating a new one.

        Steps:
            1.  Check whether the loop is already running for this project.
            2.  Schedule via BackgroundTaskManager so the loop is tracked and
                can be cancelled by cancel_docstring_tasks().
        """
        loop_name = f"docstring_loop_{project_id}"

        # -- Step 1: deduplicate --
        if self._f._bg_manager.is_running(loop_name):
            self._f._log_debug(
                f"start_docstring_loop: already running for '{project_id}', skipping"
            )
            return

        # -- Step 2: schedule via BackgroundTaskManager --
        self._f._log_debug(f"start_docstring_loop: starting loop for '{project_id}'")

        async def _start() -> None:
            await self._f._bg_manager.start(
                loop_name,
                self._docstring_generation_loop,
                project_id,
                project_id,
            )

        asyncio.ensure_future(_start())

    # ═══════════════════════════════════════════════════════════════════════════
    # 8. Helper methods for background docstring (unchanged)
    # ═══════════════════════════════════════════════════════════════════════════

    async def cancel_docstring_tasks(self) -> None:
        """Cancel the background docstring generation loop gracefully."""
        if self._active_bg_task is not None and not self._active_bg_task.done():
            self._active_bg_task.cancel()
            try:
                await asyncio.wait_for(self._active_bg_task, timeout=10.0)
            except (asyncio.CancelledError, asyncio.TimeoutError):
                pass
        self._active_bg_task = None

        drain_deadline = time.monotonic() + 5.0
        while not self._f._db_write_queue.empty():
            if time.monotonic() > drain_deadline:
                self._f._log_debug(
                    "cancel_docstring_tasks: drain timeout (5s), proceeding anyway"
                )
                break
            await asyncio.sleep(0.05)

    def _get_optimal_snippet(
        self,
        sym: "CodeSymbol",
        block: "CodeBlock",
        project_id: str,
        max_chars: int = 3000,
        context_lines: int = 5,
    ) -> str:
        """
        Extract an optimal snippet for docstring generation, adaptive to symbol type
        and block size.

        For classes: returns the class skeleton (method signatures + section comments).
        For functions/methods: extracts the function body with surrounding context.

        The snippet length is adaptive:
        - If the block is small (< 2000 chars), return the whole block (capped to max_chars).
        - Otherwise, extract the symbol's region plus `context_lines` above and below.
        - For classes, use the existing `_build_class_skeleton` method.

        The extraction uses tree-sitter precise line ranges, so there is no risk
        of accidentally including content from other functions.

        Args:
            sym (CodeSymbol): The symbol to document.
            block (CodeBlock): The code block containing the symbol.
            project_id (str): The current project identifier.
            max_chars (int): Maximum characters for the snippet.
            context_lines (int): Number of extra lines to include around the symbol.

        Returns:
            str: The extracted snippet, truncated to max_chars if necessary.
        """
        # ── REGION 1: Small block → return everything ──
        if len(block.content) < 2000:
            return block.content[:max_chars]

        # ── REGION 2: Classes → use the existing skeleton builder ──
        if sym.kind == "class":
            members_qids = self._f._symbol_index.get_class_members(sym.name, project_id)
            members_meta = []
            for qid in members_qids:
                meta = self._f._symbol_index.get_symbol_meta(qid, project_id)
                if meta:
                    members_meta.append(
                        {
                            "qid": qid,
                            "signature": meta.get("signature", qid),
                            "line_start": meta.get("line_start"),
                        }
                    )
            section_headers = self._extract_section_comments(block, sym)
            snippet = self._build_class_skeleton(
                class_name=sym.name,
                members_meta=members_meta,
                section_headers=section_headers,
                block=block,
                line_start=sym.line_start or 1,
                line_end=sym.line_end or len(block.content.splitlines()),
            )
            return snippet[:max_chars]

        # ── REGION 3: Functions/methods → extract region + context ──
        lines = block.content.split("\n")
        start_idx = max(0, (sym.line_start or 1) - 1 - context_lines)
        end_idx = min(len(lines), (sym.line_end or sym.line_start or 1) + context_lines)
        snippet = "\n".join(lines[start_idx:end_idx])

        # ── REGION 4: If too long, truncate intelligently ──
        if len(snippet) > max_chars:
            # Keep the signature (first few lines) and the end of the body
            sig_end = min(5, len(lines[start_idx:]))
            head = "\n".join(lines[start_idx : start_idx + sig_end])
            tail = "\n".join(lines[max(start_idx, end_idx - 8) : end_idx])
            snippet = f"{head}\n...\n{tail}"

        return snippet

    async def _background_docstring(
        self,
        sym: "CodeSymbol",
        block: "CodeBlock",
        project_id: str,
    ) -> None:
        """
        Generate a one-line docstring for a symbol in the background.

        This method is called from the background docstring loop and runs
        asynchronously without blocking the main request flow. It extracts
        a code snippet for the symbol, calls the LLM to generate a concise
        docstring, and persists the result both in the SymbolIndex and in
        SQLite.

        Since this runs in the background, it uses the maximum context (4000
        characters) for all symbols to ensure the highest quality docstrings.
        The cost is paid once per symbol, and the benefit is permanent.

        Args:
            sym (CodeSymbol): The symbol to document.
            block (CodeBlock): The code block containing the symbol.
            project_id (str): The current project identifier.
        """
        # ── REGION 1: Extract symbol metadata ──
        name = sym.name
        kind = sym.kind
        signature = sym.signature
        line_start = sym.line_start
        line_end = sym.line_end
        block_hash = block.hash

        # ── REGION 2: Verify the block still exists ──
        state = self._f._conversation_state_manager.get(project_id)
        target_block = state.active_blocks.get(block_hash)
        if target_block is None:
            self._f._log_debug(
                f"Background docstring: block {block_hash} not found, skipping '{name}'"
            )
            return

        # ── REGION 3: Build the snippet with maximum context ──
        # In background, it does not block the user, so we use 4000 chars always.
        # This ensures the highest quality docstrings for all symbols.
        snippet = self._get_optimal_snippet(
            sym=sym,
            block=target_block,
            project_id=project_id,
            max_chars=4000,
            context_lines=5,
        )

        # ── REGION 4: Build the LLM prompt ──
        if kind == "class":
            prompt = (
                f"In one sentence, describe the single responsibility of this class "
                f"based on its method names and structure:\n\n```\n{snippet}\n```"
            )
        else:
            prompt = (
                f"Summarize in one short sentence what this code does:\n\n"
                f"```\n{signature}\n{snippet}\n```"
            )

        # ── REGION 5: Call the LLM ──
        docstring_text = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt="You are a code summarization assistant. Output only one concise sentence.",
            model_override=self._f.valves.llm_model,
            max_tokens=500,
            temperature=0.1,
            label="bg_docstring",
        )

        if not docstring_text or not docstring_text.strip():
            return

        # ── REGION 6: Parse and validate the docstring ──
        docstring = self._clean_single_docstring(docstring_text, name)
        if not docstring:
            self._f._log_debug(
                f"Background docstring: no valid docstring extracted for '{name}'"
            )
            return

        # ── REGION 7: Persist the docstring ──
        lock = await self._f._state_store.get_project_lock(project_id)
        async with lock:
            state = self._f._conversation_state_manager.get(project_id)
            block = state.active_blocks.get(block_hash)
            if block:
                for s in block.symbols:
                    if s.name == name and s.line_start == line_start:
                        s.docstring = docstring
                        qid = qualify_symbol_name(s.name, s.parent_symbol)
                        self._f._symbol_index.update_docstring(
                            qid, project_id, docstring
                        )
                        await self._f._state_store._db_enqueue(
                            lambda q=qid, d=docstring, pid=project_id: self._f._db_conn.execute(
                                "INSERT OR REPLACE INTO symbol_docstrings "
                                "(project_id, symbol_name, docstring, updated_at) "
                                "VALUES (?,?,?,?)",
                                (pid, q, d, time.time()),
                            )
                        )
                        break
                self._f._conversation_state_manager.set(project_id, state)
            else:
                self._f._log_debug(
                    f"Background docstring: block {block_hash} disappeared, skipping '{name}'"
                )

    def _clean_single_docstring(
        self, raw_response: str, symbol_name: str
    ) -> Optional[str]:
        """Parse the LLM response to extract a single docstring sentence."""
        _BAD_PATTERNS = re.compile(
            r"(?:Analyze\s+the\s+Request|Task:|Step:|Goal:|Purpose:|Reasoning:)"
        )
        _DOCSTRING_LINE_RE = re.compile(r"^\s*[-*]?\s*([A-Za-z_][\w.]*)\s*:\s*(.+)$")

        lines = raw_response.strip().splitlines()
        docstring = None

        for line in lines:
            stripped = line.strip()
            if not stripped:
                continue
            if _BAD_PATTERNS.search(stripped):
                continue
            m = _DOCSTRING_LINE_RE.match(stripped)
            if m:
                desc = m.group(2).strip()
                if desc and len(desc) > 5:
                    docstring = desc
                    break
            if (stripped[0].isupper() or stripped[0].isalpha()) and len(stripped) > 10:
                if not re.match(r"^\d+\.\s+", stripped) and "**" not in stripped:
                    docstring = stripped
                    break

        if not docstring:
            for line in reversed(lines):
                stripped = line.strip()
                if (
                    stripped
                    and not _BAD_PATTERNS.search(stripped)
                    and len(stripped) > 10
                    and "**" not in stripped
                ):
                    docstring = stripped[:200]
                    break

        if docstring:
            docstring = re.sub(r"^\s*[A-Za-z_][\w.]*\s*:\s*", "", docstring, count=1)
            docstring = re.split(r"[.!?]\s", docstring, maxsplit=1)[0] + "."
            docstring = docstring[:200]

        return docstring

    def _extract_section_comments(
        self, block: "CodeBlock", class_sym: "CodeSymbol"
    ) -> List[Tuple[int, str]]:
        """Extract section header comments from within a class body."""
        SECTION_RE = re.compile(
            r"^\s*#\s*[─━=\-]{2,}.*[─━=\-]{0,}\s*$|^\s*#\s*[─━=\-\s]*\w+[─━=\-\s]*$"
        )
        lines = block.content.split("\n")
        start = (class_sym.line_start or 1) - 1
        end = class_sym.line_end or len(lines)
        result = []
        for i, line in enumerate(lines[start:end], start=start):
            if SECTION_RE.match(line):
                result.append((i + 1, line.strip()))
        return result

    def _build_class_skeleton(
        self,
        class_name: str,
        members_meta: List[Dict],
        section_headers: List[Tuple[int, str]],
        block: "CodeBlock",
        line_start: int,
        line_end: int,
    ) -> str:
        """Build a structural skeleton for a class."""
        method_lines = {}
        for m in members_meta:
            if m.get("line_start"):
                method_lines[m["line_start"]] = m.get("signature", m.get("qid", ""))

        header_lines = {h[0] for h in section_headers}
        lines = block.content.split("\n")
        start_idx = max(0, line_start - 1)
        end_idx = min(len(lines), line_end)

        buf = [f"class {class_name}:"]
        for i in range(start_idx, end_idx):
            line_num = i + 1
            line = lines[i].rstrip()
            if line_num in header_lines:
                buf.append("    " + line.strip())
            elif line_num in method_lines:
                buf.append("    " + method_lines[line_num])

        if len(buf) == 1:
            buf.append("    ...")

        skeleton = "\n".join(buf)
        return skeleton[:800]

    # ═══════════════════════════════════════════════════════════════════════════
    # 9. Q6: Docstring migration on symbol rename
    # ═══════════════════════════════════════════════════════════════════════════

    async def _migrate_docstring(
        self,
        from_qid: str,
        to_qid: str,
        project_id: str,
    ) -> bool:
        """
        Move a docstring from one qid to another (rename migration).
        Returns True if migration was successful.
        """
        try:
            # First, get the existing docstring
            row = await self._f._state_store._db_read(
                lambda: self._f._db_conn.execute(
                    "SELECT docstring FROM symbol_docstrings "
                    "WHERE project_id=? AND symbol_name=?",
                    (project_id, from_qid),
                ).fetchone()
            )
            if not row or not row[0]:
                return False

            docstring = row[0]

            # Insert or replace into the new qid
            def _write():
                self._f._db_conn.execute(
                    "INSERT OR REPLACE INTO symbol_docstrings "
                    "(project_id, symbol_name, docstring, updated_at) VALUES (?,?,?,?)",
                    (project_id, to_qid, docstring, time.time()),
                )
                # Delete the old entry
                self._f._db_conn.execute(
                    "DELETE FROM symbol_docstrings "
                    "WHERE project_id=? AND symbol_name=?",
                    (project_id, from_qid),
                )
                self._f._db_conn.commit()

            await self._f._state_store._db_enqueue(_write)

            # Also update the in-memory SymbolIndex
            self._f._symbol_index.update_docstring(to_qid, project_id, docstring)
            # Clear the old docstring from memory (optional)
            # self._f._symbol_index.update_docstring(from_qid, project_id, "")

            self._f._log_debug(
                f"Docstring migrated on rename: '{from_qid}' → '{to_qid}'"
            )
            return True

        except Exception as e:
            self._f._log_debug(f"Docstring migration failed {from_qid} → {to_qid}: {e}")
            return False

    async def _detect_and_migrate_renames(
        self,
        deleted_qids: Set[str],
        added_qids: Set[str],
        project_id: str,
    ) -> Tuple[Set[str], Set[str]]:
        """
        Detect symbol renames and migrate docstrings from old to new qid.

        A rename is detected when:
        - A symbol disappears from the graph (in deleted_qids)
        - A new symbol appears (in added_qids)
        - Both share the same body hash (same implementation, different name)

        Returns:
            (truly_deleted, truly_added): sets with renames removed from both.
            The caller should not re-enqueue migrated symbols for bg_docstring.
        """
        # ── Obtener estado una sola vez ──
        state = self._f._conversation_state_manager.get(project_id)
        active_blocks = state.active_blocks  # ← cache local

        # Compute body hashes for deleted symbols (only if they had docstrings)
        old_body_hashes: Dict[str, str] = {}  # body_hash -> old_qid
        for qid in deleted_qids:
            # Check if this symbol has a docstring worth migrating
            doc = self._f._symbol_index.get_docstring(qid, project_id)
            if not doc:
                continue
            # Get the body content from the active block
            block_hashes = self._f._symbol_index.find_blocks(qid, project_id)
            for bh in block_hashes:
                block = active_blocks.get(bh)  # ← usar cache local
                if block and not block.obsolete:
                    body = CodeBlockManager.extract_symbol_body(block, qid)
                    if body:
                        body_hash = hashlib.md5(body.encode()).hexdigest()
                        old_body_hashes[body_hash] = qid
                        break

        # Compute body hashes for added symbols
        new_body_hashes: Dict[str, str] = {}  # body_hash -> new_qid
        for qid in added_qids:
            block_hashes = self._f._symbol_index.find_blocks(qid, project_id)
            for bh in block_hashes:
                block = active_blocks.get(bh)  # ← usar cache local
                if block and not block.obsolete:
                    body = CodeBlockManager.extract_symbol_body(block, qid)
                    if body:
                        body_hash = hashlib.md5(body.encode()).hexdigest()
                        new_body_hashes[body_hash] = qid
                        break

        # Find renames: same body hash, different qid
        migrated_old: Set[str] = set()
        migrated_new: Set[str] = set()

        for body_hash, old_qid in old_body_hashes.items():
            new_qid = new_body_hashes.get(body_hash)
            if new_qid and new_qid != old_qid:
                # Rename detected: migrate docstring
                success = await self._migrate_docstring(old_qid, new_qid, project_id)
                if success:
                    migrated_old.add(old_qid)
                    migrated_new.add(new_qid)

        # Return filtered sets
        return (deleted_qids - migrated_old), (added_qids - migrated_new)


class ActiveCodeUpdater:
    """Processes a new user or assistant message through the full code‑aware
    pipeline, keeping the active block set and SymbolIndex in sync.

    Orchestrates, in order:
    * Extraction of code blocks and symbols via tree‑sitter.
    * Duplicate detection against the current active blocks.
    * Registration of new blocks (indexing symbols, call edges, data‑flow edges).
    * Handling of duplicate blocks (pinned/raw force‑update, obsolete marking).
    * Conflict detection for proposed changes and optional diff application.
    * Hard eviction when ``max_active_blocks`` is exceeded.
    * Post‑update tasks: mention tracking, expiration, duplicate removal,
      oversized‑block summaries, path‑index invalidation, and soft‑eviction
      via the ContextPager.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Main orchestration
    # ═══════════════════════════════════════════════════════════════════════════

    async def process(
        self,
        message: dict,
        project_id: str,
        is_continuation: bool = False,
    ) -> None:
        """
        Index all code blocks found in a single conversation message.

        Captures a snapshot of qualified ids present in the symbol index
        BEFORE processing new blocks. This pre-index snapshot is passed to
        _post_update_tasks so that _detect_and_migrate_renames can compute
        accurate deleted/added sets. Without the snapshot, _post_update_tasks
        runs after indexing and sees the post-indexing state for both sides
        of the comparison, making deleted_qids and added_qids always empty.

        Steps:
            1.  Capture pre-index qid snapshot.
            2.  Extract and prepare new blocks from message content.
            3.  Detect duplicates against existing active blocks.
            4.  Process each block (new or duplicate).
            5.  Run post-update tasks with pre-index snapshot.
        """
        state = self._f._conversation_state_manager.get(project_id)
        if state is None:
            return

        content = message.get("content")
        if not content or not isinstance(content, str):
            return

        # -- Step 1: pre-index snapshot --
        pre_index_qids: Optional[Set[str]] = None
        try:
            pre_index_qids = set(
                self._f._symbol_index.get_all_qualified_names(project_id)
            )
        except Exception as e:
            self._f._log_debug(
                f"ActiveCodeUpdater.process: pre-index snapshot failed: {e}"
            )

        # -- Step 2: extract and prepare blocks --
        try:
            new_blocks, symbol_lists, content_to_syms = (
                await self._extract_and_prepare_new_blocks(
                    content, message.get("role", "user")
                )
            )
        except Exception as e:
            self._f._log_debug(
                f"ActiveCodeUpdater.process: extraction failed for "
                f"'{project_id}': {type(e).__name__}: {e}"
            )
            return

        if not new_blocks:
            return

        # -- Step 3: detect duplicates --
        duplicate_map = self._detect_duplicates(new_blocks, state)

        # -- Step 4: process each block --
        new_blocks_pending: List["CodeBlock"] = []
        for new_block, syms in zip(new_blocks, symbol_lists):
            is_dup, existing_hash = duplicate_map.get(new_block.hash, (False, None))
            try:
                if is_dup and existing_hash:
                    existing = state.active_blocks.get(existing_hash)
                    if existing:
                        await self._process_duplicate_block(
                            existing, new_block, syms, state, project_id
                        )
                else:
                    await self._process_new_block(new_block, syms, state, project_id)
                    new_blocks_pending.append(new_block)
            except Exception as e:
                self._f._log_debug(
                    f"ActiveCodeUpdater.process: block processing failed "
                    f"({new_block.hash[:8]}): {type(e).__name__}: {e}"
                )

        if message.get("role") == "assistant":
            try:
                await self._update_assistant_base_blocks(
                    [], content_to_syms, state, project_id
                )
            except Exception as e:
                self._f._log_debug(
                    f"ActiveCodeUpdater.process: assistant base update failed: {e}"
                )

        # -- Step 5: post-update tasks with pre-index snapshot --
        await self._post_update_tasks(
            state, project_id, new_blocks_pending, is_continuation, pre_index_qids
        )

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Extraction & preparation of new blocks
    # ═══════════════════════════════════════════════════════════════════════════

    async def _extract_and_prepare_new_blocks(
        self, content: str, role: str
    ) -> Tuple[
        List["CodeBlock"], List[List["CodeSymbol"]], Dict[str, List["CodeSymbol"]]
    ]:
        """Extract code blocks from content, build CodeBlock objects, and extract symbols."""
        extracted_blocks, block_spans = await self._f._code_blocks.extract_code_blocks(
            content
        )
        new_blocks_pending = []
        for idx, block_info in enumerate(extracted_blocks):
            blk_file = None
            if self._f.valves.track_file_paths and block_spans:
                blk_file = self._f._code_blocks.extract_file_path_for_block(
                    content, block_spans[idx][0]
                )
            if not blk_file and len(extracted_blocks) == 1:
                extracted_paths = self._f._code_blocks.extract_file_paths(content)
                blk_file = extracted_paths[0] if extracted_paths else None
            content_type = self._f._code_blocks.classify_content(
                content, extracted_blocks
            )
            new_block = CodeBlock(
                content=block_info["code"],
                content_type=content_type,
                generated_by_assistant=(role == "assistant"),
                file_path=blk_file,
                line_range=None,
                timestamp=time.time(),
                is_active=True,
                mention_count=1,
                pinned=False,
                obsolete=False,
                is_raw=block_info.get("is_raw", False),
            )
            if "[KEEP]" in content:
                new_block.is_raw = True
            if "[KEEP]" in content or "#important" in content.lower():
                new_block.importance_score = 10.0
                new_block.pinned = True
            new_blocks_pending.append(new_block)

        symbols_list = []
        for idx, (blk, block_info) in enumerate(
            zip(new_blocks_pending, extracted_blocks)
        ):
            precomputed = block_info.get("precomputed_symbols")
            if precomputed:
                syms = precomputed
            else:
                syms = await SignatureExtractor.extract_async(
                    blk.content, blk.file_path
                )
            symbols_list.append(syms)

        content_to_syms: Dict[str, List[CodeSymbol]] = {
            blk.content: syms
            for blk, syms in zip(new_blocks_pending, symbols_list)
            if not isinstance(syms, Exception)
        }

        return new_blocks_pending, symbols_list, content_to_syms, extracted_blocks

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Duplicate detection
    # ═══════════════════════════════════════════════════════════════════════════

    def _detect_duplicates(
        self, new_blocks: List["CodeBlock"], state: dict
    ) -> Dict[str, Tuple[bool, Optional[str]]]:
        """
        Compare each new block against the current active blocks.
        Returns {new_block.hash: (is_duplicate, existing_block_hash)}.
        """
        duplicate_info: Dict[str, Tuple[bool, Optional[str]]] = {}
        if not state or not new_blocks:
            return duplicate_info

        existing_contents = {h: b.content for h, b in state.active_blocks.items()}

        for new_block in new_blocks:
            is_dup = False
            existing_dup = None
            for h, ex_content in existing_contents.items():
                ex_block = state.active_blocks.get(h)
                if (
                    ex_block
                    and self._f._code_blocks.calculate_code_similarity(
                        new_block.content, ex_content
                    )
                    >= self._f.valves.code_similarity_threshold
                ):
                    is_dup = True
                    existing_dup = h
                    break
            duplicate_info[new_block.hash] = (is_dup, existing_dup)

        return duplicate_info

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Processing duplicate blocks
    # ═══════════════════════════════════════════════════════════════════════════

    async def _process_duplicate_block(
        self,
        existing: "CodeBlock",
        new_block: "CodeBlock",
        syms: List["CodeSymbol"],
        state: dict,
        project_id: str,
    ) -> None:
        """
        Update an existing block with new content when a duplicate is detected.
        Handles both pinned/raw blocks (forced update) and prioritised recent code.
        Re‑indexes symbols and edges after the update.
        """
        if existing.pinned or new_block.is_raw:
            # Pinned or raw block: force update, keep pinned status
            self._f._symbol_index.remove_all_for_block(
                existing.hash, existing.symbols, project_id
            )
            prev_content = existing.content
            existing.content = new_block.content
            existing.hash = new_block.hash
            if new_block.file_path:
                existing.file_path = new_block.file_path
            existing.line_range = new_block.line_range
            existing.timestamp = time.time()
            existing.mention_count += 1
            existing.last_mentioned = time.time()
            existing.last_mentioned_msg_idx = state.message_count
            existing.pinned = True
            existing.is_raw = existing.is_raw or new_block.is_raw
            existing.importance_score = 10.0
            existing.symbols = syms

            # Re-index with background docstrings
            await self._reindex_block_symbols_with_docstrings(existing, project_id)

            if prev_content != new_block.content:
                await self._f._enrichment.generate_change_summary(
                    existing.hash, prev_content, new_block.content
                )
            return

        if self._f.valves.prioritize_recent_code:
            # Prioritise recent code: replace content with newest version
            self._f._symbol_index.remove_all_for_block(
                existing.hash, existing.symbols, project_id
            )
            prev_content = existing.content
            existing.content = new_block.content
            existing.hash = new_block.hash
            if new_block.file_path:
                existing.file_path = new_block.file_path
            existing.line_range = new_block.line_range
            existing.timestamp = time.time()
            existing.mention_count += 1
            existing.last_mentioned = time.time()
            existing.last_mentioned_msg_idx = state.message_count
            existing.symbols = syms

            # Re-index with background docstrings
            await self._reindex_block_symbols_with_docstrings(existing, project_id)

            if prev_content != new_block.content:
                await self._f._enrichment.generate_change_summary(
                    existing.hash, prev_content, new_block.content
                )

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Reindexing helpers
    # ═══════════════════════════════════════════════════════════════════════════

    async def _reindex_block_symbols(self, block: "CodeBlock", project_id: str) -> None:
        """Re‑extract symbols for a block and register them + edges in the index."""
        for s in block.symbols:
            s.parent_block_hash = block.hash
            self._f._symbol_index.add(s, block.hash, project_id)
            caller_qid = qualify_symbol_name(s.name, s.parent_symbol, s.file_path)
            for callee_name in s.calls:
                edge = Edge(
                    src=caller_qid,
                    dst=callee_name,
                    type="calls",
                    weight=EDGE_WEIGHTS["calls"],
                    confidence=1.0,
                )
                self._f._symbol_index.add_edge(edge, project_id)

        # Data-flow edges: ONE full-file AST pass per block, not per symbol.
        if self._f.valves.enable_data_flow_analysis and block.file_path:
            df_edges = self._f._code_blocks.extract_data_flow_edges(
                block.content, block.file_path, project_id
            )
            for df_edge in df_edges:
                self._f._symbol_index.add_edge(df_edge, project_id)
            if df_edges:
                self._f._log_debug(
                    f"Data flow: {len(df_edges)} edge(s) extracted from {block.file_path}"
                )

        if self._f.tokenizer:
            block._cached_token_count = len(self._f.tokenizer.encode(block.content))
        else:
            block._cached_token_count = len(block.content) // 4
        block._update_importance()

    async def _reindex_block_symbols_with_docstrings(
        self, block: "CodeBlock", project_id: str
    ) -> None:
        """Re‑extract symbols for a block and register them + edges in the index."""
        for s in block.symbols:
            s.parent_block_hash = block.hash
            self._f._symbol_index.add(s, block.hash, project_id)
            caller_qid = qualify_symbol_name(s.name, s.parent_symbol, s.file_path)
            for callee_name in s.calls:
                edge = Edge(
                    src=caller_qid,
                    dst=callee_name,
                    type="calls",
                    weight=EDGE_WEIGHTS["calls"],
                    confidence=1.0,
                )
                self._f._symbol_index.add_edge(edge, project_id)

        # Data-flow edges: ONE full-file AST pass per block, not per symbol.
        if self._f.valves.enable_data_flow_analysis and block.file_path:
            df_edges = self._f._code_blocks.extract_data_flow_edges(
                block.content, block.file_path, project_id
            )
            for df_edge in df_edges:
                self._f._symbol_index.add_edge(df_edge, project_id)
            if df_edges:
                self._f._log_debug(
                    f"Data flow: {len(df_edges)} edge(s) extracted from {block.file_path}"
                )

        if self._f.tokenizer:
            block._cached_token_count = len(self._f.tokenizer.encode(block.content))
        else:
            block._cached_token_count = len(block.content) // 4
        block._update_importance()

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Processing new blocks
    # ═══════════════════════════════════════════════════════════════════════════

    async def _process_new_block(
        self,
        new_block: "CodeBlock",
        syms: List["CodeSymbol"],
        state: dict,
        project_id: str,
    ) -> None:
        """
        Register a brand‑new block: symbols, edges, conflict/obsolete checks,
        and hard eviction if max_active_blocks is exceeded.

        Q6: Migrates docstrings from renamed symbols before processing.
        """
        for sym in syms:
            sym.parent_block_hash = new_block.hash
        new_block.symbols = syms
        new_block.last_mentioned_msg_idx = state.message_count

        # --- 1. Index symbols and call-graph edges ---
        for sym in syms:
            self._f._symbol_index.add(sym, new_block.hash, project_id)
            caller_qid = qualify_symbol_name(sym.name, sym.parent_symbol, sym.file_path)
            for callee_name in sym.calls:
                edge = Edge(
                    src=caller_qid,
                    dst=callee_name,
                    type="calls",
                    weight=EDGE_WEIGHTS["calls"],
                    confidence=1.0,
                )
                self._f._symbol_index.add_edge(edge, project_id)

        # --- 2. Data-flow edges: ONE full-file AST pass per block ---
        if self._f.valves.enable_data_flow_analysis and new_block.file_path:
            df_edges = self._f._code_blocks.extract_data_flow_edges(
                new_block.content, new_block.file_path, project_id
            )
            for df_edge in df_edges:
                self._f._symbol_index.add_edge(df_edge, project_id)
            if df_edges:
                self._f._log_debug(
                    f"Data flow: {len(df_edges)} edge(s) extracted from {new_block.file_path}"
                )

        if any(s.calls for s in syms):
            state.has_any_calls = True

        # --- 3. Check for conflicting proposed changes ---
        is_conflicting = False
        if new_block.content_type == ContentType.PROPOSED_CHANGE:
            is_conflicting = self._f._code_blocks.has_conflicting_proposed_changes(
                state, new_block
            )
            if is_conflicting:
                new_block.importance_score = max(new_block.importance_score, 7.0)

        # --- 4. Insert the new block into active_blocks ---
        state.active_blocks[new_block.hash] = new_block

        # --- 5. Mark older blocks for the same file as obsolete (step 13) ---
        obsolete_hashes = []
        if new_block.file_path and self._f.valves.enable_obsolete_marking:
            for h, blk in list(state.active_blocks.items()):
                if h == new_block.hash:
                    continue
                if blk.file_path == new_block.file_path and not blk.pinned:
                    # Remove from symbol index
                    self._f._symbol_index.remove_all_for_block(
                        blk.hash, blk.symbols, project_id
                    )
                    # Mark obsolete
                    blk.obsolete = True
                    blk._update_importance()
                    obsolete_hashes.append(h)

            # --- Cap obsolete versions per file ---
            max_keep = self._f.valves.max_obsolete_versions_per_file
            if obsolete_hashes:
                if max_keep == 0:
                    for h in obsolete_hashes:
                        del state.active_blocks[h]
                    self._f._log_debug(
                        f"Removed {len(obsolete_hashes)} obsolete block(s) for '{new_block.file_path}' "
                        f"(max_obsolete_versions_per_file=0)."
                    )
                else:
                    obsolete_blocks = [
                        (h, state.active_blocks[h])
                        for h in obsolete_hashes
                        if h in state.active_blocks
                    ]
                    obsolete_blocks.sort(key=lambda x: x[1].timestamp, reverse=True)

                    to_remove = [h for h, _ in obsolete_blocks[max_keep:]]
                    for h in to_remove:
                        del state.active_blocks[h]

                    kept = len(obsolete_blocks) - len(to_remove)
                    self._f._log_debug(
                        f"Obsolete cap for '{new_block.file_path}': kept {kept} most recent "
                        f"out of {len(obsolete_blocks)} (max_obsolete_versions_per_file={max_keep})."
                    )

        # --- 6. Handle content-type specific actions ---
        if new_block.content_type == ContentType.PROPOSED_CHANGE:
            if new_block.file_path:
                state.recent_changes = [
                    c
                    for c in state.recent_changes
                    if not (
                        c.file_path
                        and c.file_path == new_block.file_path
                        and c.hash != new_block.hash
                    )
                ]
            state.recent_changes.append(new_block)
            if self._f.valves.enable_diff_application and not is_conflicting:
                for base in list(state.active_blocks.values()):
                    if (
                        base.content_type == ContentType.BASE_CODE
                        and base.file_path == new_block.file_path
                    ):
                        if await self._f._code_blocks.apply_change_with_diff(
                            base, new_block
                        ):
                            state.recent_changes = [
                                c
                                for c in state.recent_changes
                                if c.hash != new_block.hash
                            ]
                            state.committed_changes.append(new_block)
                            break
        elif new_block.content_type == ContentType.COMMITTED_CHANGE:
            state.committed_changes.append(new_block)
        elif (
            new_block.content_type == ContentType.ERROR
            and self._f.valves.preserve_error_context
        ):
            new_block.importance_score = min(new_block.importance_score + 3.0, 10.0)

        # --- 7. Hard eviction if too many active blocks ---
        if (
            self._f.valves.max_active_blocks > 0
            and len(state.active_blocks) > self._f.valves.max_active_blocks
        ):
            sorted_blocks = sorted(
                state.active_blocks.values(),
                key=lambda b: b.importance_score
                + (self._f.valves.raw_file_priority_boost if b.is_raw else 0),
                reverse=True,
            )
            keep_hashes = {
                b.hash for b in sorted_blocks[: self._f.valves.max_active_blocks]
            }
            to_remove_hard = [h for h in state.active_blocks if h not in keep_hashes]
            for h in to_remove_hard:
                block = state.active_blocks.get(h)
                if (
                    block
                    and self._f.valves.enable_block_paging
                    and self._f._pager is not None
                ):
                    paged = await self._f._pager.page_out_block(
                        block=block,
                        project_id=project_id,
                        state=state,
                        symbol_index=self._f._symbol_index,
                        chroma_collection=self._f.memory_collection,
                        embedder=self._f.embedder,
                    )
                    if paged:
                        del state.active_blocks[h]
                        continue
                if h in state.active_blocks:
                    del state.active_blocks[h]
            if to_remove_hard:
                self._f._log_debug(
                    f"Evicted {len(to_remove_hard)} blocks due to max_active_blocks limit. "
                    f"Their symbols remain in the index for lightweight context."
                )

    # ═══════════════════════════════════════════════════════════════════════════
    # 7. Updating assistant base blocks
    # ═══════════════════════════════════════════════════════════════════════════

    async def _update_assistant_base_blocks(
        self,
        extracted: List[dict],
        content_to_syms: Dict[str, List["CodeSymbol"]],
        state: dict,
        project_id: str,
    ) -> None:
        """When the assistant replies with code that overlaps existing blocks, merge it in."""
        for block_info in extracted:
            best_base = None
            best_sim = 0.0
            for base in state.active_blocks.values():
                if base.content_type == ContentType.BASE_CODE:
                    sim = self._f._code_blocks.calculate_code_similarity(
                        base.content, block_info["code"]
                    )
                    if sim > best_sim and sim > 0.6:
                        best_sim = sim
                        best_base = base
            if best_base and best_sim > 0.5 and best_sim < 0.98:
                self._f._symbol_index.remove_all_for_block(
                    best_base.hash, best_base.symbols, project_id
                )
                prev_content = best_base.content
                best_base.content = CodeBlockManager.sanitize_text(block_info["code"])
                best_base.hash = hashlib.md5(block_info["code"].encode()).hexdigest()[
                    :16
                ]
                best_base.timestamp = time.time()
                best_base.is_active = True
                best_base.importance_score = min(best_base.importance_score + 1.0, 10.0)
                reused = content_to_syms.get(block_info["code"])
                if reused is not None:
                    best_base.symbols = [
                        s.copy(update={"parent_block_hash": best_base.hash})
                        for s in reused
                    ]
                else:
                    best_base.symbols = await SignatureExtractor.extract_async(
                        best_base.content, best_base.file_path
                    )
                await self._reindex_block_symbols(best_base, project_id)
                if any(s.calls for s in best_base.symbols):
                    state.has_any_calls = True
                if prev_content != block_info["code"]:
                    await self._f._enrichment.generate_change_summary(
                        best_base.hash, prev_content, block_info["code"]
                    )

    # ═══════════════════════════════════════════════════════════════════════════
    # 8. Post‑update tasks
    # ═══════════════════════════════════════════════════════════════════════════

    async def _post_update_tasks(
        self,
        state: "ConversationState",
        project_id: str,
        new_blocks_pending: List["CodeBlock"],
        is_continuation: bool,
        pre_index_qids: Optional[Set[str]] = None,
    ) -> None:
        """
        Run all post-processing tasks after a new message has been indexed.

        Receives pre_index_qids: the set of qualified ids that were present in
        the symbol index BEFORE the new blocks were processed. Comparing this
        against the post-indexing state gives accurate deleted/added sets for
        rename detection. Computing both sets inside this function (after
        indexing) always produces empty sets because the symbol index already
        reflects the new state.

        Steps:
            1.  Increment message counter unless this is a continuation turn.
            2.  Remove duplicate blocks from the active set.
            3.  Expire blocks that have exceeded their TTL.
            4.  Detect symbol renames and migrate docstrings using pre/post
                index snapshots.
            5.  Generate periodic session summary.
            6.  Schedule background summaries for oversized code blocks.
            7.  Invalidate lightweight activation cache.
            8.  Invalidate stale CodePathViews.
            9.  Soft-evict cold blocks via ContextPager.
        """
        # -- Step 1: message counter --
        if not is_continuation:
            state.message_count += 1

        # -- Step 2: deduplicate blocks --
        if self._f.valves.auto_remove_duplicate_blocks:
            self._f._code_blocks.remove_duplicate_blocks(state, project_id)

        # -- Step 3: expire old blocks --
        await self._f._enrichment.expire_blocks_by_time(project_id)

        # -- Step 4: docstring rename migration --
        if new_blocks_pending and pre_index_qids is not None:
            try:
                post_index_qids: Set[str] = set(
                    self._f._symbol_index.get_all_qualified_names(project_id)
                )
                deleted_qids = pre_index_qids - post_index_qids
                added_qids = post_index_qids - pre_index_qids

                if deleted_qids and added_qids:
                    await self._f._enrichment._detect_and_migrate_renames(
                        deleted_qids, added_qids, project_id
                    )
            except Exception as e:
                self._f._log_debug(
                    f"_post_update_tasks: rename migration failed: "
                    f"{type(e).__name__}: {e}"
                )

        # -- Step 5: periodic session summary --
        if self._f.valves.enable_session_summary and not is_continuation:
            interval = self._f.valves.session_summary_interval_messages
            if (
                interval > 0
                and state.message_count % interval == 0
                and state.message_count > 0
            ):
                await self._f._enrichment.run_session_summary_task(
                    {
                        "project_id": project_id,
                        "message_count": state.message_count,
                        "code_state_hash": self._f._activation.compute_code_state_hash(
                            project_id
                        ),
                    },
                    self._f.valves.llm_model,
                )

        # -- Step 6: oversized block summaries --
        if (
            self._f.valves.max_code_block_tokens > 0
            and self._f.valves.code_block_overflow_action == "summarize"
        ):
            for block in state.active_blocks.values():
                if not block.obsolete:
                    await self._f._history_compressor.schedule_block_summary(
                        block, project_id
                    )

        # -- Step 7: invalidate lightweight cache --
        self._f._activation.invalidate_lightweight_cache(project_id)

        # -- Step 8: invalidate stale CodePathViews --
        if self._f.valves.enable_path_analysis:
            changed_symbols: Set[str] = set()
            for blk in new_blocks_pending:
                for sym in blk.symbols:
                    changed_symbols.add(sym.name)

            stale_path_ids: Set[str] = set()
            for sym_name in changed_symbols:
                for pid in self._f._path_index.mark_stale_for_symbol(
                    sym_name, project_id
                ):
                    stale_path_ids.add(pid)

            for pid in stale_path_ids:
                view = self._f._path_index.get(pid, project_id)
                if not view:
                    continue
                new_structural = self._f._activation.compute_structural_hash(
                    view.induced_nodes.keys(), project_id
                )
                new_call_graph = self._f._activation.compute_call_graph_hash(
                    view.induced_nodes.keys(), project_id
                )
                if view.is_stale(new_structural, new_call_graph):
                    view.structural_hash = new_structural
                    view.call_graph_hash = new_call_graph
                    view.summary = ""
                    view.business_label = ""
                    view.label_confidence = 0.0

            if stale_path_ids:
                self._f._log_debug(
                    f"Invalidated {len(stale_path_ids)} CodePathView(s) "
                    f"due to changes in {len(changed_symbols)} symbol(s)"
                )

        # -- Step 9: soft eviction via ContextPager --
        if self._f.valves.enable_block_paging and self._f._pager is not None:
            candidates = self._f._pager.get_eviction_candidates(
                state=state,
                project_id=project_id,
                activation_scores=getattr(self._f, "_last_activation_scores", {}).get(
                    project_id, {}
                ),
                paging_threshold=self._f.valves.block_paging_threshold,
                min_activation=self._f.valves.block_paging_min_activation,
            )
            for hash_ in candidates:
                block = state.active_blocks.get(hash_)
                if block:
                    paged = await self._f._pager.page_out_block(
                        block=block,
                        project_id=project_id,
                        state=state,
                        symbol_index=self._f._symbol_index,
                        chroma_collection=self._f.memory_collection,
                        embedder=self._f.embedder,
                    )
                    if paged:
                        del state.active_blocks[hash_]
            if candidates:
                self._f._log_debug(
                    f"Soft-evicted {len(candidates)} block(s) via ContextPager "
                    f"(active_blocks now {len(state.active_blocks)})"
                )


class InletOrchestrator:
    """Handles the early stages of request processing: extracting user
    information, classifying the session type, and preparing the code
    session for context assembly.

    Provides:
    * ``get_project_id()`` — returns the current project id from valves.
    * ``inlet_preprocess(body, project_id)`` — detects project switches,
      loads persisted edges and path views, and initiates KV‑slot restore.
    * ``inlet_extract_user_info(messages)`` — finds the last user message,
      strips code spans to isolate the question, and detects explicit
      slash‑commands.
    * ``inlet_prepare_code_session(messages, project_id, ...)`` —
      classifies whether the session involves code, triggers active‑block
      updates, and handles AutoContinue continuations.
    * ``classify_session(messages, project_id)`` — returns True if the
      conversation context indicates a coding session.
    * ``ensure_last_message_is_user(messages)`` — guarantees the message
      list ends with a user role.

    Docs 10–13 backported:
        E2 – detect short continuations and inherit use_case from previous turn.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """Initialize with a reference to the parent Filter."""
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Initialization & basic utilities
    # ═══════════════════════════════════════════════════════════════════════════

    def get_project_id(self) -> str:
        """Return the current project id from the valves configuration."""
        return self._f.valves.project_id

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Preprocessing (project switch, cache load, slot restore)
    # ═══════════════════════════════════════════════════════════════════════════

    async def inlet_preprocess(self, body: dict, project_id: str) -> list:
        """Handle project switching, symbol cache loading, and KV slot restore."""
        messages = body.get("messages", [])

        if self._f._last_project_id and self._f._last_project_id != project_id:
            self._f._log_debug(
                f"Project changed from {self._f._last_project_id} to {project_id}"
            )
            self._f._conversation_state_manager.clear_project(self._f._last_project_id)
            self._f._symbol_index.clear_project(self._f._last_project_id)
            self._f._project_state_manager.clear_project(self._f._last_project_id)
            self._f._block_change_summaries.clear()

        self._f._last_project_id = project_id

        # ── load persisted CodePathViews if index is empty ──
        if self._f.valves.enable_path_analysis and HAS_TREE_SITTER:
            existing_views = self._f._path_index.get_all(project_id)
            all_names = self._f._symbol_index.get_all_names(project_id)
            if all_names and not existing_views:
                self._f._log_debug(
                    "PathIndex empty but symbols exist — loading from DB"
                )
                db_views = await self._f._state_store.load_path_views_from_db(
                    project_id
                )
                for view in db_views:
                    self._f._path_index.add(view, project_id)

        # ── restore typed edges from DB ─────────
        if self._f.valves.enable_edge_persistence:
            restored = await self._f._state_store.load_symbol_edges_from_db(project_id)
            if restored > 0:
                self._f._log_debug(
                    f"Cross-session: {restored} symbol edges restored from DB. "
                    f"No need to re-paste code."
                )

        return messages

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. User info extraction (last message, query, commands)
    # ═══════════════════════════════════════════════════════════════════════════

    async def inlet_extract_user_info(
        self,
        messages: list,
    ) -> Tuple[Optional[dict], str, str, bool, bool]:
        """Extract last user message, query, and detect explicit commands."""
        last_user_msg = next(
            (m for m in reversed(messages) if m.get("role") == "user"), None
        )
        user_query = last_user_msg.get("content", "") if last_user_msg else ""

        has_code_blocks = False
        user_question = user_query
        if last_user_msg and user_query:
            try:
                spans = await self._f._code_blocks.get_code_spans(user_query)
                if spans:
                    user_question = CodeBlockManager.remove_code_spans(
                        user_query, spans
                    ).strip()
                if "```" in user_query:
                    has_code_blocks = True
                if spans:
                    has_code_blocks = True
            except Exception:
                spans = None
            if not user_question or len(user_question) < 10:
                cleaned = re.sub(r"```.*?```", "", user_query, flags=re.DOTALL)
                cleaned = re.sub(r"`[^`]+`", "", cleaned)
                cleaned = re.sub(
                    r"\b(def |class |import |from |function |const |let |var )",
                    "",
                    cleaned,
                )
                cleaned = cleaned.strip()
                user_question = (
                    cleaned if (cleaned and len(cleaned) >= 10) else user_query
                )

        is_explicit_command = last_user_msg and last_user_msg.get(
            "content", ""
        ).startswith("/")

        # Capture every system message now, joined in order, before any
        # downstream compression/trim step can touch them.
        system_msgs_now = [m for m in messages if m.get("role") == "system"]
        original_system_prompt = "\n\n".join(
            m.get("content", "")
            for m in system_msgs_now
            if m.get("content", "").strip()
        )
        self._f._original_system_prompt = original_system_prompt

        return (
            last_user_msg,
            user_query,
            user_question,
            is_explicit_command,
            has_code_blocks,
        )

    # ═══════════════════════════════════════════════════════════════════════════
    # 4. Code session preparation (classification, active block update)
    # ═══════════════════════════════════════════════════════════════════════════

    async def inlet_prepare_code_session(
        self,
        messages: list,
        project_id: str,
        user_query: str,
        is_continuation: bool = False,
    ) -> Tuple[bool, str]:
        """Classify the session and update active code blocks."""
        is_code_session = await self.classify_session(messages, project_id)

        if self._f.valves.enable_code_awareness and is_code_session:
            last_idx = len(messages) - 1
            await self._f._update_active_code(
                messages[last_idx], project_id, is_continuation=is_continuation
            )
            extracted_blocks, block_spans = (
                await self._f._code_blocks.extract_code_blocks(user_query)
            )
            if block_spans:
                user_question = CodeBlockManager.remove_code_spans(
                    user_query, block_spans
                ).strip()
                if not user_question or len(user_question) < 10:
                    user_question = user_query
            else:
                user_question = user_query

            pstate = self._f._project_state_manager.get_pstate(project_id)
            pstate["last_processed_message_idx"] = last_idx
        else:
            user_question = user_query

        state = self._f._conversation_state_manager.get(project_id)
        if not isinstance(state.active_blocks, dict):
            self._f._log_debug(
                "CRITICAL: active_blocks corrupted even after load; resetting to empty. "
                "Delete %s if this recurs." % self._f.valves.state_db_path
            )
            state.active_blocks = {}
            self._f._conversation_state_manager.set(project_id, state)

        return is_code_session, user_question

    # ═══════════════════════════════════════════════════════════════════════════
    # 5. Session classification (cached CrossEncoder or heuristic)
    # ═══════════════════════════════════════════════════════════════════════════

    async def classify_session(
        self,
        messages: list,
        project_id: str,
    ) -> bool:
        """
        Classify whether the current conversation is a code session.

        A code session enables Block A/B context injection, symbol indexing,
        and the full activation pipeline. Non-code sessions skip all of that
        for lower latency and token usage.

        The cache key includes project_id so that two projects with identical
        last-user-message content do not share a cached classification result.
        Without this, a code session in project A would cause project B (a
        documentation-only project with the same greeting) to receive full code
        context injection incorrectly.

        Classification cascade:
            1.  Extract the last user message; return False if absent or empty.
            2.  Build cache key from (project_id, query_hash); check cache.
            3.  Run cross-encoder against code-session exemplars.
            4.  Heuristic: if code indicators are present, return True immediately.
            5.  If cross-encoder confidence is sufficient, return heuristic result.
            6.  Otherwise call _classify_session_with_llm.
            7.  Store result in cache and return.
        """
        # -- Step 1: extract last user message --
        last_user = next(
            (m for m in reversed(messages) if m.get("role") == "user"),
            None,
        )
        if not last_user:
            return False

        query = (last_user.get("content") or "").strip()
        if not query:
            return False

        # -- Step 2: cache lookup -- project_id scoped key --
        query_hash = hashlib.md5(query.encode()).hexdigest()
        cache_key = f"{project_id}:{query_hash}"

        if hasattr(self, "_session_cache") and cache_key in self._session_cache:
            self._f._log_debug(
                f"classify_session: cache hit for '{project_id}' "
                f"(result={self._session_cache[cache_key]})"
            )
            return self._session_cache[cache_key]

        # -- Step 3: cross-encoder against code-session exemplars --
        exemplars = [
            "write python function class method code implementation",
            "fix bug error traceback exception refactor",
            "explain code review architecture design pattern",
            "what is the meaning of life philosophy history",
        ]
        pairs = [(query, ex) for ex in exemplars]
        raw_ce = await self._predict_cross_encoder(pairs)
        ce_scores: List[float] = (
            [self._normalize_cross_encoder_score(s) for s in raw_ce]
            if raw_ce is not None
            else []
        )

        # -- Step 4: code-indicator fast path --
        if self._f._code_blocks.has_code_indicators(query):
            self._cache_session_result(cache_key, True)
            return True

        # -- Step 5: heuristic from cross-encoder --
        if ce_scores and len(ce_scores) >= 3:
            code_signal = max(ce_scores[:3])
            prose_signal = ce_scores[3] if len(ce_scores) > 3 else 0.0
            confidence_threshold = getattr(
                self._f.valves, "session_classifier_ce_threshold", 0.65
            )
            if code_signal >= confidence_threshold:
                result = code_signal > prose_signal
                self._cache_session_result(cache_key, result)
                return result

        # -- Step 6: LLM classification --
        try:
            result = await self._classify_session_with_llm(
                query=query,
                ce_scores=ce_scores,
                project_id=project_id,
            )
        except Exception as e:
            self._f._log_debug(
                f"classify_session: LLM failed for '{project_id}', "
                f"defaulting to False: {type(e).__name__}: {e}"
            )
            result = False

        # -- Step 7: cache and return --
        self._cache_session_result(cache_key, result)
        self._f._log_debug(
            f"classify_session: result={result} for '{project_id}' "
            f"(ce={'yes' if ce_scores else 'none'})"
        )
        return result

    async def _classify_session_with_llm(
        self,
        query: str,
        ce_scores: list,
        project_id: str,
    ) -> bool:
        """
        LLM fallback for session classification when the CrossEncoder diff falls
        below session_classify_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False for
        a clean structured answer with no reasoning preamble.

        Args:
            query: The user message to classify.
            ce_scores: [code_score, text_score] from the CrossEncoder.
            project_id: Current project identifier, used for slot restoration.

        Returns:
            bool: True if the message belongs to a coding session, False otherwise.
        """
        prompt = (
            f"CrossEncoder scores — code_session: {ce_scores[0]:.2f}, "
            f"not_code_session: {ce_scores[1]:.2f}\n\n"
            f"Message:\n{query}\n\n"
            f"Classify whether this message belongs to a coding session.\n\n"
            f"Code session signals: contains 'def', 'class', 'import', backticks, "
            f"tracebacks, or questions about code behaviour.\n"
            f"Non-code session signals: greetings, general conversation, "
            f"questions unrelated to programming.\n\n"
            f"Examples:\n"
            f'  "def foo(): pass"              → {{"is_code_session": true}}\n'
            f'  "how does this function work?" → {{"is_code_session": true}}\n'
            f'  "good morning"                 → {{"is_code_session": false}}\n'
            f'  "tengo un error en la vida"    → {{"is_code_session": false}}\n\n'
            f"Output only the JSON object."
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a strict binary classifier. "
                "Output ONLY a valid JSON object with a single boolean field "
                "'is_code_session'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="session_classify_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        # Restore the KV slot after any auxiliary LLM call.
        if self._f.valves.enable_slot_persistence:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return False

        try:
            data = json.loads(response)
            return bool(data.get("is_code_session", False))
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_classify_session_with_llm: JSON parse error — "
                f"response: {response[:200]!r}"
            )
            return False

    def _cache_session_result(self, cache_key: Optional[str], result: bool) -> None:
        """Cache the session classification result."""
        if cache_key:
            self._f._session_classify_cache[cache_key] = (result, time.time())
            if len(self._f._session_classify_cache) >= 500:
                items = sorted(
                    self._f._session_classify_cache.items(), key=lambda x: x[1][1]
                )
                self._f._session_classify_cache = dict(items[-400:])

    # ═══════════════════════════════════════════════════════════════════════════
    # 6. Message utilities
    # ═══════════════════════════════════════════════════════════════════════════

    def ensure_last_message_is_user(self, messages: list) -> list:
        """
        Guarantee that the final message in the list has role='user'.

        Required by the Anthropic messages API which mandates that conversations
        end on a user turn. When the pipeline processes outlet responses the
        final message may temporarily be from the assistant.

        Returns the original list unmodified when it already ends on a user
        message. Appends a minimal user sentinel otherwise.

        Steps:
            1.  Guard empty list — nothing to check or fix.
            2.  Check role of last message.
            3.  Append sentinel user message only when needed.
        """
        # -- Step 1: empty list guard --
        if not messages:
            self._f._log_debug(
                "ensure_last_message_is_user: received empty message list, "
                "returning as-is"
            )
            return messages

        # -- Step 2: check last message role --
        if messages[-1].get("role") == "user":
            return messages

        # -- Step 3: append sentinel --
        self._f._log_debug(
            f"ensure_last_message_is_user: last role is "
            f"'{messages[-1].get('role')}', appending user sentinel"
        )
        return messages + [{"role": "user", "content": ""}]

    # ═══════════════════════════════════════════════════════════════════════════
    # 7. Intent classification with continuation inheritance – NEW (E2)
    # ═══════════════════════════════════════════════════════════════════════════

    # ── E2: continuation detection ──────────────────────────────────────────
    _CONTINUATION_RE = re.compile(
        r"^(ok|okay|sí|si|yes|yep|yeah|continúa|continua|continue|"
        r"go on|adelante|sigue|prosigue|hazlo|hazla|genéralo|generate it|"
        r"implementa|implement|de acuerdo|sounds good|great|perfecto|"
        r"bien|vale|listo|done|proceed)\W*$",
        re.IGNORECASE | re.UNICODE,
    )

    def _is_continuation_message(
        self, message: str, classifier_confidence: float
    ) -> bool:
        """E2: detect short continuations with no intent signal.

        Criteria:
        - No code blocks (pasted code always carries intent)
        - Fewer than 15 words in non-code portions
        - Classifier confidence below 0.80 (if classifier is certain, trust it)
        """
        if "```" in message:
            return False
        text_only = re.sub(r"```.*?```", "", message, flags=re.DOTALL).strip()
        if len(text_only.split()) > 15:
            return False
        if classifier_confidence >= 0.80:
            return False
        return True

    async def classify_intent_with_continuation(
        self,
        user_query: str,
        project_id: str,
        intent_vector: Optional[dict] = None,
        is_continuation: bool = False,
    ) -> Tuple[str, dict, str]:
        if intent_vector is None:
            intent_vector = await self._f._commands.classify_intent(
                user_query, project_id
            )
        (
            use_case_key,
            profile_copy,
            human_label,
        ) = await self._f._ctx_builder.classify_use_case(
            user_query, intent_vector, project_id
        )
        confidence = max(intent_vector.values()) if intent_vector else 0.5
        pstate = self._f._project_state_manager.get_pstate(project_id)

        if is_continuation:
            inherited = pstate.get("last_use_case")
            if inherited:
                self._f._log_debug(
                    f"use_case: inheriting '{inherited}' from previous turn "
                    f"(genuine continuation, classifier had '{use_case_key}')"
                )
                use_case_key = inherited
                profile_copy = dict(
                    self._f._ctx_builder.LOD_PROFILES.get(inherited, {})
                )
                human_label = UseCase(inherited).label
        else:
            pstate["last_use_case"] = use_case_key

        return use_case_key, profile_copy, human_label


class SystemPromptBuilder:
    """Assembles the complete system prompt from two layers: a stable,
    KV‑cache‑friendly Block A (built once per code state) and a dynamic,
    per‑query Block B that injects LTM, activated code, and proactive
    suggestions.

    Provides:
    * ``build(messages, project_id, ...)`` — orchestrates Block A + Block B
      construction, runs parallel checks (contradiction, cache, duplicate
      detection), and returns the static block, dynamic injection list,
      an optional cached response, and the assembled preliminary system
      prompt.
    * Internal helpers for each dynamic source: LTM retrieval, contradiction
      warning injection, activated code context via ``ContextBuilder``,
      proactive cleanup/summarisation suggestions, and persisted
      conversation summaries.

    Docs 10–13 backported:
        M7 – computes and stores block_a_rebuild_reason in pstate.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        self._f = filter_ref

    # ═══════════════════════════════════════════════════════════════════════════
    # 1. Main orchestration
    # ═══════════════════════════════════════════════════════════════════════════

    async def build(
        self,
        messages: List[dict],
        project_id: str,
        user_query: str,
        user_question: str,
        is_code_session: bool,
        last_user_msg: Optional[dict],
        state: dict,
        slot_busy: bool = False,
        is_continuation: bool = False,
        intent_vector: Optional[dict] = None,
    ) -> Tuple[str, List[Tuple[str, str]], Optional[dict], str]:
        """
        Orchestrate the construction of the two-block system prompt.

        Returns (static_block, dynamic_injections, cached_response, prelim_system).
        """
        # -- REGION 1: Resolve per-project state --
        psm = self._f._project_state_manager
        pstate = psm.get_pstate(project_id)

        # -- REGION 2: Build Block A (static) --
        slot_free = not slot_busy
        static_block = await self._f._ctx_builder.build_block_a(
            project_id=project_id,
            is_code_session=is_code_session,
            is_continuation=is_continuation,
        )

        # -- REGION 3: Build Hub‑Bodies Tier --
        hub_tier_text, hub_tier_hash, hub_tier_qids = (
            self._f._ctx_builder._build_hub_bodies_tier(project_id)
        )
        # Almacenar en pstate (raw para claves de una sola clase)
        pstate_raw = psm.get_pstate(project_id)
        pstate_raw["hub_tier_text"] = hub_tier_text
        pstate_raw["hub_tier_hash"] = hub_tier_hash
        # Usar accesores tipados para claves compartidas
        psm.set_hub_tier_qids(project_id, hub_tier_qids)
        psm.set_hub_tier_prev_seeds(
            project_id,
            psm.get_hub_tier_seeds_this_turn(project_id),
        )
        psm.set_hub_tier_seeds_this_turn(project_id, list(hub_tier_qids))

        # -- REGION 4: Block B — Dynamic per-query injections --
        dynamic_injections: List[Tuple[str, str]] = []

        # 4a: Compute use_case label
        use_case, _, use_case_label = await self._f._ctx_builder.classify_use_case(
            user_query, intent_vector or {}, project_id
        )

        # 4b: LTM retrieval (with current messages for deduplication)
        self._f._log_debug("🔄 Block B – Step 1/5: LTM per-query retrieval")
        ltm_text = await self._build_ltm_injection(
            project_id,
            user_question,
            user_query,
            is_code_session,
            slot_free,
            use_case_label,
            is_continuation=is_continuation,
            current_messages=messages,
        )
        if ltm_text:
            dynamic_injections.append(("high", ltm_text))

        # -- 4c: Parallel checks --
        self._f._log_debug("🔄 Block B – Step 2/5: Parallel checks")
        contradiction_warning, cached_response, duplicate_match = (
            await self._build_parallel_checks(
                messages, user_query, project_id, state, slot_free
            )
        )
        if cached_response:
            return static_block, [], cached_response, ""
        if contradiction_warning and self._f.valves.contradiction_inject_warning:
            dynamic_injections.append(("medium", contradiction_warning))
        if duplicate_match:
            dynamic_injections.append(
                (
                    "medium",
                    f"⚠️ **Note**: Similar question asked before "
                    f"(similarity {duplicate_match['sim']:.2f}).",
                )
            )

        # -- 4d: Activated code --
        self._f._log_debug("🔄 Block B – Step 3/5: Code activated by query")
        active_ctx = await self._build_activated_code(
            user_query, project_id, messages, is_code_session, slot_free
        )
        if active_ctx:
            dynamic_injections.append(("critical", active_ctx))

        # -- 4e: Proactive suggestions --
        self._f._log_debug("🔄 Block B – Step 4/5: Proactive suggestions")
        for prio, text in await self._build_suggestions(
            state, project_id, messages, is_code_session
        ):
            dynamic_injections.append((prio, text))

        # -- 4f: Assemble prelim_system --
        self._f._log_debug("🔄 Block B – Step 5/5: Assemble prelim_system")
        prelim_system = self._assemble_prelim_system(
            static_block,
            hub_tier_text,
            dynamic_injections,
            messages,
        )

        # Guardar últimas puntuaciones de activación para prefetch y seguimiento LOD
        pstate["last_activation_scores"] = getattr(
            self._f, "_last_activation_scores", {}
        ).get(project_id, {})

        self._f._log_debug("🔄 Block B: complete")
        return static_block, dynamic_injections, None, prelim_system

    # ═══════════════════════════════════════════════════════════════════════════
    # 2. Block B – Dynamic injections (helpers)
    # ═══════════════════════════════════════════════════════════════════════════

    async def _build_ltm_injection(
        self,
        project_id: str,
        user_question: str,
        user_query: str,
        is_code_session: bool,
        slot_free: bool,
        use_case_label: str = "General Programming",
        is_continuation: bool = False,
        current_messages: list = None,
    ) -> Optional[str]:
        """
        Retrieve relevant memories from LTM and render them as an injectable
        context section.

        Enforces a hard token cap (ltm_injection_max_tokens) on the rendered
        section before returning. Without this cap, a large retrieval result
        (10 code-heavy memories × 800 tokens each) consumes 8 000+ tokens
        before Block A/B have been assembled, leaving insufficient budget for
        the actual code context and CoT reasoning.

        Returns None when no memories are found or the rendered section is
        empty, signalling to the caller that no LTM block should be injected.

        Steps:
            1.  Skip when LTM injection is disabled or slot is busy.
            2.  Retrieve memories via retrieve_memories_unified.
            3.  Deduplicate against current window content.
            4.  Render the LTM section.
            5.  Enforce token budget; truncate if over limit.
            6.  Return section string or None.
        """
        # -- Step 1: feature flags --
        if not getattr(self._f.valves, "enable_ltm_injection", True):
            return None
        if not slot_free and not getattr(
            self._f.valves, "ltm_inject_when_slot_busy", False
        ):
            return None

        # -- Step 2: retrieve --
        try:
            memories = await self._f._ltm.retrieve_memories_unified(
                query=user_question or user_query,
                project_id=project_id,
                use_case_label=use_case_label,
                slot_free=slot_free,
                is_continuation=is_continuation,
            )
        except Exception as e:
            self._f._log_debug(
                f"_build_ltm_injection: retrieval failed for '{project_id}': "
                f"{type(e).__name__}: {e}"
            )
            return None

        if not memories:
            return None

        # -- Step 3: deduplicate against current window --
        if current_messages:
            window_texts = [
                m.get("content", "") for m in current_messages[-6:] if m.get("content")
            ]
            window_norms = [self._normalize_for_dedup(t) for t in window_texts]
            unique_memories = []
            for mem in memories:
                norm = self._normalize_for_dedup(mem.get("content", ""))
                if not self._overlaps_window(norm, window_norms):
                    unique_memories.append(mem)
            memories = unique_memories

        if not memories:
            return None

        # -- Step 4: render --
        try:
            section = await self._render_ltm_section(
                project_id=project_id,
                memories=memories,
                current_messages=current_messages or [],
            )
        except Exception as e:
            self._f._log_debug(
                f"_build_ltm_injection: render failed for '{project_id}': "
                f"{type(e).__name__}: {e}"
            )
            return None

        if not section or not section.strip():
            return None

        # -- Step 5: enforce token budget --
        max_ltm_tokens = getattr(self._f.valves, "ltm_injection_max_tokens", 1500)
        if max_ltm_tokens > 0:
            actual_tokens = self._f._tokens.estimate_code_tokens(section)
            if actual_tokens > max_ltm_tokens:
                section = self._f._tokens.truncate_text_to_tokens(
                    section, max_ltm_tokens
                )
                section += "\n_[LTM section truncated to fit context budget]_"
                self._f._log_debug(
                    f"_build_ltm_injection: truncated LTM section from "
                    f"~{actual_tokens} to {max_ltm_tokens} tokens for '{project_id}'"
                )

        # -- Step 6: return --
        self._f._log_debug(
            f"_build_ltm_injection: injecting {len(memories)} memories "
            f"(~{self._f._tokens.estimate_code_tokens(section)} tokens) "
            f"for '{project_id}'"
        )
        return section

    async def _render_ltm_section(
        self,
        project_id: str,
        memories: list,
        current_messages: list = None,
    ) -> str:
        """
        Format retrieved memories into a structured LTM context section.

        Each memory entry is individually truncated to ltm_max_tokens_per_entry
        before being added to the section. Without per-entry truncation, a
        single code-heavy memory can fill the entire LTM budget, pushing out
        all other memories and causing _build_ltm_injection to truncate the
        section mid-entry (e.g., mid-function body), which confuses the model.

        Steps:
            1.  Resolve per-entry token limit from valves.
            2.  For each memory: extract content, truncate, format, append.
            3.  Prepend section header and return.
        """
        if not memories:
            return ""

        # -- Step 1: per-entry limit --
        max_per_entry = getattr(self._f.valves, "ltm_max_tokens_per_entry", 300)

        # -- Step 2: render each entry --
        parts: List[str] = []
        for mem in memories:
            content = mem.get("content", "").strip()
            metadata = mem.get("metadata", {})
            score = mem.get("score", 0.0)

            if not content:
                continue

            # Per-entry truncation before assembly
            if max_per_entry > 0:
                entry_tokens = self._f._tokens.estimate_code_tokens(content)
                if entry_tokens > max_per_entry:
                    content = self._f._tokens.truncate_text_to_tokens(
                        content, max_per_entry
                    )
                    content += " …"

            # Strip any existing LTM prefix to avoid double-labelling
            content = self._strip_ltm_prefix(content)

            # Role label and file hint
            role = metadata.get("role", "")
            file_path = metadata.get("file_path", "")
            label_parts = []
            if role:
                label_parts.append(role)
            if file_path:
                label_parts.append(file_path)
            label = " · ".join(label_parts)

            if label:
                entry = f"[{label}] {content}"
            else:
                entry = content

            if self._f.valves.debug:
                entry += f" _(ltm score: {score:.2f})_"

            parts.append(f"- {entry}")

        if not parts:
            return ""

        # -- Step 3: prepend header --
        header = "_Relevant context from earlier in this session or past sessions:_"
        return f"{header}\n" + "\n".join(parts)

    async def _ltm_dedup_with_llm(
        self, norm: str, window_excerpts: list, ce_score: float, project_id: str
    ) -> bool:
        """
        LLM fallback for LTM deduplication when the CrossEncoder diff falls
        below ltm_dedup_llm_threshold.

        Uses response_format={"type":"json_object"} and enable_thinking=False
        for a clean structured answer. Default on failure is False (unique) to
        avoid silently dropping memories that may be relevant.

        Excerpts are limited to the 3 most recent entries, each capped at 250
        chars individually, rather than truncating the concatenated string at
        an arbitrary byte boundary. This avoids feeding the model incomplete
        sentences that corrupt semantic comparison.

        Args:
            norm: Normalized fragment to check for duplication. Passed as-is
                  without truncation — it is already a condensed LTM fragment.
            window_excerpts: List of current conversation excerpts to compare
                             against. Only the first 3 are used.
            ce_score: CrossEncoder duplicate score (higher = more likely duplicate).
            project_id: Current project identifier, used for slot restoration.

        Returns:
            bool: True if the fragment is a duplicate, False if unique.
        """
        if not window_excerpts:
            return False

        # Limit to the 3 most recent excerpts, each capped individually.
        # Truncating the joined string would risk cutting mid-sentence and
        # feeding the model incomplete context that corrupts semantic comparison.
        window_text = "\n".join(excerpt[:250] for excerpt in window_excerpts[:3])

        prompt = (
            f"CrossEncoder duplicate score: {ce_score:.2f} "
            f"(higher = more likely duplicate)\n\n"
            f"Fragment to check:\n{norm}\n\n"
            f"Current conversation excerpts:\n{window_text}\n\n"
            f"Is the fragment a duplicate of the conversation excerpts? "
            f"Focus on semantic meaning — different words but same meaning = duplicate. "
            f"New information = unique.\n\n"
            f'Output only the JSON object, e.g. {{"is_duplicate": false}}'
        )

        response = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You are a semantic duplicate detector. "
                "Output ONLY a valid JSON object with a single boolean field 'is_duplicate'. "
                "Your entire response must start with { and end with }."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=0,
            temperature=0.0,
            label="ltm_dedup_llm",
            response_format={"type": "json_object"},
            enable_thinking=False,
            log_raw_response=False,
        )

        if self._f.valves.enable_slot_persistence:
            await self._f._project_state_manager.slot_restore_for_continuity(project_id)

        if not response:
            return False

        try:
            data = json.loads(response)
            return bool(data.get("is_duplicate", False))
        except (json.JSONDecodeError, Exception):
            self._f._log_debug(
                f"_ltm_dedup_with_llm: JSON parse error — "
                f"response: {response[:200]!r}"
            )
            return False

    async def _build_parallel_checks(
        self,
        messages: List[dict],
        user_query: str,
        project_id: str,
        state: dict,
        slot_free: bool,
    ) -> Tuple[Optional[str], Optional[dict], Optional[dict]]:
        """
        Run contradiction detection, response cache lookup, and duplicate
        question detection concurrently to minimise wall-clock latency.

        Each task is independent: a failure in one must not discard results
        from the others. asyncio.gather with return_exceptions=True is used
        so that an exception from any single task is captured as a result
        value rather than re-raised, allowing the caller to receive whatever
        partial results are available.

        Returns:
            contradiction_warning : Optional[str]   — inline warning text or None
            cached_response       : Optional[dict]  — cached LLM response or None
            duplicate_result      : Optional[dict]  — prior duplicate Q&A or None

        Steps:
            1.  Build context hash for cache lookup.
            2.  Schedule all three tasks concurrently with individual timeouts.
            3.  Await with return_exceptions=True.
            4.  Unpack results, converting exceptions to None with debug logging.
        """
        # -- Step 1: build context hash --
        context_hash = self._f._activation.compute_context_hash(messages)

        contradiction_timeout = getattr(self._f.valves, "contradiction_timeout", 8.0)
        cache_timeout = getattr(self._f.valves, "response_cache_timeout", 5.0)
        duplicate_timeout = getattr(self._f.valves, "duplicate_detection_timeout", 5.0)

        # -- Step 2: schedule all tasks --
        async def _safe_contradiction() -> Optional[str]:
            return await asyncio.wait_for(
                self._f._command_router._detect_contradictions(messages, project_id),
                timeout=contradiction_timeout,
            )

        async def _safe_cache() -> Optional[dict]:
            if not slot_free:
                return None
            return await asyncio.wait_for(
                self._f._ltm.find_cached_response(user_query, context_hash, state),
                timeout=cache_timeout,
            )

        async def _safe_duplicate() -> Optional[dict]:
            if not slot_free:
                return None
            return await asyncio.wait_for(
                self._f._ltm.find_duplicate_question(user_query, project_id),
                timeout=duplicate_timeout,
            )

        # -- Step 3: await with per-task exception capture --
        results = await asyncio.gather(
            _safe_contradiction(),
            _safe_cache(),
            _safe_duplicate(),
            return_exceptions=True,
        )

        # -- Step 4: unpack, log, and sanitise exceptions --
        def _unwrap(result: Any, label: str) -> Any:
            if isinstance(result, BaseException):
                self._f._log_debug(
                    f"_build_parallel_checks: {label} failed: "
                    f"{type(result).__name__}: {result}"
                )
                return None
            return result

        contradiction_warning = _unwrap(results[0], "contradiction")
        cached_response = _unwrap(results[1], "cache")
        duplicate_result = _unwrap(results[2], "duplicate")

        return contradiction_warning, cached_response, duplicate_result

    @staticmethod
    def _strip_ltm_prefix(doc: str) -> str:
        """
        Remove the LTM prefix from a document.

        Prefixes like '[Context: ...]\n\n' or '[Past conversation — ...]\n'
        are removed so that the raw content can be compared for deduplication
        purposes.

        Args:
            doc (str): The document text, possibly with a prefix.

        Returns:
            str: The document text without the prefix.
        """
        return re.sub(r"^\s*\[[^\]]*\]\s*\n+", "", doc, count=1)

    @staticmethod
    def _normalize_for_dedup(text: str) -> str:
        """
        Normalize text for duplicate comparison.

        The text is lower-cased, whitespace is collapsed, and it is truncated
        to 600 characters to keep comparisons fast and focused on the most
        important part of the content.

        Args:
            text (str): The text to normalize.

        Returns:
            str: The normalized text, or an empty string if the input is empty.
        """
        if not text:
            return ""
        return re.sub(r"\s+", " ", text).strip().lower()[:600]

    def _overlaps_window(self, norm: str, window_norms: list) -> bool:
        """
        Check if a normalized fragment overlaps with any message in the current window.

        Uses substring containment (cheap) and, if rapidfuzz is available,
        partial_ratio with a threshold of 90 to catch semantic duplicates even
        when wording differs slightly.

        Args:
            norm (str): The normalized fragment text.
            window_norms (list): List of normalized window messages.

        Returns:
            bool: True if the fragment overlaps with any window message,
            False otherwise.
        """
        for w in window_norms:
            if not w:
                continue
            if norm in w or w in norm:
                return True
            if HAS_FUZZ:
                from rapidfuzz import fuzz

                if fuzz.partial_ratio(norm[:300], w[:300]) >= 90:
                    return True
        return False

    async def _build_activated_code(
        self,
        user_query: str,
        project_id: str,
        messages: List[dict],
        is_code_session: bool,
        slot_free: bool,
    ) -> Optional[str]:
        """Obtain LOD-activated code context for the current query, if applicable."""
        if not (is_code_session and self._f.valves.enable_code_awareness):
            return None

        if self._f.valves.enable_path_analysis:
            intent_vector = await self._f._commands.classify_intent(
                user_query, project_id
            )
            active_ctx = await self._f._ctx_builder.build_block_b(
                project_id=project_id,
                query=user_query,
                messages=messages,
                slot_free=slot_free,
                intent_vector=intent_vector,
                is_continuation=not slot_free,
            )

            # --- Check suppression before falling back ---
            active_use_case, _, _ = await self._f._ctx_builder.classify_use_case(
                user_query, intent_vector, project_id
            )
            suppress_sigs = (
                self._f.valves.skeleton_tier_suppresses_block_b_signatures
                and active_use_case != "D"
                and self._f._ctx_builder._is_skeleton_tier_active(project_id)
            )

            if active_ctx:
                return active_ctx
            elif suppress_sigs:
                # If suppression is active, don't fall back to full context
                self._f._log_debug(
                    "Skeleton tier active and suppress_sigs=True, "
                    "skipping fallback to active_code_context to avoid duplication"
                )
                return ""
            else:
                # Fallback to full context
                return self._f._activation.get_active_code_context(
                    project_id, user_query
                )

        return self._f._activation.get_active_code_context(project_id, user_query)

    async def _build_suggestions(
        self,
        state: dict,
        project_id: str,
        messages: List[dict],
        is_code_session: bool,
    ) -> List[Tuple[str, str]]:
        """Collect proactive cleanup, summarization, and command suggestions."""
        suggestions: List[Tuple[str, str]] = []

        # ── Cleanup suggestions ───────────────────────────────────────
        if (
            self._f.valves.cleanup_suggestions_enabled
            and self._f.valves.cleanup_proactive_suggestions
            and is_code_session
        ):
            candidates = self._f._activation.get_inactive_block_candidates(project_id)
            if candidates:
                last_sugg_idx = state.last_cleanup_suggestion_msg_idx
                if (
                    state.message_count - last_sugg_idx
                    >= self._f.valves.cleanup_suggestion_cooldown_messages
                ):
                    suggestions.append(
                        (
                            "low",
                            f"[CodeAware] {len(candidates)} inactive block(s). "
                            f"Use `/status` or `/clean`.",
                        )
                    )
                    state.last_cleanup_suggestion_msg_idx = state.message_count
                    self._f._conversation_state_manager.set(project_id, state)

        # ── Token pressure suggestion ──────────────────────────────────
        sys_msgs = [m for m in messages if m.get("role") == "system"]
        history_msgs = [m for m in messages if m.get("role") != "system"]
        total_tokens = self._f._tokens.estimate_tokens(sys_msgs + history_msgs)
        if self._f.valves.context_window_tokens > 0:
            suggestion = (
                await self._f._history_compressor.check_and_suggest_summarization(
                    project_id, total_tokens, self._f.valves.context_window_tokens
                )
            )
            if suggestion:
                suggestions.append(("low", suggestion))

        # ── Command suggestion ─────────────────────────────────────────
        cmd_suggestion = await self._f._commands.suggest_commands(project_id, state)
        if cmd_suggestion:
            suggestions.append(("low", cmd_suggestion))

        # ── Persisted conversation summaries ───────────────────────────
        summaries = state.conversation_summaries
        if summaries:

            def _summary_header(s: dict) -> str:
                ct = s.get("covers_turns")
                turns = f", turns {ct[0]}-{ct[1]}" if ct else ""
                tag = (
                    "Consolidated summary"
                    if s.get("level", 1) >= 2
                    else "Summary of earlier conversation"
                )
                ts = datetime.fromtimestamp(
                    s.get("created_at", 0), tz=timezone.utc
                ).strftime("%Y-%m-%d %H:%M")
                return f"[{tag}{turns} — {ts}]"

            joined = "\n\n".join(
                f"{_summary_header(s)}\n{s['text']}" for s in summaries
            )
            suggestions.append(("medium", joined))

        return suggestions

    # ═══════════════════════════════════════════════════════════════════════════
    # 3. Final assembly (budget‑aware)
    # ═══════════════════════════════════════════════════════════════════════════

    def _assemble_prelim_system(
        self,
        static_block: str,
        hub_tier: str,
        dynamic_injections: List[Tuple[str, str]],
        messages: List[dict],
    ) -> str:
        """
        Concatenate static block, hub tier, and dynamic injections into the
        preliminary system prompt sent to the model.

        Filters out injection entries whose content is None, empty, or
        whitespace-only before assembly. Without this filter, callers that
        append (label, None) or (label, "") produce literal "None" or empty
        section headers in the system prompt, wasting tokens and potentially
        confusing the model.

        Steps:
            1.  Start with the static block (always present).
            2.  Append hub tier if non-empty.
            3.  Filter dynamic injections: skip entries with falsy content.
            4.  Append each valid injection as a labelled section.
            5.  Return the assembled system prompt.
        """
        parts: List[str] = []

        # -- Step 1: static block --
        if static_block and static_block.strip():
            parts.append(static_block.strip())

        # -- Step 2: hub tier --
        if hub_tier and hub_tier.strip():
            parts.append(hub_tier.strip())

        # -- Step 3 + 4: filter and append dynamic injections --
        for label, content in dynamic_injections:
            if not content:
                continue
            if not isinstance(content, str):
                self._f._log_debug(
                    f"_assemble_prelim_system: skipping injection "
                    f"'{label}' with non-string content "
                    f"({type(content).__name__})"
                )
                continue
            content_stripped = content.strip()
            if not content_stripped:
                continue
            if label and label.strip():
                parts.append(f"### {label.strip()}\n{content_stripped}")
            else:
                parts.append(content_stripped)

        # -- Step 5: assemble --
        return "\n\n".join(parts)


class WindowManager:
    """
    Single owner of the prose history window policy.

    Replaces (in Phase 1, step 3):
        MessageAssembler._apply_turn_based_window     (M1)
        MessageAssembler._trim_and_summarize           (M3 + M4)
        MessageAssembler._index_turns
        MessageAssembler._summary_sort_key

    Does not replace:
        MessageAssembler._apply_history_llmlingua      (M2, decoupled)
        HistoryCompressor.summarize_messages           (helper)
        HistoryCompressor._consolidate_summaries       (helper)
        HistoryCompressor._merge_summaries             (helper)
        MessageAssembler._persist_turn_summary_to_ltm  (helper)

    Complexity guarantee:
        Context history: O(K) bounded by history_max_tokens.
        Total session (T turns): O(T) linear — same as v9.0.0.

    Seams for future phases:
        _on_frontier_advance(old_hwm, new_hwm)  → Phase 2 (KV-freeze)
        _frontier_c_turn                        → Phase 3 (LLMLingua)
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the WindowManager with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._f = filter_ref
        # Phase 3 seam: turn that separates raw band from compressible band.
        # In Phase 1 it is updated but nobody reads it.
        self._frontier_c_turn: int = 0

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Public entry point
    # ═══════════════════════════════════════════════════════════════════════

    # ------------------------------------------------------------------
    # Region: Main Entry Point
    # ------------------------------------------------------------------

    async def apply(
        self,
        messages: List[dict],
        state: ConversationState,
        project_id: str,
        slot_free: bool,
    ) -> Tuple[List[dict], str]:
        """
        Apply the history window policy.

        Args:
            messages: Full list (system + history).
            state: ConversationState for the project.
            project_id: Project identifier.
            slot_free: If False, no summaries are generated.

        Returns:
            (messages_final, pending_summary).
        """
        v = self._f.valves

        # ------------------------------------------------------------------
        # Clean orphan tool calls at front.
        # ------------------------------------------------------------------
        if v.preserve_tool_calls:
            while messages and messages[0].get("role") == "tool":
                messages = messages[1:]
            if (
                messages
                and messages[0].get("role") == "assistant"
                and messages[0].get("tool_calls")
            ):
                tool_call_ids = {tc.get("id") for tc in messages[0]["tool_calls"]}
                tool_response_ids = {
                    m.get("tool_call_id")
                    for m in messages[1:]
                    if m.get("role") == "tool"
                }
                if not tool_call_ids.issubset(tool_response_ids):
                    messages = messages[1:]

        # ------------------------------------------------------------------
        # AutoContinue deferral.
        # ------------------------------------------------------------------
        if v.compaction_defer_during_autocontinue and self._is_autocontinue_active(
            messages
        ):
            self._f._log_debug(
                "WindowManager: deferral — AutoContinue active, no changes"
            )
            return messages, ""

        # ------------------------------------------------------------------
        # Separate system / history.
        # ------------------------------------------------------------------
        sys_msgs = [m for m in messages if m.get("role") == "system"]
        history = [m for m in messages if m.get("role") != "system"]
        if not history:
            return messages, ""

        # ------------------------------------------------------------------
        # Effective budget.
        # ------------------------------------------------------------------
        budget = self._effective_budget(project_id)

        # ------------------------------------------------------------------
        # Turn indexing.
        # ------------------------------------------------------------------
        turns, _total_turns = self._index_turns(history)

        # ------------------------------------------------------------------
        # Compute frontier.
        # ------------------------------------------------------------------
        kept, old_msgs, cut_turn = self._compute_frontier(history, turns, budget)

        # ------------------------------------------------------------------
        # Log B: history fits early return.
        # ------------------------------------------------------------------
        if not old_msgs:
            self._f._log_debug(
                f"WindowManager: history fits — {len(history)} msg(s), "
                f"no compaction needed"
            )
            return sys_msgs + kept, ""

        # ------------------------------------------------------------------
        # Emergency cap.
        # ------------------------------------------------------------------
        kept, old_msgs = self._apply_emergency_cap(
            history, turns, kept, old_msgs, budget
        )
        if not old_msgs:
            return sys_msgs + kept, ""

        # ------------------------------------------------------------------
        # Minimum batch.
        # ------------------------------------------------------------------
        old_turn_nums = {t for m, t in zip(history, turns) if m in old_msgs}
        if len(old_turn_nums) < v.summarize_batch_turns:
            self._f._log_debug(
                f"WindowManager: batch too small "
                f"({len(old_turn_nums)} < {v.summarize_batch_turns} turns), "
                "keeping raw"
            )
            return sys_msgs + history, ""

        # ------------------------------------------------------------------
        # Summarize batch.
        # ------------------------------------------------------------------
        if not slot_free:
            self._f._log_debug("WindowManager: no free slot, keeping raw history")
            return sys_msgs + history, ""

        has_code = any("```" in m.get("content", "") for m in old_msgs)
        summary_text = await self._f._history_compressor.summarize_messages(
            old_msgs, is_code_context=has_code
        )

        if not summary_text or not summary_text.strip():
            self._f._log_debug(
                "WindowManager: summary failed (no-degradation guard), "
                "keeping raw history"
            )
            return sys_msgs + history, ""

        # ------------------------------------------------------------------
        # Persist summary and update metrics.
        # ------------------------------------------------------------------
        pending = await self._persist(
            summary_text=summary_text,
            old_msgs=old_msgs,
            turns=turns,
            history=history,
            state=state,
            project_id=project_id,
            slot_free=slot_free,
        )

        # ------------------------------------------------------------------
        # Return trimmed history.
        # ------------------------------------------------------------------
        return sys_msgs + kept, pending

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Calculation helpers (no side effects)
    # ═══════════════════════════════════════════════════════════════════════

    # ------------------------------------------------------------------
    # Region: Budget Calculation
    # ------------------------------------------------------------------

    def _effective_budget(self, project_id: str) -> int:
        """
        Token budget for history.

        Token-primary: history_max_tokens, bounded by the actual window.
        Always returns a value >= 0.

        Args:
            project_id: Current project identifier.

        Returns:
            Effective token budget for history.
        """
        v = self._f.valves
        psm = self._f._project_state_manager
        system_tokens = psm.get_last_system_tokens(project_id)

        budget = min(
            v.history_max_tokens,
            v.context_window_tokens - system_tokens - v.response_reserve_tokens,
        )
        result = max(0, budget)

        # ------------------------------------------------------------------
        # Log A: budget source breakdown.
        # ------------------------------------------------------------------
        self._f._log_debug(
            f"WindowManager: budget={result} tokens "
            f"(window={v.context_window_tokens}, "
            f"system_prev={system_tokens}, "
            f"reserve={v.response_reserve_tokens}, "
            f"max_history={v.history_max_tokens})"
        )

        return result

    def _token_count(self, text: str) -> int:
        """
        Count tokens with tokenizer if available, else 4 chars/token heuristic.
        """
        if self._f.tokenizer:
            return len(self._f.tokenizer.encode(text))
        return max(1, len(text) // 4)

    @staticmethod
    def _index_turns(history: List[dict]) -> Tuple[List[int], int]:
        """
        Assign a 1-based turn number to each message.
        Each user message increments the counter.
        Assistant/tool messages share the turn number of the preceding user.
        Returns (turns_per_message, total_turns).
        """
        turn = 0
        per_msg: List[int] = []
        for m in history:
            if m.get("role") == "user":
                turn += 1
            per_msg.append(max(turn, 1))
        return per_msg, turn

    def _compute_frontier(
        self,
        history: List[dict],
        turns: List[int],
        budget: int,
    ) -> Tuple[List[dict], List[dict], int]:
        """
        Find the earliest index in history such that all messages from that
        index onward fit within the token budget. Returns (kept, evicted, new_hwm).

        The frontier is always snapped forward to the next complete turn boundary.
        Without this snap, the backward token scan can split a turn pair, keeping
        an assistant reply without its preceding user message (or vice versa),
        producing a malformed conversation that the LLM cannot correctly attend to.

        new_hwm is the turn number of the last evicted message, used to advance
        summarized_turn_hwm. Returns 0 when nothing is evicted.

        Steps:
            1.  Backward scan: accumulate tokens newest-first until budget is
                exceeded; record the split index.
            2.  Turn-boundary snap: if the split index falls inside a turn,
                advance it past the end of that turn so the evicted set contains
                only complete turn pairs.
            3.  Safety floor: if snapping consumed every message, preserve the
                single most-recent complete turn regardless of budget.
            4.  Split history and compute new_hwm from the turn list.
        """
        if not history:
            return [], [], 0

        # -- Step 1: backward token scan --
        total_kept = 0
        frontier_idx = 0  # default: everything fits, nothing evicted

        for i in range(len(history) - 1, -1, -1):
            tok = self._token_count(history[i].get("content", ""))
            if total_kept + tok > budget:
                frontier_idx = i + 1
                break
            total_kept += tok

        if frontier_idx == 0:
            return history, [], 0

        # -- Step 2: snap forward to the next complete turn boundary --
        # If frontier_idx lands inside a turn, advance past the entire turn
        # so that the kept slice starts at a clean user-message boundary.
        if frontier_idx < len(history):
            current_turn = turns[frontier_idx]

            # Find where the turn at frontier_idx actually starts
            turn_start = frontier_idx
            while turn_start > 0 and turns[turn_start - 1] == current_turn:
                turn_start -= 1

            if turn_start != frontier_idx:
                # frontier_idx is mid-turn — advance past its end
                while (
                    frontier_idx < len(history) and turns[frontier_idx] == current_turn
                ):
                    frontier_idx += 1

        # -- Step 3: safety floor — always keep at least one complete turn --
        if frontier_idx >= len(history):
            last_turn_num = turns[-1] if turns else 0
            last_turn_start = len(history) - 1
            while last_turn_start > 0 and turns[last_turn_start - 1] == last_turn_num:
                last_turn_start -= 1
            frontier_idx = last_turn_start
            self._f._log_debug(
                "WindowManager._compute_frontier: snap consumed all history, "
                f"preserving last turn (turn {last_turn_num})"
            )

        # -- Step 4: split and compute HWM --
        kept = history[frontier_idx:]
        old_msgs = history[:frontier_idx]
        new_hwm = turns[frontier_idx - 1] if old_msgs else 0

        self._f._log_debug(
            f"WindowManager._compute_frontier: evicting {len(old_msgs)} msg(s), "
            f"keeping {len(kept)}, new_hwm={new_hwm}, "
            f"~{total_kept} tokens retained"
        )

        return kept, old_msgs, new_hwm

    def _apply_emergency_cap(
        self,
        history: List[dict],
        turns: List[int],
        kept: List[dict],
        old_msgs: List[dict],
        budget: int,
    ) -> Tuple[List[dict], List[dict]]:
        """
        Emergency cap: if any turn in `kept` exceeds budget * 0.8
        (giant turn — e.g. a 5000-line file), keep only the last
        emergency_max_turns turns and move the rest to old_msgs.

        Replaces adaptive_trim with max_turns=8, with a more conservative
        default (4) and configurable via valve.
        """
        if not kept:
            return kept, old_msgs

        emergency_threshold = budget * 0.8
        kept_turn_set = {t for m, t in zip(history, turns) if m in kept}

        giant_found = False
        for turn_num in kept_turn_set:
            turn_tokens = sum(
                self._token_count(m.get("content", ""))
                for m, t in zip(history, turns)
                if t == turn_num
            )
            if turn_tokens > emergency_threshold:
                giant_found = True
                break

        if not giant_found:
            return kept, old_msgs

        emergency_max = getattr(self._f.valves, "emergency_max_turns", 4)
        sorted_kept_turns = sorted(kept_turn_set)
        turns_to_keep = set(sorted_kept_turns[-emergency_max:])
        turns_to_evict = kept_turn_set - turns_to_keep

        new_kept = [m for m, t in zip(history, turns) if t in turns_to_keep]
        extra_old = [m for m, t in zip(history, turns) if t in turns_to_evict]

        self._f._log_debug(
            f"WindowManager: emergency cap — giant turn detected "
            f"(>{emergency_threshold:.0f} tokens). "
            f"Keeping last {emergency_max} turns."
        )
        return new_kept, old_msgs + extra_old

    @staticmethod
    def _summary_sort_key(s: dict) -> float:
        """Chronological order by covered band start."""
        ct = s.get("covers_turns")
        return float(ct[0]) if ct else float(s.get("created_at", 0))

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Persistence (side effects: state, LTM, consolidation)
    # ═══════════════════════════════════════════════════════════════════════

    # ------------------------------------------------------------------
    # Region: Summary Persistence
    # ------------------------------------------------------------------

    async def _persist(
        self,
        summary_text: str,
        old_msgs: List[dict],
        turns: List[int],
        history: List[dict],
        state: "ConversationState",
        project_id: str,
        slot_free: bool,
    ) -> str:
        """
        Persist the generated summary and update WindowManager metrics.

        Steps:
            1.  Derive the new high-water mark from the evicted turn numbers.
            2.  Build a summary entry with full metadata and append it to
                conversation_summaries.
            3.  Apply the L1 cap, keeping only the most recent
                max_conversation_summaries entries at level 1.
            4.  Advance summarized_turn_hwm.
            5.  Update all WindowManager instrumentation flags and token-freed counter.
            6.  Persist the summary to LTM.
            7.  Attempt L1→L2 consolidation when enough L1 summaries accumulate.
            8.  Emit the Phase 2 KV-freeze signal via _on_frontier_advance,
                passing project_id explicitly to avoid the singleton-valve bug.
            9.  Persist the updated ConversationState.
        """
        v = self._f.valves
        old_hwm = state.summarized_turn_hwm

        # -- Step 1: derive new high-water mark --
        old_turn_nums = [t for m, t in zip(history, turns) if m in old_msgs]
        new_hwm = max(old_turn_nums) if old_turn_nums else old_hwm

        # -- Step 2: build and append summary entry --
        summary_entry = {
            "text": summary_text,
            "created_at": time.time(),
            "covers_msgs": len(old_msgs),
            "covers_turns": [old_hwm + 1, new_hwm],
            "level": 1,
        }
        state.conversation_summaries.append(summary_entry)

        # -- Step 3: apply L1 cap --
        max_l1 = v.max_conversation_summaries
        if max_l1 > 0:
            l1 = [s for s in state.conversation_summaries if s.get("level", 1) == 1]
            if len(l1) > max_l1:
                keep_ids = {id(s) for s in l1[-max_l1:]}
                state.conversation_summaries = [
                    s
                    for s in state.conversation_summaries
                    if s.get("level", 1) != 1 or id(s) in keep_ids
                ]
            l1_after = [
                s for s in state.conversation_summaries if s.get("level", 1) == 1
            ]
            self._f._log_debug(
                f"WindowManager: L1 cap applied — {len(l1_after)}/{max_l1} "
                f"summaries retained"
            )

        # -- Step 4: advance HWM --
        state.summarized_turn_hwm = new_hwm

        # -- Step 5: update WindowManager metrics --
        state.wm_fired = True
        state.wm_summary_ok = True
        state.wm_msgs_evicted = len(old_msgs)
        state.wm_tokens_freed = sum(
            self._token_count(m.get("content", "")) for m in old_msgs
        )
        self._f._log_debug(
            f"WindowManager: summary stored — "
            f"{len(old_msgs)} msg(s) evicted, "
            f"~{state.wm_tokens_freed} tokens freed, "
            f"HWM {old_hwm}→{new_hwm}"
        )

        # -- Step 6: persist to LTM --
        await self._f._message_assembler._persist_turn_summary_to_ltm(
            summary_text, project_id, old_hwm + 1, new_hwm
        )

        # -- Step 7: L1→L2 consolidation --
        l1_count = sum(
            1 for s in state.conversation_summaries if s.get("level", 1) == 1
        )
        if (
            slot_free
            and v.enable_hierarchical_summaries
            and l1_count >= v.hierarchical_summary_group_size
        ):
            await self._f._message_assembler._consolidate_summaries(
                state, project_id, slot_free
            )

        # -- Step 8: Phase 2 KV-freeze --
        self._on_frontier_advance(old_hwm, new_hwm, project_id)

        # -- Step 9: persist state --
        self._f._conversation_state_manager.set(project_id, state)

        return f"[Summary of earlier conversation]\n{summary_text}"

    # ═══════════════════════════════════════════════════════════════════════
    # 4. Seams and static helpers
    # ═══════════════════════════════════════════════════════════════════════

    def _on_frontier_advance(
        self,
        old_hwm: int,
        new_hwm: int,
        project_id: str,
    ) -> None:
        """
        Phase 2 KV-freeze: save the KV slot immediately after history eviction.

        When WindowManager evicts turns and generates a summary, the pre-frontier
        history tokens disappear from context. Saving the slot at this point
        captures the KV state with the new stabilised prefix (Block A + summary)
        so the next request can restore from that checkpoint instead of
        re-prefilling from scratch.

        force=True bypasses the static-hash guard: the history changed but Block A
        did not, so the structure hash is unchanged and without force the slot would
        be silently skipped.

        Receives project_id explicitly. The original code read valves.project_id
        inside this method, which captures the wrong project when multiple projects
        are served concurrently.
        """
        if old_hwm >= new_hwm:
            return

        self._f._log_debug(
            f"Phase 2 KV-freeze: frontier advanced hwm {old_hwm}→{new_hwm} "
            f"for project '{project_id}', scheduling slot_save(force=True)"
        )
        asyncio.create_task(
            self._f._project_state_manager.slot_save(project_id, force=True)
        )

    @staticmethod
    def _is_autocontinue_active(messages: List[dict]) -> bool:
        """
        True if the last assistant message contains a multi-phase
        continuation marker.
        """
        _MARKERS = frozenset(
            {
                "▶ CONTINÚA:",
                "▶ CONTINÚA EN LA SIGUIENTE PARTE",
            }
        )
        last_assistant = next(
            (m for m in reversed(messages) if m.get("role") == "assistant"),
            None,
        )
        if not last_assistant:
            return False
        return any(marker in last_assistant.get("content", "") for marker in _MARKERS)


class MessageAssembler:
    """
    Final processing of the message list before it is sent to the LLM.

    Orchestrates, in order:
    * Chain‑of‑Thought detection and reasoning generation (Level 1‑3).
    * Code‑history compression and lean‑user‑code stubbing.
    * LLMLingua‑2 compression of conversation prose.
    * Turn‑based window management (summarise then evict old turns).
    * Multi‑phase protocol injection when the token budget is tight.
    * Adaptive trimming of old messages with optional summarisation.
    * Assembly of the final system prompt (Block A + Block B) and its
        injection as the first message.

    Docs 10–13 backported:
        M3 – enforce_scientific_method forces cot_any_used=True to guarantee generation.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the MessageAssembler with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._f = filter_ref
        self._last_cot_degraded: bool = False
        # WindowManager: unified history window policy (replaces M1, M3, M4)
        self._window_manager = WindowManager(filter_ref)

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Main orchestration
    # ═══════════════════════════════════════════════════════════════════════

    async def assemble(
        self,
        messages: List[dict],
        project_id: str,
        static_block: str,
        dynamic_injections: List[Tuple[str, str]],
        prelim_system: str,
        last_user_msg: Optional[dict],
        is_code_session: bool,
        state: ConversationState,
        __user__: Optional[dict],
        user_question: str,
        has_code_blocks: bool,
        slot_busy: bool = False,
        is_continuation: bool = False,
    ) -> List[dict]:
        """
        Orchestrate CoT, multi-phase, trimming, and final assembly.

        Args:
            messages: Current list of conversation messages.
            project_id: Project identifier.
            static_block: Rendered Block A (static, KV-cacheable).
            dynamic_injections: List of (priority, text) dynamic content.
            prelim_system: Preliminary system prompt (Block A + Block B).
            last_user_msg: Last user message, if any.
            is_code_session: Whether the session is code-aware.
            state: ConversationState for the project.
            __user__: User context from OpenWebUI.
            user_question: Extracted question from the user message.
            has_code_blocks: Whether the user message contained code fences.
            slot_busy: Whether the LLM slot is busy.
            is_continuation: True only for genuine AutoContinue.

        Returns:
            Final list of messages ready for the LLM.
        """
        self._f._log_debug(
            "Assembling final messages (CoT, trimming, system prompt injection)"
        )

        slot_free = not slot_busy

        # ------------------------------------------------------------------
        # Step 1: CoT detection and generation.
        # ------------------------------------------------------------------
        await self._detect_and_generate_cot(
            dynamic_injections,
            last_user_msg,
            is_code_session,
            state,
            user_question,
            prelim_system,
            project_id,
            is_continuation,
            slot_free,
            messages,
        )

        # ------------------------------------------------------------------
        # Step 2: Code history compression + lean user code.
        # ------------------------------------------------------------------
        messages = await self._compress_code_history_and_lean(
            messages, project_id, dynamic_injections
        )

        # ------------------------------------------------------------------
        # Step 3: History LLMLingua compression.
        # ------------------------------------------------------------------
        messages = await self._apply_history_llmlingua(
            messages, project_id, user_question
        )

        # ------------------------------------------------------------------
        # Step 4: WindowManager – unified history window policy.
        # ------------------------------------------------------------------
        messages, pending_summary = await self._window_manager.apply(
            messages, state, project_id, slot_free
        )

        # ------------------------------------------------------------------
        # Step 4b: Inject pending_summary if present (Bug 16).
        # ------------------------------------------------------------------
        if pending_summary:
            self._f._log_debug(
                f"WindowManager: injecting {len(pending_summary)} char summary "
                f"into message history"
            )
            # Inject the summary as a system message at the front of the history.
            # This ensures the model sees it before the current conversation.
            messages.insert(0, {"role": "system", "content": pending_summary})
        elif pending_summary is not None:
            self._f._log_debug("WindowManager: pending_summary empty, not injecting")

        # ------------------------------------------------------------------
        # Step 5: Multi-phase instructions injection.
        # ------------------------------------------------------------------
        await self._inject_multi_phase_instructions(
            dynamic_injections,
            prelim_system,
            messages,
            user_question,
            slot_free,
            is_continuation,
            project_id,
        )

        # ------------------------------------------------------------------
        # Step 6: Assemble final system message and inject.
        # ------------------------------------------------------------------
        messages = self._assemble_final_system_and_log(
            static_block, dynamic_injections, messages, project_id, ""
        )

        return messages

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Chain‑of‑Thought (CoT) detection and generation
    # ═══════════════════════════════════════════════════════════════════════

    async def _detect_and_generate_cot(
        self,
        dynamic_injections: List[Tuple[str, str]],
        last_user_msg: Optional[dict],
        is_code_session: bool,
        state: ConversationState,
        user_question: str,
        prelim_system: str,
        project_id: str,
        is_continuation: bool,
        slot_free: bool,
        messages: List[dict],
    ) -> None:
        """
        Detect CoT configuration and generate reasoning.
        Modifies `dynamic_injections` in-place.

        Detection cascade (Fase 3 + new):
        * STAGE 0 — SymbolGraph pre-scan: sync, free, before parallel gather.
          Computes structural specificity of the user query.
        * STAGE 1 — Heuristic: always runs, feeds stages 2 and 3.
        * STAGE 2 — CrossEncoder: 6 pairs (level + scientific/linear).
          Reinforced by stages 0 and 1.
        * STAGE 3 — LLM: receives full cascaded context. Falls back to
          stage 1 if unavailable.

        Generation routing:
        * use_scientific=True OR level==3 → generate_scientific_reasoning_L3
        * use_scientific=False AND level==2 → generate_cot_reasoning (linear)
        * Architecture path mirrors: sci/L3 → scientific_arch, else arch.

        QueryDecomposition (Fase 3):
          decompose_questions runs in Task 2 of the parallel gather.
          Upgrades CoT level if ≥2 independent questions detected.

        FocalReasoning (Fase 3):
          per-question volatile activation + CoT synthesis.
          Signal: enable_focal_reasoning + len(sub_questions)≥2 + level≥2
                  + not arch mode. Falls back to unified if produces nothing.
        """
        # ── REGION 1: DETECT COT LEVEL ──
        self._f._log_debug("🧠 ENRICHMENT – CoT Step 1/3: Detect CoT configuration")
        manual_cot_used = False
        cot_any_used = False
        cot_level = 2
        _use_scientific = False
        reasoning = None
        cot_question = ""
        user_content = last_user_msg.get("content", "") if last_user_msg else ""
        sub_questions: List[str] = [user_content]

        self._last_cot_degraded = False

        # ── enforce_scientific_method ─────────────────────────────────────
        if self._f.valves.enforce_scientific_method:
            self._f._log_debug(
                "CoT: enforce_scientific_method=True → forcing L3 scientific"
            )
            cot_level = 3
            _use_scientific = True
            cot_any_used = True

        # ── Manual /think command ─────────────────────────────────────────
        if self._f.valves.enable_cot_on_demand or self._f.valves.auto_cot_enabled:
            if (
                last_user_msg
                and self._f.valves.enable_cot_on_demand
                and user_content.strip().startswith("/think")
            ):
                cot_question, level = await self._f._reasoning.parse_cot_intent(
                    user_content
                )
                if cot_question:
                    manual_cot_used = True
                    cot_any_used = True
                    cot_level = level
                    if level == 1:
                        dynamic_injections.append(
                            (
                                "high",
                                "Please think step by step before answering. "
                                "Show your reasoning, then provide the final answer.",
                            )
                        )

        # ── STAGE 0: SymbolGraph pre-scan ─────────────────────────────────
        # Synchronous, zero LLM cost. Computed before the parallel gather
        # so it's available as reinforcement in Task 1.
        _signal_vector: Dict[str, int] = {
            "n_mentioned": 0,
            "n_found": 0,
            "n_relations": 0,
            "structural_hits": 0,
        }
        if (
            is_code_session
            and self._f.valves.enable_symbol_graph_cot_signal
            and project_id
            and not is_continuation
            and not self._f.valves.enforce_scientific_method
            and user_content
        ):
            _signal_vector = self._f._meta_reasoning._compute_signal_vector(
                user_content,
                project_id,
                min_symbol_length=self._f.valves.auto_scientific_min_symbol_length,
            )
            if _signal_vector["n_found"] > 0:
                self._f._log_debug(
                    f"SymbolGraph pre-scan: {_signal_vector['n_found']} symbols "
                    f"found, {_signal_vector['structural_hits']} total hits"
                )

        # ── Parallel gather (slot_free, auto-detect path) ─────────────────
        if (
            slot_free
            and not manual_cot_used
            and not self._f.valves.enforce_scientific_method
            and not is_continuation
        ):
            parallel_tasks = []
            _available_mp_pre = self._f.valves.context_window_tokens
            if (
                self._f.valves.enable_multi_phase_response
                and self._f.tokenizer
                and prelim_system
            ):
                _prelim_tok = len(self._f.tokenizer.encode(prelim_system))
                _hist_tok = self._f._tokens.estimate_tokens(
                    [m for m in messages if m.get("role") != "system"]
                )
                _available_mp_pre = max(
                    0,
                    self._f.valves.context_window_tokens - _prelim_tok - _hist_tok,
                )
            _skip_intent_llm = (
                self._f.valves.enable_multi_phase_response
                and _available_mp_pre < self._f.valves.multi_phase_response_threshold
            )

            # Task 0: should_keep_full_code
            if not _skip_intent_llm:
                parallel_tasks.append(
                    self._f._llm_orchestrator.should_keep_full_code(
                        user_question, project_id
                    )
                )
            else:
                parallel_tasks.append(asyncio.sleep(0, result=True))

            # Task 1: detect_cot_configuration (replaces detect_cot_level)
            # Passes signal_vector from Stage 0 so it feeds CE reinforcement.
            if self._f.valves.enable_cot_on_demand or self._f.valves.auto_cot_enabled:
                cot_detection_content = (
                    user_question
                    if (user_question and len(user_question) >= 10)
                    else user_content
                )
                parallel_tasks.append(
                    self._f._reasoning.detect_cot_configuration(
                        cot_detection_content,
                        is_code_session,
                        state,
                        signal_vector=_signal_vector,
                        is_continuation=is_continuation,
                        project_id=project_id,
                    )
                )
            else:
                parallel_tasks.append(
                    asyncio.sleep(
                        0,
                        result={
                            "level": 0,
                            "use_scientific": False,
                            "decompose": False,
                            "source": "disabled",
                        },
                    )
                )

            # Task 2: decompose_questions (QueryDecomposition)
            if (
                not _skip_intent_llm
                and (
                    self._f.valves.enable_cot_on_demand
                    or self._f.valves.auto_cot_enabled
                )
                and self._f.valves.enable_query_decomposition
            ):
                parallel_tasks.append(
                    self._f._meta_reasoning.decompose_questions(
                        user_content, project_id
                    )
                )
            else:
                parallel_tasks.append(asyncio.sleep(0, result=[user_content]))

            results = await asyncio.gather(*parallel_tasks)

            # Extract Task 0
            self._f._user_intent_full_code = (
                results[0] if not _skip_intent_llm else True
            )

            # Extract Task 1 — CoTConfig
            cot_config = results[1]
            if isinstance(cot_config, dict):
                detected_level = cot_config.get("level", 0)
                _use_scientific = cot_config.get("use_scientific", False)
                _decompose_hint = cot_config.get("decompose", False)
                _cot_source = cot_config.get("source", "?")
                _cot_rationale = cot_config.get("rationale", "")
            else:
                # Backward-compat fallback if result is an int
                detected_level = int(cot_config) if cot_config else 0
                _use_scientific = False
                _decompose_hint = False
                _cot_source = "compat"
                _cot_rationale = ""

            if detected_level > 0:
                cot_any_used = True
                cot_level = detected_level
                self._f._log_debug(
                    f"🧠 CoT config detected: level={cot_level}, "
                    f"scientific={_use_scientific}, "
                    f"source={_cot_source}, "
                    f"rationale='{_cot_rationale}'"
                )

            # Extract Task 2 — QueryDecomposition
            sub_questions = results[2] if len(results) > 2 else [user_content]

            # Upgrade CoT level if multiple independent questions detected.
            # Gradual: L1→L2, L2→L3.
            if (
                cot_any_used
                and not manual_cot_used
                and self._f.valves.enable_query_decomposition
                and len(sub_questions) >= 2
                and cot_level < 3
            ):
                old_level = cot_level
                cot_level = min(cot_level + 1, 3)
                self._f._log_debug(
                    f"🧠 QueryDecomposition: {len(sub_questions)} independent "
                    f"questions → upgrading CoT L{old_level}→L{cot_level}"
                )
                await self._f._emit_status(
                    f"🧠 {len(sub_questions)} independent questions — "
                    f"upgrading reasoning depth L{old_level}→L{cot_level}"
                )

        else:
            # Serial path (continuation, manual CoT already set, etc.)
            self._f._user_intent_full_code = True
            if (
                not manual_cot_used
                and slot_free
                and not self._f.valves.enforce_scientific_method
                and not is_continuation
            ):
                cot_detection_content = (
                    user_question
                    if (user_question and len(user_question) >= 10)
                    else user_content
                )
                cot_config = await self._f._reasoning.detect_cot_configuration(
                    cot_detection_content,
                    is_code_session,
                    state,
                    signal_vector=_signal_vector,
                    is_continuation=is_continuation,
                    project_id=project_id,
                )
                detected_level = cot_config.get("level", 0)
                _use_scientific = cot_config.get("use_scientific", False)
                if detected_level > 0:
                    cot_any_used = True
                    cot_level = detected_level
                    self._f._log_debug(
                        f"🧠 CoT config (serial): level={cot_level}, "
                        f"scientific={_use_scientific}"
                    )

        if not cot_any_used:
            self._f._log_debug("🧠 ENRICHMENT – CoT Step 1/3: No CoT needed")
            return
        if not slot_free:
            self._f._log_debug(
                "🧠 ENRICHMENT – CoT Step 1/3: CoT detection skipped (no free slot)"
            )
            return

        # ── Multi-phase pre-check ─────────────────────────────────────────
        _mp_cot_degraded = False
        _available_mp_pre = self._f.valves.context_window_tokens
        if (
            self._f.valves.enable_multi_phase_response
            and self._f.tokenizer
            and prelim_system
        ):
            _prelim_tok = len(self._f.tokenizer.encode(prelim_system))
            _hist_tok = self._f._tokens.estimate_tokens(
                [m for m in messages if m.get("role") != "system"]
            )
            _available_mp_pre = max(
                0,
                self._f.valves.context_window_tokens - _prelim_tok - _hist_tok,
            )
        if (
            self._f.valves.enable_multi_phase_response
            and _available_mp_pre < self._f.valves.multi_phase_response_threshold
            and cot_any_used
            and cot_level >= 2
            and slot_free
        ):
            self._f._log_debug(
                f"🧠 Multi-phase pre-check: {_available_mp_pre} tokens "
                f"< threshold {self._f.valves.multi_phase_response_threshold}. "
                f"Degrading CoT L{cot_level}→1."
            )
            cot_level = 1
            _use_scientific = False
            _mp_cot_degraded = True

        self._last_cot_degraded = _mp_cot_degraded

        # ── REGION 2: GENERATE REASONING ──
        self._f._log_debug("🧠 ENRICHMENT – CoT Step 2/3: Generate reasoning")

        # Level 1 — terminal lightweight path
        if cot_level == 1:
            if not manual_cot_used and not _mp_cot_degraded:
                dynamic_injections.append(
                    (
                        "high",
                        "Please think step by step before answering. "
                        "Show your reasoning, then provide the final answer.",
                    )
                )
            self._f._log_debug(
                "🧠 ENRICHMENT – CoT Step 2/3: level 1 — inline prompt, no chain"
            )
            return

        # From here: levels 2 and 3 only
        _model_ctx = self._f.valves.active_context_max_tokens or 28000
        _cot_context_limit = _model_ctx // 3

        # Architecture-mode: replace full system prompt with skeleton
        _is_arch = (
            self._f.valves.enable_skeleton_cot
            and self._f._reasoning.is_architecture_query(user_question)
        )
        _skeleton_ctx = ""
        if _is_arch:
            self._f._log_debug(
                "🏗️ Architecture intent detected — fetching skeleton for CoT prior"
            )
            try:
                _skeleton_ctx = await self._f._ctx_builder._get_skeleton_for_cot(
                    project_id, user_question
                )
            except Exception as _ske:
                self._f._log_debug(f"Skeleton for CoT failed: {_ske}")
            if _skeleton_ctx:
                prelim_for_cot = _skeleton_ctx
                self._f._log_debug(
                    f"🏗️ CoT context = skeleton "
                    f"(~{self._f._tokens.estimate_code_tokens(_skeleton_ctx)} tokens)"
                )
            else:
                _is_arch = False
                self._f._log_debug(
                    "🏗️ No skeleton available — falling back to standard CoT"
                )

        if not _is_arch:
            if self._f.tokenizer:
                _prelim_tokens = len(self._f.tokenizer.encode(prelim_system))
                prelim_for_cot = (
                    self._f._tokens.truncate_text_to_tokens(
                        prelim_system, _cot_context_limit
                    )
                    if _prelim_tokens > _cot_context_limit
                    else prelim_system
                )
            else:
                prelim_for_cot = prelim_system[: _cot_context_limit * 4]

        # ── Generation routing ────────────────────────────────────────────
        # use_scientific=True OR level==3 → compete_hypotheses (scientific)
        # use_scientific=False AND level==2 → linear step-by-step CoT
        # Architecture path mirrors this.
        _go_scientific = _use_scientific or cot_level >= 3

        if _go_scientific and _use_scientific and cot_level < 3:
            self._f._log_debug(
                f"use_scientific=True with cot_level={cot_level}: "
                f"routing to scientific generation (L3 compete_hypotheses)"
            )

        # ── FocalReasoning path ───────────────────────────────────────────
        reasoning = None
        if (
            self._f.valves.enable_focal_reasoning
            and not _is_arch
            and len(sub_questions) >= 2
            and cot_level >= 2
        ):
            self._f._log_debug(
                f"🧠 FocalReasoning: {len(sub_questions)} questions, "
                f"level={cot_level}, scientific={_go_scientific}"
            )
            per_q = await self._f._meta_reasoning.reason_per_focus(
                sub_questions, project_id, cot_level, prelim_for_cot
            )
            if per_q:
                reasoning = self._f._meta_reasoning.synthesize_focal_reasoning(per_q)
                self._f._log_debug(
                    f"🧠 FocalReasoning: synthesized {len(per_q)}/"
                    f"{len(sub_questions)} questions ({len(reasoning)} chars)"
                )
            else:
                self._f._log_debug(
                    "🧠 FocalReasoning: no results — falling back to unified"
                )

        # ── Unified generation ────────────────────────────────────────────
        if not reasoning:
            question = cot_question if manual_cot_used else user_question

            if _is_arch:
                if _go_scientific and self._f.valves.enable_scientific_arch_reasoning:
                    await self._f._emit_status(
                        "🔬🏗️ Scientific architecture reasoning..."
                    )
                    reasoning = await self._f._reasoning.generate_scientific_architecture_reasoning(
                        question,
                        prelim_for_cot,
                        project_id,
                        label="sci_arch_cot",
                    )
                else:
                    reasoning = (
                        await self._f._reasoning.generate_architecture_reasoning(
                            question, prelim_for_cot, project_id, label="arch_cot"
                        )
                    )
            elif _go_scientific:
                await self._f._emit_status(
                    "🔬 Scientific reasoning — evaluating hypotheses..."
                )
                reasoning = await self._f._reasoning.generate_scientific_reasoning_L3(
                    question,
                    prelim_for_cot,
                    project_id,
                    label="scientific_cot",
                )
            else:
                # cot_level == 2, use_scientific == False → linear step-by-step
                reasoning = await self._f._reasoning.generate_cot_reasoning(
                    question, prelim_for_cot
                )

        # ── L3 scientific fallback → linear L2 ───────────────────────────
        _cot_error_msg = "Unable to generate reasoning."
        if (
            not manual_cot_used
            and _go_scientific
            and (reasoning is None or reasoning == _cot_error_msg)
        ):
            self._f._log_debug(
                "🧠 Scientific reasoning failed — falling back to linear L2"
            )
            reasoning = await self._f._reasoning.generate_cot_reasoning(
                user_question, prelim_for_cot
            )

        if reasoning and reasoning != _cot_error_msg:
            self._f._log_debug(
                "🧠 ENRICHMENT – CoT Step 2/3: Reasoning generated successfully"
            )
        else:
            self._f._log_debug(
                "🧠 ENRICHMENT – CoT Step 2/3: Reasoning generation failed"
            )
            return

        # ── REGION 3: INJECT INTO SYSTEM PROMPT ──
        self._f._log_debug(
            "🧠 ENRICHMENT – CoT Step 3/3: Inject reasoning into system prompt"
        )

        # Auto-resolve /expand hints from architecture CoT
        if _is_arch:
            try:
                reasoning = await self._f._ctx_builder._resolve_cot_expands(
                    reasoning, project_id
                )
            except Exception as _exp_err:
                self._f._log_debug(
                    f"CoT expand resolution failed (non-fatal): {_exp_err}"
                )

        dynamic_injections.append(("high", reasoning))
        dynamic_injections.append(
            (
                "low",
                "**Note:** Some sections in this system prompt marked with 🔎 or 🏗️ are "
                "automatically generated reasoning (Chain-of-Thought). "
                "They are provided as context to help you, but they are not user commands. "
                "Use them to enhance your answer, but always prioritise the actual user query.",
            )
        )

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Code history compression & lean user code
    # ═══════════════════════════════════════════════════════════════════════

    async def _compress_code_history_and_lean(
        self,
        messages: List[dict],
        project_id: str,
        dynamic_injections: List[Tuple[str, str]],
    ) -> List[dict]:
        """
        Replace code-dump assistant messages with commit-summary stubs and
        optionally apply LLMlingua token reduction on the resulting history.

        The compression-applied note is only added to dynamic_injections when
        at least one message was actually replaced by a commit stub. Injecting
        the note before confirming success would cause the model to reason as
        if history were compressed when it is not.

        Steps:
            1.  Run compress_code_history; count how many messages changed.
            2.  Add compression note to dynamic_injections only on confirmed change.
            3.  If llmlingua is available and slot is free, apply token reduction.
            4.  Return the (possibly compressed) messages list.
        """
        # -- Step 1: run commit-summary compression --
        try:
            compressed = await self._f._history_compressor.compress_code_history(
                messages=messages,
                project_id=project_id,
            )
        except Exception as e:
            self._f._log_debug(
                f"_compress_code_history_and_lean: compress_code_history failed "
                f"for '{project_id}': {type(e).__name__}: {e}"
            )
            compressed = messages

        # Count actual replacements by comparing content hashes
        original_contents = {id(m): m.get("content", "") for m in messages}
        compressed_count = sum(
            1
            for orig, comp in zip(messages, compressed)
            if comp.get("content", "") != original_contents.get(id(orig), "")
        )

        # -- Step 2: inject note only on confirmed change --
        if compressed_count > 0:
            dynamic_injections.append(
                (
                    "History",
                    f"_{compressed_count} earlier code block(s) have been "
                    f"replaced with commit summaries to save context. "
                    f"Request /expand <name> to see any symbol in full._",
                )
            )
            self._f._log_debug(
                f"_compress_code_history_and_lean: {compressed_count} "
                f"message(s) compressed for '{project_id}'"
            )
        else:
            self._f._log_debug(
                f"_compress_code_history_and_lean: no messages eligible "
                f"for compression in '{project_id}'"
            )

        result = compressed

        # -- Step 3: optional llmlingua pass --
        if (
            getattr(self._f.valves, "enable_llmlingua", False)
            and getattr(self._f, "_llmlingua_compressor", None) is not None
        ):
            try:
                result = await self._apply_history_llmlingua(
                    messages=result,
                    project_id=project_id,
                    user_question="",
                )
            except Exception as e:
                self._f._log_debug(
                    f"_compress_code_history_and_lean: llmlingua failed "
                    f"for '{project_id}': {type(e).__name__}: {e} — using commit-compressed"
                )

        # -- Step 4: return --
        return result

    async def _apply_history_llmlingua(
        self,
        messages: List[dict],
        project_id: str,
        user_question: str,
    ) -> List[dict]:
        """
        Apply LLMLingua-2 compression to conversation history, with hard cap.

        MIGRATED (step 12): Now gated by `enable_secondary_compaction`. When
        enabled, it only compresses messages that were NOT already compressed
        by the primary compactor (looks for markers like `[🗜️ PARTE` or
        `## Código — Parte`). This prevents double-compression in cascade.
        """
        # --- 1. Gate: secondary compaction is off by default ---
        if not self._f.valves.enable_secondary_compaction:
            self._f._log_debug(
                "Secondary compaction disabled (enable_secondary_compaction=False)."
            )
            return messages

        # --- 2. Check prerequisites ---
        if not (
            self._f.valves.enable_history_llmlingua
            and self._f._conv_compressor is not None
        ):
            return messages

        # --- 3. Filter out messages already compressed by the primary compactor ---
        _PRIMARY_COMPACTED_MARKERS = (
            "[🗜️ PARTE",
            "## Código — Parte",
            "## Código - Parte",
        )

        def _is_primary_compacted(content: str) -> bool:
            return any(marker in content for marker in _PRIMARY_COMPACTED_MARKERS)

        to_compress = []
        for msg in messages:
            role = msg.get("role", "")
            content = msg.get("content", "")
            if role in ("user", "assistant") and content:
                if not _is_primary_compacted(content):
                    to_compress.append(msg)

        if not to_compress:
            self._f._log_debug(
                "Secondary compaction: no eligible messages (all already primary-compacted)."
            )
            return messages

        compressed = await self._f._conv_compressor.compress_messages(
            messages=to_compress,
            project_id=project_id,
            symbol_index=self._f._symbol_index,
            current_msg_idx=len(messages) - 1,
            recent_lookback=self._f.valves.history_compress_recent_lookback,
            old_rate=self._f.valves.history_compress_old_rate,
            recent_rate=self._f.valves.history_compress_recent_rate,
            indexed_rate=self._f.valves.history_compress_indexed_rate,
            query=user_question,
        )

        comp_iter = iter(compressed)
        out = []
        for msg in messages:
            role = msg.get("role", "")
            content = msg.get("content", "")
            if (
                role in ("user", "assistant")
                and content
                and not _is_primary_compacted(content)
            ):
                out.append(next(comp_iter))
            else:
                out.append(msg)

        self._f._log_debug(
            f"Secondary compaction: compressed {len(to_compress)} message(s) "
            f"(skipped {len(messages) - len(to_compress)} already primary-compacted)."
        )

        return out

    # ═══════════════════════════════════════════════════════════════════════
    # 4. Turn‑based window management helpers (unchanged)
    # ═══════════════════════════════════════════════════════════════════════

    async def _persist_turn_summary_to_ltm(
        self, summary: str, project_id: str, turn_start: int, turn_end: int
    ) -> None:
        """Store a turn‑range summary in LTM."""
        if not (HAS_SENTENCE and HAS_CHROMA and self._f.memory_collection is not None):
            return
        try:
            text = f"[Conversation summary, turns {turn_start}-{turn_end}]\n{summary}"
            embedding = await anyio.to_thread.run_sync(
                lambda: self._f.embedder.encode(text).tolist()
            )
            msg_id = (
                f"{project_id}_turnsummary_{turn_start}_{turn_end}_{int(time.time())}"
            )
            await anyio.to_thread.run_sync(
                lambda: self._f.memory_collection.upsert(
                    ids=[msg_id],
                    embeddings=[embedding],
                    documents=[text],
                    metadatas=[
                        {
                            "role": "assistant",
                            "project_id": project_id,
                            "timestamp": time.time(),
                            "is_session_summary": True,
                            "is_turn_summary": True,
                            "covers_turn_start": turn_start,
                            "covers_turn_end": turn_end,
                            "content_type": ContentType.GENERAL.value,
                            "has_code": False,
                        }
                    ],
                )
            )
        except Exception as e:
            self._f._log_debug(f"Turn summary LTM persist failed: {e}")

    async def _merge_summaries(self, group_summaries: List[dict]) -> Optional[dict]:
        """Fuse several L1 turn-range summaries into one L2 summary via the LLM."""
        texts: List[str] = []
        starts: List[int] = []
        ends: List[int] = []
        total_msgs = 0
        for s in group_summaries:
            t = s.get("text", "")
            if t:
                texts.append(t)
            ct = s.get("covers_turns")
            if ct:
                starts.append(ct[0])
                ends.append(ct[1])
            total_msgs += s.get("covers_msgs", 0)
        combined = "\n\n".join(f"- {t}" for t in texts)
        if not combined.strip():
            return None
        prompt = (
            "Consolidate these conversation summaries into ONE higher-level "
            "summary (3-5 sentences). Preserve key decisions, files modified, and "
            "architectural changes; drop redundancy and chit-chat.\n\n"
            f"{combined[:4000]}"
        )
        merged = await self._f._llm_orchestrator.call_llm(
            prompt=prompt,
            system_prompt=(
                "You produce concise hierarchical summaries of technical "
                "conversations. Output only the summary."
            ),
            model_override=self._f.valves.summarization_model,
            max_tokens=self._f.valves.hierarchical_summary_max_tokens,
            temperature=0.2,
            label="hierarchical_summary",
            enable_thinking=False,
        )
        if not merged or not merged.strip():
            return None
        return {
            "text": merged.strip(),
            "created_at": time.time(),
            "covers_msgs": total_msgs,
            "covers_turns": [min(starts) if starts else 0, max(ends) if ends else 0],
            "level": 2,
        }

    async def _consolidate_summaries(
        self,
        state: "ConversationState",
        project_id: str,
        slot_free: bool,
    ) -> None:
        """
        Merge accumulated L1 summaries into L2 (hierarchical compression).

        Called from _persist after WindowManager evicts a batch of messages,
        when the number of L1 summaries reaches hierarchical_summary_group_size.

        Atomic replacement guarantee: a batch of L1 summaries is removed from
        conversation_summaries only when _merge_summaries returns a non-None
        merged L2 entry. If the LLM call fails, the L1 summaries are preserved
        unchanged so no conversation context is silently lost.

        Only one batch is consolidated per call. Repeated calls (one per
        WindowManager eviction) drain the L1 queue incrementally.

        Steps:
            1.  Collect all L1 summaries; exit when below group_size threshold.
            2.  Select the oldest batch up to group_size.
            3.  Attempt merge; return immediately on failure without modifying state.
            4.  Atomic swap: remove batch entries, append merged L2 entry.
            5.  Mark state dirty and log.
        """
        v = self._f.valves
        group_size = v.hierarchical_summary_group_size

        # -- Step 1: collect L1 summaries --
        l1_entries = [s for s in state.conversation_summaries if s.get("level", 1) == 1]
        if len(l1_entries) < group_size:
            return

        # -- Step 2: select oldest batch --
        batch = sorted(
            l1_entries,
            key=lambda s: s.get("covers_turns", [0, 0])[0],
        )[:group_size]

        self._f._log_debug(
            f"_consolidate_summaries: merging {len(batch)} L1 → L2 "
            f"for '{project_id}'"
        )

        # -- Step 3: attempt merge -- CRITICAL: do not touch state on failure --
        try:
            merged = await self._merge_summaries(batch)
        except Exception as e:
            self._f._log_debug(
                f"_consolidate_summaries: _merge_summaries raised for "
                f"'{project_id}': {type(e).__name__}: {e} — L1 entries preserved"
            )
            return

        if merged is None:
            self._f._log_debug(
                f"_consolidate_summaries: _merge_summaries returned None for "
                f"'{project_id}' — L1 entries preserved, will retry next eviction"
            )
            return

        # -- Step 4: atomic swap --
        batch_ids = {id(s) for s in batch}
        state.conversation_summaries = [
            s for s in state.conversation_summaries if id(s) not in batch_ids
        ]
        state.conversation_summaries.append(merged)

        # -- Step 5: mark dirty and log --
        self._f._conversation_state_manager.mark_dirty(project_id)
        self._f._log_debug(
            f"_consolidate_summaries: L1→L2 merge OK for '{project_id}' "
            f"(removed {len(batch)} L1, added 1 L2, "
            f"total={len(state.conversation_summaries)} summaries remaining)"
        )

    # ═══════════════════════════════════════════════════════════════════════
    # 5. Multi‑phase instructions injection (MIGRADO)
    # ═══════════════════════════════════════════════════════════════════════

    async def _inject_multi_phase_instructions(
        self,
        dynamic_injections: List[Tuple[str, str]],
        prelim_system: str,
        messages: List[dict],
        user_question: str,
        slot_free: bool,
        is_continuation: bool,
        project_id: str,
    ) -> None:
        """
        Inject multi‑phase protocol if the token budget is tight or a global‑scope
        query demands it.
        """
        if not (
            self._f.valves.enable_multi_phase_response
            and self._f.tokenizer
            and prelim_system
        ):
            return

        _prelim_tok: int = len(self._f.tokenizer.encode(prelim_system))
        _hist_tok: int = self._f._tokens.estimate_tokens(
            [m for m in messages if m.get("role") != "system"]
        )
        _mp_available: int = max(
            0, self._f.valves.context_window_tokens - _prelim_tok - _hist_tok
        )

        # --- Critical budget warning: append a wrap-up hint to the user message ---
        if _mp_available < self._f.valves.multi_phase_response_budget_warn:
            self._f._log_debug(
                f"Multi-phase CRITICAL ({_mp_available} tokens): "
                "wrap-up hint appended to user message (0 system tokens used)."
            )
            self._f._multi_phase.append_critical_wrap_up_hint(messages)
            return

        # --- Always evaluate the budget branch; force is an additive override ---
        budget_tight = _mp_available < self._f.valves.multi_phase_response_threshold

        # ── read the one‑shot global‑scope flag (MIGRADO) ──
        psm = self._f._project_state_manager
        force_global_scope = psm.pop_force_multi_phase_this_turn(project_id)

        use_multi_phase = (
            self._f.valves.force_multi_phase_response
            or budget_tight
            or force_global_scope
        )
        if force_global_scope and not budget_tight:
            self._f._log_debug(
                "Multi‑phase: activated by global‑scope query (full_graph active this turn)."
            )

        if use_multi_phase:
            _INSTRUCTION_OVERHEAD = 450
            _mp_budget_reported = max(500, _mp_available - _INSTRUCTION_OVERHEAD)
            _mp_instructions = self._f._multi_phase.build_multi_phase_instructions(
                available_tokens=_mp_budget_reported,
                user_query=user_question,
                cot_degraded_to_l1=self._last_cot_degraded,
                is_continuation=is_continuation,
            )
            dynamic_injections.append(("critical", _mp_instructions))
            self._f._log_debug(
                f"Multi-phase injected (priority=critical): "
                f"{_mp_available} available, reporting {_mp_budget_reported} to model "
                f"(overhead={_INSTRUCTION_OVERHEAD}). "
                f"force={self._f.valves.force_multi_phase_response}, budget_tight={budget_tight}"
            )
        else:
            self._f._log_debug(
                f"Multi-phase: not needed ({_mp_available} tokens > threshold "
                f"{self._f.valves.multi_phase_response_threshold} and force=False)."
            )

    # ═══════════════════════════════════════════════════════════════════════
    # 6. Final system assembly & logging (MIGRADO)
    # ═══════════════════════════════════════════════════════════════════════

    def _assemble_final_system_and_log(
        self,
        static_block: str,
        dynamic_injections: List[Tuple[str, str]],
        messages: List[dict],
        project_id: str,
        pending_summary: str,
    ) -> List[dict]:
        """
        Assemble final system prompt, inject it, and log token breakdown.
        """
        budget = self._f.valves.global_injection_token_budget
        priority_order = {"critical": 0, "high": 1, "medium": 2, "low": 3}

        psm = self._f._project_state_manager
        pstate = psm.get_pstate(project_id)

        if budget > 0 and self._f.tokenizer:
            dynamic_injections.sort(key=lambda x: priority_order.get(x[0], 99))
            selected_dynamic: List[str] = []
            used_dyn = 0
            static_tokens = (
                len(self._f.tokenizer.encode(static_block)) if static_block else 0
            )
            user_prompt_tokens = (
                len(
                    self._f.tokenizer.encode(
                        getattr(self._f, "_original_system_prompt", "") or ""
                    )
                )
                if getattr(self._f, "_original_system_prompt", "")
                else 0
            )
            dyn_budget = max(0, budget - static_tokens - user_prompt_tokens)

            for prio, text in dynamic_injections:
                if not text:
                    continue
                tok = len(self._f.tokenizer.encode(text))
                if used_dyn + tok <= dyn_budget:
                    selected_dynamic.append(text)
                    used_dyn += tok
                elif prio in ("critical", "high"):
                    avail = dyn_budget - used_dyn
                    if avail > 20:
                        selected_dynamic.append(text[: avail * 4] + "\n[truncated]")
                        break
            dynamic_block = "\n\n".join(selected_dynamic)
        else:
            dynamic_block = "\n\n".join(t for _, t in dynamic_injections if t)

        separator = "\n\n---\n\n" if static_block and dynamic_block else ""

        codeaware_block = static_block + separator + dynamic_block
        base_content = getattr(self._f, "_original_system_prompt", "") or ""

        final_system_parts = []
        if codeaware_block.strip():
            final_system_parts.append(codeaware_block)
        final_system = "\n\n---\n\n".join(final_system_parts)

        if base_content.strip():
            if final_system.strip():
                final_system = (
                    final_system
                    + "\n\n---\n\n## User instructions\n"
                    + base_content.strip()
                )
            else:
                final_system = "## User instructions\n" + base_content.strip()

        if pending_summary:
            final_system = final_system + "\n\n" + pending_summary

        if final_system.strip():
            messages = [m for m in messages if m.get("role") != "system"]
            messages.insert(0, {"role": "system", "content": final_system})

        # Ensure last message is from user
        if messages and messages[-1].get("role") != "user":
            last_user_idx = -1
            for i in range(len(messages) - 1, -1, -1):
                if messages[i].get("role") == "user":
                    last_user_idx = i
                    break
            if last_user_idx != -1:
                messages = messages[: last_user_idx + 1]
            else:
                messages.append({"role": "user", "content": "continue"})

        # ── Token breakdown log ─────────────────────────────────────────
        if self._f.valves.debug and self._f.tokenizer and final_system.strip():
            static_tok = (
                len(self._f.tokenizer.encode(static_block)) if static_block else 0
            )
            dynamic_tok = (
                len(self._f.tokenizer.encode(dynamic_block)) if dynamic_block else 0
            )
            base_tok = (
                len(
                    self._f.tokenizer.encode(
                        getattr(self._f, "_original_system_prompt", "") or ""
                    )
                )
                if getattr(self._f, "_original_system_prompt", "")
                else 0
            )
            total_system_tok = len(self._f.tokenizer.encode(final_system))

            # ── MIGRADO: usar set_last_system_tokens en lugar de pstate ──
            psm.set_last_system_tokens(project_id, total_system_tok)

            prefix_hash = pstate.get("last_static_prefix_hash", "N/A")
            self._f._log_debug("─" * 60)
            self._f._log_debug("TOKEN BREAKDOWN — system prompt")
            self._f._log_debug(f"  BLOCK A (static, cacheable):  ~{static_tok} tokens")
            self._f._log_debug(f"  BLOCK B (dynamic, per-query): ~{dynamic_tok} tokens")
            self._f._log_debug(
                f"  User instructions (tail):      ~{base_tok} tokens (LAST)"
            )
            self._f._log_debug(
                f"  TOTAL system tokens:          ~{total_system_tok} tokens"
            )
            self._f._log_debug(f"  Prefix hash (Block A):        {prefix_hash}")
            self._f._log_debug(
                f"  → If hash matches previous:   KV cache HIT in llama.cpp"
            )
            self._f._log_debug(
                f"  → If hash changed:            KV cache MISS, full prefill"
            )
            if self._f.valves.enable_multi_phase_response:
                self._f._log_debug("  Multi-phase:                  (see earlier log)")
            if (
                self._f.valves.enable_code_history_compression
                or self._f.valves.enable_lean_user_code
            ):
                _compressed_parts = sum(
                    1
                    for m in messages
                    if m.get("role") == "assistant"
                    and re.search(r"\[🗜️ PARTE \d+/\d+", m.get("content", ""))
                )
                _leaned_msgs = sum(
                    1
                    for m in messages
                    if m.get("role") == "user"
                    and "[CÓDIGO COMPRIMIDO" in m.get("content", "")
                )
                self._f._log_debug(
                    f"  Code history:                 "
                    f"{_compressed_parts} part(s) compressed, "
                    f"{_leaned_msgs} user msg(s) leaned"
                )
            self._f._log_debug("─" * 60)

        # ── Context dump (evolution tracking) ─────────────────────────
        if self._f.valves.enable_context_dump:
            try:
                self._f._context_dumper.schedule_inlet_snapshot(
                    project_id=project_id,
                    static_block=static_block,
                    dynamic_block=dynamic_block,
                    final_system=final_system,
                    messages=messages,
                )
            except Exception as _dump_err:
                self._f._log_debug(f"Context dump scheduling failed: {_dump_err}")

        return messages


class ContextAssembler:
    """
    Single point of coordination for the full context construction pipeline.

    Owns the two-phase context assembly sequence:
      1. Calls SystemPromptBuilder.build() to produce Block A, Block B
         injections, and the preliminary system prompt.
      2. Calls MessageAssembler.assemble() to apply CoT, compression,
         multi-phase instructions, and window management, then injects the
         final system prompt into the message list.

    Filter.inlet() delegates all context work here through a single
    assemble_for_turn() call, reducing Filter's responsibility to pipeline
    orchestration only.

    Replaces the following Filter wrapper methods (dead code after migration):
      - Filter._inlet_build_system_injections()
      - Filter._inlet_assemble_final_messages()
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance.
        """
        self._f = filter_ref

    async def assemble_for_turn(
        self,
        messages: List[dict],
        project_id: str,
        user_query: str,
        user_question: str,
        is_code_session: bool,
        last_user_msg: Optional[dict],
        state: "ConversationState",
        __user__: Optional[dict],
        has_code_blocks: bool,
        slot_busy: bool = False,
        is_continuation: bool = False,
        intent_vector: Optional[dict] = None,
    ) -> Tuple[List[dict], Optional[dict]]:
        """
        Top-level context assembly coordinator for a single turn.

        Delegates to SystemPromptBuilder, WindowManager, and MessageAssembler
        in sequence. Returns (assembled_messages, cached_response_or_None).

        slot_busy is re-evaluated after slot_restore_for_continuity to capture
        any restore that completed between when inlet computed the flag and when
        assembly starts. Using the stale flag from inlet causes the current turn
        to run all expensive operations (CoT, semantic filters, compressor) even
        though the KV cache is now warm, wasting latency.

        On cache hit, ConversationState is persisted before returning so that
        symbol indexing done in _update_active_code is not lost if the process
        crashes before the next non-cached turn triggers a save.

        Steps:
            1.  Re-evaluate slot_busy after any in-progress restore completes.
            2.  Build static (Block A) and dynamic context via SystemPromptBuilder.
            3.  On cache hit: persist state and return early.
            4.  Apply WindowManager to enforce token budget.
            5.  Assemble final message list via MessageAssembler.
            6.  Return (assembled_messages, None).
        """
        psm = self._f._project_state_manager

        # -- Step 1: re-evaluate slot_busy --
        # slot_restore_for_continuity may have completed between inlet's call and
        # now. Re-read the flag to get the accurate post-restore value.
        slot_busy = psm.get_slot_restored(project_id)
        slot_free = not slot_busy

        # -- Step 2: build system prompt and dynamic context --
        (
            static_block,
            dynamic_injections,
            cached_response,
            use_case_label,
        ) = await self._f._system_prompt_builder.build(
            messages=messages,
            project_id=project_id,
            user_query=user_query,
            user_question=user_question,
            is_code_session=is_code_session,
            last_user_msg=last_user_msg,
            state=state,
            slot_busy=slot_busy,
            is_continuation=is_continuation,
            intent_vector=intent_vector,
        )

        # -- Step 3: cache hit fast path --
        if cached_response:
            # Persist dirty state so symbol indexing from _update_active_code
            # is not lost if the process crashes before the next non-cached turn.
            try:
                await self._f._conversation_state_manager.save_if_dirty(project_id)
            except Exception as e:
                self._f._log_debug(
                    f"assemble_for_turn: save_if_dirty failed on cache hit "
                    f"for '{project_id}': {e}"
                )
            self._f._log_debug(
                f"assemble_for_turn: cache hit for '{project_id}', " f"returning early"
            )
            return messages, cached_response

        # -- Step 4: WindowManager --
        windowed_messages, pending_summary = await self._f._window_manager.apply(
            messages=messages,
            state=state,
            project_id=project_id,
            slot_free=slot_free,
        )

        # -- Step 5: MessageAssembler --
        assembled, metadata = await self._f._message_assembler.assemble(
            messages=windowed_messages,
            project_id=project_id,
            static_block=static_block,
            dynamic_injections=dynamic_injections,
            prelim_system=self._f._system_prompt_builder._assemble_prelim_system(
                static_block, "", dynamic_injections, windowed_messages
            ),
            last_user_msg=last_user_msg,
            is_code_session=is_code_session,
            state=state,
            __user__=__user__,
            user_question=user_question,
            has_code_blocks=has_code_blocks,
            slot_busy=slot_busy,
            is_continuation=is_continuation,
        )

        # -- Step 6: return --
        return assembled, None


# ---------------------------------------------------------------------------
# ContextDumper — per-turn context snapshots for evolution tracking
# ---------------------------------------------------------------------------
class ContextDumper:
    """
    Captures per‑turn context snapshots and writes them to disk for
    offline evolution tracking — the operator can follow how the context
    grows and when the Block‑A KV‑cache prefix changes across a
    conversation.

    Provides:
    * ``schedule_inlet_snapshot(project_id, static_block, dynamic_block,
      final_system, messages)`` — captures the current payload synchronously
      (cheap string copies) and offloads the disk write to a background task.
    * Markdown snapshots (one per turn) and a rolling ``latest.md`` for
      quick inspection.
    * A compact JSONL metrics log (``evolution.jsonl``) with token counts
      and hashes, suitable for plotting context growth over time.
    * Automatic pruning of old snapshots per project.

    Writes are best‑effort and fully decoupled from the request path: any
    failure is swallowed with a debug log, so nothing here can break the
    inlet or outlet.

    Docs 10–13 backported:
        M7 – includes block_a_rebuild_reason in the JSONL record.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the ContextDumper with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._f = filter_ref
        self._tasks: Set[asyncio.Task] = set()

    # ═══════════════════════════════════════════════════════════════════════
    # 1. Public API – schedule snapshot capture
    # ═══════════════════════════════════════════════════════════════════════

    def schedule_inlet_snapshot(
        self,
        project_id: str,
        static_block: str,
        dynamic_block: str,
        final_system: str,
        messages: List[dict],
    ) -> None:
        """
        Schedule an async dump of the assembled context payload for debugging.

        Fire-and-forget: the dump must never block the inlet/outlet path or
        propagate exceptions that abort the user-visible response.

        RuntimeError from asyncio.ensure_future (event loop not running or
        closed during server shutdown/reload) is caught and logged at debug
        level. All other exceptions are caught for the same reason.

        Steps:
            1.  Capture the payload synchronously before returning to the caller.
            2.  Schedule _write_async; handle event-loop errors gracefully.
        """
        if not getattr(self._f.valves, "enable_context_dump", False):
            return

        # -- Step 1: capture payload --
        try:
            payload = self._capture_payload(
                project_id, static_block, dynamic_block, final_system, messages
            )
        except Exception as e:
            self._f._log_debug(
                f"ContextDumper.schedule_inlet_snapshot: capture failed: "
                f"{type(e).__name__}: {e}"
            )
            return

        # -- Step 2: schedule write --
        try:
            asyncio.ensure_future(self._write_async(payload))
        except RuntimeError as e:
            # Event loop not running or already closed (e.g. server reload).
            # Fall back to synchronous write so the dump is not lost entirely.
            self._f._log_debug(
                f"ContextDumper.schedule_inlet_snapshot: ensure_future failed "
                f"({e}), falling back to sync write"
            )
            try:
                self._write_sync(payload)
            except Exception as e2:
                self._f._log_debug(
                    f"ContextDumper.schedule_inlet_snapshot: sync write also "
                    f"failed: {type(e2).__name__}: {e2}"
                )
        except Exception as e:
            self._f._log_debug(
                f"ContextDumper.schedule_inlet_snapshot: unexpected error: "
                f"{type(e).__name__}: {e}"
            )

    # ═══════════════════════════════════════════════════════════════════════
    # 2. Payload capture (sync, cheap, mutation‑safe) – MODIFIED (M7)
    # ═══════════════════════════════════════════════════════════════════════

    def _capture_payload(
        self,
        project_id: str,
        static_block: str,
        dynamic_block: str,
        final_system: str,
        messages: List[dict],
    ) -> dict:
        """
        Snapshot strings + metadata immediately so later mutation can't race.

        Returns:
            dict: A complete payload dictionary with all context data and metrics.

        M7: Includes block_a_rebuild_reason from pstate.
        """
        max_chars = self._f.valves.context_dump_message_max_chars
        msg_copy: List[Tuple[str, str]] = []
        if self._f.valves.context_dump_include_messages:
            for m in messages:
                role = m.get("role", "")
                content = m.get("content", "") or ""
                if max_chars > 0 and len(content) > max_chars:
                    content = (
                        content[:max_chars]
                        + f"\n[...truncated {len(content) - max_chars} chars...]"
                    )
                msg_copy.append((role, content))

        # ── Resolve per-project state ────────────────────────────────────────
        pstate = self._f._project_state_manager.get_pstate(project_id)

        try:
            code_state_hash = self._f._activation.compute_code_state_hash(project_id)
        except Exception:
            code_state_hash = ""

        # ── Get hashes from pstate ──────────────────────────────────────────
        block_a_hash = pstate.get("last_static_prefix_hash", "")
        slot_hash = pstate.get("last_saved_slot_hash", "")

        # ── Get persistent state via ConversationStateManager ───────────────
        try:
            state = self._f._conversation_state_manager.get(project_id)
            turn = state.message_count
            n_active_blocks = len(state.active_blocks)
        except Exception:
            turn = 0
            n_active_blocks = 0

        try:
            n_symbols = len(self._f._symbol_index.get_all_names(project_id))
        except Exception:
            n_symbols = 0

        # ── Class membership metrics ────────────────────────────────────────
        try:
            all_names = self._f._symbol_index.get_all_names(project_id)
            n_with_parent = sum(
                1
                for n in all_names
                if self._f._symbol_index.get_parent_symbol(n, project_id)
            )
            n_classes = len(self._f._symbol_index.get_classes(project_id))
        except Exception:
            n_with_parent, n_classes = 0, 0

        # ── WindowManager metrics (now persistent in ConversationState) ────
        try:
            state = self._f._conversation_state_manager.get(project_id)
            wm_fired = state.wm_fired
            wm_msgs_evicted = state.wm_msgs_evicted
            wm_turns_evicted = state.wm_turns_evicted
            wm_summary_ok = state.wm_summary_ok
            wm_emergency_cap = state.wm_emergency_cap
            wm_batch_too_small = state.wm_batch_too_small
            wm_no_slot = state.wm_no_slot
            wm_degradation_guard = state.wm_degradation_guard
            frontier_hwm = state.summarized_turn_hwm
            summaries = state.conversation_summaries
            n_summaries_l1 = sum(1 for s in summaries if s.get("level", 1) == 1)
            n_summaries_l2 = sum(1 for s in summaries if s.get("level", 1) >= 2)
        except Exception:
            wm_fired = wm_summary_ok = wm_emergency_cap = False
            wm_batch_too_small = wm_no_slot = wm_degradation_guard = False
            wm_msgs_evicted = wm_turns_evicted = 0
            frontier_hwm = n_summaries_l1 = n_summaries_l2 = 0

        now = time.time()
        return {
            # ── Existing fields ──────────────────────────────────────────────
            "project_id": project_id,
            "turn": turn,
            "timestamp": now,
            "iso": datetime.fromtimestamp(now, tz=timezone.utc).strftime(
                "%Y-%m-%dT%H:%M:%SZ"
            ),
            "static_block": static_block or "",
            "dynamic_block": dynamic_block or "",
            "final_system": final_system or "",
            "messages": msg_copy,
            "block_a_hash": block_a_hash,
            # ── M7: rebuild reason ─────────────────────────────────────────────
            "block_a_rebuild_reason": pstate.get("block_a_rebuild_reason"),
            "code_state_hash": code_state_hash,
            "slot_saved_hash": slot_hash,
            "n_active_blocks": n_active_blocks,
            "n_symbols": n_symbols,
            "n_symbols_with_parent": n_with_parent,
            "n_classes": n_classes,
            # ── WindowManager metrics ──────────────────────────────────────
            "wm_fired": wm_fired,
            "wm_msgs_evicted": wm_msgs_evicted,
            "wm_turns_evicted": wm_turns_evicted,
            "wm_summary_ok": wm_summary_ok,
            "wm_emergency_cap": wm_emergency_cap,
            "wm_batch_too_small": wm_batch_too_small,
            "wm_no_slot": wm_no_slot,
            "wm_degradation_guard": wm_degradation_guard,
            # ── HWM and summaries ───────────────────────────────────────────
            "frontier_hwm": frontier_hwm,
            "n_summaries_l1": n_summaries_l1,
            "n_summaries_l2": n_summaries_l2,
        }

    # ═══════════════════════════════════════════════════════════════════════
    # 3. Writing (async + sync)
    # ═══════════════════════════════════════════════════════════════════════

    async def _write_async(self, payload: dict) -> None:
        """
        Asynchronously write the context snapshot to disk.

        Delegates the entire Markdown + JSONL writing to the synchronous
        `_write_sync` method, which handles token counting and file I/O.

        Args:
            payload: The payload dictionary from _capture_payload.
        """
        self._f._log_debug(f"📝 Writing context dump (turn {payload['turn']})...")
        try:
            # All writing (Markdown + JSONL) is handled by _write_sync.
            await anyio.to_thread.run_sync(self._write_sync, payload)
            self._f._log_debug(f"✅ Context dump written (turn {payload['turn']})")
        except Exception as exc:
            self._f._log_debug(f"❌ Context dump write failed: {exc}")

    def _write_sync(self, payload: dict) -> None:
        """
        Synchronously write the context snapshot to disk (Markdown + JSONL).

        Modified (M7): adds block_a_rebuild_reason to evolution.jsonl.
        """
        project_id = payload["project_id"]
        project_dir = self._project_dir(project_id)
        os.makedirs(project_dir, exist_ok=True)

        # ── 1. Compute token counts ──────────────────────────────────────────
        if self._f.tokenizer:
            static_block = payload.get("static_block", "")
            dynamic_block = payload.get("dynamic_block", "")
            final_system = payload.get("final_system", "")
            block_a_tokens = (
                len(self._f.tokenizer.encode(static_block)) if static_block else 0
            )
            block_b_tokens = (
                len(self._f.tokenizer.encode(dynamic_block)) if dynamic_block else 0
            )
            system_tokens = (
                len(self._f.tokenizer.encode(final_system)) if final_system else 0
            )
            # History tokens: sum of all non-system messages
            history_tokens = 0
            for role, content in payload.get("messages", []):
                if role != "system":
                    history_tokens += len(self._f.tokenizer.encode(content))
        else:
            block_a_tokens = len(payload.get("static_block", "")) // 4
            block_b_tokens = len(payload.get("dynamic_block", "")) // 4
            system_tokens = len(payload.get("final_system", "")) // 4
            history_tokens = 0
            for role, content in payload.get("messages", []):
                if role != "system":
                    history_tokens += len(content) // 4

        # ── 2. Write Markdown snapshot ───────────────────────────────────────
        md_content = self._render_markdown(
            payload, block_a_tokens, block_b_tokens, system_tokens, history_tokens
        )
        turn = payload.get("turn", 0)
        timestamp_str = datetime.fromtimestamp(
            payload["timestamp"], tz=timezone.utc
        ).strftime("%Y%m%d_%H%M%S")
        md_filename = f"{timestamp_str}_turn_{turn:04d}.md"
        md_path = os.path.join(project_dir, md_filename)

        with open(md_path, "w", encoding="utf-8") as f:
            f.write(md_content)

        # ── 3. Update latest.md symlink (or copy) ──────────────────────────
        latest_path = os.path.join(project_dir, "latest.md")
        try:
            if os.path.exists(latest_path):
                os.remove(latest_path)
            os.symlink(md_filename, latest_path)
        except Exception:
            # If symlink fails (e.g., Windows without admin), copy instead
            try:
                import shutil

                shutil.copy2(md_path, latest_path)
            except Exception:
                pass

        # ── 4. Write JSONL evolution record (M7) ─────────────────────────────
        if self._f.valves.context_dump_write_jsonl:
            # ── M7: include rebuild reason in the JSONL record ──────────────
            record = {
                "ts": payload["timestamp"],
                "iso": payload["iso"],
                "turn": turn,
                "block_a_tokens": block_a_tokens,
                "block_b_tokens": block_b_tokens,
                "system_tokens": system_tokens,
                "history_tokens": history_tokens,
                "n_messages": len(payload.get("messages", [])),
                "n_active_blocks": payload.get("n_active_blocks", 0),
                "n_symbols": payload.get("n_symbols", 0),
                "block_a_hash": payload.get("block_a_hash", ""),
                # ── M7: rebuild reason (string or null) ──────────────────────
                "block_a_rebuild_reason": payload.get("block_a_rebuild_reason"),
                "code_state_hash": payload.get("code_state_hash", ""),
                "slot_saved_hash": payload.get("slot_saved_hash", ""),
                # ── WindowManager metrics ──────────────────────────────────
                "wm_fired": payload.get("wm_fired", False),
                "wm_msgs_evicted": payload.get("wm_msgs_evicted", 0),
                "wm_turns_evicted": payload.get("wm_turns_evicted", 0),
                "wm_summary_ok": payload.get("wm_summary_ok", False),
                "wm_emergency_cap": payload.get("wm_emergency_cap", False),
                "wm_batch_too_small": payload.get("wm_batch_too_small", False),
                "wm_no_slot": payload.get("wm_no_slot", False),
                "wm_degradation_guard": payload.get("wm_degradation_guard", False),
                "frontier_hwm": payload.get("frontier_hwm", 0),
                "n_summaries_l1": payload.get("n_summaries_l1", 0),
                "n_summaries_l2": payload.get("n_summaries_l2", 0),
            }
            jsonl_path = os.path.join(project_dir, "evolution.jsonl")
            with open(jsonl_path, "a", encoding="utf-8") as f:
                f.write(json.dumps(record, ensure_ascii=False) + "\n")

        # ── 5. Prune old snapshots ───────────────────────────────────────────
        self._prune(project_dir)

    # ═══════════════════════════════════════════════════════════════════════
    # 4. Rendering
    # ═══════════════════════════════════════════════════════════════════════

    def _render_markdown(
        self,
        payload: dict,
        block_a_tokens: int,
        block_b_tokens: int,
        system_tokens: int,
        history_tokens: int,
    ) -> str:
        """
        Render the context snapshot as Markdown for human inspection.

        Args:
            payload: The payload dictionary.
            block_a_tokens: Token count of Block A.
            block_b_tokens: Token count of Block B.
            system_tokens: Total system prompt tokens.
            history_tokens: History tokens (non-system).

        Returns:
            str: The rendered Markdown text.
        """
        lines: List[str] = []
        lines.append(
            f"# Context Snapshot — `{payload['project_id']}` — "
            f"turn {payload['turn']} — {payload['iso']}"
        )
        lines.append("")
        lines.append("## Metadata")
        lines.append(f"- turn (message_count): {payload['turn']}")
        lines.append(f"- Block A tokens (static):  ~{block_a_tokens}")
        lines.append(f"- Block B tokens (dynamic): ~{block_b_tokens}")
        lines.append(f"- system prompt tokens:     ~{system_tokens}")
        lines.append(f"- history tokens:           ~{history_tokens}")
        lines.append(f"- Block A prefix hash: `{payload['block_a_hash'] or 'N/A'}`")
        lines.append(f"- code_state_hash:     `{payload['code_state_hash'] or 'N/A'}`")
        lines.append(f"- slot saved hash:     `{payload['slot_saved_hash'] or 'N/A'}`")
        lines.append(f"- active blocks: {payload['n_active_blocks']}")
        lines.append(f"- indexed symbols: {payload['n_symbols']}")
        lines.append(
            f"- symbols with class resolved: "
            f"{payload['n_symbols_with_parent']}/{payload['n_symbols']}"
        )
        lines.append(f"- classes detected: {payload['n_classes']}")

        # ── WindowManager metrics ────────────────────────────────────────────
        lines.append("")
        lines.append("### WindowManager metrics (this turn)")
        lines.append(
            f"- wm_fired={payload.get('wm_fired', False)}"
            f"  msgs_evicted={payload.get('wm_msgs_evicted', 0)}"
            f"  turns_evicted={payload.get('wm_turns_evicted', 0)}"
        )
        lines.append(
            f"- summary_ok={payload.get('wm_summary_ok', False)}"
            f"  emergency_cap={payload.get('wm_emergency_cap', False)}"
        )
        lines.append(
            f"- batch_too_small={payload.get('wm_batch_too_small', False)}"
            f"  no_slot={payload.get('wm_no_slot', False)}"
            f"  degradation_guard={payload.get('wm_degradation_guard', False)}"
        )
        lines.append(
            f"- frontier_hwm={payload.get('frontier_hwm', 0)}"
            f"  summaries_L1={payload.get('n_summaries_l1', 0)}"
            f"  summaries_L2={payload.get('n_summaries_l2', 0)}"
        )

        lines.append("")
        lines.append("## Block A — static (KV-cache prefix)")
        lines.append("```text")
        lines.append(payload["static_block"] or "(empty)")
        lines.append("```")
        lines.append("")

        lines.append("## Block B — dynamic (per-query)")
        lines.append("```text")
        lines.append(payload["dynamic_block"] or "(empty)")
        lines.append("```")
        lines.append("")

        if self._f.valves.context_dump_include_messages:
            lines.append("## Message window (non-system, sent to model)")
            idx = 0
            for role, content in payload["messages"]:
                if role == "system":
                    continue  # already shown as Block A + Block B above
                lines.append(f"### [{idx}] {role}")
                lines.append("```text")
                lines.append(content or "(empty)")
                lines.append("```")
                idx += 1
            lines.append("")

        return "\n".join(lines)

    # ═══════════════════════════════════════════════════════════════════════
    # 5. Directory & pruning
    # ═══════════════════════════════════════════════════════════════════════

    def _project_dir(self, project_id: str) -> str:
        """
        Return the project-specific dump directory path.

        Args:
            project_id: The project identifier.

        Returns:
            str: The directory path.
        """
        slug = re.sub(r"[^a-zA-Z0-9_-]", "_", project_id)[:40] or "default"
        return os.path.join(self._f.valves.context_dump_dir.rstrip("/"), slug)

    def _prune(self, project_dir: str) -> None:
        """
        Remove dump files beyond the configured retention limit to prevent
        unbounded disk growth.

        Silently returns when the project directory does not yet exist (first
        request for this project) or when retention is unlimited (max_dumps <= 0).

        Steps:
            1.  Resolve retention limit from valves; skip when unlimited.
            2.  Guard: return if directory does not exist.
            3.  Collect all .md dump files sorted by modification time (oldest first).
            4.  Remove files beyond the retention limit.
        """
        # -- Step 1: retention limit --
        max_dumps = getattr(self._f.valves, "context_dump_max_files", 20)
        if max_dumps <= 0:
            return

        # -- Step 2: directory existence guard --
        if not os.path.isdir(project_dir):
            return

        # -- Step 3: collect files sorted oldest-first --
        try:
            entries = [
                os.path.join(project_dir, fn)
                for fn in os.listdir(project_dir)
                if fn.endswith(".md")
            ]
        except OSError as e:
            self._f._log_debug(f"ContextDumper._prune: listing failed: {e}")
            return

        if len(entries) <= max_dumps:
            return

        entries.sort(key=lambda p: os.path.getmtime(p))
        to_remove = entries[: len(entries) - max_dumps]

        # -- Step 4: remove stale files --
        removed = 0
        for path in to_remove:
            try:
                os.unlink(path)
                removed += 1
            except OSError as e:
                self._f._log_debug(
                    f"ContextDumper._prune: could not remove {path}: {e}"
                )

        if removed:
            self._f._log_debug(
                f"ContextDumper._prune: removed {removed} old dump(s) "
                f"from {project_dir}"
            )


class TaskRegistry:
    """
    Registry and orchestrator for all background/lazy tasks.

    Responsibilities:
        - Defines all tasks with their metadata (priority, valves, functions).
        - Validates and orders tasks based on priority valves.
        - Manages task completion status via pstate.
        - Executes lazy (on-demand) tasks in the inlet.
        - Provides the list of background tasks to the outlet.
    """

    # ------------------------------------------------------------------
    # Region: Initialization and Task Definitions
    # ------------------------------------------------------------------

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize the registry with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance.
        """
        self._f = filter_ref
        self._bg_tasks: List[BackgroundTask] = self._build_tasks()
        self._validate_and_order()

    def _build_tasks(self) -> List[BackgroundTask]:
        """
        Build the list of background task definitions.

        Each task defines:
            - A unique name and state key for persistent status in pstate.
            - Optional lazy and background functions.
            - An invalidation function that returns a hash to invalidate
              the 'completed' status when the code changes.
            - Valves to enable/disable each mode independently.
            - A priority for background execution order.
            - A flag to skip lazy execution if already completed.

        Returns:
            List[BackgroundTask]: The list of task definitions.
        """
        tasks = [
            # ------------------------------------------------------------------
            # Task 1: Session summary (highest priority: controls context size).
            # ------------------------------------------------------------------
            BackgroundTask(
                name="session_summary",
                state_key="bg_session_summary_state",
                lazy_func=self._lazy_session_summary,
                bg_func=self._bg_session_summary,
                invalidation_func=None,
                valve_bg="enable_bg_session_summary",
                valve_lazy="enable_lazy_session_summary",
                priority=1,
                skip_if_completed=True,
            ),
            # ------------------------------------------------------------------
            # Task 2: Speculative prefetch.
            # ------------------------------------------------------------------
            BackgroundTask(
                name="prefetch",
                state_key="bg_prefetch_state",
                lazy_func=self._lazy_prefetch,
                bg_func=self._f._activation.speculative_prefetch_background,
                invalidation_func=lambda pid: self._f._activation.compute_code_state_hash(
                    pid
                ),
                valve_bg="enable_bg_prefetch",
                valve_lazy="enable_lazy_prefetch",
                priority=2,
                skip_if_completed=True,
            ),
            # ------------------------------------------------------------------
            # Task 3: Docstrings (lower priority, can be generated lazily).
            # ------------------------------------------------------------------
            BackgroundTask(
                name="docstrings",
                state_key="bg_docstrings_state",
                lazy_func=self._lazy_docstrings,
                bg_func=self._f._enrichment._docstring_generation_loop,
                invalidation_func=lambda pid: self._f._symbol_index.compute_structure_hash(
                    pid
                ),
                valve_bg="enable_bg_docstrings",
                valve_lazy="enable_lazy_docstrings",
                priority=3,
                skip_if_completed=True,
            ),
            # ------------------------------------------------------------------
            # Task 4: RAPTOR rebuild.
            # ------------------------------------------------------------------
            BackgroundTask(
                name="raptor",
                state_key="bg_raptor_state",
                lazy_func=self._lazy_raptor,
                bg_func=self._bg_raptor,
                invalidation_func=lambda pid: self._f._symbol_index.compute_structure_hash(
                    pid
                ),
                valve_bg="enable_bg_raptor",
                valve_lazy="enable_lazy_raptor",
                priority=4,
                skip_if_completed=True,
            ),
            # ------------------------------------------------------------------
            # Task 5: Purge old versions (experimental, disabled by default).
            # ------------------------------------------------------------------
            BackgroundTask(
                name="purge",
                state_key="bg_purge_state",
                lazy_func=self._lazy_purge,
                bg_func=self._bg_purge,
                invalidation_func=lambda pid: self._f._activation.compute_code_state_hash(
                    pid
                ),
                valve_bg="enable_bg_purge",
                valve_lazy="enable_lazy_purge",
                priority=5,
                skip_if_completed=True,
            ),
            # ------------------------------------------------------------------
            # Task 6: LOD adaptive (invalidated every turn via message_count).
            # ------------------------------------------------------------------
            BackgroundTask(
                name="lod_adaptive",
                state_key="bg_lod_state",
                lazy_func=self._lazy_lod,
                bg_func=self._f._enrichment.update_lod_thresholds_from_response,
                invalidation_func=lambda pid: str(
                    self._f._conversation_state_manager.get(pid).message_count
                ),
                valve_bg="enable_bg_lod",
                valve_lazy="enable_lazy_lod",
                priority=6,
                skip_if_completed=False,  # Always invalidated by message_count.
            ),
        ]
        return tasks

    def _validate_and_order(self) -> None:
        """
        Validate the background_priority valve and order tasks by priority.

        - Warns about unknown task names in the valve.
        - Applies effective priority from the valve (or uses default).
        - Sorts tasks in descending priority order (higher first).
        """
        # ------------------------------------------------------------------
        # Step 1: Validate keys in background_priority valve.
        # ------------------------------------------------------------------
        valid_names = {t.name for t in self._bg_tasks}
        for name in self._f.valves.background_priority:
            if name not in valid_names:
                self._f._log_debug(
                    f"WARNING: background_priority contains unknown task '{name}'"
                )

        # ------------------------------------------------------------------
        # Step 2: Apply effective priority from valve or default.
        # ------------------------------------------------------------------
        for task in self._bg_tasks:
            task._effective_priority = self._f.valves.background_priority.get(
                task.name, task.priority
            )

        # ------------------------------------------------------------------
        # Step 3: Sort by effective priority (higher first).
        # ------------------------------------------------------------------
        self._bg_tasks.sort(key=lambda t: -t._effective_priority)

    # ------------------------------------------------------------------
    # Region: Public API for Filter
    # ------------------------------------------------------------------

    def get_background_tasks(self) -> List[BackgroundTask]:
        """
        Return the list of background tasks in execution order (priority order).

        Returns:
            List[BackgroundTask]: The ordered list of tasks.
        """
        return self._bg_tasks

    def get_task_definition(self, name: str) -> Optional[BackgroundTask]:
        """
        Return the task definition for a given name, or None if not found.

        Args:
            name (str): The task name.

        Returns:
            Optional[BackgroundTask]: The task definition, or None.
        """
        for task in self._bg_tasks:
            if task.name == name:
                return task
        return None

    # ------------------------------------------------------------------
    # Region: Lazy Task Execution (inlet)
    # ------------------------------------------------------------------

    async def run_lazy_tasks(
        self,
        project_id: str,
        pstate: dict,
    ) -> None:
        """
        Execute all pending lazy tasks for the current turn in priority order.

        Lazy tasks are best-effort: a failure in one must never prevent
        subsequent tasks from running. Each task is wrapped in an independent
        try/except so that an exception from, for example, _lazy_raptor
        (ChromaDB unavailable, embedding model not loaded) does not silently
        drop docstring generation, LOD updates, or purge runs for that turn.

        Tasks that raise are marked not-completed so they will be retried
        on the next turn rather than being silently skipped forever.

        Steps:
            1.  Collect tasks ordered by effective priority; skip completed ones.
            2.  For each task: mark in-progress, execute, mark completed or
                not-completed on exception.
            3.  Log a summary of what ran and what failed.
        """
        # -- Step 1: collect pending tasks sorted by priority --
        pending = [
            t
            for t in self.get_background_tasks()
            if not t.should_skip_lazy(pstate, project_id)
        ]

        if not pending:
            return

        self._f._log_debug(
            f"run_lazy_tasks: {len(pending)} pending task(s) for '{project_id}': "
            f"{[t.name for t in pending]}"
        )

        completed_names: List[str] = []
        failed_names: List[str] = []

        # -- Steps 2-3: run each task independently --
        for task in pending:
            task.mark_in_progress(pstate)
            try:
                await task.lazy_func(project_id)
                task.mark_completed(pstate, project_id)
                completed_names.append(task.name)
            except asyncio.CancelledError:
                # Propagate cancellation — do not swallow it.
                task.mark_not_completed(pstate)
                raise
            except Exception as e:
                # Log and continue — never let one task kill the rest.
                task.mark_not_completed(pstate)
                failed_names.append(task.name)
                self._f._log_debug(
                    f"run_lazy_tasks: task '{task.name}' failed for "
                    f"'{project_id}': {type(e).__name__}: {e}"
                )

        if completed_names or failed_names:
            self._f._log_debug(
                f"run_lazy_tasks: done for '{project_id}' — "
                f"ok={completed_names}, failed={failed_names}"
            )

    # ------------------------------------------------------------------
    # Region: Background Task Wrappers (Bugs 8 and 13)
    # ------------------------------------------------------------------

    async def _bg_raptor(self, project_id: str, stop_event=None) -> None:
        """
        Background wrapper for RAPTOR rebuild.

        Args:
            project_id: Current project identifier.
            stop_event: Optional event to signal early termination.
        """
        # ------------------------------------------------------------------
        # Step 1: Check if RAPTOR is enabled.
        # ------------------------------------------------------------------
        if not self._f.valves.enable_raptor:
            return

        # ------------------------------------------------------------------
        # Step 2: Gather necessary data.
        # ------------------------------------------------------------------
        edges_out = self._f._symbol_index.get_all_edges_out(project_id)
        graph_weight = (
            self._f.valves.raptor_graph_weight
            if self._f.valves.raptor_use_call_graph_proximity
            else 0.0
        )

        # ------------------------------------------------------------------
        # Step 3: Execute rebuild.
        # ------------------------------------------------------------------
        await self._f._raptor.rebuild(
            project_id=project_id,
            symbol_index=self._f._symbol_index,
            edges_out=edges_out,
            n_clusters=self._f.valves.raptor_clusters_per_level,
            summary_model=self._f.valves.raptor_summary_model,
            summary_max_tokens=self._f.valves.raptor_summary_max_tokens,
            chroma_collection=self._f.memory_collection,
            llm_caller=self._f._llm_orchestrator.call_llm,
            embedder=self._f.embedder,
            graph_weight=graph_weight,
            stop_event=stop_event,
        )

    async def _bg_session_summary(self, project_id: str, stop_event=None) -> None:
        """
        Background wrapper for session summary generation.

        Args:
            project_id: Current project identifier.
            stop_event: Optional event to signal early termination.
        """
        # ------------------------------------------------------------------
        # Step 1: Check if it's time to generate a summary.
        # ------------------------------------------------------------------
        state = self._f._conversation_state_manager.get(project_id)
        interval = self._f.valves.session_summary_interval_messages

        if interval <= 0:
            return

        if state.message_count % interval != 0 or state.message_count == 0:
            return

        # ------------------------------------------------------------------
        # Step 2: Execute session summary task.
        # ------------------------------------------------------------------
        await self._f._enrichment.run_session_summary_task(
            params={
                "project_id": project_id,
                "message_count": state.message_count,
                "code_state_hash": self._f._activation.compute_code_state_hash(
                    project_id
                ),
            },
            model=self._f.valves.llm_model,
            stop_event=stop_event,
        )

    async def _bg_purge(self, project_id: str, stop_event=None) -> None:
        """
        Background wrapper for purging old code versions.

        Args:
            project_id: Current project identifier.
            stop_event: Optional event to signal early termination.
        """
        # ------------------------------------------------------------------
        # Step 1: Check prerequisites.
        # ------------------------------------------------------------------
        if not self._f.valves.purge_old_code_versions_enabled:
            return

        if not self._f.valves.enable_block_paging:
            return

        if self._f._pager is None:
            return

        state = self._f._conversation_state_manager.get(project_id)
        if not state or not state.active_blocks:
            return

        # ------------------------------------------------------------------
        # Step 2: Execute purge.
        # ------------------------------------------------------------------
        await self._f._pager.purge_old_versions(
            project_id=project_id,
            state=state,
            symbol_index=self._f._symbol_index,
            chroma_collection=self._f.memory_collection,
            embedder=self._f.embedder,
            max_versions_per_file=(self._f.valves.purge_old_code_versions_max_per_file),
            stop_event=stop_event,
        )

    # ------------------------------------------------------------------
    # Region: Lazy Implementations (Specific to Each Task)
    # ------------------------------------------------------------------

    async def _lazy_docstrings(self, project_id: str) -> None:
        """
        Lazy generation of docstrings for symbols that are needed in the
        current turn. This is a lightweight version that only processes
        symbols that are about to be used (e.g., LOD-2 symbols).

        This runs in the foreground (inlet) and uses `background=False` so
        that it respects the per‑turn budget and uses the `lazy_docstring_batch`
        label (which is not whitelisted for silent ingestion, which is fine
        because this method is never called during silent ingestion).

        Args:
            project_id: The current project identifier.
        """
        psm = self._f._project_state_manager

        # ------------------------------------------------------------------
        # Step 1: Get the current conversation state.
        # ------------------------------------------------------------------
        state = self._f._conversation_state_manager.get(project_id)
        if not state or not state.active_blocks:
            return

        # ------------------------------------------------------------------
        # Step 2: Determine which symbols need docstrings.
        # ------------------------------------------------------------------
        skeleton_qids = set(psm.get_skeleton_tier_qids(project_id))
        lod2_qids = set(psm.get_lod2_active_qids_prev(project_id))

        qids_needed = set()
        for block in state.active_blocks.values():
            if block.obsolete:
                continue
            for sym in block.symbols:
                qid = qualify_symbol_name(sym.name, sym.parent_symbol)
                if (qid in skeleton_qids or qid in lod2_qids) and not sym.docstring:
                    qids_needed.add(qid)

        if not qids_needed:
            return

        # ------------------------------------------------------------------
        # Step 3: Generate docstrings for the needed symbols (foreground).
        # ------------------------------------------------------------------
        results = await self.ensure_docstrings_batch(
            list(qids_needed),
            project_id,
            background=False,  # <-- foreground (lazy)
        )
        if results:
            self._f._log_debug(
                f"_lazy_docstrings: generated {len(results)} docstrings for this turn"
            )

    async def _lazy_prefetch(self, project_id: str) -> None:
        """
        Lazy prefetch: build CodePathView for symbols mentioned in the query.

        This method is called during the inlet (lazy execution) to pre-build
        CodePathView objects for symbols that are likely to be needed in the
        current turn. It uses the last user query stored in pstate.

        Args:
            project_id: Current project identifier.
        """
        psm = self._f._project_state_manager

        # ------------------------------------------------------------------
        # Step 1: Get the current user query (from pstate).
        # ------------------------------------------------------------------
        query = psm.get_last_user_query(project_id)
        if not query:
            return

        # ------------------------------------------------------------------
        # Step 2: Build activation graph for the query.
        # ------------------------------------------------------------------
        ag = await self._f._activation.build_activation_graph(query, project_id)

        # ------------------------------------------------------------------
        # Step 3: For each seed node, build a CodePathView if not already built.
        # ------------------------------------------------------------------
        for seed in ag.get_seed_nodes()[:3]:  # Limit to top seeds
            if not self._f._path_index.get(seed, project_id):
                await self._f._activation._build_view_from_activation(
                    seed, ag, project_id
                )

    async def _lazy_session_summary(self, project_id: str) -> None:
        """
        Lazy session summary generation. Executed if not already done in background.

        Args:
            project_id: The current project identifier.
        """
        state = self._f._conversation_state_manager.get(project_id)
        interval = self._f.valves.session_summary_interval_messages
        if (
            interval <= 0
            or state.message_count % interval != 0
            or state.message_count == 0
        ):
            return

        await self._f._enrichment.run_session_summary_task(
            {
                "project_id": project_id,
                "message_count": state.message_count,
                "code_state_hash": self._f._activation.compute_code_state_hash(
                    project_id
                ),
            },
            self._f.valves.llm_model,
            stop_event=None,  # No stop_event in lazy mode.
        )

    async def _lazy_raptor(self, project_id: str) -> None:
        """
        Lazy RAPTOR rebuild. Executed if not already done in background.

        Args:
            project_id: The current project identifier.
        """
        if not self._f.valves.enable_raptor:
            return

        edges_out = self._f._symbol_index.get_all_edges_out(project_id)
        graph_weight = (
            self._f.valves.raptor_graph_weight
            if self._f.valves.raptor_use_call_graph_proximity
            else 0.0
        )

        await self._f._raptor.rebuild(
            project_id=project_id,
            symbol_index=self._f._symbol_index,
            edges_out=edges_out,
            n_clusters=self._f.valves.raptor_clusters_per_level,
            summary_model=self._f.valves.raptor_summary_model,
            summary_max_tokens=self._f.valves.raptor_summary_max_tokens,
            chroma_collection=self._f.memory_collection,
            llm_caller=self._f._llm_orchestrator.call_llm,
            embedder=self._f.embedder,
            graph_weight=graph_weight,
            stop_event=None,  # No stop_event in lazy mode.
        )

    async def _lazy_purge(self, project_id: str) -> None:
        """
        Lazy purge of old versions. Executed if not already done in background.

        Args:
            project_id: The current project identifier.
        """
        if (
            not self._f.valves.purge_old_code_versions_enabled
            or not self._f.valves.enable_block_paging
        ):
            return

        if self._f._pager is None:
            return

        state = self._f._conversation_state_manager.get(project_id)
        await self._f._pager.purge_old_versions(
            project_id=project_id,
            state=state,
            symbol_index=self._f._symbol_index,
            chroma_collection=self._f.memory_collection,
            embedder=self._f.embedder,
            max_versions_per_file=self._f.valves.purge_old_code_versions_max_per_file,
            stop_event=None,  # No stop_event in lazy mode.
        )

    async def _lazy_lod(self, project_id: str) -> None:
        """
        Lazy LOD adaptive adjustment. Uses the last assistant response
        stored in pstate from the previous turn.

        Args:
            project_id: The current project identifier.
        """
        psm = self._f._project_state_manager

        # ------------------------------------------------------------------
        # Step 1: Get the last response and check its timestamp.
        # ------------------------------------------------------------------
        last_response = psm.get_last_assistant_response(project_id)
        if not last_response:
            return

        ts = psm.get_last_response_timestamp(project_id)
        if time.time() - ts > 60:  # 1 minute.
            return

        # ------------------------------------------------------------------
        # Step 2: Execute LOD adaptive adjustment.
        # ------------------------------------------------------------------
        await self._f._enrichment.update_lod_thresholds_from_response(
            project_id, last_response, stop_event=None
        )


# ============================================================================
# ProjectStateManager — per‑project volatile state (SRP)
# ============================================================================
class ProjectStateManager:
    """
    Manages per‑project volatile state that lives in memory only.

    This class holds all attributes that vary by project (call‑graph mode,
    ingested language, cache keys, invalidation flags, etc.) in a dictionary
    keyed by project_id. It provides a clean accessor and factory, and will
    support project‑state cleanup on eviction (subsystem 05).

    This decouples project‑scoped state from the singleton Filter instance,
    preventing cross‑project corruption when alternating between projects.
    """

    def __init__(self, filter_ref: "Filter") -> None:
        """
        Initialize with a reference to the parent Filter.

        Args:
            filter_ref: The parent Filter instance (provides valves, logger, etc.).
        """
        self._f = filter_ref
        self._store: dict[str, dict] = {}

    def _new_pstate(self) -> dict:
        """
        Factory for a fresh per-project volatile state bag with all defaults.

        Every key that has a typed accessor on this class must appear here
        with its correct default so that first-turn reads never raise KeyError
        or return unexpected None values.
        """
        return {
            # -- Call-graph mode ------------------------------------------
            "resolved_call_graph_mode": None,
            "current_call_graph_mode": None,
            "graph_mode_downgrade_streak": 0,
            # -- Silent ingestion -----------------------------------------
            "ingested_lang": None,
            "raw_ingested_symbols": None,
            # -- Block A / skeleton cache ---------------------------------
            "block_a_cache_key": None,
            "block_a_cached": None,
            "skeleton_cache_key": None,
            "skeleton_cached": None,
            "skeleton_tier_cache_key": None,
            "skeleton_tier_cached": None,
            "skeleton_invalidated": False,
            "block_a_invalidated": False,
            "skeleton_rendered_this_turn": False,
            "skeleton_render_mode": None,
            "skeleton_tier_qids": [],
            # -- Centrality and lightweight context -----------------------
            "node_centrality": {},
            "cached_lightweight_context": "",
            "cached_code_state_hash": None,
            "structure_hash_for_cache": None,
            "last_static_prefix_hash": None,
            # -- Hub tier -------------------------------------------------
            "hub_tier_text": "",
            "hub_tier_hash": "",
            "hub_tier_qids": [],
            "hub_tier_seeds_this_turn": [],
            "hub_tier_prev_seeds": [],
            # -- LOD tracking ---------------------------------------------
            "lod2_active_qids_prev": [],
            "last_lod_levels": {},
            "last_activation_scores": {},
            "block_b_qids_this_turn": [],
            # -- Token accounting -----------------------------------------
            "last_system_tokens": 0,
            "last_total_context_tokens": 0,
            # -- KV cache persistence -------------------------------------
            "last_saved_slot_hash": "",
            "slot_restored": False,
            "slot_restore_attempted": False,
            # -- Query / response tracking --------------------------------
            "last_user_query": "",
            "last_assistant_response": "",
            "last_response_timestamp": 0.0,
            "last_outlet_response_hash": "",
            # -- Continuation tracking ------------------------------------
            "is_continuation": False,
            "continuation_turns": 0,
            # -- AutoContinue / multi-phase -------------------------------
            "force_multi_phase_this_turn": False,
            # -- Response cache -------------------------------------------
            "response_cache_count": 0,
            # -- Use case tracking ----------------------------------------
            "last_use_case": None,
            # -- Misc -----------------------------------------------------
            "last_processed_message_idx": -1,
            "summarize_inactive_in_progress": False,
            "force_compressed_keys": [],
            "block_a_rebuild_reason": None,
        }

    def get_pstate(self, project_id: str) -> dict:
        """
        Return the mutable per‑project state bag, creating it on first access.

        Args:
            project_id (str): The project identifier.

        Returns:
            dict: The per‑project state bag for the given project.
        """
        st = self._store.get(project_id)
        if st is None:
            st = self._new_pstate()
            self._store[project_id] = st
        return st

    def clear_project(self, project_id: str) -> None:
        """Remove the state bag for a project (called on eviction)."""
        self._store.pop(project_id, None)

